    (N'DT_ATUALIZACAO')) x(v)
UNION ALL SELECT N'KZN_HIST_KAIZEN_HIERARQUIA', v FROM (VALUES
    (N'ID_KAIZEN'),
    (N'ID_USUARIO_LIDER'),
    (N'NM_HIERARQUIA_N1'),
    (N'NM_HIERARQUIA_N2'),
    (N'NM_HIERARQUIA_N3'),
    (N'NM_HIERARQUIA_N4'),
    (N'NM_HIERARQUIA_N5'),
    (N'NM_HIERARQUIA_N6'),
    (N'NM_HIERARQUIA_N7'),
