INSERT INTO #PVC VALUES (10913, N'541142', N'541142', N'Válvula de limpeza flotação / Banco Rougher', 3, N'Others/Outros', N'Ausência de ponto de água de serviço para realização 
INSERT INTO #PVC VALUES (10914, N'81029859', N'81029404', N'Suporte de calços de roda.', NULL, N'Others/Outros', N'LUGAR ADEQUADO PARA ORGANZAÇÃO DOS CALÇOS DE RODAS.', N'ORGANIZAÇÃO', N'10144', N'01 - Imagens/01 - Antes/10914.jpeg', N'AUSÊNCIA DE UM SISTEMA ADEQUADO DE ORGANIZAÇÃO PARA OS CALÇOS DE RODAS DA OFICINA DE PEQUENO PORTE GERAVA DESPERDICIO DE TEMPO E IMPACTAVA A EFICIÊNCIA DAS MANUTENÇÕES . ', N'01 - Imagens/02 - Depois/10914.jpeg', N'CONFECCIONADO SUPORTE DE CALÇOS PARA PADRONIZAÇÃO E LOCALIZAÇÃO RÁPIDA  NO POSTO  DE TRABALHO.', NULL, N'SIM AGORA O PROCESSO FLUI MELHOR E MAIS RÁPIDO.', N'ORGANIZAÇÃO E GANHO DE TEMPO ', 0, NULL, N'Conseguimos reduzir as dosagens e despedicios, e rapidez na parada e operação do sistema de dosagem de reagente.', '2026-06-26T00:00:00.000', '2026-06-28T17:14:53.000', N'81029859', NULL, NULL);
INSERT INTO #PVC VALUES (10915, N'1008368', N'1008368', N'Replacing Steam Trap', 1, N'No Replication/Sem replicação', N'Steam Trap 0199 is passing low pressure steam which is not making condensate which could be reused in boiler room. steam entering condensate vessel is lost as it escapes to atmosphere through vent on the vessel', N'Replace Trap without involving maintenance', N'0', N'01 - Imagens/01 - Antes/10915.jpeg', N'Steam Trap 0199 is passing low pressure steam which is not making condensate which could be reused in boiler room. steam entering condensate vessel is lost as it escapes to atmosphere through vent on the vessel', N'01 - Imagens/02 - Depois/10915.jpeg', N'New Trap installed allowing steam to convert to condensate for reuse rather than losing it through the vent stack', NULL, N'Steam trap was installed without involving maintennce ', N'Having operations complete task removes the cost of having maintenance  do it', 3000, 3, N'A revisão permite continuidade da lavra segregada dos autônomos até que a mina consiga converter toda a frota de equipamentos e também garante tempo hábil para realocação de estruturas do pátio 320.', '2026-06-27T00:00:00.000', '2026-06-28T17:31:09.000', N'1008368', NULL, NULL);
INSERT INTO #PVC VALUES (10916, N'1008368', N'1008368', N'Replacing Steam traps', 1, N'No Replication/Sem replicação', N'Waiting for Maintenance to replace steam trap is lost time and lost steam literally up the vent stack. Also the cost of maintenance doing the task can be saved if operations does the task', N'Replace Trap without involving maintenance', N'0', N'01 - Imagens/01 - Antes/10916.jpeg', N'Steam Trap 0200 is passing high pressure steam which is not making condensate which could be reused in boiler room. Steam entering the condensate vessel is lost as it escapes to atmosphere through vent on vessel.', N'01 - Imagens/02 - Depois/10916.jpeg', N'New Trap installed allowing steam to convert to condensate for reuse rather than losing it through the Vent stack.', NULL, N'Yes, new steam trap installed without involving maintenance', N'HAving operations complete task removes the cost of having maintenance do the task', 3000, 3, NULL, '2026-06-27T00:00:00.000', '2026-06-28T17:48:24.000', N'1008368', NULL, NULL);
INSERT INTO #PVC VALUES (10917, N'400428', N'400428', N'Lunchroom AC exhaust port', 3, N'Concentration/Concentração', N'Using cardboard which was flimsy that wouldn''t allow light in and not exhausting hot air properly', N'Make semi permanent, ttransparent exhaust port for AC', N'10058', N'01 - Imagens/01 - Antes/10917.jpeg', N'Using cardboard which was flimsy that wouldn''t allow light in and not exhausting hot air properly. This would also allow dust into lunchroom', N'01 - Imagens/02 - Depois/10917.jpeg', N'Cut plexiglass and proper port hole for exhaust and sealed. Sunlight can now come in through window and no hot air returning into lunchroom', NULL, N'Had cardboard which was not robust enough and not seal properly. Replaced with plexiglass and sealed properly', N'Make semi permanent plexiglass panel', 0, NULL, N'Maior assertividade para o plano de blend.', '2026-06-27T00:00:00.000', '2026-06-29T01:09:47.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (10918, N'922260', N'922260', N'ILUMINAÇÃO PARA MUFLA', 2, N'Projects/Projetos', N'Na fusão de amostras para análise flúor, devido a lente do capuz ser de cor verde por segurança na proteção da visão, dificulta a retirada de amostras em fusão, causando derramamentos e até esquecimento de cadinhos na mufla por falta de  visão dos mesmos.', N'AUMENTAR VISIBILIDADE NA FUSÃO DE AMOSTRAS', N'10103', N'01 - Imagens/01 - Antes/10918.jpeg', N'Na fusão de amostras para análise flúor, devido a lente do capuz ser de cor verde por segurança na proteção da visão, dificulta a retirada de amostras da mufla  , causando derramamentos e até esquecimento de cadinhos na mufla por falta de  visão dos mesmos.', N'01 - Imagens/02 - Depois/10918.jpeg', N'           Com a instalação de uma lanterna na frente da mufla, iluminando a parte interior da mufla  os cadinhos fundidos ficam visível ao operador da mufla. ', NULL, N'sim', N'um pequeno investimento elimina perdas de amostras.', 0, NULL, N'Rastreabilidade do processo e melhora no gerenciamento.', '2026-06-24T00:00:00.000', '2026-06-29T01:36:33.000', N'922260', NULL, NULL);
INSERT INTO #PVC VALUES (10919, N'400428', N'400428', N'Blocked electrical panel', 3, N'Others/Outros', N'Materials being stored in front electrical panels blocking access', N'To prevent materials being stored blocking access to electrical panel', N'10058', N'01 - Imagens/01 - Antes/10919.jpeg', N'Materials being stored in front of electrical panle blocking access', N'01 - Imagens/02 - Depois/10919.jpeg', N'Removed items and posted signs reminding employees not to store materials in front of electrical panels', NULL, N'Yes. Cleared pathway and posted sign to remind not to store materials blocking access to panel', N'Can be used in many other areas ', 0, NULL, N'Espera-se, com a implementação do Kaizen, eliminar as falhas recorrentes do sistema, elevar a confiabilidade operacional e garantir uma operação contínua, estável e tecnicamente adequada às condições de carga e desgaste do processo.', '2026-06-28T00:00:00.000', '2026-06-29T03:46:43.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (10920, N'81009130', N'81009130', N'Controle de Montagem de Andaime Parada Programada - PGU2026', 1, N'Others/Outros', N'A falta de controle a atualização manual das informações grande parte dos dados depende de preenchimento manual, aumentando o risco de erros, com a planilha não a evidência de avanços e controle das atividades e alerta para providência imediata.', N'Controle de Montagem Visual e detalhada - Avanços ', N'10184', N'01 - Imagens/01 - Antes/10920.jpeg', N'Com a visualização através de planilha a ausência de controle e prazos as informações grande parte inserida manualmente aumentando o risco de erros e a fata de padronização percebeu-se a dificuldade visual para tomar prioridade diante das atividade de PGU 2026.', N'01 - Imagens/02 - Depois/10920.jpeg', N'A implantação do Power Bi para controle de Andaime PGU2026 trouxe mais eficiência, confiabilidade e agilidade na gestão das atividades de montagem e desmontagem, permitindo uma visão integrada das demandas e apoiando as tomadas de decisão. Monitoramento em tempo real dos avanços, controle por área operacional e gerência, acompanhamento das vistas realizadas garantindo mais controle e gestão dos recursos. ', NULL, N'Sim, tivemos grande resultados nos controle e visualização via planejamento.', N'Aprendizado de controle e eficacia nos monitar\mento em área ', 0, NULL, N'Redução significativa do tempo de processamento e consolidação de dados.
INSERT INTO #PVC VALUES (10921, N'81046537', N'81002274', N'Tampão de isolamento hidráulico.', 1, N'Others/Outros', N'Tubo de acesso a bomba auxiliar 01, ao realizar manutenção no tubo, o mesmo fica exposto a contaminação por derramamento de óleo, pois o diâmetro do tubo é grande e não tem vedação padrão resultando em possível contaminação no solo.', N'Evitar contaminação do sistema hidráulico.', N'10324', N'01 - Imagens/01 - Antes/10921.jpeg', N'Ao realizar manutenção no tubo, o mesmo fica exposto a contaminação por derramamento de óleo, pois o diâmetro do tubo é grande e não tem vedação padrão resultando em possível contaminação no solo.', N'01 - Imagens/02 - Depois/10921.jpeg', N'Confeccionado tampa de isolamento do tubo da bomba auxiliar 01, evitando contaminação do sistema hidráulico do solo por derramamento de óleo .', NULL, N'Sim, evitado contaminação do sistema hidráulico e derramamento de óleo no solo.', N'SENTIMENTO DE DONO, DESENVOLVER MELHORIA E PROJETAR EM EQUIPE.', 0, NULL, N' Como solução, foi desenvolvido um formulário digital integrado a uma planilha automatizada, que permitirá a coleta estruturada dos dados diretamente em campo, o resultado esperado é a organização e automação do lançamento de dados', '2026-06-22T00:00:00.000', '2026-06-29T10:16:01.000', N'81046537', NULL, NULL);
INSERT INTO #PVC VALUES (10922, N'92000157', N'92000157', N'Relatório de Performance Pós Preventiva', 1, N'Others/Outros', N'Atualmente, a avaliação das manutenções preventivas é concentrada principalmente na execução da intervenção, sem uma visão estruturada do comportamento do ativo após sua liberação, limitando a capacidade de medir, de forma objetiva, se a preventiva executada foi efetiva para sustentar a performance do equipamento no curto prazo.
INSERT INTO #PVC VALUES (10923, N'81012522', N'81012522', N'Otimização da coleta e comunicação dos dados de horímetro dos equipamentos leves.', NULL, N'Others/Outros', N'Atualmente há dificuldade na comunicação e na coleta dos dados de horímetro dos equipamentos leves. A ausência de um fluxo padronizado para obtenção dessas informações resulta em atrasos na atualização dos controles, impactando o planejamento de manutenção, a programação das atividades e a confiabilidade dos dados operacionais.', N'Reduzir o tempo e aumentar a confiabilidade na obtenção dos dados de horímetro dos equipamentos leves, garantindo informações atualizadas para o planejamento e controle das operações.', N'10119', N'01 - Imagens/01 - Antes/10923.jpeg', N'A coleta das informações de horímetro dos equipamentos leves era realizada de forma manual, por meio de contatos individuais com operadores e responsáveis pelos equipamentos. Esse processo demandava tempo, dificultava a obtenção rápida dos dados e ocasionava atrasos na atualização dos controles e no planejamento das atividades de manutenção.', N'01 - Imagens/02 - Depois/10923.jpeg', N'Foi desenvolvido um formulário eletrônico (Microsoft Forms) acessado por meio de QR Code, contendo o cadastro de todos os equipamentos leves. Os operadores passaram a registrar a leitura dos horímetros diretamente no formulário durante o preenchimento do checklist diário, permitindo a atualização das informações em tempo real, aumentando a confiabilidade dos dados e reduzindo o tempo gasto na coleta e consolidação das informações.
INSERT INTO #PVC VALUES (10924, N'81053475', N'81053475', N'Automação do Planejamento de Capacidade da Manutenção por Meio da Consolidação Inteligente de HH', 1, N'Projects/Projetos', N'O levantamento da demanda de mão de obra para execução dos planos de manutenção preventiva e inspeção era realizado de forma manual, exigindo grande esforço para consolidar informações de listas de tarefas, planos de manutenção e programação anual. O processo demandava elevado tempo de tratamento dos dados e estava sujeito a inconsistências e retrabalho.', N'Desenvolver uma ferramenta automatizada capaz de calcular a necessidade de Horas-Homem (HH) para atividades preventivas e de inspeção, considerando a programação do mapa de 52 semanas, aumentando a produtividade, confiabilidade e agilidade das análises.', N'10015', N'01 - Imagens/01 - Antes/10924.jpeg', N'Extração e consolidação manual das informações.
INSERT INTO #PVC VALUES (10925, N'989707', N'140178', N'FORMULÁRIO DE VERIFICAÇÃO DE TORQUE RODAS EE01', 1, N'Others/Outros', N'Falta de padrão para torque de referência dos parafusos dos cubos das rodas E001 ', N'Padronização Rotina Torque das rodas E001', N'10081', N'01 - Imagens/01 - Antes/10925.jpeg', N'Falha por ruptura dos parafusos de fixação das rodas traseiras do eixo E001 associada à inexistência de procedimento padronizado para aplicação e controle do torque de aperto dos parafusos dos cubos das rodas.', N'01 - Imagens/02 - Depois/10925.jpeg', N'Elaborado e implantado formulário de verificação de torque para os parafusos de fixação dos cubos das rodas, estabelecendo padrão de inspeção, registro e controle dos valores de torque aplicados, garantindo a conformidade da montagem e reduzindo o risco de falhas por afrouxamento ou sobreaperto.', NULL, N'Problema: Ausência de padrão e controle do torque aplicado aos parafusos dos cubos das rodas, resultando em quebras dos parafusos do eixo E001.
INSERT INTO #PVC VALUES (10926, N'81046916', N'81046916', N'Garantia de vedações dos moinhos Polysius', 1, N'Concentration/Concentração', N'Após a aquisição de vedações com a empresa FLS, foi 
INSERT INTO #PVC VALUES (10927, N'538696', N'538696', N'Controle de Bombas automatico', 1, N'Others/Outros', N'Durante as manobras de paradas e operação das bombas de espumante 2 teríamos que ir individualmente em cada bomba para parar ou colocar lá em operação.', N'Automatizar bombas de reagentes', N'10054', N'01 - Imagens/01 - Antes/10927.jpeg', N'Durante as manobras de paradas e operação das bombas de espumante 2 teríamos que ir individualmente em cada bomba para parar ou colocar lá em operação, em alguns momentos devido a alta demanda, deixava uma ou outra bomba em operação e dosando reagente, ocasionando desperdício e complicações no retorno de Usina ocasionando transbordos devido excesso de espumante.', N'01 - Imagens/02 - Depois/10927.jpeg', N'Juntamento com a equipe de automação e técnicos de sala de controle tivemos uma ideia de fazer agrupamento dessas bombas pelo sistema, tendo assim a opção de parar todas as bombas na qual estão selecionadas pelo grupo, reduzindo o desperdício e dosagem excessiva, evitando transbordos ocasionado pela excesso de espuma.', NULL, N'Foi realizado a automatização agrupamento das bombas para trabalhar em conjunto, para evitar dosagens desnecessarias.', N'Trabalhar com equipamentos em modo automatico diminui desperdícios.', 0, NULL, NULL, '2026-06-18T00:00:00.000', '2026-06-29T11:09:39.000', N'538696', NULL, NULL);
INSERT INTO #PVC VALUES (10928, N'980813', N'980813', N'Revisão Design Rampas - Fase 6.2', 1, N'No Replication/Sem replicação', N'Atual design das Rampas da Fase 6.2 não encaixa na atual rampa dos autônomos. Essa condição impactaria a operação segregada para a lavra dessa frota e teria diretamente interferências com estruturas e pátios na PDE. ', N'Melhoria de design e condição operacional', N'10162', N'01 - Imagens/01 - Antes/10928.jpeg', N'Rampas impactando na lavra segregada dos caminhões autônomos e estruturas e pátio na PDE.', N'01 - Imagens/02 - Depois/10928.jpeg', N'Recuo das posições de rampa para garantia operacional de encaixe com a atual rampa de saída da lavra segregada dos caminhões autônomos.', NULL, N'Problema resolvido com a revisão do Design! Planejamento deve alinhar o novo desenho e garantir que seja executado em campo.', N'Necessidade de revisão periódica de design de Fases alinhadas às estratégias de lavra', 0, NULL, N'Redução significativa do tempo de elaboração do S-1, aumento da produtividade, maior confiabilidade das informações e eliminação de etapas manuais.', '2026-06-15T00:00:00.000', '2026-06-29T12:17:36.000', N'980813', NULL, NULL);
INSERT INTO #PVC VALUES (10929, N'486546', N'486546', N'Implementação de Trava na Caixa do Bico de Abastecimento (CA-02)', 2, N'Others/Outros', N'O equipamento CA-02 opera com caixa de armazenamento do bico de abastecimento sem sistema de travamento confiável, utilizando mecanismo frágil, o que resultou no desprendimento do bico e avaria de componente, gerando custo de R$ 12.000,00 e risco de recorrência.', N'Implementar sistema de travamento seguro na caixa do bico de abastecimento do CA-02, eliminando o risco de desprendimento e evitando recorrência de danos, com zero incidentes relacionados.', N'10079', N'01 - Imagens/01 - Antes/10929.jpeg', N'Após a implementação da trava mecânica reforçada com corrente em 11/06, o risco de abertura involuntária foi eliminado, reduzindo a probabilidade de ocorrência do evento de alta para praticamente nula, com consequente eliminação do potencial de dano associado (R$ 12.000,00 por ocorrência).
INSERT INTO #PVC VALUES (10930, N'81029574', N'81029574', N'Amostragem com a utilização da Retroescavadeira', 1, N'Others/Outros', N'Como parte da rotina operacional, é realizada semanalmente a inspeção das pilhas, com amostragem manual para validação de basculamentos com características físicas distintas. Esse acompanhamento é essencial devido à baixa disponibilidade de minério de alto teor, visando reduzir a diluição e aumentar a confiabilidade dos teores. O uso da retroescavadeira torna a amostragem mais representativa, contribuindo para um melhor controle da qualidade do minério destinado à britagem.
INSERT INTO #PVC VALUES (10931, N'81040303', N'81040303', N'Aplicativo de inspeção dos chutes', 1, N'Others/Outros', N'É realizado a inspeção dos chutes de alimentação, porém não havia um formulário padrão nem um local onde essas inspeções fossem registradas. O inspetor ia em campo abria OM para troca dos revestimentos danificados posteriormente.', N'Padronização; Gerenciamento; Rastreabilidade', N'10293', N'01 - Imagens/01 - Antes/10931.jpeg', N'É realizado a inspeção dos chutes de alimentação, porém não havia um formulário padrão nem um local onde essas inspeções fossem registradas. O inspetor ia em campo e fazia suas anotações, e posteriormente quando retornava para a sala abria OM para troca dos revestimentos danificados. As anotações eram individuais de cada inspetor e não eram registradas em nenhum outro lugar.', N'01 - Imagens/02 - Depois/10931.jpeg', N'Desenvolvido aplicativo utilizando Power apps, possibilitando que o inspetor selecione um dos 51 chutes previamente cadastrados e faça o registro de toda a inspeção dos revestimentos, apontando a condição do revestimento separando por lado do chute e área correspondente. Após todos os campos preenchidos o registro é salvo em um banco de dados no Sharepoint list. O app foi desenvolvido para suportar o registro de forma offline em caso de falta de rede.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/09e29265-780a-4dab-a67b-a895a2d30042?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=513c7b19-375a-4912-a2e3-3e1c3d9f50f0&sourcetime=1777551382196&source=portal', N'Agora é possível realizar o acompanhamento de todas as inspeções realizadas, possibilitando um melhor gerenciamento do processo.', N'Padronização; Gerenciamento', 0, NULL, N'5S', '2026-06-01T00:00:00.000', '2026-06-29T13:37:52.000', N'81040303', NULL, NULL);
INSERT INTO #PVC VALUES (10932, N'81049526', N'81049526', N'Eliminação de Falhas Recorrentes no Sistema Pinhão-Cremalheira', 1, N'Projects/Projetos', N'O sistema de translação da cabeça móvel do transportador de correia apresenta falhas recorrentes no conjunto pinhão-cremalheira, caracterizadas por desgaste prematuro e intervenções frequentes, resultando em paradas operacionais não planejadas e redução da confiabilidade do equipamento.
INSERT INTO #PVC VALUES (10933, N'81053475', N'81053475', N'Transformação Digital da Estimativa de Horas-Homem por Meio da Integração Automatizada de Dados Corretivos e Condicionais ', 1, N'Others/Outros', N'A obtenção da demanda de Horas-Homem (HH) proveniente das manutenções corretivas e condicionais exigia a consolidação manual de informações de múltiplas bases de dados, tornando o processo demorado, suscetível a erros e com baixa padronização. Essa limitação dificultava a realização de estudos de dimensionamento de equipes e análises de capacidade da manutenção.', N'Automatizar a consolidação dos dados de manutenção corretiva e condicional, oriundos do BI do PCM para disponibilizar estimativas confiáveis de HH e apoiar os estudos de dimensionamento, planejamento e tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/10933.jpeg', N'Coleta e tratamento manual de dados provenientes de diversas fontes.
INSERT INTO #PVC VALUES (10934, N'81061143', N'81061143', N'PratForms', 1, N'No Replication/Sem replicação', N'o principal problema estava relacionado ao fato de que os dados não eram aprovisionados em tempo real, o que causava não só atrasos, mas também desorganização nas informações da planilha. Isso dificultava o controle, a padronização e aumentava o risco de erros.
INSERT INTO #PVC VALUES (10935, N'521673', N'471863', N'Localização das caixas', 1, N'No Replication/Sem replicação', N'Antes não tinha identificação nas prateleiras para encontrar as caixas com mais facilidade e rapidez.', N'Encontrar as caixas com facilidade', N'10366', N'01 - Imagens/01 - Antes/10935.jpeg', N'Antes da melhoria, não existia identificação nas prateleiras, o que tornava mais difícil e demorada a localização das caixas.', N'01 - Imagens/02 - Depois/10935.jpeg', N'Com a implementação de etiquetas padronizadas de identificação, foi possível melhorar significativamente a organização do espaço e reduzir o tempo de busca das caixas.', NULL, N'Sim, antes não existia identificação nas prateleiras, o que tornava mais difícil e demorada a localização das caixas.', N'Organização', 0, NULL, N'Redução dos custos de materiais com maior controle e visibilidade do consumo, priorização dos itens críticos e atuação na causa. Maior eficiência nas decisões e fortalecimento da gestão de fornecedores.', '2026-06-25T00:00:00.000', '2026-06-29T14:55:19.000', N'521673', NULL, NULL);
INSERT INTO #PVC VALUES (10936, N'521673', N'81022694', N'Segurança no chuveiro de emergência', 2, N'No Replication/Sem replicação', N'Antes o chuveiro ficava solto e vindo pra frente quando puxava o triangulo. ', N'Fixar o chuveiro de emergência', N'10366', N'01 - Imagens/01 - Antes/10936.jpeg', N'Antes o chuveiro encontrava-se solto, deslocando-se para frente ao puxar o triângulo, o que comprometia a segurança e a estabilidade durante o uso.', N'01 - Imagens/02 - Depois/10936.jpeg', N'Após a realização do ajuste e fixação adequada do equipamento, foi eliminada a movimentação indevida, garantindo maior segurança, estabilidade e confiabilidade na operação, além de reduzir o risco de falhas e incidentes.', NULL, N'Antes da melhoria, o chuveiro encontrava-se solto, deslocando-se para frente ao puxar o triângulo, o que comprometia a segurança e a estabilidade durante o uso.
INSERT INTO #PVC VALUES (10937, N'92000576', N'92000576', N'Criação de Algoritmo para Detecção Automática de Interfaces de Telemetria Não Conectadas com Geração de Alertas Integrados ao Aplicativo de Intervenções para Atuação Proativa do time da Telemetria', 1, N'Others/Outros', N'Equipamentos de mina podem operar por longos períodos sem transmissão de dados de telemetria devido a falhas de comunicação de interface. Antes da melhoria, não existia um mecanismo automatizado capaz de identificar essa condição em tempo adequado, permitindo que ativos operassem sem geração de informação, comprometendo o monitoramento, a confiabilidade dos dados e a tomada de decisão operacional.', N'Desenvolver e implementar um algoritmo automatizado capaz de identificar equipamentos operando sem envio de dados de telemetria, gerar alertas de forma automática e integrar esses eventos ao fluxo de tratamento do CMA, garantindo atuação proativa e padronizada.', N'10015', N'01 - Imagens/01 - Antes/10937.jpeg', N'Antes da implementação, não havia controle sistematizado para identificar equipamentos operando sem geração de eventos de telemetria. A detecção de falhas de interface ocorria de forma reativa e pontual, dificultando o monitoramento contínuo dos ativos e comprometendo a confiabilidade das informações utilizadas nas análises operacionais.', N'01 - Imagens/02 - Depois/10937.jpeg', N'Foi desenvolvido um algoritmo que realiza a análise contínua dos equipamentos com base nas horas trabalhadas e na ausência de eventos de telemetria. Quando identificado que um equipamento esteve em operação sem gerar eventos no período analisado, o sistema gera automaticamente um evento denominado “Interface Não Conectada”, indicando possível falha de comunicação.
INSERT INTO #PVC VALUES (10938, N'544612', N'544612', N'Suporte para mangotes', 3, N'Others/Outros', N'Atualmente, os mangotes são armazenados de forma inadequada.', N'Desenvolver e implementar um suporte para armazenamento de mangotes.', N'10054', N'01 - Imagens/01 - Antes/10938.jpeg', N'Mangotes armazenados de forma inadequada, permanecendo no chão ou em locais improvisados, o que dificulta sua identificação e acesso, aumenta o risco de danos, contaminação e acidentes, além de gerar perda de tempo nas atividades operacionais. A ausência de um suporte específico compromete a organização e a produtividade do setor.', N'01 - Imagens/02 - Depois/10938.jpeg', N'Foi implantado um suporte específico para armazenamento dos mangotes, garantindo que permaneçam organizados, identificados e acondicionados corretamente. Com isso, houve redução do tempo de busca e manuseio, diminuição do risco de danos, contaminação e acidentes, além de melhoria na organização, segurança e eficiência das operações.', NULL, N'A meta inicial de desenvolver e implantar um suporte adequado para os mangotes foi alcançada. Após a implementação, os mangotes passaram a ser armazenados de forma organizada, segura e de fácil acesso, eliminando o armazenamento no chão e reduzindo riscos de danos e acidentes. A solução proporcionou maior agilidade nas operações, melhor organização do setor e aumento da eficiência, atendendo aos objetivos propostos.', N'A organização adequada dos mangotes melhora significativamente a eficiência das atividades.', 0, NULL, N'Reduced downtime as we need to make process changes to accommodate filter sluicing. Derisks the process having the redundant filter available quicker', '2026-06-26T00:00:00.000', '2026-06-29T16:49:38.000', N'544612', NULL, NULL);
INSERT INTO #PVC VALUES (10939, N'92000576', N'92000576', N'Automatização e Integração do Painel de Controle de Interfaces com Algoritmo de Detecção de Falhas de Comunicação e Atualização Frequente via Power BI', 1, N'Others/Outros', N'O controle das interfaces de telemetria era realizado manualmente por meio de planilhas Excel atualizadas periodicamente pelo time do CMA. Esse processo era limitado, com baixa frequência de atualização (semanal), alta dependência de intervenção humana e sem integração com o fluxo de tratamento dos eventos. Como consequência, havia atraso na visibilidade das falhas de comunicação e dificuldade para acompanhamento da situação real das interfaces dos equipamentos.', N'Automatizar o controle das interfaces de telemetria, integrando o algoritmo de detecção de falhas ao Power BI, disponibilizando indicadores atualizados de forma frequente e permitindo acompanhamento em tempo quase real da situação das interfaces e das tratativas realizadas.', N'10015', N'01 - Imagens/01 - Antes/10939.jpeg', N'Antes da melhoria, o controle das interfaces era feito por meio de planilhas Excel atualizadas manualmente, geralmente uma vez por semana. Esse processo exigia coleta manual de dados e posterior atualização da planilha, o que gerava atraso na disponibilização das informações, baixa frequência de atualização e ausência de integração com os eventos e tratativas realizadas pela telemetria.', N'01 - Imagens/02 - Depois/10939.jpeg', N'Foi realizada a automatização do controle de interfaces com integração do algoritmo de detecção ao Power BI, substituindo o processo manual em Excel. O painel passou a apresentar, de forma consolidada, o status das interfaces, falhas de comunicação e indicadores por frota, com atualização automática cerca de 6 vezes ao dia. Além disso, foi integrado ao Aplicativo de Intervenções, refletindo status, comentários e tratativas em tempo quase real, garantindo maior visibilidade, confiabilidade e suporte à tomada de decisão.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/fed38737-81c1-4d94-abce-067650557a61/4446ccdfa95b668c8002?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (10940, N'301042', N'607702', N'Standardize fan for 3800-3804 Ore Pass', 1, N'Underground/Subterrâneo', N'Initial development required a 30HP fan to ventilate the heading as it advanced. Once the development progressed the fan would need to be replaced with a larger fan to supply adequate CFM for the equipment in the area.', N'Ventilate Ore pass long term', N'10014', N'01 - Imagens/01 - Antes/10940.jpeg', N'30HP fan used for the development is not adequate to support the equipment used after the development is complete.', N'01 - Imagens/02 - Depois/10940.jpeg', N'The 75 HP fan installed will now support all equipment CFM requirements for the life of mine.', NULL, N'Installing the larger fan initially saves substantial cost in rework, cable wire costs as the two fans require different sizes of cable to power them, and down time on the main ramp as this is the main haulage ramp and would create conflicts within production.', N'Use a long-range outlook when planning jobs.', 43, 3, N'O Kaizen reduziu o tempo de análise e comunicação dos resultados de potabilidade, substituindo a consulta individual aos laudos laboratoriais por um boletim consolidado e visual. A melhoria permitiu interpretação mais rápida da campanha, identificação imediata de conformidades ou desvios e maior agilidade na comunicação com os clientes internos.', '2026-06-28T00:00:00.000', '2026-06-29T17:21:38.000', N'301042', NULL, NULL);
INSERT INTO #PVC VALUES (10941, N'81004893', N'81004893', N'S-1 Automático ', 1, N'Others/Outros', N'A elaboração do S-1 era realizada manualmente, demandando tempo dos analistas, aumentando o risco de inconsistências nas informações e reduzindo a produtividade do processo.', N'Automatizar a geração do S-1, reduzindo o tempo de elaboração, padronizando os registros e aumentando a eficiência do processo.', N'10015', N'01 - Imagens/01 - Antes/10941.jpeg', N'O S-1 era elaborado manualmente, exigindo preenchimento de diversos campos, consolidação de informações e revisões frequentes.', N'01 - Imagens/02 - Depois/10941.jpeg', N'O S-1 passou a ser gerado automaticamente a partir das informações inseridas no sistema, reduzindo a intervenção manual e garantindo maior padronização.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/8e4c9fa7-20a3-4d13-ad8c-908113eb074f/ReportSection0993b14cc60d2964a2dd?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'Foi desenvolvida uma funcionalidade para geração automática do S-1, utilizando dados já disponíveis no sistema e preenchendo os campos de forma padronizada.', N'Processos repetitivos possuem grande potencial de automação, permitindo que as equipes direcionem esforços para atividades de maior valor agregado.', 0, NULL, N'Agora os integrantes da célula de projetos não precisam atualizar sua base manualmente e recebem notificação via Teams de que novas notas foram adicionadas na base.', '2026-06-10T00:00:00.000', '2026-06-29T18:24:14.000', N'81004893', NULL, NULL);
INSERT INTO #PVC VALUES (10942, N'81004893', N'81004893', N'Inserção de Histórico de Tratamento de Eventos de Telemetria no Painel de Eventos', 1, N'Others/Outros', N'O acompanhamento do histórico de tratamento dos eventos de telemetria era realizado de forma descentralizada, dificultando a rastreabilidade das ações executadas, consultas futuras e análises de reincidência.', N'Disponibilizar o histórico completo de tratamento diretamente no painel de eventos, aumentando a visibilidade, rastreabilidade e agilidade na tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/10942.jpeg', N'As informações de tratamento dos eventos estavam dispersas em registros, e-mails ou consultas paralelas, demandando tempo para localização e validação do histórico.', N'01 - Imagens/02 - Depois/10942.jpeg', N'O histórico de tratamento passou a ser exibido diretamente no painel de eventos, permitindo consulta rápida e centralizada das ações realizadas.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/57b68cba-2247-4f57-899a-a8bd95b9b745/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Foi desenvolvida uma funcionalidade no painel de eventos para registrar e exibir automaticamente todo o histórico de tratamento, concentrando as informações em um único ambiente e facilitando o acompanhamento das ações realizadas.', N'A centralização das informações em um único ambiente reduz tempo de análise, melhora a gestão do conhecimento e aumenta a eficiência operacional.', 0, NULL, N'ELIMINAÇÃO DAS FALHAS RECORRENTES NOS ACIONAMENTOS M2 E M3 DA TR-2303SA-02.
INSERT INTO #PVC VALUES (10943, N'81004893', N'81004893', N'Nova Estruturação de Saving e Captura de Valor', 1, N'Others/Outros', N'A mensuração dos ganhos provenientes das iniciativas do CMA apresentava oportunidades de melhoria quanto à padronização dos cálculos, filtros de redução de valores e fluxo de validação, dificultando a rastreabilidade e a confiabilidade dos resultados apresentados.', N'Estruturar um processo padronizado de captura de valor, com critérios definidos para cálculo, filtros de categorização dos ganhos e fluxo de aprovação para validação dos savings.', N'10015', N'01 - Imagens/01 - Antes/10943.jpeg', N'Os ganhos eram apurados por custo residual de novo ou de reforma, sem necessidade aprovação para validação. ', N'01 - Imagens/02 - Depois/10943.jpeg', N'Os savings passaram a seguir metodologia padronizada, com aplicação de filtros de classificação, registros estruturados e fluxo de aprovação para validação dos resultados. Custo do Componente × % Vida Remanescente × Fator de Redução, sendo:
INSERT INTO #PVC VALUES (10944, N'538409', N'81035675', N'LOCOMOÇÃO DE FERRAMENTAS', 2, N'Others/Outros', N'ABUSO NA ERGONOMIA DURANTE LOCOMOÇÃO DE FERRAMENTAS', N'ERGONOMIA/5S', N'10138', N'01 - Imagens/01 - Antes/10944.jpeg', N'LOCOMOÇÃO BRAÇAL
INSERT INTO #PVC VALUES (10945, N'763789', N'763789', N'Implantação de sinalização preventiva para controle de acesso à passarela durante embarque de ferro gusa', 2, N'Others/Outros', N'A passarela que liga a base ao píer é amplamente utilizada e acompanha o transportador 8051 TC13. Porém existe um transportador de outra empresa, posicionado acima e durante embarque de ferro gusa, ocasionam queda de material sobre a passarela. Atualmente, o controle é feito apenas com fechamento do portão, sem sinalização visual, gerando risco de acesso indevido e baixa percepção do perigo.', N'Garantir que 100% dos colaboradores sejam alertados sobre o risco antes de acessar a passarela, eliminando acessos indevidos durante operações com ferro gusa.', N'10294', N'01 - Imagens/01 - Antes/10945.jpeg', N'O acesso à passarela era controlado apenas pelo fechamento do portão durante operações com ferro gusa. Não havia sinalização visual no ponto de entrada, o que dificultava a percepção do risco e poderia levar colaboradores a tentarem acessar a área sem conhecimento do perigo existente.', N'01 - Imagens/02 - Depois/10945.jpeg', N'Com a implantação da placa de sinalização no início da passarela, o risco de queda de material passou a ser comunicado de forma clara e imediata. Os colaboradores agora conseguem identificar o perigo antes do acesso, reduzindo tentativas indevidas e reforçando a segurança operacional.', NULL, N'Sim. A implantação da placa atendeu à meta de melhorar a comunicação de risco, garantindo que os colaboradores sejam alertados logo no início da passarela. Isso aumentou significativamente a percepção do perigo e reduziu a possibilidade de acesso indevido.', N'A comunicação visual no ponto de acesso é essencial para prevenir acidentes / Medidas apenas físicas (como portão) não são suficientes sem reforço informativo / A percepção de risco aumenta significativamente com sinalização clara e objetiva / Integração entre operações de diferentes empresas exige reforço na comunicação de segurança.', 0, NULL, N'This will allow for users to locate the files they are searching for in a timelier manner, less digging, less frustration, etc. ', '2026-06-24T00:00:00.000', '2026-06-30T01:24:08.000', N'763789', NULL, NULL);
INSERT INTO #PVC VALUES (10946, N'460522', N'81016737', N'Respirator Cartridges', NULL, N'Others/Outros', N'It was identified that ops areas were stocking 60926 cartridges, while our standard requirement is 60923 cartridges. 
INSERT INTO #PVC VALUES (10947, N'87000312', N'87000345', N'Energy Savings via Inverter Adjustment of No3 RT Industrial Water Pump', 1, N'Refining/Refino', N'When the 90kW compressor (No. 3) shut down, an excessive amount of water was supplied to the 3RT8F unit, resulting in energy loss.', N'Energy Savings', N'0', N'01 - Imagens/01 - Antes/10947.jpeg', N'When the 90kW compressor (No. 3) shut down, an excessive amount of water was supplied to the 3RT8F unit, resulting in energy loss.', N'01 - Imagens/02 - Depois/10947.jpeg', N'Changing the LOW setting of INV reduced energy loss.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Redução de inconsistência em BI amplamente consultado.', '2026-06-18T00:00:00.000', '2026-06-30T06:37:37.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (10948, N'81054419', N'81054419', N'Gestão Inteligente do Consumo de Materiais com Foco em Custos e Performance', 1, N'Underground/Subterrâneo', N'Atualmente não existe acompanhamento do consumo de materiais o que não permite uma visão clara dos itens mais utilizados e daqueles com maior impacto financeiro. Isso dificulta a identificação de desvios, análise de causas e a tomada de decisão para otimização de custos e melhoria de suprimentos.', N'Monitorar quantitativamente os itens consumidos; Identificar materiais de maior custo e relevância;', N'10015', N'01 - Imagens/01 - Antes/10948.jpeg', N'Ausência de visão estruturada do consumo de materiais, dificultando identificar itens críticos por custo e volume. ', N'01 - Imagens/02 - Depois/10948.jpeg', N'Relatório estruturado com análise de consumo por valor e quantidade, priorização e identificação de itens críticos. Suporte à tomada de decisão, redução de custos e desenvolvimento de fornecedores.', NULL, N'A meta de dar visibilidade ao consumo e priorizar itens críticos foi atingida com a criação do relatório. Conseguimos identificar os principais ofensores de custo e direcionar ações, reduzindo decisões reativas e atuando na causa.', N'A gestão eficaz do consumo exige dados estruturados e priorização por impacto financeiro. A análise integrada (custo x volume) direciona ações mais assertivas, fortalece decisões e viabiliza ganhos com fornecedores.', 0, NULL, NULL, '2026-06-29T00:00:00.000', '2026-06-30T08:44:16.000', N'81054419', NULL, NULL);
INSERT INTO #PVC VALUES (10949, N'1008800', N'1008800', N'IR1 R1 Reline completed below cost (2026)', 1, N'Projects/Projetos', N'IR1 Reactor #1 had carryover relining and reinstatement required from 2025 into 2026.', N'Complete relining, return tank to service', N'0', N'01 - Imagens/01 - Antes/10949.jpeg', N'IR1 Reactor #1 had outstanding work remaining from 2025 due to delays with a new regulation with SNL that all mobile compressors on site were to be registered.
INSERT INTO #PVC VALUES (10950, N'1008800', N'1008800', N'Install Titanium Agitator IR1 Reactor #1', 1, N'Refining/Refino', N'Existing agitator was deemed no longer suitable for service.', N'Improve equipment reliability', N'#N/A', N'01 - Imagens/01 - Antes/10950.jpeg', N'IR1 Reactor #1 Agitator was originally a carbon steel rubber lined assembly. The tank was upgraded to Carbon Steel FRP Lined in 2022. Rubber is not suitable for this service.
INSERT INTO #PVC VALUES (10951, N'202638', N'202638', N'Repurpose unused equipment', 1, N'Refining/Refino', N'Our Durco filter failed and was in need of repair. Repairs would take an expected 6 months', N'Cost savings', N'0', N'01 - Imagens/01 - Antes/10951.jpeg', N'Feed filter damage was going to need major repairs and the time to repair would be excessive due the work required', N'01 - Imagens/02 - Depois/10951.jpeg', N'Reuse a similar filter that was not in use in another building saving the down time expected to repair. This would allow us to get the filter back into service minimizing downtime and allow for the filter to be repaired ', NULL, N'yes', N'Using availabel redundant equipment to lessen down time', 0, NULL, N'Financeiro (estimado): ~6h/semana economizadas por coordenação × ~20 coordenações Salobo = ~480h/mês de ganho operacional, equivalente a redução de retrabalho e horas improdutivas dos coordenadores.
INSERT INTO #PVC VALUES (10952, N'1008800', N'1008800', N'CCD-1 Feed Tank Inspection and agitator replacement', 1, N'Refining/Refino', N'CCD-1 Feed Tank was suspected to be leaking. The tank was also operating without an agitator since approximately April 2025.', N'Inspect CCD-1 Overflow Tank and return to service', N'0', N'01 - Imagens/01 - Antes/10952.jpeg', N'The upper shaft of the agitator had sheared from the mixer.
INSERT INTO #PVC VALUES (10953, N'81046430', N'81013286', N'Boletim de Potabilidade Semanal da Mina Salobo', NULL, N'Others/Outros', N'Laudos de análises laboratoriais de potabilidade em linguagem técnica, pouco acessível ao público em geral.', N'Melhorar a governança e transparência das informações de qualidade da água potável através de padronização e layout visual claro, objetivo e didático', N'10017', N'01 - Imagens/01 - Antes/10953.jpeg', N'Os resultados das análises de monitoramento da potabilidade eram disponibilizados por meio dos laudos laboratoriais. Embora tecnicamente válidos e rastreáveis, esses documentos possuem linguagem analítica, formato pouco didático e leitura voltada ao público técnico, dificultando a interpretação rápida pelos clientes internos e ocasionando equívocos de interpretação além da geração de dúvidas frequentes.', N'01 - Imagens/02 - Depois/10953.jpeg', N'Com a aplicação do Kaizen, foi desenvolvido um modelo consolidado, visual e gerencial do Boletim Semanal de Potabilidade, permitindo transformar os dados laboratoriais em informação objetiva, acessível e orientada à tomada de decisão. O novo formato apresenta, em uma única interface, a aderência ao padrão de potabilidade, o status por ponto de consumo, os parâmetros monitorados e a performance geral da campanha. A melhoria aumentou a clareza, rastreabilidade e transparência da comunicação dos resultados de potabilidade, permitindo visualizar as informações com grande rapidez se a água está própria para consumo humano, se houve não conformidades e quais pontos foram monitorados, fortalecendo a confiança dos usuários e a governança do processo de saneamento.', NULL, N'O Kaizen atingiu a meta proposta ao melhorar significativamente a governança, transparência, padronização e comunicação dos resultados de potabilidade. O novo boletim reduziu a dependência da leitura individual dos laudos, facilitou a compreensão pelos clientes internos e fortaleceu a gestão visual da qualidade da água potável na Mina Salobo.', N'1. Informação técnica precisa ser traduzida para linguagem gerencial; 2. A consolidação reduz retrabalho e melhora a tomada de decisão;  3. Indicadores visuais aumentam a confiança dos clientes internos;  4. O boletim melhora a rastreabilidade e mantém a robustez técnica; 5. A gestão da potabilidade deve ser proativa, não apenas reativa; 6. Padronização fortalece a governança; 7. O Kaizen reduziu desperdício de inventário de informação.', 0, NULL, N'Organizar os materiais da tancagem de diesel em um local adequado, melhorando o acesso, o controle dos itens e reduzindo desperdícios por meio do reaproveitamento de tambores.', '2026-06-26T00:00:00.000', '2026-06-30T09:26:54.000', N'81046430', NULL, NULL);
INSERT INTO #PVC VALUES (10954, N'81063756', N'81063756', N'Inclusão automática de novas notas na base da célula de projetos', 1, N'Others/Outros', N'Os integrantes da Célula de Projetos precisavam acessar o Dashboard de Notas YE, copiar as novas notas, e colar em sua base de controle. Esse procedimento era completamente manual e exaustivo.', N'Reduzir esforço manual de atualização da base de dados da célula de projetos com inclusão de novas notas', N'10015', N'01 - Imagens/01 - Antes/10954.jpeg', N'Os integrantes da Célula de Projetos precisavam acessar o Dashboard de Notas YE, copiar as novas notas, e colar em sua base de controle. Esse procedimento era completamente manual e exaustivo.
INSERT INTO #PVC VALUES (10955, N'81039680', N'81050084', N'MELHORIA NA FIXAÇÃO DOS TRILHOS DO CABEÇA MÓVEL DA MOAGEM', 1, N'No Replication/Sem replicação', N'PARADAS POR FALHAS NOS ACIONAMENTOS M2 E M3 DA TR-2303SA-02 DEVIDO A AVARIAS NOS TRILHOS, CAUSADAS POR FALHAS DE FIXAÇÃO, OCASIONANDO DESNIVELAMENTO DOS TRILHOS.', N'GARANTIR A CONFIABILIDADE DO ATIVO', N'10178', N'01 - Imagens/01 - Antes/10955.jpeg', N'PARADAS POR FALHAS NOS ACIONAMENTOS M2 E M3 DA TR-2303SA-02 DEVIDO A AVARIAS NOS TRILHOS, CAUSADAS POR FALHAS DE FIXAÇÃO, OCASIONANDO DESNIVELAMENTO DOS TRILHOS.', N'01 - Imagens/02 - Depois/10955.jpeg', N'APÓS A FIXAÇÃO DOS CHUMBADORES DOS TRILHOS DA TR-2303SA-02, REALIZADA PELA EQUIPE ESPECIALIZADA DA HITA, O EQUIPAMENTO RETORNOU ÀS CONDIÇÕES OPERACIONAIS ADEQUADAS, RESTABELECENDO A CONFIABILIDADE OPERACIONAL DO ATIVO.', NULL, N'APÓS A EXECUÇÃO DOS SERVIÇOS DE FIXAÇÃO DOS CHUMBADORES DOS TRILHOS PELA EQUIPE ESPECIALIZADA DA HITA, O DESVIO FOI ELIMINADO, RESTABELECENDO O ALINHAMENTO E A INTEGRIDADE DOS TRILHOS. COMO RESULTADO, O EQUIPAMENTO RETORNOU ÀS CONDIÇÕES OPERACIONAIS ADEQUADAS, RECUPERANDO SUA CONFIABILIDADE OPERACIONAL E MITIGANDO O RISCO DE NOVAS PARADAS E PERDAS DE PRODUÇÃO ASSOCIADAS À FALHA IDENTIFICADA.', N'MELHORIA CONTÍNUA', 0, NULL, N'reduzir tempo de maquina parada por conta de reparos com pinturas', '2026-05-13T00:00:00.000', '2026-06-30T10:00:54.000', N'81039680', NULL, NULL);
INSERT INTO #PVC VALUES (10956, N'81063756', N'81063756', N'Boletim informativo de alteração em estratégia de manutenção', 1, N'Others/Outros', N'Não existia uma maneira formal de comunicar alterações propostas pela engenharia de estratégia. Gerando reclamações das áreas impactadas pela demora em receber tais atualizações.', N'Manter áreas impactadas atualizadas de alterações em estratégia de manutenção', N'10015', N'01 - Imagens/01 - Antes/10956.jpeg', N'Não existia uma maneira formal de comunicar alterações propostas pela engenharia de estratégia. Gerando reclamações das áreas impactadas pela demora em receber tais atualizações.
INSERT INTO #PVC VALUES (10957, N'369561', N'369561', N'Report KPIs LHS  - Plano A+3', 1, N'No Replication/Sem replicação', N'Dificuldade de obtenção de informações dos KPIs do sequenciamento de Cava e Pilhas para análises e divulgação dos resultados do Plano A+3.', N'Informações de KPIs rápidos e organizados referente ao sequenciamento de Cava e Pilhas para os Planos A+3', N'10162', N'01 - Imagens/01 - Antes/10957.jpeg', N'Para obtenção dos KPIs, era necessário fazer exportação de vários arquivos no Excel com tabelas de resumo para análises e divulgação dos resultados.', N'01 - Imagens/02 - Depois/10957.jpeg', N'Implantação de um template no Deswik.Sched para exportação automática e organizada dos KPIs do plano para o Excel.', NULL, N'SIM', N'Tratativas de dados automaticamente elimina a possibilidade de erros.', 0, NULL, N'alguns itens foram reutilizados de outras áreas, mantendo de forma mais econômica na execução do projeto.', '2026-06-15T00:00:00.000', '2026-06-30T10:13:08.000', N'369561', NULL, NULL);
INSERT INTO #PVC VALUES (10958, N'1010242', N'1010242', N'D2 PID Cleanup', 1, N'No Replication/Sem replicação', N'Since the migration of all previous doc management systems into D2, there has been a significant number of duplicated files.  The most important documents affected are PIDs (there are other types duplicated as well - which I will work on in the future).  These duplicated files could pose a risk to D2 users if they are unfamiliar with the search method or doc management standard.  Choosing the incorrect PID could give them a very inaccurate version and something that does not show field accurate conditions.', N'To provide a single document, eliminating the need and risk to choose between multiple options.', N'10342', N'01 - Imagens/01 - Antes/10958.jpeg', N'There are a significant number of duplicated PID numbers in D2.  Not only are the layering of versions incorrect and duplicated, but there are different variations of the same PID number.  To reduce the risk of using the wrong PID number, we have marked all old versions as Superseded status and just the one correct PID as Effective status. ', N'01 - Imagens/02 - Depois/10958.jpeg', N'After multiple conversations with the D2 Support Team, it was determined that this migration issue was not an error with D2 itself and therefore it was something that I would have to correct manually.  This process involves viewing/downloading each version of the files, deleting the revisions that are duplicated, deleting the variations of the number so that when we run a search we only get one result, and keeping a log of all meta data of the files removed. D2 currently has 749 PIDs, this initiative is a work in progress, but thus far I have gone through 100 PIDs and removed 2574 versions.  Once this entire task is complete, it will remove all risk of opening the incorrect PID and will make searching in D2 smoother.', NULL, N'Once I have managed all 749 PIDs, this problem should no longer exist.', N'Develop a more comprehensive migration plan prior to completing the migration, migrate in small sets of documents', 0, NULL, N'Alinhamento entre as áreas de interesse, que trouxe maior previsibilidade pra todos.', '2026-06-29T00:00:00.000', '2026-06-30T10:25:37.000', N'1010242', NULL, NULL);
INSERT INTO #PVC VALUES (10959, N'538725', N'538725', N'Sistema de aterramento para reabastecimento de comboio', 2, N'Others/Outros', N'Identificado que o conjunto (carretel, cabo e garra de conexão) apresenta condições inadequadas de conservação, com sinais de desgaste, sujeira e possível oxidação.
INSERT INTO #PVC VALUES (10960, N'81063756', N'81063756', N'Atualização da base de Workforce MDM do BI de Notas YE', 1, N'Others/Outros', N'Vários colaboradores da gerência estavam apresentando o status de INATIVO NO SITEMA no campo referente à gerência do Criador da Nota. E foi detectado que a base Workforce MDM estava a mais de 1 ano desatualizada.', N'Atualizar a base de Workforce MDM do BI de Notas YE para eliminar o status INATIVO NO SISTEMA de colaboradores ativos', N'10015', N'01 - Imagens/01 - Antes/10960.jpeg', N'Vários colaboradores da gerência estavam apresentando o status de INATIVO NO SITEMA no campo referente à gerência do Criador da Nota. E foi detectado que a base Workforce MDM estava a mais de 1 ano desatualizada.', N'01 - Imagens/02 - Depois/10960.jpeg', N'Atualização da base de Workforce MDM no SharePoint e no Power BI e a gerência do criador da nota passou a refletir corretamente.', NULL, N'Os colaboradores ativos no sistema tiveram o campo que antes apontava "INATIVO NO SISTEMA" regularizado.', N'Extração de base Workforce MDM atualizada', 0, NULL, N'Compartilhamento contínuo por meio de pílulas de conhecimento rápidas e acessíveis', '2026-06-08T00:00:00.000', '2026-06-30T11:06:12.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (10961, N'81044914', N'81044914', N'Redução de custo com licenças de informática não utilizadas', 1, N'Others/Outros', N'Atualmente, as licenças de informática não são revisadas, ou seja, algum funcinário pode ter alguma licença que não utiliza mais ou que não precisa gerando custos desnecessários à organização', N'Reduzir custos com licenças não utilizadas', N'10222', N'01 - Imagens/01 - Antes/10961.jpeg', N'Geração de custos com licenças sem gestão próxima', N'01 - Imagens/02 - Depois/10961.jpeg', N'Redução de R$ 5.600 anuais em licenças não utilizadas no PCM', NULL, N'Redução  de R$ 5.600 anuais em licenças de informática que não estavam sendo utilizadas e relocação com a relocação, o valor total vai pra R$ 13.400', N'Redução de custos, otimização de custos, sentimento de dono, empoderamento com comprometimento', 5600, 1, N'Workers know how to get to each piece of equipment ', '2026-06-23T00:00:00.000', '2026-06-30T11:12:14.000', N'81044914', NULL, NULL);
INSERT INTO #PVC VALUES (10962, N'81063756', N'81063756', N'Atualização da base de equipamentos da mina SLB no formulário de disparo de gatilho manual de RAF', 1, N'Others/Outros', N'O formulário estava bastante desatualizado, a ponto de que faltavam uma série de equipamentos novos, o que dificultava o time de Confiabilidade a disparar gatilhos manuais de RAF. Além disso, os disparos manuais de Pneus no BI sempre eram disparados para o responsável pelo equipamento, e não pelo responsável de Pneus.', N'Atualizar base de equipamentos da mina SLB no formulário de disparo de gatilho manual de RAF', N'10015', N'01 - Imagens/01 - Antes/10962.jpeg', N'O formulário estava bastante desatualizado, a ponto de que faltavam uma série de equipamentos novos, o que dificultava o time de Confiabilidade a disparar gatilhos manuais de RAF. Além disso, os disparos manuais de Pneus no BI sempre eram disparados para o responsável pelo equipamento, e não pelo responsável de Pneus.', N'01 - Imagens/02 - Depois/10962.jpeg', N'Hoje temos a lista de equipamentos do atualizada no formulário e os gatilhos manuais de RAF de pneus estão sendo devidamente apontados para o responsável por pneus no BI.', NULL, N'Agora a lista de equipamentos do formulário está atualizada e os gatilhos manuais de RAF de pneus redirecionados para o devido responsável.', N'Edição de formulários Vale Forms', 0, NULL, N'Vacuum quality control now has a baseline, and vacuum effectiveness can be validated periodically. ', '2026-06-10T00:00:00.000', '2026-06-30T11:54:32.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (10963, N'81040303', N'81040303', N'SmartRAF — Motor de Maturidade de RAF da Usina Salobo', 1, N'Others/Outros', N'A análise das RAFs (Registro de Análise de Falha) da Usina Salobo era feita 
INSERT INTO #PVC VALUES (10964, N'81040303', N'81040303', N'Boletim Diário VPS por Coordenação — Salobo', 1, N'Others/Outros', N'O acompanhamento das pendências de rotina VPS em Salobo (Diário de Bordo, Ações Stratws+SAP, Treinamentos, Kaizens, IRIS/Proativos de Segurança e YE) era manual, disperso entre múltiplos sistemas e sem ritual padronizado, gerando falta de visibilidade em tempo real, risco de descumprimento de prazos e metas, retrabalho dos coordenadores e perda de aderência aos indicadores estratégicos do FMDS e do Gerenciamento da Rotina.', N'Garantir 100% de visibilidade diária das pendências de rotina por coordenação em Salobo, via notificação automática no Microsoft Teams, elevando a aderência aos indicadores VPS (DB, Ações, Treinamentos, Kaizens, IRIS e YE) em até 90 dias após o go-live (22/06/2026).', N'10293', N'01 - Imagens/01 - Antes/10964.jpeg', N'Antes do Boletim Diário VPS, cada coordenador precisava acessar manualmente Stratws, SAP, SharePoint e Power BI para identificar pendências de DB, ações, treinamentos, kaizens, IRIS e YE. Não havia ritual fixo, canal único nem notificação automática, o que gerava:
INSERT INTO #PVC VALUES (10965, N'1013697', N'1013697', N'Ultrasonic Autolubricators for RB 425L Pump Station', 1, N'Underground/Subterrâneo', N'Manual greasing required on calendar based frequency for main dewatering pumps in Reid Brook mine. Limited condition based monitoring.', N'Improve condition based monitoring and MTBF', N'10311', N'01 - Imagens/01 - Antes/10965.jpeg', N'Grease zerks located on pump and motor require manual greasing, and lack of sensors for condition based monitoring. Manual greasing takes time for technician to visit the area and requires them to work around running equipment.', N'01 - Imagens/02 - Depois/10965.jpeg', N'Ultrasonic sensors and autolubricators installed on the pump and motor. The sensors continuously monitor the equipment and will grease the bearings based on friction readings. This reduces the labour required to manually grease, and provides information on asset health and the ability to predict failures in advance, minimizing unplanned down time.', NULL, N'Yes. Ultrasonic autolubricators are able to grease equipment automatically reducing labour resources, and improving condition based monitoring. Asset health is able to be monitored remotely.', N'Predictive maintenance and resource efficiency', 0, NULL, NULL, '2026-06-01T00:00:00.000', '2026-06-30T13:14:39.000', N'1013697', NULL, NULL);
INSERT INTO #PVC VALUES (10966, N'121608', N'121608', N'Tambor trasformado em armario', 3, N'Others/Outros', N'Os materiais utilizados nas atividades da tancagem de recebimento de diesel não possuíam um local adequado e padronizado para armazenamento, permanecendo dispersos na área operacional. Essa condição dificultava a organização, o acesso e o controle dos itens, aumentando o risco de perdas e danos aos materiais.
INSERT INTO #PVC VALUES (10967, N'81011163', N'81062557', N'Implementação de Manutenção Preditiva com PDMA nos Motores da Correia 2101-TC-02', 1, N'Others/Outros', N'Os motores da correia transportadora 2101-TC-02 são ativos críticos no fluxo da britagem, conforme fluxograma do processo, sendo responsáveis pelo transporte do minério britado até a pilha de 38.000 t. Uma falha corretiva nesses motores resulta na parada total do processo de britagem por aproximadamente 12 horas, impactando diretamente a alimentação da planta. Atualmente, o plano de manutenção desses motores contempla apenas inspeções sensitivas, termografia, análise de vibração, medição de isolação e lubrificação periódica. Não há monitoramento preditivo elétrico capaz de identificar antecipadamente falhas internas como: degradação de isolação entre espiras, barras quebradas de rotor, excentricidade, desequilíbrios de alimentação e contaminação dos enrolamentos. A ausência dessa camada preditiva eleva o risco de falhas inesperadas, cujo impacto financeiro de uma única ocorrência (12h de parada) é de R$ 7.726.184,81 em lucro cessante, considerando taxa da usina de 2.300 t/h, teores de ', N'Reduzir em no mínimo 80% a ocorrência de falhas corretivas nos motores da correia 2101-TC-02, por meio da inclusão da análise preditiva elétrica (PDMA) no plano de manutenção, eliminando paradas não programadas da britagem e evitando perdas de produção superiores a R$ 7,7 milhões por evento.', N'10081', N'01 - Imagens/01 - Antes/10967.jpeg', N'O plano de manutenção atual contempla inspeções sensitivas, termografia, análise de vibração, medição de resistência de isolação e lubrificação periódica, proporcionando monitoramento adequado dos aspectos mecânicos e parte das condições elétricas dos equipamentos.
INSERT INTO #PVC VALUES (10968, N'81006946', N'81006946', N'Gaiola para Armazenar tintas', 3, N'Others/Outros', N'ausência de tinta na área quando necessário por falta de local para armazenar corretamente.', N'otimizar reparos que necessitam de pinturas', N'10139', N'01 - Imagens/01 - Antes/10968.jpeg', N'A área não possuía um local adequado para armazenar tintas utilizadas em pequenos reparos após serviços de solda em equipamentos. Essa condição comprometia a organização, dificultava o controle dos materiais, aumentava o risco de danos às embalagens e poderia ocasionar desperdícios, impactando a eficiência das atividades de manutenção.', N'01 - Imagens/02 - Depois/10968.jpeg', N'Com a confecção da gaiola para armazenamento de tintas, foi possível organizar adequadamente os materiais, facilitar o controle de estoque.', NULL, N'sim! se mantermos a disciplina.', N'a organização e o armazenamento adequados das tintas melhoram a segurança', 0, NULL, N'MELHOR ASPECTO VISUAL.', '2026-06-29T00:00:00.000', '2026-06-30T15:03:23.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (10969, N'81030963', N'81038507', N'PULSO SEGURO – Segurança Inclusiva por Alerta Vibratório', 1, N'Others/Outros', N'A dependência de alertas sonoros limitava a percepção de riscos por pessoas com deficiência auditiva, reduzindo sua autonomia e aumentando o tempo de resposta em situações de emergência.', N'Aumentar percepção de risco do colaborador e dar a ele autonomia ', N'10079', N'01 - Imagens/01 - Antes/10969.jpeg', N'A dependência de alertas sonoros limitava a percepção de riscos por pessoas com deficiência auditiva, reduzindo sua autonomia e aumentando o tempo de resposta em situações de emergência.', N'01 - Imagens/02 - Depois/10969.jpeg', N'Após a implantação do Pulso Seguro, colaboradores com deficiência auditiva passaram a receber alertas imediatos por vibração, ampliando a segurança, autonomia, inclusão e agilidade nas emergências.', NULL, N'Meta: Garantir que 100% dos colaboradores recebam alertas de segurança de forma imediata e acessível', N'QUE PODEMOS USAR TECNOLOGIA COMO ALIADO DA SEGURANÇA ', 0, NULL, N'Promover maior integração entre os colaboradores da Governança de Contratos, aumentar o engajamento da equipe em iniciativas coletivas e criar um ambiente digital colaborativo que facilite o conhecimento das competências, experiências e conquistas dos integrantes da equipe.', '2026-06-19T00:00:00.000', '2026-06-30T15:03:41.000', N'81030963', NULL, NULL);
INSERT INTO #PVC VALUES (10970, N'520942', N'520942', N'Cobertura em parada de onibus', 2, N'No Replication/Sem replicação', N'qualidade e segurança para todos os empregados que fazem uso desse espaço.', N'valorizar pessoas', N'10232', N'01 - Imagens/01 - Antes/10970.jpeg', N'parada de ônibus para revezamento de turno, com exposição de sol e chuva no posto de combustível.', N'01 - Imagens/02 - Depois/10970.jpeg', N'cobertura na parada de ônibus para os empregados realizarem de forma mais segura, pois garante proteção e integridade das pessoas.', NULL, N'problema resolvido e aprovado pelos usuários.', N'Valorizar pessoas', 0, NULL, N'Redução no tempo de criação da estratégia, maior segurança nas ações traçadas.', '2026-06-02T00:00:00.000', '2026-06-30T15:26:15.000', N'520942', NULL, NULL);
INSERT INTO #PVC VALUES (10971, N'525833', N'525833', N'Report Mapa de Componente M+12', 1, N'Others/Outros', N'Falta de controle e reporte das projeções de troca de componentes da frota de escavação gera falha na comunicação entre planejamento, programação e execução, causando ausência de programação por falta de info sobre troca, OM e material.', N'Dar visibilidade as projeções de troca de componente', N'10023', N'01 - Imagens/01 - Antes/10971.jpeg', N'Falta de controle e reporte das projeções de troca de componentes da frota de escavação gera falha na comunicação entre planejamento, programação e execução, causando ausência de programação por falta de info sobre troca, OM e material.', N'01 - Imagens/02 - Depois/10971.jpeg', N'Após implantação, há controle centralizado das projeções, integração entre áreas e visibilidade de prazos, OM e materiais, garantindo programação antecipada e maior eficiência nas trocas.
INSERT INTO #PVC VALUES (10972, N'503120', N'52548', N'Organizador de equipamentos de manejo de fauna ', 3, N'Others/Outros', N'Durante as ações de resgate e manejo de fauna, os equipamentos eram transportados de forma solta na carroceria da caminhonete, permanecendo expostos às intempéries, o que comprometia sua conservação, segurança e eficiência operacional.', N'Melhor condicionamento dos equipamentos, bem como durabilidade.', N'10104', N'01 - Imagens/01 - Antes/10972.jpeg', N'Durante as ações de resgate e manejo de fauna, os equipamentos eram transportados de forma solta na carroceria da caminhonete, permanecendo expostos às intempéries, o que comprometia sua conservação, segurança e eficiência operacional.', N'01 - Imagens/02 - Depois/10972.jpeg', N'Atualmente, os equipamentos de resgate e manejo de fauna são armazenados em um organizador adequado, permitindo fácil acesso pela lateral da caminhonete e garantindo maior agilidade, organização e preservação dos materiais.', NULL, N'Com essa iniciativa, houve ganho significativo no tempo de resposta, na organização das atividades e na adoção de uma postura ergonômica mais adequada pelos empregados.', N'Atividades planejadas e organizadas são mais eficazes.', 0, NULL, N'Diminuição de tempo na execução da atividade.', '2026-06-29T00:00:00.000', '2026-06-30T15:38:37.000', N'503120', NULL, NULL);
INSERT INTO #PVC VALUES (10973, N'81030963', N'81047196', N'P Conhecimento que Protege: Pílulas de Segurança Baseadas nos PROs', 1, N'Others/Outros', N'Os PROs estavam disponíveis, mas o compartilhamento do conhecimento nem sempre alcançava toda a equipe, podendo gerar dúvidas operacionais e interpretações divergentes dos procedimentos.a.', N'Garantir que 100% da equipe tenha acesso rápido e padronizado aos procedimentos operacionais (PROs), fortalecendo o compartilhamento do conhecimento, reduzindo dúvidas operacionais e aumentando a conformidade com os requisitos de segurança.', N'10079', N'01 - Imagens/01 - Antes/10973.jpeg', N'Os PROs estavam disponíveis, mas o compartilhamento do conhecimento nem sempre alcançava toda a equipe, podendo gerar dúvidas operacionais e interpretações divergentes dos procedimentos.', N'01 - Imagens/02 - Depois/10973.jpeg', N'Com a criação das Pílulas de Conhecimento de Segurança, baseadas nos PROs de Armazenagem, Estocagem e Operação do Armazém e CMD, o conhecimento passou a ser compartilhado de forma simples, objetiva e contínua.
INSERT INTO #PVC VALUES (10974, N'81050261', N'81050261', N'Refinery Drawings on Lunch Room Board ', NULL, N'Refining/Refino', N'New team for Refinery had issues with finding certain types of equipment throughout the areas.  ', N'View Drawings before proceeding to equipment ', N'0', N'01 - Imagens/01 - Antes/10974.jpeg', N'No GA''s Drawings for the team to view before heading out into the building ', N'01 - Imagens/02 - Depois/10974.jpeg', N'GA''s and Drawings posted on the Lunch Room Wall ', NULL, N'Yes', N'Give as many documents to personnel as requested ', 0, NULL, N'Consumo de explosivos foi adequado a real necessidade.', '2026-06-28T00:00:00.000', '2026-06-30T16:05:38.000', N'81050261', NULL, NULL);
INSERT INTO #PVC VALUES (10975, N'200768', N'200768', N'Road dust sampling vacuum - using a battery vs generator', 2, N'No Replication/Sem replicação', N'Workers are exposed to hazards when using a generator for road dust sampling. 
INSERT INTO #PVC VALUES (10976, N'81044397', N'81044397', N'    Reaproveitamento de Peças para Confecção de Suporte de Luvas', 3, N'Projects/Projetos', N'As luvas utilizadas pelos colaboradores não possuíam um local adequado para armazenamento, o que dificultava a organização, o acesso rápido ao EPI e contribuía para o desperdício de materiais. Além disso, havia peças sem utilização que poderiam ser reaproveitadas para atender essa necessidade.', N'Promover a organização dos EPIs, reduzir desperdícios e incentivar o reaproveitamento de materiais disponíveis na unidade.', N'10213', N'01 - Imagens/01 - Antes/10976.jpeg', N'As luvas utilizadas pelos colaboradores não possuíam um local adequado para armazenamento, o que dificultava a organização, o acesso rápido ao EPI e contribuía para o desperdício de materiais. Além disso, havia peças sem utilização que poderiam ser reaproveitadas para atender essa necessidade.', N'01 - Imagens/02 - Depois/10976.jpeg', N'Foi confeccionado um suporte para luvas utilizando peças reaproveitadas que estavam sem utilização. A solução permitiu a criação de um local adequado para armazenamento e disponibilização das luvas, facilitando o acesso dos colaboradores, melhorando a organização do ambiente de trabalho e reduzindo o desperdício de materiais. A ação contribuiu para a otimização dos recursos existentes, promovendo sustentabilidade e melhoria contínua no processo.', NULL, N'Sim', N'O reaproveitamento de materiais disponíveis pode gerar soluções simples, eficazes e de baixo custo para as necessidades do dia a dia. Com criatividade e foco na melhoria contínua, é possível otimizar recursos, reduzir desperdícios e melhorar a organização do ambiente de trabalho.', 0, NULL, N'É POSSIVE REALIZAR ATIVIDADES SIMULTANEAS COM MINIMIZAÇÃO DO RISCO DE PROJEÇÃO DE LIMALHAS', '2026-06-28T00:00:00.000', '2026-06-30T16:49:50.000', N'81044397', NULL, NULL);
INSERT INTO #PVC VALUES (10977, N'81047013', N'478939', N'Espaço adequado para conjunto oxicorte', NULL, N'Others/Outros', N'O carrinho de conjunto de oxicorte ficava dentro da caldeiraria muito próximo da bancada de realização das atividades, oferecendo riscos para o time.', N'Retirar o conjunto de oxicorte do raio de atividades na caldeiraria', N'10362', N'01 - Imagens/01 - Antes/10977.jpeg', N'O carrinho de conjunto de oxicorte ficava dentro da caldeiraria muito próximo da bancada de realização das atividades, oferecendo riscos para o time.', N'01 - Imagens/02 - Depois/10977.jpeg', N'Foi fabricado um espaço para disposição do conjunto de oxicorte e do carrinho, com cobertura, suporte adequado, mais de 5 metros de distância do local de atividade, possibilitando atuação mais segura.', NULL, N'Meta totalmente alcançada com a disposição do conjunto de oxicorte em uma distância segura para a realização das atividades.', N'Segurança', 0, NULL, N'Elaborado Book de FDS, disponivel em local de facil acesso e com gestao a vista na entrada da ferramentaria', '2026-06-12T00:00:00.000', '2026-06-30T17:13:57.000', N'81047013', NULL, NULL);
INSERT INTO #PVC VALUES (10978, N'81020643', N'81020643', N'Aplicação de adesivos na sinalização de emergência de PAEBM', 1, N'Others/Outros', N'Baixa ou nenhuma visibilidade da sinalização de emergência do PAEBM.', N'Otimizar custo na fabricação e agilizar conformidade operacional da sinalização de emergência do PAEBM', N'10141', N'01 - Imagens/01 - Antes/10978.jpeg', N'Aqui está um exemplo de placa de rota de fuga sentido único
INSERT INTO #PVC VALUES (10979, N'81047013', N'472909', N'Substituição do recalque da 2051BP01R', NULL, N'Others/Outros', N'TUBULAÇÃO DE RECALQUE DA BOMBA DE POÇO DA BRITAGEM MUITO DETERIORADA, IMPACTANDO O PROCESSO POR REPETIDAS FALHAS', N'Trocar tubulação danificada por uma mais resistente', N'10362', N'01 - Imagens/01 - Antes/10979.jpeg', N'TUBULAÇÃO DE RECALQUE DA BOMBA DE POÇO DA BRITAGEM MUITO DETERIORADA, IMPACTANDO O PROCESSO POR REPETIDAS FALHAS', N'01 - Imagens/02 - Depois/10979.jpeg', N'REALIZADA SUBSTITUIÇÃO DA TUBULAÇÃO DE AÇO CARBONO POR UMA DE INOX, MUITO MAIS RESISTENTE, ALÉM DE TER SIDO COLOCADO UM FLANGE PARA FACILITAR A MANUTENÇÃO', NULL, N'Meta alcançada com a troca da tubulação por uma de material mais resistente', N'PRODUTIVIDADE', 0, NULL, N'Redução no tempo dedicado a avaliação dos dados e retorno rápido na aprovação ou rejeição da nova projeção de DF.', '2026-06-24T00:00:00.000', '2026-06-30T17:43:08.000', N'81047013', NULL, NULL);
INSERT INTO #PVC VALUES (10980, N'81042217', N'551106', N'Implantação de ponto de ar comprimido dedicado no transportador TC12 para eliminação de deslocamentos e esforço operacional​', 2, N'Others/Outros', N'Segurança operacional · Ar comprimido · Ergonomia · Redução de esforço físico · Kaizen · Eficiência operacional · Melhoria contínua', N'Eliminar a necessidade de utilização do ponto de ar comprimido do TC14 para atendimento ao TC12.​ Reduzir o esforço físico dos colaboradores durante a atividade.​  Aumentar a segurança ao evitar deslocamentos frequentes em escadas e áreas elevadas.​  Tornar a atividade mais ágil e eficiente, garantindo execução no próprio local de trabalho.', N'10294', N'01 - Imagens/01 - Antes/10980.jpeg', N'Com a inexistência de ponto de ar comprimido no TC12 para realizar atividades de limpeza no local havia a necessidade de puxar a mangueira do TC14 até o TC12, dificultando a execução da atividade, sendo necessário um colaborador permanecer no TC14 para ligar/desligar o ar comprimido, com deslocamentos frequentes em escadas para manuseio da mangueira e esforço físico elevado para transporte e posicionamento da mangueira e limitação de alcance para execução de atividades em outros pontos do TC12. Com esse trabalho foi possível se eliminar o principal desperdício que era o de Movimentação desnecessária e espera onde com o ponto', N'01 - Imagens/02 - Depois/10980.jpeg', N'Instalação de ponto de ar comprimido dedicado no TC12, com válvula de fácil acesso, essa melhoria trouxe a eliminação da necessidade de utilizar o ponto do TC14, podendo ser executada atividades simultâneas no 14 e 12, redução significativa do esforço físico e dos deslocamentos entre transportadores, aumento da autonomia do colaborador para execução da atividade com a ampliação do alcance da mangueira para atender outros pontos do próprio transportador garantindo uma limpeza mais eficiente e com menos impacto ao colaborador e ao ativo.​', NULL, N'O problema foi resolvido com a implantação do ponto de ar comprimido no TC12 que eliminou a necessidade de utilização do TC14, reduzindo deslocamentos, esforço físico e dependência de outro colaborador. A atividade passou a ser realizada diretamente no local, com maior segurança, agilidade e eficiência, atendendo aos objetivos propostos e eliminando desperdícios do processo.​', N'A disponibilização de recursos no ponto de uso reduz esforços e aumenta a segurança com pequenas adaptações estruturais pode ser gerados ganhos significativos em produtividade e qualidade operacional. A eliminação do risco de deslocamentos desnecessários melhora a eficiência e reduz cenários de potenciais acidentes. A autonomia operacional é um fator chave para garantir uma produção segura.​', 0, NULL, N'Confeccionado com materiais sobressalentes na area, um suporte para caixa termica, eliminando o contato direto com o solo/chão e minimizando riscos ergonomicos', '2026-05-22T00:00:00.000', '2026-06-30T17:45:53.000', N'81042217', NULL, NULL);
INSERT INTO #PVC VALUES (10981, N'498359', N'81046967', N'5S SALA DE LUBRIFICAÇÃO 2251MO02', 3, N'Others/Outros', N'SALA DE LUBRIFICAÇÃO DO MOINHO DE BOLAS 02 COM EXCESSIVA QUANTIDADE DE ÓLEO DERRAMADO COM RISCO DE QUEDA.', N'SANAR CONDIÇÕES INSEGURAS NA SALA REFERENTES A PISO ESCORREGADIO', N'10362', N'01 - Imagens/01 - Antes/10981.jpeg', N'SALA DE LUBRIFICAÇÃO DO MOINHO DE BOLAS 02 COM EXCESSIVA QUANTIDADE DE ÓLEO DERRAMADO COM RISCO DE QUEDA.', N'01 - Imagens/02 - Depois/10981.jpeg', N'FOI REALIZADA LIMPEZA DO PISO, PAREDE E TETO, TROCADAS AS MANTAS DE CONTENÇÃO, SANADO VAZAMENTO DE ÓLEO, IDENTIFICADO MATERIAIS.', NULL, N'META ALCANÇADA COM A ÁREA LIMPA E INSENTA DE RISCO DE QUEDA DE MESMO NIVEL E NIVEL DIFERENTE', N'SEGURANÇA', 0, NULL, N'Confeccionado com materiais sobressalentes um suporte de calços de rodas de caminhonete, instalado em local de facil acesso, na lateral da carroceria', '2026-06-29T00:00:00.000', '2026-06-30T17:57:57.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (10982, N'533528', N'533528', N'Plataforma Gamificada - Finanças Legends - Copa 2026', 1, N'Others/Outros', N'A equipe de Governança de Contratos possuía poucas iniciativas estruturadas para integração entre os colaboradores, resultando em oportunidades limitadas para conhecer competências, experiências, conquistas pessoais e profissionais dos colegas. Além disso, não existiam mecanismos de gamificação que incentivassem a participação, colaboração e engajamento de forma contínua.', N'Aumentar o engajamento, a interação e o conhecimento entre os integrantes da Governança de Contratos por meio de uma plataforma gamificada de missões, ranking e álbum de figurinhas digitais.', N'10078', N'01 - Imagens/01 - Antes/10982.jpeg', N'A equipe de Governança de Contratos não possuía uma ferramenta estruturada para promover integração, reconhecimento e interação entre os colaboradores. O conhecimento sobre os colegas estava restrito às atividades do dia a dia, dificultando a identificação de competências, experiências e interesses em comum.
INSERT INTO #PVC VALUES (10983, N'81054422', N'81054422', N'Visão de Estratégia de Congelamento de Planos da GP2026', NULL, N'Others/Outros', N'Dificuldade na estruturação do processo de congelamento de planos da GP2026 em virtude da grande quantidade de informações.', N'Permitir uma definição ágil e clara dos congelamentos de planos de manutenção durante a GP2026', N'10081', N'01 - Imagens/01 - Antes/10983.jpeg', N'Sem visão clara da estratégia para congelamento dos planos, sendo necessárias várias manipulações com diversos dados.', N'01 - Imagens/02 - Depois/10983.jpeg', N'Visão clara, montada a partir de código VBA, trazendo todas as informações necessárias de quais planos devem ser congelados e quando.', NULL, N'A meta foi alcançada, pois a ferramenta permite a definição ágil e clara dos congelamentos de planos de manutenção durante a GP2026 através de uma visão simples e cronograma com as datas para execução do congelamento.', N'Aprofundamento na ferramenta VBA.', 0, NULL, NULL, '2026-06-29T00:00:00.000', '2026-06-30T20:21:31.000', N'81054422', NULL, NULL);
INSERT INTO #PVC VALUES (10984, N'187864', N'187864', N'Estabelecimento de Faixas Críticas de Qualidade de Energia para Acionamento de Ações Preventivas', 1, N'Projects/Projetos', N'O sistema MHT realiza o monitoramento da qualidade de energia das escavadeiras elétricas de grande porte por meio da coleta contínua de parâmetros elétricos críticos. Entretanto, a ausência de limites máximos e mínimos tecnicamente definidos para os disparos de alarmes reduz a efetividade do monitoramento, gerando alarmes excessivos ou pouco representativos. Essa condição compromete a confiabilidade das análises, aumenta o tempo de diagnóstico das equipes de manutenção e eleva o risco de falhas em componentes elétricos críticos. O projeto busca estabelecer critérios padronizados de monitoramento e alarmística, aumentando a assertividade das decisões de manutenção e a confiabilidade operacional dos ativos.', N'Definição e aplicação das grandezas elétricas para o monitoramento assertivo, conforme boas práticas de monitoramento preditivo.', N'10015', N'01 - Imagens/01 - Antes/10984.jpeg', N'Não existia alarmes isso provocava, leituras continuas com inúmeros eventos estatísticos, sem uma metodologia padronizada baseada no comportamento histórico dos ativos.
INSERT INTO #PVC VALUES (10985, N'81037114', N'540124', N'Engate rápido para abastecimento ', NULL, N'Projects/Projetos', N'No fluxo anterior, era necessário realizar a desenrosca do niple para viabilizar o abastecimento do equipamento, gerando retrabalho e impactando diretamente no aumento de maquina parada.', N'Redução de tempo ', N'10144', N'01 - Imagens/01 - Antes/10985.jpeg', N'No fluxo anterior, era necessário realizar a desenrosca do niple para viabilizar o abastecimento do equipamento, gerando retrabalho e impactando diretamente no aumento de maquina parada.', N'01 - Imagens/02 - Depois/10985.jpeg', N'Depois foi implementado um engate rápido para abastecer o equipamento diminuindo assim o tempo que era gasto para abastecer. ', NULL, N'Sim', N'Sentimento de dono ', 0, NULL, N'Agilidade na definição do resultado final da análise.', '2026-06-24T00:00:00.000', '2026-06-30T21:43:35.000', N'81037114', NULL, NULL);
INSERT INTO #PVC VALUES (10986, N'81015244', N'81015244', N'OTIMIZAÇÃO DE PREVENTIVA 250h', 1, N'Open Pit/Poço aberto', N'SUBSTITUIÇÃO DE FILTROS DIESEL COM 250h TRABALHADAS SEM A AVALIAÇÃO REAL DO LIMITE DE CONTAMINAÇÃO.', N'REDUZIR TEMPO/CUSTO DE PREVENTIVA DE 250h', N'#N/A', N'01 - Imagens/01 - Antes/10986.jpeg', N'FILTROS DE DIESEL ERAM SUBSTITUÍDOS COM A FREQUÊNCIA DE 250h, MAS SEM A AVALIAÇÃO REAL DO LIMITE DE CONTAMINAÇÃO.', N'01 - Imagens/02 - Depois/10986.jpeg', N'COM A UTILIZAÇÃO DO DIESEL S10 PREMIUM FOI REALIZADO A EXTENSÃO DA VIDA DO FILTRO DE 250h PARA 500h. NÃO HOUVE PARADAS POR BAIXO RENDIMENTO OU EVENTOS DE OBSTRUÇÃO DE FILTRO.', NULL, N'A OTIMIZAÇÃO FOI ALCANÇADA E SERÁ PADRÃO NA FROTA.', N'Otimização de atividades e custos', 3, 1, N'Melhora no controle de amostras não coletadas, auxiliando a enxergar os desafios operacionais da atividade de campo. Banco de dados com mais informação do ocorrido em campo.', '2026-06-30T00:00:00.000', '2026-06-30T22:22:42.000', N'81015244', NULL, NULL);
INSERT INTO #PVC VALUES (10987, N'483318', N'483318', N'Simulador de consumo de explosivo em planilha de excel', 1, N'Others/Outros', N'Não havia medida de atendimento a demanda de massa detonada a partir do consumo necessário de explosivo.', N'Avaliar capacidade de geração de massa desmontada para atender a lavra das escavadeiras da mina do Salobo, dentro do ciclo orçamentario.', N'10323', N'01 - Imagens/01 - Antes/10987.jpeg', N'Não havia formula para calculo da massa desmontada, a partir do consumo necessário de explosivos (fabricação e aplicação).', N'01 - Imagens/02 - Depois/10987.jpeg', N'Criado em excel, o raciocínio logico entre massa desmontada e razão de carga aplicada com base em cada tipo de material especifico a ser desmontado - minério ( alto, médio e baixo teor) e estéril (rocha fresca, saprolítico e semi-intemperizado) e malha de perfuração classificada pelo diâmetro do furo.
INSERT INTO #PVC VALUES (10988, N'81004893', N'81004893', N'Controle de Utilização de Horas Ociosas e Horas Produtivas da Infraestrutura', 1, N'Others/Outros', N'Ausência de um controle estruturado para acompanhamento das horas ociosas e produtivas da equipe de infraestrutura, dificultando a análise da utilização dos recursos e a identificação de oportunidades de melhoria.', N'Implementar um controle de horas que permita monitorar a utilização dos recursos da infraestrutura, reduzindo a ociosidade e aumentando a produtividade das atividades executadas.', N'10015', N'01 - Imagens/01 - Antes/10988.jpeg', N'Não existia uma ferramenta ou processo padronizado para registrar e acompanhar horas ociosas e horas produtivas, limitando a visibilidade da performance da equipe.', N'01 - Imagens/02 - Depois/10988.jpeg', N'Foi implantado um controle estruturado com indicadores de utilização, permitindo monitorar horas produtivas e ociosas, apoiar a tomada de decisão e otimizar perfomance', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/dd8de810-0a6e-41ce-9ea7-74c7aa078d85/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'Foi desenvolvido um controle consolidado para registro e acompanhamento das horas produtivas e ociosas da infraestrutura, com indicadores e visualização gerencial que permitem monitorar a utilização dos recursos, identificar desvios e direcionar ações de melhoria contínua.', N'A disponibilização de dados confiáveis sobre utilização dos recursos possibilita identificar gargalos, direcionar ações de melhoria e aumentar a eficiência operacional.', 0, NULL, N'Na', '2026-06-19T00:00:00.000', '2026-06-30T23:29:37.000', N'81004893', NULL, NULL);
INSERT INTO #PVC VALUES (10989, N'478853', N'478853', N'BIOMBO DE SOLDA', 2, N'Others/Outros', N'FALTA DE SEGREGAÇÃO ENTRE ATIVIDADES DE SOLDA NO INTERIOR DA CALDEIRARIA, COM RISCO DE PROJEÇÃO DE LIMALHAS E FAISCAS DE TRABALHO A QUENTE', N'MINIMIZAR RISCOS', N'10023', N'01 - Imagens/01 - Antes/10989.jpeg', N'FALTA DE SEGREGAÇÃO ENTRE ATIVIDADES DE SOLDA NO INTERIOR DA CALDEIRARIA, COM RISCO DE PROJEÇÃO DE LIMALHAS E FAISCAS DE TRABALHO A QUENTE', N'01 - Imagens/02 - Depois/10989.jpeg', N'FOI CONFECCIONADO UM BIOMBOM COM MATERIAIS DISPONIVEIS NA AREA, SOBRESSALENTES DE OUTRAS ATIVIDADES DE TRABALHO A QUENTE', NULL, N'FALTA DE SEGREGAÇÃO ENTRE ATIVIDADES DE SOLDA NO INTERIOR DA CALDEIRARIA, COM RISCO DE PROJEÇÃO DE LIMALHAS E FAISCAS DE TRABALHO A QUENTE', N'MINIMIZAÇAO DE RISCOS', 0, NULL, N'A META FOI ATINGIDA. APÓS A INSTALAÇÃO DO SUPORTE DE ANCORAGEM, O CABO PASSOU A PERMANECER CORRETAMENTE FIXADO, ELIMINANDO O RISCO DE DESPRENDIMENTO OBSERVADO ANTERIORMENTE. A MELHORIA PROPORCIONOU MAIOR SEGURANÇA OPERACIONAL, AUMENTOU A CONFIABILIDADE DO SISTEMA E CONTRIBUIU PARA A REDUÇÃO DE FALHAS E CUSTOS DE MANUTENÇÃO.', '2026-06-10T00:00:00.000', '2026-06-30T23:30:14.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (10990, N'478853', N'478853', N'Book FDS', 3, N'Others/Outros', N'Tempo elevado para identificação e controle parcial de FDS, com risco de demora na tratativa em caso de necessidade de primeiros socorros por sinistros com produtos quimicos', N'Gestao a vista e 5s', N'10234', N'01 - Imagens/01 - Antes/10990.jpeg', N'Tempo elevado para identificação e controle parcial de FDS, com risco de demora na tratativa em caso de necessidade de primeiros socorros por sinistros com produtos quimicos', N'01 - Imagens/02 - Depois/10990.jpeg', N'Elaborado Book de FDS, disponivel em local de facil acesso e com gestao a vista na entrada da ferramentaria', NULL, N'Tempo elevado para identificação e controle parcial de FDS, com risco de demora na tratativa em caso de necessidade de primeiros socorros por sinistros com produtos quimicos', N'padronização e 5s', 0, NULL, N'FOI CONFECCIONADO UMA FERRAMENTA EXPECIFICA PARA ESSA ATIVIDADE, ONDE A REMOÇÃO É FEITA DE FORMA SEGURA E PADRONIZADA, ERGONOMICAMENTE CORRETA. ', '2026-06-11T00:00:00.000', '2026-06-30T23:40:41.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (10991, N'81004893', N'81004893', N'Painel de Gestão de Intervenções de Telemetria', 1, N'Others/Outros', N'A gestão das intervenções originadas pela telemetria e cma eram tratadas em visões distintas realizada de forma descentralizada, dificultando o acompanhamento dos status, a priorização das ações, a identificação de pendências e a mensuração dos resultados.', N'Centralizar e automatizar a gestão das intervenções de telemetria, proporcionando visibilidade das ações, acompanhamento dos indicadores e maior agilidade na tomada de decisão. cma e telemetria', N'10015', N'01 - Imagens/01 - Antes/10991.jpeg', N'As informações de intervenções estavam distribuídas em diferentes fontes e separada cma x telemetria, com acompanhamento manual e baixa visibilidade dos status, responsáveis e evolução das tratativas.', N'01 - Imagens/02 - Depois/10991.jpeg', N'Implantação de um painel integrado que consolida as intervenções de telemetria e cma, permitindo monitoramento em tempo real por status, técnico, frota, ativo, subconjunto e data de coleta.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/06be9e1f-5fb3-4ac0-992c-634bafd795bc/be76a0215018000c25b7?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'Foi desenvolvido um painel de gestão de intervenções de telemetria que consolida automaticamente as informações das tratativas e disponibiliza indicadores operacionais em tempo real. A solução permite acompanhar o ciclo completo das intervenções, monitorar a performance do processo e direcionar esforços para as prioridades da operação.', N'A centralização das informações e a gestão visual aumentam a eficiência do acompanhamento operacional, reduzem o tempo gasto com consolidação de dados e apoiam decisões mais assertivas.', 0, NULL, N'over/under solids can impact other areas of the plant ', '2026-06-10T00:00:00.000', '2026-06-30T23:42:37.000', N'81004893', NULL, NULL);
INSERT INTO #PVC VALUES (10992, N'483318', N'483318', N'Comparativo  de DF entre ciclos Supply Review', 1, N'Others/Outros', N'Havia muita perda de tempo comparando mês a mês a projeção de DF do ciclo anterior com o ciclo atual.', N'Avaliar contribuição de projeções de Disponibilidade fisica dos equipamentos da  mina, nos ciclos de Supply Review', N'10323', N'01 - Imagens/01 - Antes/10992.jpeg', N'Não havia metodologia que comparasse a projeção de DF do ciclo anterior com a nova projeção do ciclo atual. Essa avaliação era feita consumindo muito tempo, devido ser necessário avaliar mês a mês, cada tag de equipamento. ', N'01 - Imagens/02 - Depois/10992.jpeg', N'Criando em excel, comparativo que avalia os dados da nova projeção e compara com os dados do ciclo anterior, gerando saldos e gerando valores em gráficos, separados por tipo de frota.', NULL, N'Problema resolvido.', N'Redução no tempo dedicado a avaliação dos dados', 0, NULL, N'Centralização das informações, maior rastreabilidade, visibilidade em tempo real dos processos', '2026-06-15T00:00:00.000', '2026-06-30T23:46:26.000', N'483318', NULL, NULL);
INSERT INTO #PVC VALUES (10993, N'478853', N'478853', N'Suporte Caixa Termica para Campo', 2, N'Others/Outros', N'Caixa termica de agua potavel disposta no chão/solo, com riscos ergonômicos e de higiene', N'minimizar riscos ergonomicos e de contaminação', N'10234', N'01 - Imagens/01 - Antes/10993.jpeg', N'Caixa termica de agua potavel disposta no chão/solo, com riscos ergonômicos e de higiene', N'01 - Imagens/02 - Depois/10993.jpeg', N'Confeccionado com materiais sobressalentes na area, um suporte para caixa termica, eliminando o contato direto com o solo/chão e minimizando riscos ergonomicos', NULL, N'Caixa termica de agua potavel disposta no chão/solo, com riscos ergonômicos e de higiene', N'Minimização de riscos', 0, NULL, N'Processo digital, integrado, rastreável e monitorado em tempo real, proporcionando mais eficiência, governança e qualidade na gestão das solicitações de estoque.', '2026-06-17T00:00:00.000', '2026-06-30T23:49:18.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (10994, N'478853', N'478853', N'Suporte calco rodas caminhonete', 3, N'Others/Outros', N'Ausencia de local adequado para alocar os calcos de rodas de caminhonetes, ficando soltos na carroceria e  dificultando o manuseio para utilização', N'5s', N'10234', N'01 - Imagens/01 - Antes/10994.jpeg', N'Ausencia de local adequado para alocar os calcos de rodas de caminhonetes, ficando soltos na carroceria e  dificultando o manuseio para utilização', N'01 - Imagens/02 - Depois/10994.jpeg', N'Confeccionado com materiais sobressalentes um suporte de calços de rodas de caminhonete, instalado em local de facil acesso, na lateral da carroceria', NULL, N'Ausencia de local adequado para alocar os calcos de rodas de caminhonetes, ficando soltos na carroceria e  dificultando o manuseio para utilização', N'Padronização e 5s', 0, NULL, N'Aumenta a visibilidade gerencial sobre o avanço e a qualidade dos processos;
INSERT INTO #PVC VALUES (10995, N'81053475', N'81053475', N'Implantação de Matriz Estratégica de Priorização para Otimização dos Ciclos de Estudos de RCM em Equipamentos Móveis', 1, N'Others/Outros', N'Ausência de critério estruturado para definir a sequência de elaboração dos estudos de RCM, dificultando o direcionamento dos recursos para os ativos de maior criticidade.', N'Estabelecer uma metodologia objetiva para priorizar as frotas que devem ser submetidas aos estudos de RCM, maximizando o retorno dos esforços de engenharia.', N'10015', N'01 - Imagens/01 - Antes/10995.jpeg', N'A definição dos ciclos de estudos de RCM era realizada com base em avaliações pontuais e subjetivas, sem uma metodologia padronizada que considerasse a relevância estratégica dos ativos.', N'01 - Imagens/02 - Depois/10995.jpeg', N'As frotas passaram a ser classificadas por meio de uma matriz de priorização baseada em critérios ponderados, permitindo decisões mais transparentes, consistentes e alinhadas às necessidades operacionais da mina.', NULL, N'Foi desenvolvida uma matriz de priorização contemplando critérios como modelo do equipamento, quantidade de ativos, vida média, impacto operacional e prioridade para a mina. Cada critério recebeu um peso específico, gerando um índice de criticidade capaz de classificar as frotas e definir uma sequência estruturada para execução dos estudos de RCM.', N'A utilização de critérios quantitativos e estruturados reduz a subjetividade das decisões e aumenta o alinhamento entre estratégia de manutenção e objetivos do negócio.', 0, NULL, N'A avaliação fica mais realista, pois considera não apenas o impacto técnico da falta do item, mas também a dificuldade de reposição.
INSERT INTO #PVC VALUES (10996, N'81035388', N'498389', N'Implantação de placa de identificação no acesso da Área', 1, N'No Replication/Sem replicação', N'O acesso necessita de melhoria na sinalização de parada obrigatória para reforçar a segurança viária de reduzir o risco de incidentes.', N'Identificação, padronização no acesso, facilitando a orientação e localização das áreas.', N'10257', N'01 - Imagens/01 - Antes/10996.jpeg', N'Não possuía placa de identificação. ', N'01 - Imagens/02 - Depois/10996.jpeg', N'Foi instalada uma placa de identificação no acesso, padronizando a sinalização da área.', NULL, N'A meta foi alcançada com implantação da placa de identificação no acesso. ', N'A identificação adequada dos acessos é essencial para garantir a segurança, facilitar a orientação das equipes e melhorar a eficiência operacional.', 7, 1, N'• Melhor monitoramento do processo
INSERT INTO #PVC VALUES (10997, N'81036958', N'81036958', N'JANELA VISITA TR2009-06', 1, N'Others/Outros', N'AUSENCIA DE ACESSO AO INTERIOR DO CHUTE TR2009-05/2009-06 POR OBSTRUÇÃO DE VIGAS DE TRAVAMENTO INSTALADOS PELA EQUIPE ESTRUTURAL', N'CRIAR ACESSO PARA LIMPEZA E MANUTENÇÃO ', N'10031', N'01 - Imagens/01 - Antes/10997.jpeg', N'JANELAS DE VISITA ANTIGAS FORAM DESCONTINUADAS POR SEREM EXTREMAMENTE FRAGEIS E ESTAREM OBSTRUIDAS POR VIGAS INSTALADAS PELA EQUIPE ESTRUTURAL PARA CONTER DESLOCAMENTO DAS CASAS DE TRANSFERENCIA ', N'01 - Imagens/02 - Depois/10997.jpeg', N'AO  ACESSAR JANELA DE VISITA NOVA E PADRONIZADA AO LOCAL, O ACESSO DE PESSOAS FOI RESTAURADO COM MAIOR SEGURANÇA.', NULL, N'SIM ', N'PADRONIZAÇÃO NOS LEVA AO AMBIENTE MAIS SEGURO ', 0, NULL, N'Disponibilizar um local adequado para armazenamento dos documentos, garantindo melhor organização e controle documental, reduzindo a necessidade de reimpressões e promovendo o uso mais eficiente dos recursos da área.', '2026-06-24T00:00:00.000', '2026-07-01T12:48:38.000', N'81036958', NULL, NULL);
INSERT INTO #PVC VALUES (10998, N'73197', N'73197', N'Simplificação no fluxo de análise do Comitê Pela Vida', 3, N'Others/Outros', N'Nas reuniões do Comitê Pela Vida os fluxos das violações eram feitos através de slides do Power Point, alterando cores e criando ou "arrastando" figuras manualmente para seguir um fluxo de análise. Este processo é moroso e improdutivo.', N'Reduzir o tempo de análise e melhorando a visualização  do fluxo definido', N'10337', N'01 - Imagens/01 - Antes/10998.jpeg', N'Nas reuniões do Comitê Pela Vida os fluxos das violações eram feitos através de slides do Power Point, alterando cores e criando ou "arrastando" figuras manualmente para seguir um fluxo de análise. Este processo é moroso e improdutivo.', N'01 - Imagens/02 - Depois/10998.jpeg', N'Fluxo gerado através de planilha automatizada com a sequência definida de acordo com as respostas de cada quadro, destacando as células que seguirão sendo analisadas até o apontamento da conclusão final.', NULL, N'Agilidade na definição do resultado final da análise.', N'Melhoria simples de processo manual', 0, NULL, N'Clarify the traffic plan in the paste plant.  Congested area to begin with.  ', '2026-06-26T00:00:00.000', '2026-07-01T14:40:24.000', N'73197', NULL, NULL);
INSERT INTO #PVC VALUES (10999, N'81054397', N'81022808', N'Controle no cadastramento de furos executados (FE) e amostras controle QAQC.', 1, N'No Replication/Sem replicação', N'Devido à dinâmica operacional, por vezes os furos eram executados sem devida identificação dos motivos de não amostragem, e as amostras de controle eram anotadas na mão. Como consequência, gerava dúvidas de informações, resultando em inconsistências no controle dos dados (furos perfurados Vs. furos amostrados). ', N'Cadastrar a informação diretamente no arquivo da coletora (GPS)', N'10162', N'01 - Imagens/01 - Antes/10999.jpeg', N'Devido à dinâmica operacional, por vezes os furos eram executados sem a devida identificação dos motivos de não amostragem, e as amostras de controle eram anotadas na mão. Como consequência, gerava dúvidas de informações, resultando em inconsistências no controle dos dados (furos perfurados Vs. furos amostrados). ', N'01 - Imagens/02 - Depois/10999.jpeg', N'A informação fica registrada diretamente no banco de dados, podendo ser visualizada no controle via Power BI, também ajuda a justificar a performance da amostragem.
INSERT INTO #PVC VALUES (11000, N'81044914', N'81044914', N'Locação incorreta de container SLB', 1, N'Others/Outros', N'Após o carve out, alguns containers de ssg estavam locados de maneira indevida em SLB', N'Redução do custo de locação em SLB', N'10222', N'01 - Imagens/01 - Antes/11000.jpeg', N'Durante a gestão de custos, foram verificados custos muito altos com containers na área de PCM, após avaliação cuidadosa, foi constatado que haviam locações de SSG em SLB, provavelmente após a separação das operações de negócio', N'01 - Imagens/02 - Depois/11000.jpeg', N'Comunicação com a área e compensação dos valores em outras aquisições da área', NULL, N'Após revisão, os valores foram levantados para a devida locação na operação correta conforme email de alinhamento', N'Controle de custo, verificação rotineira', 68511, 1, N'Thanks to reducing water , we could reduce 173KWH every years.', '2025-11-06T00:00:00.000', '2026-07-01T16:40:00.000', N'81044914', NULL, NULL);
INSERT INTO #PVC VALUES (11001, N'1010861', N'1010861', N'Filter Press Shifter Mod.', 1, N'No Replication/Sem replicação', N'Shifters of 306-FLP-003 were to tight to lock on plate grab bars.', N'Reliability of filter press plate shifter operation.', N'0', N'01 - Imagens/01 - Antes/11001.jpeg', N'Plate shifters for 306-FLP-003 were fabricated by contractor. When fab was complete shifter component fitment was to tight causing plates to be missed and jammed while washing filter press.', N'01 - Imagens/02 - Depois/11001.jpeg', N'Troubleshooting shifter locks to be to tight to lock on to the plate grab bars causing jam up in the wash process. Solution was to remove material from locking tabs on the shifter to open space for grab bars to lock in place. This process saved extended time washing and troubleshooting jamming issues.', N'https://apps.powerapps.com', N'Problem solved for this issue with fitment.', N'Shifters that come in with fitment issues can be made fit correctly.', 1000, 3, N'Thanks to the expansion of the floor area, we were able to reduce the risk of injury.', '2026-06-30T00:00:00.000', '2026-07-01T17:27:19.000', N'1010861', NULL, NULL);
INSERT INTO #PVC VALUES (11002, N'539450', N'539450', N'SUPORTE FIXAÇÃO DO CABO DE ANCORAGEM DA BÁSCULA ', 2, N'Open Pit/Poço aberto', N'Foi identificado que o cabo de ancoragem encontrava-se sem fixação, permanecendo solto nos equipamentos durante a liberação para operação. Observou-se que o equipamento operava nessa condição.', N'GARANTINDO MAIOR SEGURANÇA OPERACIONAL AO EQUIPAMENTO E ÀS PESSOAS. A AÇÃO TAMBÉM CONTRIBUI PARA A REDUÇÃO DE CUSTOS, PREVENINDO FALHAS, DESGASTE PREMATURO E AVARIAS NO CABO.', N'10279', N'01 - Imagens/01 - Antes/11002.jpeg', N'FOI IDENTIFICADO QUE O CABO DE ANCORAGEM ESTAVA SEM FIXAÇÃO, PERMANECENDO SOLTO NOS EQUIPAMENTOS DURANTE A LIBERAÇÃO PARA OPERAÇÃO. VERIFICOU-SE QUE O EQUIPAMENTO OPERAVA NESSAS CONDIÇÕES, RESULTANDO NA DANIFICAÇÃO DO CABO DE ANCORAGEM DA BÁSCULA. ', N'01 - Imagens/02 - Depois/11002.jpeg', N'FOI INSTALADO O SUPORTE DE ANCORAGEM DO CABO DA BÁSCULA, GARANTINDO A CORRETA FIXAÇÃO E O POSICIONAMENTO DO CABO DE AÇO DURANTE A OPERAÇÃO. ANTES DA LIBERAÇÃO DO EQUIPAMENTO, FOI CONFIRMADA A FIXAÇÃO ADEQUADA DO CABO AO SUPORTE, ASSEGURANDO MAIOR SEGURANÇA OPERACIONAL, REDUZINDO O RISCO DE FALHAS E AUMENTANDO A CONFIABILIDADE DO SISTEMA. A MELHORIA TAMBÉM CONTRIBUI PARA A REDUÇÃO DOS CUSTOS DE MANUTENÇÃO, EVITANDO DESGASTES E AVARIAS PREMATURAS NO CABO E EM SEUS COMPONENTES.', NULL, N'GARANTIR 100% DA FIXAÇÃO SEGURA DO CABO DA BÁSCULA POR MEIO DA INSTALAÇÃO DO SUPORTE DE ANCORAGEM, ELIMINANDO O RISCO DE DESPRENDIMENTO E AUMENTANDO A CONFIABILIDADE E A SEGURANÇA OPERACIONAL.', N' A INSTALAÇÃO DO SUPORTE DE ANCORAGEM GARANTE A FIXAÇÃO CORRETA DO CABO DA BÁSCULA, REDUZINDO O RISCO DE DESPRENDIMENTO E FALHAS DURANTE A OPERAÇÃO.  A PADRONIZAÇÃO DO SISTEMA DE ANCORAGEM AUMENTA A SEGURANÇA DOS OPERADORES E A CONFIABILIDADE DO EQUIPAMENTO.  AÇÕES PREVENTIVAS E MELHORIAS SIMPLES CONTRIBUEM PARA A REDUÇÃO DE CUSTOS COM MANUTENÇÃO, EVITANDO DESGASTE PREMATURO E PARADAS NÃO PROGRAMADAS. A VERIFICAÇÃO DA FIXAÇÃO DO CABO DEVE FAZER PARTE DA INSPEÇÃO ANTES DA LIBERAÇÃO DO EQUIPAMENTO PARA OPERAÇÃO.', 0, NULL, N'Thanks to the scaling up of the piping, the time required for liquid replacement was cut in half.', '2026-07-01T00:00:00.000', '2026-07-02T08:03:47.000', N'539450', NULL, NULL);
INSERT INTO #PVC VALUES (11003, N'553135', N'81047177', N'FERRAMENTA DE REMOÇÃO E INSTALAÇÃO - D6', 2, N'Others/Outros', N'ANTES A REMOÇÃO E INSTALAÇÃO DO EIXO DA TRANSMISSÃO DE D6 ERA FEITA DE FORMA MANUAL E ERGONOMICAMENTE ERRADA. USAVA-SE MARRETAS, SOLDA ... DEIXANDO O EMPREGADO NA LINHA DE FOGO, EXPOSTO AO PERIGO. ', N'TORNAR A ATIVIDADE SEGURA ATÉ 30 DE JUNHO', N'10139', N'01 - Imagens/01 - Antes/11003.jpeg', N'ANTES A REMOÇÃO E INSTALAÇÃO DO EIXO DA TRANSMISSÃO DE D6 ERA FEITA DE FORMA MANUAL E ERGONOMICAMENTE ERRADA. USAVA-SE MARRETAS, SOLDA ... DEIXANDO O EMPREGADO NA LINHA DE FOGO, EXPOSTO AO PERIGO. ', N'01 - Imagens/02 - Depois/11003.jpeg', N'FOI CONFECCIONADO UMA FERRAMENTA EXPECIFICA PARA ESSA ATIVIDADE, ONDE A REMOÇÃO É FEITA DE FORMA SEGURA E PADRONIZADA, ERGONOMICAMENTE CORRETA. ', NULL, N'FOI CONFECCIONADO UMA FERRAMENTA EXPECIFICA PARA ESSA ATIVIDADE, ONDE A REMOÇÃO É FEITA DE FORMA SEGURA E PADRONIZADA, ERGONOMICAMENTE CORRETA. ', N'A VIDA SEMPRE EM PRIMEIRO LUGAR ', 0, NULL, N' leading to optimized product quality and overall quality improvement.', '2026-06-25T00:00:00.000', '2026-07-02T09:29:29.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11004, N'1008574', N'1008574', N'improved CCD wash control', 1, N'Refining/Refino', N'when using water to supplement wash soltiuon for the CCD''s the flow meter was very erratic and displaying +/- 20 m3. ', N'reduce variability in set point ', N'0', N'01 - Imagens/01 - Antes/11004.jpeg', N'water flow was very erratic resulting in inaccurate CCD wash setpoint. This can result in over or under washing the CCD solids causing Ni lose or production downtime ', N'01 - Imagens/02 - Depois/11004.jpeg', N'PPTS would control from valve next to flow meter which caused a lot of turbulence. That valve has been green locked open and tagged to notify PPTs to use the valve further downstream  ', NULL, N'yes', N'field walk issues ', 1000, 3, N'Centralização das principais informações da Gerência Geral em um único portal, facilitando o acesso, a comunicação e a integração entre as equipes', '2026-07-01T00:00:00.000', '2026-07-02T09:58:26.000', N'1008574', NULL, NULL);
INSERT INTO #PVC VALUES (11005, N'81014495', N'81014495', N'BI Homologação de Fornecedores (CH_Master)', 1, N'Others/Outros', N'Com a migração do sistema de gerenciamento de materiais do Klassmatt para o CH_Master, o site deixou de contar com uma base única para o acompanhamento dos processos de homologação de materiais. A base anteriormente utilizada estava integrada aos dados do sistema descontinuado, tornando-se indisponível após a transição, o que impactou a rastreabilidade e a gestão centralizada dessas homologações.', N'Criar uma ferramenta única para acompanhamento dos processos de homologação de materiais no site de Sossego', N'10081', N'01 - Imagens/01 - Antes/11005.jpeg', N'A substituição do Klassmatt pelo CH_Master resultou na perda da base única de acompanhamento dos processos de homologação de materiais no site, uma vez que a solução anterior era dependente dos dados do sistema descontinuado. Como consequência, houve uma redução na visibilidade e centralização das informações relacionadas às homologações.', N'01 - Imagens/02 - Depois/11005.jpeg', N'Criei um relatório único em Power BI para acompanhamento dos processos de homologação de materiais do site de Sossego, utilizando os dados do CH_Master como fonte oficial. A solução proporcionará centralização das informações, maior rastreabilidade, visibilidade em tempo real dos processos, redução de controles manuais, melhoria na qualidade dos dados e suporte à tomada de decisão baseada em indicadores confiáveis.', NULL, N'Sim, o problema foi resolvido.', N'Sempre prezar por um sistema de gerenciamento visual e prático que auxilie nas tomadas de decisão', 0, NULL, N'Redução a zero do perigo de escorregões  na rampa através da adequação com material antiderrapante.', '2026-07-01T00:00:00.000', '2026-07-02T10:53:56.000', N'81014495', NULL, NULL);
INSERT INTO #PVC VALUES (11006, N'81030963', N'81044230', N'Gestão e Governança de Solicitações de Estoque', 1, N'Others/Outros', N'Este Kaizen transformou um processo manual, descentralizado e com baixa visibilidade em uma solução digital integrada e governada. Antes, as solicitações de estoque eram controladas por e-mails e planilhas, gerando retrabalho, dificuldades de acompanhamento, duplicidade de demandas e falta de rastreabilidade.', N'Eliminar controles Manuais ', N'10079', N'01 - Imagens/01 - Antes/11006.jpeg', N'o processo de solicitação de materiais de estoque era realizado por meio de e-mails, planilhas e controles individuais. As informações ficavam dispersas em diferentes fontes, dificultando o acompanhamento das demandas e a visualização do status das solicitações.
INSERT INTO #PVC VALUES (11007, N'81014495', N'81014495', N'Ferramenta de Avaliação de Maturidade  de Processos de Homologação Sossego', 1, N'Others/Outros', N'Sem avaliação de maturidade, a operação perde controle sobre a qualidade, rastreabilidade e evolução dos processos técnicos, aumentando o risco de decisões subjetivas, atrasos, falhas de compliance e exposição operacional. ', N'Estabelecer o acompanhamento mensal da maturidade dos processos ativos de desenvolvimento técnico (SAT, PT, IN e Desomologação, em escala de 0 a 100 pontos, com base em seis dimensões críticas.', N'10081', N'01 - Imagens/01 - Antes/11007.jpeg', N'Sem avaliação de maturidade, a operação perde controle sobre a qualidade, rastreabilidade e evolução dos processos técnicos, aumentando o risco de decisões subjetivas, atrasos, falhas de compliance e exposição operacional. O IMD funciona como uma régua objetiva para transformar processos dispersos em uma carteira governada, mensurável e passível de melhoria contínua.', N'01 - Imagens/02 - Depois/11007.jpeg', N'A ferramenta de avaliação de maturidade dos processos (IMD) é um modelo de acompanhamento mensal utilizado para medir o nível de organização, controle e aderência dos processos ativos de desenvolvimento técnico, como SAT, PT, IN e Desomologação. Ela permite avaliar, de forma padronizada e objetiva, a maturidade dos processos técnicos ativos, garantindo maior controle, rastreabilidade e governança. ', NULL, N'A ferramenta IMD atende essa meta ao transformar processos dispersos em uma carteira mensurável, estruturada por dimensões críticas como SSMA/Compliance, Planejamento, Execução, Encerramento, Governança e Formalização. ', N'A principal lição aprendida foi que a maturidade dos processos só pode ser gerenciada quando existe critério padronizado, evidência rastreável e rotina de acompanhamento. A criação do IMD mostrou que uma ferramenta simples, objetiva e integrada ao BI permite reduzir subjetividade, dar visibilidade à liderança, identificar gargalos e transformar avaliações em planos de ação concretos.', 0, NULL, N'Great communication and problem solving by my team  ', '2026-06-29T00:00:00.000', '2026-07-02T11:11:15.000', N'81014495', NULL, NULL);
INSERT INTO #PVC VALUES (11008, N'81014495', N'81014495', N'Ferramenta de avaliação de Criticidade de Sobressalentes MRO Sossego', 1, N'Others/Outros', N'A operação possuía dificuldade em classificar sobressalentes de forma padronizada, principalmente quando a análise considerava apenas o impacto operacional do item no ativo. Isso podia ', N'Criar uma metodologia objetiva para classificar os sobressalentes em GOP, Crítico ou Normal, considerando não apenas a função do item e a criticidade do ativo, mas também fatores de risco de suprimento, como lead time de aquisição e custo do material.', N'10081', N'01 - Imagens/01 - Antes/11008.jpeg', N'A operação possuía dificuldade em classificar sobressalentes de forma padronizada, principalmente quando a análise considerava apenas o impacto operacional do item no ativo. Isso podia gerar classificações subjetivas, excesso ou falta de estoque, baixa rastreabilidade na decisão e risco de tratar itens de alto impacto logístico ou financeiro como materiais comuns.', N'01 - Imagens/02 - Depois/11008.jpeg', N'A ferramenta de avaliação de criticidade de sobressalentes evoluiu a classificação dos materiais ao combinar impacto operacional com risco de suprimento. A inclusão dos fatores lead time e custo tornou a análise mais robusta, permitindo identificar itens que exigem maior proteção de estoque, contratos, homologação ou plano de contingência. ', NULL, N'A ferramenta atende à meta ao estruturar a avaliação em duas etapas: primeiro, identifica a criticidade operacional do sobressalente com base no ativo e na função do item; depois, aplica uma matriz complementar de risco de suprimento, cruzando lead time e custo para validar ou ajustar a classificação final.', N'A criticidade não deve ser avaliada apenas pelo impacto operacional; Custo elevado exige equilíbrio entre segurança de estoque e capital empatado;   Lead time longo aumenta a exposição operacional.', 0, NULL, N'Eliminação do risco de obstrução da linha de alimentação.
INSERT INTO #PVC VALUES (11009, N'503339', N'503339', N'Habilitar animação do Extrator EX-2009-05', 1, N'Others/Outros', N'Indisponibilidade do Extrator de sucatas sobre o Transportador TR-2009-01', N'Inserido na tela principal da Estocagem Secundária um Pop-up que vai abrir o detalhamento do extrator mostrando sua condição', N'10151', N'01 - Imagens/01 - Antes/11009.jpeg', N'Habilitar animação do Extrator EX-2009-05 sobre o transportador TR-2009-01.
INSERT INTO #PVC VALUES (11010, N'81012099', N'473599', N'Implantação de quadro de gestão documental da área', 3, N'Others/Outros', N'Foi identificada dificuldade na localização e controle dos documentos utilizados diariamente nas atividades operacionais, devido à ausência de um sistema visual padronizado para armazenamento e consulta.', N'Disponibilizar os documentos da área de forma organizada, padronizada e de fácil acesso por meio da implantação de um quadro de gestão documental, garantindo maior agilidade nas consultas e apoio às atividades operacionais.', N'10245', N'01 - Imagens/01 - Antes/11010.jpeg', N'A ausência de um local adequado para armazenamento de documentos tem gerado reimpressões recorrentes, resultando em aumento de custos, desperdício de recursos e dificuldades no controle e organização documental da área.', N'01 - Imagens/02 - Depois/11010.jpeg', N'Com a implantação do quadro, houve uma melhoria na organização dos documentos, reduzindo o extravio de papéis e eliminando a necessidade de reimpressões, o que contribuiu para a diminuição do consumo desnecessário de papel.
INSERT INTO #PVC VALUES (11011, N'81032895', N'81032895', N'Traffic Plan Road Sign', 2, N'Open Pit/Poço aberto', N'No road sign letting motorists know that this road is a one way street.  There is a sign on one side of the road letting drivers know but no sign letting drivers know do not enter. ', N'To align more with traffic plan. ', N'10101', N'01 - Imagens/01 - Antes/11011.jpeg', N'No signs letting vehicles know to "DO NOT ENTER". ', N'01 - Imagens/02 - Depois/11011.jpeg', N'DO NOT ENTER sign to align with traffic plan and to let motorist know not to enter. ', NULL, N'Yes, added signs to show the traffic plan from the parking lot. ', N'To align better with traffic plan. ', 0, NULL, N'eliminação do risco de queda de pessoas', '2026-07-01T00:00:00.000', '2026-07-02T14:25:19.000', N'81032895', NULL, NULL);
INSERT INTO #PVC VALUES (11012, N'81043245', N'81043245', N'Padronização da gestão visual com instalação de placas do passo a passo operacional dos Filtros 2551-FL-01 e 2551-FL-02', 1, N'Others/Outros', N'As instruções do passo a passo de operação dos filtros 2551-FL-01 e 2551-FL-02 eram disponibilizadas por meio de folhas impressas e plastificadas, com tamanho reduzido, menor visibilidade e suscetíveis ao desgaste, dificultando a leitura, a limpeza e a consulta durante as atividades operacionais.', N'Maior visibilidade e legibilidade das instruções operacionais', N'10054', N'01 - Imagens/01 - Antes/11012.jpeg', N'As instruções do passo a passo de operação dos filtros 2551-FL-01 e 2551-FL-02 eram disponibilizadas por meio de folhas impressas e plastificadas, com tamanho reduzido, menor visibilidade e suscetíveis ao desgaste, dificultando a leitura, a limpeza e a consulta durante as atividades operacionais.', N'01 - Imagens/02 - Depois/11012.jpeg', N'Foram confeccionadas e instaladas placas de sinalização em tamanho ampliado para os filtros 2551-FL-01 e 2551-FL-02, contendo o passo a passo da operação e a posição das válvulas em cada etapa do processo. A melhoria substituiu as folhas plastificadas por um material mais resistente, padronizado e de melhor visualização.
INSERT INTO #PVC VALUES (11013, N'87000312', N'87000326', N'To reduce washing water for gas sampler of the No2RT', 1, N'Refining/Refino', N' A constant flow of wash water was maintained for the 2RT gas sampler; however, this water would evaporate, be recovered at the AP, and subsequently be routed to the wastewater treatment system.', N'To reduce waste acid from 2AP.', N'0', N'01 - Imagens/01 - Antes/11013.jpeg', N'A constant flow of wash water was maintained for the 2RT gas sampler; however, this water would evaporate, be recovered at the AP, and subsequently be routed to the wastewater treatment system.', N'01 - Imagens/02 - Depois/11013.jpeg', N'Its installation reduced the volume of wastewater requiring treatment, leading to energy and resource savings.', NULL, N'Yes, we could achieve the target as we thought.', N'asset', 0, NULL, N'Tracker has improved on accountability, visibility, and follow-through on key initiatives.', '2026-07-01T00:00:00.000', '2026-07-03T07:14:56.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11014, N'87000312', N'87000377', N'Extend intermediate 7th floor of No2RT', 2, N'Refining/Refino', N'The intermediate 7F floor area was cramped, creating a risk of dropping tools or other items while working.', N'To reduce injury risk.', N'0', N'01 - Imagens/01 - Antes/11014.jpeg', N'The intermediate 7F floor area was cramped, creating a risk of dropping tools or other items while working.', N'01 - Imagens/02 - Depois/11014.jpeg', N'The intermediate 7th-floor area was expanded, reducing the risk of falling parts.', NULL, N'Yes, we could achieve the target as we thought.', N'asset', 0, NULL, N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', '2026-07-01T00:00:00.000', '2026-07-03T07:23:41.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11015, N'87000312', N'87000319', N'Installation piping for dilution water at the acid leakage pit in Acid shopping area.', 1, N'Refining/Refino', N'The water supply piping for the acid leakage pit was narrow, so replacing the liquid took a long time.', N'To increase water supply at the leak acid pit there. ', N'0', N'01 - Imagens/01 - Antes/11015.jpeg', N'The water supply piping for the acid leakage pit was narrow, so replacing the liquid took a long time.', N'01 - Imagens/02 - Depois/11015.jpeg', N'Increasing the diameter of the water supply piping reduced the time required to replace the liquid in the pit.', NULL, N'Yes, we could achieve the target as we thought.
INSERT INTO #PVC VALUES (11016, N'87000312', N'87000460', N'Movie timer switch for BQ tumbling machine', 1, N'Refining/Refino', N'The switch on the BQ tumbling machine is located immediately next to the timer dial used to set the rotation speed; consequently, there is a risk of accidentally bumping the dial and altering the timer setting when operating the switch, potentially leading to an incorrect powdering rate measurement.', N'Prevention of timer value fluctuations caused by switch movement in the BQ tumbling machine.', N'0', N'01 - Imagens/01 - Antes/11016.jpeg', N'The switch on the BQ tumbling machine is located next to the timer dial; consequently, there is a risk of accidentally bumping the dial and altering the timer setting.', N'01 - Imagens/02 - Depois/11016.jpeg', N'The position of the timer dial was changed. This allowed the rotational speed to be maintained within the appropriate range.', NULL, N'Yes, we could achieve the target as we thought.', N'asset', 0, NULL, N'Redução da emissão de particulados e radiação.', '2026-07-02T00:00:00.000', '2026-07-03T07:42:05.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11017, N'81048240', N'81048240', N'Portal Integrado da Gerência Geral de Finanças Empresariais de Salobo', 1, N'Others/Outros', N'As informações da Gerência Geral de Finanças Empresariais encontravam-se dispersas em diferentes sites, e-mails e pastas, dificultando o acesso rápido ao organograma, aos portais das gerências, às informações de VPS e ao conhecimento das equipes. Essa descentralização gerava perda de tempo na busca por informações e menor integração entre as áreas.', N'Promover a gestão visual e a transparência da Gerência Geral de Finanças Empresariais, consolidando informações estratégicas da área em um portal de fácil acesso alinhado aos princípios do VPS', N'10367', N'01 - Imagens/01 - Antes/11017.jpeg', N'As informações da Gerência Geral de Finanças Empresariais estavam distribuídas em diferentes sites, pastas, e-mails e equipes, sem um ponto único de consulta. A localização de informações como organograma, responsáveis, portais das gerências, representantes de VPS e materiais institucionais dependia do conhecimento individual das pessoas ou de consultas frequentes a colegas. Isso gerava maior tempo de busca, dificuldade de integração entre as áreas e menor visibilidade da estrutura organizacional.', N'01 - Imagens/02 - Depois/11017.jpeg', N'Solução Implementada
INSERT INTO #PVC VALUES (11018, N'81012700', N'543301', N'Rampa de saída do refeitório', 2, N'Others/Outros', N'Identificamos risco de acidente de trabalho na saída do refeitório do escritório de campo devido á falta de aderência no piso da rampa. A ausência de sinalização e de material antiderrapante compromete a segurança na circulação dos colaboradores ao sair do restaurante.', N'mitigar 100% a segurança dos colaboradores ao sair do refeitório, eliminar o risco de escorregamento  ou queda, tornando a saída do restaurante mais segura. ', N'10257', N'01 - Imagens/01 - Antes/11018.jpeg', N'Rampa com superfície lisa e sem aderência na saída do refeitório, gerando perigo imediato de quedas e escorregões para os colaboradores durante o fluxo de saída do restaurante.', N'01 - Imagens/02 - Depois/11018.jpeg', N'Instalação de fitas de alta aderência em toda a rampa de saída do refeitório. Garantindo a tração necessária para os colaboradores, eliminando o risco de escorregões e quedas, tornando o fluxo de saída100% seguro.', NULL, N'sim o problema foi totalmente resolvido com a instalação das fitas antiderrapante, garantindo assim atrito e aderência ao piso e eliminando o risco de escorregões na saída do refeitório.', N'Avaliar segurança. Rampas de acessos de colaboradores devem ter revestimento antiderrapante desde o projeto.', 0, NULL, N'Melhoria da gestão visual.
INSERT INTO #PVC VALUES (11019, N'81046430', N'81013286', N'Segurança Hídrica na Britagem Secundária I/II', 2, N'Others/Outros', N'A Britagem Secundária I/II dependia de abastecimento por caminhão-pipa para alimentação do reservatório de água potável, gerando risco de desabastecimento, exposição a cenário RAC-03, maior vulnerabilidade sanitária e custos operacionais com transporte, combustível e manutenção.', N'Eliminar a dependência de abastecimento por caminhão-pipa na Britagem Secundária I/II, garantindo alimentação contínua do reservatório de água potável pela rede mestra, com maior segurança sanitária, redução de riscos operacionais e melhoria da confiabilidade do abastecimento.', N'10017', N'01 - Imagens/01 - Antes/11019.jpeg', N'Antes do Kaizen, a Britagem Secundária I/II apresentava falta de água de forma recorrente, devido à dependência de abastecimento por caminhão-pipa. Essa condição comprometia atividades operacionais, rotinas de higiene, uso de banheiros, copas e processos de limpeza predial.', N'01 - Imagens/02 - Depois/11019.jpeg', N'Após o Kaizen, o reservatório passou a ser abastecido diretamente pela rede mestra de água potável, garantindo maior continuidade operacional, redução do risco de falta de água, eliminação da dependência de caminhão-pipa e melhoria nas condições de higiene, conforto e segurança sanitária.', NULL, N'A meta inicial do Kaizen era eliminar a dependência de abastecimento por caminhão-pipa, garantindo fornecimento contínuo, seguro e confiável de água potável para a Britagem Secundária I/II.
INSERT INTO #PVC VALUES (11020, N'609694', N'609694', N'Pinch point', 2, N'Underground/Subterrâneo', N'When adding self closing gates at 3410 sump 1 - we caused a severe pinch point issue- This was noticed by crew members completing the work', N'Remove pinch point', N'10260', N'01 - Imagens/01 - Antes/11020.jpeg', N'When adding self closing gates to   3410 level sump 1 - we caused a severe pinch point issue.
INSERT INTO #PVC VALUES (11021, N'515962', N'515962', N'Intertravamento entre os moinhos verticais e as bombas da CX 01 Flotação.', 1, N'No Replication/Sem replicação', N'Quando os Moinhos verticais paravam por falha, as bombas da CX 01 (2351-BP-01, 2351-BP-01R e 2351-BP-02) continuavam em operação e mantinham o fluxo de alimentação direcionado ao moinho parado. Esse comportamento gerava risco de obstrução na linha da tubulação e calha.', N'Eliminar condições de obstruções na alimentação dos moinhos.', N'10054', N'01 - Imagens/01 - Antes/11021.jpeg', N'Quando os Moinhos verticais paravam por falha, as bombas da CX 01 (2351-BP-01, 2351-BP-01R e 2351-BP-02) continuavam em operação e mantinham o fluxo de alimentação direcionado ao moinho parado. Esse comportamento gerava risco de obstrução na linha da tubulação e calha.', N'01 - Imagens/02 - Depois/11021.jpeg', N'Foi criado o intertravamento lógico, entre o moinho vertical e as bombas da caixa 01. Quando o moinho parar por falha, após um minuto as bombas que estiverem funcionando irão parar por intertravamento com o moinho que estiver alimentando, assim a 2351-BP-01 irá intertravar com o 2351-MO-01. Há 2351-BP-02 com o 2351-MO-02 e a 2351-BP-01R vai intertravar dependendo da válvula que estiver direcionada para o respectivo moinho selecionado para alimentação. ', NULL, N'Realizado testes e até o momento resultados positivos', N'Realizar melhorias com objetivo de melhorar segurança de pessoas e ativos.', 0, NULL, N'META ATINGIDA ', '2026-07-02T00:00:00.000', '2026-07-03T13:51:45.000', N'515962', NULL, NULL);
INSERT INTO #PVC VALUES (11022, N'510839', N'510839', N'Aprimoramento da Gestão de Vida Útil dos Cabos', 1, N'Others/Outros', N'O controle da vida útil dos cabos da frota 7495 HD/HR utilizava parâmetros limitados para projeção da tonelagem acumulada, reduzindo a assertividade na previsão das datas de troca e dificultando o planejamento antecipado das intervenções de manutenção.', N'Melhorar a precisão da previsão de troca dos cabos, possibilitando planejamento antecipado e maior confiabilidade das ações de manutenção.', N'10234', N'01 - Imagens/01 - Antes/11022.jpeg', N'O dashboard utilizava a movimentação estimada dos últimos 30 dias como principal parâmetro de projeção, reduzindo a precisão das previsões de troca e a previsibilidade do planejamento de manutenção.', N'01 - Imagens/02 - Depois/11022.jpeg', N'O dashboard passou a utilizar média dos últimos 15 dias e projeções de atingimento de 90% e 98% da vida útil, aumentando a precisão das previsões e a assertividade do planejamento de manutenção.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/dc2d6a76-b33a-444d-b65c-f465aceaa07f/ReportSection?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim. A atualização do dashboard incorporou novos parâmetros de análise, incluindo média de movimentação dos últimos 15 dias, projeções de atingimento de 90% e 98% da vida útil e estimativas de troca. Com isso, as previsões passaram a refletir melhor a condição operacional dos equipamentos, aumentando a assertividade do planejamento de manutenção e reduzindo a dependência de análises complementares.', N'A utilização de múltiplos parâmetros operacionais torna as projeções de vida útil mais assertivas, aumentando a confiabilidade dos indicadores e a qualidade do planejamento de manutenção.', 0, NULL, N'Segurança', '2026-07-02T00:00:00.000', '2026-07-03T13:52:08.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11023, N'200500', N'608234', N'Filter Plant Concentrate Tank Covers', 2, N'Concentration/Concentração', N'#1 and #2 concentrate tanks at the filter plant were open to the workroom environment.   Splashing and misting would result in slurry drying and causing dusting conditions in the plant.   ', N'To improve the workroom environment by eliminating  the dusty conditions that exist in the plant.', N'10194', N'01 - Imagens/01 - Antes/11023.jpeg', N'The #1 and #2 Concentrate Tanks at the Filter Plant were open to the workroom environment, allowing slurry splashing and misting to escape the tanks during normal operation. As the airborne slurry dried, it generated dust throughout the area, creating housekeeping, exposure, and maintenance challenges. A key constraint was that the tops of the tanks were located below the floor grating, making it difficult to implement a conventional tank cover while still maintaining access and operability.', N'01 - Imagens/02 - Depois/11023.jpeg', N'To address the dust generation and housekeeping issues associated with the #1 and #2 Concentrate Tanks, tank covers were installed to contain slurry misting and splashing within the tanks and prevent material from escaping into the workroom environment. The project successfully enclosed the tanks despite the challenge of the tank openings being located below the floor grating. Following installation, a noticeable improvement in housekeeping and dust control was observed. Qualitative assessments were conducted using dust collection "coupons" placed near the #2 Tank, which showed no measurable dust accumulation when inspected. Then #1 Tank cover was completed, and the results demonstrate that the enclosure effectively mitigated dust releases while improving overall workplace conditions within the Filter Plant.', NULL, N'Removed the accumulation of dust that was previously created at the #1 and #2 concentrate tanks, which was positive for the workroom environment.', N'controlling dust generation at the source is significantly more effective than managing dust after it has entered the work environment', 0, NULL, N'Cabinet was returned to a functional state.', '2026-03-31T00:00:00.000', '2026-07-03T15:44:36.000', N'200500', NULL, NULL);
INSERT INTO #PVC VALUES (11024, N'81006571', N'81040190', N'PISO AO REDOR DA GRUA FIXA DO SAG', 2, N'Others/Outros', N'Antes ao redor da GRUA LE do SAG estava com ao redor dela danificada ', N'ELIMINAR RISCOS DE PESSOAS ', N'10362', N'01 - Imagens/01 - Antes/11024.jpeg', N'Durante as atividades de manutenção (TROCA DE REVESTIMENTO DO SAG), era necessária a montagem de andaime ao redor da grua devido ao espaçamento entre o piso e a base de fixação da mesma. Essa condição gerava risco de queda de pessoas, exposição a altura e demais perigos associados.', N'01 - Imagens/02 - Depois/11024.jpeg', N'Instalação de um piso fixo ao redor da grua, eliminando o vão e proporcionando uma superfície segura e nivelada para a execução das atividades de troca de revestimento
INSERT INTO #PVC VALUES (11025, N'200500', N'200219', N'Acid Plant Safety Shower Water On-Demand', 2, N'Refining/Refino', N'The Acid Plant’s safety shower system struggled to maintain American National Standards Institute (ANSI) compliant water temperature and supply, especially in winter due to cold incoming water, slow tank reheating, and outdated controls, creating risks of inadequate emergency response', N'Provide 45 minutes of continuous 20°C water to emergency showers, supporting multiple showers simultaneously.', N'10194', N'01 - Imagens/01 - Antes/11025.jpeg', N'The temperature of inlet water that would fill the 1000-gallon tank was at approximately 4°C. 
INSERT INTO #PVC VALUES (11026, N'200500', N'200535', N'Action Plan Tracker', 1, N'Others/Outros', N'Operations and Maintenance Superintendents work on projects continually throughout the year;  wanted a method of tracking the good work that is being completed, and being able to check in as a leadership team at the smelter on what projects are being worked on throughout the complex.', N'Monitor, manage, and drive completion of action items, milestones, deliverables, and savings targets through regular follow-up and accountability routines', N'10194', N'01 - Imagens/01 - Antes/11026.jpeg', N'Operations and Maintenance Superintendents work on projects continually throughout the year;  wanted a method of tracking the good work that is being completed, and being able to check in as a leadership team at the smelter on what projects are being worked on throughout the complex.   There was also no method to monitor, manage, and drive completion of action items, milestones, deliverables, and savings targets through regular follow-up and accountability routines.', N'01 - Imagens/02 - Depois/11026.jpeg', N'At the weekly leadership meeting of the smelter complex, the team reviews action items assigned to each superintendent, and a status update is reported on, discussions on whether assistance is required, discussion on whether a pivot is needed from the original action.', NULL, N'The initial goal was to have a sustainable method of accountability and reporting on the work being completed.  The action plan tracker is providing this to the smelter leadership team.', N'Increase execution discipline and sustain improvement efforts by implementing a tracking system of the work that was assigned and being completed.', 0, NULL, N'ausência de um transporte para movimentar as rodas dos caminhões.', '2026-02-05T00:00:00.000', '2026-07-03T16:43:28.000', N'200500', NULL, NULL);
INSERT INTO #PVC VALUES (11027, N'81007243', N'81048616', N'Suporte da transmissão TT-43', 3, N'Others/Outros', N'A transmissão do TT43 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte.', N'Redução de cenário de risco, ', N'10139', N'01 - Imagens/01 - Antes/11027.jpeg', N'A transmissão do TT43 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte."', N'01 - Imagens/02 - Depois/11027.jpeg', N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', NULL, N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', N'Condição de risco eliminada', 0, NULL, N'Ganho de aproximadamente 20 minutos na atividade por não precisar usar os equipamentos para atendimento a RAC01.', '2026-07-02T00:00:00.000', '2026-07-03T20:23:39.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11028, N'81007243', N'81048616', N'Suporte da transmissão MA52', 3, N'Others/Outros', N'A transmissão do MA52 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte', N'Redução de risco', N'10139', N'01 - Imagens/01 - Antes/11028.jpeg', N'A transmissão do MA52 estava acondicionada sobre paletes de madeira, apresentando risco durante a movimentação com a empilhadeira, devido à falta de fixação adequada do componente. Foi identificado também risco de quebra do palete em função do elevado peso da transmissão, podendo ocasionar queda da carga, danos ao equipamento e acidentes durante o transporte', N'01 - Imagens/02 - Depois/11028.jpeg', N'Para eliminar a condição de risco, foi confeccionado um suporte metálico pelo time da Caldeiraria, garantindo maior estabilidade, segurança na movimentação e acondicionamento adequado do componente.', NULL, N'Sim', N'Acondicionamento adequado ', 0, NULL, N'Reaproveitamento de materiais da caldeiraria que iria para descarte. ', '2026-07-02T00:00:00.000', '2026-07-03T20:28:13.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11029, N'482294', N'483338', N'Tampa da abóboda', 2, N'No Replication/Sem replicação', N'Projeção de particulados e radiação de temperatura nos equipamentos periféricos.', N'Eliminar furos da abóboda desativados', N'10243', N'01 - Imagens/01 - Antes/11029.jpeg', N'Após desativação da lança de emergência de nitrogênio e lança adição de fios, os furos na abóboda do Forno panela para essa atividade ficaram disfuncionais e logo estavam contribuindo para emissão de particulados e radiação de temperatura nos equipamentos periféricos.', N'01 - Imagens/02 - Depois/11029.jpeg', N'Decidimos fabricar duas tampas refratarias. e sanar o problema de projeção de particulados e radiação.', NULL, N'Foi reduzido a emissão de particulados e radiação durante o processo no forno panela.', N'Não ignore pequenos problemas, sempre haja de acordo os valores da Vale.', 0, NULL, N'Melhor condição para instalação da bandeira. Ganho de tempo de aproximadamente 20 minutos para instalação ou remoção. ', '2026-06-28T00:00:00.000', '2026-07-03T22:14:10.000', N'482294', NULL, NULL);
INSERT INTO #PVC VALUES (11030, N'81007243', N'81021635', N'Confecção de mangueiras para drenar oleo do tandem', 3, N'Projects/Projetos', N'O processo de drenagem do óleo SAE 30 nas motoniveladoras modelo 24M apresentava baixa eficiência devido à incompatibilidade entre a capacidade dos carrinhos coletores (70 litros) e o volume total do reservatório (370 litros). Como resultado, a equipe precisava interromper a atividade cerca de cinco vezes para transportar o óleo até a bomba de transferência, realizar o esvaziamento do coletor e retornar ao equipamento. Essas movimentações adicionais aumentavam o tempo de execução da tarefa para aproximadamente 3 horas, impactando diretamente a produtividade, elevando o esforço operacional e ampliando a exposição dos trabalhadores a riscos ergonômicos.', N'Redução do tempo levado na atividade', N'10139', N'01 - Imagens/01 - Antes/11030.jpeg', N'O processo de drenagem do óleo SAE 30 nas motoniveladoras modelo 24M apresentava baixa eficiência devido à incompatibilidade entre a capacidade dos carrinhos coletores (70 litros) e o volume total do reservatório (370 litros). Como resultado, a equipe precisava interromper a atividade cerca de cinco vezes para transportar o óleo até a bomba de transferência, realizar o esvaziamento do coletor e retornar ao equipamento. Essas movimentações adicionais aumentavam o tempo de execução da tarefa para aproximadamente 3 horas, impactando diretamente a produtividade, elevando o esforço operacional e ampliando a exposição dos trabalhadores a riscos ergonômicos.', N'01 - Imagens/02 - Depois/11030.jpeg', N'Para melhorar a eficiência da atividade, foi confeccionada uma mangueira de 20 metros, conectada diretamente ao sistema de drenagem da motoniveladora 24M e à bomba da baia de lubrificação. Com essa solução, o óleo passou a ser drenado diretamente do equipamento para o sistema de armazenamento, eliminando a necessidade de utilizar os carrinhos coletores durante o processo.
INSERT INTO #PVC VALUES (11031, N'81043245', N'81043245', N'Padronização da gestão visual com instalação de placa de identificação das válvulas dos Filtros 2551-FL-01 e 2551-FL-02', 1, N'Others/Outros', N'A identificação das principais válvulas dos filtros dependia do conhecimento dos operadores ou da consulta em documentos, dificultando a localização rápida dos componentes, principalmente durante inspeções e intervenções operacionais.', N'Apoio ao treinamento de novos operadores. Facilidade na identificação e localização das válvulas', N'10054', N'01 - Imagens/01 - Antes/11031.jpeg', N'A identificação das principais válvulas dos filtros dependia do conhecimento dos operadores ou da consulta em documentos, dificultando a localização rápida dos componentes, principalmente durante inspeções e intervenções operacionais.', N'01 - Imagens/02 - Depois/11031.jpeg', N'Foi confeccionada e instalada uma placa de gestão visual contendo a identificação das principais válvulas dos filtros 2551-FL-01 e 2551-FL-02, com ilustração da localização de cada válvula no equipamento, sua nomenclatura, função e correspondência entre os dois filtros.', NULL, N'SIM. A melhoria facilita a identificação dos componentes, agiliza as atividades operacionais', N' identificação rápida e padronizada das válvulas', 0, NULL, N'Maior segurança, preservação do equipamento e redução de riscos.', '2026-07-03T00:00:00.000', '2026-07-04T02:05:14.000', N'81043245', NULL, NULL);
INSERT INTO #PVC VALUES (11032, N'202638', N'202638', N'Reduce vending machines', 3, N'Refining/Refino', N'Vending machines were not fully stocked and were taking up sace', N'cost reduction', N'0', N'01 - Imagens/01 - Antes/11032.jpeg', N'EW had a total of 6 Fastenal vending machines, some were used as asset lockers however none were full', N'01 - Imagens/02 - Depois/11032.jpeg', N'We consolidated all items and were able to reduce our vending machine totals from 6 to 3', NULL, N'Cost reduced as we are not paying for the machines, area freed up', N'5S', 1000, 3, N'Proteger o sensor de nível contra impactos e garantir a continuidade do processo produtivo.', '2026-07-03T00:00:00.000', '2026-07-04T10:07:35.000', N'202638', NULL, NULL);
INSERT INTO #PVC VALUES (11033, N'498359', N'81047016', N'DISPOSITIVOP PARA COMPLETAR O OLEO LUBRIFICANTE', 2, N'Others/Outros', N'Dificuldade na execução em  completar de óleo do tanque do sistema de lubrificação do britador primário, ao virar o tambor de óleo não estando na gravidade correta com isso o óleo não chegava ao tanque, e com os riscos de escorregar na escada, tropeçar, esmagamento de membros.', N'REDUZIR RISCOS ERGONOMICOS', N'10362', N'01 - Imagens/01 - Antes/11033.jpeg', N'Dificuldade na execução em  completar de óleo do tanque do sistema de lubrificação do britador primário, ao virar o tambor de óleo não estando na gravidade correta com isso o óleo não chegava ao tanque, e com os riscos de escorregar na escada, tropeçar, esmagamento de membros.', N'01 - Imagens/02 - Depois/11033.jpeg', N'Foi realizada uma melhoria significativa no britador primário, com foco na eliminação de riscos operacionais e aumento da segurança dos trabalhadores. A intervenção contemplou a readequação do sistema, eliminando o risco de queda durante a execução da atividade, bem como o risco de contaminação do óleo, garantindo maior integridade do processo.
INSERT INTO #PVC VALUES (11034, N'498359', N'81047016', N'JANELA DE VISITA', 2, N'Others/Outros', N'DIFICULDADE NA REMOÇÃO DA PROTEÇÃO PARA PODER ACESSAR O SENSOR DE BAIXA VELOCIDADE', N'REDUZIR EXPOSIÇÃO DE ENERGIA ELETRICA', N'10362', N'01 - Imagens/01 - Antes/11034.jpeg', N'DIFICULDADE NA REMOÇÃO DA PROTEÇÃO PARA PODER ACESSAR O SENSOR DE BAIXA VELOCIDADE', N'01 - Imagens/02 - Depois/11034.jpeg', N'FOI FABRICADO UMA JANELA DE VISITA PARA ACESSAR O SENSOR DE BAIXA VELOCIDADE, COM GANHOS EM ERGONOMIA, PRODUTIDADE, TEMPO, FACILIDADE NA HORA DA MANUTENÇÃO DO SENSOR.', NULL, N'META ATINGIDA ', N'MELHORAR O AMBIENTE DE TRABALHO', 0, NULL, N'Garantia da segurança e melhor otimização do tempo para realização da atividade. ', '2026-07-03T00:00:00.000', '2026-07-04T17:09:48.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (11035, N'81006689', N'81045062', N'Deposito de água de ar condicionado', 3, N'Others/Outros', N'Deposito de água de ar condicionado sem escape para água, ocasionando vazamento e risco de escorregão.', N'eliminar o derramamento de água na área', N'10233', N'01 - Imagens/01 - Antes/11035.jpeg', N'Deposito de água de ar condicionado sem escape para água, ocasionando vazamento e risco de escorregão.', N'01 - Imagens/02 - Depois/11035.jpeg', N'Foi instalado torneira para vasão de água acumulada.', NULL, N'sim, Foi instalado torneira para vasão de água acumulada.', N'sempre observar área de trabalho.', 0, NULL, N'The ability to internal inspect a tank that otherwise would have not been inspected. Overall reducing the risk to workers in the area', '2026-07-03T00:00:00.000', '2026-07-04T19:15:56.000', N'81006689', NULL, NULL);
INSERT INTO #PVC VALUES (11036, N'609342', N'609342', N'3rd Floor Cabinet Repair', 3, N'Refining/Refino', N'The cabinet on 3rd floor was rusting away, and the doors were becoming non-functional.', N'To repair the functionality of the 3rd floor cabinet ', N'10114', N'01 - Imagens/01 - Antes/11036.jpeg', N'The cabinet/workbench was becoming non-functional due to wear and tear. Doors were rusting out and overall appearance was unsatisfactory. ', N'01 - Imagens/02 - Depois/11036.jpeg', N'Doors were fabricated and replaced by Barry and work was cleaned and 5s was brought back to 5s state.', NULL, N'Yes, the cabinet was repaired in house and functionality was returned.  ', N'To repair something, instead of having to buy new', 1000, 3, N'A iniciativa gerou maior governança sobre a programação de férias, reduziu a dependência de controles manuais, melhorou a visibilidade gerencial e possibilitou a identificação preventiva de conflitos de agenda. O app também automatizou comunicações ao gestor e lembretes de aniversário e tempo de empresa. A solução foi replicada para outras equipes, ampliando o alcance para aproximadamente 210 pessoas.', '2026-07-02T00:00:00.000', '2026-07-04T22:56:11.000', N'609342', NULL, NULL);
INSERT INTO #PVC VALUES (11037, N'550548', N'550548', N'Energia para Testar, Agilidade para Manter', 1, N'No Replication/Sem replicação', N'A falta de alimentação dos sensores indutivos e capacitivos durante a manutenção da aranha impedia a realização de testes funcionais antes da remontagem. Caso fosse identificada uma falha após a instalação, era necessária uma nova retirada da aranha, atividade com duração aproximada de 5 horas, gerando retrabalho, aumento do tempo de manutenção e maior indisponibilidade do britador.', N'Permitir a realização de testes funcionais dos sensores indutivos e capacitivos antes da remontagem da aranha, eliminando a necessidade de retrabalho decorrente da identificação tardia de falhas, reduzindo em até 5 horas o tempo de manutenção por ocorrência e aumentando a confiabilidade e a disponibilidade do britador.', N'10245', N'01 - Imagens/01 - Antes/11037.jpeg', N'Sem alimentação elétrica, os sensores da aranha não podiam ser testados durante a manutenção. Falhas eram identificadas somente após a montagem, exigindo nova retirada da aranha e cerca de 5 horas de retrabalho.', N'01 - Imagens/02 - Depois/11037.jpeg', N'Foi desenvolvido um dispositivo portátil para testar sensores no local da manutenção, permitindo validar seu funcionamento antes da montagem, evitando retrabalho e reduzindo até 5 horas por ocorrência.', NULL, N'A meta foi atingida com o desenvolvimento do dispositivo portátil, permitindo testar os sensores antes da remontagem da aranha, eliminando retrabalhos e reduzindo em até 5 horas o tempo de manutenção por ocorrência.', N'A validação dos sensores antes da remontagem aumenta a confiabilidade da manutenção, evita retrabalhos, reduz o tempo de intervenção e evidencia a importância de desenvolver ferramentas simples para solucionar limitações operacionais.', 0, NULL, N'The elimination of the dribble box removed a repetitive manual handling task.', '2026-07-04T00:00:00.000', '2026-07-05T02:52:24.000', N'550548', NULL, NULL);
INSERT INTO #PVC VALUES (11038, N'81033365', N'81048606', N'Suporte do extintor de icendio', 1, N'Others/Outros', N'ausência de local adequado', N'processo de melhorias', N'10139', N'01 - Imagens/01 - Antes/11038.jpeg', N'O extintor estava guardado incorretamente no chão e exposto ao tempo (sol e chuva), o que pode causar corrosão e falha no funcionamento.', N'01 - Imagens/02 - Depois/11038.jpeg', N'O extintor foi retirado do chão e instalado em um suporte adequado para garantir sua conservação e funcionamento seguro.', NULL, N'AUSENCIA DE SUPORTE E DEPOIS FOI FABRICADO SUPORTE.', N'MELHORIA CONTINUA', 0, NULL, N'Os condutores estão respeitando o distanciamento seguro.', '2026-06-29T00:00:00.000', '2026-07-05T09:31:52.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11039, N'81033365', N'81048572', N'Carrinho de transportar roda', 2, N'Others/Outros', N'Ausência de suporte para transportar roda.', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/11039.jpeg', N'Identificado que a Movimentação manual de rodas durante o transporte interno, gerando risco ergonômico e potencial de acidentes por queda de material ou prensagem de membros.', N'01 - Imagens/02 - Depois/11039.jpeg', N'Realizado fabricação e implementação de carrinho ergonômico dedicado para o transporte seguro de rodas, eliminando o manuseio manual e mitigando o risco de acidentes.', NULL, N'ausência de um transporte para movimentar as rodas dos caminhões.', N'melhoria continua', 0, NULL, N'melhorando a ergonomia e aumentando a segurança dos empregados.', '2026-07-04T00:00:00.000', '2026-07-05T10:05:10.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11040, N'983254', N'983254', N'Segurança na dosagem de CAL', 2, N'Others/Outros', N'Empregados para realizar o abastecimento do tanque de cal virgem 2251SL04 com exposto RAC 01.', N'Redução de riscos', N'10054', N'01 - Imagens/01 - Antes/11040.jpeg', N'Empregados para realizar o abastecimento do tanque de cal virgem 2251SL04 ficava exposta aos riscos de RAC 01.', N'01 - Imagens/02 - Depois/11040.jpeg', N'Prolongamento do guarda-corpos da plataforma em 8000 mm eliminado reduzindo o risco de queda do colabora e aplicação da RAC1 para atividade. ', NULL, N'Meta superada com a redução do risco na atividade.', N'Redução de riscos', 0, NULL, N'Eliminação de perdas produtivas associadas à atividade.
INSERT INTO #PVC VALUES (11041, N'983254', N'983254', N'Estacionamento Britagem', 2, N'Others/Outros', N'Risco de incidente com veículos por movimentação involuntária por ausência de trava rodas no local.  ', N'Redução do risco de batida contra de veículo. ', N'10054', N'01 - Imagens/01 - Antes/11041.jpeg', N'Estacionamento da britagem próximo ao CCB sem trava rodas. Risco de incidente com veículos por movimentação involuntária por ausência de trava rodas no local.  ', N'01 - Imagens/02 - Depois/11041.jpeg', N'Fabricação interna de trava, com uso de restos de materiais da caldeiraria da equipe de manutenção da operação de usina.', NULL, N'Riscos, de movimentação involuntária do veículo no estacionamento eliminado. ', N'Redução de riscos e Reaproveitamento de materiais', 0, NULL, N'A melhoria garantiu continuidade operacional na emissão de notificações contratuais, reduziu esforço manual, aumentou a agilidade do processo e fortaleceu a rastreabilidade das comunicações. O documento gerado automaticamente contempla informações essenciais da notificação, como número, data de emissão, prazo de resposta, fornecedor, contrato, assunto, descrição da ocorrência, cláusulas aplicáveis e campo para ciência/assinatura.', '2026-06-16T00:00:00.000', '2026-07-05T19:50:28.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (11042, N'983254', N'983254', N'Bandeira', 1, N'Others/Outros', N'Falta de mastro para instalação de bandeira no período dos jogos da copa.', N'Instalação de mastro para bandeira ', N'10054', N'01 - Imagens/01 - Antes/11042.jpeg', N'Ausência local seguro para instalação de bandeira do Brasil durante os jogos da copa.', N'01 - Imagens/02 - Depois/11042.jpeg', N'Instalação de um mastro no ponta da lança para posicionamento da bandeira durante os jogos da copa.', NULL, N'Meta alcançada. Encontrado local estratégico, com boa visibilidade e acesso seguro. ', N'Engajamento das equipes.', 0, NULL, N'mantendo o equipamento por mais tempo disponívelpara operação', '2026-06-04T00:00:00.000', '2026-07-05T19:59:31.000', N'983254', NULL, NULL);
INSERT INTO #PVC VALUES (11043, N'81047450', N'525730', N'SUPORTE PARA CAPACETE', 2, N'Others/Outros', N'OS CAPACETES NAO TINHA UM LOCAL ADEQUADO PARA ARMAZENAMENTO AO ENTRA NA SALA DE EPIS,ISSO FAZ COM OS COLABORADORES DEIXAVA OS CAPACETES NO CHAO CAUSANDO ARRANHÕES,UMIDADE,COM RESULTADO A VIDA UTIL DO CAPACETE DIMINUI,AUMENTA O CUSTO DE REPOSIÇÃO E O RISCO DE O EPI NÃO OFERECER PROTEÇÃO NECESSÁRIA EM CASO DE ACIDENTE', N'REDUZIR EM 100 % OS CASOS DE CAPACETES PO DANIFICADOS POR ARMAZENAMENTO INADEQUADO .', N'10036', N'01 - Imagens/01 - Antes/11043.jpeg', N'OS CAPACETES NAO TINHA UM LOCAL ADEQUADO PARA ARMAZENAMENTO AO ENTRA NA SALA DE EPIS,ISSO FAZ COM OS COLABORADORES DEIXAVA OS CAPACETES NO CHAO CAUSANDO ARRANHÕES,UMIDADE,COM RESULTADO A VIDA UTIL DO CAPACETE DIMINUI,AUMENTA O CUSTO DE REPOSIÇÃO E O RISCO DE O EPI NÃO OFERECER PROTEÇÃO NECESSÁRIA EM CASO DE ACIDENTE.', N'01 - Imagens/02 - Depois/11043.jpeg', N'APÓS A FABRICAÇÃO DO SUPORTE,O CAPACETE FICAR PROTEGIDO,SEM CONTATO COM O CHÃO /UMIDADE.A VIDA ÚTIL AUMENTA EM ATÉ 40%,COM MENOS REPOSIÇÃO ,O INVESTIMENTO NO SUPORTE SE PAGA COM A DURABILIDADE DO CAPACETE ', NULL, N'SIM', N'SÓ ENTREGAR NÃO RESOLVE,PRECISA INSTALAR E TREINAR ,HÁBITO SE CRIA COM EXEMPLO E FISCALIZAÇÃO', 0, NULL, N'Como resultado, houve aumento da produtividade, redução de erros, aceleração na execução das atividades e fortalecimento da cultura de melhoria contínua por meio da simplificação dos processos digitais.', '2026-07-04T00:00:00.000', '2026-07-05T23:19:42.000', N'81047450', NULL, NULL);
INSERT INTO #PVC VALUES (11044, N'81037838', N'81047011', N'"Instalação de Grade de Proteção na Condensadora - Sala dos Operadores"', 2, N'Others/Outros', N'A condensadora do ar-condicionado encontrava-se exposta, sem proteção, com risco de impactos e danos que poderiam causar a quebra do equipamento, gerando vulnerabilidade a impactos e comprometendo a segurança.', N'Proteger a unidade condensadora do ar-condicionado da sala dos operadores contra impactos e danos, garantindo a segurança, a integridade do equipamento e a continuidade do funcionamento.', N'10054', N'01 - Imagens/01 - Antes/11044.jpeg', N'A condensadora do ar-condicionado encontrava-se exposta, sem proteção, com risco de impactos e danos que poderiam causar a quebra do equipamento, gerando vulnerabilidade a impactos e comprometendo a segurança.', N'01 - Imagens/02 - Depois/11044.jpeg', N'Foi instalada grade de proteção metálica, pintada na cor amarela, ao redor da unidade condensadora. A proteção garante a integridade do equipamento contra impactos, preserva a tubulação e não compromete a ventilação. Equipamento seguro e sinalizado.', NULL, N'SIM. O problema foi resolvido. A unidade condensadora que estava exposta e sem proteção foi isolada com a instalação da grade de proteção metálica. Com isso, eliminamos o risco de impacto e danos ao equipamento, garantindo a segurança e a continuidade do funcionamento do ar-condicionado.', N'A proteção de equipamentos expostos evita custos com manutenção corretiva e aumenta a vida útil do ativo. A sinalização com cor amarela também reforça a segurança.', 0, NULL, N'- Redução do tempo de abastecimento;
INSERT INTO #PVC VALUES (11045, N'81037838', N'81036133', N'Instalação de Caixa Metálica com Tampa Gradeada', 2, N'Others/Outros', N'  O sensor de nível do silo da Rebritagem operava sem proteção física adequada, ficando vulnerável a impactos causados por ferramentas, equipamentos e materiais durante intervenções de manutenção e rotina operacional. Essa condição representava risco de dano ao instrumento, perda de leitura, necessidade de substituições frequentes e possibilidade de interrupção do processo produtivo.', N'Substituir a proteção antiga por uma caixa metálica mais robusta e segura, evitando contato acidental e danos ao vibrador.', N'10054', N'01 - Imagens/01 - Antes/11045.jpeg', N'O sensor de nível do silo da Rebritagem operava sem proteção física adequada, ficando vulnerável a impactos causados por ferramentas, equipamentos e materiais durante intervenções de manutenção e rotina operacional. Essa condição representava risco de dano ao instrumento, perda de leitura, necessidade de substituições frequentes e possibilidade de interrupção do processo produtivo.', N'01 - Imagens/02 - Depois/11045.jpeg', N'   Foi instalada caixa de proteção metálica na cor amarela com tampa em chapa expandida sobre o sensor de nível do silo da Rebritagem. A nova estrutura é mais robusta e fechada, garantindo proteção contra impactos, queda de materiais e ferramentas durante a operação e manutenção. Com isso, foi eliminada a vulnerabilidade do instrumento, assegurando a confiabilidade da leitura de nível e a continuidade do processo produtivo.  ', NULL, N'SIM. O problema foi resolvido. O sensor de nível do silo da Rebritagem que operava sem proteção adequada recebeu uma caixa de proteção metálica com tampa gradeada. A nova estrutura eliminou a vulnerabilidade a impactos, garantindo a integridade do instrumento e a continuidade da leitura de nível.', N'padronização de proteções reduz riscos e retrabalho.', 0, NULL, N'Os equipamentos que saem da Pilha B parem obrigatoriamente, garantindo a prioridade e a segurança dos veículos vindos da Sat 4 que tem menos visibilidade devido ponto cego.', '2026-07-05T00:00:00.000', '2026-07-06T03:01:37.000', N'81037838', NULL, NULL);
INSERT INTO #PVC VALUES (11046, N'81046430', N'81013286', N'Plano de Contingência para Abastecimento de Água Potável no Prédio da Moagem SLB I/II', 2, N'Others/Outros', N'Durante as PGUs, o aumento do consumo no Prédio da Moagem SLB I/II reduz a pressão da rede e aumenta o tempo de recarga dos reservatórios do 7º piso, gerando risco de desabastecimento para cerca de 400 pessoas e impacto nas condições de higiene, consumo e continuidade segura das atividades.', N'Garantir a continuidade do abastecimento de água potável no Prédio da Moagem SLB I/II durante períodos de PGU, por meio do aumento da vazão de recarga dos reservatórios', N'10017', N'01 - Imagens/01 - Antes/11046.jpeg', N'Antes do Kaizen, durante as PGUs, o aumento do consumo reduzia a pressão da rede e atrasava a recarga dos reservatórios do 7º piso da Moagem SLB I/II, gerando risco de desabastecimento para cerca de 400 pessoas e impacto nas condições de higiene, consumo e continuidade segura das atividades.', N'01 - Imagens/02 - Depois/11046.jpeg', N'Após o Kaizen, a aquisição do mangote de 100 metros de 1 polegada permitiu reforçar a vazão de recarga dos reservatórios do 7º piso da Moagem SLB I/II durante PGUs, reduzindo o risco de desabastecimento e garantindo maior estabilidade hídrica, segurança sanitária e continuidade das atividades para cerca de 400 pessoas.', NULL, N'A implantação do mangote de 100 metros de 1 polegada possibilitou reforçar a vazão de abastecimento dos reservatórios, melhorando o equilíbrio hídrico do sistema e reduzindo o risco de desabastecimento durante o período crítico.', N'1)A demanda hídrica aumenta significativamente durante PGUs; 2) Pontos elevados são mais vulneráveis ao desabastecimento; 3) Ações simples podem gerar alto impacto operacional; 4) Segurança hídrica impacta diretamente a continuidade das atividades e processos; 5) Padronizar a solução facilita a replicação.', 0, NULL, N'Aumentar a performance e a produtividade da equipe de manutenção, reduzindo o tempo de setup da coleta SOS e assegurando amostras confiáveis para decisões preditivas ágeis e assertivas nas frotas', '2026-06-02T00:00:00.000', '2026-07-06T09:14:27.000', N'81046430', NULL, NULL);
INSERT INTO #PVC VALUES (11047, N'81030314', N'483565', N'REVITALIZADO ABASTECIMENTO DE GRAXA DOS RESERVATORIOS ', 1, N'Others/Outros', N'Durante do abastecimento da máquina o colaborador tinha que subir no equipamento com a mangueira, assim expondo em trabalho em altura. 
INSERT INTO #PVC VALUES (11048, N'1010414', N'1010414', N'Drone Inspection Cobalt Crud Tank', NULL, N'Refining/Refino', N'The 10 year internal inspection interval is past due for the Cobalt Crud Tank (224-334-TNK-012) and is on the list of inspection for the October 2026 PMP.  A YE notification was created to update the PM for internal inspection to call for a drone inspection. Using the drone for this inspection eliminates the need for complex scaffolding or rope access due to tank orientation and geometry', N'Develop a plan for the internal inspection of the Cobalt Crud Tank', N'10006', N'01 - Imagens/01 - Antes/11048.jpeg', N'An Internal inspection has not been performed on this tank due to the limited access inside', N'01 - Imagens/02 - Depois/11048.jpeg', N'The updated Maintenance Plan will call for the inspection to be carried out via drone', NULL, N'The initial goal was met as there is now a plan to use a drone for the internal inspection of the Cobalt Crud Tank', N'N/A', 0, NULL, N'toda a informação agora está centralizada', '2026-07-05T00:00:00.000', '2026-07-06T11:16:29.000', N'1010414', NULL, NULL);
INSERT INTO #PVC VALUES (11049, N'533528', N'533528', N'App Integrado de Gestão de Férias ', 1, N'Others/Outros', N'A gestão de férias era feita em planilha Excel, com baixa visibilidade consolidada e dificuldade para identificar conflitos entre profissionais no mesmo período. Isso aumentava o risco de ausências simultâneas, impacto na produtividade, maior controle manual e dificuldade para visualizar pessoas sem programação, substitutos e concentração por mês.', N'Digitalizar, automatizar e padronizar a gestão de férias das equipes, permitindo o cadastro rápido das programações, atualização visual em Power BI, identificação preventiva de conflitos de agenda e comunicação automática com a liderança. A iniciativa busca aumentar a governança, reduzir riscos de ausência simultânea de profissionais e possibilitar a replicação da solução para outras áreas.', N'10078', N'01 - Imagens/01 - Antes/11049.jpeg', N'A gestão de férias possuía baixa visibilidade consolidada e dependia de acompanhamento manual, dificultando a identificação prévia de conflitos entre pessoas com férias no mesmo período. Isso gerava conflitos indesejados, risco de ausência simultânea de profissionais e impacto potencial na produtividade da área.', N'01 - Imagens/02 - Depois/11049.jpeg', N'Foi desenvolvido um app integrado de gestão de férias utilizando Power Apps, Power BI, Power Query e Power Automate. A solução permite registrar, editar e consultar férias de forma rápida, com atualização do painel gerencial em aproximadamente 3 minutos. O app alerta quando há tentativa de marcação em período já ocupado, reduzindo conflitos e melhorando o planejamento da equipe.
INSERT INTO #PVC VALUES (11050, N'200500', N'607668', N'Installation of Dribble Screw on Furnace M Floor', 2, N'Others/Outros', N'For many years, the M Floor has been designated as a mandatory respirator area due to elevated levels of airborne dust generated from feed and fines carryover at the primary and secondary scrapers located at the head end of the 29 Conveyor (M+1 Floor). The existing design directed these fines into a chute and dribble box below, which required regular manual handling, transportation, and reintroduction into the process. This method created repeated opportunities for dust generation and employee exposure to airborne contaminants, while also increasing housekeeping requirements and maintenance handling activities. The continued presence of dust impacted workplace conditions, necessitated respiratory protection, and presented ongoing challenges in controlling airborne contaminants at the source.', N'Reduce Airborne Contaminants ', N'10194', N'01 - Imagens/01 - Antes/11050.jpeg', N'Prior to the 2026 PMP modification, the head end of the 29 Conveyor generated a significant amount of feed and fines carryover from the primary and secondary scrapers. These fines were discharged into a chute and collected in a dribble box located below on M Floor. As material accumulated, the dribble box required frequent handling, transportation, and dumping back into the process stream. Each step in this process created opportunities for dust generation, resulting in elevated airborne contaminant levels throughout the area. The persistent dust exposure led to M Floor being designated as a mandatory respirator area for many years, while also increasing housekeeping requirements, material handling activities, and employee exposure to airborne particulates. The existing design controlled the material only after it had already escaped the conveyor system, rather than eliminating the contamination source at its origin.', N'01 - Imagens/02 - Depois/11050.jpeg', N'During the 2026 PMP, the existing feed chute was redesigned and a transfer screw was installed to automatically collect and discharge fines directly onto 33 Conveyor. This modification eliminated the need for the dribble box and the associated manual handling, transportation, and dumping of accumulated material. By returning the fines directly to the process stream at the source, the system significantly reduced dust generation and airborne contaminants on M Floor. The improvement created a cleaner and safer work environment, reduced employee exposure to airborne particulates, lowered housekeeping requirements, improved material recovery, and removed a long-standing source of dust that had contributed to the area''s mandatory respirator designation. The new design provides a sustainable engineering control that addresses the root cause of the issue rather than managing the consequences of material spillage after it occurs.', NULL, N'Yes, the problem was solved by rethinking the fines handling process, the team improved safety, reduced manual work, and enhanced operational efficiency through a sustainable, permanent solution.', N'Long-standing workplace hazards can often be eliminated through simple engineering solutions when the focus is placed on addressing the source of the problem rather than managing its symptoms.', 0, NULL, N'Aumento da segurança operacional.
INSERT INTO #PVC VALUES (11051, N'81062708', N'81062708', N'ADESIVO DISTANCIAMENTO SEGURO ', 2, N'Others/Outros', N'Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito. Como ação preventiva, foi desenvolvido um adesivo educativo para reforçar continuamente esse comportamento seguro durante a condução.Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito. ', N'Promover a conscientização dos condutores sobre a importância de manter uma distância segura entre veículos durante o deslocamento, contribuindo para a prevenção de colisões traseiras e proporcionando maior tempo e espaço para reação diante de situações inesperadas no trânsito.', N'10030', N'01 - Imagens/01 - Antes/11051.jpeg', N'Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito. Como ação preventiva, foi desenvolvido um adesivo educativo para reforçar continuamente esse comportamento seguro durante a condução.Foi identificada a necessidade de reforçar, de forma simples e visual, a importância da manutenção do distanciamento seguro entre veículos. A condução com distância insuficiente reduz o tempo de reação do motorista e aumenta o risco de colisões, especialmente em situações de frenagem repentina, mudanças nas condições da via ou alterações inesperadas no fluxo do trânsito.', N'01 - Imagens/02 - Depois/11051.jpeg', N'Como ação preventiva, foi desenvolvido um adesivo educativo para reforçar continuamente esse comportamento seguro durante a condução. Promover a conscientização dos condutores sobre a importância de manter uma distância segura entre veículos durante o deslocamento, contribuindo para a prevenção de colisões traseiras e proporcionando maior tempo e espaço para reação diante de situações inesperadas no trânsito.
INSERT INTO #PVC VALUES (11052, N'81058966', N'550686', N'Fabricação e instalação de alçapões no piso superior da remoagem Salobo 2 – BP-2057-32', 1, N'Others/Outros', N'O acesso aos pontos de manutenção era realizado de forma inadequada, exigindo corte com máquinas rotativas durante as intervenções. Isso aumentava o tempo de execução, gerava riscos de acidentes (cortes, projeção de partículas e faíscas), comprometia a ergonomia e elevava os custos de manutenção.', N'Implantar alçapões de acesso para eliminar a necessidade de cortes durante as manutenções, reduzindo o tempo de intervenção, melhorando a ergonomia e aumentando a segurança dos empregados.', N'10031', N'01 - Imagens/01 - Antes/11052.jpeg', N' Antes era necessário realizar cortes com lixadeira  para acessar o equipamento, aumentando o tempo de manutenção e a exposição dos empregados aos riscos de corte e projeção de partículas.', N'01 - Imagens/02 - Depois/11052.jpeg', N'Foram fabricados  alçapões no piso superior da remoagem, permitindo acesso rápido e seguro aos pontos de manutenção, eliminando a necessidade de cortes durante as intervenções.', NULL, N'sim, fabricado alçapões para facilitar na hora da manutenção dos equipamentos.', N'Pequenas melhorias estruturais podem reduzir significativamente os riscos de acidentes, aumentar a produtividade, facilitar futuras manutenções e proporcionar maior segurança e ergonomia para a equipe.', 0, NULL, N'Automatizar a atualização anual do calendário da planilha M+12, eliminando atividades manuais, reduzindo o risco de erros e aumentando a produtividade e confiabilidade das informações utilizadas no planejamento de manutenção.', '2026-07-03T00:00:00.000', '2026-07-06T15:07:31.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11053, N'81058966', N'81038889', N'Eliminação de parada da coluna de flotação para substituição de mangueiras do manifold da CF 2057 22', 1, N'Others/Outros', N'O manifold da coluna possuía mangueiras conectadas diretamente ao sistema, sem válvulas de bloqueio individuais. Quando ocorria desgaste ou vazamento , era necessária a parada total da coluna para realizar sua substituição.
INSERT INTO #PVC VALUES (11054, N'533528', N'533528', N'Emissão Automatizada de Notificações Contratuais', 1, N'Others/Outros', N'O processo de emissão de notificações dependia do SGC, porém a nova versão do sistema não possuía essa funcionalidade disponível. Isso gerava risco de descontinuidade na emissão formal das notificações, maior esforço manual, perda de agilidade e possível impacto na governança contratual e na comunicação com fornecedores.', N'Automatizar a emissão de notificações contratuais por meio do Power Apps, com geração de PDF e envio por e-mail, garantindo continuidade operacional, padronização, agilidade e rastreabilidade no processo de comunicação formal com fornecedores.', N'10078', N'01 - Imagens/01 - Antes/11054.jpeg', N'As solicitações de notificação eram recebidas pela Governança de Contratos e emitidas via SGC. Com a transição do sistema, a nova versão não possuía essa funcionalidade, gerando risco de interrupção do processo, atrasos, controles manuais e perda de padronização na emissão das notificações.', N'01 - Imagens/02 - Depois/11054.jpeg', N'Foi criada no Power Apps uma funcionalidade para emissão automatizada de notificações contratuais, permitindo gerar o documento em PDF diretamente pelo app e encaminhá-lo por e-mail aos responsáveis. A solução garante continuidade operacional durante a transição do SGC, reduz etapas manuais, padroniza a emissão das notificações, melhora a rastreabilidade e aumenta a agilidade da comunicação formal com fornecedores. O PDF gerado mantém estrutura padronizada de notificação, com número, data de emissão, prazo de resposta, fornecedor, contrato, assunto, cláusulas aplicáveis e campo de ciência/assinatura.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/8ac5a1bb-152a-402d-b5e3-3107c1803b31?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&skipAppMetadata=true', N'O problema foi resolvido com a criação de uma funcionalidade no Power Apps para emissão automatizada de notificações contratuais em PDF e envio por e-mail. A solução eliminou a dependência imediata da funcionalidade indisponível no novo SGC, manteve a continuidade do processo, reduziu tratativas manuais e padronizou a comunicação formal com fornecedores.', N'A automação de etapas críticas em processos de governança contratual reduz riscos de descontinuidade, principalmente durante transições sistêmicas. Soluções desenvolvidas com Power Apps e Power Automate podem preservar a padronização, aumentar a rastreabilidade e manter a operação funcionando mesmo quando funcionalidades oficiais ainda não estão disponíveis.', 0, NULL, N'A implantação da proteção semimóvel dos mancais do tambor de retorno da 2301TC03 representa uma importante melhoria de segurança, confiabilidade e manutenibilidade. O Kaizen eliminou exposições a riscos de acidentes, facilitou as atividades de manutenção e inspeção, aumentou a eficiência da coleta de dados do CMA e contribuiu diretamente para a disponibilidade operacional do equipamento, reforçando o compromisso com a segurança das pessoas e a excelência operacional.', '2026-07-03T00:00:00.000', '2026-07-06T15:37:02.000', N'533528', NULL, NULL);
INSERT INTO #PVC VALUES (11055, N'81058966', N'81038801', N'Substituição do sistema de acionamento CF 2057 28', 2, N'Others/Outros', N' Equipamento frequentemente entrava em manutenção, devido queima do motor, quebras de correias e substituição frequente de polias motriz, devido ao desgastes.', N' Eliminar a indisponibilidade do equipamento devido a troca frequentemente de componentes e motor', N'10031', N'01 - Imagens/01 - Antes/11055.jpeg', N'O equipamento utilizava sistema de acionamento V-Drive, que apresentava falhas frequentes, como queima do motor, quebra de correias, desgaste de polias e substituição de mancais.', N'01 - Imagens/02 - Depois/11055.jpeg', N'Foi realizada a substituição do sistema de acionamento V-Drive pelo sistema E-Drive, eliminando os componentes sujeitos a desgaste frequente e proporcionando maior confiabilidade.', NULL, N'redução de paradas para manutenção.', N'A busca por soluções inovadoras e tecnologias mais confiáveis reduz custos de manutenção, aumenta a disponibilidade dos equipamentos e melhora a eficiência operacional.', 0, NULL, N'A implantação da talha na monovia 2051TL01 representa uma melhoria permanente no processo de manutenção do acionamento da TC do SAG, proporcionando um ambiente mais seguro, reduzindo custos operacionais, diminuindo o tempo de intervenção e aumentando a confiabilidade das atividades. O Kaizen reforça a cultura de melhoria contínua, com foco em Segurança em primeiro lugar, eficiência operacional e excelência na manutenção.', '2026-06-15T00:00:00.000', '2026-07-06T15:41:18.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11056, N'92000679', N'92000679', N'Menu Rápido do Usuário', NULL, N'Others/Outros', N'Os usuários precisavam navegar por múltiplas transações SAP, memorizar códigos e acessar diferentes caminhos para executar atividades rotineiras', N'Reduzir interação com o sistema', N'10234', N'01 - Imagens/01 - Antes/11056.jpeg', N'Usuário navegava por diversos menus e precisava memorizar códigos SAP.', N'01 - Imagens/02 - Depois/11056.jpeg', N'Usuário acessa os principais processos em uma única tela, com poucos cliques.', NULL, N'O Menu Rápido SAP transformou um processo baseado na memorização de transações em uma navegação intuitiva e padronizada. A solução eliminou desperdícios de tempo com buscas e acessos repetitivos, concentrando em uma única interface as principais ferramentas utilizadas pela operação.', N'Padronização', 0, NULL, N'page is more intuitive to use ', '2026-07-06T00:00:00.000', '2026-07-07T08:56:19.000', N'92000679', NULL, NULL);
INSERT INTO #PVC VALUES (11057, N'81020607', N'723908', N'Melhoria  no abastecimento do compressor da PZ47', 3, N'Others/Outros', N'O tanque de abastecimento do óleo Corena 68 possuía um bujão de fábrica que dificultava sua remoção devido ao elevado torque de aperto.', N'Melhoria continua', N'10139', N'01 - Imagens/01 - Antes/11057.jpeg', N'O tanque de abastecimento do óleo Corena 68 possuía um bujão de fábrica que dificultava sua remoção devido ao elevado torque de aperto. Essa condição aumentava o tempo de abastecimento, exigia maior esforço do colaborador e apresentava risco de danificar o bujão durante a retirada.
INSERT INTO #PVC VALUES (11058, N'475291', N'81035465', N'Adição de placa pare no Acesso da Pilha B com a Sat 4', 2, N'No Replication/Sem replicação', N' Riscos de colisão no acesso devido à falta de sinalização vertical. Os equipamentos vindos da Pilha B não paravam, desrespeitando a preferência dos veículos vindos da Sat 4, que possuem ponto cego crítico na conversão', N'Evitar possíveis colisões entre equipamentos ou veículos ', N'10257', N'01 - Imagens/01 - Antes/11058.jpeg', N' Riscos de colisão no acesso devido à falta de sinalização vertical. Os equipamentos vindos da Pilha B não paravam, desrespeitando a preferência dos veículos vindos da Sat 4, que possuem ponto cego crítico na conversão', N'01 - Imagens/02 - Depois/11058.jpeg', N'Instalação de placa de sinalização "PARE" no acesso que sai da Pilha B. Situação Atual: Fluxo corrigido. Os equipamentos da Pilha B agora param obrigatoriamente, garantindo a prioridade e a segurança dos veículos vindos da Sat 4.', NULL, N'Os equipamentos da Pilha B agora param obrigatoriamente, garantindo a prioridade e a segurança dos veículos vindos da Sat 4.', N'A instalação de sinalização vertical ("PARE") é indispensável para garantir a preferência correta, eliminar conflitos de tráfego e mitigar riscos de colisão em acessos críticos.', 0, NULL, N' eliminando a necessidade de cortes durante as intervenções, reduzindo o tempo de execução e proporcionando melhores condições ergonômicas e de segurança.', '2026-05-15T00:00:00.000', '2026-07-07T10:14:38.000', N'475291', NULL, NULL);
INSERT INTO #PVC VALUES (11059, N'81046576', N'81020892', N'Maleta Kit de Coleta Padrão - SOS', 3, N'Others/Outros', N'Materiais de coleta SOS armazenados de forma despadronizada em bancadas e caixas de ferramentas, expostos a poeira e umidade, gerando risco de contaminação da amostra e baixa agilidade no processo de coleta.', N'Padronizar o kit de coleta SOS em maleta única, eliminando contaminação dos materiais e reduzindo o tempo de preparação da coleta.', N'10144', N'01 - Imagens/01 - Antes/11059.jpeg', N'Materiais de coleta SOS armazenados de forma despadronizada em bancadas e caixas de ferramentas, expostos a poeira e umidade, gerando risco de contaminação da amostra e perda de tempo no setup da coleta.', N'01 - Imagens/02 - Depois/11059.jpeg', N'Maleta Kit de Coleta Padrão – SOS reúne sonda, bomba de vácuo, mangueiras, tesoura e cortador de filtro em um só local. Elimina contaminação, agiliza o setup e é replicável para as demais frotas.', NULL, N'SIM — problema resolvido. Kit padronizado em maleta única eliminou a exposição dos materiais a poeira e umidade, garantiu a confiabilidade da amostra e reduziu o tempo de preparação da coleta SOS.', N'Padronização simples e de baixo custo, quando aplicada a processos críticos como a coleta SOS, gera ganho direto em confiabilidade, produtividade e qualidade da análise preditiva.', 0, NULL, N'Agilizar pesquisa de documentos de segurança.', '2026-06-30T00:00:00.000', '2026-07-07T12:47:43.000', N'81046576', NULL, NULL);
INSERT INTO #PVC VALUES (11060, N'486474', N'486474', N'SUPORTE REGULAVEL PARA BASE MAGNÉTICA DO SWITCH DE LIMITE DE BÁSCULA ALTA', 1, N'Open Pit/Poço aberto', N'CORRETIVA NO CAMPO 
INSERT INTO #PVC VALUES (11061, N'81030274', N'81030274', N'Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual  ', 1, N'No Replication/Sem replicação', N'não existia Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual', N'Mapear de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual', N'10234', N'01 - Imagens/01 - Antes/11061.jpeg', N'não existia Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual  ', N'01 - Imagens/02 - Depois/11061.jpeg', N'Agora existe Mapeamento de Requisições de Materiais de equipamento full service para evitar compras fora da cláusula contratual  ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/8ac993ed-7c4c-4fcc-9cfc-a3c860f8202a?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=610b18fb-40b1-4932-a352-1e8cd9f4ae4a&sourcetime=1783442521551&source=portal', N'agora é possível ter um histórico de todos que fazem requisição emergencial de compras ', N'utilizando bem as ferramentas é possível criar métodos para evitar problemas no peocesso', 0, NULL, N'A melhoria eliminou o risco de acidentes durante a execução da atividade, tornando o processo mais seguro e confiável.
INSERT INTO #PVC VALUES (11062, N'81024446', N'81024446', N'Eliminação de cenário de risco (RAC 01)', 2, N'Others/Outros', N'Para a realização das atividades de inspeção e manutenção da estação de referência de monitoramento da qualidade do ar, era necessário acessar a parte superior da estrutura utilizando cinto de segurança, escada sem corrimão e possuir os treinamentos exigidos para atividades críticas, conforme o RAC 01.', N'Eliminar trabalho em altura durante atividades de inspeção e manutenção da estação de monitoramento da qualidade do ar ', N'10268', N'01 - Imagens/01 - Antes/11062.jpeg', N'Para a realização das atividades de inspeção e manutenção da estação de referência de monitoramento da qualidade do ar, era necessário acessar a parte superior da estrutura utilizando cinto de segurança, escada sem corrimão e possuir os treinamentos exigidos para atividades críticas, conforme o RAC 01. Para realização da atividade ainda era necessária a elaboração de PTS e acompanhamento mais específico. ', N'01 - Imagens/02 - Depois/11062.jpeg', N'Foi construída uma escada de madeira, utilizando material reaproveitado das atividades de supressão vegetal, equipada com corrimão, com o objetivo de eliminar o risco associado ao trabalho em altura. Essa melhoria proporcionou maior segurança e agilidade na execução das atividades de inspeção e manutenção da estação de referência para monitoramento da qualidade do ar', NULL, N'O problema de trabalho em altura foi solucionado com a construção de uma escada fixa de madeira equipada com corrimão, utilizando material reaproveitado das atividades de supressão vegetal. A implementação dessa estrutura eliminou a necessidade de acesso por métodos que exigiam trabalho em altura, reduzindo a exposição dos trabalhadores ao risco de queda e proporcionando maior segurança, praticidade e eficiência nas atividades de inspeção e manutenção da estação de referência para monitoramento da qualidade do ar', N'A substituição de controles administrativos e do uso frequente de sistemas de proteção para trabalho em altura por uma solução de engenharia permanente proporcionou maior segurança, padronização do acesso, redução da exposição ao risco e ganho de eficiência nas atividades de manutenção e inspeção da estação de monitoramento da qualidade do ar', 0, NULL, N'Redução expressiva dos riscos químicos e aumento da segurança operacional.
INSERT INTO #PVC VALUES (11063, N'81017966', N'81017966', N'SINALIZADOR  SEGURANÇA AUDIO/VISUAL TE 2009-07', 2, N'Projects/Projetos', N'A talha elétrica não possuía um sistema de alerta sonoro e visual. Durante a operação, as pessoas ao redor nem sempre percebiam o início dos movimentos ou condições de falha, aumentando o risco de acidentes, colisões e danos ao equipamento.', N'Instalar um sinalizador áudio-visual na talha elétrica para alertar os operadores e pessoas próximas durante os movimentos de elevação e translação, além de indicar situações de sobrecarga e cabo frouxo, aumentando a segurança operacional e reduzindo o risco de acidentes.', N'10124', N'01 - Imagens/01 - Antes/11063.jpeg', N'Ausência de sinalização sonora e visual durante a movimentação da talha.
INSERT INTO #PVC VALUES (11064, N'81017966', N'81017966', N'INSTALAÇÃO SINALIZADOR AUDIO VISUAL TE 2009-09', 2, N'Others/Outros', N'A talha elétrica não possuía um sistema de alerta sonoro e visual. Durante a operação, as pessoas ao redor nem sempre percebiam o início dos movimentos ou condições de falha, aumentando o risco de acidentes, colisões e danos ao equipamento.', N'Instalar um sinalizador áudio-visual na talha elétrica para alertar os operadores e pessoas próximas durante os movimentos de elevação e translação, além de indicar situações de sobrecarga e cabo frouxo, aumentando a segurança operacional e reduzindo o risco de acidentes.', N'10124', N'01 - Imagens/01 - Antes/11064.jpeg', N'Ausência de sinalização sonora e visual durante a movimentação da talha.
INSERT INTO #PVC VALUES (11065, N'510839', N'510839', N'Automatização da Atualização de Calendário na Planilha M+12', 1, N'Others/Outros', N'A atualização anual do calendário utilizado no planejamento M+12 era realizada manualmente, demandando tempo da equipe e aumentando o risco de inconsistências nos dias da semana.', N'Automatizar a atualização do calendário anual da planilha M+12, eliminando ajustes manuais e garantindo maior confiabilidade das informações.', N'10234', N'01 - Imagens/01 - Antes/11065.jpeg', N'A atualização dos dias da semana para novos anos era realizada manualmente na planilha M+12, gerando retrabalho, maior tempo de manutenção e risco de erros no calendário.', N'01 - Imagens/02 - Depois/11065.jpeg', N'Foi criado um calendário dinâmico com fórmulas automáticas, permitindo atualizar todo o ano apenas alterando uma célula de referência, eliminando ajustes manuais.', NULL, N'A meta foi plenamente atingida. O processo de atualização do calendário, anteriormente realizado manualmente e sujeito a erros, foi automatizado por meio de fórmulas dinâmicas. A solução eliminou retrabalho, reduziu o tempo gasto com manutenção da ferramenta e aumentou a confiabilidade dos dados utilizados no planejamento de manutenção.', N'Pequenas automações em ferramentas de planejamento podem gerar ganhos significativos de confiabilidade, produtividade e padronização dos processos.', 0, NULL, N'Monitoramento de variações de temperatura dos pinos da caçamba em tempo real, gerando dados quantitativos para tomadas de decisão para serviços de manutenção no sistema de lubrificação centralizado dos pontos de graxa. ', '2026-07-06T00:00:00.000', '2026-07-07T16:38:18.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11066, N'510839', N'510839', N'Extração Automatizada de Planos de Manutenção da frota de Perfuração', 1, N'Others/Outros', N'A extração de planos de manutenção da frota de perfuração no SAP na transação IP19, exigia preenchimento manual de filtros e critérios de seleção, aumentando o tempo de execução e a possibilidade de erros operacionais.', N'Reduzir o tempo gasto na consulta e extração de planos de manutenção da frota de perfuração, aumentando a padronização, produtividade e confiabilidade do processo.', N'10234', N'01 - Imagens/01 - Antes/11066.jpeg', N'A consulta de planos no SAP IP19 exigia configuração manual através da seleção da variante previamente salva , consumindo tempo e aumentando o risco de inconsistências.', N'01 - Imagens/02 - Depois/11066.jpeg', N'Implementado robô VBA para automatizar consultas e baixas de dados no SAP, aumentando a produtividade e permitindo execução paralela de outras atividades.', NULL, N'Sim, o problema foi resolvido. A implementação do robô VBA eliminou a necessidade de execução manual da consulta e extração dos planos de manutenção na transação IP19. O processo passou a ser realizado automaticamente, reduzindo o tempo operacional, minimizando riscos de erro, garantindo maior padronização das informações e liberando o usuário para atividades de maior valor agregado durante a execução da rotina.', N'A automação de atividades repetitivas através de VBA e SAP Script reduz a dependência da operação manual, aumenta a produtividade da equipe e permite direcionar esforços para análises e atividades de maior valor agregado.', 0, NULL, N'A substituição do equipamento convencional por um modelo elétrico proporciona ganhos expressivos em ergonomia, produtividade e redução de custos. Entre os principais benefícios, destacam-se a redução de aproximadamente 50% no peso do equipamento, a eliminação total do consumo de combustível e da exposição à vibração e ao calor gerados por motores a combustão. Além disso, a menor fadiga dos colaboradores aumenta a agilidade e a produtividade das atividades, reduz pela metade a quantidade de equipamentos necessários (de dois para um), diminui os custos com manutenção e insumos e promove significativa melhoria das condições ergonômicas, com menor sobrecarga física ao longo da jornada de trabalho.', '2026-07-06T00:00:00.000', '2026-07-07T17:29:36.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11067, N'516481', N'516481', N'Proteção Semimóvel dos Mancais do Tambor de Retorno – 2301TC03', NULL, N'Projects/Projetos', N'Antes da implantação da melhoria, os mancais do tambor de retorno possuíam proteção inadequada e pontos de acesso expostos, gerando riscos durante atividades de inspeção e manutenção.', N'Desenvolver e instalar uma proteção semimóvel para os mancais do tambor de retorno da correia transportadora 2301TC03, garantindo maior segurança para as equipes de manutenção, operação e inspeção, além de proporcionar melhor acesso para coleta de dados de monitoramento do equipamento.', N'10362', N'01 - Imagens/01 - Antes/11067.jpeg', N'Antes da implantação da melhoria, os mancais do tambor de retorno possuíam proteção inadequada e pontos de acesso expostos, gerando riscos durante atividades de inspeção e manutenção.
INSERT INTO #PVC VALUES (11068, N'516481', N'516481', N'Instalação da Talha 2051TL01 na Monovia', NULL, N'Projects/Projetos', N'Anteriormente, a substituição do redutor dependia de caminhão munck e de operações de içamento complexas, exigindo maior número de pessoas, isolamento de áreas e condições específicas para execução. Com a instalação da talha na monovia, o equipamento passou a ser movimentado de forma segura, controlada e diretamente no local da manutenção.', N'aumentar a segurança, reduzir o tempo de manutenção e eliminar riscos durante as intervenções no acionamento da Transportadora de Correia (TC) do SAG', N'10362', N'01 - Imagens/01 - Antes/11068.jpeg', N'Anteriormente, a substituição do redutor dependia de caminhão munck e de operações de içamento complexas, exigindo maior número de pessoas, isolamento de áreas e condições específicas para execução. Com a instalação da talha na monovia, o equipamento passou a ser movimentado de forma segura, controlada e diretamente no local da manutenção.
INSERT INTO #PVC VALUES (11069, N'81031131', N'81031131', N'updating Port PI screen', 1, N'Others/Outros', N'port SOS PI was hard to find information on ', N'make Port SOS PI screen easier to use', N'#N/A', N'01 - Imagens/01 - Antes/11069.jpeg', N'previous screen was unorganized and had large icons for less frequently looked at information cluttering the screen while missing some more beneficial information. 
INSERT INTO #PVC VALUES (11070, N'550315', N'550315', N'CLAVICULÁRIO CORRETIVA', 3, N'Others/Outros', N'A falta de um local padronizado para armazenamento das chaves da manutenção corretiva dificultava sua localização e controle, aumentando o risco de extravios e atrasos nas atividades. O problema foi identificado durante a rotina da equipe, devido ao tempo excessivo gasto na busca das chaves e aos impactos na eficiência operacional.', N'Organizar, identificar e controlar as chaves utilizadas nas atividades de manutenção corretiva, garantindo fácil acesso, armazenamento adequado e rastreabilidade, contribuindo para a agilidade no atendimento das ocorrências e para a conservação dos recursos da área.', N'10234', N'01 - Imagens/01 - Antes/11070.jpeg', N'As chaves utilizadas pela equipe de manutenção corretiva não possuem um claviculário específico para armazenamento e controle, permanecendo guardadas em locais diversos e sem identificação padronizada. Essa condição dificulta a localização rápida das chaves, aumenta o risco de extravios e gera perda de tempo durante a execução das atividades de manutenção, impactando a organização e a eficiência da equipe.', N'01 - Imagens/02 - Depois/11070.jpeg', N'Foi implantado um claviculário para a equipe de manutenção corretiva, com posições definidas e identificadas para cada chave. As chaves passaram a ser armazenadas em local específico, de fácil acesso e visualização, garantindo melhor organização, controle e rastreabilidade.', NULL, N'SIM
INSERT INTO #PVC VALUES (11071, N'81058966', N'81046993', N'Fabricação e instalação de alçapões no piso superior da remoagem Salobo 2 – BP-2057-36.', 1, N'Others/Outros', N' O acesso aos pontos de manutenção era realizado de forma inadequada, exigindo corte com máquinas rotativas durante as intervenções. Isso aumentava o tempo de execução, gerava riscos de acidentes (cortes, projeção de partículas e faíscas), comprometia a ergonomia e elevava os custos de manutenção.', N'Implantar alçapões de acesso para eliminar a necessidade de cortes durante as manutenções, reduzindo o tempo de intervenção, melhorando a ergonomia e aumentando a segurança dos empregados.', N'10031', N'01 - Imagens/01 - Antes/11071.jpeg', N' Antes era necessário realizar cortes com lixadeira ou outras máquinas rotativas para acessar o equipamento, aumentando o tempo de manutenção. E riscos ao trabalhador.', N'01 - Imagens/02 - Depois/11071.jpeg', N'Foram fabricados e instalados alçapões no piso superior da remoagem, permitindo acesso rápido e seguro aos pontos de manutenção, eliminando a necessidade de cortes durante as intervenções.', NULL, N'sim, Foram fabricados e instalados alçapões.', N'Pequenas melhorias estruturais podem reduzir significativamente os riscos de acidentes, aumentar a produtividade', 0, NULL, N'depois da janela de visita instalada ficou acessível para limpeza e inspeção  ', '2026-07-02T00:00:00.000', '2026-07-08T11:09:07.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11072, N'501925', N'501925', N'Gestão de análises de Risco', 1, N'Others/Outros', N'Dificuldade na localização de ART''S pela descrição da tarefa.', N'Facilitar busca de documentos no sistema ART.', N'10178', N'01 - Imagens/01 - Antes/11072.jpeg', N'Dificuldade na localização de ART''S pela descrição da tarefa.', N'01 - Imagens/02 - Depois/11072.jpeg', N'Criado controle com todas as análises de risco da coordenação, indicando as RAC''s e PRO''s associados juntamente com os ID''s.', NULL, N'Redução do tempo de busca em 90%', N'Agilizar a pesquisa de documentos', 0, NULL, N'Desenvolvimento de fornecedor local;
INSERT INTO #PVC VALUES (11073, N'81042755', N'81019680', N'Cathodic Protection Thickener Tanks', 1, N'Concentration/Concentração', N'Enable the corrosion protection system, the Cathodic Protection System, for the Concentrator Thickener tanks, specifically the Copper Thickener, the Nickle Conc Thickener, and the Middlings Conc Thickener tanks.', N'Re-establish Cathodic Protection of Thickener Tanks', N'10047', N'01 - Imagens/01 - Antes/11073.jpeg', N'The Cathodic Protection system on the Copper Thickener, the Nickle Conc Thickener, and the Middlings Conc Thickener tanks was not powered. There was an issue with the powering equipment and thus it was not powered pending vendor rep. review and troubleshooting of system. ', N'01 - Imagens/02 - Depois/11073.jpeg', N'The Cathodic Protection system on the Copper Thickener, the Nickle Conc Thickener, and the Middlings Conc Thickener tanks has been re-powered. Issue with the powering equipment solved via replacement of components. ', NULL, N'Yes. Cathodic protection system for thickener tanks re-energized and corrosion protection is re-enabled.', N'Cathotic Protection system, the anodes are consumables.', 10000, 3, N'Increased efficiency', '2026-06-26T00:00:00.000', '2026-07-08T11:29:49.000', N'81042755', NULL, NULL);
INSERT INTO #PVC VALUES (11074, N'81058966', N'81058364', N'Dispositivo para Proteção das Mãos durante o Uso do Punção', NULL, N'Others/Outros', N'Durante a utilização do punção com o auxílio de uma marreta, foi identificado risco de impacto nas mãos e nos dedos do operador. A atividade exigia que os membros superiores permanecessem próximos à área de impacto, aumentando a probabilidade de acidentes e comprometendo a segurança durante a execução do serviço.
INSERT INTO #PVC VALUES (11075, N'81058966', N'81038934', N'Melhoria nas tubulações de recalque e sucção-BQ-2022-188', 1, N'Others/Outros', N'As tubulações de sucção e recalque originais eram confeccionadas em PEAD rígido. Suas curvas e soldas sofriam ressecamento1 progressivo ao longo do tempo, causado pela ação1 do produto químico transportado pelo sistema, o que resultava em vazamentos frequentes.', N'Substituir as tubulações rígidas por modelos flexíveis, com maior resistência ao produto químico transportado, visando elevar a confiabilidade do sistema e eliminar os vazamentos.  ', N'10031', N'01 - Imagens/01 - Antes/11075.jpeg', N'Havia contaminação constante na baia das BQ’s, causada pelo grande volume de vazamentos provenientes das tubulações dos equipamentos.', N'01 - Imagens/02 - Depois/11075.jpeg', N's tubulações rígidas foram totalmente substituídas por modelos flexíveis, desenvolvidos para maior resistência química e durabilidade.', NULL, N'sim,eliminação completa dos vazamentos nas tubulações
INSERT INTO #PVC VALUES (11076, N'81035985', N'81030300', N'Disponibilização de tablet para monitoramento da PC13 na Usina', 2, N'Others/Outros', N'Na operação da Usina, o monitoramento do sistema de acompanhamento de pneus da PC13 em atividades externas era realizado com dificuldade devido à indisponibilidade de acesso móvel ao sistema, o que poderia gerar atrasos na identificação de desvios e impactar a preservação dos ativos.', N'Maior agilidade no monitoramento da PC13 em atividades externas.', N'10162', N'01 - Imagens/01 - Antes/11076.jpeg', N'Não havia acesso móvel ao sistema de monitoramento da PC13 em campo, limitando o acompanhamento em tempo real e tornando o processo mais lento e menos eficiente.', N'01 - Imagens/02 - Depois/11076.jpeg', N'Disponibilização de tablet para acesso ao sistema em campo, permitindo monitoramento em tempo real, maior agilidade operacional e melhor preservação dos ativos.', NULL, N'Antes da implementação, o monitoramento da PC13 em atividades externas era limitado pela falta de acesso móvel ao sistema, dificultando o acompanhamento em tempo real e aumentando o tempo de resposta para identificação de desvios.
INSERT INTO #PVC VALUES (11077, N'81012715', N'81012715', N'Melhoria da Confiabilidade do Monitoramento Preditivo com Sensor Portátil DynaPortable', 1, N'Others/Outros', N'30% dos spots dos equipamentos da Usina permaneciam sem coleta de dados de vibração devido à ausência de sensores fixos', N'Elevar o número de coleta de dados de Spots sem sensor fixo', N'10362', N'01 - Imagens/01 - Antes/11077.jpeg', N'Aproximadamente 30% dos spots dos equipamentos da Usina permaneciam sem coleta de dados de vibração devido à ausência de sensores fixos e à demora na aquisição e reposição desses dispositivos. Essa limitação reduzia a abrangência do monitoramento preditivo, dificultava a identificação precoce de falhas e aumentava o risco de evolução de defeitos em ativos sem acompanhamento contínuo.', N'01 - Imagens/02 - Depois/11077.jpeg', N'Foi adquirido o sensor portátil DynaPortable como solução para monitorar equipamentos sem sensores fixos instalados. O equipamento é leve, compacto, de fácil transporte e fixação magnética, permitindo coletas rápidas com apenas uma mão, inclusive em áreas sem cobertura de rede, armazenando os dados para sincronização posterior via Bluetooth.
INSERT INTO #PVC VALUES (11078, N'81004462', N'81004462', N'Monitoramento pinos da caçamba', 1, N'Others/Outros', N'Falta de visibilidade de Lubrificação deficiente os pinos e buchas da caçamba, ', N'Previsibilidade e monitoramento', N'10015', N'01 - Imagens/01 - Antes/11078.jpeg', N'Desgaste de pinos e buchas da caçamba devido falha de lubrificação, não sendo possível a identificação com antecedência dos problemas de lubrificação devido a eficiência do sistema.', N'01 - Imagens/02 - Depois/11078.jpeg', N'Instalação de sensores de temperatura na extremidade do braço de elevação lado direito e lado esquerdo, com o objetivos de monitorar a ocorrências de variações de temperatura devido falhas de lubrificação em tempo real, gerando parâmetros para atendimento antecipado de possíveis falha e desgaste dos pinos e buchas da caçamba.
INSERT INTO #PVC VALUES (11079, N'544481', N'81047743', N'Adaptação do equipamento atomizador', 1, N'No Replication/Sem replicação', N'O uso de atomizadores costais motorizados no controle de pragas exige elevado esforço físico devido ao peso, vibração, ruído e calor do equipamento. Essas condições aumentam a fadiga, prejudicam a ergonomia, a produtividade e a qualidade das atividades, além de elevar os riscos de falhas operacionais e acidentes, afetando a segurança e a eficiência do processo.', N'Melhoria ergonômica significativa, com redução de sobrecarga física durante a jornada ', N'10017', N'01 - Imagens/01 - Antes/11079.jpeg', N'A utilização de atomizadores costais motorizados nas atividades de controle de pragas exige elevado esforço físico dos colaboradores, devido ao peso do equipamento, vibração, ruído e calor gerados durante a operação. Essa condição intensifica a fadiga ao longo da jornada, impactando negativamente a ergonomia, a produtividade e a qualidade das atividades executadas. Além disso, o desgaste físico aumenta o risco de falhas operacionais e de acidentes, comprometendo a segurança dos colaboradores e a eficiência do processo.
INSERT INTO #PVC VALUES (11080, N'81034443', N'81047331', N'Implementação do Lavador de Peças para Eliminar Contaminação na Limpeza de Componentes.', 3, N'Others/Outros', N'A lavagem de peças era realizada em baldes com acúmulo de óleo e resíduos. Esse método gerava contaminação cruzada entre os componentes, risco de sujeira retornar ao sistema, ambiente de trabalho sujo e inseguro, e descarte inadequado dos resíduos.', N'Padronizar a lavagem de peças utilizando o lavador de peças, garantindo limpeza sem contaminação, aumento da segurança e organização do posto de trabalho.', N'10140', N'01 - Imagens/01 - Antes/11080.jpeg', N'Nas primeiras fotos a lavagem estava sendo feita no balde, com resíduo de óleo preto acumulado no fundo e nas paredes. Isso gera risco de contaminação cruzada, porque a sujeira de uma peça volta pra outra. ', N'01 - Imagens/02 - Depois/11080.jpeg', N'As peças estão na bancada verde do lavador, com contenção. O fluido fica circulando ali e não espalha óleo no chão.
INSERT INTO #PVC VALUES (11081, N'81034443', N'81034443', N' Inventário e Checklist para Ferramentas de Caminhões Fora de Estrada.', 3, N'Others/Outros', N'O armário de ferramentas de apoio aos caminhões fora de estrada não possuía inventário atualizado nem processo padrão de conferência. Isso gerava perda de tempo na busca de ferramentas, ferramentas danificadas ou faltantes não identificadas na troca de turno e risco de atraso na manutenção/liberação dos caminhões por falta de item crítico.', N'Garantir 100% de disponibilidade e rastreabilidade das ferramentas do armário de apoio aos caminhões fora de estrada, através de inventário atualizado e checklist visual na troca de turno, reduzindo perda de tempo na busca de ferramentas e atrasos na manutenção.', N'10140', N'01 - Imagens/01 - Antes/11081.jpeg', N'O armário de ferramentas de apoio aos caminhões fora de estrada não possuía inventário atualizado nem processo padrão de conferência. Isso gerava perda de tempo na busca de ferramentas, ferramentas danificadas ou faltantes não identificadas na troca de turno e risco de atraso na manutenção/liberação dos caminhões por falta de item crítico.', N'01 - Imagens/02 - Depois/11081.jpeg', N'Checklist padrão feito todo início/fim de turno.
INSERT INTO #PVC VALUES (11082, N'516481', N'516481', N'Montagem de Suportes para Linha de Vida na Flexowell 2301TR01', NULL, N'Projects/Projetos', N'ão existia sistema de ancoragem contínuo para trabalho em altura.
INSERT INTO #PVC VALUES (11083, N'81038902', N'81038902', N'dispositivo recuperador de corpos moedores ', 1, N'Others/Outros', N'local -TR-2313SA-01 que e alimentada 
INSERT INTO #PVC VALUES (11084, N'81038902', N'479513', N'janela de inspeção ', 1, N'Others/Outros', N'local- TR-2009-5 chute de descarga chute sem acesso para manutenção  ', N'acessar chute para inspeção  e manutenção interna ', N'10031', N'01 - Imagens/01 - Antes/11084.jpeg', N'LOCAL-SLB-1-2 TR-2009-5 chute de descarga antes esse mesmo chute não tinha como acessar para fazer manutenção deixando o chute se colapsar em desgastes internos  ', N'01 - Imagens/02 - Depois/11084.jpeg', N'LOCAL-SLB-1-2 TR-2009-5 chute de descarga foi fabricado e instalado uma janela de visita na dimensão de 800mmx 800mm assim facilitando o acesso para realizar reparos internamente no chute   ', NULL, N'sim resolvido foi fabricado e instalado uma janela de visita no chute dando condições para acessar e fazer manutenção no mesmo  ', N'sempre criar melhores condições para manutenção ', 0, NULL, N'ELIMINAÇÃO DE RISCOS DE BATIDAS ', '2026-06-29T00:00:00.000', '2026-07-09T00:14:29.000', N'81038902', NULL, NULL);
INSERT INTO #PVC VALUES (11085, N'81011396', N'81011396', N'Desenvolvimento Implemento Garfo para CAT950', 2, N'Projects/Projetos', N'O fornecedor CAT, cotado por suprimentos para fornecimento do implemento Garfo não possuía um implemento nas dimensões necessárias para aplicação na Carregadeira CAT950.  ', N'Especificar Implemento Garfo para implantação na CAT950', N'10015', N'01 - Imagens/01 - Antes/11085.jpeg', N'Ausência de fornecedor que atendesse a especificação para fabricação do Garfo para implementação na Carregadeira CAT950, de acordo com as suas dimensões e requisitos de segurança (mandatório acionamento automático da abertura e fechamento do Garfo), conforme NR-12 Req. Proteção de Máquinas', N'01 - Imagens/02 - Depois/11085.jpeg', N'Desenvolvimento do implemento Garfo, com fornecedor local  de Parauapebas-PA, atendendo aos requisitos de segurança necessários (acionamento hidráulico p/ abertura e fechamento reduzindo assim a exposição ao risco do operador), bem como as dimensões necessárias de operação p/ CAT950 (2440mmx200mmx80mm) com capacidade de carga 18 toneladas', NULL, N'Sim, problema resolvido. Foi desenvolvimento com fornecedor local implemento Garfo, atendendo as especificações técnicas e de segurança', N'Desenvolvimento de novos fornecedores locais', 0, NULL, N'Melhoria da produtividade e do bem-estar da equipe, devido às condições de trabalho mais adequadas.', '2026-07-08T00:00:00.000', '2026-07-09T11:21:21.000', N'81011396', NULL, NULL);
INSERT INTO #PVC VALUES (11086, N'200795', N'301033', N'Garson Rail Slinging Skid', NULL, N'Underground/Subterrâneo', N'Since sections of track rail don''t fit in the Garson cage, we would sling them only 3 at a time.  The method required many supplies including 5 slings, 5 shackles, 2 divider bolts with nuts.  This was time consuming.', N'Increase efficiency and safety', N'10238', N'01 - Imagens/01 - Antes/11086.jpeg', N'Since sections of track rail don''t fit in the Garson cage, we would sling them only 3 at a time.  The method required many supplies including 5 slings, 5 shackles, 2 divider bolts with nuts.  This was time consuming.', N'01 - Imagens/02 - Depois/11086.jpeg', N'Implemented a new rail slinging skid.  It can secure up to 16 sections of track rail.  We can now move almost 6 times the amount in the same time.  All properly designed and engineered for safety.', NULL, N'Problem solved', N'N/A', 0, NULL, N'Redução de custos desnecessários com aquisição de peças e materiais.', '2026-06-30T00:00:00.000', '2026-07-09T12:04:54.000', N'200795', NULL, NULL);
INSERT INTO #PVC VALUES (11087, N'609090', N'609090', N'Air Movers LS1', 3, N'Underground/Subterrâneo', N'The proper amount of CMF required for Load station has always been adequate, the air had a hard time exhausting the area.  High ammonia and high humify would be common during summer months.  Muck Circuit workers felt that something can be done to move the air around and exhaust it faster than its current state', N'Move air and exhaust air faster ', N'10340', N'01 - Imagens/01 - Antes/11087.jpeg', N'The proper amount of CMF required for Load station has always been adequate, but the air had a hard time exhausting the area.  High ammonia and high humify would be common during summer months.  Muck Circuit workers felt that something can be done to move the air around and exhaust it faster than its current state.  ', N'01 - Imagens/02 - Depois/11087.jpeg', N'After discussing the situation with the vent department, it was decided that 3 air movers would be installed with their own stop and start switch in specified locations to move the air around and exhaust quicker from the LS1 platform. Muck Circuit workers are extremely happy with the results especially during the high humidity months. The air movers also help with clearing blast gas when having to blast down hang ups.   ', NULL, N'Yes, the air exhaust faster than before making the environment a lot more comfortable to work.  Having the fans on their own stop and start switch allows the workers to control the flow of air to their liking ', N'Listen to workers that perform the work on a daily basis.  ', 0, NULL, N'Reduced time and effort to clear plugged line from pump', '2026-07-08T00:00:00.000', '2026-07-09T12:52:06.000', N'609090', NULL, NULL);
INSERT INTO #PVC VALUES (11088, N'510839', N'510839', N'Dashboard de Projeção dos Planos de Manutenção da Frota de Carga – Base SAP IP19', 1, N'Others/Outros', N'O processo de análise dos planos da frota de carga era realizado por meio do BI de Projeção de Planos alimentado pelo SAP Hana ou pela extração manual de planilhas Excel do SAP. Além do tempo gasto na obtenção e tratamento das informações, a defasagem da base comprometia a agilidade e a confiabilidade das análises para o planejamento da manutenção.', N'Desenvolver um dashboard simplificado e confiável, utilizando dados extraídos diretamente da transação SAP IP19, reduzindo o tempo de consulta das informações e aumentando a assertividade do planejamento da manutenção da frota de carga.', N'10234', N'01 - Imagens/01 - Antes/11088.jpeg', N'A gestão dos planos da frota de carga era feita por planilhas Excel extraídas do SAP, exigindo análise manual dos dados e aumentando o tempo de consulta e planejamento da manutenção.', N'01 - Imagens/02 - Depois/11088.jpeg', N'Implementado dashboard de projeção dos planos da frota de carga utilizando base SAP IP19, centralizando informações e reduzindo o tempo de análise e planejamento da manutenção.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/26e53ab2-dd5d-4706-ad8d-731dab0da7df/f92168403940559d4135?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim, A melhoria implementada atendeu ao objetivo proposto, substituindo análises manuais realizadas em planilhas extraídas do SAP e complementando as consultas ao BI alimentado pelo SAP Hana. Com a criação do dashboard de Projeção dos Planos da Frota de Carga utilizando dados da transação SAP IP19, houve ganho de produtividade, maior confiabilidade das informações e redução do tempo necessário para análise e tomada de decisão no planejamento da manutenção.', N'utilização de dados extraídos diretamente da transação SAP IP19, associada a dashboards simplificados e direcionados ao usuário, aumenta a confiabilidade das informações e reduz o esforço necessário para análise e planejamento da manutenção.', 0, NULL, N'Bancada móvel com proteção para corte de bloco civil, melhoria na ergonomia do operador e mitigar o risco de projeção ao cortar os blocos.', '2026-07-08T00:00:00.000', '2026-07-09T13:57:07.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11089, N'486474', N'506216', N'ENGATE RAPIDO DE ABASTECIMENTO DE ÓLEO DO MOTOR DIESEL FROTA KOMATSU 830E E 930E', 1, N'Open Pit/Poço aberto', N'​"Identificado vazamento constante de óleo lubrificante no sistema de dreno do motor diesel, causado por desgaste e danos na rosca do bujão/conexão anterior. Esta falha resultava em desperdício contínuo de insumo (óleo motor), riscos de contaminação ambiental e excesso de horas de mão de obra dedicadas a intervenções corretivas e limpeza da área."', N'Substituir a conexão danificada por um sistema de engate rápido para garantir a estanqueidade do cárter, eliminar o desperdício de óleo motor e padronizar o processo de dreno para tornar as revisões futuras mais rápidas e limpas.', N'10140', N'01 - Imagens/01 - Antes/11089.jpeg', N'O dreno do óleo era feito pela remoção manual de um componente com a rosca danificada. O processo gerava gotejamento constante mesmo após o aperto, demandava muito tempo da equipe para conter o óleo e limpar o local, além de trazer o risco de espanar em definitivo a rosca do cárter a cada manutenção.', N'01 - Imagens/02 - Depois/11089.jpeg', N'​Eliminação de Desperdício: Vazamento zero de óleo motor, gerando economia imediata de lubrificante.
INSERT INTO #PVC VALUES (11090, N'55053', N'55053', N'Acompanhamento de carteira', 1, N'Others/Outros', N'Dificuldade na visualização por etapa das ordens da carteira de reforma de componentes.', N'Facilitar visualização de carteira', N'10234', N'01 - Imagens/01 - Antes/11090.jpeg', N'Para visualizar as ordens de reforma por etapa, era necessário criar filtros para visualização exclusiva da etapa.', N'01 - Imagens/02 - Depois/11090.jpeg', N'Foi criado gráfico para acompanhamento das ordens de reforma, por etapa de processo. 
INSERT INTO #PVC VALUES (11091, N'81035985', N'81039320', N'Mesh Monitor', 1, N'Others/Outros', N'Os repetidores de sinal nem sempre mantêm o GPS operacional, dificultando a localização dos equipamentos em campo. Além disso, não há rastreabilidade das movimentações, impossibilitando identificar quem deslocou o repetidor, quando ocorreu a movimentação e para qual área da mina ele foi direcionado, gerando perda de tempo e impacto na eficiência operacional.', N'Precisçao de localização e mapa de calor das minas ', N'10216', N'01 - Imagens/01 - Antes/11091.jpeg', N'A movimentação das repetidoras de sinal ocorria sem controle de localização. Em caso de falha no GPS, as equipes não conseguiam identificar onde o equipamento havia sido posicionado, gerando perda de tempo na localização e impactos na operação.', N'01 - Imagens/02 - Depois/11091.jpeg', N'Foi criado um sistema que registra a última localização da repetidora e a equipe responsável pela movimentação, utilizando o GPS do celular ou tablet para garantir rastreabilidade.', N'https://mesh.revisaai.cloud/pt-BR/map', N'A solução reduziu o tempo de localização das repetidoras durante os desmontes, aumentou a precisão na identificação de áreas sem cobertura e disponibilizou um histórico de movimentações, ampliando o suporte às operações de mina.', N'A rastreabilidade dos ativos não deve depender apenas do GPS embarcado. O registro automatizado da localização e da equipe responsável pela movimentação aumenta a confiabilidade das informações e reduz o tempo gasto na localização das repetidoras.', 0, NULL, N'Facilidade de acesso, organização', '2026-07-08T00:00:00.000', '2026-07-09T15:56:42.000', N'81035985', NULL, NULL);
INSERT INTO #PVC VALUES (11092, N'81054395', N'81054395', N'Desenvolvimento do Fluxograma de Inclusão de Materiais em Estoque', 1, N'Open Pit/Poço aberto', N'A ausência de um fluxograma formal para inclusão de materiais em estoque gerava falta de padronização e retrabalho, sendo identificada durante a análise das solicitações de inclusão.', N'Desenvolver e implementar um fluxograma padronizado para o processo de inclusão de materiais em estoque, definindo critérios, responsabilidades e etapas de aprovação.', N'10015', N'01 - Imagens/01 - Antes/11092.jpeg', N'Antes da melhoria, o processo de inclusão de materiais em estoque não possuía padronização, gerando divergências de avaliação, retrabalho e riscos de inclusões desnecessárias em estoque.', N'01 - Imagens/02 - Depois/11092.jpeg', N'Foi criado um fluxograma padronizado para inclusão de materiais em estoque, definindo responsabilidades e critérios de aprovação. ', NULL, N'Sim. O problema foi mitigado com a criação e implementação do fluxograma, que padronizou o processo, definiu responsabilidades e reduziu dúvidas e retrabalhos nas solicitações de inclusão de materiais em estoque.', N'Padronização do processo e definição clara de responsabilidades. Fluxo formal reduz retrabalho e aumenta a governança. Critérios definidos evitam inclusões desnecessárias em estoque. Alinhamento entre áreas melhora a tomada de decisão.', 0, NULL, N'Melhoria na organização do ambiente, facilitando inspeções e elevando o nível de segurança com baixo custo e alto impacto operacional.', '2026-07-08T00:00:00.000', '2026-07-09T16:46:36.000', N'81054395', NULL, NULL);
INSERT INTO #PVC VALUES (11093, N'81054395', N'81054395', N'Desenvolvimento da Matriz RACI do Processo de Inclusão de Materiais em Estoque', 1, N'Open Pit/Poço aberto', N'A ausência de uma definição formal de responsabilidades gerava dúvidas sobre os papéis das áreas no processo de inclusão de materiais em estoque, impactando o alinhamento e a governança.', N'Definir e formalizar os papéis e responsabilidades das áreas envolvidas no processo de inclusão de materiais em estoque.', N'10015', N'01 - Imagens/01 - Antes/11093.jpeg', N'Antes da melhoria, não havia uma definição clara das responsabilidades das áreas envolvidas, gerando divergências de entendimento e retrabalho.', N'01 - Imagens/02 - Depois/11093.jpeg', N'Foi criada uma matriz RACI para formalizar os responsáveis, aprovadores, consultados e informados em cada etapa do processo.', NULL, N'Sim. A matriz RACI definiu claramente os papéis e responsabilidades, reduzindo dúvidas e aumentando a padronização do processo.', N'Clareza de responsabilidades reduz retrabalho. Papéis bem definidos melhoram o alinhamento entre áreas. Governança depende de atribuições formalizadas.', 0, NULL, N'Adequação de suporte de coletores de resíduos, mantendo organização e limpeza na área.
INSERT INTO #PVC VALUES (11094, N'81004462', N'81004462', N'Escaneamento 3D de caçambas', 1, N'Others/Outros', N'O monitoramento de desgaste das caçambas das escavadeiras e carregadeiras de grande portes eram realizados apenas de modo visual, não existindo a mensuração de desgaste das caçambas.', N'Monitoramento sistemático de desgaste', N'10015', N'01 - Imagens/01 - Antes/11094.jpeg', N'Realizado apenas a inspeção sensitiva a cada 125h para avaliação de desgaste das caçambas e definição de troca, ocorrendo projeções de trocas imprecisas.
INSERT INTO #PVC VALUES (11095, N'92000587', N'81002955', N'ESFRIADOR DE PEÇAS', 1, N'Others/Outros', N'era feito resfriamento jogando água em cima da peça,  risco de queimaduras com o vapor da água quente.', N'  REDUZIR RISCOS ', N'10144', N'01 - Imagens/01 - Antes/11095.jpeg', N'Era feito resfriamento jogando água em cima da peça,  risco de queimaduras com o vapor da água quente.', N'01 - Imagens/02 - Depois/11095.jpeg', N'Foi confeccionado um resfriador de peças, eliminado o risco de queimaduras', NULL, N'SIM, ELIMINAÇÃO DE EXPOSIÇAÕ DO COLABORADOR A QUEIMADURAS.', N'IMPORTANCIA DE IDENTIFICAR RISCOS NAS ATIVIDADES ROTINEIRAS ', 0, NULL, N'Redução de custos com reposição e maior agilidade no processo produtivo, além de promover organização e padronização da área.', '2026-05-22T00:00:00.000', '2026-07-09T22:39:26.000', N'92000587', NULL, NULL);
INSERT INTO #PVC VALUES (11096, N'92000587', N'496890', N'ISTALAÇÃO DE SUPORTE PARA ARMAZENAMENTO DE EXTENÇÕES ELETRICAS ', 1, N'Others/Outros', N'CABOS ESPALHADOS PELO CHÃO, DESORGANIZAÇÃO NAS ATIVIDADES', N' ORGANIZAÇÃO E SEGURANÇA ', N'10144', N'01 - Imagens/01 - Antes/11096.jpeg', N'As extensões elétricas utilizadas na tenda de manutenção da perfuratriz no Pátio de Manutenção Mirante permaneciam acondicionadas diretamente no piso, sem local apropriado para armazenamento. Essa condição ocasionava desorganização da área, dificultava o manuseio dos cabos, aumentava o risco de tropeços e quedas, além de contribuir para o desgaste prematuro das extensões devido ao contato constante com o solo e ao armazenamento inadequado', N'01 - Imagens/02 - Depois/11096.jpeg', N'Foi fabricado e instalado um suporte para acondicionamento das extensões elétricas na tenda de manutenção da perfuratriz do Pátio de Manutenção Mirante. Com a implementação da melhoria, os cabos passaram a permanecer organizados, suspensos e de fácil acesso, promovendo maior segurança operacional, redução do risco de acidentes, preservação dos equipamentos e melhoria das condições de organização e padronização da área conforme os princípios do 5S', NULL, N'SIM, AREA MAIS ORGANIZADA , ELIMINANDO RISCOS DE TROPEÇOS, REDUZINDO DESGASTES DAS EXTENSÕES ', N'5´S NAS ATIVIDADES ', 0, NULL, N'Melhor distribuição de peso
INSERT INTO #PVC VALUES (11097, N'92000587', N'547637', N'ILUMINAÇÃO CABINE DA PF1201', 1, N'Others/Outros', N'FALTA DE ILUMINAÇÃO', N'MELHORAR VISIBILIDADE DO OPERADOR ', N'10144', N'01 - Imagens/01 - Antes/11097.jpeg', N'Não havia no equipamento perfuratriz iluminação na parte superior da cabine para auxiliar no momento de posicionar a lança na horizontal para locomoção muito dificuldade devido a visibilidade no horário de turno noturno', N'01 - Imagens/02 - Depois/11097.jpeg', N'instalado um farol na parte superior da cabine com foco de iluminação para parte traseira do equipamento melhorando a visibilidade no momento de posicionar a lança na horizontal.', NULL, N'SIM. MELHORADO VISIBILIDADE DA OPERAÇÃO', N'MELHORA DA VISIBILIDADE', 0, NULL, N'●	Padronização visual para comunicação com a liderança;
INSERT INTO #PVC VALUES (11098, N'521673', N'33019', N'Climatizado para salão de mina', 2, N'No Replication/Sem replicação', N'O climatizador não funcionava de forma eficiente devido à sua instalação em local inadequado.', N'Reduzir a exposição ao calor', N'10366', N'01 - Imagens/01 - Antes/11098.jpeg', N'Anteriormente, o climatizador não era eficaz devido à sua instalação em local inadequado. Além disso, permanecia desligado com frequência porque o dreno enchia, causando acúmulo de água no chão, o que dificultava as atividades da equipe.', N'01 - Imagens/02 - Depois/11098.jpeg', N'O equipamento passou a proporcionar melhor ventilação e conforto térmico aos empregados mais expostos ao calor durante a execução das atividades, contribuindo para a redução da fadiga, maior bem-estar e melhor desempenho operacional.', NULL, N'Sim, A área agora dispõe de um climatizador instalado em local adequado, proporcionando melhor ventilação aos empregados que estão mais expostos ao calor.', N'Local de trabalho deve ter condições ergonômicas adequadas.', 0, NULL, N'Melhorar a organização, disponibilidade e controle das ferramentas de trabalho, reduzindo tempo de busca, evitando perdas/extravio e aumentando a produtividade e segurança da equipe.
INSERT INTO #PVC VALUES (11099, N'550315', N'544865', N'EQUIPAMENTO FULL SERVICE', 1, N'Others/Outros', N'material sendo solicitado para equipamentos de garantia contratualmente ', N'Implementar bloqueio para impedir a abertura de RM (Requisição de Manutenção) corretiva em equipamentos que estejam cobertos por garantia.', N'10234', N'01 - Imagens/01 - Antes/11099.jpeg', N'Identificado solicitação de material para equipamento coberto por garantia.', N'01 - Imagens/02 - Depois/11099.jpeg', N'Implementado o  bloqueio a solicitação de materiais em RMs corretivas para equipamentos cobertos por garantia, garantindo o cumprimento contratual e evitando custos indevidos à empresa.', NULL, N'Problema resolvido com a implementação de bloqueio sistêmico para impedir a abertura de RM corretiva em equipamentos cobertos por garantia, eliminando solicitações indevidas de materiais e assegurando o cumprimento das condições contratuais.', N'Eliminação de solicitações indevidas de materiais para equipamentos em garantia', 0, NULL, N'Em função das notificações lembrarem os responsáveis dos riscos de vencimentos das ações, a expectativa é termos um aumento de aderência.', '2026-07-09T00:00:00.000', '2026-07-10T04:12:26.000', N'550315', NULL, NULL);
INSERT INTO #PVC VALUES (11100, N'400428', N'400428', N'6A clean up clean out', 3, N'Concentration/Concentração', N'6A clean up pump plugged regularly and was difficult to tale apart sections to unsand', N'Easier to clean plugged pump', N'10058', N'01 - Imagens/01 - Antes/11100.jpeg', N'Connections were all vitaulic and had no clean out spots making it difficult to clear line.', N'01 - Imagens/02 - Depois/11100.jpeg', N'Installed a clean out valve and a quick connect fitting up the line for ease of clearing line. ', NULL, N'Yes. It will be easier in the future to clear line. Also, if needed it can be disconnected and reconnected without tools', N'Less chance of fatigue or injury struggling to get line back together', 0, NULL, N'Redução de tempo de análise em função de estar publicado e com o número de páginas e visuais suficientes.
INSERT INTO #PVC VALUES (11101, N'81002390', N'81002390', N'Bancada Movel para corte de Bloco ', 1, N'Others/Outros', N'Não havia local especifico para o corte de blocos, a postura da execução da atividade não era ergonómica.
INSERT INTO #PVC VALUES (11102, N'81046355', N'81002390', N'Misturador de Tinta e Massa ', 1, N'Others/Outros', N'Era usado pedaços de cano ou madeira para realizar a mistura da tinta ou massa que seria usada nas atividades.
INSERT INTO #PVC VALUES (11103, N'81002390', N'81002390', N'Sinalização Removível de Solo ', 3, N'Others/Outros', N'Devido a perda de placas ou as mesmas não estar bem fixada sinalizando o local/material.', N'manter o local ou material sinalizado', N'10361', N'01 - Imagens/01 - Antes/11103.jpeg', N'Devido a perda de muitas placas ou as mesmas não estar bem fixada dava a impressão de desordem no local de trabalho ou ausência de sinalização.
INSERT INTO #PVC VALUES (11104, N'81002390', N'81002390', N'Suporte para BOTAS', 3, N'Others/Outros', N' Ausência de local adequado para armazenamento das botas, risco de animais peçonhentos se alojar no EPI.
INSERT INTO #PVC VALUES (11105, N'81002390', N'81002390', N'Suporte para Extensão', 3, N'Others/Outros', N' Ausência de local adequado para armazenamento das extensões, com cabos dispostos no chão, gerando risco de tropeços, desorganização da área e possibilidade de danos aos equipamentos
INSERT INTO #PVC VALUES (11106, N'81002390', N'81002390', N'Suporte para coletores de residuos', 3, N'Others/Outros', N'Coletores acondicionados diretamente no solo.', N'manter 5S', N'10361', N'01 - Imagens/01 - Antes/11106.jpeg', N'Coletores acondicionados diretamente no solo com avarias.', N'01 - Imagens/02 - Depois/11106.jpeg', N'Adequação de suporte de coletores de resíduos, mantendo organização e limpeza na área.
INSERT INTO #PVC VALUES (11107, N'81029879', N'81029879', N'Controle de Caixas Térmicas', 1, N'No Replication/Sem replicação', N' Dificultando na rastreabilidade das caixas térmicas.', N'Objetivo: melhorar o controle e a rastreabilidade das caixas térmicas', N'10178', N'01 - Imagens/01 - Antes/11107.jpeg', N'As caixas térmicas eram disponibilizadas nas áreas conforme a necessidade das equipes. Porém, devido à falta de um controle formal de movimentação, muitas vezes a localização das caixas acabavam sendo informada apenas por mensagens no WhatsApp, dificultando a rastreabilidade e o acompanhamento atualizado de onde cada unidade se encontra.', N'01 - Imagens/02 - Depois/11107.jpeg', N'Para solucionar essa situação e garantir maior controle, foi criado um acompanhamento para identificarmos, de forma rápida e confiável, a localização atual de cada caixa térmica.
INSERT INTO #PVC VALUES (11108, N'81002390', N'81002390', N'Suporte Móvel para Identificação de Materiais', 3, N'Others/Outros', N'Deficiência na identificação de materiais devido à falta de espaço adequado e ausência de suporte para fixação das placas, gerando desorganização, dificuldade na localização dos materiais a ser utilizado ou descartado. Transporte feito de forma segura, distribuindo o peso e mitigando o risco ergonômico.', N'5S, Sinalização', N'10361', N'01 - Imagens/01 - Antes/11108.jpeg', N'Deficiência na identificação de materiais e ausência de suporte para fixação das placas, gerando desorganização, dificuldade na localização dos materiais a ser utilizado ou descartado. ', N'01 - Imagens/02 - Depois/11108.jpeg', N'Com o suporte móvel para placas de identificação, foi possível posicionar a sinalização diretamente junto aos materiais, garantindo melhor visibilidade, preservação das placas, redução de custos com reposição e maior agilidade no processo produtivo, além de promover organização e padronização da área.', NULL, N'Sim, melhor visibilidade, preservação das placas.', N'Preservação das placas, redução de custos com reposição e maior agilidade no processo produtivo', 0, NULL, N'With larger garbage disposal capacity there is less risk of garbage being stored in improper areas', '2026-04-10T00:00:00.000', '2026-07-10T15:22:06.000', N'81002390', NULL, NULL);
INSERT INTO #PVC VALUES (11109, N'81002390', N'81002390', N'FUNIL LANÇADOR DE CONCRETO', 1, N'Others/Outros', N'Era realizado o carregamento manual de concreto em baldes. Porém, devido o peso e o formato do balde dificultava a atividade laboral e ergonômica, também causando desperdício de material.
INSERT INTO #PVC VALUES (11110, N'81054422', N'81048232', N'Painel de Acompanhamento de Projetos de Engenharia via Power BI (Python', 1, N'Others/Outros', N'Falta de padronização e agilidade no monitoramento da carteira de projetos, com risco de atrasos não percebidos a tempo, ausência de visibilidade sobre custo estimado em aberto e sobrecarga de engenheiros não mapeada', N'Desenvolver e implementar um painel automatizado de acompanhamento da carteira de projetos de engenharia, utilizando Power BI integrado a visuais em Python, com o objetivo de consolidar informações de prazo, custo, status e carga de trabalho em uma única plataforma, aumentando a visibilidade da carteira, agilizando a tomada de decisão, reduzindo atividades manuais de reporte e permitindo a identificação proativa de atrasos, reprogramações e riscos associados aos projetos.', N'10081', N'01 - Imagens/01 - Antes/11110.jpeg', N'O acompanhamento da carteira de projetos de engenharia (aceitos, novos, encerrados) era feito de forma dispersa, sem visão consolidada de prazos, custos e carga de trabalho por engenheiro. Não havia identificação automática de projetos atrasados ou reprogramados, dificultando a priorização e a comunicação de status para a área. A geração de relatórios de acompanhamento dependia de montagem manual, consumindo tempo e sujeita a inconsistências.', N'01 - Imagens/02 - Depois/11110.jpeg', N'Desenvolvimento de um conjunto de visuais Python integrados ao Power BI, aplicados diretamente sobre a base de dados de projetos, contemplando:
INSERT INTO #PVC VALUES (11111, N'544481', N'544481', N'SUPORTE DE FERRAMENTAS ', 2, N'Others/Outros', N'As ferramentas ficavam armazenadas de forma desorganizada, sem identificação adequada e sem controle de uso. Havia dificuldade na localização, perda de tempo durante as atividades e risco de extravio ou uso inadequado.', N'Melhorar a organização, disponibilidade e controle das ferramentas de trabalho, reduzindo tempo de busca, evitando perdas/extravio e aumentando a produtividade e segurança da equipe.', N'10017', N'01 - Imagens/01 - Antes/11111.jpeg', N'As ferramentas ficavam armazenadas de forma desorganizada, sem identificação adequada e sem controle de uso. Havia dificuldade na localização, perda de tempo durante as atividades e risco de extravio ou uso inadequado.', N'01 - Imagens/02 - Depois/11111.jpeg', N'Ferramentas foram organizadas e padronizadas com identificação visual e controle de uso, reduzindo o tempo de busca e aumentando a conservação, eficiência e segurança das atividades.', NULL, N'Melhorar a organização, disponibilidade e controle das ferramentas de trabalho, reduzindo tempo de busca, evitando perdas/extravio e aumentando a produtividade e segurança da equipe.
INSERT INTO #PVC VALUES (11112, N'81063756', N'81063756', N'Abrangência do fluxo de notificação de vencimento de prazos de Ações do Plano Diretor', 1, N'Others/Outros', N'O fluxo de notificação de vencimento de prazos de Ações do Plano Diretor havia sido criado apenas para a gerência de Insp, Confiab e Eng.
INSERT INTO #PVC VALUES (11113, N'81063756', N'81063756', N'Dashboard de Eventos na Mina e Perdas de DF por Paradas de Manutenção', 1, N'No Replication/Sem replicação', N'O time de Confiabilidade de mina utilizava dois Dashboards:
INSERT INTO #PVC VALUES (11114, N'81042217', N'81033125', N'Dispositivo para transporte seguro de amostras de cobre entre a área de coleta e o laboratório', 1, N'Others/Outros', N'As amostras de concentrado de cobre coletadas na área de descarga eram transportadas manualmente até o laboratório para análise de umidade e densidade. Essa condição exigia esforço físico dos colaboradores e aumentava a possibilidade de impactos, movimentação excessiva ou alterações das características da amostra durante o transporte, podendo comprometer a confiabilidade dos resultados analíticos.', N'Reduzir o esforço físico associado ao transporte manual das amostras. Preservar a integridade das amostras durante o deslocamento. Melhorar a confiabilidade dos resultados de umidade e densidade. Aumentar a segurança e ergonomia dos colaboradores. Padronizar o processo de transporte de amostras.', N'10294', N'01 - Imagens/01 - Antes/11114.jpeg', N'Transporte manual das amostras entre o ponto de coleta e o laboratório.
INSERT INTO #PVC VALUES (11115, N'81005555', N'524302', N'Tubo distanciador de ajuste dos mancais ', 1, N'Others/Outros', N'Era necessário ajuda de uma outra pessoa para ajustar os mancais, enquanto um  verificava a medida a ajuda do outro era para segurar a trena e escala.', N'Eliminar a necessidade de duas pessoas para ajustar o distanciamento dos mancais', N'10249', N'01 - Imagens/01 - Antes/11115.jpeg', N'Por diversas vezes era necessário ajuda de outro colega para ajustar os mancais, isso atrasava a atividade dele e acarretava em perca de produtividade para a turma.', N'01 - Imagens/02 - Depois/11115.jpeg', N'Usinado um tubo, que é instalado no furo do graxeiro para serve de guia durante o ajuste, dessa forma não é mais necessário ajuda de outra pessoa para ajustar os mancais, basta rosquear o tubo. ', NULL, N'Foi resolvido e testado na prática, o restante do ajuste foi feito sozinho, somente fazendo uso da ferramenta criada.', N'Fortalecimento do senso de criatividade em prol da melhor distribuição da equipe', 0, NULL, N'para eliminar as possíveis falhas de nível do L/C e da confiabilidade para o equipamento.', '2026-06-17T00:00:00.000', '2026-07-11T02:06:42.000', N'81005555', NULL, NULL);
INSERT INTO #PVC VALUES (11116, N'81005555', N'524302', N'Ferramenta de instalação do retentor do eixo pinhão do diferencial 854k', 1, N'Others/Outros', N'Falta de meios adequados para instalar o retentor, risco de danificar.', N'Criar um dispositivo capaz de instalar o retentor sem danificar', N'10249', N'01 - Imagens/01 - Antes/11116.jpeg', N'Atividade foi paralisada pois o retentor precisava passar por ajustes e principalmente pois o retentor precisava de uma ferramenta específica que garantisse a sua instalação de forma segura.', N'01 - Imagens/02 - Depois/11116.jpeg', N'A ferramenta foi criada, encaixe feito na base do retentor, material leve e com uma boa resistência, feito instalação do retentor com a ferramenta, testado na prática durante a manutenção desse componente. ', NULL, N'Meta foi atingida e a comprovação veio após o teste prático', N'Senso de engajamneto', 0, NULL, N'Acionamento instantâneo. Ao menor sinal de alerta de temporais, qualquer colaborador abre o aplicativo no celular e, com um toque, acende as luzes vermelhas na área. O tempo de resposta caiu para zero, iniciando o processo de abrigo imediatamente', '2026-06-18T00:00:00.000', '2026-07-11T02:18:13.000', N'81005555', NULL, NULL);
INSERT INTO #PVC VALUES (11117, N'81005555', N'524302', N'Ferramenta de remoção dos rolamentos do tambor da TCLD', 1, N'Others/Outros', N'Era extremamente difícil remover os rolamentos do tambor da TCLD, pois é um equipamento de grande porte, na maior parte das vezes era necessário cortar os rolamentos. ', N'Realizar a desmontagem sem precisar bater com marretas no rolamento, de uma forma mais rápida e mais eficiente.', N'10249', N'01 - Imagens/01 - Antes/11117.jpeg', N'Era utilizado uma marreta ou slide para bater no rolamento e dessa forma deslocar da bucha e fazê-lo se soltar do eixo, na maioria das vezes era necessário o uso de oxicorte pois o rolamento é de grande porte.  ', N'01 - Imagens/02 - Depois/11117.jpeg', N'Agora é utilizado pressão hidráulica para desmontar, não é necessário uso do oxicorte, apenas pressão hidráulica que é conduzida até os rasgos da bucha e dessa forma obriga o rolamento se deslocar do eixo.', NULL, N'A meta era desmontar o rolamento de uma outra maneira, mais fácil e com mais comodidade para o executante.', N'Fazendo e acontecendo', 0, NULL, N'REDUÇÃO DE TEMPO AO REALIZAR ATIVIDADE', '2026-06-20T00:00:00.000', '2026-07-11T02:34:30.000', N'81005555', NULL, NULL);
INSERT INTO #PVC VALUES (11118, N'81037761', N'81037761', N'Alarme crítico do Sistema de Despoeiramento Prensagem Salobo IIIParado', 1, N'No Replication/Sem replicação', N'Quando ocorre falha no Sistema de Despoeiramento Prensagem Salobo III não é possível uma identificação rápida do técnico de sala de controle problema devido ausência de alarme crítico.', N'Identificação rápida da falha no Sistema de Despoeiramento da Prensagem Salobo III', N'10025', N'01 - Imagens/01 - Antes/11118.jpeg', N'O Sistema de Despoeiramento da Prensagem foi projetado para operar em modo automático. Contudo, em situações de falha, a Sala de Controle perde a visibilidade operacional do sistema, impossibilitando a identificação imediata de sua condição de operação (em funcionamento ou parado). Além disso, atualmente não existe um alarme crítico que sinalize prontamente essas ocorrências, dificultando o acionamento rápido da cadeia de ajuda para o tratamento da anomalia e o restabelecimento seguro do processo.', N'01 - Imagens/02 - Depois/11118.jpeg', N'Foi implementado um alarme de alerta na tela principal do Sistema Supervisório da Prensagem com o objetivo de notificar imediatamente o técnico de sala sobre eventuais falhas no Sistema de Despoeiramento da Prensagem, possibilitando a rápida avaliação da situação e o acionamento da cadeia de ajuda, quando necessário. Essa iniciativa é fundamental para a mitigação de riscos ambientais e operacionais, prevenindo o acúmulo de poeira em suspensão, que pode comprometer a visibilidade dos operadores em campo e impactar a qualidade do ar respirado, expondo os trabalhadores a condições inseguras.', NULL, N'Alarme implementado e funcional no Sistema Supervisório da Prensagem, com exibição automática na tela principal sempre que ocorrer uma falha no Sistema de Despoeiramento da Prensagem, proporcionando visibilidade imediata da ocorrência e permitindo uma resposta rápida da equipe operacional.', N'Importância do acionamento rápido da cadeia de ajuda reduzem o tempo de resposta, minimizam riscos ambientais e ocupacionais.', 0, NULL, N'Keep on full power', '2026-07-06T00:00:00.000', '2026-07-11T04:42:07.000', N'81037761', NULL, NULL);
INSERT INTO #PVC VALUES (11119, N'1009261', N'1009261', N'Label for HCL samples', 3, N'Refining/Refino', N'sample bottle full of solution with no label', N'identify samples', N'0', N'01 - Imagens/01 - Antes/11119.jpeg', N'Full samples bottles with no label identifying contents', N'01 - Imagens/02 - Depois/11119.jpeg', N'Label to identify the samples ', NULL, N'yes, problem was solved', N'samples need to be identified', 0, NULL, N'To safely take samples.', '2026-06-30T00:00:00.000', '2026-07-11T09:56:54.000', N'1009261', NULL, NULL);
INSERT INTO #PVC VALUES (11120, N'81055041', N'81055041', N'Padronização e Garantia de Registros de Embarque com Uso de Dispositivo Corporativo Dedicado', 1, N'Others/Outros', N'Durante o processo de embarque, foi identificado que não há garantia nem confiabilidade nos volumes registrados sem a evidência formal entre paradas. Os inspetores, embora presentes integralmente na operação, não conseguem se deslocar para realizar os registros nas balanças, gerando lacunas no processo. Além disso, o uso de dispositivos pessoais compromete a padronização, segurança e continuidade das informações entre turnos.
INSERT INTO #PVC VALUES (11121, N'1015684', N'1015684', N'Larger Domestic Waste Bin at Port', 1, N'Refining/Refino', N'The domestic waste bin at Port was undersized, this would lead to excess garbage being kept inside the building, or general waste being disposed of in the contaminated waste bin, resulting in extra costs of disposal for materials not required to be sent off as contaminated.', N'To have a larger general waste bin similar to the metal and wood bins.', N'0', N'01 - Imagens/01 - Antes/11121.jpeg', N'The domestic waste bin at Port was undersized, this would lead to excess garbage being kept inside the building, or general waste being disposed of in the contaminated waste bin, resulting in extra costs of disposal for materials not required to be sent off as contaminated.', N'01 - Imagens/02 - Depois/11121.jpeg', N'Sourced a larger domestic waste bin for use at Port, this will allow us to segregate and dispose of our waste properly and cut down on the cost of contaminated waste disposal.', NULL, N'We estimate that with the larger general waste bin we will be able to divert 3-5 full bins of contaminated waste a year into the proper domestic waste bin.', N'Adding the larger bin has made garbage disposal and segregation better at Port.', 40000, 3, N'Com a instalação de luminária na tenda de material preventiva, eliminando os riscos de animais peçonhentos devido, tropeços, com a iluminação que estava baixa.
INSERT INTO #PVC VALUES (11122, N'81047013', N'472909', N'Dispositivo para abastecimento de óleo no 2051BR01', NULL, N'Others/Outros', N'-Abastecimento realizado diretamente no reservatório.
INSERT INTO #PVC VALUES (11123, N'498359', N'81047016', N'PROTEÇÃO GUARDA CORPO', 2, N'Others/Outros', N'acesso ao fosso estava danificado e sem partes de guarda - corpo causando risco de queda do mesmo nivel, batida contra e afogamento', N'ELIMINAR RISCOS', N'10362', N'01 - Imagens/01 - Antes/11123.jpeg', N'Acesso ao fosso estava danificado e sem partes de guarda - corpo causando risco de queda do mesmo nível, batida contra e afogamento', N'01 - Imagens/02 - Depois/11123.jpeg', N'Foi realizada uma melhoria com a instalação de um guarda-corpo, visando eliminar a condição de risco e prevenir acidentes, como queda de mesmo nível e afogamento, proporcionando mais segurança às pessoas que circulam pela área.', NULL, N'META ATINGIDA COM SUCESSO', N'melhorar ambiente de trabalho', 0, NULL, N'GARANTIR UMA ÁREA DE IÇAMENTO MAIS SEGURA, COM ACESSO CONTROLADO E DEVIDAMENTE ISOLADO  DURANTE A MOVIMENTAÇÃO DE CARGAS, REDUZINDO O RISCO DE ACIDENTES, PROTEGENDO OS COLABORADORES E PROMOVENDO MAIOR SEGURANÇA E ORGANIZAÇÃO NAS OPERAÇÕES DE RECEBIMENTOS DE MATERIAIS', '2026-07-10T00:00:00.000', '2026-07-11T17:31:39.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (11124, N'498359', N'81061120', N'PROTEÇÃO GUARDA-CORPO', 2, N'Others/Outros', N'TUBULAÇÃO PROXIMO DA CELULA RADIOATIVA ESTAV SEM PARTES DO GUARDA CORPO CAUSANDO RISCO DE QUEDA DE MESMO NIVEL.', N'ELIMINAR RISCO ', N'10362', N'01 - Imagens/01 - Antes/11124.jpeg', N'TUBULAÇÃO PROXIMO DA CELULA RADIOATIVA ESTAV SEM PARTES DO GUARDA CORPO CAUSANDO RISCO DE QUEDA DE MESMO NIVEL.', N'01 - Imagens/02 - Depois/11124.jpeg', N'FOI RECUPERADO A PROTEÇÃO GUARDA CORPO DA TUBULAÇÃO DA BOMBA DE POLPA ELIMINANDO RISCO DE QUEDA DE MESMO NIVEL', NULL, N'META ATINGIDA', N'MELHORAR AMBIENTE DE TRABALHO', 0, NULL, N'Melhorar o monitoramento operacional por meio da visualização em tempo real da corrente dos alimentadores, permitindo a identificação rápida de desvios, maior controle do processo e aumento da eficiência operacional.', '2026-07-10T00:00:00.000', '2026-07-11T17:39:36.000', N'498359', NULL, NULL);
INSERT INTO #PVC VALUES (11125, N'81047013', N'81056636', N'PORTINHOLA DE PROTEÇÃO - ACESSO AO SENSOR DE VELOCIDADE 2301BR01', NULL, N'Others/Outros', N'Para acessar o sensor de velocidade do rebritador, era necessário tirar bloquear e tirar toda a proteção das correias de acionamento, demandando mais tempo e esforço dos colaboradores.', N'Implementar barreira de proteção entre partes moveis e permitir o acesso rápido ao sensor em caso de parada', N'10362', N'01 - Imagens/01 - Antes/11125.jpeg', N'Para acessar o sensor de velocidade do rebritador, era necessário tirar bloquear e tirar toda a proteção das correias de acionamento, demandando mais tempo e esforço dos colaboradores. ', N'01 - Imagens/02 - Depois/11125.jpeg', N'Fabricada uma portinhola de acesso, mantendo a barreira fisica nas partes moveis mas possibilitando o acesso ao sensor caso necessário', NULL, N'Meta alcançada 100%', N'Facilitar o acesso mantendo a segurança', 0, NULL, N'plate can''t be dropped now', '2026-07-06T00:00:00.000', '2026-07-11T17:49:00.000', N'81047013', NULL, NULL);
INSERT INTO #PVC VALUES (11126, N'81052181', N'514016', N'Passaporte de Emergência do Colaborador – Identificação Rápida de Informações Críticas de Saúde', 1, N'Others/Outros', N'Atualmente, os colaboradores possuem apenas o passaporte de treinamentos, não existindo um meio padronizado e de fácil acesso para disponibilizar informações essenciais de saúde em situações de emergência. ', N'Desenvolver e implantar um Passaporte de Emergência do Colaborador, contendo informações críticas de saúde e contato, de forma padronizada, prática e acessível, visando agilizar o atendimento em situações de emergência, apoiar a tomada de decisão das equipes de resgate e contribuir para a segurança e preservação da vida dos colaboradores.', N'10245', N'01 - Imagens/01 - Antes/11126.jpeg', N'Os colaboradores possuíam apenas o passaporte de treinamentos, sem um documento com informações essenciais de saúde para consulta rápida em situações de emergência.', N'01 - Imagens/02 - Depois/11126.jpeg', N'Implantação do Passaporte de Emergência, reunindo informações críticas de saúde e contatos em um único documento, permitindo atendimento mais rápido, seguro e eficiente.', NULL, N'Meta: Disponibilizar um passaporte com informações essenciais de saúde para todos os colaboradores.
INSERT INTO #PVC VALUES (11127, N'81042202', N'81010117', N'Mangueira de ar comprimido', 2, N'Others/Outros', N'
INSERT INTO #PVC VALUES (11128, N'81059721', N'552496', N'ALINHAMENTO DO SENSOR DE NÍVEL DO L/C', NULL, N'Others/Outros', N'O chicote do sensor de nível do L/C estava com várias, e ocasionando ocorrências de baixo nível devido o chicote se rompendo, ocasionando parada do equipamento', N'evitar parada do equipamento, redução de custos e tempo', N'10144', N'01 - Imagens/01 - Antes/11128.jpeg', N'O chicote do sensor de nível do L/C estava com várias, e ocasionando ocorrências de baixo nível devido o chicote se rompendo, ocasionando parada do equipamento.
INSERT INTO #PVC VALUES (11129, N'81059721', N'545523', N'IMPLEMENTAÇÃO DE ALERTA REMOTO PARA DESCARGAS ATMOSFÉRICAS - VIA WI-FI', 2, N'Projects/Projetos', N'a informação dependia do repasse manual. O operador precisava se deslocar até um painel físico para ligar um alarme ou avisar os grupos de boca em boca. Segundos preciosos eram perdidos na comunicação.
INSERT INTO #PVC VALUES (11130, N'81022743', N'81006537', N'PROTEÇÃO PARA PARTE ROTATIVA DA BOMBA DO ACOPLAMENTO', 1, N'Open Pit/Poço aberto', N'EXPOSIÇÃO DE MÃOS E DEDOS A PARTES ROTATIVAS DA BOMBA DO ACOPLAMENTO ', N'EVITAR CONTATO COM PARTES ROTATIVAS DA BOMBA DO ACOPLAMENTO', N'10144', N'01 - Imagens/01 - Antes/11130.jpeg', N'NÃO TINHA PROTEÇÃO NA PARTE ROTATIVA DA BOMDA DO ACOMPLAMENTO, O COLABORADOR ERA EXPOSTO A CORTE, E ESMAGAMENTO  DE MEMBROS. ', N'01 - Imagens/02 - Depois/11130.jpeg', N'CRIAMOS UMA PROTEÇÃO PARA PARTE ROTATIVA DA BOMBA, EVITANDO CONTATO COM OS MEMBROS DOS COLABORADORES, ELIMINANDO O RISCO DE CORTE, E ESMAGAMENTO! PROPORCIONAMENTO REALIZAR ATIVIDADE COM SEGURANÇA E AGILIDADE. ', NULL, N'PROBLEMA ELIMINADO, POIS NÃO TEM MAIS CONATATO COM MEMBROS DOS COLABORADORES.', N'EVITAR CONTATO COM PARTES ROTATIVAS ', 0, NULL, N'Reduzindo o tempo de limpeza;
INSERT INTO #PVC VALUES (11131, N'1008564', N'1009524', N'Avoid high Anolyte Temperature', 1, N'Refining/Refino', N'Powering down from 24000A due to high anolyte temp, ', N'Avoid the anolyte temperatures from exceeding 60 degrees and keeps us at full power', N'0', N'01 - Imagens/01 - Antes/11131.jpeg', N'The Anolyte temperature was exceeding 60 degrees and causing us to reduce power. ', N'01 - Imagens/02 - Depois/11131.jpeg', N'Lowered the Bay Heat Exchangers cooling water setpoints from 52 down to 50.5 degrees', NULL, N'yes', N'Keep temperature down to keep from staying om full power', 0, NULL, N'diminui o tempo de parada do equipamento e aumenta a confiabilidade operacional do sistema de refugo de bolas dos moinhos.', '2026-07-11T00:00:00.000', '2026-07-12T07:48:41.000', N'1008564', NULL, NULL);
INSERT INTO #PVC VALUES (11132, N'81062686', N'81062686', N'Sample information and PPE', 2, N'Others/Outros', N'There were no safety information or proper gloves at the sample point.', N'To provide necessary details and PPE to safely take samples.', N'10212', N'01 - Imagens/01 - Antes/11132.jpeg', N'No safety information and no proper gloves. ', N'01 - Imagens/02 - Depois/11132.jpeg', N'Added safety information and proper PPE.', NULL, N'Yes, necessary details and PPE to safely take samples have been added.', N'N/A', 0, NULL, N'CO2 emission could be reduced 126 Kg per year.', '2026-07-11T00:00:00.000', '2026-07-12T08:10:35.000', N'81062686', NULL, NULL);
INSERT INTO #PVC VALUES (11133, N'81056513', N'81047889', N'SUPORTE PROPULSSORAS DE GRAXA', 3, N'Others/Outros', N'Antes as propulssoras de graxa não tinha local adequado ficava num canto no boxe em cima de paletes.', N'Organização e padrão 5s', N'10324', N'01 - Imagens/01 - Antes/11133.jpeg', N'Antes as propulssoras de graxa não tinha local adequado ficava num canto no boxe em cima de paletes.', N'01 - Imagens/02 - Depois/11133.jpeg', N'Com aplicação de suporte agora propulssoras possuem local seguro e adequado para armazenamento', NULL, N'Desorganização e poluição de cenario com propulsorras mal armazenadas', N'5s', 0, NULL, N'Disponibilizar informações gerenciais de forma rápida e confiável, eliminando atividades manuais de consolidação de dados e permitindo o monitoramento contínuo dos principais indicadores de manutenção da frota.', '2026-07-11T00:00:00.000', '2026-07-12T11:50:38.000', N'81056513', NULL, NULL);
INSERT INTO #PVC VALUES (11134, N'81059721', N'552496', N'ILUMINAÇÃO NA TENDA DE MATERIAL - PREVENTIVA', 3, N'Others/Outros', N'O local possuía baixa  iluminação na tenda de material preventiva pátio Mirante, dificultando visibilidade e aumentando o risco de acidentes com risco animais peçonhentos..
INSERT INTO #PVC VALUES (11135, N'81059721', N'552496', N'INSTALAÇÃO DA LUMINÁRIA NA PARTE INTERNA DA CABINE', 1, N'Others/Outros', N'a falta de iluminação na cabine impossibilitando a  visibilidade dos botões de acionamento do caminhão, e tropeço dentro da cabine por não visualizar a parte interna do mesmo.', N'Segurança, melhor visibilidade, ter qualidade principalmente em  turnos noturnos que precisam de visibilidade ', N'10144', N'01 - Imagens/01 - Antes/11135.jpeg', N'Não existia iluminação interna na cabine do operador, impossibilitando a  visibilidade dos botões de acionamento do caminhão, e tropeço dentro da cabine por não visualizar a parte interna do mesmo.
INSERT INTO #PVC VALUES (11136, N'81046953', N'81055527', N'INSTALAÇÃO DE PORTÃO DE SEGURANÇA NA ÁREA DA PONTE PARA RECEBIMENTO E IÇAMENTO DE MATERIAIS', 2, N'Others/Outros', N'A ÉRA DA PONTE DESTINADA AO RECEBIMENTO E IÇAMENTO DE MATERIAIS NÃO POSSUIA PORTÃO DE ISOLAMENTO. ISSO PERMITIA O ACESSO DE PESSOAS DURANTE A MOVIMENTAÇÃO DE CARGAS, AUMENTANDO O RISCO DE ACIDENTES, COMO ATIGIMENTO POR CARGAS SUSPENSAS E ACESSO NÃO AUTORIZADO Á ÁREA OPERACIONAL.', N'INSTALAR UM PORTÃO DE SEGURANÇA NA ÁREA DA PONTE PARA CONTROLAR O ACESSO DURANTE O RECEBIMENTO E O IÇAMENTO DE MATERIAIS, ELIMINANDO EXPOSIÇÃO DOS COLABORADORES AOS RISCOS DE CARGAS SUSPENSAS, AUMENTANDO A SEGURANÇA OPERACIONAL GARANTINDO UMA ÁREA DE TRABALHO MAIS ORGANIZADA E SEGURA', N'10362', N'01 - Imagens/01 - Antes/11136.jpeg', N'A ÁREA DA PONTE DESTINADA AO RECEBIMENTO E IÇAMENTO DE MATERIAL NÃO POSSUÍA PORTÃO DE ISOLAMENTO. ISSO PERMITIA O ACESSO DE PESSOAS DURANTE A MOVIMENTAÇÃO DE CARGAS, AUMENTANDO O RISCO DE ACIDENTES, COMO ATINGIMENTO POR GARGAS SUSPENSAS E ACESSO NÃO AUTORIZADO Á ÁREA OPERACIONAL.', N'01 - Imagens/02 - Depois/11136.jpeg', N'A INSTALAÇÃO DO PORTÃO ELIMINA UMA CONDIÇÃO INSEGURA AO IMPEDIR O ACESSO DE PESSOAS DURANTE A MOVIMENTAÇÃO DE CARGAS SUSPENSAS, REDUZINDO SIGNIFICATIVAMENTE O RISCO DE ACIDENTES. ALÉM DISSO, FORTALECE O CONTROLE DA ÁREA, ATENDENDO ÁS BOAS PRÁTICAS DE SEGURANÇA OPERACIONAL E PRESERVANDO A INTEGRIDADE FÍSICA DOS TRABALHADORES.', NULL, N'A ÁREA DA PONTE NÃO NÃO POSSUÍA PORTÃO DE ISOLAMENTO, PERMITINDO O ACESSO DE PESSOAS DURANTE O RECEBIMENTO DE MATERIAL, COM A INSTALAÇÃO DO PORTÃO, O ACESSO PASSOU A SER CONTROLADO E Á ÁREA FICOU DEVIDAMENTE ISOLADA DURANTE  AS OPERAÇÕES DE IÇAMENTO, A MELHORIA ATENDEU Á META ESTABELECIDA, REDUZIDO A EXPOSIÇÃO AOS RISCOS, AUMENTANDO A SEGURANÇA DOS COLABORADORES E PROPORCIONANDO MAIOR CONTROLE.', N'A IDENTIFICAÇÃO E ELIMINAÇÃO DE CONDIÇÕES INSEGURAS ANTES DA EXECUÇÃO DAS ATIVIDADES REDUZEM SIGNIFICAMENTE OS RISCOS DE ACIDENTES ', 0, NULL, N'Risk of process upset requiring manual intervention and downtime is reduced.', '2026-07-09T00:00:00.000', '2026-07-12T17:56:20.000', N'81046953', NULL, NULL);
INSERT INTO #PVC VALUES (11137, N'81037761', N'516643', N'Disponibilização da corrente do alimentadores da Pilha Primária Salobo III na tela do Supervisório', 1, N'No Replication/Sem replicação', N'Atualmente, a tela do supervisório não apresenta a corrente dos alimentadores da Pilha Primária Salobo III, o que dificulta a rápida avaliação das condições operacionais e o monitoramento do desempenho dos equipamentos pelos técnicos de sala de controle.', N'Visualização rápida da corrente dos alimentadores da Pilha Primária Salobo III', N'10025', N'01 - Imagens/01 - Antes/11137.jpeg', N'A tela do supervisório do Circuito de Britagem Primária Salobo III não apresenta a corrente dos alimentadores, o que dificulta a rápida avaliação das condições operacionais e o monitoramento do desempenho dos equipamentos pelos operadores.', N'01 - Imagens/02 - Depois/11137.jpeg', N'Foi incluída na tela do supervisório a indicação da corrente dos alimentadores da Pilha Primária Salobo III, proporcionando ao técnico de Sala de Controle maior visibilidade das condições operacionais permitindo uma análise mais rápida e eficiente da operação pelos técnicos.', NULL, N'Com a indicação da corrente dos alimentadores da Pilha Primária Salobo III, o técnico de sala de controle tem maior visibilidade das condições operacionais permitindo uma análise mais rápida e eficiente da operação pelos técnicos.', N'Contribuir para a identificação de oportunidades de melhoria e favorecendo análises mais assertivas e tomadas de decisão mais ágeis.', 0, NULL, N'Foi implantada a abraçadeira de identificação do programa Padrinho e Afilhado, proporcionando melhor acompanhamento, integração e comunicação entre os colaboradores. Desta forma, as pessoas conseguem identificar os colaboradores novatos em nossas operações. ', '2026-07-06T00:00:00.000', '2026-07-13T00:36:18.000', N'81037761', NULL, NULL);
INSERT INTO #PVC VALUES (11138, N'81062454', N'81062454', N'wire for deflector plate', 1, N'Others/Outros', N'deflector plate wasn''t secured so it could fall into the bin i fdropped', N'secure so it can not be dropped', N'10271', N'01 - Imagens/01 - Antes/11138.jpeg', N'plate not secured', N'01 - Imagens/02 - Depois/11138.jpeg', N'used wire to attach plate', NULL, N'wire stops plate from being able to be dropped', N'plate can''t be dropped into bin', 0, NULL, N'Aumento da confiabilidade das informações', '2026-07-12T00:00:00.000', '2026-07-13T02:35:00.000', N'81062454', NULL, NULL);
INSERT INTO #PVC VALUES (11139, N'1010605', N'1010605', N'Fan for feed bin whipping', 2, N'Others/Outros', N'During the summer months the bin whip location is to warm to be staying up at for long periods of time. The area is 8+ stories up and requires full PPE, so is very warm even during the winter months.', N'Reduce heat exhaustion at bin whip controls', N'10271', N'01 - Imagens/01 - Antes/11139.jpeg', N'Area is very hot, especially during summer. No nearby areas to cool down.', N'01 - Imagens/02 - Depois/11139.jpeg', N'Large fan added to keep heat at bay.', NULL, N'YES, area is much more reasonable to be in for extended periods of time.', N'We need more fans', 0, NULL, NULL, '2026-07-12T00:00:00.000', '2026-07-13T02:35:31.000', N'1010605', NULL, NULL);
INSERT INTO #PVC VALUES (11140, N'81062454', N'81062454', N'mounting hose rack', 1, N'Others/Outros', N'previous mount kept detaching from wall', N'to keep mount from detaching from wall', N'10271', N'01 - Imagens/01 - Antes/11140.jpeg', N'mount was installed with self tapping screws which over time would pull out of wall', N'01 - Imagens/02 - Depois/11140.jpeg', N'mount was secured with bolt and nut', NULL, N'bolt and nut can''t detach from wall', N'bolt works better then screw', 0, NULL, N'Better housekeeping, knowing where items are stored that are currently not in use', '2026-07-12T00:00:00.000', '2026-07-13T02:43:30.000', N'81062454', NULL, NULL);
INSERT INTO #PVC VALUES (11141, N'81062454', N'81062454', N'marker holder', 1, N'No Replication/Sem replicação', N'nowhere to put markers', N'have markers in good location for use', N'10271', N'01 - Imagens/01 - Antes/11141.jpeg', N'no holder for markers', N'01 - Imagens/02 - Depois/11141.jpeg', N'holder now in spot where they are needed', NULL, N'markers will be where needed', N'markers are easier to find when in holder', 0, NULL, NULL, '2026-07-12T00:00:00.000', '2026-07-13T02:51:14.000', N'81062454', NULL, NULL);
INSERT INTO #PVC VALUES (11142, N'81037761', N'516643', N'Disponibilização da corrente do alimentadores da Secundária Salobo III na tela do Supervisório', 1, N'No Replication/Sem replicação', N'A tela do supervisório do Circuito de Britagem Secundária Salobo III não apresenta a corrente dos alimentadores da Pilha Secundária, o que dificulta a rápida avaliação das condições operacionais e o monitoramento do desempenho dos equipamentos pelos operadores.
INSERT INTO #PVC VALUES (11143, N'496936', N'496936', N'Barra distribuidora de ar comprimido ', 2, N'Others/Outros', N'A limpeza de pó na área da Calcinação e Forno Redução é realizada utilizando um equipamento confeccionado em cano de PVC com apenas uma saída de ar comprimido. No entanto ha uma baixa eficiência de limpeza, pois apenas uma saída de ar cobre uma pequena área por vez, ocasionando maior esforço físico e ergonômico do operador, devido à necessidade de movimentar continuamente,', N'Projetar e implementar uma Barra Distribuidora de Ar Comprimido em PVC com saídas de ar estrategicamente distribuídas e duas rodinhas de apoio na barra horizontal, permitindo o deslocamento suave sobre o piso. A barra distribuidora tem como finalidade remover poeira, acúmulo finos de minério e outros resíduos de áreas industriais, reduzindo o tempo de limpeza, o consumo de ar comprimido e a exposição dos colaboradores a riscos ergonômicos e operacionais.', N'10049', N'01 - Imagens/01 - Antes/11143.jpeg', N'Atualmente, a limpeza de pó na área da Calcinação e Forno Redução é realizada utilizando um equipamento confeccionado em cano de PVC com apenas uma saída de ar comprimido. O operador direciona o jato de ar manualmente sobre o piso para remover o material particulado acumulado.
INSERT INTO #PVC VALUES (11144, N'81022574', N'81022574', N'Melhoria na Detecção de Falhas da TR-2305SA-04 através de Alarme na Sala de Controle', 1, N'Others/Outros', N'Anteriormente, quando a TR-2305SA-04 parava, a informação permanecia em uma área da tela da sala de controle com pouca visibilidade, dificultando a percepção imediata do evento pelo técnico. Como resultado, o equipamento frequentemente permanecia parado por períodos prolongados até que a condição fosse identificada e tratada, gerando impactos na operação.', N'Que o Tecnico de sala consiga visualizar de forma rapida a parada da TR-2305SA-04', N'10051', N'01 - Imagens/01 - Antes/11144.jpeg', N'Anteriormente, quando a TR-2305SA-04 parava, a informação permanecia em uma área da tela da sala de controle com pouca visibilidade, dificultando a percepção imediata do evento pelo técnico. Como resultado, o equipamento frequentemente permanecia parado por períodos prolongados até que a condição fosse identificada e tratada, gerando impactos na operação.', N'01 - Imagens/02 - Depois/11144.jpeg', N'Para eliminar essa dificuldade, foi desenvolvida em conjunto com a equipe de Automação uma lógica de alarme que exibe uma falha de forma destacada na tela da sala de controle sempre que a TR-2305SA-04 é interrompida. Com essa melhoria, o técnico passa a ter visibilidade imediata da ocorrência, podendo acionar rapidamente o operador de área e solicitar apoio com maior prontidão. Essa ação reduz significativamente o tempo de resposta, diminui o tempo de parada do equipamento e aumenta a confiabilidade operacional do sistema de refugo de bolas dos moinhos.', NULL, N'Sim, pois conseguimos melhorar a prontidão operacional devido o técnico de sala ter visibilidade rápida da falha quando a TR-2305SA-04 para', N'Melhoria no processo', 0, NULL, N'Atendimento ao requisito do procedimento operacional.
INSERT INTO #PVC VALUES (11145, N'87000312', N'87000312', N'Reducing CO2 emissions through the introduction of EV trucks', 1, N'Others/Outros', N'Using petrol car was exhausting a lot of CO2', N'Reduction of CO2 emissions', N'0', N'01 - Imagens/01 - Antes/11145.jpeg', N'All the company car was petrol car. Using petrol car was exhausting a lot of CO2', N'01 - Imagens/02 - Depois/11145.jpeg', N'One of the company car changed from petrol car to EV car. As a result, CO2 emission could be reduced.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'O resultado alcançado é maior acompanhamento do sistema Dynamox com gestão a vista podemos acompanhar através de gráficos no Bi ', '2026-07-12T00:00:00.000', '2026-07-13T07:24:34.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11146, N'549252', N'549252', N'Dashboard Automatizado para Gestão de Ocorrências de Manutenção da Frota', 1, N'Others/Outros', N'A ausência de uma ferramenta automatizada para análise das ocorrências de manutenção gerava retrabalho na consolidação dos dados, dificultava o monitoramento dos indicadores de desempenho da frota e limitava a rapidez na identificação de desvios e oportunidades de melhoria.', N'Reduzir o esforço manual no tratamento de dados de manutenção, disponibilizando indicadores em tempo real por meio de dashboard automatizado, aumentando a produtividade da equipe e a qualidade das análises operacionais.', N'10171', N'01 - Imagens/01 - Antes/11146.jpeg', N'O controle das ocorrências de manutenção era realizado por meio de uma planilha básica, com baixa padronização e limitada capacidade de análise. A consolidação das informações era realizada manualmente, demandando tempo para atualização dos dados e elaboração de relatórios. A ausência de indicadores automáticos e painéis gerenciais dificultava a identificação rápida dos principais desvios, equipamentos com maior recorrência de falhas e tendências das ocorrências de manutenção, aumentando o esforço operacional e o risco de inconsistências nas análises.', N'01 - Imagens/02 - Depois/11146.jpeg', N'Foi desenvolvida uma nova estrutura de banco de dados padronizada e um dashboard automatizado para monitoramento das ocorrências de manutenção da frota. A solução permite a atualização rápida das informações e a geração automática de indicadores estratégicos, como quantidade de ocorrências, equipamentos com mais paradas, distribuição por tipo de ocorrência, responsáveis e tendências mensais. A melhoria reduziu atividades manuais, aumentou a confiabilidade dos dados, trouxe maior agilidade na geração de relatórios e forneceu suporte mais eficiente para a tomada de decisão da gestão de manutenção.', NULL, N'SIM. O problema foi mitigado por meio da criação de uma nova estrutura de banco de dados e de um dashboard automatizado. A solução eliminou grande parte do trabalho manual de consolidação e análise das informações, proporcionando maior agilidade na geração de relatórios, aumento da confiabilidade dos dados e melhor acompanhamento dos indicadores de manutenção.', N'Automação e padronização de dados aumentam significativamente a confiabilidade das informações, reduzem retrabalhos e permitem maior agilidade na geração de indicadores para tomada de decisão.', 0, NULL, N'aumento da segurança operacional e redução do risco químico,
INSERT INTO #PVC VALUES (11147, N'544481', N'544481', N'PROTETOR DE FOICE ', 2, N'Others/Outros', N'As foices eram transportadas e armazenadas sem proteção na lâmina, ficando expostas. Isso gerava risco elevado de cortes durante o manuseio, transporte e deslocamento da equipe, além de maior desgaste da lâmina por contato com outras superfícies.', N'Aumentar a segurança dos colaboradores durante o transporte e armazenamento da foice, prevenindo acidentes com cortes, além de garantir melhor conservação da lâmina.', N'10017', N'01 - Imagens/01 - Antes/11147.jpeg', N'As foices eram transportadas e armazenadas sem proteção na lâmina, expondo trabalhadores a cortes durante o manuseio e deslocamento, além de acelerar o desgaste do equipamento.', N'01 - Imagens/02 - Depois/11147.jpeg', N'Foi implantado protetor de lâmina para foice, reduzindo riscos de acidentes no transporte e armazenamento, aumentando a segurança dos colaboradores e a vida útil da ferramenta.', NULL, N'SIM, Foi implantado o uso de protetor de lâmina para foice, confeccionado com material resistente e de fácil encaixe. Com isso, a lâmina permanece protegida durante o transporte e armazenamento, reduzindo significativamente o risco de acidentes, melhorando a segurança dos colaboradores e aumentando a vida útil da ferramenta.', N'Segurança', 0, NULL, N'Maior disponibilidade dos canhões de lavagem.
INSERT INTO #PVC VALUES (11148, N'544481', N'544481', N'SUPORTE PARA LAVA OLHOS PORTÁTIL  ', 2, N'Others/Outros', N'O lava-olhos portátil ficava armazenado em locais improvisados ou sem identificação com dificuldade de acesso rápido em situações de emergência. ', N'Garantir 100% de disponibilidade e acesso rápido ao lava-olhos portátil em áreas com risco de contato químico, promovendo organização, padronização e segurança operacional.', N'10017', N'01 - Imagens/01 - Antes/11148.jpeg', N' O lava-olhos portátil ficava armazenado em locais improvisados ou sem identificação com dificuldade de acesso rápido em situações de emergência. ', N'01 - Imagens/02 - Depois/11148.jpeg', N'Foi implantado protetor de lâmina para foice, reduzindo riscos de acidentes no transporte e armazenamento, aumentando a segurança dos colaboradores e a vida útil da ferramenta.', NULL, N'Foi Implantado um  suporte fixo e identificado para armazenamento do lava-olhos portátil, o equipamento fica  posicionado em local estratégico e de fácil acesso.
INSERT INTO #PVC VALUES (11149, N'1010304', N'1010304', N'Change 150-CVF-001 vibrator timing', 1, N'Crusher/Britadeira', N'Vibrator timing sequence was a fixed interval, ~20 minutes between cycles. This led to buildup and potential plugging of the grizzly and belt area. CRT were running vibrators in manual mode for more frequent cycles.', N'Improve circuit performance, reduce plugging', N'0', N'01 - Imagens/01 - Antes/11149.jpeg', N'Vibrator timing sequence was a fixed interval, ~15 minutes between cycles. The timing could mean that, at higher production rates (46tph and higher), there was potential for multiple buckets to be dumped into the grizzly in between vibrator cycles. This led to buildup and potential plugging of the grizzly and belt area. CRT were running vibrators in manual mode for more frequent cycles.', N'01 - Imagens/02 - Depois/11149.jpeg', N'Suggested tying vibrator cycle interval to match bucket timing number that is entered by CRTs.
INSERT INTO #PVC VALUES (11150, N'544481', N'544481', N'ABRAÇADEIRA PADRINHO/AFILHADO ', 1, N'Others/Outros', N'Não havia identificação visual entre padrinhos e afilhados, dificultando o acompanhamento e a integração dos colaboradores nas atividades operacionais. Os colaboradores antigos não identificavam os colaboradores recente na área. A apresentação dos mesmo, eram feitas através de DSS. ', N'Fortalecer a cultura de segurança e a integração entre colaboradores através do programa “Padrinho e Afilhado.', N'10017', N'01 - Imagens/01 - Antes/11150.jpeg', N'Não havia identificação visual entre padrinhos e afilhados, dificultando a integração e o acompanhamento. Colaboradores experientes não identificavam facilmente os recém-chegados à área.', N'01 - Imagens/02 - Depois/11150.jpeg', N'Foi implantada a abraçadeira de identificação do programa Padrinho e Afilhado, facilitando a identificação dos novatos e melhorando a integração, comunicação e acompanhamento.', NULL, N'Foi implantada a abraçadeira de identificação do programa Padrinho e Afilhado, proporcionando melhor acompanhamento, integração e comunicação entre os colaboradores. Desta forma, as pessoas conseguem identificar os colaboradores novatos em nossas operações. ', N'Acompanhamento -identificação', 0, NULL, N'Maior rastreabilidade do material limonítico segregado.', '2026-06-02T00:00:00.000', '2026-07-13T11:14:27.000', N'544481', NULL, NULL);
INSERT INTO #PVC VALUES (11151, N'81006667', N'81006667', N'Power Bi de Treinamentos', 1, N'Others/Outros', N'Antes tinha um power bi de treinamentos, porém com a mudança de sistema do RH houve uma atualização na base de relatórios tornando o bi que existia ineficaz. ', N'Criar Bi de treinamentos para gerência', N'10054', N'01 - Imagens/01 - Antes/11151.jpeg', N'Existia um painel Power BI para acompanhamento dos treinamentos dos colaboradores. Entretanto, após a mudança do sistema de RH, houve atualização na estrutura e na base de dados dos relatórios, tornando o dashboard existente obsoleto e ineficaz para o monitoramento das informações de treinamento.', N'01 - Imagens/02 - Depois/11151.jpeg', N'Foi criado um novo Power BI integrado à base de dados atual do sistema de RH, permitindo o acompanhamento eficiente dos treinamentos dos colaboradores. A ferramenta trouxe maior confiabilidade das informações, atualização automática dos dados e melhor gestão das capacitações.', NULL, N'A meta foi alcançada com a criação de um novo painel, permitindo novamente o acompanhamento eficiente e atualizado dos treinamentos dos colaboradores.', N'manter os relatórios e dashboards alinhados às mudanças dos sistemas corporativos', 0, NULL, N'Maior segurança para os colaboradores e seus pertences;
INSERT INTO #PVC VALUES (11152, N'81057857', N'81057857', N'Auto Lubber Upgrade, Filter Press 4', 1, N'Refining/Refino', N'issue - grease system was not providing adequate grease to bearings.
INSERT INTO #PVC VALUES (11153, N'1008370', N'1008370', N'Salt bucket storage', 1, N'Others/Outros', N'POL storage room was messy, unorganized and not meeting 5S standards ', N'Organization', N'0', N'01 - Imagens/01 - Antes/11153.jpeg', N'Clutter, items stored overhead, no organization.', N'01 - Imagens/02 - Depois/11153.jpeg', N'All items reorganized and overhead storage removed.
INSERT INTO #PVC VALUES (11154, N'503436', N'503436', N'MONITORAMENTO DE TEMPERATURA DOS ACUMULADORES DE FREIO DE PISTÃO', 1, N'Others/Outros', N'Foi realizada a instalação de sensores de temperatura Dynamox no acumulador de freio do caminhão Komatsu 830E, com o objetivo de monitorar continuamente a condição operacional do componente. Durante o acompanhamento dos dados, foi identificada uma elevação da temperatura no acumulador, condição diretamente relacionada ao aumento da pressão do gás em seu interior. Quando o sensor Dynamox através do gráfico de tendência apresenta dados de criticidade alta podemos identificar na tela do CMA da mina condições anormais nos pistões e evitar falha na direção do equipamento com paradas não planejadas.', N'MONITORAR TEMPERATURAS ELEVADAS DOS ACUMULADORES DE FREIO DE PISTÃO', N'10024', N'01 - Imagens/01 - Antes/11154.jpeg', N'Os acumuladores de freio de pistão do caminhão Komatsu 830 E apresentaram altas temperaturas e paradas não planejadas em corretiva devido ao endurecimento do volante da direção do operador na mina. Condição essa devido a vazamentos dentro do componente e alta temperatura e sem condições de operação em mina para movimentar o equipamento.', N'01 - Imagens/02 - Depois/11154.jpeg', N'Através da instalação dos sensores de temperatura Dynamox TC Ag nos acumuladores de freio de pistão, é possível monitorar continuamente a evolução da temperatura desses componentes. O sistema permite a configuração de parâmetros de alerta e criticidade, gerando alarmes automáticos quando são identificadas elevações anormais de temperatura. Além disso, os dados podem ser visualizados no CMA da mina, possibilitando o acompanhamento da condição do equipamento e a emissão de laudos técnicos que subsidiem a programação de paradas planejadas para inspeção e manutenção, reduzindo o risco de falhas e aumentando a confiabilidade operacional.', NULL, N'Antes da implantação dos sensores Dynamox TC Ag, as falhas nos acumuladores de direção e freio eram identificadas apenas após a manifestação de sintomas, como aumento excessivo da temperatura, enrijecimento da direção e paradas não planejadas. Após a instalação dos sensores, tornou-se possível acompanhar a evolução da temperatura em tempo real por meio dos gráficos de tendência disponíveis no CMA da mina, permitindo a emissão de alertas preventivos e a programação de paradas planejadas para manutenção, mitigando riscos operacionais e aumentando a confiabilidade dos ativos.', N'Monitoramento online', 25300, 1, N'Aumento da segurança para motoristas e pedestres;
INSERT INTO #PVC VALUES (11155, N'544481', N'544481', N'CHECKLIST DE INSPEÇÃO – ROÇO MECANIZADO', 2, N'Others/Outros', N'As atividades de roço mecanizado eram iniciadas sem um padrão definido de inspeção da área e controle de projeção de materiais. Havia risco de lançamento de pedras, galhos e resíduos durante a operação da roçadeira, além da ausência de isolamento adequado e controle de acesso de pessoas e veículos na área operacional.', N'Padronizar a inspeção das atividades de roço mecanizado, garantindo o controle dos riscos relacionados à projeção de materiais, isolamento da área e segurança dos empregados, prevenindo acidentes com pessoas, veículos e equipamentos.', N'10017', N'01 - Imagens/01 - Antes/11155.jpeg', N'As atividades de roço mecanizado eram realizadas sem padrão de inspeção e isolamento da área, aumentando o risco de projeção de materiais e exposição de pessoas e veículos.', N'01 - Imagens/02 - Depois/11155.jpeg', N'Foi implantado checklist visual para roço mecanizado, assegurando inspeção da área, isolamento, uso de EPIs e controle de riscos, aumentando a segurança e prevenindo acidentes. ', NULL, N'Foi implantado um checklist visual de inspeção para as atividades de roço mecanizado, garantindo a verificação do isolamento da área, uso correto de EPIs, inspeção dos equipamentos e controle dos riscos de projeção de materiais. A melhoria proporcionou mais segurança operacional, maior percepção de risco e prevenção de acidentes durante as atividades.', N'Padronização', 0, NULL, NULL, '2026-05-21T00:00:00.000', '2026-07-13T13:12:02.000', N'544481', NULL, NULL);
INSERT INTO #PVC VALUES (11156, N'1008370', N'1008370', N'222 line labelling', 1, N'Others/Outros', N'Upcoming line cleaning for building 222. Pipes in pipe rack not labelled and can be confusing. Maintenance and ops both unfamiliar with overhead lines in pipe rack', N'Visual aid for techs, maintenance and work parties', N'0', N'01 - Imagens/01 - Antes/11156.jpeg', N'Many lines running through 222 pipe rack, none of which are labelled. With upcoming cleaning of many of these lines, it would be a benefit to have them easy to identify by all work parties', N'01 - Imagens/02 - Depois/11156.jpeg', N'Line labelled in area that can clearly be seen. This will help all working parties, Ops, Maintenance and Clean Harbors to be able to identify lines more efficiently.', NULL, N'Yes, line is labelled which will provide a positive impact going forward', N'Labelled lines make overall work easier/more efficient', 0, NULL, N'Proactive identification of potential issues, savings and efficiencies in hosting ecosystem in a consistent and predictable manner ', '2026-07-10T00:00:00.000', '2026-07-13T13:13:38.000', N'1008370', NULL, NULL);
INSERT INTO #PVC VALUES (11157, N'81042078', N'81042078', N'IMPLANTAÇÃO DE DISPOSITIVO NIVELADOR PARA PADRONIZAÇÃO DA ALTURA DAS AMOSTRAS NA DETERMINAÇÃO DE UMIDADE', 1, N'Others/Outros', N'Na etapa de preparação das amostras para determinação de umidade, prevista no PRO-004262, não existia uma ferramenta que garantisse o atendimento ao requisito de altura máxima de 30 mm da camada de material. O nivelamento era realizado visualmente, favorecendo a formação de “camelos” e de camadas irregulares, comprometendo a uniformidade da secagem, aumentando a variabilidade do processo e reduzindo a confiabilidade dos resultados analíticos.
INSERT INTO #PVC VALUES (11158, N'503436', N'503436', N'MONITORAMENTO DE INSTAÇÃO DE GATEWAYS FROTA TRANSPORTE', 1, N'No Replication/Sem replicação', N'O controle de instalação das gateways da frota transporte são monitoradas através de uma planilha de Excel em pastas aleatórias sem visão geral de como está o andamento do comissionamento das gateways com gestão a vista.  ', N'Acompanhar o monitoramento de instalação através de um farol de Bi e no CMA', N'10024', N'01 - Imagens/01 - Antes/11158.jpeg', N' Sobre o comissionamento das gateways Dynamox o controle era realizado através de planilha de Excel e no grupo de WhatsApp sobre o andamento das instalações com pouca visibilidade para as equipes de inspeção de campo e CMA. ', N'01 - Imagens/02 - Depois/11158.jpeg', N'Após a criação do Bi de farol de controle de instalação de sensores Dynamox e gateways nos equipamentos através da alimentação de informações, conseguimos enviar os dados para o CMA e através da tela de gestão a vista podemos acompanhar através de gráficos e condições de alarmes o andamento da instalação das gateways.', NULL, N'Anteriormente não havia condição de acompanharmos o monitoramento desses ativos quanto á instalação somente através de planilhas e no WhatsApp celular, após a criação de um Bi para controle do comissionamento de instalação das gateways, conseguimos acompanhar o comissionamento com dados e eventos nas telas do CMA.', N'Monitoramento com gestão a vista', 0, NULL, N'Redução de pessoas em campo operacional.
INSERT INTO #PVC VALUES (11159, N'81058966', N'81038717', N'BQ-2022-191 – Melhoria nas tubulações de recalque e sucção.', 1, N'Others/Outros', N' As tubulações de sucção e recalque eram feitas em PEAD rígido, e suas curvas e soldas, com o passar do tempo, ressecavam devido à ação do produto químico transportado pelo sistema, ocasionando frequentes vazamentos.', N'ubstituir as tubulações rígidas por tubulações flexíveis e mais resistentes ao produto químico, aumentando a confiabilidade do sistema e reduzindo os vazamentos.', N'10031', N'01 - Imagens/01 - Antes/11159.jpeg', N' Existia muita contaminação na baia devido ao excesso de vazamentos provenientes das tubulações dos equipamentos.', N'01 - Imagens/02 - Depois/11159.jpeg', N'As tubulações foram substituídas por modelos flexíveis, mais resistentes aos produtos químicos e com maior vida útil.', NULL, N'sim, redução dos vazamentos nas tubulações, eliminação da contaminação frequente na baia das BQ’s', N'Melhorias de processo contribuem diretamente para segurança, confiabilidade operacional e aumento da vida útil dos equipamentos.', 0, NULL, N'Monthly carbon output reduced >50% from 2025 in VBM Azure subscriptions from 757kgCO2e to 362kgCO2e', '2026-07-08T00:00:00.000', '2026-07-13T17:07:21.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11160, N'81058966', N'81038855', N'Adequação da tubulação dos canhões de limpeza da baia da CX-2057-06', 1, N'Others/Outros', N'Durante o translado da CX-2057-06, foi identificado um grande acúmulo de material concentrado na baia, com potencial de ser direcionado ao sump. Entretanto, devido às falhas recorrentes na tubulação de alimentação dos canhões de lavagem, o equipamento permanecia indisponível, impossibilitando a limpeza eficiente da baia e a recuperação do material para retorno ao circuito de processo.', N'Aumentar a vida útil da tubulação dos canhões de lavagem. Eliminar vazamentos de água. Garantir a disponibilidade dos canhões de limpeza. Melhorar a organização, limpeza e segurança da área. Reduzir perdas operacionais por acúmulo de material.', N'10031', N'01 - Imagens/01 - Antes/11160.jpeg', N'Durante o translado da CX-2057-06, verificou-se grande acúmulo de material concentrado na baia. Os caminhões de lavagem, responsáveis por  esse material ao sump para retorno ao processo, encontravam-se frequentemente indisponíveis devido a falhas na tubulação de alimentação.', N'01 - Imagens/02 - Depois/11160.jpeg', N'Foi fabricado e instalado um novo trecho de tubulação, substituindo o percurso subterrâneo por uma tubulação externa e de fácil acesso para inspeções e manutenções. ', NULL, N'sim,Aumento da vida útil da tubulação.
INSERT INTO #PVC VALUES (11161, N'81045248', N'1009268', N'Ball Valve for water lance ', 1, N'Concentration/Concentração', N'to clean the Ball Mill Discharge tank it can be full of solids. It can be difficult to get the concentrate to drain out of the tank.
INSERT INTO #PVC VALUES (11162, N'81045248', N'1010297', N'Workbench ', 3, N'Others/Outros', N'Our workbench is made of wood and is falling apart. It is difficult to keep clean', N'create sturdy, clean workbench', N'0', N'01 - Imagens/01 - Antes/11162.jpeg', N'we spray down this area so the wood is getting wet multiple times a shift.
INSERT INTO #PVC VALUES (11163, N'81029574', N'81029574', N'Criação da nomenclatura LR (Limonita Rica) para segregação e controle de estoque de minério', 1, N'Open Pit/Poço aberto', N'Anteriormente, a segregação dos estoques de limonita era realizada apenas com base nas características físicas observadas em campo. Esse método não permitia distinguir de forma clara os materiais com maior teor de níquel na zona limonítica. A ausência de parametrização e de uma nomenclatura padronizada dificultava a rastreabilidade da origem do material, podendo ocasionar a mistura de minérios com diferentes qualidades e comprometendo a confiabilidade do controle de estoque e do direcionamento do material para o processo.
INSERT INTO #PVC VALUES (11164, N'81020607', N'547536', N'Armários com leitor de crachá', 3, N'Others/Outros', N'Os armários disponíveis na área apresentavam condições inadequadas de utilização e não possuíam sistema de segurança para controle de acesso.', N'Melhoria Continua ', N'10139', N'01 - Imagens/01 - Antes/11164.jpeg', N'Os armários disponíveis na área não eram adequados às necessidades operacionais e não possuíam mecanismos de segurança para controle de acesso.', N'01 - Imagens/02 - Depois/11164.jpeg', N'Foi realizada a aquisição e instalação de novos armários com sistema de abertura por leitura de crachá, proporcionando maior segurança no armazenamento de pertences, modernização da área e melhoria das condições de organização e controle de acesso.', NULL, N'Maior segurança para os colaboradores e seus pertences;
INSERT INTO #PVC VALUES (11165, N'201675', N'201675', N'Tech Obsolesence Elimination and Cost Reduction', 1, N'Projects/Projetos', N'Expensive and obsolete technology assets using costly service models ', N'Reduce cost and support risk through replacement of obsolete assets with vale owned equiptment', N'0', N'01 - Imagens/01 - Antes/11165.jpeg', N'-high ongoing cost for obsolete 3rd party owned equipment
INSERT INTO #PVC VALUES (11166, N'81020607', N'547536', N'Instalação de Base Estrutural para Armários', 3, N'Others/Outros', N'Os armários ficavam apoiados diretamente no piso, tornando-os mais suscetíveis ao desgaste prematuro e à deterioração causada pelas condições do ambiente.', N'Melhoria Continua', N'10139', N'01 - Imagens/01 - Antes/11166.jpeg', N'Os armários permaneciam diretamente apoiados no chão, ficando expostos à umidade, sujeira e possíveis impactos, o que poderia acelerar o desgaste da estrutura, comprometer sua conservação e dificultar a limpeza e organização da área.', N'01 - Imagens/02 - Depois/11166.jpeg', N'Foi realizada a confecção e instalação de uma base estrutural para os armários, elevando-os do piso e proporcionando maior proteção, estabilidade e melhor conservação dos equipamentos.', NULL, N'A instalação da base estrutural elevou o padrão de conservação dos armários, reduzindo riscos de deterioração, aumentando sua vida útil e contribuindo para um ambiente mais organizado e seguro.', N'Qualidade e produtividade no processo', 0, NULL, N'Redução de 25% da mão de obra necessária na atividade;
INSERT INTO #PVC VALUES (11167, N'81020607', N'547536', N'Implantação de Sinalização para Entrada e Saída de Veículos', 1, N'Others/Outros', N'A área não possuía um sistema de sinalização para controlar a entrada e saída de veículos, o que dificultava a orientação dos condutores, aumentava o risco de conflitos de tráfego e comprometia as condições de segurança operacional.', N'Melhoria Continua', N'10139', N'01 - Imagens/01 - Antes/11167.jpeg', N'Não havia sinalização para entrada e saída de veículos, dificultando a orientação dos condutores e o controle do fluxo de tráfego na área, aumentando o risco de incidentes e manobras inadequadas.', N'01 - Imagens/02 - Depois/11167.jpeg', N'Foi realizada a aquisição e instalação de um semáforo para controle da entrada e saída de veículos, proporcionando maior visibilidade, organização do fluxo de tráfego e reforço das condições de segurança na área.', NULL, N'A implantação do semáforo trouxe mais segurança e controle para a circulação de veículos, reduzindo riscos operacionais, melhorando a organização do tráfego e proporcionando maior confiabilidade nas movimentações da área.', N'Segurança e qualidade no processo', 0, NULL, N'organização e armazenamento adequado de ferramentas de limpeza, substituindo o acondicionamento desorganizado no canto por um suporte fixo para ferramentas', '2026-07-08T00:00:00.000', '2026-07-14T11:34:36.000', N'81020607', NULL, NULL);
INSERT INTO #PVC VALUES (11168, N'201675', N'201675', N'Exit Markham Datacenter facility ', 1, N'No Replication/Sem replicação', N'Markham datacenter managed facility no longer required and used as originally intended for disaster recovery purposes.  Continued use resulting in unnecessary cost and environment complexity ', N'Eliminate or migrate all hosting equiptment and applications from Markham to eliminate need for datacenter ', N'0', N'01 - Imagens/01 - Antes/11168.jpeg', N'>30 applications/services, ~8 hosting equipment assets in Markham datacenter resulting in >$5K/month in facility costs 
INSERT INTO #PVC VALUES (11169, N'201675', N'81031520', N'On-Premises & Cloud Hosting Observability Excellence', 3, N'Others/Outros', N'-missing proactive routines to regularly check on-premises and cloud services for health, security, and performance issues/risks
INSERT INTO #PVC VALUES (11170, N'201675', N'200363', N'VBM peer review routine for billing cost validation', 1, N'Others/Outros', N'Historical responsibility for dxc billing cost review and approval performed by VSA without due dilligence/peer review by VBM team members.  Difficulty toi ensure accuracey and thoroughness of billing file review due to size and global scope without regional assesstment ', N'Cost control, billing accuracey, waste reduction ', N'0', N'01 - Imagens/01 - Antes/11170.jpeg', N'-Monthly DXC billing file for hosting costs review centralized by VSA team without peer review/feedback from VBM 
INSERT INTO #PVC VALUES (11171, N'81012715', N'81012715', N'Otimização das atividade de campo do CMA.', 1, N'Others/Outros', N'Ausência de um processo padronizado para disponibilização das listas de coleta e instalação, resultando em perda de tempo, retrabalho e baixa produtividade nas atividades de campo.', N'Aumentar a produtividade da equipe por meio de padronização de listas.', N'10362', N'01 - Imagens/01 - Antes/11171.jpeg', N'Antes da implantação do Kaizen, não existia um método padronizado para disponibilizar as listas de coleta e instalação. Cada colaborador gerava suas próprias listas, utilizando procedimentos distintos, o que consumia tempo, gerava retrabalho, dificultava o acompanhamento das pendências e reduzia a produtividade das atividades em campo.', N'01 - Imagens/02 - Depois/11171.jpeg', N'Foram inseridas planilhas padronizadas de coleta e instalação nos três tablets da equipe de CMA, garantindo que todos os colaboradores utilizem a mesma base de informações, sempre atualizada. As listas permitem marcar as atividades concluídas e manter visíveis apenas as pendências, facilitando a execução das tarefas em campo. A melhoria reduziu o tempo de preparação das atividades, eliminou retrabalho, padronizou o processo e aumentou a produtividade, a organização e a eficiência da equipe.', NULL, N'Meta alcançada e retrabalho reduzido. Redução das visitas à campo ao mesmo equipamento e redução de pessoas em área operacional gerando mais segurança.', N'Ferramentas simples, quando bem organizadas, geram banhos significantes de produtividade.', 0, NULL, N'Risco zero de acidentes por partes móveis.', '2026-07-13T00:00:00.000', '2026-07-14T12:53:31.000', N'81012715', NULL, NULL);
INSERT INTO #PVC VALUES (11172, N'201675', N'201675', N'Cloud Carbon Reduction ', 1, N'Projects/Projetos', N'Unnecessary carbon output from overprovisioned or unused cloud assets from applications/services in MS Azure', N'Reduce carbon emissions from Azure services ', N'0', N'01 - Imagens/01 - Antes/11172.jpeg', N'-significant number of workloads in Azure cloud no longer required or are oversized for current usage, resulting in excessive carbon emissions and cost ', N'01 - Imagens/02 - Depois/11172.jpeg', N'Established ongoing cadence to review cloud consumption, implemented budgets and other monitors in Azure to improve visibility and proactive routines to analyze performance and efficiency 
INSERT INTO #PVC VALUES (11173, N'81048127', N'81048127', N'Safety Shower', 1, N'Refining/Refino', N'Safety showers continue leaking after testing', N'Less Mess', N'0', N'01 - Imagens/01 - Antes/11173.jpeg', N'Safety showers leaking after testing.', N'01 - Imagens/02 - Depois/11173.jpeg', N'I found that the handle needed to be tightened so when you push the handle all the way it closes the valve all the way', NULL, N'Yes, water stops when you function the handle all the way closed. Before it was hitting the stop and not fully closing.', N'over time and usage the handles wear', 0, NULL, N'Melhoria na organização e padronização da área de trabalho;
INSERT INTO #PVC VALUES (11174, N'201675', N'201986', N'OT Email Relay Reliability Improvements', 2, N'Others/Outros', N'Unreliable email notification service used in Port Colborne impacting safe operations
INSERT INTO #PVC VALUES (11175, N'553135', N'81019440', N'SUPORTE DO FAROL FRONTAL TT-85', 2, N'Others/Outros', N'O EQUIPAMENTO NÃO POSSUIA UM SUPORTE EFICIENTE PARA O FAROL. HAVIA UM OUTRO SUPORTE EXTREMAMENTE PESADO E DIFICIL DE INSTALAR. ', N'DEIXAR A ATIVIDADE MAIS SEGURA, E DAR DURABILIDADE PARA O FAROL', N'10139', N'01 - Imagens/01 - Antes/11175.jpeg', N'O EQUIPAMENTO NÃO POSSUIA UM SUPORTE EFICIENTE PARA O FAROL. HAVIA UM OUTRO SUPORTE EXTREMAMENTE PESADO E DIFICIL DE INSTALAR. ', N'01 - Imagens/02 - Depois/11175.jpeg', N'FOI CONSTRUIDO UM SUPORTE NA OFICINA COM RECURSOS PROPRIOS, GERANDO FACILIDADE PARA INSTALAÇÃO E DURABILIDADE DO FAROL. TAMBÉM TIVEMOS CUSTO EVITADO JÁ QUE O SUPORTE FOI FABRICADO NA OFICINA. ', NULL, N'O EQUIPAMENTO NÃO POSSUIA UM SUPORTE EFICIENTE PARA O FAROL. HAVIA UM OUTRO SUPORTE EXTREMAMENTE PESADO E DIFICIL DE INSTALAR. ', N'MELHORIAS QUE GERAM MELHORIAS ', 0, NULL, N'Decreased lead time = increased productivity and decreased risk', '2026-07-09T00:00:00.000', '2026-07-14T13:57:02.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11176, N'81031659', N'878868', N'Suporte Martelete ', 3, N'Others/Outros', N'Equipamento armazenado de forma inadequada.
INSERT INTO #PVC VALUES (11177, N'201675', N'201675', N'Cloud Observability Improvements', 1, N'Others/Outros', N'-lack of established budgets in cloud to manage workload costs based on actual expenses 
INSERT INTO #PVC VALUES (11178, N'514353', N'878868', N'Suporte Transporte Mourão', 1, N'Projects/Projetos', N'O transporte manual de mourões exigia grande esforço físico, dificultava o manuseio e aumentava o risco de lesões, quedas e perda de controle da carga.', N'"Reduzir o esforço físico e os riscos no transporte de mourões, promovendo maior segurança, ergonomia e padronização da atividade.', N'10017', N'01 - Imagens/01 - Antes/11178.jpeg', N'O transporte manual de mourões exigia esforço físico elevado, dificultava o manuseio e aumentava o risco de lesões, quedas e perda do controle da carga.', N'01 - Imagens/02 - Depois/11178.jpeg', N'Foi implantada uma tenaz para transporte de mourões, garantindo pega firme, reduzindo o esforço físico, aumentando a segurança e facilitando o manuseio da carga.', NULL, N'A meta foi alcançada. O uso da tenaz reduziu o esforço físico, melhorou o controle da carga e aumentou a segurança e a ergonomia no transporte de mourões.', N'ergonomia, segurança e produtividade', 0, NULL, N'Melhorar o controle e a integridade das caixas de mangueiras por meio da utilização de lacres, facilitando a identificação visual de intervenções, tornando as inspeções mais eficientes e contribuindo para a conservação e a prontidão dos equipamentos de combate a incêndio.', '2026-07-13T00:00:00.000', '2026-07-14T14:40:23.000', N'514353', NULL, NULL);
INSERT INTO #PVC VALUES (11179, N'514353', N'878868', N'ferramenta auxiliar transporte de mourão', 1, N'Others/Outros', N'O transporte manual de materiais era realizado por 4 colaboradores, exigindo maior esforço físico, maior exposição ao risco ergonômico e menor eficiência na execução da atividade.', N'Reduzir o esforço físico e otimizar a quantidade de colaboradores envolvidos no transporte, mantendo a segurança e eficiência da atividade.', N'10017', N'01 - Imagens/01 - Antes/11179.jpeg', N'O transporte manual de materiais era realizado por 4 colaboradores, exigindo maior esforço físico, maior exposição ao risco ergonômico e menor eficiência na execução da atividade.', N'01 - Imagens/02 - Depois/11179.jpeg', N'Com a implantação da ferramenta, houve redução da quantidade de colaboradores necessários para a atividade, passando de 4 para 3 pessoas, mantendo maior segurança e eficiência operacional.', NULL, N'Redução de 25% da mão de obra necessária na atividade;
INSERT INTO #PVC VALUES (11180, N'514353', N'878868', N'suporte para organização de ferramentas de limpeza', 3, N'Others/Outros', N'Ferramentas de limpeza armazenadas de forma inadequada, apoiadas no piso e sem local definido, ocasionando desorganização, risco de queda de materiais, dificuldade de identificação e perda de tempo na busca dos utensílios.', N'5s', N'10017', N'01 - Imagens/01 - Antes/11180.jpeg', N'Ferramentas de limpeza armazenadas sem local definido, ocasionando desorganização, risco de queda de materiais, dificuldade de identificação.', N'01 - Imagens/02 - Depois/11180.jpeg', N'Foi desenvolvido um suporte de cano PVC para acondicionamento das ferramentas, garantindo padronização, organização e melhor aproveitamento do espaço.', NULL, N'organização e armazenamento adequado de ferramentas de limpeza, substituindo o acondicionamento desorganizado no canto por um suporte fixo para ferramentas', N'5s', 0, NULL, N'Technicians can now more quickly identify problem with equipment and resolve more efficiently.', '2026-07-10T00:00:00.000', '2026-07-14T14:53:18.000', N'514353', NULL, NULL);
INSERT INTO #PVC VALUES (11181, N'81060882', N'81060882', N'Monitoramento Preditivo no Rolo Desaguador nº 01', 1, N'Projects/Projetos', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N'Realizar o monitoramento da temperatura dos rolamentos do rolo', N'10362', N'01 - Imagens/01 - Antes/11181.jpeg', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N'01 - Imagens/02 - Depois/11181.jpeg', N'Monitoramento online e em tempo real, garantindo detecção precoce de anomalias sem necessidade de aproximação humana constante do ativo.', NULL, N'A meta inicial do projeto era garantir a integridade do Rolo Desaguador nº 01 através de uma rotina de inspeção mais assertiva e segura.', N'Aumento da Disponibilidade do Rolo Desaguador 01 via Sensoriamento Online', 0, NULL, N'Aumentar a segurança da atividade de lubrificação, eliminando a exposição a riscos ergonômicos e mecânicos através da instalação de pontos de lubrificação remota, proporcionando uma execução mais segura, confortável e eficiente para os empregados.', '2026-07-13T00:00:00.000', '2026-07-14T15:00:47.000', N'81060882', NULL, NULL);
INSERT INTO #PVC VALUES (11182, N'81060882', N'81060882', N'Monitoramento Preditivo no Rolo Desaguador nº 02', 1, N'Projects/Projetos', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N' Realizar o monitoramento da temperatura dos rolamentos do rolo desaguador de forma online.', N'10362', N'01 - Imagens/01 - Antes/11182.jpeg', N'Monitoramento intermitente via inspeção sensitiva (visual/auditiva), gerando risco de exposição do inspetor e falhas não detectadas entre as rotas.', N'01 - Imagens/02 - Depois/11182.jpeg', N'Monitoramento online e em tempo real, garantindo detecção precoce de anomalias sem necessidade de aproximação humana constante do ativo.', NULL, N'A meta inicial do projeto era garantir a integridade do Rolo Desaguador nº 02 através de uma rotina de inspeção mais assertiva e segura.', N'Aumento da disponibilidade do rolo desaguador n°2', 0, NULL, N'More accurate reading was accomplished', '2026-07-13T00:00:00.000', '2026-07-14T15:09:52.000', N'81060882', NULL, NULL);
INSERT INTO #PVC VALUES (11183, N'514353', N'878868', N'Padronização do Controle Diário de Efetivo', 3, N'Others/Outros', N'Ausência de um controle visual atualizado do efetivo diário, dificultando a identificação dos colaboradores disponíveis, em férias ou ausentes, impactando o planejamento e o dimensionamento das atividades.', N'Implementar uma gestão visual eficiente do efetivo, garantindo atualização diária das informações dos colaboradores, melhorando o planejamento das atividades, o dimensionamento da equipe e a tomada de decisão operacional', N'10017', N'01 - Imagens/01 - Antes/11183.jpeg', N'Implantação de controle diário do efetivo em planilha, permitindo o correto dimensionamento das atividades, com visibilidade dos colaboradores ativos, férias e ausências no site.', N'01 - Imagens/02 - Depois/11183.jpeg', N'Implantado painel visual com ímãs e fotos dos colaboradores, contendo nome e função, permitindo atualização diária do status do efetivo (ativo, férias ou ausente), facilitando o controle e a gestão.', NULL, N'Controle do efetivo realizado apenas em planilhas, sem visualização rápida da disponibilidade dos colaboradores, dificultando o acompanhamento diário.', N'5s', 0, NULL, N'- Zero paradas duplas de caminhões.
INSERT INTO #PVC VALUES (11184, N'81060882', N'81060882', N'proteção física articulada dos mancais do tambor traseiro.', 1, N'Projects/Projetos', N'Proteção física danificada e ineficaz, não atendendo aos requisitos mínimos de segurança para enclausuramento de partes móveis.', N'Reduzir a zero o índice de exposição de colaboradores a partes móveis e pontos de prensamento no ativo.', N'10362', N'01 - Imagens/01 - Antes/11184.jpeg', N'Proteção dos mancais do tambor se encontrava com avarias, devido a abertura realizada para facilitar na lubrificação com o equipamento em funcionamento.', N'01 - Imagens/02 - Depois/11184.jpeg', N'Fabricação e montagem de nova proteção dos mancais (padrão de segurança) tipo portão para facilitar no manuseio e possíveis manutenções.', NULL, N'A meta original era restabelecer a segurança e criar uma rotina confiável para os colaboradores.', N'Proteções articuladas com puxadores reduzem o tempo de intervenção mecânica e reestabelecer a segurança.', 0, NULL, NULL, '2026-07-02T00:00:00.000', '2026-07-14T15:23:45.000', N'81060882', NULL, NULL);
INSERT INTO #PVC VALUES (11185, N'81006732', N'81006732', N'Uso de Pega Cilindro para transporte de cilindros industriais.', 2, N'Others/Outros', N'Era realizado o transporte de cilindros industriais de forma totalmente manual, com uso de força, pressão, flexão manual, podendo causar quedas dos cilindros e lesões corporais devido posturas inadequadas.', N'Minimizar ou eliminar os riscos nos transporte de cilindros de gases.', N'10184', N'01 - Imagens/01 - Antes/11185.jpeg', N'Era realizado o transporte de cilindros industriais de forma totalmente manual, com uso de força, pressão, flexão manual, podendo causar quedas dos cilindros e lesões corporais devido posturas inadequadas.', N'01 - Imagens/02 - Depois/11185.jpeg', N'Implementamos o uso do "Pega Cilindro" para realizarmos o transporte manual dos cilindros industriais, a ferramenta é ideal pois reduz os esforços físicos dos empregados ao utilizar, minimizando os riscos de acidentes devido os cilindros serem acoplados e ajustados conforme a necessidade e na lateral há alças emborrachadas que facilitam o manuseio, oferecendo conforto e firmeza ao realizar o transporte dos cilindros, eliminando posturas e lesões inadequadas.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal', N'Sim, com o uso do pega cilindro conseguimos oferecer conforto e firmeza ao realizar o transporte dos cilindros industriais. ', N'Eliminação de posturas inadequadas, e realizado gestão de mudança na área GM 5625.', 0, NULL, NULL, '2026-07-10T00:00:00.000', '2026-07-14T15:29:16.000', N'81006732', NULL, NULL);
INSERT INTO #PVC VALUES (11186, N'81020607', N'543295', N'Elo para ponto de ancoragem do dispositivo para abrir tambor ', 3, N'Others/Outros', N'O dispositivo utilizado para abertura de tambores não possuía um local definido para armazenamento quando não estava em uso, ficando apoiado em locais inadequados. Essa condição gerava risco de danos ao equipamento, dificuldade de localização e potencial de queda ou tropeço na área de trabalho.', N'Melhoria continua ', N'10139', N'01 - Imagens/01 - Antes/11186.jpeg', N'Dispositivo para abertura de tambores sem ponto ou local específico para armazenamento e fixação.', N'01 - Imagens/02 - Depois/11186.jpeg', N'Foi confeccionado e instalado um elo para ponto de ancoragem, permitindo o armazenamento adequado e a fixação segura do dispositivo de abertura de tambores quando fora de uso.', NULL, N'Maior segurança, organização, conservação do equipamento e facilidade de acesso.', N'Qualidade no processo', 0, NULL, N'O operador acessa o equipamento sem necessidade de translado', '2026-07-09T00:00:00.000', '2026-07-14T16:15:13.000', N'81020607', NULL, NULL);
INSERT INTO #PVC VALUES (11187, N'81054395', N'81054395', N'Implementação de Visão Prospectiva para Otimização de Estoques', 1, N'Open Pit/Poço aberto', N'Não existia uma visão consolidada dos ganhos potenciais da revisão dos níveis de estoque, dificultando a priorização das ações e a demonstração dos benefícios esperados. O problema foi identificado durante as análises de Working Capital, diante da necessidade de quantificar e comunicar o potencial de redução do capital imobilizado.', N'Desenvolver uma visão estratégica do potencial de redução de estoques para apoiar a tomada de decisão e direcionar as ações de otimização do capital imobilizado.', N'10015', N'01 - Imagens/01 - Antes/11187.jpeg', N'Antes da implementação, não havia uma visão clara e consolidada do potencial de redução dos estoques, dificultando a priorização das iniciativas e a demonstração dos ganhos esperados. Essa limitação reduzia a visibilidade das oportunidades de otimização do capital imobilizado e foi identificada durante as análises de Working Capital e revisão dos níveis de estoque.', N'01 - Imagens/02 - Depois/11187.jpeg', N'Foi desenvolvida uma projeção estruturada de redução de estoques, com metodologia padronizada para estimar e comunicar os ganhos potenciais, proporcionando maior visibilidade das oportunidades de otimização, melhor direcionamento das ações e suporte à tomada de decisão para redução do capital imobilizado e melhoria do Working Capital.', NULL, N'Sim. Foi criada uma visão consolidada do potencial de redução dos estoques, permitindo quantificar e comunicar os benefícios esperados de forma estruturada', N'A visibilidade dos ganhos potenciais é fundamental para direcionar prioridades e apoiar a tomada de decisão', 0, NULL, N'Aumentar o controle e a rastreabilidade dos anexos, garantindo a segurança das informações do processo.', '2026-07-02T00:00:00.000', '2026-07-15T09:14:55.000', N'81054395', NULL, NULL);
INSERT INTO #PVC VALUES (11188, N'800303', N'800303', N'We can pump that - Lix-84 IC', 1, N'Refining/Refino', N'Lix-84i, an important reagent required for Copper Solvent Extraction had a very long lead time of 6 months.  When speaking with the vendor I was told the reason for the lead time was that we were the only customers for the 84-i product, so the plant needed to be changed to make a batch for us.  We held an RFA to switch our supply to the IC product - more concentrated version, which we had to first prove with could pump due to the increased viscosity.  We proved we could pump and initiated the change.  Lead times should decrease by ~50%', N'Decrease Lead Time', N'0', N'01 - Imagens/01 - Antes/11188.jpeg', N'Lix-84i, an important reagent required for Copper Solvent Extraction had a very long lead time of 6 months.  When speaking with the vendor I was told the reason for the lead time was that we were the only customers for the 84-i product, so the plant needed to be changed to make a batch for us.  I was then informed of a more readily available product, the 84-IC brand which is the same but with a more concentrated (+33%) more active ingredient.', N'01 - Imagens/02 - Depois/11188.jpeg', N'Decreased lead time and cost savings with vendor managing stock in their WHSE', NULL, N'Yes - lead times decreased.  Vendor is now holding the material in their WHSE and managing the min-max inventory for us as well, which results in cost savings associated with the reduction of use of our off-site WHSE space', N'Challenge Status Quo', 10000, 3, N'A solução implantada eliminou o armazenamento das ferramentas no chão, promoveu organização e padronização conforme o 5S, reduziu riscos ergonômicos e aumentou a segurança e a eficiência operacional.
INSERT INTO #PVC VALUES (11189, N'502705', N'502705', N'Prioridade de Componentes no BI', 1, N'No Replication/Sem replicação', N'No BI de Gestão de Materiais e componentes da coordenação de aprovisionamento, é possível enxergar a visão geral de componentes, saldos, aquisições, reformas e distribuição por áreas, porém não tínhamos a visão de prioridade dos componentes ABC para melhor controle das ações.', N'Auxiliar na análise de prioridade dos componentes ABC para tratativa de cobertura.', N'10222', N'01 - Imagens/01 - Antes/11189.jpeg', N'Visão detalhada dos componentes da Usina, separado por grupos de componente, área de aplicação e possibilidade de filtro dos componentes do singelo. Porém sem visão de prioridade dos componentes (ABC). ', N'01 - Imagens/02 - Depois/11189.jpeg', N'Foi incluído no BI, a separação dos componentes por prioridade ABC, bem como o resumo do STATUS de cobertura destes componentes e destaque dos 10 maiores grupos de componentes.', N'https://app.powerbi.com/groups/42c65efb-0cd7-47f1-bd62-844c73607c87/reports/a7de042a-7a35-443c-af0d-eb7ad583367b/22d0e650a9079da3b98d?experience=power-bi', N'Com a publicação do BI, foi possível identificar de forma clara os componentes prioritários para direcionar as tratativas.', N'As demandas podem ser priorizadas após identificação das prioridades.', 0, NULL, N'Ganhos em segurança e garantia de ambiente seguro para os colaboradores com redução de riscos de queda e tropeço.', '2026-07-13T00:00:00.000', '2026-07-15T09:41:04.000', N'502705', NULL, NULL);
INSERT INTO #PVC VALUES (11190, N'486546', N'535629', N'Melhoria da Organização e Conservação das Propulsoras de Graxa', 3, N'Others/Outros', N'As mangueiras das propulsoras de graxa eram armazenadas de forma inadequada, permanecendo enroladas e apoiadas sobre os cilindros dos equipamentos. Essa condição sujeitava componentes críticos a esforços mecânicos e atrito contínuo, aumentando o desgaste prematuro de hastes, vedações e conexões. Além do risco de vazamentos e falhas operacionais, a prática comprometia a organização da área, dificultava o manuseio seguro dos equipamentos e elevava a necessidade de intervenções de manutenção não programadas.', N'Garantir o acondicionamento seguro e organizado das mangueiras das propulsoras de graxa, reduzindo o desgaste prematuro de hastes, vedações e conexões, minimizando o risco de vazamentos e falhas operacionais, além de proporcionar maior segurança e eficiência no manuseio dos equipamentos', N'10079', N'01 - Imagens/01 - Antes/11190.jpeg', N'As mangueiras das propulsoras de graxa eram armazenadas de forma inadequada, permanecendo enroladas e apoiadas sobre os cilindros dos equipamentos. Essa condição sujeitava componentes críticos a esforços mecânicos e atrito contínuo, aumentando o desgaste prematuro de hastes, vedações e conexões. Além do risco de vazamentos e falhas operacionais, a prática comprometia a organização da área, dificultava o manuseio seguro dos equipamentos e elevava a necessidade de intervenções de manutenção não programadas.
INSERT INTO #PVC VALUES (11191, N'513657', N'52836', N'Padronização do Lacre das Caixas de Mangueiras para Garantia da Prontidão Operacional', 1, N'Others/Outros', N'Padronização do Lacre das Caixas de Mangueiras para Garantia da Prontidão Operacional', N'Implementar a padronização dos lacres em todas as caixas de mangueiras', N'10189', N'01 - Imagens/01 - Antes/11191.jpeg', N'Gerando resposta Copilot said: Antes da implementação do Kaizen, as caixas de mangueiras não possuíam lacres de controle, dificultando a verificação rápida da integridade dos equipamentos e a identificação de acessos não autorizados. Essa condição exigia inspeções mais detalhadas para confirmar a presença e as condições dos componentes internos, aumentando o tempo gasto nas verificações e o risco de não conformidades passarem despercebidas. Além disso, a ausência de um controle visual imediato poderia comprometer a confiabilidade e a prontidão dos equipamentos de combate a incêndio, impactando a resposta adequada em situações de emergência.', N'01 - Imagens/02 - Depois/11191.jpeg', N'Copilot said: Após a implementação do Kaizen, todas as caixas de mangueiras passaram a possuir lacres de controle padronizados, permitindo a identificação visual imediata de qualquer abertura ou intervenção nos equipamentos. Com essa melhoria, as inspeções tornaram-se mais ágeis e eficientes, aumentando a confiabilidade da verificação da integridade dos componentes e reduzindo o risco de não conformidades. A adoção dos lacres proporcionou maior controle sobre os equipamentos de combate a incêndio, contribuindo para a sua conservação, disponibilidade e prontidão operacional em situações de emergência.', NULL, N'A ação implementada tratou diretamente o problema identificado, proporcionando um controle visual mais eficiente da integridade das caixas de mangueiras. Com a utilização dos lacres, tornou-se mais fácil identificar aberturas ou intervenções, tornando as inspeções mais ágeis e confiáveis. A melhoria contribuiu para o fortalecimento do controle dos equipamentos e para o aumento da prontidão operacional do sistema de combate a incêndio.', N'A utilização de lacres nas caixas de mangueiras mostrou que medidas simples e de baixo custo podem aumentar a segurança, facilitar as inspeções e garantir maior controle sobre a integridade dos equipamentos, contribuindo para sua prontidão em situações de emergência.', 0, NULL, N'Maior vida útil do sistema de distribuição de ar;
INSERT INTO #PVC VALUES (11192, N'513657', N'52836', N'Inspeção Inteligente por QR Code', 1, N'Others/Outros', N'Gerando resposta Copilot said: As inspeções manuais frequentemente dependem de formulários em papel e registros dispersos, tornando o processo mais lento, sujeito a erros de preenchimento, perda de informações e retrabalho. Além disso, a falta de rastreabilidade e de acesso aos dados em tempo real dificulta o acompanhamento das condições dos ativos e a tomada de decisões rápidas. A inspeção inteligente por QR Code soluciona esses desafios ao permitir o registro digital instantâneo, garantindo maior agilidade, confiabilidade dos dados e controle das informações.', N'Digitalizar e padronizar o processo de inspeção por meio da utilização de QR Codes, garantindo registros mais rápidos, precisos e rastreáveis, com disponibilidade das informações em tempo real para apoiar a gestão e a tomada de decisões.', N'10189', N'01 - Imagens/01 - Antes/11192.jpeg', N'Atualmente, as inspeções são realizadas de forma manual, utilizando formulários em papel ou planilhas preenchidas pelos inspetores em campo. Após a coleta das informações, os dados precisam ser compilados e lançados em sistemas ou relatórios, gerando retrabalho e aumentando o tempo de processamento. Esse modelo está sujeito a falhas de preenchimento, perda de registros, dificuldades na rastreabilidade das inspeções e atraso na disponibilização das informações para análise. ', N'01 - Imagens/02 - Depois/11192.jpeg', N'Após a implementação da Inspeção Inteligente por QR Code, os inspetores passam a acessar os checklists digitais diretamente pelo celular ou tablet, por meio da leitura do QR Code fixado nos equipamentos, áreas ou estruturas. As informações são registradas em tempo real, com possibilidade de anexar fotos e evidências, eliminando o uso de papel e a necessidade de transcrever dados posteriormente. Os registros ficam automaticamente armazenados em uma base centralizada, garantindo rastreabilidade, maior confiabilidade das informações e acesso imediato aos resultados. Com isso, a identificação de desvios e a tomada de decisões tornam-se mais rápidas e eficazes, aumentando a eficiência operacional, o controle dos ativos e a conformidade dos processos.', NULL, N'A solução de Inspeção Inteligente por QR Code atendeu aos objetivos propostos para resolver os problemas identificados no processo de inspeção manual. Enquanto o cenário inicial era marcado pelo uso de formulários em papel, retrabalho na consolidação de dados, dificuldades de rastreabilidade e atraso na disponibilização das informações, a nova solução permitiu a digitalização completa das inspeções, com registro e consulta dos dados em tempo real. Como resultado, houve redução significativa do tempo gasto nas atividades, eliminação de registros físicos, aumento da confiabilidade das informações e melhoria no acompanhamento das não conformidades. Dessa forma, a implementação demonstrou aderência à meta de tornar o processo mais ágil, eficiente, rastreável e alinhado às necessidades operacionais da organização.', N'A implementação da Inspeção Inteligente por QR Code demonstrou que a digitalização dos processos de inspeção aumenta significativamente a qualidade e a confiabilidade dos dados coletados. A facilidade de acesso aos checklists por dispositivos móveis favoreceu a adesão dos usuários e reduziu erros de preenchimento. Também foi constatado que a rastreabilidade em tempo real agiliza a identificação de desvios e a tomada de decisões. Além disso, o projeto evidenciou a importância do treinamento dos colaboradores, da padronização dos formulários digitais e da conectividade adequada em campo para garantir o sucesso da solução e a sustentabilidade dos resultados alcançados.', 0, NULL, N'No more time wasted during inspection looking for decommissioned equipment.', '2026-07-08T00:00:00.000', '2026-07-15T11:25:38.000', N'513657', NULL, NULL);
INSERT INTO #PVC VALUES (11193, N'81046830', N'1010414', N'Kiln Zone Contactor Faults', 1, N'Others/Outros', N'Kiln is intermittently shutting down with an indication for Zone breaker alarm from DCS panel. This indication refers to local HMI for more information. Locally there is no alarm information to help technicians.', N'Add additional messages to local HMI for technician troubleshooting', N'0', N'01 - Imagens/01 - Antes/11193.jpeg', N'Kiln alarm information from DeltaV. References to check local HMI for more fault information to identify issue. However not all fault information is present on local HMI.', N'01 - Imagens/02 - Depois/11193.jpeg', N'Added additional logic to PLC and new alarm messages to display Zone contactor alarms to assist technicians in field to the problematic device.', NULL, N'Alarm messages now present in HMI to allow field technicians to better identify equipment causing the issue.', N'Issues still exist from commissioning, not all logic fully tested', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (11194, N'518048', N'518048', N'Lubrificação da barra do d9t', 2, N'Others/Outros', N'Desgaste das buchas e pinos da barra estabilizadora por falta de lubrificação, devido a falta de espaço para acessar os pontos de lubrificação.', N'Segurança do empregado e durabilidade do componente', N'10188', N'01 - Imagens/01 - Antes/11194.jpeg', N'Durante a execução das atividades de lubrificação, tanto em oficina quanto em campo, foi identificado que a intervenção na barra estabilizadora exigia a adoção de postura ergonomicamente inadequada. Adicionalmente, o empregado permanecia em contato direto com a estrutura do equipamento, aumentando a exposição a riscos ergonômicos e potenciais lesões decorrentes de esforço físico, compressão mecânica e restrição de mobilidade durante a execução da tarefa.', N'01 - Imagens/02 - Depois/11194.jpeg', N'Durante o estudo de melhoria da atividade, verificou-se que o fabricante disponibilizava uma atualização de projeto contemplando pontos de lubrificação remota. A adequação foi implementada com o objetivo de eliminar a exposição dos empregados a condições de risco decorrentes do acesso à barra estabilizadora. A solução proporcionou ganhos significativos em segurança, ergonomia e manutenabilidade, reduzindo a necessidade de posturas forçadas e o contato com a estrutura do equipamento. Adicionalmente, houve melhoria na eficácia da lubrificação, aumento da confiabilidade dos componentes e extensão da vida útil dos elementos lubrificados, contribuindo para a redução de falhas e para o aumento da disponibilidade física do equipamento.', NULL, N'Durante o processo de estudos das falhas estávamos focados apenas na duração dos componentes do equipamento, porém durante as avaliações percebemos que o nosso maior ganho foi com a segurança do funcionário.', N'Durante a analise enteemos que melhorias de engenharia do fabricante podem e devem ser implementadas nos equipamentos.', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (11195, N'1008463', N'460565', N'LOT Dip tube support', 1, N'Refining/Refino', N'When dipping the LOT, the dip tube was bending, preventing the PPTs from getting an accurate reading', N'More accurate mesasurment', N'10112', N'01 - Imagens/01 - Antes/11195.jpeg', N'Just an open hole, dip tube was bending when trying to get a mesasurment', N'01 - Imagens/02 - Depois/11195.jpeg', N'Dip tube down comer was installed in the hole to keep the tube straight when inserting it into the LOT', NULL, N'Yes', N'None', 0, NULL, N'Tempo menor para o planejamento 
INSERT INTO #PVC VALUES (11196, N'475291', N'475291', N'Área para Revezamento de operadores no Posto pesado', 1, N'No Replication/Sem replicação', N'A Ausência de um ponto de apoio estratégico próximo ao posto pesado impede o revezamento operacional (almoço/janta, ginástica laboral e outros.) durante a parada por abastecimento dos caminhões fora de estrada. Isso gera paradas duplas desnecessárias dos equipamentos, resultando em perda de tempo produtivo e redução da eficiência operacional da frota.', N'Facilitar/otimizar os revezamentos da operação', N'0', N'01 - Imagens/01 - Antes/11196.jpeg', N'A Ausência de um ponto de apoio estratégico próximo ao posto pesado impede o revezamento operacional (almoço/janta, ginástica laboral e outros.) durante a parada por abastecimento dos caminhões fora de estrada. Isso gera paradas duplas desnecessárias dos equipamentos, resultando em perda de tempo produtivo e redução da eficiência operacional da frota.', N'01 - Imagens/02 - Depois/11196.jpeg', N'Realizamos a adequação física da área com o alargamento do espaço próximo ao posto de abastecimento, garantindo que o fluxo de veículos leves não fosse interferido. Foi implantado um ponto estratégico exclusivo para revezamento de operadores, dotado de leiras sinalizadas e placas de identificação. Para garantir a integridade física da equipe, criamos um caminho seguro delimitado para o deslocamento dos operadores entre o ônibus e o posto. A área foi testada com sucesso para manobras de ônibus e permite que a rendição da ginástica laboral e refeições ocorra de forma segura e simultânea ao abastecimento do caminhão fora de estrada.', NULL, N'Sim. A meta foi 100% atingida. Com o novo ponto estratégico e o caminho seguro, eliminamos as paradas duplas dos caminhões fora de estrada. Agora, o revezamento para almoço e ginástica laboral ocorre de forma totalmente segura e simultânea ao abastecimento, otimizando o tempo produtivo e garantindo a pontualidade das pausas da equipe.', N'Através de um olhar atento pequenas adequações de infraestrutura podem gerar grandes ganhos de produtividade.', 0, NULL, NULL, '2026-07-01T00:00:00.000', '2026-07-15T15:58:21.000', N'475291', NULL, NULL);
INSERT INTO #PVC VALUES (11197, N'1008463', N'460565', N'Reusing pipe clamp', 1, N'Others/Outros', N'Water leak in Cu SX and no clamps available to stop it', N'Stop water leak', N'10112', N'01 - Imagens/01 - Antes/11197.jpeg', N'Water leak in Cu SX and there were no clamps available', N'01 - Imagens/02 - Depois/11197.jpeg', N'A clamp was found on a spool piece in a dumpster and was repurposed instead of throwing it out.', NULL, N'Goal met', N'Removed clamps before throwing out spools', 600, 3, N'Real-time access to: total NCRs YTD, open count, overdue count, pending approvals, verified closures (MTD), status distribution donut chart, NCR volume by month, most frequent offender by vendor, most common root cause by classification, average remediation cycle time by vendor, and an overdue NCR alert table. No manual report preparation required.', '2026-07-14T00:00:00.000', '2026-07-15T16:28:02.000', N'1008463', NULL, NULL);
INSERT INTO #PVC VALUES (11198, N'1008463', N'460565', N'Clamp leak in Cd', 1, N'Others/Outros', N'Process water leak in Cd removal and no clamp to stop it', N'Clamp the leak', N'10112', N'01 - Imagens/01 - Antes/11198.jpeg', N'Process water leak and no clamp to stop it', N'01 - Imagens/02 - Depois/11198.jpeg', N'Repurposed a hose clamp on a spool that was getting thrown out', NULL, N'GOal met', N'Remove clamps before throwing out spools', 600, 3, N'- Monthly report generation time reduced from ~4 hours to under 2 minutes
INSERT INTO #PVC VALUES (11199, N'122911', N'473357', N'Estacionamento da carreta SI 43', 1, N'No Replication/Sem replicação', N'Dificuldade pra inspecionar e fazer a logística do operador até o equipamento.', N'Reduzir o tempo de deslocamento dos operadores até a carreta SI 43, eliminando a necessidade de translado do operador até o equipamento.', N'10257', N'01 - Imagens/01 - Antes/11199.jpeg', N'O estacionamento anterior estava localizado no Depósito Sudoeste Flauta, nível 240, exigindo o deslocamento do operador para a realização das inspeções diárias e para a operação do equipamento sempre que fosse necessário executar atividades de transporte.', N'01 - Imagens/02 - Depois/11199.jpeg', N'Foi confeccionado um novo estacionamento ao lado do Escritório do Misto, possibilitando que o operador realize a inspeção diária e acesse o equipamento de forma rápida e prática sempre que necessário. Essa melhoria eliminou a necessidade de translado até o antigo local de estacionamento, reduzindo o tempo de deslocamento e aumentando a eficiência operacional.', NULL, N'Com a realocação do estacionamento para uma área próxima ao Escritório do Misto, a necessidade de translado dos operadores foi eliminada, reduzindo significativamente o tempo de acesso ao equipamento.
INSERT INTO #PVC VALUES (11200, N'81030465', N'81030465', N'Organizador de anexos ', 1, N'Others/Outros', N'Anteriormente, todos os anexos da sala do flúor, sejam eles concluídos, em andamento ou finalizados, eram armazenados de forma única em uma única prancheta. Essa condição gerava falta de organização, dificuldade para localizar os documentos e um alto risco de perda ou extravio de informações importantes para o controle do processo.', N'Eliminar o risco de perca de anexos da analise de Flúor ', N'10366', N'01 - Imagens/01 - Antes/11200.jpeg', N'Anteriormente, todos os anexos da sala do flúor, sejam eles concluídos, em andamento ou finalizados, eram armazenados de forma única em uma única prancheta. Essa condição gerava falta de organização, dificuldade para localizar os documentos e um alto risco de perda ou extravio de informações importantes para o controle do processo.', N'01 - Imagens/02 - Depois/11200.jpeg', N'Após a melhoria, foi implantado um organizador específico com divisórias para separar os anexos por status: Concluídos, Em Andamento e Finalizados. Com isso, ganhamos mais controle, rastreabilidade e segurança na guarda dos documentos. A ação reduziu significativamente o risco de perda, trouxe agilidade na consulta e contribuiu para um ambiente mais organizado e padronizado.', NULL, N'Meta Inicial: Organizar os anexos da sala do flúor e eliminar o risco de perda devido ao armazenamento único em prancheta.
INSERT INTO #PVC VALUES (11201, N'81042202', N'81017935', N'Suporte para ferramentas  ', 3, N'Others/Outros', N'Durante as atividades de limpeza industrial, as ferramentas não possuíam um local definido para armazenamento, permanecendo expostas diretamente no chão. Essa condição comprometia a organização do ambiente, dificultava o acesso aos materiais, aumentava o tempo de execução das atividades e gerava riscos ergonômicos e de segurança aos colaboradores.
INSERT INTO #PVC VALUES (11202, N'81060535', N'487612', N'Redução do Risco de Acidentes por Meio de Sinalização de Degrau​', 2, N'Others/Outros', N'Durante uma reunião no espaço conexão identificamos 
INSERT INTO #PVC VALUES (11203, N'550315', N'550315', N'SUPORTE PARA CALÇO DE RODAS  CAMINHONETE', 1, N'Others/Outros', N'Caminhonete com calço de rodas transportado na carroceria sem suporte ou dispositivo de fixação, permanecendo solto', N'Projetar um suporte para o calço de rodas da caminhonete', N'10234', N'01 - Imagens/01 - Antes/11203.jpeg', N'Calço de rodas solto na carroceria da caminhonete, sem acondicionamento e sem suporte adequado para fixação.', N'01 - Imagens/02 - Depois/11203.jpeg', N'Caminhonete equipada com suporte para armazenamento de calço de rodas, mantendo devidamente fixado e organizado na carroceria, sem risco de deslocamento durante o transporte.', NULL, N'Anteriormente, o calço encontrava-se solto na carroceria, podendo se deslocar durante a movimentação do veículo, gerando risco de queda, danos ao equipamento e potencial ocorrência de acidentes. Após a adequação, o calço passou a ser armazenado em suporte apropriado e devidamente fixado, eliminando o risco de movimentação indevida e garantindo maior organização, segurança e conformidade com as boas práticas de transporte de materiais.', N'A utilização de suportes dedicados melhora a organização dos equipamentos e reduz o risco de perca', 0, NULL, N'.', '2026-07-15T00:00:00.000', '2026-07-16T06:32:46.000', N'550315', NULL, NULL);
INSERT INTO #PVC VALUES (11204, N'81058966', N'81036659', N' Substituição da tubulação de ar da coluna de flotação em aço carbono por tubulação em aço inoxidável.', 1, N'Others/Outros', N'A tubulação de ar da coluna de flotação, fabricada em aço carbono, apresentava elevado desgaste devido à corrosão, ocasionando vazamentos frequentes, necessidade de reparos corretivos, risco de perda de pressão do sistema de ar e redução da confiabilidade operacional. ', N' Substituir a tubulação de aço carbono por tubulação em aço inoxidável, aumentando a vida útil do sistema, eliminando vazamentos por corrosão, reduzindo custos de manutenção corretiva e aumentando a confiabilidade operacional da coluna de flotação.', N'10031', N'01 - Imagens/01 - Antes/11204.jpeg', N'Exposição contínua à umidade e ao ambiente agressivo do processo;
INSERT INTO #PVC VALUES (11205, N'1010227', N'1010227', N'Acid Piping Update', 1, N'Others/Outros', N'Modifications were made in the field but these changes were not reflected in SAP. A recent PM was performed, and it was determined that some piping on this PM was removed from service. The PM was also attached to the equipment number that should have been deactivated. There was also some other equipment in the area that had been removed but was not changed in SAP.', N'Ensure assets in SAP reflect what is in the field for proper history tracking', N'0', N'01 - Imagens/01 - Antes/11205.jpeg', N'An active PM identified two pipelines that no longer exist in the field. The PM was also attached to the inactive pipeline in SAP. A pump and transmitter were also determined to be removed.', N'01 - Imagens/02 - Depois/11205.jpeg', N'The decommissioned equipment was changed to inactive in SAP and the PM was updated to no longer reference the pipelines. The PM was also attached to one of the active pipelines instead.', NULL, N'Yes, the required updates were made in SAP so the removed pipelines will no longer be referenced. The next time the PM is completed there will be no time wasted looking for the pipelines. Equipment records and history are now accurate in SAP.', N'Any changes in the field needs to be updated in existing documents and  data management systems.', 0, NULL, N'Ganhos em segurança e garantia de ambiente seguro para os colaboradores com redução de riscos de prensamento de mãos e dedos.
INSERT INTO #PVC VALUES (11206, N'81007807', N'81007807', N'Lista de tarefa - Falha MR (módulo de falha motor)', 1, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (11207, N'81007807', N'81007807', N'Lista de tarefa - Falha sistema ABS', 1, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (11208, N'81007807', N'81007807', N'Lista de tarefa - Corrigir falhas elétricas', 1, N'Others/Outros', N'Demora na criação dos passos de elaboração para a 
INSERT INTO #PVC VALUES (11209, N'81042793', N'81042793', N'Digital Transformation of Contract Sourcing Planning — Spreadsheet to Intelligent App', 1, N'Projects/Projetos', N'Contract sourcing planning at VNL was managed through a combination of static Excel spreadsheets, disconnected email chains, and manual calendar tracking. No single system provided visibility into sourcing timelines, SLA burn rates, or phase-level progress. Contracts approaching expiry required manual filtering to be identified, sourcing leads had no standard mechanism to record weekly progress, and management had no real-time view of portfolio risk. The effort required to produce a single status report exceeded several hours of manual consolidation every cycle.', N'1.  Replace spreadsheet-based sourcing tracking with a single, authoritative Power Apps canvas app connected to SharePoint as the system of record for all contractors.   2. Give sourcing coordinators, contract managers, and leadership real-time Gantt visibility of all contract SLA timelines, phase positions, and RAG statuses at any point in time.  3. Automatically calculate and flag contracts approaching SLA thresholds — eliminating manual expiry monitoring and ensuring sourcing is triggered with adequate lead time.  4. Provide a structured mechanism for weekly sourcing progress updates and comments, replacing ad-hoc email updates with a timestamped audit trail per contract', N'10026', N'01 - Imagens/01 - Antes/11209.jpeg', N'Contract expiry dates tracked in a shared Excel workbook with no automated alerts.
INSERT INTO #PVC VALUES (11210, N'81042793', N'81042793', N'Digitalization of Contractor Nonconformance Management Through an Integrated Power Apps Solution', 1, N'Projects/Projetos', N'VNL had no dedicated digital system for recording, tracking, and closing out contractor nonconformances across its operations. NCR documentation was managed through a combination of email chains, shared spreadsheets, and manually drafted Word documents — a fragmented approach that created significant gaps in visibility, accountability, audit readiness, and contractor performance governance. Nonconformances were being raised inconsistently, followed up informally, and in several cases not formally closed out at all, leaving unresolved compliance obligations invisible to management and unenforceable under contract.', N'1. Eliminate manual NCR tracking.  2. Ensure completeness of reporting, using mandatory fields. 3.  Reduce average NCR response time by 20% through automating notifications. 4.  Eliminate missed close-out deadlines. 5. Automated overdue alerts; zero NCRs closed without NC Manager sign-off. 6. Create a defensible, time-stamped audit trail for every NCR.', N'10026', N'01 - Imagens/01 - Antes/11210.jpeg', N'NC events were usually identified and reported verbally or via email. Notification emails to the contractor drafted manually. Follow-up was tracked informally. 
INSERT INTO #PVC VALUES (11211, N'81042793', N'81042793', N'Digital Tracking of Contractor Performance Management', 1, N'Projects/Projetos', N'VNL had no integrated system for monitoring the performance of active contractors. Headcount, safety incidents, quality metrics, and financial spend data were maintained in Excel workbooks and emails, with no single source of truth, no mechanism for correlating contractor performance with vendor evaluations. Monthly reporting to management required significant manual effort with risk of error, inconsistency, and delay.', N'1. Consolidate FTE, Quality, Safety, and Finance contractor data into a single integrated platform. 2. Replace manual reporting with automated, on-demand HTML reports exportable to browser and Excel. 3. Enable trend management through monthly dashboard and per-contractor scorecards. 4. Standardise performance monitoring across all contractors under one framework', N'10026', N'01 - Imagens/01 - Antes/11211.jpeg', N'Contractors tracked in fragmented Excel files and email threads across FTE, Safety, Quality, and Finance. No consolidated view, no trend analysis, no automated reporting. Monthly reporting required manual compilation taking several hours, with inconsistent formats between preparers and no audit trail.', N'01 - Imagens/02 - Depois/11211.jpeg', N'Five live report tabs (FTE, Safety, Quality, Finance, Dashboard), Contractor scorecard, automated HTML report generation, one-click browser launch, and Excel export. Scorecard tab delivers per-contractor YTD performance in seconds.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/0128a908-d0bf-4851-a51b-50939f4908f4?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a52b8fdb-f574-451b-bcde-02edf229c540&sourcetime=1784214249050', N'Problem solved. New tool for vendor assessment and potential ranking.', N'Scorecard composite score and trend data can aid earlier identification of underperforming contractors.', 0, NULL, N'O aplicativo resolveu o problema anterior.', '2026-06-19T00:00:00.000', '2026-07-16T12:30:03.000', N'81042793', NULL, NULL);
INSERT INTO #PVC VALUES (11212, N'763789', N'763789', N'Instalação de Espelho Convexo para Eliminação de Ponto Cego e Aumento da Segurança Viária no Acesso à Via Principal', 2, N'Others/Outros', N'Motoristas de carretas encontravam dificuldade para visualizar veículos na via principal devido à existência de ponto cego no acesso, aumentando o tempo de espera e a exposição ao risco de acidentes durante a realização da manobra.', N'Implantar uma solução permanente para eliminar o ponto cego existente no acesso à via principal, aumentando a segurança viária e estabelecendo um novo padrão operacional para motoristas de veículos leves e pesados.', N'10294', N'01 - Imagens/01 - Antes/11212.jpeg', N'No acesso à via principal, os condutores de veículos pesados encontravam dificuldade para visualizar o tráfego da faixa adjacente devido à existência de um ponto cego. A limitação de visibilidade aumentava o tempo de tomada de decisão e elevava a exposição ao risco durante a entrada na via.
INSERT INTO #PVC VALUES (11213, N'516619', N'512014', N'Melhoria na Analise de xantato', 2, N'No Replication/Sem replicação', N'Na analise atual de Xantato necessita de preparação 
INSERT INTO #PVC VALUES (11214, N'81013885', N'81013885', N'SUPORTE METALICO', 2, N'Refining/Refino', N'A carcaça da bomba era movimentada e apoiada diretamente sobre o piso ou bancada, sem um suporte específico. Essa condição dificultava o manuseio, comprometia a estabilidade da peça e aumentava o risco de tombamento, danos às superfícies de vedação, esforço ergonômico excessivo e acidentes durante o transporte.', N' ergonomia durante as atividades de manutenção e protege as faces de vedação contra impactos e avarias.', N'10362', N'01 - Imagens/01 - Antes/11214.jpeg', N'A carcaça da bomba era movimentada e apoiada diretamente sobre o piso ou bancada, sem um suporte específico. Essa condição dificultava o manuseio, comprometia a estabilidade da peça e aumentava o risco de tombamento, danos às superfícies de vedação, esforço ergonômico excessivo e acidentes durante o transporte.', N'01 - Imagens/02 - Depois/11214.jpeg', N'Foi fabricado um suporte metálico dimensionado para acomodar a carcaça da bomba de forma estável e segura. O suporte mantém a peça elevada, facilita o transporte por ponte rolante ou carrinho, melhora a ergonomia durante as atividades de manutenção e protege as faces de vedação contra impactos e avarias.', NULL, N'SIM. Facilita o transporte por ponte rolante ou carrinho, melhora a ergonomia durante as atividades de manutenção e protege as faces de vedação contra impactos e avarias.', N'melhora a ergonomia durante as atividades', 0, NULL, N'houve uma ganho significativo no tempo estimado para posicionar a avaria. Com isso há um ganho sequencial de tempo, em todos os passos da atividade, melhorando a DF do equipamento.', '2026-07-15T00:00:00.000', '2026-07-16T15:30:19.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11215, N'485273', N'485273', N'Otimização do Fornecimento de Água Potável por meio da Substituição de Galões de 20L por Sistema de Filtragem', 1, N'Others/Outros', N'O fornecimento de água por meio de galões de 20 litros gera custos recorrentes de aquisição e logística, além de exigir movimentação manual para troca dos recipientes, expondo os empregados a riscos ergonômicos. Esse processo também demanda tempo operacional e maior necessidade de armazenamento dos galões.', N'Implementar um sistema de filtragem de água diretamente nos bebedouros, substituindo o uso de galões de 20 litros, com o objetivo de promover maior ergonomia nas atividades dos empregados, eliminando a necessidade de movimentação e troca manual dos recipientes. Além disso, a iniciativa visa reduzir custos operacionais relacionados à aquisição, transporte e armazenamento de galões, bem como aumentar a eficiência no fornecimento de água potável, contribuindo para a sustentabilidade e a melhoria das condições de trabalho.', N'10017', N'01 - Imagens/01 - Antes/11215.jpeg', N'O abastecimento de água potável era realizado por meio de galões de 20 litros, que precisavam ser armazenados, transportados e substituídos manualmente sempre que esvaziavam. A atividade exigia o levantamento e manuseio dos galões pelos empregados, gerando esforço físico e risco ergonômico, além de demandar tempo para reposição e controle do estoque de água.', N'01 - Imagens/02 - Depois/11215.jpeg', N'Com a instalação de filtros nos bebedouros, o fornecimento de água passou a ser realizado diretamente no ponto de consumo, eliminando a necessidade de utilização, armazenamento e troca de galões de 20 litros. A melhoria reduziu o esforço físico dos empregados, eliminando os riscos ergonômicos associados ao manuseio dos galões, além de proporcionar redução de custos operacionais, maior praticidade no abastecimento e melhor eficiência no fornecimento de água potável.', NULL, N'Sim, a melhoria implementada atendeu à meta estabelecida, eliminando a troca manual de galões de 20 litros, reduzindo riscos ergonômicos, diminuindo custos operacionais e aumentando a eficiência no fornecimento de água potável.', N'A substituição dos galões por filtros demonstrou que soluções simples podem gerar ganhos expressivos em ergonomia, redução de custos, eficiência operacional e sustentabilidade, reforçando a importância da melhoria contínua na otimização dos processos.', 2, 1, N'Transformar o controle de refeições em um processo totalmente digital, ágil, confiável e sustentável, proporcionando maior eficiência operacional e melhor gestão dos recursos do refeitório.', '2026-07-15T00:00:00.000', '2026-07-16T15:52:19.000', N'485273', NULL, NULL);
INSERT INTO #PVC VALUES (11216, N'81013885', N'81013885', N'PROTEÇÃO DE BOMBA', 2, N'Others/Outros', N'A proteção do acoplamento possuía pequena área de visualização, dificultando a inspeção do estado do acoplamento. Para verificar visualmente componentes como elemento elástico, alinhamento aparente e condição geral, era necessário bloquear o equipamento e remover a proteção, aumentando o tempo da atividade e a exposição dos mantenedores.', N'. A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', N'10362', N'01 - Imagens/01 - Antes/11216.jpeg', N'A proteção do acoplamento possuía pequena área de visualização, dificultando a inspeção do estado do acoplamento. Para verificar visualmente componentes como elemento elástico, alinhamento aparente e condição geral, era necessário bloquear o equipamento e remover a proteção, aumentando o tempo da atividade e a exposição dos mantenedores.', N'01 - Imagens/02 - Depois/11216.jpeg', N'Foi confeccionada e instalada uma nova proteção metálica com ampla área em tela metálica de proteção, permitindo a visualização do acoplamento durante as inspeções de rotina, sem necessidade de remoção da proteção. A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', NULL, N'SIM. A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', N' A solução mantém a proteção contra contato com partes rotativas, atendendo aos requisitos de segurança, ao mesmo tempo em que facilita a inspeção visual do conjunto.', 0, NULL, N'Redução do tempo gasto na localização e retirada dos EPIs, proporcionando maior agilidade no atendimento das necessidades dos colaboradores e melhor fluidez nas atividades diárias.', '2026-07-15T00:00:00.000', '2026-07-16T15:52:21.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11217, N'81045425', N'81045425', N'TESTE NOS FREIOS DOS MOTORES', 2, N'Others/Outros', N'SEMPRE QUE ERA NECESSÁRIO TESTAR OS FREIOS INSTALADOS NOS MOTORES ERA PRECISO QUE FOSSE DADO COMANDO NO EQUIPAMENTO PARA QUE CHEGASSE TENSÃO NOS MESMOS', N'MINIMIZAR ESPOSIÇÃO A RISCOS DE CHOQUE ELÉTRICO  DURANTE TESTES NOS FREIOS', N'10294', N'01 - Imagens/01 - Antes/11217.jpeg', N'PARA QUE SE CONSEGUISSE TESTAR OS FREIOS DA TRANSLAÇÃO DO CN ERA NECESSÁRIO QUE FOSSE DADO COMANDO NA TRANSLAÇÃO E AS VERIFICAÇÕES FOSSE FEITAS COM O CN EM MOVIMENTO, AUMENTANDO O RISCO  ELÉTRICO.', N'01 - Imagens/02 - Depois/11217.jpeg', N'APÓS CRIAÇÃO DO DISPOSITIVO PARA TESTE, PODEMOS TESTAR OS FREIOS COM O EQUIPAMENTO PARADO E BLOQEADO. ', NULL, N'ALÉM DE REDUZIR O RISCO DE CHOQUE ELÉTRICO, ELIMINAMOS O RISCO DE ESMAGAMENTO PELO MOVIMENTO DO CN DURANTE OS TESTES NOS FREIOS', N'Às vezes, a verdadeira mudança começa quando criamos nossas próprias inovações, e assim transformamos cenários e promovemos a evolução.', 0, NULL, N'MELHOROU A PRODUTIVIDADE EM TODOS O MOMENTOS COM UMA ILUMINAÇÃO MAIS REFORÇADA. COM CUSTO DE R$149,23 POR CADA UMA LUMINÁRIA FABRICADA NESTE MODELO DE EXTENSÃO.', '2026-07-10T00:00:00.000', '2026-07-16T16:31:57.000', N'81045425', NULL, NULL);
INSERT INTO #PVC VALUES (11218, N'81060535', N'81060535', N'Implementação de Sinalização de Segurança para Uso Seguro do Elevador de Cargas do Laboratório Físico 1.', 2, N'Others/Outros', N'Foi identificada a ausência de sinalização de segurança no elevador de cargas do laboratório Físico 1. A falta de comunicação visual não evidenciava os riscos e perigos da utilização do equipamento, essa condição pode dificultar a percepção do risco pelos usuários, aumentando o potencial de acidentes durante a operação do elevador. O mesmo possui abertura de portas de correr que podem vir a fechar rapidamente prensando dedos e mãos, o que ocasionaria em uma ocorrência operacional.
INSERT INTO #PVC VALUES (11219, N'87000312', N'87000339', N'Energy savings through reduced operating frequency of the No. 2 leak acid pit pump', 1, N'Refining/Refino', N'During 3RT operations, condensate from the No. 3 Final MC continuously overflows from the seal tank into the No. 2 leak acid pit. Since this liquid cannot be discharged directly, it is collected in the No. 2 leak acid pit and periodically pumped to the water treatment process.', N'Reduction of pump operating time and working time', N'0', N'01 - Imagens/01 - Antes/11219.jpeg', N'During 3RT operations, condensate from the No. 3 Final MC continuously overflows from the seal tank into the No. 2 leak acid pit. Since this liquid cannot be discharged directly, it is collected in the No. 2 leak acid pit and periodically pumped to the water treatment process.', N'01 - Imagens/02 - Depois/11219.jpeg', N'Liquid from the No. 3 Final MC spray pump is sent via piping to the 3EAT-PT unit, where it undergoes treatment in the water treatment process. This has resulted in reduced electricity costs associated with pump operation and a reduced man power.', NULL, N'Yes, we could achieve the target as we thought.', N'Asset ', 0, NULL, N'Permitir que qualquer usuário do Painel de Telemetria Unificada compreenda rapidamente não apenas a ocorrência do evento, mas também todo o histórico de ações executadas para sua análise e tratamento.', '2026-07-15T00:00:00.000', '2026-07-17T05:30:32.000', N'87000312', NULL, NULL);
INSERT INTO #PVC VALUES (11220, N'81046830', N'1010414', N'SEW Drive Replacement Procedure', 1, N'Others/Outros', N'SEW drives are used within our Ionic vendor equipment systems, this is a limited footprint and can be challenging to work with if not prepared.', N'Allow for efficient replacement of failed SEW drive equipment.', N'0', N'01 - Imagens/01 - Antes/11220.jpeg', N'SEW drive failures can become a challenge to replace efficiently due to the small footprint of the equipment on site. However, the equipment is important to keep the CSM and Inking Stations running.', N'01 - Imagens/02 - Depois/11220.jpeg', N'Developed a SEW drive replacement procedure and guide to assist field and control technicians when another failure occurs.', NULL, N'Work instruction developed to assist with a more efficient replacement of SEW drives.', N'Important to develop work instructions for future use', 0, NULL, N'Garantir que os spots permaneçam ativos e transmitindo dados regularmente, assegurando monitoramento contínuo dos ativos e suporte às análises de confiabilidade da Mina de Salobo.', '2026-07-16T00:00:00.000', '2026-07-17T06:50:41.000', N'81046830', NULL, NULL);
INSERT INTO #PVC VALUES (11221, N'81043724', N'81043724', N'TABELA DE TAG ', 3, N'Others/Outros', N'O RESPONSAVEL PELA SALA DE CADASTRO TINHA QUE IR TODOS OS DIAS VERIFICAR AS TAG DOS EQUIPAMENTOS PARA LANCAMENTO. O QUE DEMANDAVA MUITO TEMPO NO PROCESSO EM CASO DE MANUTENCAO ERA PRECISO FAZER ESSA VERIFICACAO NAS SALAS PARA ACIONAMENTO DA EQUIPE .', N'ELIMINAR TEMPO NA PROCURA DAS TAG ', N'10366', N'01 - Imagens/01 - Antes/11221.jpeg', N'NÃO EXISTIA UMA PADRONIZAÇÃO COM TODAS AS TAG DISPONIVEIS, ERA NECESSARIO FICAR INDO ATE OS EQUIPAMENTOS PARA VERIFICACAO DAS MESMAS ', N'01 - Imagens/02 - Depois/11221.jpeg', N'FOI DISPONIBILIZADO UMA TABELA COM TODAS AS TAG EXISTENTE NAS SALA DO LABORATORIO FISICO O QUE ELIMINOU O MOVIMENTO DE ESTA INDO TODO OS DIAS VERIFICAR AS TAG EM CADA EQUIPAMENTOS .GANHAMOS TEMPO E AGILIDADE NO PROCESSO DE LANCAMENTO E NA MANUTENÇÃO ', NULL, N'ANTES TINHAMOS QUE IR OLHAR OS TAG VARIAS VEZES DURANTE O TURNO NO EQUIPAMENTO, AGORA TEMOS DISPONIVEL NA SALA DE CADASTRO COM TODOS OS TAG .', N'COM O SIMPLES FATO DE CRIAR UMA TABELA ELIMANOS VARIOS MOVIMENTOS DURANTE O DIA .', 0, NULL, N'Permitir que todos os eventos de telemetria da Mina de Salobo sejam tratados dentro de uma única plataforma, garantindo padronização, rastreabilidade e acompanhamento contínuo das ocorrências.', '2026-07-11T00:00:00.000', '2026-07-17T10:59:26.000', N'81043724', NULL, NULL);
INSERT INTO #PVC VALUES (11222, N'608046', N'81010661', N'Truck Unloading-Wheel Chocks', NULL, N'Others/Outros', N'Previously utilized wheel chocks were rubber wedges, awkward to handle, bend down to ground level to install and usually were not left in place for ease of reagent unloading, as required.', N'Reagent-Handling-Safety', N'10114', N'01 - Imagens/01 - Antes/11222.jpeg', N'Rubber wheel chock left in unloading areas, didn''t have a storage station, hard to handle and usually not in pairs.', N'01 - Imagens/02 - Depois/11222.jpeg', N'Cl2/H2SO4/NaOH-unloading stations implemented new wheel chock positions at all locations, ergonomic-easy to utilize and install during offloading of reagents.', NULL, N'Yes-reagent handler doesn''t have to leave area to locate wheel chocks-they are in unloading areas in position and readily available. ', N'ergonomically friendly/ease of accessibility', 0, NULL, N'Garantir controle completo sobre as substituições de componentes da frota, permitindo análises históricas, gestão da vida útil e suporte à tomada de decisão baseada em dados.', '2026-07-15T00:00:00.000', '2026-07-17T11:18:52.000', N'608046', NULL, NULL);
INSERT INTO #PVC VALUES (11223, N'200746', N'200746', N'Population of Lot # on Co Certificates of Analysis', NULL, N'Others/Outros', N'Lot number information wasn''t consistently being populated on the cobalt certificates of analysis being auto generated by LIMS', N'Consistent addition of lot information to cobalt certificates of analysis', N'10286', N'01 - Imagens/01 - Antes/11223.jpeg', N'When logging cobalt product in LIMS, the barcode wasn''t consistently being scanned into the ID1 field.  When CoA''s are auto-generated by LIMS, the system pulls the information inputted into the ID1 field to populate the lot number on the certificate.  This information was often missing.  The procedure for logging final product also did not include instructions for scanning the barcode information in LIMS.', N'01 - Imagens/02 - Depois/11223.jpeg', N'A LIMS ticket was entered to make the ID1 field in LIMS mandatory when logging Co product.  This would ensure that the necessary information would be inputted into the system and that it would be available for CoA generation.  The procedure for logging final product was also revised to include instructions pertaining to scanning the product barcode into the ID1 field in LIMS.', NULL, N'Required information is now available in LIMS.  The goal has been achieved.', N'Creating mandatory fields helps serve as a reminder to include necessary important information', 0, NULL, N'Permitir que os eventos provenientes da plataforma My Sandvik sejam acompanhados e tratados dentro do mesmo fluxo operacional das demais fontes de telemetria, garantindo padronização, rastreabilidade e maior eficiência das análises.', '2026-07-16T00:00:00.000', '2026-07-17T11:27:04.000', N'200746', NULL, NULL);
INSERT INTO #PVC VALUES (11224, N'81034239', N'81030330', N'App Gestão Operacional', 1, N'Others/Outros', N'O processo de elaboração do relatório de turno era realizado exclusivamente por meio de mensagens no WhatsApp, o que dificultava a padronização e o controle das informações registradas. As ocorrências, resultados e atividades do turno ficavam dispersos em diferentes mensagens, tornando a consulta ao histórico lenta e pouco eficiente.', N'Melhorar o relatório de turno do laboratório', N'10366', N'01 - Imagens/01 - Antes/11224.jpeg', N'O relatório de turno era realizado exclusivamente por meio de mensagens em grupos de WhatsApp. As informações eram registradas de forma não padronizada e a consulta do histórico geral não era eficiente.', N'01 - Imagens/02 - Depois/11224.jpeg', N'O relatório de turno passou a ser realizado por meio de um aplicativo desenvolvido em Power Apps, proporcionando um processo padronizado, estruturado e centralizado. O app garante rastreabilidade.', NULL, N'O problema foi resolvido.', N'O app melhorou a organização e rastreabilidade dos dados', 0, NULL, N'Produção / Tempo', '2026-07-13T00:00:00.000', '2026-07-17T11:29:36.000', N'81034239', NULL, NULL);
INSERT INTO #PVC VALUES (11225, N'81006571', N'81040190', N'SUPORTE DE IÇAMENTO EIXO MO03', 1, N'Others/Outros', N'Antes era necessário uso de uma chapa lisa para içamento do eixo podendo haver desprendimento durante a elevação do eixo', N'Eliminar improvisos', N'10362', N'01 - Imagens/01 - Antes/11225.jpeg', N'A atividade de elevação do eixo era executada de forma manual e sem a utilização de suporte específico, o que expunha os colaboradores a riscos de prensamento de membros superiores e inferiores, além da exposição direta à linha de fogo. 
INSERT INTO #PVC VALUES (11226, N'516619', N'552800', N'Melhoria da Descarga de Efluentes do Peneirador Suspenso', 2, N'No Replication/Sem replicação', N'O colaborador precisa realizar o descarte da água na pia várias vezes ao dia. Atividade gera desgaste físico.', N'Eliminar o trabalho manual de retirada do balde com efluente de descarte ', N'10366', N'01 - Imagens/01 - Antes/11226.jpeg', N'Durante os testes de granulometria no peneirador suspenso, o colaborador precisava retirar continuamente a água acumulada com um balde e descartá-la na pia diversas vezes ao dia. Essa atividade, apesar de realizada dentro dos limites operacionais estabelecidos, exigia esforço físico repetitivo, aumentando o risco de sobrecarga lombar, além da exposição a riscos ergonômicos, quedas e impactos.', N'01 - Imagens/02 - Depois/11226.jpeg', N'A melhoria implementada consistiu na instalação de tubulações de drenagem para conduzir os efluentes diretamente à canaleta de rejeitos, eliminando a necessidade de coleta e descarte manual da água em baldes. Com essa adequação, foi eliminado o esforço físico associado à atividade, reduzindo significativamente a exposição a riscos ergonômicos, sobrecarga lombar, quedas e impactos, além de proporcionar maior segurança e eficiência operacional.', NULL, N'A solução atingiu integralmente a meta proposta, eliminando o esforço físico associado à atividade.', N'A eliminação de atividades manuais repetitivas contribui significativamente para a redução dos riscos ergonômicos e para a preservação da saúde dos colaboradores.', 0, NULL, N'Agora não há necessidade de realizar conexões elétricas e se expor a riscos de choque em baixa tesão. A atividade ficou mais segura e rápida.', '2026-07-16T00:00:00.000', '2026-07-17T13:38:12.000', N'516619', NULL, NULL);
INSERT INTO #PVC VALUES (11227, N'520770', N'520770', N'FACILIDADE DE POSICIONAR', 1, N'Others/Outros', N'DIFICULDADE PARA INDENTIFICAR PONTO CORRETO NO POSICIONAMENTO DA CORREIA ', N'FACILITAR POSICIONAMENTO', N'10031', N'01 - Imagens/01 - Antes/11227.jpeg', N'por a correia rodar muito rápido, havia dificuldade para identificar o ponto a ser posicionado para reparo em determinado local', N'01 - Imagens/02 - Depois/11227.jpeg', N'Foi comprado spray amarelo para fazer marcação bem visivel para identificação durante a operação da correia.
INSERT INTO #PVC VALUES (11228, N'485273', N'485273', N'Implantação de Catraca Digital para Automação da Contagem de Refeições e Eliminação da Lista de Assinaturas', 1, N'Others/Outros', N'Atualmente, o controle e a contagem de refeições são realizados por meio de listas de assinatura em papel no refeitório. Esse processo é manual, demandando tempo para preenchimento, conferência e consolidação das informações, além de estar sujeito a falhas como assinaturas ilegíveis, esquecimentos, duplicidade de registros e divergências na contabilização das refeições.
INSERT INTO #PVC VALUES (11229, N'482858', N'81013746', N'Organização dos EPI''s nas prateleiras', 3, N'Others/Outros', N'EPIs acomodados nas prateleiras, ocupando espaço e aspecto de desordem', N'Deixar o local organizado, otimizar espaço', N'10257', N'01 - Imagens/01 - Antes/11229.jpeg', N'EPIs acomodados diretamente nas prateleiras, ocupando espaço de forma inadequada e sem um padrão definido de organização. Essa condição gera um aspecto visual de desordem, dificulta a identificação e o acesso rápido aos materiais.', N'01 - Imagens/02 - Depois/11229.jpeg', N'Foram instaladas caixas de acrílico nas prateleiras para armazenar os EPIs de forma organizada, reduzindo a desordem visual, facilitando a identificação dos itens e otimizando o espaço disponível.', NULL, N'Sim. A implementação das caixas de acrílico proporcionou melhor organização dos EPIs, diminuindo o tempo de procura e acesso aos materiais.', N'Soluções simples e de baixo custo, o acesso e a reposição dos itens, ', 0, NULL, N'A MUDANÇA GARANTE MUITO MAIS RESISTÊNCIA, EVITA QUEBRAS E DEIXA O EQUIPAMENTO COM MAIS DURABILIDADE E VIDA ÚTIL.', '2026-03-02T00:00:00.000', '2026-07-17T14:56:05.000', N'482858', NULL, NULL);
INSERT INTO #PVC VALUES (11230, N'522369', N'522369', N'LUMINÁRIA PORTÁTIL REFORÇADA ANTI-IMPACTO COM EXTENSÃO DE CABO 5 M NO PLUG INDUSTRIAL 220V', 2, N'Others/Outros', N'DIFICULDADE DE ILUMINAÇÃO NA FRENTE DE SERVIÇO DURANTE TURNO DIA E NOITE NA MOAGEM/TRANSPORTADORES', N'MELHORAR E PADRONIZAR ILUMINAÇÃO NA FRENTE DE SERVIÇO PARA ELÉTRICA/MECÂNICA/OPERAÇÃO', N'10031', N'01 - Imagens/01 - Antes/11230.jpeg', N'DIFICULDADE DE ILUMINAÇÃO NA FRENTE DE SERVIÇO MECÂNICA/ELÉTRICA/OPERAÇÃO NOS TURNOS DE DIA/NOITE NA MOAGEM/TRANSPORTADORES USINAS I,II,III.', N'01 - Imagens/02 - Depois/11230.jpeg', N'FOI DESENVOLVIDO UMA LUMINÁRIA DE LED REFORÇADA ANTI-IMPACTO COM EXTENSÃO DE 5 METROS COM PLUG INDUSTRIAL 220V. PARA MELHORAR E REFORÇAR ILUMINAÇÃO NAS FRENTES DE SERVIÇO COM BAIXA LUMINOTÉCNICA. COM CUSTO R$149,23 PARA FABRICAR ESTE MODELO DE EXTENSÃO DE CABO COM PLUG 220V.', NULL, N'SIM RESOLVIDO E COM APLICAÇÃO COM 6 LUMINÁRIAS PORTÁTIL FABRICADAS COM REFORÇO ANTI-IMPACTO COM CABO DE EXTENSÃO COM PLUG 220V.', N'MELHORIA CONTÍNUA PARA EXPOR MENOS NOSSOS COLABORADORES AO RISCOS OCUPACIONAIS', 1, 1, N'Facilidade em cruzar o pote correto com a tampa correta imediatamente.
INSERT INTO #PVC VALUES (11231, N'92000576', N'92000576', N'Implantação de Agente de IA para Consulta Inteligente do Histórico de Validações e Notas no Portal CMA Connect', 1, N'Projects/Projetos', N'Durante a validação dos alertas de telemetria no portal CMA Connect, os técnicos precisavam consultar diferentes bases para entender o histórico de tratativas já realizadas para um determinado alerta ou equipamento. Esse processo exigia buscas manuais em validações anteriores e em notas de manutenção, aumentando o tempo de análise e dificultando a identificação rápida das ações já executadas.', N'Disponibilizar de forma automática, durante a validação dos alertas, o histórico das últimas tratativas realizadas, incluindo validações anteriores, comentários técnicos, notas abertas ou encerradas e recomendações de atuação, apoiando a tomada de decisão do usuário.', N'10015', N'01 - Imagens/01 - Antes/11231.jpeg', N'Antes da melhoria, os técnicos realizavam a validação dos alertas utilizando apenas as informações do evento atual. Para consultar o histórico de ocorrências semelhantes era necessário acessar outras bases e procurar manualmente validações anteriores, comentários registrados e notas relacionadas ao equipamento. Esse processo consumia tempo e dificultava a identificação rápida das ações já executadas anteriormente.', N'01 - Imagens/02 - Depois/11231.jpeg', N'Foi desenvolvido um Agente de IA integrado ao portal CMA Connect, disponível na tela de validação de alertas. A solução realiza consultas automáticas na base de validações e na base de notas de manutenção, consolidando informações relevantes sobre tratativas anteriores do mesmo alerta ou equipamento. O recurso apresenta ao usuário o status da última validação, comentários registrados anteriormente, notas identificadas, status da nota, data de encerramento e recomendações para apoio à tomada de decisão. Dessa forma, o técnico consegue visualizar rapidamente o histórico completo da ocorrência sem necessidade de pesquisas manuais em outros sistemas.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/2a525ae8-4308-4fc2-bf1d-4fd5d261053c?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a0778281-b342-4712-b9cd-717bbb90e274&sourcetime=1783355034446&source=portal', N'✅ SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11232, N'92000576', N'92000576', N'Integração do Histórico de Intervenções do CMA Connect ao Painel de Telemetria Unificada para Rastreabilidade das Tratativas de Eventos', 1, N'Others/Outros', N'O Painel de Telemetria Unificada consolidava eventos de diversas plataformas de telemetria utilizadas na Mina de Salobo, como Vision Link, MineCare, MHT Monitor, My Sandvik. No entanto, apesar de apresentar informações detalhadas dos eventos, o painel não possuía visibilidade sobre as tratativas realizadas após a ocorrência dos alarmes. Dessa forma, os usuários conseguiam identificar os eventos, mas não tinham acesso ao histórico das intervenções executadas pelas equipes', N'Integrar ao Painel de Telemetria Unificada o histórico de intervenções registradas no CMA Connect, permitindo que os usuários visualizem as tratativas realizadas para cada evento e equipamento, promovendo rastreabilidade, padronização e apoio à tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/11232.jpeg', N'Antes da melhoria, o Painel de Telemetria Unificada apresentava informações detalhadas sobre os eventos dos equipamentos, incluindo criticidade, data, horário, frequência e evolução dos alarmes. Entretanto, não existia integração com o histórico de intervenções realizadas pelas equipes de telemetria. Para verificar se um evento já havia sido analisado, tratado ou se possuía nota associada, era necessário consultar outras fontes de informação, dificultando o entendimento completo do histórico do evento.', N'01 - Imagens/02 - Depois/11232.jpeg', N'Foi criada uma nova área no Painel de Telemetria Unificada dedicada ao histórico de intervenções registradas no CMA Connect. A solução integra automaticamente os eventos de telemetria às tratativas executadas pelas equipes do CMA e do CCM, permitindo visualizar informações como comentários técnicos, validações realizadas, abertura de notas, parada de equipamentos, responsáveis pela análise e demais ações registradas durante o tratamento do evento. Com essa integração, os usuários passaram a ter uma visão completa do ciclo do evento, desde sua ocorrência até as ações executadas para sua tratativa.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/57b68cba-2247-4f57-899a-a8bd95b9b745/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'✅ SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11233, N'92000576', N'92000576', N'Criação do Painel de Gestão de Coletas DynaPredict para Monitoramento e Priorização de Spots sem Comunicação', 1, N'Others/Outros', N'Os spots da plataforma DynaPredict são responsáveis pela coleta de dados de vibração dos equipamentos monitorados. Antes da implantação do painel, não existia uma ferramenta centralizada para acompanhar quais spots estavam sem comunicação, há quanto tempo estavam sem enviar dados e quais deveriam ser priorizados para atuação. Essa limitação dificultava a gestão dos ativos monitorados e aumentava o risco de equipamentos permanecerem longos períodos sem monitoramento de condição.', N'Desenvolver um painel de gestão que permita monitorar continuamente os spots sem coleta, identificar atrasos, definir prioridades de atuação e direcionar as ações para os responsáveis de cada frota, garantindo maior disponibilidade do monitoramento de vibração.', N'10015', N'01 - Imagens/01 - Antes/11233.jpeg', N'Antes da implantação do painel, não existia uma visão consolidada dos spots que estavam sem envio de dados de vibração. A identificação dependia de consultas manuais na plataforma DynaPredict, dificultando o acompanhamento dos atrasos e a definição de prioridades. Como resultado, alguns spots permaneciam longos períodos sem comunicação, comprometendo o monitoramento de condição dos equipamentos.', N'01 - Imagens/02 - Depois/11233.jpeg', N'Foi desenvolvido o painel Gestão de Coletas DynaPredict, integrado à plataforma Dynamox, permitindo monitorar todos os spots sem comunicação e classificá-los por faixas de atraso. O painel apresenta a distribuição dos spots por criticidade (até 30 dias, de 30 a 60 dias, de 60 a 90 dias e acima de 90 dias sem coleta), além da quantidade total de spots sem comunicação por frota. A solução permite filtrar informações por frota e identificar rapidamente o responsável pela tratativa, tornando o processo de gestão mais eficiente e direcionado. Dessa forma, a equipe consegue atuar de forma proativa para restabelecer a coleta de dados e garantir a continuidade do monitoramento de vibração dos equipamentos.
INSERT INTO #PVC VALUES (11234, N'92000576', N'92000576', N'Integração dos Eventos de Telemetria do MHT Monitor ao Portal CMA Connect para Centralização e Tratativa de Alertas Operacionais', 1, N'Others/Outros', N'O portal CMA Connect já recebia eventos provenientes de diversas fontes de telemetria utilizadas na Mina de Salobo, permitindo o registro, validação e acompanhamento das tratativas realizadas pelas equipes técnicas. Entretanto, os eventos do sistema MHT Monitor, responsável pelo monitoramento das perfuratrizes elétricas, ainda não estavam integrados ao portal, exigindo consultas e acompanhamentos separados e reduzindo a centralização das informações de telemetria.', N'Integrar os eventos do sistema MHT Monitor ao portal CMA Connect, permitindo que os alertas das perfuratrizes elétricas sejam recebidos, validados, tratados e acompanhados dentro da mesma plataforma já utilizada pelo CMA e pela Telemetria.', N'10015', N'01 - Imagens/01 - Antes/11234.jpeg', N'Antes da melhoria, o portal CMA Connect consolidava eventos provenientes de plataformas como MineCare, VisionLink e outras fontes de telemetria. Entretanto, os eventos gerados pelo MHT Monitor não estavam integrados ao processo de validação do portal. Como consequência, as ocorrências das perfuratrizes elétricas não seguiam o mesmo fluxo padronizado de acompanhamento, reduzindo a visibilidade e a centralização das informações.', N'01 - Imagens/02 - Depois/11234.jpeg', N'Foi realizada a integração dos eventos do sistema MHT Monitor ao portal CMA Connect, permitindo que os alertas gerados pelas perfuratrizes elétricas passem a seguir o mesmo fluxo de validação já utilizado para as demais fontes de telemetria. A partir da integração, os técnicos passaram a registrar comentários, validar eventos, informar tratativas realizadas, associar notas e realizar o acompanhamento completo das ocorrências diretamente no portal. Com isso, o CMA Connect ampliou sua capacidade de consolidação de eventos, tornando-se ainda mais aderente ao conceito de Centro Integrado de Eventos de Telemetria e Manutenção.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/2a525ae8-4308-4fc2-bf1d-4fd5d261053c?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a0778281-b342-4712-b9cd-717bbb90e274&sourcetime=1783355034446&source=portal', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11235, N'92000576', N'92000576', N'Criação de Algoritmo para Identificação de Trocas de Componentes e Geração do Histórico Automatizado de Substituições da Frota', 1, N'Others/Outros', N'As informações de substituição de componentes estavam distribuídas em registros operacionais do SAP ECC, sem uma visão consolidada que permitisse identificar automaticamente quando um componente era removido e substituído por outro. Essa limitação dificultava análises de vida útil, aderência aos ciclos de troca, acompanhamento de componentes vencidos e rastreabilidade das substituições realizadas na frota.', N'Desenvolver algoritmos capazes de identificar automaticamente as substituições de componentes e disponibilizar essas informações em um painel dedicado, permitindo rastreabilidade, análise da vida útil dos componentes e acompanhamento da aderência aos planos de manutenção.', N'10015', N'01 - Imagens/01 - Antes/11235.jpeg', N'Antes da melhoria não existia uma visão estruturada do histórico de substituições dos componentes da frota. As informações estavam dispersas em registros operacionais e não havia uma lógica capaz de identificar automaticamente quando um componente era removido e substituído. Isso dificultava análises de confiabilidade, acompanhamento da vida útil dos componentes e avaliação da aderência aos ciclos de manutenção.', N'01 - Imagens/02 - Depois/11235.jpeg', N'Foi desenvolvido um algoritmo baseado em gatilhos dos registros do SAP ECC capaz de identificar automaticamente quando um componente é removido e substituído por outro. A partir dessa lógica foi criado um histórico automatizado de substituições, permitindo rastrear a data da troca, horímetro do componente, percentual de vida consumida, ciclo planejado, status da vida útil e demais informações relevantes. Esses dados passaram a alimentar uma nova página no painel Gestão de Componentes, disponibilizando indicadores por frota, equipamento e componente, além de apoiar análises de confiabilidade, aderência aos ciclos de manutenção e gestão do ciclo de vida dos ativos.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/5e15fa89-9fd0-4a3c-8f20-853460bc50c0/e6efa35044639a37e7e7?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11236, N'92000576', N'92000576', N'Integração dos Eventos de Telemetria do My Sandvik ao Portal CMA Connect para Centralização e Tratativa de Alertas Operacionais', 1, N'Others/Outros', N'O portal CMA Connect já consolidava eventos de telemetria provenientes de diferentes plataformas utilizadas na Mina de Salobo, permitindo o registro, validação e acompanhamento das tratativas realizadas pelas equipes técnicas. Entretanto, os eventos provenientes da plataforma My Sandvik ainda não estavam integrados ao portal, exigindo consultas separadas e dificultando a centralização das informações e das ações executadas pelas equipes de telemetria.', N'Integrar os eventos do My Sandvik ao portal CMA Connect, permitindo que os alertas gerados pelos equipamentos monitorados pela plataforma sejam recebidos, validados, tratados e acompanhados dentro do mesmo fluxo operacional utilizado pelas demais fontes de telemetria.', N'10015', N'01 - Imagens/01 - Antes/11236.jpeg', N'Antes da melhoria, os eventos gerados pela plataforma My Sandvik não faziam parte do fluxo operacional do CMA Connect. Dessa forma, os técnicos precisavam consultar fontes distintas para acompanhar ocorrências, reduzindo a centralização das informações e dificultando a rastreabilidade das análises e tratativas realizadas.', N'01 - Imagens/02 - Depois/11236.jpeg', N'Foi realizada a integração dos eventos da plataforma My Sandvik ao portal CMA Connect, permitindo que os alertas gerados pelos equipamentos monitorados sejam recebidos automaticamente e passem a seguir o mesmo fluxo de validação utilizado pelas demais fontes de telemetria. Após a integração, os técnicos passaram a registrar comentários, validar eventos, associar notas de manutenção, informar tratativas executadas e acompanhar todo o histórico das ocorrências diretamente no portal. Com isso, o CMA Connect ampliou sua cobertura operacional e passou a consolidar mais uma importante fonte de telemetria dentro de um ambiente único de gestão.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/2a525ae8-4308-4fc2-bf1d-4fd5d261053c?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=a0778281-b342-4712-b9cd-717bbb90e274&sourcetime=1783355034446&source=portal', N'SIM – O objetivo foi atingido.
INSERT INTO #PVC VALUES (11237, N'81042217', N'81018130', N'Implantação de alerta visual e sonoro para prevenção de deslocamento do caminhão-pipa com a tomada de força (PTO) acionada', 2, N'Others/Outros', N'Foram registradas ocorrências recorrentes de quebra da tomada de força (PTO) do caminhão-pipa devido ao deslocamento do veículo com o sistema ainda acionado. A condição era causada principalmente pelo esquecimento do operador em desacionar a PTO antes da movimentação do equipamento, gerando falhas mecânicas, indisponibilidade do veículo e custos de manutenção.
INSERT INTO #PVC VALUES (11238, N'81037761', N'81037761', N'Alarme Crítico Prevenção de Desarme das Bombas por Nível Baixo nas Torres de Resfriamento dos Moinhos Salobo 3', 1, N'No Replication/Sem replicação', N'Quando ocorre a redução do nível de água nas torres de resfriamento dos moinhos do Salobo 3, há oscilação na vazão das bombas. Essa condição pode não ser percebida em tempo hábil pelo técnico da sala de controle para acionar a operação e realizar a verificação em campo, podendo resultar no desarme das bombas e em cortes de alimentação da usina. Ocorre que existe um alerta mas o mesmo não está oferecendo tempo suficiente para evitar os desarmes e cortes de alimentação. ', N'Identificação rápida e proteção para evitar o desarme das bombas das torres de resfriamento dos moinhos, prevenindo interrupções e cortes de alimentação na usina.', N'10025', N'01 - Imagens/01 - Antes/11238.jpeg', N'Quando ocorre a redução do nível de água nas torres de resfriamento dos moinhos do Salobo 3, há oscilações na vazão das bombas. Essa condição nem sempre é identificada em tempo hábil pelo técnico da sala de controle para acionar a equipe de operação e realizar a verificação em campo, podendo evoluir para o desarme das bombas e consequentes cortes de alimentação da usina. Atualmente, existe um alerta configurado para vazão inferior a 270 m³/h; entretanto, esse aviso não proporciona tempo de resposta suficiente para a adoção de ações corretivas, resultando na ocorrência de desarmes e impactos operacionais no processo.', N'01 - Imagens/02 - Depois/11238.jpeg', N'Foi implementado um alerta com acionamento a partir de 390 m³/h de vazão no bombeamento (vazão pela qual as bombas iniciam a cavitação), exibido na tela do supervisório (Água Refrigerada e na tela dos moinhos), para indicar ao técnico da sala de controle uma possível redução do nível das torres de resfriamento dos moinhos. Essa antecipação proporciona tempo hábil para acionar a operação e realizar a verificação em campo, mitigando o risco de desarme das bombas e evitando cortes de alimentação da usina.', NULL, N'Alarme funcional e com visibilidade na tela dos moinhos e na tela de água refrigerada das torres no supervisório da sala de controle toda vez que acontece a redução da vazão do bombeamento das torres dos moinhos.', N'A importância de evitar desarmes das bombas e cortes de alimentação da usina, garantindo maior segurança dos equipamentos, estabilidade operacional e produtividade.', 0, NULL, N'eliminar risco de projeção de corpo moedor.', '2026-07-17T00:00:00.000', '2026-07-18T03:16:52.000', N'81037761', NULL, NULL);
INSERT INTO #PVC VALUES (11239, N'81060357', N'81060357', N'Conector Seguro e Rápido para testes Elétricos', 1, N'Others/Outros', N'Anteriormente, quando necessário realizar um teste de funcionalidade com algum dispositivo eletrônico, como Gateways ou Elsys era necessário buscar um conector macho e realizar as conexões elétricas, o que tomava muito tempo, pois nem sempre as ferramentas, cabos ou conectores estavam a disposição. Nesses casos, eram utilizadas conexões rudimentares que não são seguras e poderiam ocasionar problemas.', N'Minimizar riscos e agilizar o processo de teste de Gateways e Antenas Elsys', N'10178', N'01 - Imagens/01 - Antes/11239.jpeg', N'Anteriormente, quando necessário realizar um teste de funcionalidade com algum dispositivo eletrônico, como Gateways ou Elsys era necessário buscar um conector macho e realizar as conexões elétricas, o que tomava muito tempo, pois nem sempre as ferramentas, cabos ou conectores estavam a disposição. Nesses casos, eram utilizadas conexões rudimentares que não são seguras e poderiam ocasionar problemas.', N'01 - Imagens/02 - Depois/11239.jpeg', N'Criamos uma pequena extensão que já conta com o conector macho e 2 conectores tipo Wago para facilitar a alimentação dos dispositivos. A atividade que antes levava vários minutos para ser feita corretamente ou era feita de forma rudimentar agora é feita de forma segura em menos de 1 minuto com 2 ''clicks''.', NULL, N'O problema foi resolvido por completo. A simples solução permite uma rápida conexão elétrica sem a necessidade de fazer ligações de tomada ou cabos. Agora a atividade é segura e ágil. ', N'Soluções simples aumentam a segurança e otimizam o tempo', 0, NULL, N'Condição de acesso seguro ao desnível para acesso ao chute.', '2026-07-17T00:00:00.000', '2026-07-18T10:42:05.000', N'81060357', NULL, NULL);
INSERT INTO #PVC VALUES (11240, N'542033', N'999359', N'CONTROLE DOS GUINCHOS AUXILIARES', 2, N'Projects/Projetos', N' O controle de acionamento do guincho auxiliar da máquina elétrica 7495 HD/HR não possuía dispositivo de parada de emergência integrado e apresentava menor resistência às condições operacionais da área.', N' Melhorar as condições de segurança, ergonomia e confiabilidade operacional do sistema de acionamento do guincho auxiliar da máquina 7495 HD/HR, reduzindo a exposição dos colaboradores a riscos, permitindo parada rápida em situações de emergência e aumentando a durabilidade do equipamento.', N'10324', N'01 - Imagens/01 - Antes/11240.jpeg', N' Anteriormente, o guincho auxiliar da máquina elétrica 7495 HD/HR era operado por um controle de acionamento que não possuía botoeira de emergência integrada, o que limitava a capacidade de interrupção imediata da operação em situações de risco.
INSERT INTO #PVC VALUES (11241, N'81009130', N'81009130', N'Dispositivo de Acesso seguro no telhado', 2, N'Projects/Projetos', N'Acesso improvisado ao telhado, sem padronização e sem atendimento ao PRO e risco elevado de escorregamento devido à ausência de uma superficie segura sem aderência.', N'Segura e estabilidade de acesso', N'10056', N'01 - Imagens/01 - Antes/11241.jpeg', N'Acesso improvisado ao telhado, sem padronização e sem atendimento ao PRO 026780de Acesso ao telhado e risco elevado de escorregamento devido à ausência de uma superfície segura sem aderência que garantisse estabilidade no acesso e interdição recorrente e atrasos nas atividades.', N'01 - Imagens/02 - Depois/11241.jpeg', N'Com objetivo de aumentar a segurança, eliminar improvisos e padronizar o acesso aos telhados, foi desenvolvido e implementado um dispositivo de acesso ao telhado, que garante maior estabilidade e segurança para o acesso entrada e saída dos colaboradores agilidade de montagens e fácil instalação.', NULL, N'Sim, maior segurança durante o acesso no telhado. ', N'Avaliação de atividades  prévia', 0, NULL, N'Instalar uma barreira fisica nas canaletas próximo a caldeiraria da moagem , e melhorar condições visuais do local. ', '2026-07-17T00:00:00.000', '2026-07-18T10:59:22.000', N'81009130', NULL, NULL);
INSERT INTO #PVC VALUES (11242, N'81057520', N'81057520', N'SUPORTE PARA BRAÇO MECÂNICO DO PULVERIZADOR', 2, N'Projects/Projetos', N'Antes, contávamos apenas com um pequeno gancho para essa função, que por ser frágil, acabava se danificando e  com isso vindo a quebrar com frequência e gerando manutenções constantes.', N'AJUDAR NA DURABILIDADE DO EQUIPAMENTO', N'10129', N'01 - Imagens/01 - Antes/11242.jpeg', N'Antes, contávamos apenas com um pequeno gancho para essa função, que por ser frágil, acabava se danificando e  com isso vindo a quebrar com frequência  gerando manutenções constantes.', N'01 - Imagens/02 - Depois/11242.jpeg', N'Agora, implementamos uma solução com lona resistente em cima do pulverizador, que garante muito mais resistência, durabilidade evitando arranhões e segurança no suporte do equipamento, evitando quebras inesperadas e otimizando nossa operação.', NULL, N'ANTES USAVAMOS UM GANCHO FRÁGIL PARA O DESCANÇO DO BRAÇO MECÂNICO QUE QUEBRAVA COM FREQUÊNCIA', N'DURABILIDADE DOS EQUIPAMENTOS', 0, NULL, NULL, '2026-07-17T00:00:00.000', '2026-07-18T13:59:23.000', N'81057520', NULL, NULL);
INSERT INTO #PVC VALUES (11243, N'81057520', N'81057520', N'PADRONIZAÇÃO E IDENTIFICAÇÃO DE POTES DE AMOSTRAGEM', 1, N'Others/Outros', N'Situação Inicial (Antes)
