INSERT INTO #PVC VALUES (11246, N'1008449', N'1008449', N'Copper secondary separator teflon replacement', 1, N'No Replication/Sem replicação', N'Secondary separators not going down far enough to strip the copper off', N'More effeciant copper stripping', N'0', N'01 - Imagens/01 - Antes/11246.jpeg', N'Copper at times become extremely sticky and hard to strip. Secondary separators are there to help but the Teflon pieces are not lowering enough to take the copper off the bottom', N'01 - Imagens/02 - Depois/11246.jpeg', N'New Teflon pieces made up and installed about 4" longer to be able to reach and strip the copper off', NULL, N'Yes problem solved', N'Troubleshooting with maintenance is key', 0, NULL, N'- Equipe impactada diariamente pela mensagem de segurança;
INSERT INTO #PVC VALUES (11247, N'81028405', N'81028405', N'Dimensionamento do Parque Reserva de PTO da Frota DR416i', 1, N'Others/Outros', N'Não existia um critério técnico definido para o dimensionamento do parque reserva de PTO da frota DR416i. As decisões relacionadas à quantidade de conjuntos reserva eram realizadas sem uma metodologia padronizada, gerando risco de indisponibilidade por falta de material ou investimento excessivo em ativos de baixa utilização.', N'Determinar o parque reserva ideal de PTO para a frota DR416i por meio de metodologia de engenharia e confiabilidade, garantindo o atendimento das demandas de manutenção com o menor risco de indisponibilidade operacional e otimização dos recursos investidos em estoque.', N'10015', N'01 - Imagens/01 - Antes/11247.jpeg', N'A frota DR416i não possuía um estudo técnico para definição do parque reserva de PTO. A quantidade de conjuntos disponíveis era baseada em percepção operacional e experiência prática, sem uma metodologia padronizada para avaliar a necessidade real da frota.
INSERT INTO #PVC VALUES (11248, N'1008360', N'1014251', N'Lime Feluwas Vale Form Update', 3, N'Others/Outros', N'During filling out the vale form the stormwater valve was said to always be connected to #1 but the hose connection often changes ', N'Update form to reflect changes ', N'0', N'01 - Imagens/01 - Antes/11248.jpeg', N'During filling out the vale form the stormwater valve was said to always be connected to #1 but the hose connection often changes from #1 to #2 . (NO BEFORE PIC)', N'01 - Imagens/02 - Depois/11248.jpeg', N'Valeform was updated to show an option for which Lime Feluwa the stormwater hose is connected too ', NULL, N'Yes', N'None', 0, NULL, N'Ability to refill cakewash 4 using flush/sample point', '2026-07-17T00:00:00.000', '2026-07-18T19:57:21.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11249, N'81049566', N'81017006', N'MANGOTE SEGURO', 2, N'Concentration/Concentração', N'Bomba de óleo com Mangote de recalque exposto, em caso de rompimento, risco de projetar em pessoas.', N'eliminar o risco de contato em caso de rompimento ', N'10362', N'01 - Imagens/01 - Antes/11249.jpeg', N'Mangote de Recalque da bomba de óleo Era exposto, com risco de SE em caso de rompimento projete óleo pressurizado em pessoas. ', N'01 - Imagens/02 - Depois/11249.jpeg', N'Fabricado capa de proteção para o corpo do mangote, removível com parafuso , protegendo o mangote de projeção em caso de rompimento, eliminando o risco de dano a pessoas. ', NULL, N'Foi instalado capa de proteção para o mangote, caso haja rompimento do mesmo nao ira atingir pessoas.', N'Segurança no caso de rompimento', 0, NULL, N'Conexões até 10 vezes mais rápidas com mais segurança, organização e ergonomia, o que evita a drenagem forçada de água da mina ficar inoperante  por mau contado das conexões e demoras', '2026-07-13T00:00:00.000', '2026-07-19T10:07:15.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11250, N'81049566', N'81012442', N'Suporte tubulaçao', 1, N'Others/Outros', N'Frequente queda da tubulação de agua dentro do predio da moagem , gerando vazamento de agua nos andares inferiores.', N'eliminar queda da tubulação .', N'10362', N'01 - Imagens/01 - Antes/11250.jpeg', N'Tubulação do esgoto no 4 andar do prédio da moagem sem sustentação , caindo, vazamento agua nos andares inferiores. ', N'01 - Imagens/02 - Depois/11250.jpeg', N'Fabricado e instalado suporte para sustentar tubulação e evitar vazamentos de esgoto no local.', NULL, N'Fixado tubulação de forma permanente, eliminando o risco de soltar. ', N'Suporte fixo. ', 0, NULL, N'Tempo de análise quando requisitados', '2026-07-14T00:00:00.000', '2026-07-19T10:18:27.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11251, N'81049566', N'502163', N'Janela de proteção', NULL, N'Concentration/Concentração', N'Chute de alimentação de bolas do sag, sem proteção na janela de visitar, permitindo a projeção de corpo moedores.', N'eliminar risco de projeção de corpo moedor', N'10362', N'01 - Imagens/01 - Antes/11251.jpeg', N'Alimentador de bolas do SAG sem proteção na janela de visita, projetando corpo moedores para aréa externa ', N'01 - Imagens/02 - Depois/11251.jpeg', N'Fabricado e instalado janela de proteção para o chute dosador de bolas, eliminando risco de projeção de corpo moedor. ', NULL, N'instalado janela de visita no chute dosador, eliminando o risco de projeção de corpo moedor durante operação. ', N'Protegido o risco de projeção ', 0, NULL, N'Agilidade no processo de análise', '2026-07-15T00:00:00.000', '2026-07-19T10:33:23.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11252, N'81049566', N'502163', N'Acesso Seguro TC5', 3, N'Crusher/Britadeira', N'Ausência de Escada para acessar o acionamento da 2301TC05 , desnível de 80cm para descer sem degrau de acesso. ', N'Fabricar escada para acesso seguro', N'10362', N'01 - Imagens/01 - Antes/11252.jpeg', N'Ausência de acesso Seguro para acessar o chute de descarga da correia 2301TC05.', N'01 - Imagens/02 - Depois/11252.jpeg', N'Fabricado escada com dois degraus para acesso ao desnível do chute de acionamento da 2301TC05.', NULL, N'Fabricado escada para acesso seguro ao chute da 2301TC05.', N'Mais seguro acesso local', 0, NULL, N'Garantir maior controle, rastreabilidade e padronização das solicitações de remoção de abelhas, pragas e vetores no Complexo Sossego, assegurando que todas as demandas sejam registradas, acompanhadas e concluídas de forma eficiente. Espera-se aumentar a conformidade com os requisitos de Saúde, Segurança e Meio Ambiente (SSMA), por meio da aprovação obrigatória para atividades críticas, além de melhorar a qualidade dos serviços prestados por meio do monitoramento dos atendimentos e da pesquisa de satisfação dos usuários. Como resultado, busca-se fortalecer a gestão operacional, reduzir falhas de processo e promover a melhoria contínua dos serviços.', '2026-07-09T00:00:00.000', '2026-07-19T11:09:40.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11253, N'81049566', N'502163', N'Linha de Agua ', 1, N'Crusher/Britadeira', N'Ausência de ponto de Agua para lavagem na caldeiraria do revezamento na Usina. ', N'Facilitar a limpeza da caldeiraria e peças', N'10362', N'01 - Imagens/01 - Antes/11253.jpeg', N'Ausência de ponto de agua para limpeza da Caldeiraria, lavar peças e outros no local. ', N'01 - Imagens/02 - Depois/11253.jpeg', N'Instalado tubulação e linha de agua para limpeza da caldeiraria e serviços. ', NULL, N'Instalado ponto fixo de agua na caldeiraria.', N'Maior facilidade para limpeza do local', 0, NULL, N'Maior autonomia dos usuários;
INSERT INTO #PVC VALUES (11254, N'81049566', N'502163', N'Aréa organizada', 3, N'Crusher/Britadeira', N'Ausência de barreira física na área próximo a caldeiraria da moagem . ', N'Instalar Barreira para isolar canaleta', N'10362', N'01 - Imagens/01 - Antes/11254.jpeg', N'Ausência de uma barreira para proteger canaleta, com riscos de quedas ao passar próximo .', N'01 - Imagens/02 - Depois/11254.jpeg', N'Instalado uma barreira próxima a área próximo a aréa da caldeiraria protegendo a canaleta e melhorando visualmente o ambiente.', NULL, N'Instalado barreira fisica próximo as canaletes e melhorado a condição visual da área. ', N'Melhor aspecto visual e seguraça', 0, NULL, N'at minimum we are expecting safety improvement', '2026-07-08T00:00:00.000', '2026-07-19T11:49:47.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11255, N'81004794', N'81004794', N'Waste Transportation Utilization ', 1, N'Others/Outros', N'Waste in production areas becoming expensive to transport in Waste Containers.  As well, waste container availability has been a problem', N'Reduce cost, maximize efficiency', N'0', N'01 - Imagens/01 - Antes/11255.jpeg', N'Process waste had accumulated in the EW area in significant quantities due to a lack of available waste containers. The waste consists of nickel debris packaged in large super sacks. Because this material is relatively lightweight, it does not utilize container capacity efficiently and would require up to six waste containers for this cleanup alone.', N'01 - Imagens/02 - Depois/11255.jpeg', N'We sourced a Semi Dump B-Train tractor trailer through our waste management contractor to support the cleanup. The two waste boxes on the unit can accommodate large volumes of material and hold up to 36 tonnes.
INSERT INTO #PVC VALUES (11256, N'550443', N'550443', N'ZERO DEFEITO', 1, N'Others/Outros', N'O desviador da peneira 01/01R apresentava falhas recorrentes devido à movimentação excessiva do mecanismo, ocasionando quebra do sensor e perda de leitura. Essas ocorrências provocavam paradas frequentes do equipamento, impactando diretamente a disponibilidade operacional e a produtividade da planta. Além disso, a substituição do sensor demandava em algumas atuações mais de três horas de intervenção, expondo a equipe a um ambiente com diversos obstáculos e aumentando os riscos durante a execução da atividade.', N'Evitar paradas desnecessárias', N'10245', N'01 - Imagens/01 - Antes/11256.jpeg', N'O desviador da peneira 01/01R apresentava falhas recorrentes devido à movimentação excessiva do mecanismo, ocasionando quebra do sensor e perda de leitura. Essas ocorrências provocavam paradas frequentes do equipamento, impactando diretamente a disponibilidade operacional e a produtividade da planta. Além disso, a substituição do sensor demandava em algumas atuações mais de três horas de intervenção, expondo a equipe a um ambiente com diversos obstáculos e aumentando os riscos durante a execução da atividade.', N'01 - Imagens/02 - Depois/11256.jpeg', N'Com o objetivo de eliminar essas ocorrências, foi desenvolvida e implantada uma melhoria consistindo na instalação de um guia para limitar a movimentação lateral do desviador, evitando o desalinhamento com consequente perda de leitura do sensor e quebra do sensor. Além disso, foi confeccionado um novo suporte para o acionamento do sensor, proporcionando maior estabilidade e confiabilidade ao equipamento.
INSERT INTO #PVC VALUES (11257, N'484637', N'81058959', N'Eliminação da quebra da placa limitadora (7Y1746) do tensor da esteira.', 1, N'Projects/Projetos', N'Durante a operação do equipamento, a placa limitadora de curso do ajustador do tensor da esteira (P/N 7Y1746) sofreu quebra e/ou deformação, perdendo sua função de limitar o movimento do conjunto. Em consequência, o ajustador do tensor passou a girar livremente em seu próprio eixo, atingindo até 360°, o que impossibilitou o correto posicionamento do ponto de aplicação da propulsora de graxa. Devido à falta de acesso para execução do procedimento de tensionamento da esteira, o sistema de ajuste ficou inoperante, comprometendo a manutenção da tensão adequada da esteira e exigindo a substituição do tensor.', N'Garantir a integridade e o correto funcionamento do sistema de tensionamento da esteira, por meio da substituição da placa limitadora de curso (P/N 7Y1746) e/ou do tensor, restabelecendo o controle angular do ajustador e permitindo o acesso adequado para aplicação de graxa, assegurando a manutenção da tensão correta da esteira e a confiabilidade operacional do equipamento.', N'10139', N'01 - Imagens/01 - Antes/11257.jpeg', N'Durante a operação do equipamento, a placa limitadora de curso (P/N 7Y1746) do ajustador do tensor da esteira apresentava quebra e/ou deformação, permitindo a rotação livre do ajustador em até 360°. Essa condição impossibilitava o acesso da propulsora de graxa para o tensionamento da esteira, comprometendo o funcionamento do sistema de ajuste, a manutenção da tensão adequada e ocasionando a necessidade de substituição do tensor.', N'01 - Imagens/02 - Depois/11257.jpeg', N'Após a implementação da melhoria, o sistema de ajuste do tensor da esteira passou a contar com um limitador de curso íntegro e funcional, impedindo a rotação excessiva do ajustador e mantendo seu correto posicionamento. Com isso, o ponto de aplicação da propulsora de graxa permaneceu acessível, permitindo a realização do tensionamento da esteira de forma segura e eficiente. A melhoria restabeleceu o controle angular do ajustador, eliminou a necessidade de substituições prematuras do tensor associadas à quebra da placa 7Y1746 e aumentou a confiabilidade e disponibilidade operacional do equipamento.', NULL, N'A meta inicial foi eliminar as falhas causadas pela quebra da placa limitadora de curso (7Y1746), garantindo o correto funcionamento do ajustador do tensor da esteira e a execução adequada do tensionamento. Após a implementação da melhoria, o ajustador passou a operar dentro do limite previsto, sem rotação excessiva, mantendo o ponto de aplicação da propulsora de graxa acessível para os ajustes necessários. Com isso, foi eliminada a condição que provocava a indisponibilidade do sistema de tensionamento, reduzindo a necessidade de substituição do tensor e aumentando a confiabilidade e a disponibilidade operacional do equipamento.', N'Inspeções preventivas e melhorias no sistema de travamento da placa limitadora (7Y1746) evitam falhas no tensionamento da esteira, reduzem paradas não programadas e aumentam a confiabilidade do conjunto tensor.', 75902, 1, N'depois da criação do nosso projeto na ultima reunião que teve CSP de 2025, r4eunião que antes demorava 2 dias para reavaliar todos os colaboradores da gerencia foi gasto somente 1 dia. ', '2026-07-18T00:00:00.000', '2026-07-19T17:11:07.000', N'484637', NULL, NULL);
INSERT INTO #PVC VALUES (11258, N'202615', N'202615', N'Alternate water source', 1, N'Refining/Refino', N'Building 211 has had numerous freeze-up issues with the process water entering the washbay  ', N'maintain water flow', N'0', N'01 - Imagens/01 - Antes/11258.jpeg', N'Building 211 has had numerous freeze-up issues with the process water entering the washbay. This delays and prevents regular cleaning maintenance of the mobile equipment, cleanup of the washbay floors and walls and the supply to the boot brush washer which leads to environmental concerns when exiting the building.', N'01 - Imagens/02 - Depois/11258.jpeg', N'An alternate source of potable water was identified on the underground right outside the building that had been connected but never commissioned since it was installed during construction. The curb stop was opened, and a bi-pass line was run to the existing hose reels providing an uninterrupted source should the process fail again.', NULL, N'Yes, the curb stop was opened, and a bi-pass line was run to the existing hose reels providing an uninterrupted source should the process fail again.', N'Interruptions to the water supply here leads to PM''s on mobile equipment not being completed and environmental risks  ', 199, 3, N'Change made to all Gas Sensors on Site.', '2026-07-12T00:00:00.000', '2026-07-19T22:40:37.000', N'202615', NULL, NULL);
INSERT INTO #PVC VALUES (11259, N'123307', N'533479', N'SINALIZAÇÃO SEMÁFORO PELA VIDA', 2, N'Others/Outros', N'A comunicação de segurança não estava visível em pontos estratégicos da usina e mina. Sem placas de alertas nos acessos, áreas operacionais e salas de troca de turno, os colaboradores não tinham um lembrete constante das atitudes seguras sobre segurança.', N'Reforçar a cultura de segurança e aumentar a percepção de risco dos colaborares  através da comunicação visual.', N'10054', N'01 - Imagens/01 - Antes/11259.jpeg', N'A comunicação de segurança não estava visível em pontos estratégicos da usina e mina. Sem placas de alertas nos acessos, áreas operacionais e salas de troca de turno, os colaboradores não tinham um lembrete constante das atitudes seguras sobre segurança.', N'01 - Imagens/02 - Depois/11259.jpeg', N'Foi realizada instalação de placas( 30 placas) com alerta de segurança com o tema: "Semáforo pela Vida"  em pontos de grande circulação da usina e na área de troca de turno dos colaboradores da mina, a ação contemplou portões de acesso, escadas, áreas operacionais e salas CCB.', NULL, N'Sim, o objetivo foi 100% alcançado. As placas foram instaladas em todas as área previstas. Agora o colaborador e impactado pela mensagem" PARE, ATENÇAO e SIGA"', N'Pequenas ações de comunicação visual geram grande impacto para cultura de segurança.', 0, NULL, N'This solution eliminated several hours of welding and reworking exhaust systems to perform diesel particulate testing.', '2026-07-03T00:00:00.000', '2026-07-20T00:01:02.000', N'123307', NULL, NULL);
INSERT INTO #PVC VALUES (11260, N'1009299', N'1009299', N'IR1 Floc Dilution pump labels', 1, N'Others/Outros', N'Pumps were not labeled making it difficult to identify ', N'Easy identification of pumps', N'0', N'01 - Imagens/01 - Antes/11260.jpeg', N'No labels on front of pumps', N'01 - Imagens/02 - Depois/11260.jpeg', N'Added labels to front of pumps for easy identification', NULL, N'Yes, pumps are now labeled', N'Labels are effective for easy identification', 0, NULL, N'Redução no backlog de demandas vencidas', '2026-07-07T00:00:00.000', '2026-07-20T00:50:43.000', N'1009299', NULL, NULL);
INSERT INTO #PVC VALUES (11261, N'1009299', N'1009299', N'Cakewash 4 Flush/Sample point ', 1, N'Others/Outros', N'Cakewash 4 had no flush/sample point', N'Add flush point to refill tank', N'0', N'01 - Imagens/01 - Antes/11261.jpeg', N'No flush/sample point on cakewash 4 ', N'01 - Imagens/02 - Depois/11261.jpeg', N'Added flush/sample point to suction drain for refilling of tank', NULL, N'Yes, flush/sample point was added', N'Added flush/sample point', 0, NULL, N'Having this setup will make it easier to collect floc samples rather than looking for a marker or label maker. it also makes it easier to see what is left in the tray rather than in a box.', '2026-07-08T00:00:00.000', '2026-07-20T00:57:36.000', N'1009299', NULL, NULL);
INSERT INTO #PVC VALUES (11262, N'81055392', N'505896', N'Conecta +', 1, N'Projects/Projetos', N'Atividade de conectar e desconectar os cabos dos instrumentos de medição de temperatura e nível  de agua das bombas que drenam a água  no fundo das cavas (SUMP)  Geralmente são 4 destes equipamentos,  o que seriam 60 conexões  de cabos de 0,5mm² para realizar, o tempo de execução para esta manobra é cerca de 40 minutos para alguém experiente, pois a cada retorno de desmonte, é necessário prensar os terminais tubulares de 0,5mm² para conectar nos 60 bornes, outro problema é o desconforto físico devido a falta da ergonomia durante a execução, ainda causando paradas inesperadas no bombeamento devido a falha nas conexões ', N'Conectar e desconectar cabos de instrumentos com extrema velocidade ', N'10242', N'01 - Imagens/01 - Antes/11262.jpeg', N'Atividade de conectar e desconectar os cabos dos instrumentos de medição de temperatura e nível  de agua das bombas que drenam a água  no fundo das cavas (SUMP) é bastante rotineira, 3 cabos para PT100 e 3 cabos para Nível de 0,5mm², cada bomba possui Três PT100 e Dois de nível, totalizando 15 cabos para conectar, geralmente são 4 destes equipamentos,  o que seriam 60 conexões para realizar, o tempo de execução para esta manobra é cerca de 40 minutos para alguém experiente, pois a cada retorno de desmonte, é necessário prensar os terminais tubulares de 0,5mm² para conectar nos 60 bornes, outro problema é o desconforto físico devido a falta da ergonomia durante a execução  ', N'01 - Imagens/02 - Depois/11262.jpeg', N'A conexão e desconexão dos sensores, não impactam mais no retorno do bombeamento  e também na ergonomia do executante , com a utilização do conector Wago que na sua especificação suporta cabos de 0,4 a 4mm², 32 Amperes e 40KG de tração sem romper. Pois são realizadas sem a necessidade de prensar terminais nos 60 cabos  de 0,5mm²  e com apenas um click mecânico já conecta ou desconecta o cabo, evitando também o desgaste dos bornes ', N'https://www.wago.com/br/conexao/conectores-de-emenda/linha221/221inline', N'Resolvido, tempo de conexão era realizado entre 30 hà 50 minutos, com os conectores in-line isso é realizado entre 3 a 7 minutos ', N'Projetar pensando na manutenção aumenta a segurança, reduz o tempo de parada e melhora a confiabilidade do sistema', 0, NULL, NULL, '2026-06-22T00:00:00.000', '2026-07-20T01:18:50.000', N'81055392', NULL, NULL);
INSERT INTO #PVC VALUES (11263, N'532872', N'532872', N'Dashboard de Cobertura da Programação', 1, N'Others/Outros', N'Inexistência de monitoramento detalhado', N'Realizar monitoramento do % programamdo da capacidade dos centros de trabalho', N'10179', N'01 - Imagens/01 - Antes/11263.jpeg', N'Não existia um dashboard dedicado ao monitoramento da cobertura da capacidade programada, dificultando o acompanhamento e a análise dos resultados.', N'01 - Imagens/02 - Depois/11263.jpeg', N'Foi desenvolvido e disponibilizado um dashboard corporativo de Cobertura da Programação, permitindo o monitoramento contínuo da capacidade planejada de manutenção por meio de indicadores visuais e interativos.
INSERT INTO #PVC VALUES (11264, N'532872', N'532872', N'Dashboard de Trabalho Reativo', NULL, N'Others/Outros', N'Inexistência de Dashboard para monitoramento do indicador', N'Desenvolver dashboard para monitoramento do indicador', N'10081', N'01 - Imagens/01 - Antes/11264.jpeg', N'Não existia um dashboard específico para monitoramento do Percentual de Trabalho Reativo, o que dificultava a visibilidade dos indicadores de manutenção corretiva, a identificação das principais causas dos desvios e o acompanhamento do desempenho por área, gerência e equipe. As análises eram realizadas de forma descentralizada, demandando maior esforço na consolidação das informações e reduzindo a agilidade na tomada de decisão.', N'01 - Imagens/02 - Depois/11264.jpeg', N'Dashboard de Trabalho Reativo implantado para monitorar indicadores de manutenção não planejada, com análises por área, equipe e ativo, Pareto de desvios e apoio à tomada de decisão.', N'https://app.powerbi.com/groups/me/apps/2f1cf443-5ea8-45a4-9860-b084ee3f2a39/reports/99315b71-44b1-4677-ae95-943eeb1be34c/82bc44eee62a58d704d2?experience=power-bi', N'sim, indicador monitorado e em implementação na rotina.', N'Monitorar para gerenciar', 0, NULL, N'This will be a temporary fix untill the pipe can repaired with proper materials ', '2026-07-17T00:00:00.000', '2026-07-20T09:15:21.000', N'532872', NULL, NULL);
INSERT INTO #PVC VALUES (11265, N'504475', N'871194', N'APLICATIVO - Gestão de Solicitações de Remoção de Abelhas e Controle de Pragas e Vetores com Fluxo de Aprovação SSMA no Complexo Sossego', 1, N'Others/Outros', N'Qual é o problema?
INSERT INTO #PVC VALUES (11266, N'92000100', N'92000100', N'Aplicativo de salas', 1, N'Others/Outros', N'Desperdício de tempo. Trabalho manual repetitivo.', N'Otimizar agendamento de salas', N'10234', N'01 - Imagens/01 - Antes/11266.jpeg', N'Antes, para realizar o agendamento de salas, o solicitante precisava entrar em contato com o administrador responsável para verificar a disponibilidade na agenda do Outlook. Todo o processo de reserva dependia dessa consulta, pois somente o administrador possuía acesso à visualização da disponibilidade das salas. Como consequência, havia impacto na rotina de trabalho, já que o administrador precisava interromper suas atividades frequentemente para atender às solicitações e consultar a agenda antes de efetivar os agendamentos.', N'01 - Imagens/02 - Depois/11266.jpeg', N'Foi replicado o aplicativo de agendamento de salas já utilizado no Prédio Jequitibá, proporcionando mais autonomia e agilidade aos usuários.
INSERT INTO #PVC VALUES (11267, N'81013125', N'81013125', N'Contractor Performance', 1, N'Others/Outros', N'Contractor performance has been an issue in the past in multiple areas of the vendor''s accountability. During contract renewal process, we moved to a performance management system for the service.', N'Increase contractor performance', N'10026', N'01 - Imagens/01 - Antes/11267.jpeg', N'Previously there was not a lot of "teeth" in the contract that allowed Vale to set targets that had commercial impact on the contractor. ', N'01 - Imagens/02 - Depois/11267.jpeg', N'We have written into the scope a sliding scale for performance that will commercially impact the vendor based on underperformance and outperformance', NULL, N'We have currently written performance management into the Scope of Work, final results to be followed up', N'We need to bring back performance management', 0, NULL, N'flash vessel overflow line reinstatement to the original configuration, allows just one Autoclave, as opposed to two, come down for the necessary flash vessel overflow line cleanings when required   ', '2026-07-15T00:00:00.000', '2026-07-20T10:09:08.000', N'81013125', NULL, NULL);
INSERT INTO #PVC VALUES (11268, N'81040247', N'81040247', N'Fluxograma de Exceção – Montagem de Andaimes Provisórios ', 2, N'Others/Outros', N'Anteriormente, não havia um controle efetivo sobre a quantidade de barreiras físicas montadas no site Salobo. Como consequência, recursos de andaime eram frequentemente desviados de sua finalidade original e utilizados como solução provisória, sem tratar a causa raiz dos problemas, o que contribuía para a recorrência das ocorrências.', N'Redução de Custo ', N'10178', N'01 - Imagens/01 - Antes/11268.jpeg', N'Anteriormente, não havia um controle efetivo sobre a quantidade de barreiras físicas montadas no site Salobo. Como consequência, recursos de andaime eram frequentemente desviados de sua finalidade original e utilizados como solução provisória, sem tratar a causa raiz dos problemas, o que contribuía para a recorrência das ocorrências.', N'01 - Imagens/02 - Depois/11268.jpeg', N'Foi implementada uma nova diretriz para o controle de solicitações de barreiras físicas provisórias com andaime. A partir de agora, toda instalação deverá ser previamente aprovada por Gilberto Benigno, mediante envio de solicitação formal contendo justificativa técnica, evidência fotográfica, centro de custo (CC) e prazo para implementação da solução definitiva.
INSERT INTO #PVC VALUES (11269, N'473024', N'473024', N'MACRO INSERIR VPTS, ATR E PRO EM LISTA TAREFA DE PLANOS', 1, N'Others/Outros', N'Foi identificado que os planos de manutenção preventiva da usina estão configurados sem a associação obrigatória dos documentos de suporte (VPTS, ART e PRO). Essa condição resulta em ineficiência operacional e aumento do esforço administrativo das equipes de Planejamento e Programação, devido à necessidade de inclusão manual desses documentos em todos os ciclos de programação das ordens de manutenção, elevando o risco de inconsistências e impactando a produtividade do processo.', N'95% DOS PLANOS DA MOAGEMCOM VPTS, ART E PRO', N'10178', N'01 - Imagens/01 - Antes/11269.jpeg', N'Foi identificado que os planos de manutenção preventiva da usina estão configurados sem a associação obrigatória dos documentos de suporte (VPTS, ART e PRO). Essa condição resulta em ineficiência operacional e aumento do esforço administrativo das equipes de Planejamento e Programação, devido à necessidade de inclusão manual desses documentos em todos os ciclos de programação das ordens de manutenção, elevando o risco de inconsistências e impactando a produtividade do processo.', N'01 - Imagens/02 - Depois/11269.jpeg', N'Foi desenvolvida uma Macro em Excel integrada a um SAP Script para automatizar a inclusão de VPTs, ARTs e PROs nas listas de tarefas dos planos preventivos por meio da transação ZOVOPM051. A solução eliminou atividades repetitivas e aumentou significativamente a produtividade, permitindo a inserção de até 100 VPTs, ARTs e PROs em aproximadamente 6 segundos, após o preenchimento das informações pelo usuário.', NULL, N'O problema identificado no processo foi corrigido com total exatidão por meio da solução desenvolvida, eliminando inconsistências e garantindo a execução confiável das atividades. Os resultados alcançados atenderam integralmente aos objetivos definidos, atingindo 100% da meta estabelecida no projeto inicial e proporcionando maior eficiência operacional, padronização e redução de erros.', N'A automação é uma ferramenta poderosa para aumentar a produtividade, reduzir erros e otimizar processos operacionais.', 0, NULL, N'A implementação da solução resultou em maior controle, padronização e confiabilidade das informações relacionadas ao Head Count de Terceiros do Complexo Sossego. Com a automatização do processo, a centralização do recebimento dos dados, a utilização de formulários padronizados e as validações automáticas realizadas pelo Power BI, foi possível reduzir inconsistências, eliminar retrabalho e aumentar a eficiência operacional.
INSERT INTO #PVC VALUES (11270, N'81034557', N'81034557', N'Score de Operadores ', 1, N'Concentration/Concentração', N'A supervisão operacional possuía informações de desempenho dos operadores dispersas em diversas bases e controles, dificultando:
INSERT INTO #PVC VALUES (11271, N'1008535', N'1008535', N'Cl2 & H2S Gas Sensors Reading Negative Values', 2, N'Underground/Subterrâneo', N'During an OH&S visit is was noted that a Chlorine Gas Detector in EW Bay was reading -.28ppm but DCS was showing 0 PPM.  When detectors drift into  the negative region or an improper zero is performed then the negative reading will not be displayed and  Ops will not be aware of required maintenance and risk of lower then actual gas readings.', N'Read Negative Values  to Warn Operations Maintenance is Required', N'0', N'01 - Imagens/01 - Antes/11271.jpeg', N'DCS reading 0 when Gas Sensor in field drifted to a Negative Value.', N'01 - Imagens/02 - Depois/11271.jpeg', N'DCS now  reads negative values.  Alarm added to notify Control Room Operator when reading goes below -.3ppm.  Maintenance can be advised sooner to perform calibration.  Less Risk of reading lower then actual concentrations of Gas.', NULL, N'Previously Negative Readings would not be seen until regularly scheduled maintenance.  With this change maintenance can be performed sooner when needed and gives visibility to the Control Room Operator.', N'Negative Gas Reading & Alarm is Beneficial to Operations.', 0, NULL, N'Aumento da vida útil do ciclone, redução das perdas de material, menor frequência de intervenções de manutenção, maior disponibilidade do equipamento e melhoria da segurança operacional e da produtividade.', '2026-07-19T00:00:00.000', '2026-07-20T17:01:55.000', N'1008535', NULL, NULL);
INSERT INTO #PVC VALUES (11272, N'607251', N'608824', N'DPM sample probe', 1, N'Underground/Subterrâneo', N'New diesel particulate matter tester probes where too large to fit into the test port on the exhaust system. This would have required a rework of all the exhaust ports on 100 pieces of equipment.', N'Eliminate extra work', N'10066', N'01 - Imagens/01 - Antes/11272.jpeg', N'Test probe supplied with the equipment was not compatible with the port sizes on the exhaust. ', N'01 - Imagens/02 - Depois/11272.jpeg', N'Reached out to the supplier of the equipment to see if any other options were available, the supplier did not offer anything. The mobile team was able to get new probes built by a local business, after the probes were received our onsite welder closed off one end and drilled holes in the pipe to match the original probe. Emails and pictures were sent to the manufacture for approvals.  ', NULL, N'Yes, the Totten mobile team was able to come up with simple and cost-effective solution.', N'Look outside the box for solutions', 0, NULL, N'Redução do tempo gasto na consolidação e análise das informações de materiais.
INSERT INTO #PVC VALUES (11273, N'81046574', N'81046574', N'Estratégia de Paradas Preventivas – GP|26', 1, N'Others/Outros', N'Em virtude da GP26 tornou-se fundamental definir a estratégia de paradas conforme priorização clara e estratégica do Backlog para atuação durante as paradas do caminho singelo e das linhas da usina durante esse períod.', N'Definir estratégia de Paradas de Manutenção durante a P|26', N'10081', N'01 - Imagens/01 - Antes/11273.jpeg', N'Não havia estratégia definida', N'01 - Imagens/02 - Depois/11273.jpeg', N'Durante a GP|26, haverá 110 dias de parada do moinho SAG, com uso de by-pass (980 t/h) para sustentar a produção. Nesse período, parte da planta operará enquanto outra estará disponível para intervenções.
INSERT INTO #PVC VALUES (11274, N'81036746', N'81036746', N'Flocculant sample tube storage', 1, N'No Replication/Sem replicação', N'Falcon tube storage has become unorganized in storage cabinet near the floc skid. Labelling the tubes is inconvenient as pen ink does not show up on the plastic.', N'Better organization and availability of sample tubes in floc area', N'10045', N'01 - Imagens/01 - Antes/11274.jpeg', N'No organized storage in area designated for falcon tubes. If tubes are available, they aren''t pre-labeled. ', N'01 - Imagens/02 - Depois/11274.jpeg', N'Tray labelled and filled with ready to use falcon tubes to use for Neut, ETP and IR2 floc sample taking.', NULL, N'Yes, the problem was solved, falcon tubes are now easily accessible and pre-labelled. ', N'Organization helps make tasks easier and less time consuming.', 0, NULL, N'MELHOROU A PRODUTIVIDADE APÓS A IMPLEMENTAÇÃO DO 5S NO KANBAN ELÉTRICA.', '2026-07-19T00:00:00.000', '2026-07-20T21:47:42.000', N'81036746', NULL, NULL);
INSERT INTO #PVC VALUES (11275, N'1008449', N'1008449', N'East crane Hydraulics YEM', 1, N'Refining/Refino', N'New hydraulic lines put on crane 002 during day shift. Came in on nights and they leaked and two hoses were put on but needed to be swapped as it was causing hooks to open when you would close and close when you would open', N'Ops completed this rather than tying up maintenance resources', N'0', N'01 - Imagens/01 - Antes/11275.jpeg', N'New hydraulic lines put on crane 002 during day shift. Came in on nights and they leaked and two hoses were put on but needed to be swapped as it was causing hooks to open when you would close and close when you would open. To fix we would have to get maintenance, tying up resources when there were other urgent work ongoing at the time', N'01 - Imagens/02 - Depois/11275.jpeg', N'Ops completed this work while being walked through it with maintenance that completed the job on days. We were able to tighten the fittings and switch around a hose to get the crane up and running. Preventing maintenance to have to deal with it while other work needed to be done.', NULL, N'yes, avoided hitting power down triggers and didn''t have to tie up maintenance resources', N'Test equipment when things get changed', 500, 3, N'Melhoria da segurança com o 5s em dias.', '2026-07-19T00:00:00.000', '2026-07-20T23:21:51.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (11276, N'1008449', N'1008449', N'4" pipe clamp on hot water line', 2, N'Refining/Refino', N'Utility hot water sprung a leak in the tankhouse', N'Stop water leak', N'0', N'01 - Imagens/01 - Antes/11276.jpeg', N'Hot water line started leaking spraying onto the tankhouse and in the walkway next to system 400', N'01 - Imagens/02 - Depois/11276.jpeg', N'Pipe clamp used to stop the leak and keep hot water on so we can use for harvesting. This prevented us from waiting to cut and weld new pipe', NULL, N'Yes water leak stopped via pipe clamp', N'Caution to carbon steel piping in the tankhouse', 0, NULL, N'Redução de impacto recurso hídrico e estabilidade do processo.', '2026-07-10T00:00:00.000', '2026-07-21T02:46:55.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (11277, N'1008390', N'1008390', N'Caustic Leak Funnel Setup ', 2, N'Others/Outros', N'Caustic was leaking out of a pipe outside in the piperack and landing on the pavement ', N'To prevent Caustic from Landing on the ground ', N'0', N'01 - Imagens/01 - Antes/11277.jpeg', N'Caustic was leaking in pipe rack outside and onto to the pavement below into a walkway ', N'01 - Imagens/02 - Depois/11277.jpeg', N'We used a JLG to gain access to leak and attached a funnel with rope to the pipe and ran a hose down into a tote. this will make sure that if there is a leak it will fall into the funnel and end up in the tote and not on the walkway.', NULL, N'Yes it will prevent Caustic from falling into the walkway ', N'Ensure right Material is used when Bonding FRP', 0, NULL, N'GARANTIA OPERACIONAL DO EQUIPAMENTO DANIFICADO SUBSTITUÍDO DENTRO DO PRAZO ANTES QUE VOLTAR A RODAR. ECONOMIZAMOS MILHARES DE REAIS.', '2026-07-19T00:00:00.000', '2026-07-21T02:53:35.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11278, N'1008390', N'1008390', N'Fixing Seal Water Solenoid to Recirc Pump ', 1, N'Refining/Refino', N'Tried to start Recirc pump and it failed on no seal water going to pump ', N'To Repair Seal water  Solenoid to Recirc Pump ', N'0', N'01 - Imagens/01 - Antes/11278.jpeg', N'Tried to start Recirc Pump and it failed on no seal water to pump so could not get pump started ', N'01 - Imagens/02 - Depois/11278.jpeg', N'Locked out seal water and took apart the solenoid and cleaned it up and freed up the parts that were dirty and sticking preventing the solenoid from opening and allowing seal water to flow through ', NULL, N'Yes Problem was solved, seal water was restored to the pump and pump was started ', N'Troubleshooting can come up with a simple solution ', 500, 3, NULL, '2026-07-10T00:00:00.000', '2026-07-21T03:09:43.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11279, N'1008449', N'1008449', N'Shift 1 Cl2 badge storage location', 3, N'Refining/Refino', N'Nowhere to store rental badges for shift 1', N'Create storage location', N'0', N'01 - Imagens/01 - Antes/11279.jpeg', N'Shift 1 EW were given 4 Cl2 gas badges and nowhere to safely store these to prevent mixing them up', N'01 - Imagens/02 - Depois/11279.jpeg', N'4 Badges were labels "shift 1" and storage home created in the coaches locker so they are available each shift', NULL, N'yes. Badges are in the correct location each set and aren''t misplaced', N'Creating a home for tools and devices prevent them from getting lost', 0, NULL, N'Maintaining integrity and Improving Workability', '2026-06-01T00:00:00.000', '2026-07-21T03:29:32.000', N'1008449', NULL, NULL);
INSERT INTO #PVC VALUES (11280, N'81061897', N'81061897', N'Titanium Blind repurposing ', 1, N'Projects/Projetos', N'Reinstating Flash Vessel overflow lines to original configuration would require (2) 16 inch blinds after spool removal that were high cost and long lead times', N'cost savings ', N'0', N'01 - Imagens/01 - Antes/11280.jpeg', N'Titanium blinds required for reinstatement of the original flash vessel overflow line configuration had a long lead time and high cost', N'01 - Imagens/02 - Depois/11280.jpeg', N'We reused titanium blinds from a separate upgrade project on the line that would have been otherwise obsolete. This allowed us to complete the flash vessel overflow line reinstatement to the original configuration and allow just one Autoclave, as opposed to two, come down for the necessary flash vessel overflow line cleanings when required   ', NULL, N'Yes', N'cost savings', 25000, 3, N'It led to the prevention of electric shock accidents.', '2026-06-01T00:00:00.000', '2026-07-21T08:39:28.000', N'81061897', NULL, NULL);
INSERT INTO #PVC VALUES (11281, N'81013125', N'81009117', N'VB rental tracker', 1, N'Others/Outros', N'a number of years ago Shawn Hunt asked for a list of rental equipment on VB site. With multiple requisitioners, each area was siloed which made it difficult to put a single list together', N'Have one unified list of rental equipment on VB site', N'10026', N'01 - Imagens/01 - Antes/11281.jpeg', N'-Conflicting lists living on individual''s hard drives
INSERT INTO #PVC VALUES (11282, N'504475', N'871194', N'Automação - Head Count Terceiros Complexo Sossego', 1, N'Others/Outros', N'Atualmente, o controle do Head Count de Terceiros do Complexo Sossego é realizado por meio de processos manuais e consolidações em diferentes fontes de dados, demandando elevado esforço operacional e aumentando o risco de inconsistências, retrabalho e atrasos na disponibilização das informações. A falta de automação dificulta o acompanhamento em tempo real da força de trabalho terceirizada, impactando a eficiência da gestão, o monitoramento de contratos e a tomada de decisões estratégicas. Dessa forma, torna-se necessária a implementação de uma solução automatizada que proporcione maior confiabilidade, agilidade e padronização no gerenciamento dessas informações.', N'Automatizar o processo de controle e consolidação do Head Count de Terceiros do Complexo Sossego, garantindo maior agilidade, confiabilidade e rastreabilidade das informações, reduzindo atividades manuais, minimizando erros operacionais e proporcionando uma visão atualizada para apoio à gestão e à tomada de decisão.', N'10361', N'01 - Imagens/01 - Antes/11282.jpeg', N'O processo de controle do Head Count de Terceiros do Complexo Sossego era realizado de forma manual, por meio de planilhas e informações enviadas por diferentes áreas. Essa dinâmica resultava em registros incompletos, dados informados incorretamente, duplicidades e divergências entre as bases de informação. Além disso, a consolidação dos dados demandava grande esforço operacional, elevado tempo de processamento e constantes validações manuais.
INSERT INTO #PVC VALUES (11283, N'1008564', N'1008449', N'Post QR Code for Employee Recognition Form', 1, N'No Replication/Sem replicação', N'There was no form posted in the Technician''s Room to access the QR Code for Employee Recognition Form', N'Employee Recognition Form QR Code would be more accessible to the Technicians', N'0', N'01 - Imagens/01 - Antes/11283.jpeg', N'No QR Code for Employee Recognition Form', N'01 - Imagens/02 - Depois/11283.jpeg', N'QR Code for Employee Recognition Form', NULL, N'yes', N'Locate QR Code ', 0, NULL, N'The extension cords have addressed the tripping hazard in the lunchroom.', '2026-07-20T00:00:00.000', '2026-07-21T12:25:57.000', N'1008564', NULL, NULL);
INSERT INTO #PVC VALUES (11284, N'81058966', N'472918', N'Substituição do Ciclone CI-2017-02 por modelo com revestimento cerâmico.', 1, N'Others/Outros', N'Durante uma manutenção foi identificado que o ciclone antigo, com revestimento de borracha, apresentava desgaste excessivo devido à abrasão do material transportado. Esse desgaste ocasionava vazamentos de material, aumentando a necessidade de manutenções corretivas, elevando os custos e expondo os colaboradores a riscos durante as intervenções.', N'Substituir o ciclone por um modelo com revestimento cerâmico, aumentando sua vida útil.', N'10031', N'01 - Imagens/01 - Antes/11284.jpeg', N'O ciclone antigo possuía revestimento de borracha, que sofria desgaste prematuro, causando vazamento de material e frequentes paradas para manutenção.', N'01 - Imagens/02 - Depois/11284.jpeg', N' Foi instalado um novo ciclone CI-2017-02 com revestimento de cerâmica, material com maior resistência à abrasão.', NULL, N'SIM. A substituição do ciclone de borracha por um ciclone com revestimento cerâmico eliminou os vazamentos de material causados pelo desgaste prematuro, aumentou a resistência do equipamento, reduziu a necessidade de manutenções corretivas e proporcionou maior segurança e confiabilidade ao processo.', N' componentes mais resistentes aumenta a confiabilidade do equipamento, reduz custos com manutenção', 0, NULL, NULL, '2026-07-15T00:00:00.000', '2026-07-21T14:15:00.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11285, N'81034734', N'520046', N'Dashboard Integrado de Gestão de Materiais por Criticidade e Data de Necessidade', NULL, N'Others/Outros', N'O controle dos materiais da parada era realizado por meio de planilhas e informações descentralizadas, dificultando a visualização dos riscos relacionados aos prazos de entrega e às datas de necessidade para aplicação. Essa limitação reduzia a capacidade de antecipação das ações de mitigação, aumentando o risco de indisponibilidade de materiais críticos e impactos no cronograma da parada.
INSERT INTO #PVC VALUES (11286, N'522369', N'522369', N'5S KANBAN ELÉTRICA', 3, N'No Replication/Sem replicação', N'FOI CONSTATADO NA ROTINA QUE TEM MUITO ACUMULO DE MATERIAL RECEBIDO DO ARMAZÉM PARA ABASTECIMENTO DO KANBAN ELÉTRICA.', N'MELHORAR PROCESSO DE MATERIAIS ORGANIZADO NA PRATELEIRA QUE FICA DISPONÍVEL CONFORME PADRÃO DE CINCO SENSOS DE 5S', N'10031', N'01 - Imagens/01 - Antes/11286.jpeg', N'DESORGANIZAÇÃO NO KANBAN ELÉTRICA COM RECEBIMENTO DE MATERIAL PARA ABASTECER O LOCAL QUE ESTÁ FORA DO PADRÃO DE 5S.', N'01 - Imagens/02 - Depois/11286.jpeg', N'FOI REALIZADO APLICAÇÃO DE TODOS OS SENSOS DE 5S NO KANBAN ELÉTRICA PARA ARMAZENAR MATERIAIS NA PRATELEIRAS E DESCARTAR CORRETAMENTE O RESÍDUO GERADO NA ATIVIDADE DE PADRONIZAÇÃO.', NULL, N'MELHORAR E PADRONIZAR SEMPRE O ABASTECIMENTO DE MATERIAIS PARA CICLO DE MANUTENÇÃO ELÉTRICA, ONDE TEMOS GANHOS NA PRODUTIVIDADE.', N'FOI FEITO TODOS OS SENSOS DE 5S NA ORGANIZAÇÃO DO KANBAN ELÉTRICA', 0, NULL, N'Redução de tempo nas atividades de abertura das praças de sondagrm', '2026-07-20T00:00:00.000', '2026-07-21T15:04:10.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11287, N'522369', N'522369', N'KANBAN ELÉTRICA 5S', 3, N'No Replication/Sem replicação', N'DIFICULDADE NO PRIMEIRO CICLO DE ABASTECIMENTO DE MATERIAIS RECEBIDO DO ARMAZÉM PARA KANBAN ELÉTRICA, ONDE ACUMULA MUITAS CAIXAS QUEBRANDO O CICLO DE 5S.', N'MELHORAR PROCESSO DE MATERIAIS ORGANIZADO NAS PRATELEIRAS QUE FICA DISPONÍVEL CONFORME PADRÃO DE CINCO SENSOS DE 5S', N'10178', N'01 - Imagens/01 - Antes/11287.jpeg', N'DESORGANIZAÇÃO NO KANBAN ELÉTRICA COM RECEBIMENTO DE MATERIAL PARA ABASTECER O LOCAL QUE ESTÁ FORA DO PADRÃO DE 5S.', N'01 - Imagens/02 - Depois/11287.jpeg', N'FOI REALIZADO APLICAÇÃO DE TODOS OS SENSOS DE 5S NO KANBAN ELÉTRICA PARA ARMAZENAR MATERIAIS NA PRATELEIRAS E DESCARTAR CORRETAMENTE O RESÍDUO GERADO NA ATIVIDADE DE PADRONIZAÇÃO.', NULL, N'MELHORAR E PADRONIZAR SEMPRE O ABASTECIMENTO DE MATERIAIS PARA CICLO DE MANUTENÇÃO ELÉTRICA, ONDE TEMOS GANHOS NA PRODUTIVIDADE.', N'FOI FEITO TODOS OS SENSOS DE 5S NA ORGANIZAÇÃO DO KANBAN ELÉTRICA.', 0, NULL, N'Essa sinalização reforça a segurança operacional, restringe intervenções indevidas, aumenta a percepção de risco e padroniza o procedimento de acesso e intervenção no equipamento.', '2026-07-20T00:00:00.000', '2026-07-21T15:35:43.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11288, N'515962', N'81061537', N'melhoria do amostrador cleaners', 1, N'No Replication/Sem replicação', N'Condições ergonômicas ao coletar a amostra ruim  e condições de 5s anormal.', N'melhorar a condição da amostragem e ergonômia ', N'10054', N'01 - Imagens/01 - Antes/11288.jpeg', N'O ponto de coleta de amostra possuía um registro de PVC para controle de abertura e fechamento. Devido à exposição contínua aos intempéries (radiação solar, chuva e variações de temperatura), o componente apresentava fragilidade mecânica, aumentando o risco de quebra durante a operação. Essa condição gerava insegurança para os operadores, maior necessidade de manutenção e possibilidade de indisponibilidade do ponto de amostragem.', N'01 - Imagens/02 - Depois/11288.jpeg', N'Foi realizada a substituição do registro de PVC por uma válvula de aço, material mais resistente às condições ambientais e aos esforços mecânicos aplicados durante a operação. A nova válvula proporciona maior robustez, confiabilidade e vida útil ao sistema de coleta de amostras. Além disso foi instalado mangueira com descarga para a pia, melhoria da ergonomia e 5s do local. ', NULL, N'Sim!', N'Uma boa ergonomia faz toda a diferença no nosso dia a dia.', 0, NULL, N'o numero de ordens de embarcados vencidos da carteira foi sanado', '2026-07-13T00:00:00.000', '2026-07-21T16:52:05.000', N'515962', NULL, NULL);
INSERT INTO #PVC VALUES (11289, N'488890', N'488890', N'Marca  que vai', 1, N'No Replication/Sem replicação', N'Durante a operação do circuito em BY PASS, com o material sendo desviado para a 2301 TC 08, foi identificado que a lógica de controle do sistema continua considerando que 100% da massa alimentada está sendo direcionada ao moinho SAG para o cálculo do percentual de sólidos.', N'Eliminar falha no cálculo do % sólido alimentação do moinho SAG. ', N'10054', N'01 - Imagens/01 - Antes/11289.jpeg', N'Durante a operação em BY-PASS, com desvio de material para a 2301-TC-08, a lógica de controle continua considerando que 100% da massa alimentada segue para o moinho SAG no cálculo do percentual de sólidos. Como resultado, ocorre superestimação da vazão de água, gerando adição excessiva de água ao moinho e aumentando o risco de instabilidade operacional e elevação do nível de descarga.', N'01 - Imagens/02 - Depois/11289.jpeg', N'Foi implementada uma melhoria na lógica de controle do sistema, permitindo identificar automaticamente quando o circuito está operando em BY PASS para a 2301 TC 08 ou alimentando o moinho SAG. Com essa adequação, o cálculo do percentual de sólidos passou a considerar apenas a massa efetivamente direcionada ao moinho, garantindo maior precisão na adição de água, reduzindo riscos operacionais e aumentando a confiabilidade do processo.', NULL, N'A lógica de controle não diferenciava a condição operacional do circuito, comprometendo o cálculo do percentual de sólidos. A meta foi garantir que o cálculo considerasse apenas a massa alimentada ao moinho SAG, aumentando a precisão e a confiabilidade do processo.', N'Confiabilidade no processo faz a diferencia. ', 0, NULL, N'Identificação, mitigação ou neutralização de perigos. Esses benefícios impactam diretamente a produtividade, a cultura organizacional e os custos', '2026-07-15T00:00:00.000', '2026-07-21T17:08:47.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11290, N'522369', N'522369', N'ENTREGA DELIVERY PGU JULHO 2026 MOAGEM SLB III', 2, N'No Replication/Sem replicação', N'INTERVALOS MUITOS LONGOS NA ESPERA DO CICLO DE SEPARAÇÃO DE MATERIAIS. JUNTO COM A ÁREA DEPEDENTE DO RECURSO PARA LIBERAR O EQUIPAMENTO.', N'AGILIDADE NO PROCESSO DE SEPARAÇÃO DE MATERIAIS NO ARMAZÉM PARA DESTINO FINAL À MANUTENÇÃO ELÉTRICA', N'10178', N'01 - Imagens/01 - Antes/11290.jpeg', N'SEPARAR MATERIAIS SÃO MUITOS BUROCRÁTICOS, NA QUAL PERDEMOS MUITO TEMPO AGUARDANDO O CICLO DE SEPARAÇÃO ONDE PERDEMOS EM PRODUTIVIDADE DO PROCESSO INDUSTRIAL.', N'01 - Imagens/02 - Depois/11290.jpeg', N'FOI FEITO COMUNICAÇÃO QUE O MATERIAL ERA CRÍTICO E REDUZIDO À BUROCRACIA EM 7 MINUTOS DE SEPARAÇÃO PARA ENTREGAR NA ÁREA SLB III / USINA NO CICLO DA PGU JUL / 2026.', NULL, N'MUITA AGILIDADE NO FLUXO DE SEPARAÇÃ DE MATERIAIS PARA ATENDER A URGÊNCIA CRÍTICA DO RECURSO.', N'COMUNICAÇÃO É O MELHOR REMÉDIO PARA INTERVENÇÃO DE URGÊNCIA DO MATERIAL CRÍTICO.', 1, 1, NULL, '2026-07-01T00:00:00.000', '2026-07-21T17:47:43.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11291, N'1008390', N'1008390', N'Handle fell off safety shower ', 2, N'Refining/Refino', N'YEM was put in today about safety shower handle was on the floor so the shower could not be pulled if it needed to be used ', N'To fix safety shower so that it can be  used ', N'0', N'01 - Imagens/01 - Antes/11291.jpeg', N'YEM was put in today for safety shower handle had fallen off, so if the safety shower had to used you would not be able to pull the handle. ', N'01 - Imagens/02 - Depois/11291.jpeg', N'When I inspected the shower as to why the handle fell off, I noticed that the nut that held the handle on was missing. Located another nut and put the handle back on and tightened nut. Shower not works as it shoulda', NULL, N'Yes Problem was solved and safety shower is fixed and can be used ', N'Troubleshooting can lead to an easy solution ', 500, 3, N'A melhoria reduziu o esforço físico, aumentou a segurança e padronizou a operação na CF-2057-01.', '2026-07-21T00:00:00.000', '2026-07-22T01:44:33.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11292, N'87000324', N'87000442', N'Specification Change for Bolts and Nuts Used to Secure the 110 kW RB Unit', 1, N'Refining/Refino', N'We had been securing the main unit with double nuts, but there were concerns that the bolts might loosen.', N'Improvements in Insulation and Measurement Efficiency', N'10217', N'01 - Imagens/01 - Antes/11292.jpeg', N'We had been securing the main unit with double nuts, but there were concerns that the bolts might loosen.', N'01 - Imagens/02 - Depois/11292.jpeg', N'We switched to Hardlock Nuts to address the causes of screw loosening.', NULL, N'There was no gap,', N'Optimization', 0, NULL, N'Muito mais segurança', '2026-06-17T00:00:00.000', '2026-07-22T05:17:56.000', N'87000324', NULL, NULL);
INSERT INTO #PVC VALUES (11293, N'87000324', N'87000320', N'Addition to  Regarding Crane Operations on 　Construction Safety Regulations', 2, N'Refining/Refino', N'Since there are no opportunities to raise awareness about the distance between high-voltage power lines and cranes, it is difficult to recognize the danger.', N'Notice to Employees', N'10217', N'01 - Imagens/01 - Antes/11293.jpeg', N'Since there are no opportunities to raise awareness about the distance between high-voltage power lines and cranes, it is difficult to recognize the danger.', N'01 - Imagens/02 - Depois/11293.jpeg', N'High-voltage power lines have been marked on the factory layout plan, and preparations for the risk assessment are complete.', NULL, N'There was no gap,', N'heads up', 0, NULL, N'Melhorar a segurança e a ergonomia da operação, reduzir o tempo de intervenção, facilitar a abertura e o fechamento da válvula e padronizar o sistema de acionamento da AM-2017-47.', '2026-07-21T00:00:00.000', '2026-07-22T06:00:42.000', N'87000324', NULL, NULL);
INSERT INTO #PVC VALUES (11294, N'81033365', N'81033365', N'Suporte de bateria', 2, N'Others/Outros', N'ausência de um suporte correto', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/11294.jpeg', N'O suporte antigo encostava nos polos das baterias, gerando curto-circuito e danos mecânicos nas células.', N'01 - Imagens/02 - Depois/11294.jpeg', N'Um novo suporte sob medida foi fabricado, garantindo a fixação firme e o isolamento seguro dos polos.', NULL, N'Problema: Suporte inadequado encostava nos polos, gerando curto-circuito e danificando as baterias.
INSERT INTO #PVC VALUES (11295, N'81058966', N'81038855', N'Adequação da tubulação dos canhões de limpeza da baia da CX-2057-06', 1, N'Others/Outros', N'Durante o translado da CX-2057-06, foi identificado um grande acúmulo de material concentrado na baia, com potencial de ser direcionado ao sump. Entretanto, devido às constantes falhas na tubulação de alimentação dos canhões de lavagem, não era possível realizar a limpeza de forma eficiente, ocasionando perdas operacionais, acúmulo de material e maior necessidade de intervenções de manutenção.', N'Aumentar a vida útil da tubulação; Garantir a disponibilidade dos canhões de lavagem; Reduzir perdas operacionais; Proporcionar um ambiente mais limpo, seguro e organizado.', N'10031', N'01 - Imagens/01 - Antes/11295.jpeg', N'Durante o translado da CX-2057-06, foi identificado grande acúmulo de material concentrado na baia. A indisponibilidade dos canhões de lavagem impedia a remoção desse material e seu retorno ao circuito de processo.', N'01 - Imagens/02 - Depois/11295.jpeg', N'Foi fabricado e instalado um novo trecho de tubulação, substituindo o percurso subterrâneo por um trajeto externo. ', NULL, N'SIM. O problema foi resolvido com a substituição da tubulação subterrânea por uma tubulação externa, eliminando os vazamentos de água e restabelecendo a disponibilidade dos canhões de lavagem. A solução permitiu a recuperação do material acumulado na baia da CX-2057-06, reduzindo perdas operacionais e proporcionando um ambiente mais limpo, seguro e organizado.', N'Aumento da vida útil da tubulação; Eliminação de vazamentos de água; Maior disponibilidade dos canhões de lavagem;', 0, NULL, N'Redução da escrita manual repetitiva, diminuindo a fadiga das mãos e dos punhos , maior conforto e agilidade na execução da atividade administrativa.', '2026-07-09T00:00:00.000', '2026-07-22T08:53:32.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11296, N'124132', N'124132', N'Tripping hazard', 3, N'Refining/Refino', N'We do not have enough electrical outlets in our lunchroom. There was one area in the lunchroom that an employee was using to charge their cell phone. It was stretched across the table and floor area. ', N'Remove tripping hazard', N'10255', N'01 - Imagens/01 - Antes/11296.jpeg', N'We do not have enough electrical outlets in our lunchroom. There was one area in the lunchroom that an employee was using to charge their cell phone. It was stretched across the table and floor area. ', N'01 - Imagens/02 - Depois/11296.jpeg', N'I purchased some extension cords to be used in the lunchroom removing the tripping hazard.', NULL, N'We had a safety issue that needed to be addressed.', N'The importance of removing the tripping hazard', 0, NULL, NULL, '2026-07-21T00:00:00.000', '2026-07-22T10:36:03.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11297, N'202630', N'202630', N'Rental rate reduction', 2, N'Others/Outros', N'Required an additional 20 Chlorine gas monitors - monthly rate of $4800 received, added to our current contract with new monthly rate of $1302.93', N'To reduce monthly rental rate by adding to contract', N'10026', N'01 - Imagens/01 - Antes/11297.jpeg', N'Required an additional 20 Chlorine gas monitors - monthly rate of $4800 received.', N'01 - Imagens/02 - Depois/11297.jpeg', N'Added to our current contract with new monthly rate of $1302.93', NULL, N'Yes, cost savings of $3497.07 per month, 
INSERT INTO #PVC VALUES (11298, N'553135', N'516988', N'PROTEÇÃO DA HASTE DO CILINDRO - EC-20', 2, N'Others/Outros', N'ANTES A HASTE DO CILINDRO FICAVA EXPOSTA A MATERIAIS ABRASIVOS,  SENDO DANIFICADO COM MUITA FACILIDADE. ISSO GERAVA UMA FREQUENTE NECESSIDADE DE TROCA DO CILINDRO EXPONDO OS EMPREGADOS AO RISCO DE ESMAGAMENTO E PRENSAMENTO. ', N'AUMENTAR A VIDA UTIL ', N'10139', N'01 - Imagens/01 - Antes/11298.jpeg', N'ANTES A HASTE DO CILINDRO FICAVA EXPOSTA A MATERIAIS ABRASIVOS,  SENDO DANIFICADO COM MUITA FACILIDADE. ISSO GERAVA UMA FREQUENTE NECESSIDADE DE TROCA DO CILINDRO EXPONDO OS EMPREGADOS AO RISCO DE ESMAGAMENTO E PRENSAMENTO. ', N'01 - Imagens/02 - Depois/11298.jpeg', N'FOI ADQUIRIDA UMA CAPA PROTETORA PARA A HASTE DO CILINDRO. BENEFICIOS ALCANÇADOS: REDUÇÃO DE TROCA DE CILINDROS, EMPREGADOS MENOS EXPOSTOS A RISCOS REALCIONADOS A MANUTENÇÃO E REDUÇÃO DE CUSTO. ', NULL, N'FOI ADQUIRIDA UMA CAPA PROTETORA PARA A HASTE DO CILINDRO. BENEFICIOS ALCANÇADOS: REDUÇÃO DE TROCA DE CILINDROS, EMPREGADOS MENOS EXPOSTOS A RISCOS REALCIONADOS A MANUTENÇÃO E REDUÇÃO DE CUSTO. ', N'SOLUÇÕES EFICAZES ', 0, NULL, N'A aderência do IMOS Automação foi recuperada por meio da revisão das programações, priorização das atividades críticas, alinhamento com a equipe executante e tratativa das ordens recorrentes, garantindo maior execução das OMs e redução do backlog, essa tratativa semanal teve um resultado positivo na aderência desse indicador.', '2026-07-21T00:00:00.000', '2026-07-22T10:52:59.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11299, N'81029574', N'81029574', N'Programação de Sondagem via GPS de navegação para confecção das praças de sondagem', 1, N'Open Pit/Poço aberto', N'O processo de sondagem dependia da equipe de Topografia para realizar a locação e marcação dos furos em campo antes da confecção das praças de sondagem. Essa dependência gerava atrasos no cronograma, aumento do tempo de espera e redução da produtividade da equipe de sondagem.
INSERT INTO #PVC VALUES (11300, N'81006670', N'81053737', N'Sistema de intertravamento de segurança na porta do gabinete elétrico', 2, N'Others/Outros', N'Durante as atividades de inspeção e manutenção no compressor, a abertura da porta do gabinete elétrico permitia o acesso a componentes energizados, mantendo o circuito de comando disponível.', N'Bloquear acesso a gabinete elétrico do compressor', N'10144', N'01 - Imagens/01 - Antes/11300.jpeg', N'Durante as atividades de inspeção e manutenção no compressor, a abertura da porta do gabinete elétrico permitia o acesso a componentes energizados, mantendo o circuito de comando disponível e expondo os trabalhadores ao risco de choque elétrico e partida inesperada do equipamento. Além disso, qualquer profissional, mesmo não sendo eletricista autorizado, tinha livre acesso ao interior do gabinete, permanecendo exposto aos riscos elétricos e podendo realizar alterações indevidas nos parâmetros do equipamento, sem qualquer sistema de intertravamento ou bloqueio que impedisse esse acesso.', N'01 - Imagens/02 - Depois/11300.jpeg', N'Foi implantado um sistema de intertravamento de segurança na porta do gabinete, utilizando um dispositivo de segurança integrado a um relé de segurança. Com a abertura da porta, o circuito de segurança é interrompido, desenergizando o circuito de comando do compressor e impedindo seu funcionamento. O retorno à operação somente é possível após o fechamento da porta e a realização do reset manual do sistema, garantindo que o equipamento só volte a operar de forma segura.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Como complemento à melhoria, foi instalada uma sinalização visual do tipo giroflex na parte superior do gabinete. Sempre que a porta é aberta, o giroflex é acionado, indicando de forma clara e imediata a condição de porta aberta e perigo, alertando todos os profissionais nas proximidades sobre a condição de risco. ', N'Esse processo transforma o registro de falhas em mudanças concretas em processos, sistemas e comportamentos.', 0, NULL, N'CONFECIONADA E INSTALADA FIXAÇÃO DOS TUBOS, GERANDO AUMENTO DA VIDA UTIL DO COMPONENTE E REDUÇÃO DE CUSTO. ', '2026-07-21T00:00:00.000', '2026-07-22T11:48:32.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (11301, N'545887', N'545887', N'Projeção semanal caminhões de leves ', 1, N'Others/Outros', N'A equipe de Automação enfrentava grandes dificuldades para executar suas atividades, devido à falta de visibilidade das demandas de automação no planejamento e programação das atividades de Leves. Frequentemente, as intervenções eram impactadas porque não havia uma projeção adequada contendo informações essenciais, como a descrição das atividades, a quantidade de horas de máquina necessárias e a respectiva demanda a ser atendida.
INSERT INTO #PVC VALUES (11302, N'81006670', N'81053737', N'Melhoria do Circuito Elétrico da Bancada de Teste para Motores de Partida.', 2, N'Others/Outros', N'O motor de partida, cuja corrente nominal pode atingir aproximadamente 120 A, era acionado diretamente por uma chave Margirius com capacidade nominal de apenas 15 A.', N'Melhoria no circuito elétrico da bancada por meio da separação entre os circuitos de comando e potência.', N'10144', N'01 - Imagens/01 - Antes/11302.jpeg', N'A bancada de teste para motores de partida foi fornecida pelo fabricante com o circuito de acionamento elétrico subdimensionado para a aplicação. O motor de partida, cuja corrente nominal pode atingir aproximadamente 120 A, era acionado diretamente por uma chave Margirius com capacidade nominal de apenas 15 A. Essa condição provocava sobrecarga no dispositivo de manobra, ocasionando centelhamento nos contatos e conexões da chave, aquecimento excessivo e elevado risco de falha elétrica, além de comprometer a segurança operacional e a confiabilidade dos ensaios.', N'01 - Imagens/02 - Depois/11302.jpeg', N'Foi implementada uma melhoria no circuito elétrico da bancada por meio da separação entre os circuitos de comando e potência. O acionamento do motor de partida passou a ser realizado por um contator, responsável pelo seccionamento da alimentação elétrica de potência, enquanto uma chave seletora de duas posições ficou dedicada exclusivamente ao circuito de comando, acionando apenas a bobina do contator. Também foi incorporada proteção por disjuntor no circuito. Com essa modificação, a corrente elevada do motor deixou de circular pela chave seletora, eliminando o centelhamento, aumentando a vida útil dos componentes, proporcionando maior segurança operacional e tornando a bancada mais confiável para a realização dos testes.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Com essa modificação, a corrente elevada do motor deixou de circular pela chave seletora, eliminando o centelhamento, aumentando a vida útil dos componentes, proporcionando maior segurança operacional e tornando a bancada mais confiável para a realização dos testes.', N'Esse processo transforma o registro de falhas em mudanças concretas em processos, sistemas e comportamentos.', 0, NULL, N'Eliminação do riscos de prensamento e esmagamento e melhoria riscos ergonômico', '2026-07-21T00:00:00.000', '2026-07-22T13:22:26.000', N'81006670', NULL, NULL);
INSERT INTO #PVC VALUES (11303, N'81058075', N'81058075', N'Uniform Sharing and Control Kaizen', 3, N'Others/Outros', N'Uniforms and coveralls at the Long Harbour site are currently stored across multiple locations, including the stockroom and areas near the washrooms, without a consistent process to manage identification, issuance, condition, laundry dispatch, return, or availability for controlled sharing. As a result, some garments remain unidentified, damaged items may be mixed with usable stock, excess inventory is not fully utilized, and the site has limited visibility into the true need for new purchases. This creates avoidable risk related to waste, unnecessary spend, administrative rework, invoice validation, and missed opportunities to maximize the value of garments already available on site.', N'Establish a simple, traceable, and sustainable process to manage uniforms and coveralls at Long Harbour by prioritizing existing stock before new purchases, reducing laundry process discrepancies, and improving stockroom organization. ', N'0', N'01 - Imagens/01 - Antes/11303.jpeg', N'The current process relies primarily on manual controls, informal knowledge, and visual checks. The stockroom does not yet function as a single, reliable source of information because garments are not consistently classified by size, condition, usage status, or laundry status. There is also no reliable digital record confirming how many garments were sent to the laundry, how many were returned, or whether supplier invoices accurately reflect the volume processed. As a result, new uniforms may be requested even when usable garments are available, and the site cannot clearly quantify current waste levels or potential savings.', N'01 - Imagens/02 - Depois/11303.jpeg', N'The stockroom will be reorganized and standardized using 5S principles, with uniforms and coveralls clearly separated by type, size, condition, and status. Clean and usable garments will be made available through a controlled sharing model, supported by defined issuance and return rules. A digital app or tracking tool will record garments sent to and returned from the laundry, enabling monthly reconciliation against supplier invoices. This future-state process will improve traceability, strengthen operational control, increase utilization of existing inventory, and reduce unnecessary purchases and laundry activity.
INSERT INTO #PVC VALUES (11304, N'81058966', N'81054451', N' Adequação da válvula da tubulação de ar – CF-2057-01', 1, N'Others/Outros', N'Durante uma manutenção na tubulação de ar da CF-2057-01, foi identificado que a válvula existente exigia o uso de chave e elevado esforço físico para sua abertura e fechamento. Essa condição aumentava o risco de lesões ergonômicas, dificultava a execução da atividade e impactava a segurança e a eficiência da manutenção.', N' Melhorar a ergonomia e a segurança da atividade, padronizando o sistema de acionamento da válvula e facilitando sua operação.', N'10031', N'01 - Imagens/01 - Antes/11304.jpeg', N'A válvula antiga necessitava de chave para seu acionamento e exigia grande esforço físico para abrir e fechar', N'01 - Imagens/02 - Depois/11304.jpeg', N'A válvula foi substituída por um modelo com volante, permitindo abertura e fechamento de forma simples, rápida e sem necessidade de ferramentas', NULL, N'sim,permitindo abertura e fechamento de forma simples.', N'Pequenas melhorias podem gerar grandes ganhos em segurança, ergonomia e produtividade.', 0, NULL, N'Identify a practical opportunity to reuse rainwater already available at Long Harbour, supporting sustainability, responsible water use, and potential cost reduction', '2026-07-15T00:00:00.000', '2026-07-22T14:43:39.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11305, N'92000525', N'486875', N'Melhoria dos sensores indutivos do mastro', 2, N'Others/Outros', N' As atividades de inspeção, ajuste, manutenção ou substituição desses sensores exigiam a execução de trabalhos em altura, enquadrados nos requisitos do RAC 01 – Trabalho em Altura, demandando a adoção de controles específicos de segurança, utilização de sistemas de acesso e equipamentos de proteção adequados.', N'Tornar os sensores acessíveis para executar a atividade sem risco', N'10324', N'01 - Imagens/01 - Antes/11305.jpeg', N'Situação Anterior Os dois sensores indutivos responsáveis pelo monitoramento da posição do carrossel de acomodação das hastes de perfuração estavam instalados a aproximadamente 10 metros de altura. Esses sensores desempenham função de segurança e intertravamento dos movimentos da cabeça rotativa, fornecendo ao sistema informações sobre a posição do carrossel, indicando se este se encontra na condição de giro ou recolhimento.', N'01 - Imagens/02 - Depois/11305.jpeg', N'Após a realocação dos dois sensores indutivos para uma posição acessível ao nível da plataforma de trabalho, as atividades de inspeção, instalação, ajuste e manutenção dos sensores e respectivos cabeamentos passaram a ser executadas em condição de acesso seguro, sem necessidade de intervenção em altura. Com essa modificação, foi eliminada a exposição dos empregados aos riscos associados ao trabalho em altura, bem como a necessidade de execução de atividades enquadradas no RAC 01 – Trabalho em Altura, uma vez que os componentes passaram a estar localizados abaixo da altura mínima estabelecida para caracterização dessa atividade nas operações da Vale (1,80 m).', NULL, N'Além do ganho em segurança, a alteração proporcionou maior facilidade de acesso aos componentes, redução da complexidade das intervenções de manutenção e aumento da eficiência operacional, mantendo integralmente a funcionalidade de monitoramento e intertravamento do sistema.  Muito mais segurança ', N'Com essa modificação, foi eliminada a exposição dos empregados aos riscos associados ao trabalho em altura, bem como a necessidade de execução de atividades enquadradas no RAC 01 – Trabalho em Altura, uma vez que os componentes passaram a estar localizados abaixo da altura mínima estabelecida para caracterização dessa atividade nas operações da Vale (1,80 m).', 0, NULL, NULL, '2026-06-28T00:00:00.000', '2026-07-22T14:50:59.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11306, N'81058966', N'81058966', N' Adequação da válvula da linha de ar – AM-2017-47', 1, N'Others/Outros', N'Durante uma manutenção na linha de ar da AM-2017-47, foi identificado que a válvula existente possuía acionamento inadequado, exigindo elevado esforço físico e o uso de ferramenta para sua operação. Essa condição aumentava o risco de lesões ergonômicas e dificultava as atividades de manutenção.', N' Melhorar a ergonomia, a segurança e a padronização da operação, facilitando a abertura e o fechamento da válvula.', N'10031', N'01 - Imagens/01 - Antes/11306.jpeg', N'A válvula antiga possuía sistema de acionamento que exigia grande esforço físico e utilização de ferramenta para abertura e fechamento.', N'01 - Imagens/02 - Depois/11306.jpeg', N'Foi instalada uma válvula com volante manual, permitindo abertura e fechamento de forma rápida, segura e sem necessidade de ferramentas.', NULL, N'SIM. O problema foi resolvido com a substituição da válvula antiga por uma válvula com volante, eliminando a necessidade de esforço excessivo e do uso de ferramentas. A melhoria proporcionou maior segurança, ergonomia e eficiência operacional, atendendo ao objetivo proposto.', N'A substituição de componentes por modelos mais ergonômicos contribui para a segurança dos empregados, reduz o esforço físico durante as intervenções e fortalece a cultura de melhoria contínua.', 0, NULL, N'The proposed cut-off process improves month-end discipline, reduces SAP transactions, minimizes estimate variances, and allows Contracts and Finance to focus on higher-value activities.', '2026-07-16T00:00:00.000', '2026-07-22T14:51:19.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11307, N'545887', N'545887', N'Acompanhamento semanal IMOS', 1, N'Others/Outros', N'O aumento do backlog de Automação  ocorreu devido à recorrência de reprogramações sem execução das OMs, motivadas principalmente pela indisponibilidade do equipamento, falta de energia para intervenção, restrição de efetivo e execução concomitante de outras demandas. Como consequência, ordens permaneceram pendentes por longos períodos, impactando diretamente os indicadores de manutenção."', N'Manter aderinca', N'10234', N'01 - Imagens/01 - Antes/11307.jpeg', N'O aumento do backlog de Automação  ocorreu devido à recorrência de reprogramações sem execução das OMs, motivadas principalmente pela indisponibilidade do equipamento, falta de energia para intervenção, restrição de efetivo e execução concomitante de outras demandas. Como consequência, ordens permaneceram pendentes por longos períodos, impactando diretamente os indicadores de manutenção."', N'01 - Imagens/02 - Depois/11307.jpeg', N'Após a tratativa da carteira de backlog, a frota de Automação apresentou evolução significativa no controle das pendências, com redução das ordens represadas, maior aderência à programação e melhor alinhamento entre PCM e execução. A atuação conjunta permitiu atacar as principais causas dos desvios, aumentando a efetividade das intervenções e contribuindo para a estabilização dos indicadores de manutenção da frota."', NULL, N'SIM', N'A rotina diária faz total diferença no processo ', 0, NULL, N'Com a redução de tempo conseguimos aumentar a produção. Abrindo espaço para outras demandas. ', '2026-07-10T00:00:00.000', '2026-07-22T14:53:09.000', N'545887', NULL, NULL);
INSERT INTO #PVC VALUES (11308, N'81054438', N'81054438', N'Implantação de carimbo padronizado para encerramento de Permissão de trabalho seguro (PTS)', 1, N'Others/Outros', N'O encerramento manual das PTS consome tempo, apresenta baixa padronização e aumenta a ocorrência de erros de preenchimento, ocasionando retrabalho na conferência e no arquivamento dos documentos.', N'Redução do tempo de encerramento das PTS.', N'10229', N'01 - Imagens/01 - Antes/11308.jpeg', N'O processo de encerramento das Permissões de Trabalho Seguro (PTS) era realizado totalmente por preenchimento manual. As informações de encerramento eram escritas à mão, tornando a atividade repetitiva, demorada e suscetível a erros.', N'01 - Imagens/02 - Depois/11308.jpeg', N'A padronização elimina variações no preenchimento manual.
INSERT INTO #PVC VALUES (11309, N'81058075', N'81058075', N'Long Harbour On-Site Laundry for Coverall Cleaning and Control', 1, N'Others/Outros', N'The current coverall cleaning process depends on an external provider, which limits Vale’s direct control over collection, return, garment identification, turnaround time, service responsiveness, and invoice validation. Existing issues include unidentified garments, limited visibility over Vale-owned coveralls, inconsistent communication with the supplier, and reduced ability to confirm whether cleaned and dirty garments are properly separated.', N'By building an on-site laundry facility, Long Harbour will gain stronger uniform control, achieve cost savings, and reduce dependency on external suppliers.', N'0', N'01 - Imagens/01 - Antes/11309.jpeg', N'Coveralls are collected and cleaned off site, creating dependency on supplier pickup, response time, and external handling practices. Vale has limited visibility into the full cleaning cycle and less control over volume, garment condition, ownership, and service performance.', N'01 - Imagens/02 - Depois/11309.jpeg', N'An on-site laundry would allow Vale to manage receiving, washing, drying, sorting, and availability of coveralls directly at Long Harbour. This would improve operational control, response time, traceability, garment separation, and visibility over the actual volume cleaned each month.
INSERT INTO #PVC VALUES (11310, N'550315', N'550315', N'Gestão à Vista de Materiais com Pendências', 3, N'Others/Outros', N'Material armazenado em palete sem etiqueta de identificação, comprometendo sua rastreabilidade
INSERT INTO #PVC VALUES (11311, N'545887', N'545887', N'Acompanhamento dos IMOS Automação ', 1, N'Others/Outros', N' O IMOS estava sendo impactado por ordens antigas e pendentes da Automação, decorrentes de sucessivos replanejamentos, indisponibilidade do equipamento, falta de energia e limitações de efetivo para execução das atividades e ordens esquecidas na carteira onde havia pendencia apenas de tratativa.', N'Aderência do indicador semanal', N'10234', N'01 - Imagens/01 - Antes/11311.jpeg', N' O IMOS estava sendo impactado por ordens antigas e pendentes da Automação, decorrentes de sucessivos replanejamentos, indisponibilidade do equipamento, falta de energia e limitações de efetivo para execução das atividades e ordens esquecidas na carteira onde havia pendencia apenas de tratativa.', N'01 - Imagens/02 - Depois/11311.jpeg', N'A aderência do IMOS Automação foi recuperada por meio da revisão das programações, priorização das atividades críticas, alinhamento com a equipe executante e tratativa das ordens recorrentes, garantindo maior execução das OMs e redução do backlog, essa tratativa semanal teve um resultado positivo na aderência desse indicador.', NULL, N'sim', N'Manter o acompanhamento e a rotina com melhoria se faz acontecer.', 0, NULL, N'segurança', '2026-07-10T00:00:00.000', '2026-07-22T15:42:04.000', N'545887', NULL, NULL);
INSERT INTO #PVC VALUES (11312, N'553135', N'543407', N'DISPOSITIVO DE SEGURANÇA MA-83', 2, N'Others/Outros', N'Análise dos riscos durante a manutenção
INSERT INTO #PVC VALUES (11313, N'553135', N'81047717', N'SUPORTE DE FIXAÇÃO DO TUBO DOS CILINDRO TRATOR DE ESTEIRA D6', 1, N'Others/Outros', N'TUBOS SEM A DEVIDA FIXAÇÃO, DESGATE PREMATURO DOS TUBOS
INSERT INTO #PVC VALUES (11314, N'81045351', N'81045351', N'COMPOSTEIRA ', 2, N'Others/Outros', N'A unidade gera diariamente resíduos orgânicos provenientes do preparo e das sobras de alimentos, que são destinados integralmente ao descarte. Essa prática aumenta o volume de resíduos enviados para destinação final, gera custos operacionais e desperdiça um material que poderia ser reaproveitado de forma sustentável.', N'Reduzir o desperdício de resíduos orgânicos por meio da implantação de uma composteira, transformando resíduos em recurso útil, diminuindo os impactos ambientais, incentivando a gestão sustentável de resíduos e promovendo a conscientização ambiental dos colaboradores.', N'10017', N'01 - Imagens/01 - Antes/11314.jpeg', N'Os resíduos orgânicos eram destinados ao descarte, sem processo de reaproveitamento. Aumento do volume de resíduos encaminhados para destinação final, desperdício de matéria orgânica.', N'01 - Imagens/02 - Depois/11314.jpeg', N'Após a implantação da composteira, os resíduos orgânicos passaram a ser reaproveitados na produção de adubo, reduzindo o descarte e fortalecendo as práticas de sustentabilidade da unidade.', NULL, N'A meta foi atingida com a implantação da composteira, permitindo o reaproveitamento dos resíduos orgânicos que antes eram descartados. A iniciativa reduziu o volume de resíduos destinados à coleta, promoveu a produção de adubo orgânico e fortaleceu as práticas de sustentabilidade na unidade.', N'A segregação correta dos resíduos é essencial para o sucesso da compostagem. O engajamento da equipe, a conscientização ambiental e o acompanhamento do processo garantem melhores resultados e possibilitam replicar a iniciativa em outras unidades.', 0, NULL, N'Melhoria da organização do setor, liberação de área de circulação, armazenamento adequado dos materiais e redução do risco de acidentes.', '2026-07-03T00:00:00.000', '2026-07-22T16:09:35.000', N'81045351', NULL, NULL);
INSERT INTO #PVC VALUES (11315, N'81034916', N'81034916', N'SEGURANÇA NO PROCESSO DE CALANDRAGEM', 2, N'Others/Outros', N'Riscos de prensamento/esmagamento por contato acidental com parte móveis da calandra e exposição ergonômicas. 
INSERT INTO #PVC VALUES (11316, N'81058075', N'81058075', N'Controlled Uniform Purchasing and Employee Distribution Process', 3, N'Others/Outros', N'Employees are requesting new uniforms without a formal procedure or clear approval rules. The laundry service has reported approximately 5 to 15 new uniforms per weekly pickup, creating risk of unnecessary purchases, weak cost control, inconsistent decisions, and limited visibility over the real operational need.', N'Establish a standardized process for new uniform acquisition while promoting awareness and accountability among all stakeholders involved.', N'0', N'01 - Imagens/01 - Antes/11316.jpeg', N'Requests may be submitted based on individual need or urgency, without verification of available new or used stock, documented justification, or standard approval criteria. As a result, Vale has limited ability to confirm whether each new uniform is truly required or whether an available new or used uniform could be issued first.', N'01 - Imagens/02 - Depois/11316.jpeg', N'All requests will follow a standard process requiring verification of available new and used stock, justification, approval before purchase, and registration by employee. This will improve purchasing discipline, strengthen accountability, reduce duplicate or emergency purchases, and provide reliable data for monthly cost and demand monitoring.
INSERT INTO #PVC VALUES (11317, N'81058075', N'81058075', N'Rainwater Collection and Reuse from Long Harbour Office Rooftops', 1, N'Others/Outros', N'Rainwater from Long Harbour office rooftops is not currently captured or reused, even though the site receives approximately 1,350 to 1,390 mm of annual precipitation. This creates an opportunity to use an available natural resource to reduce treated water consumption, support environmental goals, and generate potential long-term savings for approved non-potable applications.', N'Promote responsible use of natural resources, support environmental sustainability, and create potential cost savings by reducing the risk of exceeding monthly or annual water consumption limits.', N'0', N'01 - Imagens/01 - Antes/11317.jpeg', N'Rainwater drains from the office rooftops without being collected, stored, or redirected for controlled use. The site continues to rely on treated water for activities that may not require potable water, such as exterior cleaning, floor washing, irrigation, or future support to an on-site laundry if technically approved.', N'01 - Imagens/02 - Depois/11317.jpeg', N'Rainwater would be collected from selected office rooftops, stored in approved tanks, and reused for non-potable activities such as exterior cleaning, floor washing, irrigation, washrooms and potentially to support a future on-site laundry if technically suitable. Goal: Promote responsible use of natural resources, support environmental sustainability, reduce treated water consumption, and lower the risk of exceeding monthly or annual water usage limits. Savings Potential: Based on estimated precipitation, each 1,000 m² of roof area could provide approximately 1.0 to 1.18 million litres/year of usable rainwater, creating savings by offsetting treated water use. This initiative uses a natural resource already available on site and aligns with long-term cost control, sustainability, and operational resilience goals while Engineering refines the technical feasibility.', NULL, N'The initial goal directly addresses the problem by proposing a practical way to capture and reuse rainwater that is currently being lost. While the problem highlights the missed opportunity and continued reliance on treated water, the goal focuses on converting that unused resource into value through reduced water consumption, environmental benefits, and potential cost saving.', N'Responsible use of natural resources can create both environmental and financial value.', 4, 3, N'Improved access to visitor information during emergency situations, enabling faster and more accurate personnel accountability.', '2026-07-22T00:00:00.000', '2026-07-22T17:59:36.000', N'81058075', NULL, NULL);
INSERT INTO #PVC VALUES (11318, N'541850', N'541850', N'Filtro Torre dos​  Comboios Diesel​', 1, N'Open Pit/Poço aberto', N'Os comboios diesel CA02, CV56 e CV58 utilizavam o filtro torre código Vale 13351854 (PN 400007141), identificado pela gestão como um dos principais ofensores de custo da frota, impactando diretamente o orçamento de manutenção.', N'Redução de custos de manutenção, maior disponibilidade potencial, menor frequência de intervenções, padronização .', N'10081', N'01 - Imagens/01 - Antes/11318.jpeg', N'Os comboios diesel CA02, CV56 e CV58 utilizavam o filtro torre código Vale 13351854 (PN 400007141), identificado pela gestão como um dos principais ofensores de custo da frota, impactando diretamente o orçamento de manutenção. Além disso, o componente permanecia associado a planos preventivos e listas de materiais que necessitavam revisão técnica e atualização, exigindo controle mais rigoroso das aprovações, da estratégia de manutenção e da governança dos materiais aplicados. ', N'01 - Imagens/02 - Depois/11318.jpeg', N'mplementar a substituição do filtro torre código Vale 13351854 (PN 400007141) pelo filtro código Vale 13044565 (PN UE610AP40Z) nos comboios diesel CA02, CV56 e CV58, associada à revisão dos planos SAP PM, atualização das listas de tarefas, regularização contratual via ZCON e implantação de controles de rastreabilidade técnica.                                                                              
INSERT INTO #PVC VALUES (11319, N'81058075', N'81058075', N'Monthly Invoice Cut-Off and Accrual Reduction Process', 1, N'Others/Outros', N'At month-end, missing supplier invoices are currently estimated and entered in SAP as accruals. These estimates may not reflect the final invoice value, especially when supplier projections are exceeded. The process also creates rework for Contracts and Finance through accrual creation, approval, reversal, deleted, and subsequent invoice processing.', N'Eliminate rework and improve process efficiency.', N'0', N'01 - Imagens/01 - Antes/11319.jpeg', N'Invoices not received by the month-end deadline require manual accruals based on estimated values. Contracts create the accrual, Finance approves it, the Contract Manager later reverses it, and Finance or Contracts deletes it before the actual invoice can be entered for payment. This adds non-value-added work, delays invoice processing, and increases exposure to estimate variances.', N'01 - Imagens/02 - Depois/11319.jpeg', N'A monthly invoice cut-off date will be established. Invoices received by the cut-off date will be processed in the current month, while invoices received after the cut-off date will be processed in the following month rather than accrued using uncertain estimates. This approach simplifies the workflow, reduces rework, improves consistency, and supports more disciplined period-end processing.
INSERT INTO #PVC VALUES (11320, N'81020908', N'532815', N'Redução de peneiras em teste de granulometria ', 1, N'Others/Outros', N'Durante os testes de moabilidade, acontece a etapa de peneiramento, onde utilizávamos 7 peneiras para descobri o P80, que significa que 20% do material precisa ficar retido na malha de 212 e 80% passar nas malhas subsequentes, para descobri o tempo de moagem necessário. Demandávamos 20 minutos de peneiramento para cada amostra.  ', N'Reduzir tempo de peneiramento', N'10129', N'01 - Imagens/01 - Antes/11320.jpeg', N'Durante os testes de moabilidade, acontece a etapa de peneiramento, onde utilizávamos 7 peneiras para descobri o P80, que significa 20% do material precisa ficar retido na malha de 212 e 80% passar nas malhas subsequentes, para descobri o tempo de moagem necessário. Demandávamos 20 minutos de peneiramento para cada amostra. Com a necessidade de fazer muitos peneiramentos em um dia, precisávamos reduzir o tempo do processo e termos agilidade nas demais etapas. ', N'01 - Imagens/02 - Depois/11320.jpeg', N' Sabendo a massa inicial de cada amostra foi possível então reduzir o número de peneiras para 4, utilizando as malhas maiores, dessa forma conseguimos identificar quanto de material passou e ficou retido. Com a mitigação das peneiras, reduzimos 10 minutos de peneiramento durante o teste. ', NULL, N'O problema foi resolvido, a meta de redução de tempo foi alcançada sem modificar o resultado.', N'Aprendemos que diminuir os processos sem fugir do padrão reduz tempo e esforço.', 0, NULL, NULL, '2026-07-20T00:00:00.000', '2026-07-23T10:38:03.000', N'81020908', NULL, NULL);
INSERT INTO #PVC VALUES (11321, N'81019448', N'81019448', N'Otimização do Fluxo de Homologação por Meio da Padronização e Governança', 1, N'Projects/Projetos', N'Falta de conhecimento e alinhamento dos requisitantes sobre o processo de desenvolvimento e homologação de materiais e fornecedores, resultando no preenchimento incorreto de documentos,  ocasionando retrabalhos, atrasos, riscos de compliance, inconsistências na aplicação de SAT, PT e RET e subjetividade na avaliação dos resultados dos testes.', N'Reduzir a variabilidade e aumentar a confiabilidade do processo de homologação de materiais por meio da capacitação dos requisitantes quanto às diretrizes, padronização das etapas, definição de responsabilidades, estabelecimento de KPIs quantitativos e reforço dos requisitos de compliance e gestão de riscos.', N'10015', N'01 - Imagens/01 - Antes/11321.jpeg', N'Os requisitantes possuíam níveis distintos de conhecimento sobre o processo, suas responsabilidades e os critérios para utilização das ferramentas SAT, PT e RET. Eram recorrentes solicitações com informações incompletas/incorretas, definição inadequada de KPIs, dúvidas sobre fluxos e papéis entre as áreas, além de desvios relacionados aos requisitos de compliance e gestão de riscos. Esse cenário gerava retrabalhos, devoluções, aumento do lead time das homologações e menor confiabilidade na tomada de decisão.', N'01 - Imagens/02 - Depois/11321.jpeg', N'KPIs quantitativos para avaliação dos testes.
INSERT INTO #PVC VALUES (11322, N'92000525', N'81019022', N'Melhoria do aterramento dos motores partida', 2, N'Others/Outros', N'Ao ter curto circuito com principio de incêndio na Pz 02 com cabo de aterramento do motor de partida fizemos essa melhoria', N'Com essa melhoria temos mais segurança operacional e evitamos possivel  principio de incêndio podendo ter perda material', N'10324', N'01 - Imagens/01 - Antes/11322.jpeg', N'Foi identificada ocorrência de curto-circuito com princípio de incêndio na Pz-02, originado no cabo de aterramento do motor de partida. Como ação corretiva, foi realizada a melhoria no sistema para evitar novas falhas.', N'01 - Imagens/02 - Depois/11322.jpeg', N'Melhoria realizada no aterramento do motor de partida da Pz-02. Aumento da segurança operacional e mitigação do risco de princípio de incêndio e danos materiais.', NULL, N'Sim', N'Pequenas falhas elétricas geram grandes riscos Um cabo de aterramento mal fixado, pode parar a operação e gerar perda material. ', 0, NULL, NULL, '2026-06-06T00:00:00.000', '2026-07-23T11:39:45.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11323, N'525833', N'525833', N'Project de acompanhamento dos Projetos de GP', 1, N'Others/Outros', N'Ausência de acompanhamento dos projetos de responsabilidade do time de grande parada', N'Visibilidade e acompanhamento', N'10023', N'01 - Imagens/01 - Antes/11323.jpeg', N'Não havia acompanhamento estruturado dos projetos da Grande Parada, dificultando o controle de prazos, marcos e a visibilidade das atividades em andamento.', N'01 - Imagens/02 - Depois/11323.jpeg', N'Foi implantado um Project para gestão dos projetos, aumentando a visibilidade, o controle dos prazos e a assertividade no acompanhamento das atividades.', NULL, N'Sim, melhoramos o acompanhamento e demos visibilidade', N'Melhoria no acompanhamento', 0, NULL, N'QUALIDADE, SATISFAÇÃO DA EQUIPE DE EXECUÇÃO, ', '2026-07-13T00:00:00.000', '2026-07-23T11:51:18.000', N'525833', NULL, NULL);
INSERT INTO #PVC VALUES (11324, N'81037003', N'479348', N'SUPORTE PARA TRANSPORTE DOS RADIADORES ', 2, N'Others/Outros', N'TRANSPORTE ERA REALIZADO COM PALETE, HAVIA RISCO DE TOMBAMENTO DA CARGA E QUEBRA DO PALETE ', N'TRANSPORTE SEGUROS ', N'10031', N'01 - Imagens/01 - Antes/11324.jpeg', N'Identificou-se que o transporte de radiadores em paletes apresentava risco de quebra do palete e instabilidade da carga, podendo resultar em tombamentos, acidentes de trabalho e avarias no produto. ', N'01 - Imagens/02 - Depois/11324.jpeg', N'Foi fabricado um suporte específico para o transporte dos radiadores, aumentando a segurança da movimentação e eliminando o risco de tombamento da carga.', NULL, N'A ação eliminou o risco identificado, tornando o transporte dos radiadores mais seguro e estável.', N'Que devemos fazer o transporte de matérias de forma correta ', 0, NULL, N'Centralização das ideias e problemas da área, padronização do fluxo de melhoria contínua, definição clara de responsáveis e prazos, maior rastreabilidade das ações, gestão visual dos cronogramas e fortalecimento da participação da equipe. A solução também criou uma base estruturada para monitorar a aderência aos planos de ação e a evolução das iniciativas.', '2026-07-22T00:00:00.000', '2026-07-23T12:06:21.000', N'81037003', NULL, NULL);
INSERT INTO #PVC VALUES (11325, N'92000525', N'81024026', N'Switch de acionamento do controle Remoto Concluída Produtividade', 2, N'Others/Outros', N'Antes esse Switch era exposto e o operador constantemente desligava involuntariamente com braço esquerdo...causando perda operacional', N'realizada melhoria para proteção/relocação do componente', N'10324', N'01 - Imagens/01 - Antes/11325.jpeg', N'Anteriormente o switch ficava exposto, o que ocasionava desligamentos involuntários pelo operador com o braço esquerdo durante a operação.', N'01 - Imagens/02 - Depois/11325.jpeg', N'COM A PROTEÇÃO DO SWITCH ELIMINAMOS ESSE DESLIGAMENTO INVOLUTARIO E PERDA OPERACIONAL MELHORANDO PRODUTIVIDADE E SEGURANCA NAS ATIVIDADES EVITANDO DESLOCAMENTO DA MANUTENÇÃO PARA REINICIAR EQUIPAMENTO ', NULL, N'Sim', N'Proteção física evita erro humano Componentes críticos como botão de parada/emergência não podem ficar expostos na área de alcance do operador. Proteção simples evita falha por descuido.', 0, NULL, NULL, '2026-06-05T00:00:00.000', '2026-07-23T12:20:36.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11326, N'81037003', N'479348', N'Suporte de transporte de piças do freio ', 1, N'Others/Outros', N'equipamentos eram transportados em paletes', N'transporte com segurança ', N'10031', N'01 - Imagens/01 - Antes/11326.jpeg', N'o transporte das pinças do freio dos moinhos eram realizadas  em paletes, existia o risco de quebra do palete e tombamento da carga, expondo os colaboradores a possíveis acidentes e gerando perdas de material.', N'01 - Imagens/02 - Depois/11326.jpeg', N'Foi fabricado um suporte específico para o transporte das pinças, aumentando a segurança da movimentação e eliminando o risco de tombamento da carga', NULL, N'A meta foi atingida com a implementação do suporte, eliminando o risco de tombamento e aumentando a segurança no transporte.', N'transporte seguro', 0, NULL, N'Increased visibility of Health & Safety communications.
INSERT INTO #PVC VALUES (11327, N'81037003', N'81039148', N'suporte de sustentação de vigas e cantoneiras', 3, N'No Replication/Sem replicação', N'Não tínhamos um local adequado para realizar o armazenamentos de nossos matérias ', N'manter os matérias organizados ', N'10031', N'01 - Imagens/01 - Antes/11327.jpeg', N'Não havia um local adequado para o armazenamento dos materiais, resultando em desorganização da área, dificuldade de acesso aos itens e risco de acidentes durante a movimentação.', N'01 - Imagens/02 - Depois/11327.jpeg', N'Foi fabricado um suporte específico para armazenamento dos materiais, proporcionando melhor organização, aproveitamento do espaço e maior segurança na área de trabalho.', NULL, N'A meta foi atingida com a implantação do suporte, garantindo armazenamento adequado, organização dos materiais e maior segurança operacional.', N'A criação de estruturas adequadas para armazenamento melhora a organização, a segurança e a produtividade da área.', 0, NULL, N'Esse Kaizen ficou muito forte, evidenciando claramente os ganhos de digitalização, gestão visual, produtividade e melhoria do processo de planejamento de manutenção, que são fatores normalmente bem avaliados pela Vale Base Metals. 🚀', '2026-07-14T00:00:00.000', '2026-07-23T12:33:19.000', N'81037003', NULL, NULL);
INSERT INTO #PVC VALUES (11328, N'81026906', N'81026906', N'Revestimento Metálico', 1, N'Others/Outros', N'Grande incidência de desgaste e quebra de tambores de dobra.', N'Troca de todos os tambores de cauda das britagens', N'10178', N'01 - Imagens/01 - Antes/11328.jpeg', N'Durante inspeções operacionais, foi identificada uma elevada incidência de descolamento das placas de revestimento nos tambores de cauda das correias transportadoras. Essa falha tem gerado uma série de consequências operacionais relevantes:
INSERT INTO #PVC VALUES (11329, N'81040303', N'81040303', N'Aplicativo de turno', 1, N'Others/Outros', N'Equipes de manutenção necessitavam de uma aplicação para gerenciamento das atividades ocorridas no turno, com acesso as paradas do sistema GPVm, inclusão de novos registros e abertura de pendências para o turno seguinte.', N'Gerenciamento, otimização', N'10293', N'01 - Imagens/01 - Antes/11329.jpeg', N'Registros enviados via Whatsapp em grupos de equipe.', N'01 - Imagens/02 - Depois/11329.jpeg', N'Desenvolvimento de aplicativo em Power Apps para gestão operacional de ocorrências e pendências do GPVm, permitindo a consulta das paradas registradas no sistema, inclusão de comentários e anexação de evidências diretamente aos apontamentos. A solução possibilita ainda o cadastro de novas ocorrências, abertura e acompanhamento de pendências, proporcionando maior controle, rastreabilidade e gestão das atividades em aberto. Como complemento, o aplicativo oferece a geração automática de relatórios em PDF contendo todas as ocorrências registradas no turno, facilitando o compartilhamento das informações e apoiando a tomada de decisão operacional.', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/90d8e0e8-6a87-4225-a4a7-c077ec7c8a12?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=8e2fad7f-8c9f-4e4b-8bb9-7c250544ce54&sourcetime=1784824484635', N'Houve uma melhora significativa no gerenciamento das informações do turno, permitindo um acompanhamento dos acontecimentos e otimização de tempo com geração de relatórios de turno.', N'Trabalho em equipe', 500000, 1, N'don''t have to use batteries any more', '2026-07-01T00:00:00.000', '2026-07-23T13:44:01.000', N'81040303', NULL, NULL);
INSERT INTO #PVC VALUES (11330, N'81056094', N'81050495', N'Visitor Management System', 1, N'Others/Outros', N'Created a digital Visitor Sign-In Application to replace a paper-based process. The solution improves efficiency, reduces manual data entry, enhances data accuracy, and provides better tracking and reporting of site visitors.', N'Improve the visitor sign in process at Vale corporate offices', N'10353', N'01 - Imagens/01 - Antes/11330.jpeg', N'Visitor sign-in relied on paper records and manual tracking, resulting in extra administrative effort, inconsistent data, and limited visibility into visitor activity.', N'01 - Imagens/02 - Depois/11330.jpeg', N'Implemented a standardized digital visitor sign-in process that improved efficiency, data accuracy, visitor tracking, and reporting. ', NULL, N'Yes - The solution successfully addressed the identified issues by digitizing and standardizing the visitor sign-in process, improving efficiency, data accuracy, tracking, and reporting.', N'User feedback and process standardization were key to developing an effective solution.', 0, NULL, N'Improved user confidence, reduced troubleshooting effort, and accelerated issue resolution.', '2026-07-17T00:00:00.000', '2026-07-23T13:48:22.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11331, N'92000525', N'81063738', N'Suporte base para o armário de material de combate a incêndio ', 1, N'Others/Outros', N'o armário de material de combate a incêndio, estava com a base diretamente no chão. vindo a danificar muito mais rápido ', N'Preservar a integridade do armário ', N'10324', N'01 - Imagens/01 - Antes/11331.jpeg', N'O armário de material de combate á incêndio ficava no chão, com risco de danificar mais rápido devido ao contato com água durante a limpeza da área. ', N'01 - Imagens/02 - Depois/11331.jpeg', N'Mais durabilidade do armário ', NULL, N'Sim', N'Sentimento de dono', 0, NULL, N'Reduced manual effort, improved inventory accuracy, and simplified ongoing printer administration.', '2026-06-12T00:00:00.000', '2026-07-23T14:20:06.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11332, N'81056094', N'81050495', N'Centralized Imaging Station for Computer Deployments', NULL, N'Others/Outros', N'Technicians spent time waiting for image downloads before preparing and deploying computers.', N'Reduce technician wait time by providing a centralized location for computer images.', N'10353', N'01 - Imagens/01 - Antes/11332.jpeg', N'Images had to be downloaded directly from server as needed, creating delays and reducing technician productivity.', N'01 - Imagens/02 - Depois/11332.jpeg', N'Configured a dedicated tower PC for Techs to remote in and store the images creating a central access point on the computer rather than having to download from the network', NULL, N'The imaging station eliminated unnecessary wait times by providing immediate access to images.', N'Centralized resources reduce wait times and improve technician efficiency.', 0, NULL, N'Easier flow of trucks ', '2026-06-08T00:00:00.000', '2026-07-23T14:38:04.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11333, N'1013432', N'1013432', N'Freight Consolidation', 1, N'No Replication/Sem replicação', N'Multiple inbound requests were being uploaded to the freight optimizer and shipped as individual packages. Shipper was contacted to consolidate all the freight once a week to be shipped as one request to save on freight costs. ', N'Cost Savings', N'0', N'01 - Imagens/01 - Antes/11333.jpeg', N'On average each shipment cost was $339 in 2026', N'01 - Imagens/02 - Depois/11333.jpeg', N'Shipments are consolidated weekly at an average cost of $250 per shipment', NULL, N'Yes', N'Methodology can be used in other scenerios', 2328, 3, N'Keep the drivers safe', '2026-07-22T00:00:00.000', '2026-07-23T15:06:34.000', N'1013432', NULL, NULL);
INSERT INTO #PVC VALUES (11334, N'92000525', N'520914', N'Baixa visibilidade das Roc L8 ao acessar mina Corrigido', 1, N'Others/Outros', N'Ao acessar mina a operação com equipamento Roc L8 ficava exposto devido baixa iluminação do equipamento a noite. causando insegurança para operador', N'Melhorar a visibilidade do operador', N'10324', N'01 - Imagens/01 - Antes/11334.jpeg', N'Durante a operação noturna na mina, o equipamento Roc L8 apresentava baixa iluminação frontal, expondo o operador e causando insegurança durante a locomoção. ', N'01 - Imagens/02 - Depois/11334.jpeg', N'Foi realizado a instalação do psicocoflex frontal, aumentando a visibilidade do equipamento e a segurança do Operador durante a locomoção em áreas de curto deslocamento.', NULL, N'Sim', N'Baixa iluminação no equipamento expõe o operador e aumenta o risco de colisão e atropelamento na mina à noite', 0, NULL, N'Redução no tempo de reforma ', '2026-06-11T00:00:00.000', '2026-07-23T15:06:59.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11335, N'1009931', N'202638', N'CMD Scrap Removal', 1, N'Others/Outros', N'A large amount of scrap metal had been gathering around site and need to be removed', N'Sell Scrap Metal', N'0', N'01 - Imagens/01 - Antes/11335.jpeg', N'400TO of scrap metal had accumulated on site. Our internal scrap contractor was unable to remove this volume of scrap metal, and our negotiated contract price was much lower than market value of $50/TO.', N'01 - Imagens/02 - Depois/11335.jpeg', N'Vale negotiated a new agreement with Newco Metals to support the removal of large scrap volumes and maximize returns through market-value pricing @ $110/TO.', NULL, N'Yes, the new scrap removal and sales process generated approximately 44K in revenue for Vale, representing a 24K increase over the 20K that would have been earned using the previous method.', N'Accumulating scrap reaped a higher rate of return and value for Vale', 24000, 3, N'Será ampliado para os demais transportadores', '2026-07-10T00:00:00.000', '2026-07-23T15:44:23.000', N'1009931', NULL, NULL);
INSERT INTO #PVC VALUES (11336, N'495045', N'495045', N'SUPORTE DE PONTO DE ANCORAGEM PARA CINTO DE SEGURANÇA', 2, N'Crusher/Britadeira', N'Durante a aferição da APF, foi identificada a ausência de ponto de ancoragem para o cinto de segurança. Trata-se de uma atividade crítica, com elevado risco de queda do colaborador para o interior do britador, podendo resultar em acidente grave ou fatal. É necessária a implementação de um sistema de ancoragem adequado antes da execução da tarefa.', N'AUMENTAR E GARANTIR A SEGURANÇA NA AFERIÇÃO DA APF', N'10293', N'01 - Imagens/01 - Antes/11336.jpeg', N'ANTES A ATIVIDADE ERA REALIZADA SEM O CINTO DE SEGURANÇA POR FALTA DE PONTO DE ANCORAGEM TRAZENDO RISCOS ACIDENTES E INCIDENTES.', N'01 - Imagens/02 - Depois/11336.jpeg', N'FOI FABRICADO UM SUPORTE E INSTALADO NA ESTRUTURA PARA SERVIR DE PONTO DE ANCORAGEM ONDE COLOCA-SE O TRAVA QUEDA RETRATIL JUNTAMENTE COM CINTO MITIGANDO TODOS OS RISCOS DE QUEDA.', NULL, N'SIM, POIS COM ESSE DISPOSITIVO ELIMINAMOS O RISCO DE QUEDA DO OPERADOR DENTRO DO BRITADOR DURANTE A AFERIÇÃO DA APF.', N'SOLUÇÕES SIMPLES PARA GARANTIR A SEGURANÇA', 0, NULL, N'Resultados Obtidos
INSERT INTO #PVC VALUES (11337, N'81007925', N'81007925', N'Fábrica de Ideias e Salobo Solutions: Da Ideia à Execução', 1, N'Others/Outros', N'Ideias e problemas eram discutidos de forma descentralizada, sem um fluxo estruturado para registro, priorização e acompanhamento. Isso dificultava a definição de responsáveis e prazos, reduzia a rastreabilidade das ações e aumentava o risco de oportunidades de melhoria não avançarem até a implementação.', N'Estruturar o ciclo de melhoria contínua da área, desde o brainstorming e registro de ideias e problemas até a definição de responsáveis, prazos, ações e resultados, aumentando a participação, a rastreabilidade e a efetividade na implementação das soluções.', N'10078', N'01 - Imagens/01 - Antes/11337.jpeg', N'Ideias e problemas eram discutidos em reuniões e canais distintos, sem um fluxo padronizado para registro, priorização e acompanhamento. Não havia visão consolidada de responsáveis, prazos e andamento das ações, aumentando o risco de oportunidades perderem visibilidade ou não avançarem até a implementação.', N'01 - Imagens/02 - Depois/11337.jpeg', N'Foram implantadas duas soluções complementares: a Fábrica de Ideias, para brainstorming, registro e priorização de oportunidades, e o Salobo Solutions, para definir responsáveis, prazos, planos de ação e status. A gestão visual em Power BI padronizou o fluxo da ideia à solução, ampliando a rastreabilidade, o acompanhamento gerencial e a efetividade das ações.', N'https://padlet.com/CaioFogliarine/fabrica-de-ideias-7vozi24j77i9e3jj /  https://app.powerbi.com/groups/me/apps/fb9add9f-c44e-43e7-bbe7-e0c8e3bd0c6c/reports/350a81d8-2f37-43d5-bf82-121ac2455eb8/79a24566b2a0896eac72?experience=power-bi ', N'Comparação com a meta inicial/declaração de problemas:
INSERT INTO #PVC VALUES (11338, N'81038056', N'81038056', N'Cisco Call Manager Cleanup and License Management Process', 1, N'Others/Outros', N'Call Manager contained inactive and unregistered devices and Numbers, making license and number management difficult and increasing manual effort to identify devices and numbers suitable for removal. we were running out of licenses. Cleanup activities were inconsistent and time-consuming.', N'Reduce wasted licenses and administrative effort by establishing a repeatable cleanup process for inactive devices.', N'10100', N'01 - Imagens/01 - Antes/11338.jpeg', N'Manual device review.
INSERT INTO #PVC VALUES (11339, N'81038056', N'81038056', N'Deployment of Digital Displays to Improve Health & Safety Communications at OOC', 1, N'Others/Outros', N'Health & Safety updates, awareness campaigns, and critical communications relied on traditional communication methods that may not always reach employees at the right time or in the right location. There was an opportunity to improve visibility of important safety information within operational areas.', N'Improve visibility, accessibility, and reach of Health & Safety communications by deploying digital display technology in key operational areas at OOC.', N'10100', N'01 - Imagens/01 - Antes/11339.jpeg', N'Health & Safety information was distributed through existing communication channels.
INSERT INTO #PVC VALUES (11340, N'510839', N'510839', N'Dashboard Projeção de Planos de Manutenção de Automação – Base SAP IP19', 1, N'Others/Outros', N'O acompanhamento dos planos de manutenção da automação era realizado por meio de relatórios AMS M+3 com grande volume de dados e baixa capacidade analítica. A ausência de indicadores visuais e filtros específicos dificultava a identificação rápida dos planos programados, aumentando o tempo de análise e reduzindo a eficiência do planejamento da manutenção.', N'Reduzir o tempo de análise dos planos de manutenção da automação, aumentando a visibilidade das informações, a assertividade do planejamento e a rapidez na tomada de decisão através da digitalização e consolidação dos dados em um dashboard interativo.', N'10234', N'01 - Imagens/01 - Antes/11340.jpeg', N'O acompanhamento dos planos de manutenção da Automação era realizado no AMS M+3, exigindo filtros e consultas manuais, dificultando análises, visualização dos dados e a tomada de decisão.', N'01 - Imagens/02 - Depois/11340.jpeg', N'Desenvolvido dashboard Power BI com filtros dinâmicos, indicadores visuais e cores para AMS dos planos, facilitando análises, priorização das atividades e tomada de decisão.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/07e3fe80-a920-4704-84d5-182a48eb6756/f92168403940559d4135?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim. Maior visibilidade dos planos programados, padronização das análises, redução do tempo de busca por informações, priorização mais eficiente das atividades e suporte à tomada de decisão da equipe de PCM.', N'A utilização de dashboards interativos com indicadores visuais e segmentação dinâmica aumenta a produtividade das análises, padroniza informações e melhora a tomada de decisão.', 0, NULL, N'Renamed 16,000 PDF files and generated the required spreadsheet within minutes.', '2026-07-22T00:00:00.000', '2026-07-23T19:20:56.000', N'510839', NULL, NULL);
INSERT INTO #PVC VALUES (11341, N'81046597', N'81046597', N'Ferramenta de Análise de Testes de Oportunidade', 1, N'Open Pit/Poço aberto', N'Falta de aprofundamento na análise dos desvios sob a ótica da confiabilidade humana, comprometendo a consistência da classificação das infrações.', N'Padronizar a análise e classificação de desvios operacionais', N'10293', N'01 - Imagens/01 - Antes/11341.jpeg', N'Classificação de desvios baseada apenas no procedimento ou no item descumprido, sem aprofundamento das causas do descumprimento.', N'01 - Imagens/02 - Depois/11341.jpeg', N'Classificação estruturada com análise dos fatores de confiabilidade humana, permitindo identificar e tratar as causas dos desvios de forma mais assertiva, com melhor direcionamento dos inspetores de DBU.', N'https://app.powerbi.com/groups/me/apps/26f3e8ea-2b35-43eb-b4e0-5b07e8ff22ae/reports/5c4ce671-9ac9-4b16-953f-d1556a080401/c61511ca5aab9b4e5902?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim. O problema foi resolvido por meio da implementação de uma ferramenta estruturada para análise dos desvios baseada nos fatores de confiabilidade humana.', N'Análise estruturada reduz a subjetividade das avaliações e permite ações mais eficazes.', 0, NULL, N'100% dos materiais preparados e revisados com antecedência, garantindo apresentações de alta qualidade, comunicação clara e maior confiança nas tomadas de decisão.', '2026-07-22T00:00:00.000', '2026-07-23T23:41:39.000', N'81046597', NULL, NULL);
INSERT INTO #PVC VALUES (11342, N'81036736', N'81036736', N'Head Lamp Charging Station', 1, N'Others/Outros', N'Not being able to find a charger for head lamp having to have head lamp in tech room on desk', N'Always have a charged headlamp', N'0', N'01 - Imagens/01 - Antes/11342.jpeg', N'Before adding in head lamp changing station', N'01 - Imagens/02 - Depois/11342.jpeg', N'Now we can hang up our hard hats and charge our head lamps in the changeroom.', NULL, N'Charging station for head lamp. Don''t have to use batteries. A place to hang up our hard hats to charge our head lamps. so, we don''t have to go looking for the right cords and a place to plug them in.', N'Easy way to do thing', 5000, 3, NULL, '2026-07-03T00:00:00.000', '2026-07-24T00:50:11.000', N'81036736', NULL, NULL);
INSERT INTO #PVC VALUES (11343, N'81056094', N'81049500', N'LTE Surface Testing Environment for Underground Tablets', NULL, N'Others/Outros', N'Tablets were deployed underground without prior LTE testing, resulting in user complaints and troubleshooting delays.', N'Enable testing of LTE tablets on surface before underground deployment to identify issues early and improve reliability.', N'10349', N'01 - Imagens/01 - Antes/11343.jpeg', N'No LTE test environment existed on surface. Issues were discovered only after tablets were deployed underground.', N'01 - Imagens/02 - Depois/11343.jpeg', N'Installed LTE equipment on surface, allowing tablets to be tested and validated before underground deployment.', NULL, N'The LTE test environment enabled pre-deployment validation, addressing the root cause of deployment complaints.', N'Testing equipment in a production-like environment before deployment reduces support issues and user frustration.', 0, NULL, NULL, '2026-06-23T00:00:00.000', '2026-07-24T08:47:58.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11344, N'81056094', N'81049500', N'Network Integration of Xerox Printers in Thompson', NULL, N'Others/Outros', N'Some printers relied on local or USB connections, limiting visibility, management, and automated services.
INSERT INTO #PVC VALUES (11345, N'81009995', N'81009995', N'Truck Scale Access Reading', 1, N'No Replication/Sem replicação', N'Without an access reading, the shipper/receiver does not know if the scale is operating effectively or not.', N'Better access to scale system', N'10255', N'01 - Imagens/01 - Antes/11345.jpeg', N'No information screen to show when scale is not working', N'01 - Imagens/02 - Depois/11345.jpeg', N'Proper reading to show when scale is not operating correctly', NULL, N'Information to allow our shipper/receiver better access to our scale', N'better understanding of our scale operations ', 0, NULL, N'- Improved accessibility for technicians of all heights.
INSERT INTO #PVC VALUES (11346, N'81009995', N'81009995', N'Disposable Pants at Shipping Office', 1, N'Others/Outros', N'Drivers show up with shorts and cannot enter the plant', N'Give drivers disposable pants to enter the plant', N'10255', N'01 - Imagens/01 - Antes/11346.jpeg', N'No disposable pants for drivers', N'01 - Imagens/02 - Depois/11346.jpeg', N'Disposable pants for drivers', NULL, N'Allow drivers to enter the plant ', N'Give drivers the ability to enter the plant', 0, NULL, N'Melhorou na parte da segurança, pois temos um local adequado para armazenar os itens de segurança e na parte de ajustes em campo,pois com as ferramentas no malão, pequenos ajustes podem ser feitos em campo', '2026-07-23T00:00:00.000', '2026-07-24T12:00:40.000', N'81009995', NULL, NULL);
INSERT INTO #PVC VALUES (11347, N'388959', N'388959', N'Kit de revestimento de caçamba WE1850', 1, N'Others/Outros', N'Durante a reforma de caçamba preparar o material de revestimento é elevado, consumindo mão de obra da caldeiraria e impossibilitando outras reformas', N'Criar Kit de revestimento para reforma da caçamba', N'10081', N'01 - Imagens/01 - Antes/11347.jpeg', N'O material era confeccionado na caldeiraria, elevando o tempo total de reforma da caçamba', N'01 - Imagens/02 - Depois/11347.jpeg', N'Desenvolvido um kit de revestimento para reforma da caçamba.', NULL, N'Redução no tempo de reforma ', N'agilidade na reforma de componentes', 0, NULL, N'.', '2026-07-23T00:00:00.000', '2026-07-24T12:50:32.000', N'388959', NULL, NULL);
INSERT INTO #PVC VALUES (11348, N'81026906', N'502547', N'Suporte RAC 07', 1, N'Others/Outros', N'Má fixação das proteções RAC 07', N'Melhor fixação das proteções RAC 07', N'10178', N'01 - Imagens/01 - Antes/11348.jpeg', N'As proteções RAC 07 apresentavam fixação inadequada, ocasionando o desprendimento e a queda das grades durante a operação. Essa condição expunha partes móveis do equipamento, aumentando o risco de contato acidental e comprometendo a segurança operacional.', N'01 - Imagens/02 - Depois/11348.jpeg', N'Após a implantação do suporte de fixação, as grades passaram a apresentar maior estabilidade e segurança, eliminando ocorrências de desprendimento durante a operação. Além disso, a solução proporcionou mais agilidade nas atividades de montagem e desmontagem, reduzindo o tempo de intervenção e aumentando a eficiência operacional.', NULL, N'Meta atingida', N'Substituir as demais fixações de toda britagem', 0, NULL, N'Produtividade.
INSERT INTO #PVC VALUES (11349, N'81029574', N'81035347', N'Controle Automatizado de Manutenção da Perfuratriz', NULL, N'Others/Outros', N'O registro das atividades que envolviam a manutenção eram realizados de forma manual e descentralizada, gerando um retrabalho nas buscas de informações e dificultava a analise das principais falhas do equipamento.', N'Automatização dos apontamentos do equipamento PF 6001', N'10171', N'01 - Imagens/01 - Antes/11349.jpeg', N'O registro das manutenções da perfuratriz era realizado de forma manual e descentralizada, dificultando o acompanhamento preciso do tempo gasto nas intervenções e o histórico das correções executadas. Isso gerava retrabalho na busca de informações e dificultava a análise das principais falhas do equipamento.', N'01 - Imagens/02 - Depois/11349.jpeg', N'Foi desenvolvido uma planilha automatizada para a gestão das manutenções da perfuratriz, possibilitando o registro preciso dos tempos de intervenção e das correções executadas. Essa melhoria aumentou o controle das informações, reduziu erros de apontamento e facilitou a análise de falhas recorrentes. Além disso, contribui para a otimização da disponibilidade do equipamento e para o aumento da precisão de indicadores operacionais, como DF (Disponibilidade Física) e UT (Utilização), proporcionando maior confiabilidade na tomada de decisões e no acompanhamento da performance do equipamento.', NULL, N'Sim. A melhoria aumentou o controle das informações reduziu erros de apontamentos. Facilitando a analises de falhas recorrentes. E contribuiu para a otimização da disponibilidade do equipamento.', N'A necessidade de uma padronização e no apontamento das informações', 0, NULL, NULL, '2026-01-01T00:00:00.000', '2026-07-24T13:51:15.000', N'81029574', NULL, NULL);
INSERT INTO #PVC VALUES (11350, N'81046537', N'81063692', N'Grade de Proteção do Para-brisa (Cabine)', 2, N'Others/Outros', N'Durante a inspeção técnica de rotina na Perfuratriz PZ02, foi identificado um desvio crítico na cabine de operação. A grade de proteção frontal do para-brisa, responsável por proteger o operador e o vidro contra projeção de detritos e impactos, encontrava-se fixada de maneira precária utilizando uma corda (amarração paliativa).
INSERT INTO #PVC VALUES (11351, N'81047819', N'81006709', N'Perfuração sem Colapso ', 2, N'Open Pit/Poço aberto', N'Dificuldades na execução da perfuração de pré-corte e dos furos do plano de produção com perfuratrizes de pequeno diâmetro em áreas com elevada percolação de água. A presença de água e forro ocasionava instabilidade dos furos, perda de eficiência operacional, geração de offsets, material agregado ao talude projetado (aumentando o atividade de saneamento, bem como o risco de projeção de material durante à atividade) e risco de não atendimento aos parâmetros de qualidade e profundidade especificados, impactando o desempenho das atividades de perfuração, desmonte.
INSERT INTO #PVC VALUES (11352, N'81046755', N'483391', N'TRACKUP - APP DOS INDICADORES DA SLA - LOGSUP', 1, N'Others/Outros', N'AUSÊNCIA DO CONTROLE E VISIBILIDADE EM TEMPO REAL SOBRE A EXECUÇÃO DO CRONOGRAMA DE COLETAS DA LOGSUP, dificultando a identificação dos desvios, ACOMPANHAMENTOS DOS INDICADORES DA SLA E PRINCIPALMENTE DA ADERE^NCIA DE COLETAS DO SITE SOSSEGO.', N'REDUÇÃO 100%', N'10079', N'01 - Imagens/01 - Antes/11352.jpeg', N'O PROCESSO ERA REALIZADO CON CONTROLES MANUAIS E INFORMAÇÕES DISPERSAS, SEM ACOMPANHAMENTO EM TEMPO REAL DA EXECUÇÃO DO CRONOGRAMA. A IDENTIFICAÇÃO DOS DESVIOS, PONTOS NÃO REALIZADOS, OCORRIA DE FORMA TARDIA, DIFICULTADO A TOMADA DE DECIÇÃO E ATUAÇÃO IMEDIATA NAS TRATAIVAS.', N'01 - Imagens/02 - Depois/11352.jpeg', N'IMPLANTAÇÃO DO APP TRACKUP PARA ACOMPANHAMENTO EM TEMPO REAL DA EXECUÇÃO DO CRONOGRAMA, MONITORAMENTO DOS DESVIOS E GESTÃO DOS INDICADORES DE ADERÊNCIA E DOS DEMAIS INDICADORES DO SLA.', N'https://trackup.logsupsystem.com.br/login', N'SIM, A IMPLANTAÇÃO DO TRACKUP SOLUIONOU A FALTA DE VISIBILIDADE E CONTROLE, PERMITINDO ACOMPANHAMENTO EM TEMPO REAL DA ADERÊNCIA DE COLETAS', N'O APP realiza acompanhamento em tempo real da aderência de coletas tratando os desvios de forma imediataa', 0, NULL, N'NA', '2026-04-06T00:00:00.000', '2026-07-24T14:36:08.000', N'81046755', NULL, NULL);
INSERT INTO #PVC VALUES (11353, N'81056094', N'201795', N'Automate the renaming of 16,000 PDF files and generate a record of the new file names.', NULL, N'Others/Outros', N'Renaming 16,000 PDF files manually was extremely time-consuming and had already taken weeks of effort.', N'Automate the renaming of 16,000 PDF files and generate a record of the new file names.', N'10100', N'01 - Imagens/01 - Antes/11353.jpeg', N'Files had to be renamed individually, creating a significant workload and risk of human error.', N'01 - Imagens/02 - Depois/11353.jpeg', N'Developed a PowerShell script to automatically rename PDF files and export the updated names to Excel.', NULL, N'Automation replaced weeks of manual effort and completed the task accurately in a fraction of the time.', N'Simple automation can eliminate repetitive tasks and deliver significant time savings.', 0, NULL, N'Instalar um suporte para a mangueira ficar guardado de forma organizada', '2026-07-17T00:00:00.000', '2026-07-24T14:38:30.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11354, N'499365', N'499365', N'Informativo da Programação Semana do Diálogo de Saúde e Segurança.', 2, N'Others/Outros', N'A ausência de preparação adequada dos materiais compromete a qualidade das entregas, a credibilidade das informações e o impacto das apresentações junto ao time de gestão de capital.', N'Promover a conscientização e o engajamento do time de FP&A da Gestão de Capital nas práticas de Saúde e Segurança, fortalecendo a cultura de prevenção, cuidado com as pessoas e operação segura no dia a dia.', N'10367', N'01 - Imagens/01 - Antes/11354.jpeg', N'Não havia um padrão estruturado para a preparação dos materiais, resultando em apresentações com qualidade inconsistente e menor efetividade na comunicação das mensagens-chave.', N'01 - Imagens/02 - Depois/11354.jpeg', N'Implementação de uma rotina estruturada de informativo para preparação e revisão dos materiais, garantindo maior qualidade, consistência das mensagens e apresentações mais assertivas para o time e liderança.', NULL, N'Saímos de um cenário de preparação reativa e qualidade variável para um processo estruturado, garantindo entregas consistentes, profissionais e de alto impacto.', N'A qualidade da entrega é definida antes da apresentação. Preparação antecipada, revisão estruturada e alinhamento das mensagens são fatores essenciais para gerar credibilidade, engajamento e decisões mais assertivas.', 0, NULL, N'Ter um ponto disponível  para atuar com ferramentas pneumaticas e limpeza de peças na caldeiraria.', '2026-07-03T00:00:00.000', '2026-07-24T15:03:54.000', N'499365', NULL, NULL);
INSERT INTO #PVC VALUES (11355, N'81041923', N'81041923', N'Raspador HOSCH', 2, N'Open Pit/Poço aberto', N'O raspador de correia da Martin instalado no transportador (TR-2009-06) apresenta desempenho insatisfatório na remoção do material aderido à correia, permitindo elevado retorno de material . Essa condição resulta em acúmulo de material na estrutura do transportador, aumento da necessidade de limpeza, maior desgaste dos componentes, risco à segurança operacional e aumento dos custos de manutenção. Além disso, a frequência de ajustes e substituições compromete a disponibilidade do equipamento e a eficiência do processo.', N'Eliminar  material fugitivo no retorno da correia', N'10031', N'01 - Imagens/01 - Antes/11355.jpeg', N'O raspador de correia da Martin instalado no transportador (TR-2009-06) apresenta desempenho insatisfatório na remoção do material aderido à correia, permitindo elevado retorno de material . Essa condição resulta em acúmulo de material na estrutura do transportador, aumento da necessidade de limpeza, maior desgaste dos componentes, risco à segurança operacional e aumento dos custos de manutenção. Além disso, a frequência de ajustes e substituições compromete a disponibilidade do equipamento e a eficiência do processo.', N'01 - Imagens/02 - Depois/11355.jpeg', N'Os principais benefícios do raspador Hosch em comparação com raspadores convencionais incluem:
INSERT INTO #PVC VALUES (11356, N'81062073', N'81062073', N'Novas Aplicações de Ensaios VLF, Tangente Delta (Tan δ) e Tensão Aplicada', 1, N'Others/Outros', N'A iniciativa visa aumentar a confiabilidade dos ativos elétricos por meio da adoção de diagnóstico preditivo em cabos de alta tensão. O método atual, baseado apenas em Megger, identifica falhas já avançadas, sem detectar degradação progressiva da isolação. A falha do alimentador AL-01 em 10/11/2025, com 8,73 horas de indisponibilidade e impactos operacionais, evidenciou essa limitação.
INSERT INTO #PVC VALUES (11357, N'81058050', N'81058050', N'Automatização dos Moto Bombas.', 2, N'Others/Outros', N'   Durante a operação dos caminhões-pipa, os operadores precisavam descer da cabine para realizar o acionamento manual da bomba de abastecimento, o que aumentava o tempo da atividade e expunha os empregados a riscos desnecessários. Como a operação ocorre em área próxima à mata, havia exposição a animais peçonhentos, selvagens, insetos, terrenos irregulares, condições climáticas adversas e outros equipamentos em movimento. ', N'Redução de Cenário de Risco.', N'10188', N'01 - Imagens/01 - Antes/11357.jpeg', N'   Durante a operação dos caminhões pipa, os operadores precisavam descer da cabine para realizar o acionamento manual da bomba de abastecimento, o que aumentava o tempo da atividade e expunha os empregados a riscos desnecessários. Como a operação ocorre em área próxima à mata, havia exposição a animais peçonhentos, selvagens, insetos, terrenos irregulares, condições climáticas adversas e outros equipamentos em movimento. ', N'01 - Imagens/02 - Depois/11357.jpeg', N'Para eliminar essa condição, foi implantado um sistema de acionamento da bomba por controle remoto via rádio, permitindo a operação diretamente da cabine. A melhoria reduziu significativamente a exposição aos riscos, aumentou a segurança dos operadores e proporcionou maior agilidade e eficiência no processo de abastecimento. GM6095', NULL, N'Sim , através da implantação do sistema automático de funcionamento dos moto bombas.', N'Redução de cenário de risco.', 0, NULL, N'performance, produtividade, segurança, tempo;
INSERT INTO #PVC VALUES (11358, N'81054319', N'81054319', N'Temporary Step Stool Installation to Improve System 200 HMI Accessibility', 2, N'Others/Outros', N'The HMI screen has a scratched, hazy area in the center where alarm and error messages are displayed. Shorter technicians were unable to clearly read critical piece of information from the angle they are standing from, while taller technicians were not affected. Although a screen replacement has been initiated, it requires procurement and is not an immediate repair since it is categorized as a non-urgent maintenance work.', N'Provide all technicians with equal and safe access to critical HMI information while the damaged HMI screen awaits replacement.', N'10191', N'01 - Imagens/01 - Antes/11358.jpeg', N'Shorter technicians struggled to read alarm and error messages on the damaged HMI screen with hazy patch in the center of the screen, reducing response efficiency and increasing the potential for delayed response.', N'01 - Imagens/02 - Depois/11358.jpeg', N'A step stool enables technicians of different heights to comfortably view the HMI, ensuring critical information can be read clearly until the new screen is installed.
INSERT INTO #PVC VALUES (11359, N'81006946', N'81048624', N'MALÃO DO IMPLEMENTO ', 1, N'No Replication/Sem replicação', N'Dificuldade no armazenamento de material, como calços, cones e ferramentas do uso dos operadores ', N'Criar um malão para armazenar material no equipamento ', N'10139', N'01 - Imagens/01 - Antes/11359.jpeg', N'Não havia um malão grande o suficiente para armazenar os epc ''s,e ferramentas do uso diário dos operadores. ', N'01 - Imagens/02 - Depois/11359.jpeg', N'Com a criação do malão de ferramentas, melhorou muito a condição de transporte dos itens de segurança  e ferramentas,  dando uma melhor condição aos colaboradores. ', NULL, N'Sim!se mantermos a disciplina e organização do malão, será eficaz ', N'Ter um local definido e organizado, traz mais segurança  e agilidade ao seu dia a dia de trabalho ', 0, NULL, N'performance, produtividade, segurança, tempo;
INSERT INTO #PVC VALUES (11360, N'81029931', N'81052327', N'PADRONIZAÇÃO VISUAL PANELA-SACO DE AMOSTRA', 1, N'No Replication/Sem replicação', N'1. Plástico sobre o quarteador  
INSERT INTO #PVC VALUES (11361, N'81057418', N'81057418', N'Identificação de amostras com análises pendentes ', 3, N'Open Pit/Poço aberto', N'As amostras armazenadas na prateleira não possuíam identificação visual indicando análises pendentes. Para verificar o status de cada amostra, era necessário acessar o sistema e realizar consultas individuais', N'Maior agilidade na identificação de amostras pendentes.', N'10129', N'01 - Imagens/01 - Antes/11361.jpeg', N'Necessidade de acessar o sistema para identificar análises pendentes de cada amostra.', N'01 - Imagens/02 - Depois/11361.jpeg', N'Identificação imediata das amostras pendentes por meio da sinalização visual na prateleira, sem necessidade de consulta prévia ao sistema.', NULL, N'Redução do tempo gasto em consultas ao sistema.
INSERT INTO #PVC VALUES (11362, N'81046149', N'81046149', N'Adequação de Guarda-corpo', 2, N'Others/Outros', N'Guarda-corpo danificado e/ou fora do padrão, oferecendo risco de queda e comprometendo a segurança dos colaboradores durante o acesso e a circulação.', N'Eliminar o risco de queda, adequar o guarda-corpo às normas de segurança e garantir um ambiente de trabalho seguro para todos.', N'10362', N'01 - Imagens/01 - Antes/11362.jpeg', N'Guarda-corpo danificado e/ou fora do padrão, oferecendo risco de queda e comprometendo a segurança dos colaboradores durante o acesso e a circulação.', N'01 - Imagens/02 - Depois/11362.jpeg', N'Guarda-corpo substituído ou reparado, atendendo aos requisitos de segurança, proporcionando proteção coletiva e circulação segura.
INSERT INTO #PVC VALUES (11363, N'81038902', N'81038902', N'dispositivo recuperador de corpos moedores', 3, N'Others/Outros', N'local=TR2313SA-01 que e alimentada pelo AL-2313SA-01 nessa transferência sempre acontece sobrecarga no transportador e cai muitos corpos moedores no piso causado um aspecto desorganizado e perigoso podendo causar queda de mesmo nível sem falar do desperdício muita das vezes era descartado os corpos moedores    ', N'mudar aspecto físico da área e reduzir gasto com insumo  ', N'10031', N'01 - Imagens/01 - Antes/11363.jpeg', N'LOCAL=TR-2313SA-01 retorno alimentação da TR nesse ponto do transportado sempre acontece de transborda e cair muitos corpos moedores no piso deixando o local em situação de risco podendo causar queda de mesmo nível, e mostrando um aspecto desorganizado da área sem falar num grande desperdício de insumo dos moinhos     ', N'01 - Imagens/02 - Depois/11363.jpeg', N'LOCAL-TR-2313SA-01foi fabricado e instalado um dispositivo para recuperar os corpos moedores, devolvendo manualmente os corpos moedores  com o transportador em operação  sem correr nenhum risco resultado em um local limpo organizado e seguro livre de acidentes e sem desperdício dos corpos moedores ', NULL, N'sim foi fabricado e instalado um dispositivo para devolver os corpos moedores de imediato com o transportador em operação sem correr risco de acidente  ', N'sempre fazer do nosso local de trabalho um lugar mais seguro ', 0, NULL, N'Eliminar os riscos identificados no mirante, adequar a estrutura conforme os padrões de segurança, melhorar a organização da área e aumentar a segurança e a eficiência operacional.', '2026-07-06T00:00:00.000', '2026-07-26T01:03:49.000', N'81038902', NULL, NULL);
INSERT INTO #PVC VALUES (11364, N'81046149', N'81040359', N'Adequação Barreira física ', 2, N'Others/Outros', N'Barreira física danificada, comprometendo a proteção da área.
INSERT INTO #PVC VALUES (11365, N'1014906', N'1014906', N'WLN R3 Level Indicator Safety Barrier', 2, N'Others/Outros', N'Unable to safely access level indicator on WLN R3 for cleaning. To access properly a step stool is required which brings you  ', N'Allow safe access to WLN R3 level inidcator.', N'0', N'01 - Imagens/01 - Antes/11365.jpeg', N'WLN R3 level indicator requires a step ladder to access it properly. ', N'01 - Imagens/02 - Depois/11365.jpeg', N'Scaffold barrier erected to allow safe access to WLN R3 Level Indicator for cleaning.', NULL, N'Yes, can now safely access WLN R3 Level Indicator.', N'Safe Access', 0, NULL, N'A participação da equipe na identificação dos riscos evidenciou que ações simples e de baixo custo podem gerar grandes ganhos em segurança, confiabilidade e padronização das áreas operacionais.', '2026-07-25T00:00:00.000', '2026-07-26T10:09:05.000', N'1014906', NULL, NULL);
INSERT INTO #PVC VALUES (11366, N'81049566', N'81012442', N'Suporte mangueira ', 3, N'Crusher/Britadeira', N'Ausência de um suporte para a mangueira O que levava a mangueira a ficar caída no chão Com o risco de pessoas tropeçarem.', N'fabricar um suporte para guardar a mangueira de forma org', N'10362', N'01 - Imagens/01 - Antes/11366.jpeg', N'Ausência de um suporte para a mangueira Utilizado na limpeza da caldeiraria do revezamento.', N'01 - Imagens/02 - Depois/11366.jpeg', N'Após a instalação de um novo ponto de água e ar Na oficina da cadeira foi fabricado e instalado um suporte para a mangueira.', NULL, N'Foi fabricado um suporte armazenado da mangueira de forma segura', N'Ambiente mais organizado e seguro', 0, NULL, N'A implantação da iluminação de emergência evidenciou que ações preventivas fortalecem a cultura de segurança, asseguram melhores condições de resposta em emergências e contribuem para a proteção das pessoas e do patrimônio.', '2026-07-25T00:00:00.000', '2026-07-26T10:31:56.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11367, N'81049566', N'81012442', N'Linha de ar comprimido ', 3, N'Crusher/Britadeira', N'Ausência de uma linha de ar comprimido para a utilização de ferramentas e limpeza de equipamentos na caldeiraria dos revezamento.', N'instalar ponto de ar comprimido na caldeiraria', N'10362', N'01 - Imagens/01 - Antes/11367.jpeg', N'Ausência de uma linha de ar comprimido na caldeiraria do revezamento', N'01 - Imagens/02 - Depois/11367.jpeg', N'Instalado linha de ar comprimida Vindo da moagem para alimentar a caldeiraria do revezamento.', NULL, N'Instalado linha de ar comprimido na caldeiraria do revezamento.', N'melhoria no dia a dia ', 0, NULL, N'Padronizar o armazenamento dos utensílios de limpeza por meio da instalação de um suporte específico, eliminando materiais apoiados no piso, aumentando a segurança, preservando a vida útil dos equipamentos, reduzindo o tempo de localização e guarda dos utensílios e fortalecendo a aplicação da metodologia 5S, com potencial de replicação em outras áreas.', '2026-07-25T00:00:00.000', '2026-07-26T10:45:30.000', N'81049566', NULL, NULL);
INSERT INTO #PVC VALUES (11368, N'1008687', N'1008687', N'GUL Cement Usage', 1, N'Underground/Subterrâneo', N'Remove GUL Cement from inventory', N'Remove all inventory of GUL Cement from site at Minimum Cost ', N'10292', N'01 - Imagens/01 - Antes/11368.jpeg', N'GUL Cement was procured and transported to Voisey’s Bay for use in the Cemented Rock Fill (CRF) process. Following further evaluation, it was determined that CRF would not be adopted as a standard operational practice. As a result, approximately 5,100 bags of GUL Cement remain on site with no identified operational use.
INSERT INTO #PVC VALUES (11369, N'1008687', N'1008687', N'Warehouse Workspace Development ', 3, N'Others/Outros', N'Improve the functionality and ergonomics of the Warehouse Receiving area to enhance safety, efficiency, and workflow', N'Improve Warehouse Receiving ', N'10292', N'01 - Imagens/01 - Antes/11369.jpeg', N'The Warehouse Receiving workstation had become cluttered and was not designed to effectively support the daily receiving process. Materials, paperwork, and equipment were stored in a manner that limited available workspace and created inefficiencies during receiving activities. The layout was not ergonomic, requiring employees to perform unnecessary reaching, bending, and movement to complete routine tasks.
INSERT INTO #PVC VALUES (11370, N'81050572', N'81050572', N'PADRONIZAÇÃO IDENTIFICAÇÃO DAS CÉLULAS BANCO DE BATERIAS', 1, N'Others/Outros', N'Banco de baterias não possuía identificação clara e padronizada das células, dificultando inspeções, medições, registros de manutenção e a localização de falhas.
INSERT INTO #PVC VALUES (11371, N'488890', N'544624', N'Sem condição', 1, N'Projects/Projetos', N'Durante a operação do circuito em BY PASS, com o moinho SAG parado, foi identificado um intertravamento na lógica de controle que bloqueava a partida dos alimentadores 2301 AL 01/02 sempre que o fluxo era direcionado para a 2301 TC 08. ', N'Alcançada', N'10054', N'01 - Imagens/01 - Antes/11371.jpeg', N'Durante a operação do circuito em BY PASS, com o moinho SAG parado, foi identificado um intertravamento na lógica de controle que bloqueava a partida dos alimentadores 2301 AL 01/02 sempre que o fluxo era direcionado para a 2301 TC 08. Como consequência, a operação normal do circuito de rebritagem ficava impossibilitada. Diante desse cenário, foi necessário a revisão da lógica de controle para eliminar a restrição operacional identificada.', N'01 - Imagens/02 - Depois/11371.jpeg', N'Após a implantação da melhoria na lógica de controle, foi eliminada a restrição operacional que impedia a partida dos alimentadores 2301 AL 01/02 durante a operação em BY PASS com o moinho SAG parado. A adequação da lógica restabeleceu a flexibilidade operacional do circuito, aumentou a confiabilidade do processo e eliminou a necessidade de intervenções operacionais.', NULL, N'O resultado obtido atendeu integralmente à meta inicial, eliminando o intertravamento indevido e garantindo a operação do circuito conforme a estratégia definida.', N'Validar a lógica de controle em todos os modos de operação evita restrições operacionais.', 0, NULL, N'Processo mais rápido, padronizado e confiável, com ganho de produtividade na análise das pendências de capitalização', '2026-07-19T00:00:00.000', '2026-07-26T14:05:38.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11372, N'81050572', N'81050572', N'Implementação da Rastreabilidade das Células dos Bancos de Baterias através da Padronização da Identificação', 1, N'Others/Outros', N'Os bancos de baterias das subestações não possuíam um padrão de identificação das células, dificultando a rastreabilidade dos componentes durante inspeções, medições e atividades de manutenção. A ausência de identificação clara aumentava o tempo de localização das células, elevava o risco de erros nos registros e comprometia a confiabilidade das informações utilizadas na tomada de decisão e na gestão dos ativos.', N'Padronizar a identificação de 100% das células dos bancos de baterias por meio de etiquetas e nomenclaturas definidas, garantindo rápida localização durante inspeções, medições e manutenções. A iniciativa visa eliminar erros de identificação, aumentar a confiabilidade dos registros, reduzir o tempo de execução das atividades e fortalecer a segurança operacional e a rastreabilidade dos ativos.', N'10294', N'01 - Imagens/01 - Antes/11372.jpeg', N'Situação Inicial
INSERT INTO #PVC VALUES (11373, N'81030117', N'523439', N'SUPORTE PARA CABOS DO GERADOR', 1, N'Others/Outros', N'Na mesa de Perfuração o alojamento do defletor de pó sem proteção quando o mastro está horizontal, com condição de um acidente com pessoas', N'MITIGAR RISCOS', N'10324', N'01 - Imagens/01 - Antes/11373.jpeg', N'Na mesa de Perfuração o alojamento do defletor de pó sem proteção quando o mastro está horizontal, com condição de um acidente com pessoas', N'01 - Imagens/02 - Depois/11373.jpeg', N'Foi confeccionado uma proteção e eliminando o risco de acidentes', NULL, N'Foi confeccionado uma proteção e eliminando o risco de acidentes.', N'MAIS SEGURANÇA', 0, NULL, N'Reduzir o risco de exposição dos operadores a produtos químicos em caso de rompimento da mangueira de dosagem, evitando respingos durante a operação. Proteger os componentes do sistema contra danos mecânicos, aumentar a segurança operacional, a confiabilidade do processo e reduzir a necessidade de manutenções corretivas.', '2026-07-19T00:00:00.000', '2026-07-26T15:16:29.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (11374, N'544624', N'81047035', N'Roda pé seguro', 3, N'No Replication/Sem replicação', N'Material de limpeza caindo diretamente para dentro do galpão de concentrado.', N'Eliminar queda de material', N'10054', N'01 - Imagens/01 - Antes/11374.jpeg', N'Rodapé com fragilidade na contenção de materiais proveniente de limpeza do piso ou manutenção. 
INSERT INTO #PVC VALUES (11375, N'488890', N'488890', N'Se alarmou olhe', 1, N'Projects/Projetos', N'Sempre que as temperaturas do sistema de refrigeração do moinho SAG se elevavam, não havia um alarme no sistema de controle que permitisse antecipar uma possível parada do equipamento por alta temperatura do sistema de refrigeração ou do cicloconversor.', N'Antecipar equipe para verificação da elevação das temperaturas sistema de refrigeração moinho SAG.', N'10054', N'01 - Imagens/01 - Antes/11375.jpeg', N'Antes da implantação da melhoria, não havia um alarme no sistema de controle para alertar antecipadamente a elevação da temperatura do sistema de refrigeração do moinho SAG e do cicloconversor. Como consequência, a operação não dispunha de um aviso prévio para atuar preventivamente, aumentando o risco de paradas não programadas por atuação das proteções de alta temperatura.', N'01 - Imagens/02 - Depois/11375.jpeg', N'Após a implementação da melhoria, foi criado um alarme no sistema de controle para monitorar a elevação da temperatura do sistema de refrigeração do moinho SAG e do cicloconversor. Essa funcionalidade passou a alertar antecipadamente a operação sobre condições anormais de temperatura, permitindo a atuação preventiva antes do acionamento das proteções do equipamento, reduzindo o risco de paradas não programadas e aumentando a confiabilidade operacional do processo.', NULL, N'Ausência de alarme preventivo para alta temperatura do sistema de refrigeração do moinho SAG e do cicloconversor, solucionada com a implementação de alarme no sistema de controle.', N'Alarmes preventivos aumentam a confiabilidade operacional.', 324, 3, N'Mitigação de riscos ergonômicos na operação de aperto e desaperto de parafusos nas operações de instalação e remoção de pneus.', '2026-07-25T00:00:00.000', '2026-07-26T18:05:55.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11376, N'81061781', N'523252', N'Adequação do mirante do pátio mirante', 1, N'Projects/Projetos', N'O mirante do pátio apresentava condições inadequadas de utilização, com necessidade de melhorias na estrutura, organização e sinalização, gerando riscos de acidentes, dificuldade de acesso e comprometendo a segurança operacional.', N'Adequar o mirante do pátio, promovendo maior segurança, organização e padronização do ambiente, eliminando riscos aos colaboradores e melhorando a utilização da área.', N'10144', N'01 - Imagens/01 - Antes/11376.jpeg', N'* Estrutura do mirante sem adequação completa.
INSERT INTO #PVC VALUES (11377, N'81061781', N'523252', N'Adequação de acesso de veiculo a tenda de perfuratriz', 2, N'Projects/Projetos', N'O acesso de veículos à tenda da perfuratriz apresentava condições inadequadas, dificultando a circulação e as manobras, aumentando o risco de incidentes, danos aos equipamentos e atrasos nas atividades operacionais.', N'Adequar o acesso de veículos à tenda da perfuratriz, garantindo segurança na circulação, melhor organização da área e maior eficiência nas operações.', N'10144', N'01 - Imagens/01 - Antes/11377.jpeg', N'* Acesso sem padronização.
INSERT INTO #PVC VALUES (11378, N'81061781', N'81061781', N'Instalação de antiderrapante na escada do mirante para prevenir risco de queda', 2, N'Others/Outros', N'A escada do mirante não possuía superfície antiderrapante, tornando o acesso inseguro, principalmente em condições de chuva ou umidade, aumentando o risco de acidentes.', N'Instalar material antiderrapante na escada do mirante para aumentar a segurança dos colaboradores, reduzindo o risco de escorregões e quedas durante o acesso.', N'10144', N'01 - Imagens/01 - Antes/11378.jpeg', N'* Escada sem revestimento antiderrapante.
INSERT INTO #PVC VALUES (11379, N'81061781', N'81061781', N'Instalação de luz de emergência na sala da Komatsu', 2, N'Projects/Projetos', N'A sala da Komatsu não possuía iluminação de emergência. Em caso de interrupção do fornecimento de energia elétrica, o ambiente ficava totalmente sem iluminação, dificultando a evacuação, aumentando o risco de acidentes e comprometendo a segurança dos colaboradores.', N'Instalar iluminação de emergência na sala da Komatsu para garantir a segurança dos colaboradores durante situações de falta de energia, assegurando uma evacuação segura e o atendimento aos requisitos de segurança.', N'10144', N'01 - Imagens/01 - Antes/11379.jpeg', N'* Ausência de luz de emergência na sala.
INSERT INTO #PVC VALUES (11380, N'479995', N'81034962', N'Implantação de suporte para organização e padronização dos utensílios de limpeza (5S)', 3, N'Others/Outros', N'Os utensílios de limpeza eram armazenados de forma inadequada, apoiados no chão e sem local definido, dificultando a organização, favorecendo danos aos equipamentos, aumentando o tempo de procura e comprometendo a aplicação do programa 5S.
INSERT INTO #PVC VALUES (11381, N'524052', N'524052', N'monitoramento de FPS de motoniveladoras', 1, N'Others/Outros', N'não há uma forma rápida e visual de acompanhar o desgaste de bordas de lâminas das motoniveladoras. Para avaliação de condição ou consumo, depende de relatórios de inspeção.', N'projetar consumo de bordas de acordo com desgaste real', N'10154', N'01 - Imagens/01 - Antes/11381.jpeg', N'A verificação da condição de bordas das lâminas de motoniveladoras dependia de pesquisa em base de dados de paradas ou solicitação de relatório fotográfico do time de inspeção', N'01 - Imagens/02 - Depois/11381.jpeg', N' Gerado um painel dashboard em Power Bi que é alimentado pelo inspetor, dessa forma é possível verificar a condição atual da última inspeção e o histórico de datas passadas', NULL, N'resultado positivo pois com o acompanhamento, pode-se projetar consumo mensal e anual', N'sempre há possibilidade de melhoria', 0, NULL, N'FOI CRIADO UMA ARTE E IMPRESSA EM MATERIAL IMANTADO. ASSIM AS ATUALIZAÇÕES FICAM FLUIDAS E DINAMICAS ', '2026-07-24T00:00:00.000', '2026-07-27T10:36:40.000', N'524052', NULL, NULL);
INSERT INTO #PVC VALUES (11382, N'200236', N'200236', N'CoPilot Assistance with PI Vision', NULL, N'No Replication/Sem replicação', N'PI Vision has a logic language for use in calculations.  The language syntax is not readily available to users.  A question or submission to PI Team can take a significant time and is often avoided.', N'PI Vision programming', N'10190', N'01 - Imagens/01 - Antes/11382.jpeg', N'PI Vision logic syntax is not readily available to users.  PI Team does not have the resource to provide very quick responses to questions regarding logic syntax. ', N'01 - Imagens/02 - Depois/11382.jpeg', N'CoPilot was tested for knowledge of PI Vision logic syntax.  CoPilot is able to provide logic syntax for various scenarios.  It is able to write logic should you require it.  It will also check your own logic for errors.  It is not perfect and does require some back and forth, however the timing within which questions can be answered with respect to PI Vison logic syntax is a fraction of what it was.', NULL, N'Problem is solved.  Waiting is eliminated.', N'AI is becoming very useful in everyday work', 0, NULL, N'A instalação de um guarda‑corpo traz ganhos claros e relevantes para a operação e para a segurança da equipe. O principal benefício é a redução do risco de quedas, garantindo maior proteção aos trabalhadores durante atividades em altura ou em escadas. Além disso, promove conformidade com normas regulamentadoras de segurança, evitando autuações e fortalecendo a cultura preventiva da empresa. ', '2026-06-01T00:00:00.000', '2026-07-27T10:39:34.000', N'200236', NULL, NULL);
INSERT INTO #PVC VALUES (11383, N'81047036', N'81047036', N'Melhoria do Sistema de Ancoragem para Manutenção em Transportadores', 2, N'Others/Outros', N'Durante as atividades de troca de rolos em transportadores, os trabalhadores encontravam dificuldades para localizar e utilizar pontos adequados para conexão dos talabartes dos cinturões de segurança. A ausência de pontos de ancoragem claramente definidos, acessíveis, identificados e tecnicamente validados dificultava a montagem do sistema de proteção contra quedas, aumentava o tempo de preparação da atividade e poderia favorecer o uso de pontos inadequados ou soluções não padronizadas. Essa condição gerava exposição ao risco de queda e impactava a segurança e a eficiência da manutenção.', N'Eliminar as dificuldades e os riscos associados à ausência ou à inadequação de pontos de ancoragem durante as atividades de troca de rolos em transportadores, por meio da avaliação, validação e emissão de documentação técnica pela Engenharia, permitindo o uso seguro e padronizado de pontos específicos da estrutura para instalação de cintas de ancoragem e conexão dos talabartes dos cinturões de segurança.', N'10145', N'01 - Imagens/01 - Antes/11383.jpeg', N'Durante a troca de rolos em transportadores, a atividade demorava muito tempo para ser iniciada, devido a montagem de andaimes, tubo-vida, e os empregados encontravam dificuldades para localizar pontos adequados para conexão dos talabartes dos cinturões de segurança. A ausência de pontos claramente definidos e tecnicamente validados aumentava o tempo de preparação da atividade e poderia favorecer o uso de locais inadequados ou não padronizados, ampliando a exposição ao risco de queda.', N'01 - Imagens/02 - Depois/11383.jpeg', N'Os empregados deixaram de procurar ou avaliar individualmente possíveis locais para conexão dos talabartes. A atividade passou a contar com pontos conhecidos, acessíveis, identificados e respaldados por documentação técnica, tornando a instalação do sistema de proteção contra quedas (cintas de ancoragem) mais segura, rápida e padronizada. Dessa forma, foram eliminadas as improvisações e montagem de tubo-vidas, o que desprendia muito tempo para realização da atividade.', NULL, N'Sim!
INSERT INTO #PVC VALUES (11384, N'81001594', N'81001594', N'Automação da Geração e Consolidação de Relatórios de Pendências de Capitalização', 1, N'Others/Outros', N'A extração de relatórios de pendências de capitalização era feita individualmente por elemento PEP, resultando em um processo manual, repetitivo e de baixa produtividade.', N'Reduzir o esforço operacional na geração de relatórios de pendências de capitalização por meio da automação da extração e consolidação de múltiplos elementos PEPs.', N'10367', N'01 - Imagens/01 - Antes/11384.jpeg', N'A transação do SAP permite gerar o relatório de pendências de capitalização para apenas um elemento PEP por vez. Dessa forma, a extração de informações de múltiplos PEPs exige várias execuções manuais, aumentando o tempo operacional.', N'01 - Imagens/02 - Depois/11384.jpeg', N'Foi desenvolvida uma ferramenta automatizada que permite a geração de relatórios para múltiplos elementos PEP simultaneamente, realizando também a consolidação das informações em um único relatório por projeto. Com isso, o processo tornou-se mais rápido, padronizado e eficiente.', NULL, N'Automatização da geração e consolidação de relatórios de múltiplos elementos PEP, eliminando atividades manuais e reduzindo o tempo de processamento.', N'Automatizar atividades repetitivas é uma das formas mais eficazes de aumentar a produtividade e reduzir desperdícios no processo.', 0, NULL, N'Increased the availability of heat management products on site. ', '2026-06-30T00:00:00.000', '2026-07-27T12:26:57.000', N'81001594', NULL, NULL);
INSERT INTO #PVC VALUES (11385, N'592501', N'592501', N'Controle Caminhões Rodoviários Implementos SLB', 1, N'Others/Outros', N'Ausência de controle integrado da frota de caminhões rodoviários Scania frota leves, contemplando informações completas dos respectivos implementos, gerando uma lacuna crítica na gestão de ativos. ', N'Estabelecer controle da frota dos caminhões implementos possibilitando a consolidação de dados para construção do contrato de reforma dos ativos.   ', N'0', N'01 - Imagens/01 - Antes/11385.jpeg', N'Ausência de controle integrado da frota de caminhões rodoviários Scania frota leves, contemplando informações completas dos respectivos implementos, gerando uma lacuna crítica na gestão de ativos. Tal cenário compromete o planejamento de manutenção, a estratégia de reposição de materiais e a previsibilidade da demanda por recursos, impactando diretamente a confiabilidade dos equipamentos, a disponibilidade operacional e a eficiência dos processos de manutenção.', N'01 - Imagens/02 - Depois/11385.jpeg', N'Controle consolidado e padronizado de todos os caminhões rodoviários Scania frota leves, contemplando informações completas dos respectivos implementos, contribuindo com o planejamento de manutenção, a estratégia de reposição de materiais e a previsibilidade da demanda por recursos, impactando diretamente a confiabilidade dos equipamentos, sendo um embasador técnico para construção de um contrato de reforma dos ativo junto aos fornecedores locais.', N'https://globalvale.sharepoint.com/:f:/r/sites/GESTAODECOMPONENTES-PLANILHA/Shared%20Documents/General/Controle%20Caminh%C3%B5es%20Implementos%20SLB?csf=1&web=1&e=AhRwas', N'Sim', N'Gestão e controle.', 0, NULL, N'Eliminar o contato direto das mãos com o gelo, garantir a utilização da pazinha para retirada do material e fortalecer a cultura de segurança, reduzindo a exposição a acidentes e desvios comportamentais.', '2026-07-27T00:00:00.000', '2026-07-27T13:40:16.000', N'592501', NULL, NULL);
INSERT INTO #PVC VALUES (11386, N'479995', N'81034962', N'Proteção e padronização das mangueiras de dosagem de produtos químicos da ETEO.', 2, N'Others/Outros', N'As mangueiras de dosagem dos produtos químicos Cal, Polímero e Praestol da ETO permaneciam expostas, sem proteção mecânica e sem padronização, ficando suscetíveis a danos, desgaste prematuro, vazamentos e interferências externas. Essa condição comprometia a organização da área, a segurança operacional e a confiabilidade do sistema de dosagem.', N'Proteger e padronizar a passagem das mangueiras de dosagem de cal, polímero e Praestol da ETO, aumentando a segurança operacional, preservando os equipamentos e melhorando a organização da área.', N'10213', N'01 - Imagens/01 - Antes/11386.jpeg', N'As mangueiras de dosagem dos produtos químicos (cal, polímero e Praestol) da ETEO permaneciam expostas, sem proteção mecânica e sem padronização, ficando suscetíveis a impactos, desgaste prematuro, rompimentos e vazamentos. Essa condição aumentava o risco de respingos de produtos químicos sobre os operadores durante a operação e manutenção, comprometendo a segurança das pessoas, a organização da área e a confiabilidade do sistema de dosagem.', N'01 - Imagens/02 - Depois/11386.jpeg', N'Foi instalada uma tubulação de PVC para proteger e organizar a passagem das mangueiras de dosagem dos produtos químicos (cal, polímero e Praestol) da ETEO. A melhoria eliminou a exposição direta das mangueiras a impactos e desgaste mecânico, reduzindo o risco de rompimentos e de respingos de produtos químicos sobre os operadores. Além disso, padronizou a instalação, facilitou as atividades de inspeção e manutenção, aumentou a segurança operacional e elevou a confiabilidade do sistema de dosagem.
INSERT INTO #PVC VALUES (11387, N'594051', N'594051', N'Otimização da Troca dos Braços dos Limpadores D60/D65', 1, N'Others/Outros', N'Durante a elaboração do orçamento de 2027 da Frota de Perfuração PD, foi identificada uma oportunidade de otimização de custos por meio da revisão da estratégia de manutenção dos braços dos limpadores de para-brisa das perfuratrizes D60/D65.
INSERT INTO #PVC VALUES (11388, N'81048243', N'81048243', N'Melhoria Ergonômica nas Operações de Aperto e Desaperto de Parafusos com Chave de Impacto nas remoções e instalações de pneus em equipamentos GP', 2, N'Projects/Projetos', N'Manejo de chaves de impacto em condições específicas as quais são impactantes na ergonomia haja visto o peso da ferramenta e as posições as quais são demandadas pelo mecânico durante as operações de aperto e desaperto de porcas e parafusos nas rodas de equipamentos fora de estrada.', N'Mitigar situações ergonômicas durante as operações de Remoção e Instalação de Pneus em equipamentos de Grande Porte', N'10144', N'01 - Imagens/01 - Antes/11388.jpeg', N'Remoção de Parafusos e porcas com manuseio operacional da chave de impacto em várias posições do pneu-grande esforço físico para mantenimento constante da operação devido ao peso da ferramenta(16kg).', N'01 - Imagens/02 - Depois/11388.jpeg', N'Aplicação de 01 equipamento de apoio na sustentação (sistema tipo gravidade zero(cap 11 à 18kg)) de forma à reduzir o peso da ferramenta durante as operações de movimentação para aperto/desaperto de parafusos.', NULL, N'Situação resolvida conforme premissas base do conceito inicial (GM 4043)', N'Redução de Movimentos e Manipulação de Cargas com auxílio de dispositivos de gravidade zero', 0, NULL, N'segurança ', '2026-07-24T00:00:00.000', '2026-07-27T15:04:47.000', N'81048243', NULL, NULL);
INSERT INTO #PVC VALUES (11389, N'81058966', N'543216', N' Válvula de segurança.', 1, N'Others/Outros', N'Antes os amostradores eram manutenidos apenas em PGU/Parada de linha, por estarem instalados em pontos específicos como o recalque das bombas, alimentação e rejeito da usina, locais que param somente em PGU.', N'Realizar as manutenções em rotina, sem depender de paradas de linha ou PGU.', N'10031', N'01 - Imagens/01 - Antes/11389.jpeg', N'Impossibilidade de  fazer manutenção no equipamento em rotina.
INSERT INTO #PVC VALUES (11390, N'1009878', N'1009878', N'Scan RLS Pump Casing', NULL, N'Refining/Refino', N'The RLS Pump''s casing in 221 has shown signs of failure.  A new casing is over $500k.  Cost is quite high for ordering a spare part', N'Look into alternative suppliers', N'0', N'01 - Imagens/01 - Antes/11390.jpeg', N'Casing is leaking and a spare casing has a long lead time and is over $500k', N'01 - Imagens/02 - Depois/11390.jpeg', N'A third party vendor was contacted who 3D scanned the old casing during the last outage.  They are offering to fabricate a new casing with a better lead time for 1/3 of the cost if we wish to order.', NULL, N'Yes.  Alternative vendor can supply spare parts.', N'3D Scan', 300000, 3, N'Improved user experience, increased visibility of issues, and strengthened communication between users and IT.', '2026-07-26T00:00:00.000', '2026-07-27T15:24:54.000', N'1009878', NULL, NULL);
INSERT INTO #PVC VALUES (11391, N'81058966', N'81058570', N'Adequação e Padronização de Válvula na Linha de Ar Comprimido', 2, N'Others/Outros', N'Durante a execução de manutenção corretiva/preventiva na rede de utilidades (ar comprimido), identificou-se um desvio de SSMA. A válvula existente demandava torque excessivo e o uso de ferramenta improvisada (chave) para acionamento. Esta condição gerava risco crítico de acidente ergonômico e perda de produtividade pelo tempo elevado de manobra.', N'Eliminar 100% o risco ergonômico na operação da válvula e padronizar o ativo, garantindo conformidade com os requisitos de segurança e facilidade operacional (Garantia da Rotina).', N'10031', N'01 - Imagens/01 - Antes/11391.jpeg', N'Ativo operando fora do padrão técnico ideal. Válvula com acionamento travado.', N'01 - Imagens/02 - Depois/11391.jpeg', N'Implementação de melhoria de engenharia através da substituição por uma válvula de gaveta/esfera .', NULL, N'sim, substituição por uma válvula de gaveta/esfera . ', N' O olhar atento do operador na identificação de desvios e a aplicação imediata do conceito de Melhoria Contínua (Kaizen) evitam incidentes e consolidam a cultura de Disciplina Operacional do VPS.Data ', 0, NULL, N'O aplicativo teve 386 registros e 83 relatórios exportados em PDF nos primeiros 27 dias de utilização apenas pela gerência de elétrica e instrumentação (média de ~14 registros dia).
INSERT INTO #PVC VALUES (11392, N'81017062', N'81017062', N'Oil sample points for hoist equipment', 1, N'Underground/Subterrâneo', N'Oil samples were inconsistently labelled resulting in poor data quality', N'Improve data quality of oil samples', N'10012', N'01 - Imagens/01 - Antes/11392.jpeg', N'Over 20 assets for 4 sample points resulting in poor data quality', N'01 - Imagens/02 - Depois/11392.jpeg', N'Each sample point is labelled with QR code to prevent mislabeling. Data quality will be improved going forward.', NULL, N'Goal achieved', N'QR codes', 0, NULL, N'A melhoria evidenciou a importância de considerar ergonomia, segurança e facilidade operacional no projeto, mostrando que ajustes simples podem reduzir riscos, otimizar atividades e aumentar a eficiência.)', '2026-07-23T00:00:00.000', '2026-07-27T15:43:52.000', N'81017062', NULL, NULL);
INSERT INTO #PVC VALUES (11393, N'81042683', N'81055953', N'In-House Rebuild of Critical SLN Sump', 1, N'Refining/Refino', N'A critical process sump pump experienced significant deterioration requiring a complete wet-end and barrel rebuild. The system had no installed redundancy, resulting in the continued use of temporary drop-in submersible pumps to maintain operation and mitigate production risk.
INSERT INTO #PVC VALUES (11394, N'553135', N'553135', N'ORGANOGRAMA DINAMICO ', 1, N'Others/Outros', N'O ORGANOGRAMA ERA FEITO DE FORMA IMPRESSA E COLOCADA NO FMDS, TODAS AS VEZES QUE ACONTECIAM ATUALIZAÇÕES PRECISAVAMOS FAZER TODO O PROCESSO NOVAMENTE. GASTANDO PAPEIS, PLASTICOS E FITAS ', N'TORNAR AS ATUALIZAÇÕES FÁCEIS ', N'10139', N'01 - Imagens/01 - Antes/11394.jpeg', N'O ORGANOGRAMA ERA FEITO DE FORMA IMPRESSA E COLOCADA NO FMDS, TODAS AS VEZES QUE ACONTECIAM ATUALIZAÇÕES PRECISAVAMOS FAZER TODO O PROCESSO NOVAMENTE. GASTANDO PAPEIS, PLASTICOS E FITAS ', N'01 - Imagens/02 - Depois/11394.jpeg', N'FOI CRIADO UMA ARTE E IMPRESSA EM MATERIAL IMANTADO. ASSIM AS ATUALIZAÇÕES FICAM FLUIDAS E DINAMICAS ', NULL, N'FOI CRIADO UMA ARTE E IMPRESSA EM MATERIAL IMANTADO. ASSIM AS ATUALIZAÇÕES FICAM FLUIDAS E DINAMICAS ', N'MELHORIA CONSTANTE ', 0, NULL, N'Reduced calendar creation time from hours to minutes while improving consistency and accuracy.', '2026-07-24T00:00:00.000', '2026-07-27T16:22:07.000', N'553135', NULL, NULL);
INSERT INTO #PVC VALUES (11395, N'81007243', N'81047727', N'Guarda corpo escada', 3, N'Others/Outros', N'A ausência de guarda‑corpo em uma escada do lavador', N'Melhorar segurança nas atividades do lavador', N'10139', N'01 - Imagens/01 - Antes/11395.jpeg', N'A ausência de guarda‑corpo em uma escada ou plataforma representa um risco direto à segurança dos trabalhadores, pois aumenta significativamente a possibilidade de quedas durante a execução das atividades, especialmente em situações de movimentação constante ou transporte de ferramentas. Além disso, gera insegurança operacional, já que a equipe executante trabalha com receio, reduzindo eficiência e foco. Outro problema é a não conformidade com normas regulamentadoras de segurança, como a NR‑18 e NR‑35 no Brasil, o que pode resultar em autuações e penalidades. A falta dessa proteção compromete a confiabilidade das operações, pois qualquer acidente pode causar paralisações inesperadas e custos elevados com manutenção corretiva.', N'01 - Imagens/02 - Depois/11395.jpeg', N'Foi elaborado e instalado um guarda-corpo visando garantir maior proteção durante as atividades executadas pelo time do lavador. A estrutura foi projetada e instalada conforme normas de segurança.', NULL, N'A instalação de um guarda‑corpo traz ganhos claros e relevantes para a operação e para a segurança da equipe. O principal benefício é a redução do risco de quedas, garantindo maior proteção aos trabalhadores durante atividades em altura ou em escadas. Além disso, promove conformidade com normas regulamentadoras de segurança, evitando autuações e fortalecendo a cultura preventiva da empresa. ', N'Segurança', 0, NULL, N'todas as marcas de centrais cobertas.', '2026-07-23T00:00:00.000', '2026-07-27T20:25:21.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11396, N'81007243', N'81047727', N'Suporte para armários ', 3, N'Others/Outros', N'Foi identificado que o armário permanece em contato direto com o canhão que lança água e sabão com frequência, situação que pode comprometer tanto a integridade do ativo quanto a segurança das atividades realizadas no local. O contato constante com água e sabão pode acelerar o desgaste do material do armário.', N'Proteção dos armários ', N'10139', N'01 - Imagens/01 - Antes/11396.jpeg', N'Foi identificado que o armário permanece em contato direto com o canhão que lança água e sabão com frequência, situação que pode comprometer tanto a integridade do ativo quanto a segurança das atividades realizadas no local. O contato constante com água e sabão pode acelerar o desgaste do material do armário.', N'01 - Imagens/02 - Depois/11396.jpeg', N'Foi identificado que o armário permanecia em contato direto com o canhão que lança água e sabão com frequência, situação que comprometia sua conservação e a segurança operacional. Para resolver o problema, a equipe da caldeiraria confeccionou e instalou um suporte adequado, elevando o armário e afastando-o da linha de impacto do jato. Com essa medida, foi possível reduzir significativamente a exposição à umidade e aos produtos químicos, preservar a integridade do armário e dos materiais armazenados, além de garantir melhores condições de organização e segurança na área de trabalho.', NULL, N'Sim, com o suporte o armário deixa de ficar em contato direto com o jato de água e sabão lançado, reduzindo a exposição constante à umidade e aos produtos químicos. Isso traz proteção estrutural.', N'Preservação da vida útil dos ativos ', 0, NULL, N'Retenção eficaz de objetos na base da plataforma devido à instalação do rodapé metálico contínuo.', '2026-07-24T00:00:00.000', '2026-07-27T20:35:15.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11397, N'1008687', N'81046822', N'Material Creation - Electrolyte Freezies', 2, N'Concentration/Concentração', N'In Voisey''s Bay getting cooling aids during hot weather is not always easy, with each area using P Card and Spot PO''s to generate mechanisms to bring Squinchers (Electrolyte Freezies) on site for their crews. This creates access air freight and higher costs. ', N'Ensure all working parties have access to items to help with heat stress and dehydration ', N'10292', N'01 - Imagens/01 - Antes/11397.jpeg', N'Prior to improvements, electrolyte replenishers were frequently procured through spot purchase orders and P-Card transactions due to limited inventory planning and inconsistent product availability. This reactive purchasing approach often resulted in urgent air freight shipments to site to prevent stockouts, significantly increasing transportation costs and overall procurement expenses. In addition, fluctuating supplier availability created challenges in securing product when needed, leading to supply uncertainty, increased administrative effort, and reduced cost efficiency within the replenishment process.', N'01 - Imagens/02 - Depois/11397.jpeg', N'A dedicated material code was established for electrolyte replenishers, enabling improved inventory visibility and management within SAP. Min/max inventory levels were defined based on site consumption requirements, and the product was placed under contract to secure consistent supply and pricing. Inventory is now routinely stocked in the warehouse and available through the normal reservation process, eliminating the need for spot purchases, reducing air freight requirements, lowering overall costs, and improving product availability for end users.', NULL, N'Yes solved by creating new stock code and inventory min / max. ', N'Take the initiative to help improve site for everyone', 10000, 3, N'Aumento da confiabilidade do equipamento, maior durabilidade do componente, redução das paradas para manutenção corretiva, agilidade na substituição das peças e melhoria da segurança operacional.', '2026-07-26T00:00:00.000', '2026-07-27T20:39:46.000', N'1008687', NULL, NULL);
INSERT INTO #PVC VALUES (11398, N'81046234', N'81046234', N' Segurança na Retirada de Gelo', 2, N'Others/Outros', N'Durante a retirada de gelo da máquina, foi observado que os empregados utilizavam as próprias mãos para manusear o gelo, gerando exposição a riscos de lesões por frio, cortes e possíveis contaminações. Além disso, não havia uma orientação visual padronizada reforçando a utilização de ferramenta adequada para essa atividade.', N'Eliminar o contato direto das mãos com o gelo durante a retirada do material da máquina, promovendo um processo mais seguro, higiênico e padronizado, reduzindo a exposição a lesões e fortalecendo a cultura de segurança.', N'10099', N'01 - Imagens/01 - Antes/11398.jpeg', N'Durante a retirada de gelo da máquina, alguns empregados realizavam o manuseio diretamente com as mãos, por não haver um reforço visual adequado sobre a utilização da pazinha disponível. Essa prática expunha os empregados ao risco de lesões por contato com superfícies frias, cortes e contaminação do gelo. Além disso, não existia uma padronização clara do processo, favorecendo desvios comportamentais e condições inseguras durante a atividade.', N'01 - Imagens/02 - Depois/11398.jpeg', N'Foi implantada uma comunicação visual de segurança na máquina de gelo, reforçando a proibição do manuseio do gelo com as mãos e orientando a utilização da pazinha apropriada disponível no equipamento. A ferramenta passou a ser mantida em local de fácil acesso e identificação, padronizando o processo de retirada do gelo. A melhoria eliminou o contato direto das mãos com o gelo, reduziu a exposição a riscos de lesões e contaminação, aumentou a conscientização dos empregados sobre o uso correto de ferramentas e fortaleceu a cultura de segurança da área. A ação também possibilita replicação em outras máquinas de gelo da unidade.', NULL, N'O problema foi resolvido através da implantação da comunicação visual e da padronização da utilização da pazinha para retirada do gelo. A melhoria eliminou o manuseio direto do gelo com as mãos, reduziu a exposição ao risco e reforçou a aplicação do princípio "Suas mãos não são ferramentas", contribuindo para um ambiente de trabalho mais seguro.', N'Pequenas melhorias e reforços visuais podem eliminar comportamentos inseguros e reduzir a exposição aos riscos. A disponibilização de ferramentas adequadas e a conscientização dos empregados contribuem para a execução segura das atividades.', 0, NULL, N'Eliminar o risco de contato com a guilhotina da válvula, aumentar a segurança dos colaboradores, prevenir acidentes e garantir melhores condições de operação e manutenção.', '2026-07-27T00:00:00.000', '2026-07-28T00:52:55.000', N'81046234', NULL, NULL);
INSERT INTO #PVC VALUES (11399, N'517558', N'517558', N'IMPLEMENTACAO DE ALARME SONORO NA CAIXA DE FORÇA DO SISTEMA DE INCENDIO DA USINA III', NULL, N'Others/Outros', N'A CAIXA DE FORÇA DO SISTEMA DE ALARME DE INCENDIO POSSUIA APENAS UMA TRANCA QUE FACILITA ABERTURA DE SUA PORTA. POR TODOS ', N'AUMENTAR A PROTEÇAO NA CAIXA DE FORÇA DE INCENDIO ', N'10011', N'01 - Imagens/01 - Antes/11399.jpeg', N'A CAIXA DE FORÇA DO SISTEMA DE ALARME DE INCENDIO POSSUIA APENAS UMA TRANCA QUE FACILITA ABERTURA DE SUA PORTA. POR TODOS', N'01 - Imagens/02 - Depois/11399.jpeg', N' COM A INSTALACAO DE UM ALARME SONORO LIMITA O ACESSO DE PESSOA NAO AUTORIZADA.', NULL, N'SIM', N'MAIS CONTROLE DE ACESSO DE PESSOAS NAO AUTORIZADAS ', 0, NULL, N'Criação de um método único para a execução da limpeza; redução de variabilidade ;Elaboração e Implantação de Instrução de trabalho etc..', '2026-07-27T00:00:00.000', '2026-07-28T03:50:36.000', N'517558', NULL, NULL);
INSERT INTO #PVC VALUES (11400, N'81041919', N'81041919', N'Padronização da posição construtiva dos motores M1 e M2 TR_2020_03 para eliminação de retrabalho em substituições', 2, N'Others/Outros', N'O motor M1 possuía configuração construtiva B3D, diferente do motor M2, que utiliza configuração B3E. Durante as substituições de motores, os motores sobressalentes disponíveis geralmente chegavam com a caixa de ligação posicionada de forma incompatível com a instalação. Essa condição gerava retrabalho frequente, exigindo a inversão da caixa de ligação na oficina antes da liberação do equipamento ou adaptações provisórias dos cabos elétricos em campo durante emergências. Como consequência, ocorria aumento do escopo das atividades de manutenção, maior tempo de indisponibilidade do equipamento, elevação dos custos de mão de obra e aumento da exposição da equipe aos riscos da intervenção.', N'Padronizar a configuração construtiva dos motores M1 e M2, alterando o motor M1 de B3D para B3E, eliminando a necessidade de adequações em oficina e intervenções provisórias em campo, reduzindo o tempo de substituição, aumentando a segurança e melhorando a disponibilidade operacional do equipamento.', N'10178', N'01 - Imagens/01 - Antes/11400.jpeg', N'Os motores M1 e M2 possuíam configurações construtivas diferentes, resultando em incompatibilidade da posição da caixa de ligação nos motores sobressalentes. Isso exigia inversão da caixa na oficina ou adaptações provisórias dos cabos em campo durante as substituições. Como consequência, ocorria retrabalho, aumento do tempo de manutenção, ampliação do escopo das atividades e maior exposição das equipes aos riscos operacionais, impactando a disponibilidade do equipamento.', N'01 - Imagens/02 - Depois/11400.jpeg', N'Os motores M1 e M2 foram padronizados para a configuração B3E, eliminando incompatibilidades na posição da caixa de ligação. A melhoria eliminou retrabalhos em oficina e campo, reduziu o tempo de manutenção e aumentou a disponibilidade dos equipamentos.', NULL, N'A padronização da configuração construtiva para B3E eliminou uma condição crônica de retrabalho durante as substituições de motores. A necessidade de inverter a caixa de ligação em motores de alta tensão exigia desmontagens e ajustes adicionais, aumentando o tempo de manutenção, a exposição dos trabalhadores aos riscos da atividade e o potencial de falhas decorrentes de intervenções desnecessárias. Com a padronização, os motores sobressalentes tornaram-se totalmente intercambiáveis, reduzindo o tempo de reparo, aumentando a confiabilidade do processo e contribuindo para maior disponibilidade operacional dos equipamentos.', N'A padronização de equipamentos similares reduz retrabalhos, simplifica as atividades de manutenção e aumenta a agilidade nas intervenções corretivas e emergenciais.', 0, NULL, N'proteção coletiva robusta que impede acidentes em altura para os colaboradores em tráfego.', '2026-07-17T00:00:00.000', '2026-07-28T09:44:24.000', N'81041919', NULL, NULL);
INSERT INTO #PVC VALUES (11401, N'140178', N'140178', N'Implantação do Minuto da Orientação para Matriz de Bloqueio de Energias da Perfuratriz Sandvik DR416i', 2, N'Others/Outros', N'Foi identificada a necessidade de aumentar a conscientização e a aderência dos empregados e contratados aos procedimentos de bloqueio e etiquetagem (LOTO) da Perfuratriz Sandvik DR416i. As informações da matriz de bloqueio encontram-se disponíveis nos documentos técnicos, porém nem sempre são consultadas antes das intervenções, dificultando a rápida identificação das energias envolvidas, pontos críticos de bloqueio e sequência correta das etapas de energia zero. Essa condição pode aumentar a exposição aos riscos operacionais e comprometer a efetividade dos controles de segurança durante atividades de manutenção, inspeção e diagnóstico.', N'Fortalecer a cultura de bloqueio de energias e segurança operacional nas atividades de manutenção e intervenção da Perfuratriz Sandvik DR416i, por meio da implementação de comunicação visual padronizada (Minuto da Orientação), promovendo maior conscientização dos riscos, redução de desvios de bloqueio, aumento da conformidade com a matriz de energias e prevenção de acidentes relacionados às fontes elétrica, hidráulica, térmica, gravitacional e pneumática.', N'#N/A', N'01 - Imagens/01 - Antes/11401.jpeg', N'Não existia material visual padronizado sobre a Matriz de Bloqueio de Energias da Perfuratriz Sandvik DR416i. As informações estavam disponíveis apenas em documentos técnicos, dificultando a consulta rápida, a identificação das fontes de energia e a orientação das equipes durante atividades de manutenção e inspeção', N'01 - Imagens/02 - Depois/11401.jpeg', N'Foi desenvolvido e implantado o “Minuto da Orientação” da Matriz de Bloqueio de Energias da Perfuratriz Sandvik DR416i, contendo comunicação visual simplificada, identificação das energias críticas, pontos de bloqueio, etapas para energia zero e principais riscos do equipamento. O material passou a ser utilizado em DDS, orientações de campo e atividades de manutenção, facilitando a consulta rápida, aumentando a conscientização das equipes e reforçando a aplicação dos procedimentos de bloqueio e etiquetagem (LOTO). [Cópia de C...Básicos 2 | Excel]
INSERT INTO #PVC VALUES (11402, N'923201', N'979633', N'Controle de substituição elementos filtrantes da Osmose Reversa', 1, N'Others/Outros', N'A falta de controle visual de troca dos elementos filtrantes, impactando na qualidade da água para análise ', N'Garantir a qualidade da água e controle da troca insumos.', N'10129', N'01 - Imagens/01 - Antes/11402.jpeg', N'Ausência de controle visual e rastreabilidade das substituições dos elementos filtrantes da osmose reversa, resultando em dificuldades no gerenciamento dos insumos, risco de trocas fora da periodicidade estabelecida e impacto potencial na qualidade da água utilizada nas análises laboratoriais.', N'01 - Imagens/02 - Depois/11402.jpeg', N'Foi implementado um controle visual de gestão da manutenção junto ao sistema de osmose reversa para registro e rastreabilidade das substituições dos elementos filtrantes. Adicionalmente, foi padronizado um critério de troca preventiva, no qual a cada cinco substituições do filtro PP05 é realizada a renovação programada dos demais filtros, otimizando a vida útil do sistema de filtração e assegurando o fornecimento contínuo de água com especificação adequada para as análises laboratoriais.', NULL, N'O controle visual implementado permitiu padronizar e rastrear as trocas dos elementos filtrantes, melhorando a gestão dos insumos, assegurando a qualidade da água produzida e atendendo à necessidade identificada no cenário inicial.', N'Controle e rastreabilidade dos processos.', 0, NULL, N'Redução de aproximadamente 276 HH/ano dedicadas à análise e correção de fechamentos de massa.
INSERT INTO #PVC VALUES (11403, N'81056094', N'81039915', N'IT Radio Support Channel on ICE Platform', NULL, N'Others/Outros', N'Users had limited options to quickly report issues and obtain IT support while working remotely.', N'Provide real-time IT support through call and text capabilities on Sonim devices.', N'10100', N'01 - Imagens/01 - Antes/11403.jpeg', N'Reporting IT issues could be delayed, impacting response times and user productivity.', N'01 - Imagens/02 - Depois/11403.jpeg', N'Implemented an IT Radio Support Channel, allowing users to call or text IT directly from Sonim phones. Established a dedicated support channel that improved communication and access to IT assistance.', NULL, N'The new support channel provides direct access to IT, improving responsiveness and issue resolution.', N'Accessible communication channels improve user engagement and speed up issue reporting.', 0, NULL, N'SSMARE
INSERT INTO #PVC VALUES (11404, N'81040303', N'81040303', N'Aplicativo de turno', 1, N'Others/Outros', N'Área necessitava de uma aplicação para centralização de informações, gerenciamento e geração de relatórios das ocorrências do turno. O processo acontecia com Reports via WhatsApp em grupos do turno, gerando dificuldade de acompanhamento e com risco de perda de informações importantes.', N'Gerenciamento; Otimização', N'10293', N'01 - Imagens/01 - Antes/11404.jpeg', N'Processo acontecia via WhatsApp com o envio via grupos, de fotos, relatos e pendências.', N'01 - Imagens/02 - Depois/11404.jpeg', N'Desenvolvimento de aplicativo em Power Apps para gestão operacional de ocorrências e pendências do GPVm, permitindo a consulta das paradas registradas no sistema, inclusão de comentários e anexação de evidências diretamente aos apontamentos. A solução possibilita ainda o cadastro de novas ocorrências, abertura e acompanhamento de pendências, proporcionando maior controle, rastreabilidade e gestão das atividades em aberto. Como complemento, o aplicativo oferece a geração automática de relatórios em PDF contendo todas as ocorrências registradas no turno, facilitando o compartilhamento das informações e apoiando a tomada de decisão operacional. ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/90d8e0e8-6a87-4225-a4a7-c077ec7c8a12?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&hint=8e2fad7f-8c9f-4e4b-8bb9-7c250544ce54&sourcetime=1785247482395&source=portal', N'Com o início de utilização do app, houve uma melhora no gerenciamento das informações do turno, permitindo um acompanhamento dos acontecimentos e otimização de tempo com geração de relatórios de turno.', N'Trabalho em equipe; Centralização de informações; Padronização', 500000, 1, N' A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', '2026-07-01T00:00:00.000', '2026-07-28T12:00:28.000', N'81040303', NULL, NULL);
INSERT INTO #PVC VALUES (11405, N'550466', N'544517', N'Rebaixamento estrutural', 2, N'Others/Outros', N'As chaves seccionadoras estavam instaladas em altura muito elevada, dificultando a operação. Essa condição gerava baixa ergonomia, maior esforço físico dos executantes e aumento do risco durante o seccionamento, além de tornar as manobras mais lentas e menos seguras.
INSERT INTO #PVC VALUES (11406, N'81056094', N'81050495', N'Long Harbour IT Workspace Optimization', NULL, N'Others/Outros', N'Limited storage space and workspace layout reduced efficiency and collaboration among technicians.', N'Improve storage capacity and create a more effective workspace for Long Harbour IT technicians.', N'10100', N'01 - Imagens/01 - Antes/11406.jpeg', N'Technicians had limited storage space and were spread apart, making collaboration more difficult.', N'01 - Imagens/02 - Depois/11406.jpeg', N'Created a dedicated IT room with additional storage space and an improved collaborative work area. Established a centralized IT workspace that supports collaboration, organization, and efficiency.', NULL, N'Yes - The new workspace increased storage capacity and created a more collaborative environment for technicians.', N'Well-designed workspaces improve team collaboration, organization, and productivity.', 0, NULL, N'None', '2026-07-01T00:00:00.000', '2026-07-28T12:58:23.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11407, N'81056094', N'81056094', N'Reusable Calendar Generator Script', NULL, N'Others/Outros', N'Creating and formatting calendars manually was time-consuming.', N'Create a reusable tool to generate standardized calendars quickly and consistently on Excel.', N'10100', N'01 - Imagens/01 - Antes/11407.jpeg', N'Calendars were created manually, requiring repetitive effort and increasing the risk of formatting errors.', N'01 - Imagens/02 - Depois/11407.jpeg', N'Developed a reusable Office Script that automatically generates calendars in Excel. This standardized calendar creation and reduced manual effort through a consistent automated process.', NULL, N'The script automated calendar generation, eliminating repetitive manual formatting and setup work.', N'Building configurable tools increases reusability and reduces maintenance effort over time.', 0, NULL, N' A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', '2026-07-27T00:00:00.000', '2026-07-28T13:03:53.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11408, N'471876', N'471876', N'Controle universal para ar condicionado', 1, N'Others/Outros', N'NÃO TEMOS TODOS OS CONTROLES DE AR DO PRÉDIO', N'eliminar ausência de controle', N'10032', N'01 - Imagens/01 - Antes/11408.jpeg', N'No prédio do Laboratório, temos 62 centrais de ar, nem todas temos o controle, isso as vezes atrapalha, devido esta ausência, muitas vezes fica desligado por não ter Controle remoto do equipamento, sala quente, reclamação ambiente inadequado para pessoas e equipamentos sensiveis.', N'01 - Imagens/02 - Depois/11408.jpeg', N'Fizemos uma reflexão do problema e pesquisamos com nossos contratos, adquirimos um controle universal, compatível com 99% das marcas de ar condicionados, melhorando assim o atendimento principalmente para o turno.', NULL, N'alcançado', N'pesquisando a gente consegue resolver.', 0, NULL, N'Definitive information on couplings', '2026-07-24T00:00:00.000', '2026-07-28T13:43:20.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (11409, N'81023633', N'507447', N'Adequação de Segurança e Fechamento de Guarda-Corpo', 2, N'Others/Outros', N'O sistema antigo utilizava uma proteção simples de tubos (roll). Apresentava apenas barras horizontais e grandes vãos abertos.Ferramentas podiam cair facilmente pelas aberturas da estrutura. Não existia uma barreira de contenção totalmente segura para os operadores.', N'Mitigar o risco de queda de ferramentas e materiais, Proteger os operadores contra acidentes em vãos abertos.', N'10064', N'01 - Imagens/01 - Antes/11409.jpeg', N'A proteção antiga era feita com um sistema simples de tubos (roll). Esse modelo contava apenas com barras horizontais e deixava grandes vãos abertos na estrutura. Essa falta de fechamento aumentava o risco de acidentes. Ferramentas podiam cair facilmente e os operadores não tinham uma barreira de contenção totalmente segura.
INSERT INTO #PVC VALUES (11410, N'81058966', N'81036062', N'Fabricação de Carretel em Inox para a CF', 1, N'Others/Outros', N'Durante as inspeções em campo foi identificado que os carretéis utilizados apresentavam desgaste e quebras frequentes, dificultando a reposição imediata durante as manutenções. Essa condição aumentava o tempo de intervenção, comprometia a disponibilidade do equipamento e elevava os riscos para a equipe.', N'Reduzir os riscos durante as atividades de manutenção, proporcionando maior agilidade, segurança e confiabilidade no processo de substituição dos componentes.', N'10031', N'01 - Imagens/01 - Antes/11410.jpeg', N'Os carretéis antigos sofriam desgaste e quebra com frequência, dificultando a reposição imediata e ocasionando atrasos nas atividades de manutenção.', N'01 - Imagens/02 - Depois/11410.jpeg', N'Foi fabricado um novo carretel em aço inox, permitindo um reparo mais rápido, prático e eficiente quando necessário. A melhoria aumentou a durabilidade do componente. ', NULL, N'sim.a fabricação do caritel em inox eliminou as quebras recorrentes do componente, facilitou a reposição durante as manutenções, reduziu o tempo de intervenção e aumentou a segurança dos empregados.', N'A busca contínua por melhorias nos equipamentos contribui para aumentar a segurança, reduzir o tempo de manutenção e garantir maior confiabilidade ao processo.', 0, NULL, N'Redução de aproximadamente 69% no tempo de limpeza (de 8h para 2h30), aumento da produtividade, maior disponibilidade do equipamento para manutenção, melhoria da segurança e redução da exposição dos colaboradores aos reagentes e à umidade.', '2026-07-07T00:00:00.000', '2026-07-28T15:17:54.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11411, N'81058966', N'81010570', N'Substituição de Válvula com Proteção – BO-2017-25', 1, N'Others/Outros', N'Durante inspeções na área, foi identificado que a válvula instalada possuía a guilhotina exposta, sem qualquer proteção, oferecendo risco de acidentes com as mãos e dedos dos colaboradores durante a operação e manutenção do equipamento. Essa condição comprometia a segurança da atividade e exigia uma ação corretiva.', N'Eliminar o risco de acidentes por contato com a guilhotina da válvula, aumentando a segurança dos colaboradores e adequando o equipamento às boas práticas de segurança.', N'10031', N'01 - Imagens/01 - Antes/11411.jpeg', N'A válvula existente possuía a guilhotina exposta, sem proteção, representando risco de prensamento e acidentes durante sua operação.', N'01 - Imagens/02 - Depois/11411.jpeg', N'A válvula antiga foi substituída por um modelo com proteção integrada na guilhotina, eliminando o contato direto com as partes móveis e reduzindo significativamente o risco de acidentes.', NULL, N'sim,A meta foi atingida com a substituição da válvula antiga por um modelo com proteção na guilhotina. A melhoria eliminou a exposição às partes móveis, reduzindo significativamente o risco de acidentes com as mãos e os dedos e tornando a operação mais segura.', N'A identificação e eliminação de condições inseguras contribuem para um ambiente de trabalho mais seguro. A melhoria contínua deve fazer parte da rotina, buscando sempre prevenir acidentes antes que ocorram.', 0, NULL, N'e melhoria das condições de segurança e manutenção.', '2026-07-27T00:00:00.000', '2026-07-28T15:28:46.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11412, N'763789', N'763789', N'Implantação do Método Padronizado de Limpeza Setorizada das Sapatas do Armazém de Carvão.', 1, N'Others/Outros', N'A limpeza das sapatas era realizada sem sequência padronizada, gerando deslocamentos desnecessários e dificuldade para identificar o status de cada posição. Em observações de campo, identificou-se ausência de critérios para definição da sequência de limpeza, diferenças na execução entre equipes e falta de um padrão visual para controle da atividade.', N'Implementar um novo método padronizado de limpeza das sapatas, baseado em setorização e gestão visual, visando aumentar a eficiência operacional, melhorar a organização da atividade e eliminar desperdícios durante a execução da limpeza.', N'10294', N'01 - Imagens/01 - Antes/11412.jpeg', N'A limpeza das sapatas era realizada de forma não padronizada, sem definição de sequência entre os pontos. Os empregados deslocavam-se entre diferentes sapatas conforme a necessidade percebida no momento, gerando movimentações desnecessárias, dificuldade de acompanhamento da atividade e variação na forma de execução entre equipes.
INSERT INTO #PVC VALUES (11413, N'81023633', N'81022716', N'Blindagem contra Quedas', 1, N'Others/Outros', N'Utilização inadequada de postes improvisados de sinalização fincados no solo.
INSERT INTO #PVC VALUES (11414, N'81028405', N'81028405', N'Dimensionamento Técnico do Parque Reserva de Componentes e Periféricos das Perfuratrizes 320XPC', 1, N'No Replication/Sem replicação', N'A frota de perfuratrizes 320XPC não possuía um critério técnico padronizado para dimensionamento do parque reserva de componentes e periféricos críticos. A definição dos estoques era baseada principalmente em percepções operacionais e experiências anteriores, gerando risco de indisponibilidade por falta de peças em eventos de falha e, simultaneamente, possibilidade de capital excessivamente imobilizado em materiais de baixa necessidade.
INSERT INTO #PVC VALUES (11415, N'81015967', N'81015967', N'Implantação de Balança Integrada na Britagem Secundária para Redução dos Ajustes de Reconciliação de Massa', 1, N'Others/Outros', N'Desvios  significativos entre as medições entre a balança da TR 2005-03 , medição na pilha e os dados de fechamento produção, exigindo ajustes mensais elevados para fechamento de massa. Em dezembro, a britagem secundária (ALBRITSECSLB1_2) demandou correção de +115.319 t, correspondente a 5,7% da produção do período, indicando baixa confiabilidade na medição do fluxo de minério e dificultando a gestão operacional e o controle de perdas.', N'Reduzir em 90% os desvios de reconciliação de massa da britagem secundária, aumentando a confiabilidade das medições e reduzindo o percentual de ajuste da produção para patamares inferiores a 1%.', N'10293', N'01 - Imagens/01 - Antes/11415.jpeg', N'Existiam desvios significativos entre as medições da britagem secundária, pilhas de minério e fechamento da produção, gerando baixa confiabilidade dos dados e necessidade de elevados ajustes de massa. Em dezembro, o ajuste atingiu 115.319 t (5,7% da produção), impactando a gestão operacional, a tomada de decisão, o planejamento da usina e a confiabilidade dos estoques de minério.
INSERT INTO #PVC VALUES (11416, N'81046597', N'81046597', N'Ferramenta de Análise de Testes de Oportunidade DBU', NULL, N'Open Pit/Poço aberto', N'A análise dos desvios humanos na DBU era limitada ao item do procedimento descumprido, sem identificação estruturada das causas subjacentes. Isso exigia análise manual das observações dos Testes de Oportunidade, tornando o processo de geração de insights demorado, complexo e pouco eficiente para direcionar ações de confiabilidade humana.', N'Reduzir o tempo de obtenção, análise e apresentação de dados relacionados à confiabilidade humana, por meio de uma ferramenta padronizada de classificação de desvios operacionais e gestão visual.', N'10293', N'01 - Imagens/01 - Antes/11416.jpeg', N'A elaboração de um relatório de confiabilidade humana com base nos registros de 2026 demandaria entre 6 e 8 horas, considerando todo o processo de análise.', N'01 - Imagens/02 - Depois/11416.jpeg', N'A classificação e análise dos 29 desvios registrados em 2026 foram realizadas em aproximadamente 30 minutos, enquanto o relatório passou a ser gerado automaticamente. Redução de 91,7% do tempo de elaboração do relatório.', N'https://app.powerbi.com/groups/me/apps/26f3e8ea-2b35-43eb-b4e0-5b07e8ff22ae/reports/5c4ce671-9ac9-4b16-953f-d1556a080401/c61511ca5aab9b4e5902?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'•	Embora o tempo de análise individual tenha aumentado devido ao maior nível de detalhamento, a padronização da classificação e a automatização da consolidação dos dados resultaram em uma redução significativa do tempo total de elaboração de relatórios e em uma melhoria da qualidade de análise.', N'Uma análise estruturada reduz a subjetividade na avaliação de fatores de desempenho humano; Dados confiáveis são essenciais para análises eficazes de confiabilidade humana; Ferramentas digitais são fundamentais para o gerenciamento da rotina. ', 0, NULL, N'BI COM A VISÃO DA CATEIRA POR ÁREAS E PROCESSOS, DE ONDE É POSSÍVEL TER UMA VISÃO ATUALIZADA DA CARTEIRA PARA REALIZAR ANÁLISES E TOMADAS DE DECISÃO.', '2026-07-24T00:00:00.000', '2026-07-28T22:10:02.000', N'81046597', NULL, NULL);
INSERT INTO #PVC VALUES (11417, N'81029862', N'81029862', N'Implantação de Cadeira para Melhoria Ergonômica no Posto de Trabalho', 2, N'No Replication/Sem replicação', N'O processo de lançamento dos resultados exigia que o colaborador permanecesse em pé por cerca de 30 á 40 minutos, gerando desconforto ergonômico e fadiga nas pernas e costas durante a execução da atividade.', N'Redução de risco ergonômico durante a atividade lançamentos de resultados', N'10198', N'01 - Imagens/01 - Antes/11417.jpeg', N'O lançamento dos resultados era realizado com o colaborador permanecendo em pé durante todo o processo, com duração média de 30 a 40 minutos. Essa condição gerava desgaste físico e risco ergonômico, ocasionando dores nas pernas e na região lombar, comprometendo o conforto e o bem-estar durante a execução da atividade.', N'01 - Imagens/02 - Depois/11417.jpeg', N'Foi disponibilizada uma cadeira para a realização do lançamento dos resultados, permitindo que o colaborador execute a atividade sentado durante todo o processo. A melhoria proporcionou maior conforto ergonômico, reduzindo a sobrecarga física, a fadiga e o risco de dores nas pernas, além de tornar a atividade mais confortável e segura.', NULL, N'Com a instalação de uma cadeira no posto de trabalho, o colaborador passou a realizar o lançamento dos resultados sentado. A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', N'Pequenas adaptações podem eliminar riscos significativos.', 0, NULL, N'Melhoria no controle de acesso à área operacional', '2026-07-28T00:00:00.000', '2026-07-29T04:05:23.000', N'81029862', NULL, NULL);
INSERT INTO #PVC VALUES (11418, N'1008360', N'81036743', N'Flange Identification  ', 2, N'Others/Outros', N'Flange/Pipe didnt have paint on it often posing a problem to strike up against ', N'Paint the object to make sure its seen ', N'0', N'01 - Imagens/01 - Antes/11418.jpeg', N'Flange not painted before ', N'01 - Imagens/02 - Depois/11418.jpeg', N'Flange now painted making it more visible to avoid any strikes ', NULL, N'Yes', N'More visible is safer', 0, NULL, N'melhoria no armazenamento e manuseio dos materiais', '2026-07-28T00:00:00.000', '2026-07-29T04:13:45.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11419, N'1008360', N'81036743', N'Lime Tank Drain Identification ', 2, N'Others/Outros', N'Drain is full of lime and can easily be walked into ', N'Make the drain on the lime tank more visible ', N'0', N'01 - Imagens/01 - Antes/11419.jpeg', N'Drain full of lime making it now harder to see', N'01 - Imagens/02 - Depois/11419.jpeg', N'Drain now painted a bright orange and is more visible ', NULL, N'Yes', N'brighter is better ', 0, NULL, N'Mais agilidade e rapidez para encontrar as baterias carregadas', '2026-07-28T00:00:00.000', '2026-07-29T04:17:15.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11420, N'81029862', N'81029862', N'Implantação de Cadeira para Melhoria Ergonômica no Posto de Trabalho', 2, N'No Replication/Sem replicação', N'O processo de lançamento dos resultados exigia que o colaborador permanecesse em pé por cerca de 30 minutos, gerando desconforto ergonômico e fadiga nas pernas, costas e região cervical durante a execução da atividade.', N'Redução de risco ergonômico durante a atividade lançamentos de resultados', N'10082', N'01 - Imagens/01 - Antes/11420.jpeg', N'O lançamento dos resultados era realizado com o colaborador permanecendo em pé durante todo o processo, com duração média de 30 a 40 minutos. Essa condição gerava desgaste físico e risco ergonômico, ocasionando dores nas pernas e na região lombar, comprometendo o conforto e o bem-estar durante a execução da atividade.', N'01 - Imagens/02 - Depois/11420.jpeg', N'Foi disponibilizada uma cadeira para a realização do lançamento dos resultados, permitindo que o colaborador execute a atividade sentado durante todo o processo. A melhoria proporcionou maior conforto ergonômico, reduzindo a sobrecarga física, a fadiga e o risco de dores nas pernas, além de tornar a atividade mais confortável e segura.', NULL, N'Com a instalação de uma cadeira no posto de trabalho, o colaborador passou a realizar o lançamento dos resultados sentado. A melhoria reduziu o esforço físico e os riscos ergonômicos, proporcionando maior conforto, bem-estar e segurança durante a execução da atividade.', N'Pequenas adaptações podem eliminar riscos significativos.', 0, NULL, N'Permitir ao eletricista sair da zona de risco durante a realização de manobras de fechamento de disjuntores ', '2026-07-28T00:00:00.000', '2026-07-29T05:22:57.000', N'81029862', NULL, NULL);
INSERT INTO #PVC VALUES (11421, N'1009878', N'1009878', N'Lime Vic Fitting Tracker for Pipeline', 1, N'Refining/Refino', N'There are multiple victaulic fittings on the lime pipeline which need to be inspected or replaced.  We do not have any detailed drawings showing where or how many couplings we have', N'Determine Quantity of Vic Fittings and Track Them', N'0', N'01 - Imagens/01 - Antes/11421.jpeg', N'There are no definitive details on where the Victaulic couplings are located and how many we have.', N'01 - Imagens/02 - Depois/11421.jpeg', N'The pipeline was walked and each location was given a number.  A tracker was then developed and the civil drawing was marked up to show the team where the couplings are located.  This also provides a means to determined what was repaired and what is outstanding.', NULL, N'It is now clear how many couplings we have and where they are located', N'More Detail on Couplings', 0, NULL, N'Eliminado atrasos nas atividades do caminho critico com problemas de equipamentos de contingências ', '2026-07-27T00:00:00.000', '2026-07-29T06:46:55.000', N'1009878', NULL, NULL);
INSERT INTO #PVC VALUES (11422, N'81033365', N'1005614', N'Proteção da bomba do arla', 1, N'Others/Outros', N'ausência de proteção contra acumulo de material', N'processo de melhoria', N'10139', N'01 - Imagens/01 - Antes/11422.jpeg', N'O acúmulo de material sobre o sistema de ARLA do caminhão causava a contaminação severa de todos os seus componentes.', N'01 - Imagens/02 - Depois/11422.jpeg', N'Desenvolvimento e instalação de uma carenagem de proteção sob medida para bloquear o contato dos materiais com o sistema.', NULL, N'ausência de uma proteção, e fabricado uma proteção.', N'melhoria continua', 0, NULL, N'This has gone as expected. All parties are happy with this change.', '2026-07-28T00:00:00.000', '2026-07-29T08:32:14.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11423, N'81058966', N'498974', N' Instalação de Válvula de Dreno na Caixa de Flotação CF-2017-07', 1, N'Others/Outros', N' Durante as atividades de manutenção da caixa de flotação CF-2017-07 foi identificada a ausência de uma válvula de dreno na parte inferior do equipamento. Essa condição dificultava a drenagem do material acumulado, fazendo com que a equipe da Sodexo gastasse aproximadamente um turno de 8 horas para realizar a limpeza interna.', N'Implantar uma válvula guilhotina de 4 polegadas para facilitar a drenagem do material acumulado, reduzindo o tempo de limpeza de 8 horas para aproximadamente 2 horas e 30 minutos, aumentando a segurança, a produtividade e a disponibilidade do equipamento.', N'10031', N'01 - Imagens/01 - Antes/11423.jpeg', N' a caixa de flotação não possuía válvula de dreno, dificultando a retirada do material acumulado na parte inferior. A limpeza era realizada manualmente, demandando cerca de 8 horas.', N'01 - Imagens/02 - Depois/11423.jpeg', N'Instalada válvula guilhotina de 4" em um ponto estratégico da caixa de flotação, permitindo a drenagem rápida do material acumulado. O tempo de limpeza foi reduzido para  2 horas e 30 minutos, proporcionando maior agilidade, segurança e eficiência.', NULL, N'Sim, O problema foi resolvido com a instalação da válvula guilhotina de 4". A melhoria permitiu a drenagem eficiente do material acumulado, reduziu significativamente o tempo de limpeza, aumentou a produtividade das equipes de manutenção e eliminou a necessidade de longos períodos de limpeza manual, proporcionando maior segurança durante a execução das atividades.', N'A instalação de dispositivos simples, como uma válvula de dreno, pode gerar ganhos expressivos em segurança, produtividade e redução do tempo de manutenção. A identificação de oportunidades em campo e a atuação preventiva contribuem para a melhoria contínua dos processos.', 0, NULL, N'Diminuição de tempo necessário para coleta e envio de informações, redução de 10 minutos para menos de 1 minuto.
INSERT INTO #PVC VALUES (11424, N'81058966', N'81038896', N'Instalação de Válvula de Dreno CF-2017-06', 1, N'Others/Outros', N'Durante a manutenção da caixa de flotação CF-2017-06 foi identificada a ausência de uma válvula de dreno, dificultando a remoção do material acumulado. A limpeza demandava cerca de 8 horas, causando atrasos, baixa produtividade e exposição dos colaboradores à umidade e aos reagentes.', N'Instalar uma válvula guilhotina de 4" para reduzir o tempo de limpeza de 8 horas para 2h30, aumentando a segurança, a produtividade e a eficiência da manutenção.', N'10031', N'01 - Imagens/01 - Antes/11424.jpeg', N' Sem válvula de dreno, a limpeza da caixa era manual e demorava cerca de 8 horas, gerando atrasos na manutenção e maior exposição dos colaboradores à umidade e reagentes.', N'01 - Imagens/02 - Depois/11424.jpeg', N' Foi instalada uma válvula guilhotina de 4", reduzindo a limpeza para cerca de 2h30, melhorando a drenagem, a produtividade e a segurança das equipes.', NULL, N' Sim. A meta foi atingida com redução do tempo de limpeza.', N'Pequenas melhorias de engenharia podem reduzir o tempo de manutenção, aumentar a segurança e elevar a eficiência operacional.', 0, NULL, N'SSMA
INSERT INTO #PVC VALUES (11425, N'517013', N'517013', N'Automatização do Dimensionamento de Hh Preventivo para Estudos de Mão de Obra', 1, N'Open Pit/Poço aberto', N'O levantamento das horas-homem (Hh) preventivas para estudos de dimensionamento de mão de obra era realizado manualmente no SAP, demandando elevado esforço operacional e alto tempo de processamento.', N'Automatizar a obtenção e consolidação das horas planejadas de manutenção preventiva, reduzindo o esforço manual e aumentando a confiabilidade das informações utilizadas nos estudos de dimensionamento de mão de obra.', N'10015', N'01 - Imagens/01 - Antes/11425.jpeg', N'Para obter o dimensionamento de HH preventivo utilizado nos estudos de mão de obra, era necessário acessar o SAP e consultar individualmente os planos de manutenção, registrando manualmente os valores das listas de tarefas. O processo era totalmente manual, demorado e trabalhoso, exigindo grande movimentação entre telas e registros. Além disso, havia elevado risco de erros de digitação, inconsistências nos resultados e retrabalho para validação das informações.', N'01 - Imagens/02 - Depois/11425.jpeg', N'Foi estruturada uma solução baseada em modelagem de dados no Power Query, onde basta realizar a extração da base do SAP para que todo o tratamento e consolidação dos dados ocorram automaticamente. A solução reúne os tempos planejados de HH dos planos de manutenção em uma única estrutura padronizada e confiável, reduzindo atividades manuais, aumentando a agilidade do processo e garantindo maior qualidade e confiabilidade das informações para os estudos de dimensionamento de mão de obra.', NULL, N'Foi desenvolvida uma modelagem de dados utilizando Power Query no Excel, capaz de tratar automaticamente a base exportada do SAP e consolidar os tempos de HH planejados dos planos de manutenção em uma estrutura única para análise, gasto médio 16 horas reduzido para 1 hora.', N'A utilização de modelagem de dados para automatizar processos de consolidação reduz significativamente o esforço operacional, melhora a qualidade das informações e libera tempo para atividades de maior valor agregado.', 0, NULL, N'Redução estimada de até R$ 7.200,00 por ano com a eliminação de custos de manutenção corretiva dos cantos das paredes. A melhoria foi realizada com o reaproveitamento de correia de tambor de retorno, evitando descarte e garantindo proteção contra impactos. A solução aumentou a durabilidade da estrutura, reduziu retrabalho e contribuiu para ganhos financeiros e ambientais.
INSERT INTO #PVC VALUES (11426, N'517013', N'517013', N'Automatização do Dimensionamento de Hh Corretivo e Condicional para Estudos de Mão de Obra', 1, N'Open Pit/Poço aberto', N'A obtenção das horas-homem (Hh) corretivas e condicionais para estudos de dimensionamento de mão de obra exigia diversas etapas manuais de tratamento e consolidação de dados, tornando o processo demorado e sujeito a erros.', N'Automatizar a consolidação das horas executadas em manutenções corretivas e condicionais, reduzindo o esforço operacional e aumentando a confiabilidade das informações utilizadas nos estudos de dimensionamento de mão de obra.', N'10015', N'01 - Imagens/01 - Antes/11426.jpeg', N'Para obter o dimensionamento de HH corretivo e condicional utilizado nos estudos de mão de obra, era necessário baixar uma base de dados proveniente de um relatório em Power BI do PCM e realizar diversas tratativas manuais, incluindo agregação de valores, classificação de itens e consolidação das informações. O processo era demorado, repetitivo, sujeito a erros operacionais e exigia elevado esforço para garantir a consistência dos dados antes da análise.', N'01 - Imagens/02 - Depois/11426.jpeg', N'Foi estruturada uma solução baseada em modelagem de dados no Power Query, onde basta realizar a extração da base do Power BI para que todo o tratamento, classificação e consolidação das informações ocorram automaticamente. A solução reúne os tempos executados das ordens de manutenção corretiva e condicional em uma estrutura única, padronizada e confiável, proporcionando maior agilidade, redução de atividades manuais (de 8 horas para 30 minutos) e aumento da confiabilidade dos dados utilizados nos estudos de dimensionamento de mão de obra.', NULL, N'Foi desenvolvida uma modelagem de dados utilizando Power Query no Excel para automatizar as etapas de tratamento, classificação, consolidação e cálculo dos tempos executados das ordens corretivas e condicionais a partir da base extraída do Power BI do PCM.', N'A automação através de modelagem de dados reduz significativamente o tempo de preparação das informações, elimina retrabalhos e aumenta a qualidade dos dados utilizados em análises técnicas.', 0, NULL, N'performance, produtividade, segurança, tempo', '2026-07-28T00:00:00.000', '2026-07-29T09:53:12.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (11427, N'517013', N'517013', N'Automatização da Avaliação de Critérios para Cadastro de Local de Instalação de 6º Nível', 1, N'Open Pit/Poço aberto', N'A definição sobre a possibilidade de cadastro de locais de instalação de 6º nível durante a elaboração do documento normativo de dados mestres VBM dependia de análises interpretativas dos critérios estabelecidos, gerando dúvidas e dificuldades para tomada de decisão padronizada.', N'Padronizar e automatizar a avaliação dos critérios para cadastro de locais de instalação de 6º nível, garantindo decisões consistentes e alinhadas ao documento normativo.', N'10015', N'01 - Imagens/01 - Antes/11427.jpeg', N'Durante a elaboração do documento normativo de dados mestres VBM, existiam dúvidas e dificuldades para determinar quando um local de instalação poderia ser cadastrado como 6º nível. A análise dependia da interpretação dos critérios definidos no documento, tornando o processo sujeito a diferentes entendimentos, discussões, retrabalho e falta de padronização na tomada de decisão.', N'01 - Imagens/02 - Depois/11427.jpeg', N'Foi desenvolvida uma planilha inteligente que utiliza perguntas estruturadas com respostas em formato dropdown para avaliar automaticamente os critérios definidos no documento normativo. Com base nas respostas fornecidas, a ferramenta gera uma recomendação objetiva indicando se o cadastro como local de instalação de 6º nível é aplicável ou não, garantindo uma decisão padronizada, rastreável e fundamentada nos critérios e diretrizes estabelecidos. Houve uma redução significativa no processo de 1 hora para 5 minutos.', NULL, N'Foi desenvolvida uma planilha inteligente em Excel com lógica de decisão baseada em perguntas e respostas pré-configuradas, utilizando validação de dados (dropdowns) e fórmulas automatizadas para avaliar os critérios definidos no documento normativo e emitir uma recomendação padronizada.', N'Transformar regras e critérios normativos em ferramentas automatizadas reduz subjetividades, aumenta a padronização e melhora a qualidade das decisões.', 0, NULL, N'Sem impacto financeiro direto. Ganhos relacionados ao aumento do engajamento, da comunicação interna e da participação dos colaboradores nas ações de saúde e qualidade de vida.
INSERT INTO #PVC VALUES (11428, N'81022762', N'81059346', N'Suporte de latas (limpa contato, desingripante)', 1, N'Others/Outros', N'Latas ficavam espalhadas sem um local definido
INSERT INTO #PVC VALUES (11429, N'81034922', N'81027004', N'BI DA CARTEIRA DE ORDENS PGB E PGU', 1, N'Others/Outros', N'HAVIA UMA DEFICIÊNCIA PARA OBTER OS DADOS DA CARTEIRA DE PGB E PGU PARA SE FAZER ANÁLISE, TENDO QUE BAIXAR A BASE MANUALMENTE DO SAP E CRIAR TABELAS DINAMICAS PARA ANALISAR.', N'CONTROLE VISUAL PARA ANÁLISE DA CARTEIRA DE PGB E PGU', N'10081', N'01 - Imagens/01 - Antes/11429.jpeg', N'HAVIA UMA DEFICIÊNCIA PARA OBTER OS DADOS DA CARTEIRA DE PGB E PGU PARA SE FAZER ANÁLISE, TENDO QUE BAIXAR A BASE MANUALMENTE DO SAP E CRIAR TABELAS DINAMICAS PARA ANALISAR.', N'01 - Imagens/02 - Depois/11429.jpeg', N'CRIADO BI COM A VISÃO DA CATEIRA POR ÁREAS E PROCESSOS, DE ONDE É POSSÍVEL TER UMA VISÃO ATUALIZADA DA CARTEIRA PARA REALIZAR ANÁLISES E TOMADAS DE DECISÃO.', NULL, N'SIM, COM O BI TEMOS A INFORMAÇÃO RÁPIDA DE FORMA VISUAL PARA ANÁLISE AGILIZANDO ASSIM AS TOMADAS DE DECISÃO.', N'BI COMO FORMA VISUAL ATUALIZADO AGILIZA A TOMADA DE DECISÃO', 0, NULL, N'Having the ability to formally submit NCRs and work with vendors to identify areas of improvement will in time improve overall vendor performance as well as improve internal performance with VNL.', '2026-07-06T00:00:00.000', '2026-07-29T10:11:10.000', N'81034922', NULL, NULL);
INSERT INTO #PVC VALUES (11430, N'81022762', N'81059346', N'Adequação do isolamento da praça Itaquerão ', 2, N'Others/Outros', N'Isolamento ineficaz, facilidade de acesso por lugar impróprio, não fazer o uso do caminho seguro.
