INSERT INTO #PVC VALUES (11432, N'81022762', N'81061987', N'Suporte para baterias que já estão carregadas ', 1, N'Others/Outros', N'Desorganização das baterias carregadas entre baterias descarregadas
INSERT INTO #PVC VALUES (11433, N'81046359', N'81046359', N'Fechamento de disjuntor temporizado via relé', 2, N'Others/Outros', N'Qual é o problema?
INSERT INTO #PVC VALUES (11434, N'81009653', N'81027004', N'Estratégia de abastecimento de equipamentos de Paradas  ', 1, N'No Replication/Sem replicação', N'Antes não havia um plano de atendimento de abastecimento dos equipamentos de contingências  das atividades de paradas de usina, os acionamentos era feito todos via rádio e gerava atrasos nos atendimentos e paradas dos equipamentos , com isso gerava atrasos direto com impactos nas atividades do caminho Critico da parada de usina . ', N'Viabilizar Recursos , reduzir atrasos nas atividades de Paradas ', N'10081', N'01 - Imagens/01 - Antes/11434.jpeg', N'Antes não havia um plano de atendimento de abastecimento dos equipamentos de contingências  das atividades de paradas de usina, os acionamentos era feito todos via rádio e gerava atrasos nos atendimentos e paradas dos equipamentos , com isso gerava atrasos direto com impactos nas atividades do caminho Critico da parada de usina . ', N'01 - Imagens/02 - Depois/11434.jpeg', N'Foi elaborado , um plano de abastecimento contemplando todos equipamentos de contingência  das atividades criticas da paradas de usina, com localização dos equipamentos , Rota de abastecimento , Horários de abastecimento , e com Tag de todos os equipamentos mapeados nas atividades validado com de time da equipe de combustível do site , gerando assim melhor atendimento e reduzindo atrasos no atendimento , eliminado paradas das atividades do caminho critico por falta de combustível dos equipamentos ', NULL, N'Problema resolvido com ganhos nas entregas das atividades no tempo programado ', N'Falha no abastecimento de equipamentos ', 0, NULL, N'The floor has been repaired and there are no issues in the shipping area in building 6.', '2026-07-01T00:00:00.000', '2026-07-29T10:32:12.000', N'81009653', NULL, NULL);
INSERT INTO #PVC VALUES (11435, N'81031229', N'81031229', N'Procurement Assistance', 1, N'Others/Outros', N'The process of ordering materials can be challenging when considering every step in the work flow. 
INSERT INTO #PVC VALUES (11436, N'81038914', N'81038914', N'Criação de tela no PIMS para reporte gerencial de informações do comissionamento ATHENA – Britagem 1 e 2', 1, N'Open Pit/Poço aberto', N'Foi identificado uma dificuldade e demora no envio das principais informações de comissionamento e Ramp up do projeto.', N'Maior agilidade no envio de informações.', N'10293', N'01 - Imagens/01 - Antes/11436.jpeg', N'Durante a fase de testes e comissionamento do Projeto ATHENA, havia necessidade frequente de reportar informações operacionais para acompanhamento da performance.
INSERT INTO #PVC VALUES (11437, N'81057254', N'81057254', N'Eliminação de Perdas e Contaminação com Graxa Ensacada (SAP 15317285)', 1, N'Others/Outros', N'Durante o consumo de graxa em tambores, permanecia um resíduo médio de 37 kg por tambor (20,5%), exigindo recuperação manual e transferência para outros recipientes.
INSERT INTO #PVC VALUES (11438, N'81042078', N'81042078', N'Replicação: aumento da vida útil da infraestrutura por proteção de cantos em áreas de circulação- Sala de estufa', 1, N'Others/Outros', N'Durante a movimentação e posicionamento dos carrinhos de amostras nas entradas das salas do laboratório, observou-se o impacto frequente nos cantos das paredes. Essa condição ocasionava desgaste da estrutura, descascamento da pintura e necessidade recorrente de manutenção corretiva. Além disso, o contato direto comprometia o padrão visual do ambiente e gerava retrabalho para a equipe. Esse cenário resultava em aumento de custos operacionais e redução da vida útil da infraestrutura, além de impactar negativamente na organização e nos padrões de 5S do laboratório.
INSERT INTO #PVC VALUES (11439, N'81042078', N'81042216', N'Implantação do Método de Determinação da Densidade Aparente de Carvão por Deslocamento de Água', 1, N'Others/Outros', N'O método anteriormente utilizado para determinação da densidade aparente do carvão exigia atividades em campo, como escavação da pilha, utilização de molde metálico, preenchimento do furo com água para determinação do volume, transporte das amostras ao laboratório, secagem em estufa por aproximadamente oito horas e cálculos posteriores. Essas etapas tornavam o processo lento, operacionalmente complexo, com maior consumo de recursos e maior exposição dos colaboradores aos riscos da atividade.
INSERT INTO #PVC VALUES (11440, N'81042078', N'81042078', N'Informativo Mensal – Turma B Sempre em Foco', 1, N'Others/Outros', N'Observou-se a ausência de um canal de comunicação específico para divulgar informações relacionadas à saúde e qualidade de vida da Turma B. Essa falta de divulgação reduz o acesso dos colaboradores a conteúdos relevantes, campanhas internas e orientações sobre hábitos saudáveis, impactando o engajamento e a participação nas ações promovidas pela empresa.
INSERT INTO #PVC VALUES (11441, N'81052333', N'81047054', N'Suporte para as ponteiras do rompedor ', 1, N'Crusher/Britadeira', N'As ponteiras estavam armazenadas em locais inadequados, diretamente sobre o piso superior do britador, gerando risco de tropeço, dificuldade na organização da área e potencial comprometimento da segurança durante as atividades de manutenção.', N'Auxiliar na substituição dos côncavos, garantindo a execução segura e eficiente da manutenção.', N'10362', N'01 - Imagens/01 - Antes/11441.jpeg', N'As ponteiras estavam armazenadas em local inadequado, diretamente sobre o piso superior do britador, gerando risco de tropeço, dificuldade na organização da área e atividade.', N'01 - Imagens/02 - Depois/11441.jpeg', N'Objetivo do suporte: Realizar a remoção e o acondicionamento adequado das ponteiras durante a troca dos côncavos, promovendo maior organização, segurança e eficiência na execução da manutenção.', NULL, N'sim, o suporte está sendo utilizado na substituição dos côncavos, garantindo a execução segura e eficiente da manutenção. Assegurando a continuidade e a confiabilidade da operação do equipamento.', N'melhorias contínuas nos processos operacionais .', 45000, 1, N'.', '2026-07-20T00:00:00.000', '2026-07-29T13:16:12.000', N'81052333', NULL, NULL);
INSERT INTO #PVC VALUES (11442, N'81031846', N'1005740', N'NCR Procedure & NCR Vendor Handbook', 1, N'Others/Outros', N'NCR Power App was developed. Refer to Kaizen # 11210. Procedure was required to explain how to use the App, define expectations, obligations, etc.', N'Develop NCR Procedure to explain how to use the NCR App, define expectations, obligations, etc.', N'10026', N'01 - Imagens/01 - Antes/11442.jpeg', N'NCR Power App was developed. Refer to Kaizen # 11210. Procedure was required to explain how to use the App, define expectations, obligations, etc. ', N'01 - Imagens/02 - Depois/11442.jpeg', N'Developed a detailed NCR Procedure & supplemental Workflow & Approvals Reference doc. Also, created a Vendor NCR Handbook defining vendor obligations which auto-attaches to vendor NCRs. Documents linked in NCR App. ', NULL, N'Yes, problem was resolved and goal achieved. More detailed than initially planned. Addition of vendor NCR handbook was not a part of initial plan but will prove to be a great addition to the process.', N'Need for clarity in expectations, roles & approvals within NCR process. Also, importance of providing clarity to vendors on NCR process. ', 0, NULL, N'chemical is now mixing better in the tank which will draw more copper out of the cobalt solution which in turn will make nicer cobalt rounds', '2026-06-19T00:00:00.000', '2026-07-29T13:39:24.000', N'81031846', NULL, NULL);
INSERT INTO #PVC VALUES (11443, N'81011163', N'81062557', N'Substituição de relés SIMOCODE obsoletos (Pro C) por conjuntos-reservas pré-montados com SIMOCODE Pro V', 1, N'Others/Outros', N'Ocorrência de paradas não programadas devido a falhas nos relés SIMOCODE Pro C obsoletos (base instalada de 281 unidades). Os equipamentos apresentam perda de comunicação com a rede, exigindo intervenção manual para restabelecimento da operação, com tempo médio de recuperação de aproximadamente 3 horas. Além disso, a ausência de unidades sobressalentes prontas para reposição rápida amplia o impacto operacional e o tempo de indisponibilidade dos ativos.', N'Evitar as paradas inoportunas com tempo médio de 3 horas de reconexão, decorrentes de falhas nos relés SIMOCODE obsoletos (Pro C), por meio da disponibilização de conjuntos-reserva pré-montados com SIMOCODE Pro V para substituição rápida — conforme validado no piloto 2251 AL-01 —, mitigando o lucro cessante por evento.', N'10081', N'01 - Imagens/01 - Antes/11443.jpeg', N'A gaveta do alimentador 2251 AL-01 (Alimentador de bolas dos moinhos MO-02 e MO-03, área de Moagem) operava com relé SIMOCODE modelo Pro C, já obsoleto. O dispositivo apresentou falha e deixou de conectar-se à rede, comprometendo o monitoramento e a proteção do motor. Para restabelecer a operação, era necessária intervenção manual (diagnóstico, download/upload do programa e reparametrização de sobrecarga e nó de rede), com tempo médio de 3 horas de parada por evento. Não havia gaveta-reserva pré-montada disponível para substituição rápida, o que prolongava a indisponibilidade e expunha o circuito de Moagem a paradas inoportunas.', N'01 - Imagens/02 - Depois/11443.jpeg', N'A gaveta do alimentador 2251 AL-01 (Alimentador de bolas dos moinhos MO-02 e MO-03, área de Moagem) passou a operar com relé SIMOCODE modelo Pro V, atual e com suporte de fabricante. Como ação imediata, foi realizado o download do programa de uma gaveta disponível e o upload no SIMOCODE do AL-01, com configuração dos parâmetros de sobrecarga e nó de rede, normalizando a conexão de rede do dispositivo. Na sequência, foi disponibilizada uma gaveta-reserva pré-montada com SIMOCODE Pro V, permitindo a substituição rápida (plug-in) em caso de nova falha. Com isso, eliminou-se a necessidade de reconexão manual de 3 horas, reduzindo o tempo de parada (MTTR) e mitigando o lucro cessante de R$ 804.262,35 por evento.', NULL, N'A ação implementada atendeu ao objetivo proposto de mitigar as paradas inoportunas associadas às falhas dos relés SIMOCODE Pro C obsoletos. O alimentador 2251 AL-01 passou a operar com um relé SIMOCODE Pro V, modelo atual e suportado pelo fabricante, eliminando a condição de vulnerabilidade causada pelas recorrentes perdas de comunicação observadas no equipamento anterior.
INSERT INTO #PVC VALUES (11444, N'81026607', N'81026607', N'Adequação da Rotina de Entrega de Materiais', 1, N'No Replication/Sem replicação', N'A entrega de materiais do armazém para a área de preparação apresenta atrasos e falta de padronização no processo, causando indisponibilidade de materiais no momento da preparação dos recursos para manutenção. Essa situação gera retrabalho, aumento de deslocamentos, perda de produtividade e impacto no cumprimento da programação das atividades planejadas.
INSERT INTO #PVC VALUES (11445, N'81031846', N'1014409', N'Reduction in Monthly Subscription', 1, N'Others/Outros', N'Monthly subscription cost for OPAS app was $9,500 which was based on full/larger role out. However, Vale not receiving full benefit because OPAS software is still dependent on the ongoing testing being conducted by Vale to determine which device will be used for U/G communication at Voisey''s Bay.', N'Reduce Monthly Subscription Cost', N'10026', N'01 - Imagens/01 - Antes/11445.jpeg', N'OPAS monthly subscription was $9,500. Vale not receiving full benefit. Software dependent on the ongoing testing being conducted by Vale to determine which device will be used for U/G communication at Voisey''s. ', N'01 - Imagens/02 - Depois/11445.jpeg', N'Vendor agreed to lower monthly fee to $2,850 per month while maintaining current level of service for approximately 12 months or until Vale confirms path forward, whichever comes first.  ', NULL, N'Goal of reducing monthly rate was achieved. Rate reduced by $6,650 per month.', N'Challenge rates when the intended service is not being provided even if it is at no fault of the vendor.', 79800, 3, N'.', '2026-05-01T00:00:00.000', '2026-07-29T14:18:56.000', N'81031846', NULL, NULL);
INSERT INTO #PVC VALUES (11446, N'81046916', N'81046916', N'Garantias de curvas 24 x 45° Raio 5D ', 1, N'Concentration/Concentração', N'Após a aquisição de curvas com a empresa Del Rey Minerals, foi observada que as curvas entregues apresentaram descolamento da estrutura de borracha em relação a sua estrutura metálica. Sendo assim, no decorrer do ano de 2026 foram solicitadas as garantias das duas curvas relacionadas a Linha 4 que alimenta o moinho MO-2014-12.', N'Redução de custo com novas aquisições e aumento da confiabilidade da linha 4', N'10293', N'01 - Imagens/01 - Antes/11446.jpeg', N'Conforme é apresentado na figura, tivemos o rompimento da curva e a paralização da linha 4 de SLB 2 para troca do componente. As avarias esse ano totalizaram 42 horas.
INSERT INTO #PVC VALUES (11447, N'124132', N'124132', N'Shipping floor damaged in multiple areas', 1, N'Refining/Refino', N'The floor in building #6 had some damage that required repairs. Causing issues with our forklifts being bounce around.', N'Repair floor', N'10255', N'01 - Imagens/01 - Antes/11447.jpeg', N'The floor area in shipping building #6 was in need of repairs.', N'01 - Imagens/02 - Depois/11447.jpeg', N'The floor area in building #6 has been repaired.', NULL, N'Forklift hitting these holes in the floor causes issues.', N'Floor needed repairs', 0, NULL, N'.', '2026-07-27T00:00:00.000', '2026-07-29T14:26:38.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11448, N'124132', N'124132', N'2-ton scale requires bracing', 1, N'Refining/Refino', N'We had some load cells on the 2-ton scale damaged.', N'Install bracing on the 2-ton scale to eliminate load cell damage', N'10255', N'01 - Imagens/01 - Antes/11448.jpeg', N'We had some load cells damaged on the 2-ton scale by our forklifts moving the scale.', N'01 - Imagens/02 - Depois/11448.jpeg', N'We installed braces to keep the stand from moving.', NULL, N'Load cells will not get damaged by the forklift moving the stand.', N'New braces will help keep the stand in place', 0, NULL, N'.', '2026-07-28T00:00:00.000', '2026-07-29T14:32:37.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11449, N'81013897', N'81013712', N'Crusher Duct Cleaning', 1, N'Crusher/Britadeira', N'Limited vent flow in crusher dust collector due to build up of dust. Considering replacement of all ducting.', N'Improve vent flow in crusher dust collector venting', N'10345', N'01 - Imagens/01 - Antes/11449.jpeg', N'Vent ducting choked due to accumulation of dust.', N'01 - Imagens/02 - Depois/11449.jpeg', N'Cut holes in ducting to allow vacuuming of the duct rather than pulling it all down and replacing.', NULL, N'Problem solved without need to replace all ducting.', N'Dust was able to be vacuumed out safely without need to replace all ducting', 44000, 3, N'Tempo reduzido e confiabilidade nos resultados.', '2026-07-10T00:00:00.000', '2026-07-29T14:33:25.000', N'81013897', NULL, NULL);
INSERT INTO #PVC VALUES (11450, N'81056094', N'81056094', N'Voisey''s Bay Contractor Onboarding Process Guide', NULL, N'Others/Outros', N'Contractor onboarding information was not documented in a centralized, standardized format.', N'Standardize the contractor onboarding process and improve clarity for all stakeholders.', N'10100', N'01 - Imagens/01 - Antes/11450.jpeg', N'Knowledge was dispersed among team members, creating inconsistency and onboarding delays.', N'01 - Imagens/02 - Depois/11450.jpeg', N'Created a comprehensive onboarding guide outlining roles, steps, requirements, and responsibilities. Standardized onboarding activities and provided a single source of truth for the process.', NULL, N'The guide centralized onboarding information and standardized contractor onboarding activities.', N'Clear documentation reduces confusion, improves consistency, and supports knowledge transfer.', 0, NULL, N'performance, produtividade, saúde e segurança, tempo;
INSERT INTO #PVC VALUES (11451, N'81046654', N'81046654', N'Planilha projeção de custo Carga e Carregamento', 1, N'Others/Outros', N'Ausência de informações completas na planilha de custos comprometia a precisão das previsões de gastos, podendo resultar em desvios orçamentários e na necessidade de recursos adicionais não planejados.', N'Controle de custo das ordens mensal D+30 e D+90', N'10234', N'01 - Imagens/01 - Antes/11451.jpeg', N'Alguns campos da planilha de custos apresentavam informações incompletas, comprometendo a precisão das projeções financeiras. Essa situação poderia resultar em custos não previstos, desvios orçamentários e dificuldades no planejamento adequado das ordens.', N'01 - Imagens/02 - Depois/11451.jpeg', N'Foi desenvolvida uma planilha consolidada contendo todas as informações necessárias para tornar as previsões de custos mais assertivas. Foram centralizados em um único local dados como empenhos, kit delivery, ordens solicitadas de períodos anteriores, ordens canceladas e o planejamento previsto. Essa consolidação proporcionou maior visibilidade dos custos, melhor controle orçamentário e redução do risco de gastos acima do valor orçado', NULL, N'Sim', N'Ganho de Tempo na alimentação da planilha', 0, NULL, N'MOVIMENTAÇÃO MAIS FÁCIL E LEVE E VISUALIZAÇÃO DE LIMITE PARA QUANTIDADE CORRETO DENTRO DOS TAMBORES.', '2026-07-08T00:00:00.000', '2026-07-29T14:51:09.000', N'81046654', NULL, NULL);
INSERT INTO #PVC VALUES (11452, N'81056094', N'81056094', N'SharePoint Site Request Process Guide', NULL, N'Others/Outros', N'Users lacked documented guidance for requesting SharePoint sites and relied on IT for assistance.', N'Provide clear instructions for requesting SharePoint sites and reduce user confusion.', N'10100', N'01 - Imagens/01 - Antes/11452.jpeg', N'No centralized instructions existed, resulting in repeated support requests and delays.', N'01 - Imagens/02 - Depois/11452.jpeg', N'Created a guide outlining the SharePoint site request process, requirements, and key information. Standardized the request process and provided a consistent self-service resource.', NULL, N'The guide centralized request information and reduced dependency on EUC support.', N'Clear documentation reduces support effort and improves the user experience.', 0, NULL, N'Evitou possível vazamento e contaminação do solo e perda de material.', '2026-06-23T00:00:00.000', '2026-07-29T14:59:08.000', N'81056094', NULL, NULL);
INSERT INTO #PVC VALUES (11453, N'483375', N'483375', N'Aplicativo Busca ART', 2, N'Others/Outros', N'As ART''s ficam disponíveis no BI da Segurança, mas para ter acessar essas informações é necessário ter acesso a rede VALE bem como ao Power Apps, é um processo que pode demorar e não é muito intuitivo, o projeto consolida essa informações em um APP que roda de foram Offline, permitindo que executantes, operadores, planejadores e inspetores tenham acesso fácil e rápido a todas as ART''s disponíveis.', N'Facilitar o acesso as ART''s cadastradas e revisadas', N'10178', N'01 - Imagens/01 - Antes/11453.jpeg', N'O acesso as informações é feita através do BI da Segurança, para tal, é necessário solicitação de acesso a plataforma, ao PoweApps e ter acesso a rede Vale V-DATA. Dificultando o executantes, acessar de forma fácil.
INSERT INTO #PVC VALUES (11454, N'81013885', N'81040973', N'PORTÃO METALICO', 2, N'No Replication/Sem replicação', N'O acesso à plataforma era realizado por uma escada sem sistema de fechamento.', N' reduzindo significativamente o risco de queda e proporcionando maior segurança durante o acesso à plataforma.', N'10362', N'01 - Imagens/01 - Antes/11454.jpeg', N'Durante as atividades de içamento de cargas com guindaste , as áreas de acesso não possuíam isolamento adequado. A restrição de acesso era realizada de forma improvisada, utilizando correntes ou cones de sinalização, o que não garantia uma barreira física eficaz e aumentava o risco de acesso indevido à área durante as operações.', N'01 - Imagens/02 - Depois/11454.jpeg', N'Foi projetada, fabricada e instalada uma cancela metálica de segurança nos pontos de acesso às plataformas de içamento. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', NULL, N'sim.  A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado.', N' proporcionando maior controle de acesso.', 0, NULL, N'Com a aplicação da chave seccionadora 6214410, alcançamos a meta estabelecida de melhoria operacional e redução de custos. A solução proporcionou maior facilidade nas manobras de ligação e desligamento, aumentando a segurança e a agilidade das intervenções.', '2026-07-28T00:00:00.000', '2026-07-29T15:10:12.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11455, N'1008390', N'1008390', N'Agitator in tote for Chemical Trial in cobalt ', 1, N'Others/Outros', N'Tech Services is running a trial for a chemical in cobalt, and the tote was not agitated so chemical was settling in the bottom of the tote and not getting  accurate results', N'agitate tote to stir chemicals that settle out ', N'0', N'01 - Imagens/01 - Antes/11455.jpeg', N'Tech Services is running a trial for a chemical in cobalt, and the tote was not agitated so chemical was settling in the bottom of the tote and not getting  accurate results', N'01 - Imagens/02 - Depois/11455.jpeg', N'solution to this issue was to put a small pneumatic  mixer/agitator in the tote to help mix the chemicals and get accurate results during the trial. in order for the mixer to fit we had to make up a little platform on top of the tote to keep the mixer off the bottom. ', NULL, N'Yes Problem was solved mixer is now in tote and mixing the solution for dosing ', N'proper mixing of certain chemicals is needed during dosing ', 0, NULL, N'Melhoria no tempo de manutenção e na ergonomia durante execução da atividade', '2026-07-28T00:00:00.000', '2026-07-29T15:15:15.000', N'1008390', NULL, NULL);
INSERT INTO #PVC VALUES (11456, N'81013885', N'81040973', N'PORTÃO DE ACESSO PENEIRA', 2, N'Others/Outros', N'Durante as atividades de içamento de cargas com ponte rolante na área das peneiras não tinha o portão de controle de acesso de pessoas. ', N'portão de controle de acesso de pessoas na área das peneiras.', N'10362', N'01 - Imagens/01 - Antes/11456.jpeg', N'Durante as atividades de içamento de cargas com ponte rolante na área das peneiras não tinha o portão de controle de acesso de pessoas. ', N'01 - Imagens/02 - Depois/11456.jpeg', N'Fabricada e instalada uma cancela metálica de segurança nos pontos de acesso  içamento da ponte rolante. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', NULL, N'SIM.A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado.', N'aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', 0, NULL, N'Resultado esperado alcançado', '2026-07-28T00:00:00.000', '2026-07-29T15:23:55.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11457, N'517429', N'517429', N'Automação da Validação de massas dos Pontos de Controle no GPV', 1, N'No Replication/Sem replicação', N'O processo de validação dos apontamentos de movimentação de massa era realizado manualmente nos pontos de controle do GPV. Esses pontos geram aproximadamente 48.993 movimentos por mês, exigindo um elevado volume de conferências e validações operacionais, aumentava a carga operacional da Sala de Controle e tornava o processo suscetível a atrasos, especialmente durante o fechamento mensal', N'Automatizar o processo de validação dos pontos de controle de movimentação de massa, eliminando atividades manuais de baixo valor agregado, reduzindo o tempo dedicado às validações, minimizar riscos de erros operacionais, aumentar a confiabilidade das informações e contribuir para um fechamento mensal mais ágil e dentro dos prazos estabelecidos.', N'10229', N'01 - Imagens/01 - Antes/11457.jpeg', N'Validação manual de aproximadamente 48.993 registros mensais de movimentação de massa, gerados através do pontos de controle, demandava elevado esforço operacional gerando sobrecarga, risco de atrasos no fechamento mensal e utilização de recursos em atividades repetitivas de baixo valor agregado.
INSERT INTO #PVC VALUES (11458, N'81013885', N'81040973', N'CANCELA DE SEGURANÇA', 2, N'Others/Outros', N'Ao acessar o equipamento 2251 BP 02 não tinha uma cancela de segurança.', N', garantindo a continuidade da proteção coletiva.', N'10362', N'01 - Imagens/01 - Antes/11458.jpeg', N' A restrição de acesso a bomba  era realizada de forma improvisada, utilizando de sinalização, o que não garantia uma barreira física eficaz e aumentava o risco de acesso indevido à área durante as operações.', N'01 - Imagens/02 - Depois/11458.jpeg', N' Instalada uma cancela metálica de segurança nos pontos de acesso a bomba. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para acessa a bomba.', NULL, N'SIM. aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para acessa a bomba.', N' A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado', 0, NULL, N'Foi fabricado um suporte para melhorar o processo', '2026-07-27T00:00:00.000', '2026-07-29T15:53:46.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11459, N'517429', N'517429', N'Padronização de Apontamentos GPV– Corte Grosseiro na Ciclonagem', 1, N'No Replication/Sem replicação', N'Os apontamentos de paradas relacionados ao corte grosseiro na ciclonagem vinham sendo registrados de forma não padronizada, utilizando diferentes classificações de falha para uma mesma condição operacional, como Entupimento, Inspeção Operacional, Nível Alto, entre outras.
INSERT INTO #PVC VALUES (11460, N'81013885', N'81016951', N'SUPORTE DE CAIXA', 2, N'Others/Outros', N'AGUA EM LOCAL INADEQUADO .', N'MELHORA A AREA DE TRABALHO .', N'10362', N'01 - Imagens/01 - Antes/11460.jpeg', N'A caixa térmica para armazenamento de água potável permanecia apoiada diretamente sobre o piso, dificultando o acesso dos colaboradores, a higienização do local e a organização do ambiente. As embalagens de água também eram armazenadas no chão, ficando suscetíveis ao contato com umidade, sujeira e impactos, comprometendo as boas práticas de organização e conservação.', N'01 - Imagens/02 - Depois/11460.jpeg', N'Foi fabricado e instalado um suporte metálico para elevação da caixa térmica, proporcionando melhor ergonomia durante a utilização, facilitando a limpeza da área e eliminando o contato direto com o piso. O projeto também contemplou um suporte lateral para armazenamento das embalagens de água, mantendo-as organizadas, protegidas e de fácil acesso, contribuindo para a melhoria das condições de trabalho, organização do ambiente e padronização conforme as práticas de segurança e 5S.', NULL, N'SIM.O projeto também contemplou um suporte lateral para armazenamento das embalagens de água, mantendo-as organizadas, protegidas e de fácil acesso, contribuindo para a melhoria das condições de trabalho.', N'Foi fabricado e instalado um suporte metálico para elevação da caixa térmica, proporcionando melhor ergonomia durante a utilização, facilitando a limpeza da área e eliminando o contato direto com o piso.', 0, NULL, N'Foi colocado suporte', '2026-07-28T00:00:00.000', '2026-07-29T16:17:30.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11461, N'81013885', N'81012464', N'PORTAO DE ACESSO', 2, N'Others/Outros', N'Durante as operações de içamento, os colaboradores permaneciam expostos ao risco de queda, devido à ausência de uma barreira física que garantisse a continuidade da proteção coletiva.', N'fabricada e instalada uma cancela metálica de segurança nos pontos de acesso às plataformas de içamento.', N'10362', N'01 - Imagens/01 - Antes/11461.jpeg', N'Durante as atividades de içamento de cargas com ponte rolante, as áreas de acesso não possuíam isolamento adequado. A restrição de acesso era realizada de forma improvisada, utilizando correntes ou cones de sinalização, o que não garantia uma barreira física eficaz e aumentava o risco de acesso indevido à área durante as operações.', N'01 - Imagens/02 - Depois/11461.jpeg', N'Foi projetada, fabricada e instalada uma cancela metálica de segurança nos pontos de acesso às plataformas de içamento. A solução substituiu os isolamentos provisórios por um sistema fixo e padronizado, proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', NULL, N'SIM. proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança para movimentação de cargas com ponte rolante.', N'proporcionando maior controle de acesso, aumento da segurança dos colaboradores e conformidade com os requisitos de segurança.', 0, NULL, N'Mas agilidade e mas segurança', '2026-07-28T00:00:00.000', '2026-07-29T16:22:42.000', N'81013885', NULL, NULL);
INSERT INTO #PVC VALUES (11462, N'540335', N'540335', N'Relatório D-1', 1, N'Others/Outros', N'Relatório D-1 e S-1 não confiável, apresentando divergências de dados em comparação com o SAP.', N'Tornar confiável e ', N'#N/A', N'01 - Imagens/01 - Antes/11462.jpeg', N'Foi criado um relatório de acompanhamento D-1 e S-1, alimentado por dados provenientes do BW. Entretanto, as informações apresentavam baixa confiabilidade, pois a carga de dados não ocorria diariamente, resultando em divergências entre os dados exibidos no relatório e as informações registradas no sistema SAP.', N'01 - Imagens/02 - Depois/11462.jpeg', N'Foi desenvolvido um relatório cujos dados são extraídos diretamente do sistema SAP. As informações são atualizadas diariamente, garantindo maior confiabilidade e evitando inconsistências nos dados e nos resultados apresentados.', NULL, N'O relatório anterior frequentemente apresentava informações desatualizadas devido a falhas no sistema BW, o que demandava tempo para investigação, análise e correção dos problemas. Com a extração dos dados sendo realizada diretamente do sistema SAP, o relatório passou a ter maior confiabilidade, garantindo informações atualizadas e eliminando a necessidade de esforços recorrentes para resolver inconsistências, permitindo maior foco nas atividades de negócio.', N'A melhoria dos processos torna o tempo mais produtivo e proveitoso.', 0, NULL, N'melhora a identificação e o tempo  de produção .', '2026-07-01T00:00:00.000', '2026-07-29T16:22:49.000', N'540335', NULL, NULL);
INSERT INTO #PVC VALUES (11463, N'81042078', N'81023761', N'Implantação de Estacionamento Dedicado na Área do Carvão Mineral para Otimização da Mobilidade e Segurança Operacional', 1, N'Others/Outros', N'Atualmente, os veículos utilizados pelos colaboradores não possuem um local exclusivo para estacionamento na área do Carvão Mineral. Essa condição provoca estacionamento em locais inadequados, aumento da circulação de veículos próximos às operações, conflitos entre equipamentos móveis e veículos leves, dificuldades de acesso e maior exposição dos colaboradores aos riscos operacionais.
INSERT INTO #PVC VALUES (11464, N'81008764', N'81007797', N'PESO ADEQUADO  E ERGONOMIA DA TAREFA', 2, N'Others/Outros', N'TAMBORES ESTAVAM FICANDO COM LIMITE ACIMA DO PERMITIDO E ASSIM FICANDO MUITO PESADO, PARA MANUSEAR, E INVIÁVEL ERGONOMICAMENTE PODENDO CAUSAR LESÕES NO COLABORADOR, NA HORA DA MOVIMENTAÇÃO PARA O DESCARTE.', N'ELIMNINAR O EXCESSO DE PESO', N'10129', N'01 - Imagens/01 - Antes/11464.jpeg', N'Os tambores utilizados para descarte não possuíam identificação visual indicando o limite máximo de preenchimento. Com isso, frequentemente eram acondicionados com volume e peso acima do recomendado, tornando a movimentação difícil, ergonomicamente inadequada e aumentando o risco de lesões aos colaboradores durante o transporte para descarte.', N'01 - Imagens/02 - Depois/11464.jpeg', N'Foi implementada a identificação visual do limite máximo de preenchimento dos tambores, orientando os colaboradores quanto à quantidade adequada de material a ser depositada. A ação permitiu o controle do peso dos recipientes, tornando o manuseio e a movimentação mais seguros e ergonômicos, reduzindo o esforço físico e o risco de lesões ocupacionais.', NULL, N'EXCESSO DE PESO E FALTA DE IDENTIFICAÇÃO DE NÍVEL DENTRO DOS TAMBORES, AGORA COM PLACA VISÍVEL E MELHORIA NA ERGONOMIA E MOVIMENTAÇÃO.', N'RESPEITO AS REGRAS E ORIENTAÇÕES DE SEGURANÇA E TRABALHO', 0, NULL, N'O problema foi resolvido por meio da implantação de suporte para acondicionamento das mangueiras em 100% das propulsoras de graxa. A melhoria reduziu o esforço ergonômico durante o manuseio, melhorou a organização dos equipamentos e contribuiu para a realização das atividades de abastecimento e lubrificação de forma mais segura e eficiente.', '2026-07-28T00:00:00.000', '2026-07-29T17:48:17.000', N'81008764', NULL, NULL);
INSERT INTO #PVC VALUES (11465, N'81046537', N'81046759', N'MONTAGEM DE ESTRUTURA PARA SUSTENTAÇÃO', 1, N'Others/Outros', N'As mangueiras do sistema central de fluxo do mastro estavam sofrendo forte atrito.', N'EVITAR ATRITO ENTRE TUBOS', N'10150', N'01 - Imagens/01 - Antes/11465.jpeg', N'Os tubos do sistema central de fluxo de óleo do mastro estavam tendo um grande atrito entre si, resultando em desgaste, podendo acarretar vazamentos e perda de material. ', N'01 - Imagens/02 - Depois/11465.jpeg', N'Providenciado suporte e abraçadeiras plásticas para montagem de estrutura para sustentação do tubo de alimentação dos motores de rotação do cabeçote rotativo, devido à atrito entre tubos, o que poderia ocasionar danos e posteriormente vazamento hidráulico.', NULL, N'SIM, NÃO HOUVE MAIS ATRITOS. ', N'Observação do maquinário ', 0, NULL, N'Garantimos o nível máximo de funcionalidade do sistema anticolisão CAS na operação dos caminhões fora de estrada CAT.', '2026-07-17T00:00:00.000', '2026-07-29T17:50:21.000', N'81046537', NULL, NULL);
INSERT INTO #PVC VALUES (11466, N'81008764', N'81007797', N'ORGANIZAÇÃO DO ARQUIVO DE AMOSTRAS COMPOSTAS', 3, N'Others/Outros', N'FALTA DE ORGANIZAÇÃO E DIFICULDADE DE ENCONTRAR AS AMOSTRAS COMPOSTAS.', N'MANTER ORGANIZADO O ARQUIVO', N'10129', N'01 - Imagens/01 - Antes/11466.jpeg', N'As amostras de USINA e PFE não possuíam identificação padronizada para armazenamento, ficando distribuídas de forma desorganizada no arquivo. A ausência de placas de identificação e de locais definidos dificultava a localização das amostras, aumentava o tempo de busca e elevava o risco de armazenamento incorreto.', N'01 - Imagens/02 - Depois/11466.jpeg', N'Foram implantadas placas de identificação e definida uma padronização para o armazenamento das amostras em caixas específicas e em locais previamente determinados. Com a melhoria, as amostras passaram a ser acondicionadas de forma organizada, facilitando a localização, o controle e a rastreabilidade, além de otimizar o espaço do arquivo.', NULL, N'SIM, TIVEMOS UMA PADRONIZAÇÃO DE ORGANIZAÇÃO NO ARQUIVO DE AMOSTRAS E FACILIDADE NA HORA DA PROCURA DENTRO DO ARQUIVO.', N'ORGANIZAÇÃO E RASTREABILIDADE', 0, NULL, NULL, '2026-07-24T00:00:00.000', '2026-07-29T18:26:54.000', N'81008764', NULL, NULL);
INSERT INTO #PVC VALUES (11467, N'500473', N'500473', N'chave seccionadora', 2, N'Others/Outros', N'dificuldade de ligar e desligar a chave geral.', N'Facilita o ligação da chave seccionadora geral', N'10034', N'01 - Imagens/01 - Antes/11467.jpeg', N'chave seccionadora geral 7N-0718, o seccionamento da energia é através da chave 8H5306, que liga e desliga a chave de bloqueio. Durante a tentativa de manobra da chave seccionadora geral 7N-0718, foi constatada dificuldade para realização do fechamento (ligação), exigindo esforço acima do normal no mecanismo de acionamento. ', N'01 - Imagens/02 - Depois/11467.jpeg', N'A chave seccionadora 621-4410 apresenta facilidade de manobra, permitindo operações de ligação e desligamento de forma simples, rápida e segura. Seu mecanismo proporciona acionamento suave, reduzindo o esforço do operador e contribuindo para maior eficiência e confiabilidade nas atividades de operação e manutenção.', NULL, N'sim, a chave seccionadora 6214410 possui acionamento leve e de fácil operação, facilitando as manobras de ligar e desligar com segurança e praticidade.', N'identificamos que a adoção de soluções que simplificam a operação e a manutenção contribui diretamente para o alcance das metas, a redução de custos e o aumento da confiabilidade do processo.', 334, 1, N'Trip hazard removed', '2026-07-24T00:00:00.000', '2026-07-29T23:39:43.000', N'500473', NULL, NULL);
INSERT INTO #PVC VALUES (11468, N'81042217', N'81055015', N'Implantação de janela de acesso para manutenção da caixa de ligação do motor da unidade hidráulica', 1, N'Others/Outros', N'A caixa de ligação do motor da unidade hidráulica não possuía acesso direto para inspeções e manutenções. As atividades eram executadas por cima da estrutura, exigindo posições inadequadas de trabalho, maior esforço físico e dificuldade de alcance dos componentes, aumentando o tempo de intervenção e a exposição a riscos ergonômicos.
INSERT INTO #PVC VALUES (11469, N'81010025', N'81010025', N'Relatório automatizado Horímetros x Tag x Modelo x Série', 1, N'Others/Outros', N'Demora para consulta de informações referente a Horímetros, Tag, Modelo e Série dos equipamentos de mina', N'Reduzir tempo de consulta', N'10081', N'01 - Imagens/01 - Antes/11469.jpeg', N'Não havia Dashboard para consulta rápida de horímetros, tag, modelo e série de equipamentos de mina', N'01 - Imagens/02 - Depois/11469.jpeg', N'Elaborado relatório automatizado (Dashboard) no Power Bi como fonte de consulta rápida para horímetro x Tag x Modelo x Série.', NULL, N'Reduzido tempo para pesquisa e consulta. Meta alcançada', N'Inovação', 0, NULL, N'Redução do tempo de limpeza dos tornos, aumento da segurança dos operadores por meio da eliminação do contato direto com a limalha e melhoria da organização e produtividade da área de usinagem.', '2026-07-30T00:00:00.000', '2026-07-30T08:35:22.000', N'81010025', NULL, NULL);
INSERT INTO #PVC VALUES (11470, N'81006946', N'81006946', N'SUPORTE DE CILINDROS', 3, N'Others/Outros', N'Atualmente, a área não dispõe de um suporte adequado para a armazenagem de cilindros. Como consequência, os cilindros permanecem diretamente no chão, sem um padrão definido de organização, dificuldade de identificação, movimentação inadequada e comprometimento da segurança e da organização do ambiente de trabalho.', N'Eliminar o armazenamento de cilindros diretamente no chão.', N'10139', N'01 - Imagens/01 - Antes/11470.jpeg', N'Durante a análise do problema, identificou-se que a ausência de um suporte adequado está relacionada à falta de estrutura específica para armazenamento e à inexistência de um padrão definido para alocação dos cilindros. Também foi observado que a limitação de espaço e a ausência de planejamento da área contribuíram para a situação atual.', N'01 - Imagens/02 - Depois/11470.jpeg', N'Com a implantação do suporte, espera-se obter um ambiente mais seguro e organizado, com todos os cilindros armazenados corretamente, redução dos riscos de acidentes, maior facilidade de acesso e movimentação, melhoria no padrão visual da área e atendimento às práticas e requisitos de segurança.', NULL, N'Sim! se mantermos a organização e o padrão.', N'Com a padronização, a área ficou mais segura.', 0, NULL, NULL, '2026-07-29T00:00:00.000', '2026-07-30T09:40:15.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (11471, N'81022747', N'540124', N'suporte e  instalado caixa de aferição', NULL, N'Others/Outros', N'não tinha um suporte para colocar a caixa de distribuição dê aferimento dos olhos.', N'Segurança', N'10144', N'01 - Imagens/01 - Antes/11471.jpeg', N'Antes não tinha um suporte para colocar a caixa de distribuição dê a ferimento dos olhos.', N'01 - Imagens/02 - Depois/11471.jpeg', N'Foi fabricado um suporte', NULL, N'Não tinha nenhum tipo de segurança', N'SEGURANÇA', 0, NULL, N'Com a instalação da fita de isolamento retrátil e redefinição da área, foi possível ampliar efetivamente o espaço de manobra, proporcionando maior segurança, melhor fluidez operacional e redução das manobras corretivas, atendendo à meta de melhorar a circulação da empilhadeira sem necessidade de investimento em infraestrutura.', '2026-07-29T00:00:00.000', '2026-07-30T10:11:52.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11472, N'1014349', N'1014349', N'Capital Spot POs', 1, N'Others/Outros', N'There is a lack of visibility on the status of Spot POs when requisitions are sent to Wipro because local procurement does not issue spot POs. ', N'Increase visability on status of spot PO creation', N'0', N'01 - Imagens/01 - Antes/11472.jpeg', N'Spot requisitions are entered for Long Harbour Capital Projects and are sent to Wipro, not local procurement, for negotiation and award. There is a lack of visibility on the status and potential issues associated with these Spot orders. ', N'01 - Imagens/02 - Depois/11472.jpeg', N'Weekly touchpoint scheduled with LH Capital Proj Super, LH Procurement Super, Contracts Analyst & Wipro
INSERT INTO #PVC VALUES (11473, N'81022747', N'540124', N'Confeccionado suporte e  instalado caixa de aferição', NULL, N'Others/Outros', N'não tinha um suporte para colocar a caixa de distribuição dê a ferimento dos olhos.', N'Segurança', N'10144', N'01 - Imagens/01 - Antes/11473.jpeg', N'Antes não tinha um suporte para colocar a caixa de distribuição dê a ferimento dos olhos.', N'01 - Imagens/02 - Depois/11473.jpeg', N'Foi fabricado um suporte', NULL, N'Sem suporte para aferir', N'Mas suporte para segurança', 0, NULL, N'AGILIDADE E PRECISÃO COM MENOS ERRO NA BUSCA DE MATERIAIS NO ARMAZÉM PARA CONTROLARMOS O HISTÓRICO DE RETIRADA.', '2026-07-29T00:00:00.000', '2026-07-30T10:19:32.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11474, N'81022747', N'540124', N'engate de melhoria de abastecimento', NULL, N'Others/Outros', N'havia nessa cidade de 2 pessoas para completar o óleo e perdíamos muito tempo', N'Agilidade e segurança', N'10144', N'01 - Imagens/01 - Antes/11474.jpeg', N'Antes havia nessa cidade de 2 pessoas para completar o óleo e perdíamos muito tempo', N'01 - Imagens/02 - Depois/11474.jpeg', N'Foi instalado engate rápido no suporte do óleo do martelo e do óleo do hidráulico necessitamos se agora de uma pessoa. Tendo um ganho de 15 minutos', NULL, N'Antes a atividade tomava um tempo maior e com pouca segurança', N'Agilidade do processo', 0, NULL, N'O processo, que anteriormente exigia a leitura de diversos e-mails para localizar informações específicas, passou a ser realizado em poucos segundos por meio da planilha consolidada. Essa melhoria reduziu significativamente o tempo de consulta, atualização e compartilhamento das informações, proporcionando maior produtividade, organização e confiabilidade dos dados.', '2026-07-29T00:00:00.000', '2026-07-30T10:28:46.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11475, N'81006512', N'128215', N'patio Componentes ', 3, N'No Replication/Sem replicação', N'Na área de subconjunto de preparação de material dos componentes , não tinha identificação e organização por processo de prioridade e serviços ', N'Organização ', N'10081', N'01 - Imagens/01 - Antes/11475.jpeg', N'Dificuldade em identifica material para serviços da semana.
INSERT INTO #PVC VALUES (11476, N'538725', N'538725', N'Abrigo para os extintores de carretilha', 1, N'No Replication/Sem replicação', N'Os extintores de carretilha encontram-se expostos às condições climáticas, como chuva, sol e poeira, ocasionando desgaste prematuro, corrosão e necessidade de manutenções frequentes. A ausência de proteção adequada pode comprometer a conservação e a disponibilidade dos equipamentos em situações de emergência.', N'Melhorar a durabilidade e conservação dos extintores de carretilha, reduzindo a exposição às intempéries e aumentando a vida útil dos equipamentos.', N'10079', N'01 - Imagens/01 - Antes/11476.jpeg', N'O extintor de carretilha encontra-se instalado em área externa, sem proteção adequada contra sol, chuva e poeira. Essa condição tem contribuído para o desgaste prematuro da pintura, componentes e etiquetas de identificação, dificultando a inspeção visual e aumentando a necessidade de manutenção. Além disso, a exposição contínua às intempéries pode comprometer a conservação e a vida útil do equipamento, impactando sua confiabilidade em situações de emergência.', N'01 - Imagens/02 - Depois/11476.jpeg', N'Foi desenvolvido e instalado um abrigo metálico para os extintores de carretilha, garantindo proteção contra chuva, sol e poeira. A melhoria padronizou o acondicionamento dos equipamentos nas áreas externas, proporcionando maior conservação e facilitando as inspeções periódicas.
INSERT INTO #PVC VALUES (11477, N'486546', N'535629', N'Melhoria da Ergonomia e Organização no Processo de Lubrificação dos Comboios', 2, N'Others/Outros', N'A ausência de um sistema adequado de acondicionamento para as mangueiras das propulsoras de graxa gerava dificuldades operacionais, aumento do esforço ergonômico durante o manuseio dos equipamentos, desorganização da área e potencial risco de danos às mangueiras e conexões.
INSERT INTO #PVC VALUES (11478, N'81014137', N'81014137', N'POKA YOKE DOS GIGANTES DA MINERAÇÃO', 2, N'Others/Outros', N'Ausência de confiabilidade no teste de 2ª Etapa no retorno de manutenção no cambio de marchar dos caminhões.(Checklist operacional) ', N'Reporte de Falhas Critica.', N'10245', N'01 - Imagens/01 - Antes/11478.jpeg', N'A Verificação de Status funcional do decodificador de marcha no sistema embarcado anticolisão CAS era feita através de checklist manual pelo operador do equipamento, porém a falta de disciplina ou conhecimento da criticidade desta tarefa não garantia o eficácia desse fluxo, e identificamos vários casos na manutenção preventiva em que o Decodificador de marcha estava desligado do ponto de sensoriamento. 
INSERT INTO #PVC VALUES (11479, N'460522', N'81016737', N'Shutdonw - consumable gas detection supplies', 1, N'Projects/Projetos', N'HSR has an existing inventory of consumable gas detection supplies, including tubing, that remains unused following previous outages. Without a process to identify and utilize these available materials, operating areas may unnecessarily purchase new supplies for planned outages, resulting in avoidable costs, excess inventory, and increased waste', N'Utilization of existing gas detection supplies will reduce unnecessary purchasing, lower inventory carrying costs, minimize waste, and generate measurable cost savings for the September outage.', N'0', N'01 - Imagens/01 - Antes/11479.jpeg', N'HSR has an existing inventory of consumable gas detection supplies, including tubing, that remains unused following previous outages. Without a process to identify and utilize these available materials, operating areas may unnecessarily purchase new supplies for planned outages, resulting in avoidable costs, excess inventory, and increased waste. An opportunity exists to optimize inventory management by using existing stock before procuring new materials, thereby reducing costs and improving resource utilization.', N'01 - Imagens/02 - Depois/11479.jpeg', N'An opportunity exists to optimize inventory management by using existing stock before procuring new materials, thereby reducing costs and improving resource utilization.', N'https://globalvale.sharepoint.com/teams/basemetals', N'Utilization of existing gas detection supplies will reduce unnecessary purchasing, lower inventory carrying costs, minimize waste, and generate measurable cost savings for the September outage.', N'inventory control', 1200, 3, N'Estávamos “reféns” dos fabricantes para compra dos componentes homologados, custo mais alto, logística dupla e tempo de entrega maior.
INSERT INTO #PVC VALUES (11480, N'1010861', N'1010861', N'222 Sump Line Re-routing', 3, N'Others/Outros', N'Sump lined in 222 routed across travel ways causing tripping hazards and damage to chem hoses.', N'Re-route lie to remove from travel routes.', N'0', N'01 - Imagens/01 - Antes/11480.jpeg', N'2" chem hoses ran across building floors to move sump liquids. These lines would get ran over by forklifts as well as cause potential tripping hazards. ', N'01 - Imagens/02 - Depois/11480.jpeg', N'Sump lines were re-routed using existing lines and chem hose to create new flow paths for sump liquids. By doing this the hoses could be removed from main travel areas and rerouted. ', N'https://apps.powerapps.com/play/e/default-7893571b-6c2c-4cef-b4da-7d4b266a0626/a/36968851-22f6-4a28-bb70-3fdc4531d789?tenantId=7893571b-6c2c-4cef-b4da-7d4b266a0626&sourcetime=1726857871865&source=portal#', N'Hoses moved', N'Use of existing piping ', 2000, 3, N'Maior aderência ao planejamento, integração entre áreas operacionais, redução de desvios de execução, melhoria da previsibilidade da produção, governança estruturada do sequenciamento e maior alinhamento entre estratégia e operação.', '2026-07-29T00:00:00.000', '2026-07-30T13:28:35.000', N'1010861', NULL, NULL);
INSERT INTO #PVC VALUES (11481, N'202630', N'202630', N'Fee reduction - buyout of vehicles', 1, N'Others/Outros', N'Over the past 3 years we leased 47 vehicles through Hickman''s. Upon review of the buyout and looking for cost reduction i was about to remove the transfer fee of $50 per vehicle', N'Cost reduction', N'10026', N'01 - Imagens/01 - Antes/11481.jpeg', N'Over the past 3 years we leased 47 vehicles through Hickman''s. Upon review of the upcoming buyout and looking for cost reduction i was about to remove the transfer fee of $50 per vehicle', N'01 - Imagens/02 - Depois/11481.jpeg', N'Hickman''s agreed to waive this fee for each vehicle', NULL, N'Hickman''s agreed to waive this $50 fee for each vehicle resulting in an avoidance of $2,350', N'Look at ways to reduce, not a big savings but every dollar counts', 2350, 3, N'Melhoria na aderência dos planos.', '2026-01-13T00:00:00.000', '2026-07-30T13:49:50.000', N'202630', NULL, NULL);
INSERT INTO #PVC VALUES (11482, N'81029873', N'547581', N'Dispositivo Para limpar limalha nos tornos', 3, N'Others/Outros', N'Ausência de um dispositivo específico para remoção de limalha nos tornos, resultando em baixa eficiência na limpeza e redução da disponibilidade operacional dos equipamentos.', N'Desenvolver e implementar um dispositivo para limpeza de limalha nos tornos, visando aumentar a segurança dos operadores, reduzir o tempo de limpeza e melhorar a organização da área de usinagem.', N'10245', N'01 - Imagens/01 - Antes/11482.jpeg', N'Dificuldade na remoção de cavacos presos entre as arestas e a placa do torno, mesmo com o uso de luvas adequadas, aumentando o risco de cortes e lesões durante a limpeza do equipamento.
INSERT INTO #PVC VALUES (11483, N'81052333', N'81014733', N'Carro suporte para transportar tambor', 1, N'Crusher/Britadeira', N'A movimentação manual de tambores gera riscos de lesões ergonômicas, acidentes com queda de carga e derramamento de produtos, comprometendo a segurança dos colaboradores e a eficiência operacional.', N'Segurança e eficiência operacional ', N'10362', N'01 - Imagens/01 - Antes/11483.jpeg', N'A movimentação manual de tambores gera riscos de lesões ergonômicas, acidentes com queda de carga e impactos na segurança dos trabalhadores.', N'01 - Imagens/02 - Depois/11483.jpeg', N'Com a implantação e utilização de carro porta-tambor, reduz o risco de lesões ergonômicas, e proporciona maior estabilidade, controle operacional e executa o transporte seguro dos tambores sem esforços excessivos.
INSERT INTO #PVC VALUES (11484, N'92000679', N'81005006', N'Kaizen Área Livre, Manobra Segura', 2, N'Others/Outros', N'A área de isolamento dependia das grades de isolamento. O que limitava a área de manobra.', N'Ampliação da Área de Manobra Utilizando Apenas Fita Retrátil', N'10234', N'01 - Imagens/01 - Antes/11484.jpeg', N'A área de manobra era limitada pela quantidade de grades de isolamento disponíveis.', N'01 - Imagens/02 - Depois/11484.jpeg', N'Com a fita retrátil, a área de manobra pode ser ajustada conforme a necessidade.', NULL, N'A área disponível para manobra da empilhadeira era insuficiente, dificultando as operações, aumentando o tempo de movimentação e elevando os riscos de contato com estruturas e materiais.', N'Com uma área de manobra mais adequada, diminuíram-se as manobras corretivas, reduzindo riscos de colisões e aumentando a eficiência operacional.', 0, NULL, N'doors open properly now. proper signage for hazards', '2026-07-29T00:00:00.000', '2026-07-30T14:05:22.000', N'92000679', NULL, NULL);
INSERT INTO #PVC VALUES (11485, N'81052333', N'472995', N'Spray Controle de Particulados', 2, N'Crusher/Britadeira', N'A geração excessiva de particulados na área operacional tem causado dispersão de poeira no ambiente, a geração excessiva de particulados na área operacional tem causado dispersão de poeira no ambiente,', N'implantação/otimização do sistema de spray', N'10362', N'01 - Imagens/01 - Antes/11485.jpeg', N'Spray de água que serve para eliminar particulados (poeira) no chute de descarga do equipamento 2101TC01 ( TCLD) estava com formato (I) causando obstrução constante nos bicos e com excesso de bicos montado causando desperdício de água.', N'01 - Imagens/02 - Depois/11485.jpeg', N'Foi Instalado novo Spray de água para eliminar particulados (poeira) no chute de descarga do equipamento 2101TC01 ( TCLD) com novo formato (T) eliminando obstrução dos bicos de saída de água .Foi reduzido quantidade de bicos de 6 p/ 4 pra eliminar desperdício de água.', NULL, N'Spray de água que serve para eliminar particulados (poeira) no chute de descarga do equipamento 2101TC01 ( TCLD) estava com formato (I) causando obstrução constante nos bicos e com excesso de bicos montado, causando desperdício de água, foram reduzidos os bicos de 6 para 4 pra eliminar desperdício de água.', N'Melhorias contínuas nos processos operacionais.', 65000, 1, N'less time to disconnect hoses.', '2026-07-28T00:00:00.000', '2026-07-30T14:12:54.000', N'81052333', NULL, NULL);
INSERT INTO #PVC VALUES (11486, N'522369', N'92000204', N'CONTROLE DE RESERVAS / PEDIDO ', 1, N'No Replication/Sem replicação', N'DIFICULDADE DE RASTREIO DE MATERIAIS RETIRADOS DO ARMAZÉM PARA ÁREA ELÉTRICA  E KANBAN ELÉTRICA USINAS', N'GARANTIR CONTROLE E EFICIÊNCIA NA BUSCA DE MATERIAIS DA ELÉTRICA.', N'10197', N'01 - Imagens/01 - Antes/11486.jpeg', N'TEMOS DIFICULDADE DE CONTROLE DE DADOS HISTÓRICO DA RETIRADA DO MATERIAIS DO ARMAZÉM PARA ÁREA GERÊNCIA MANUTENÇÃO ELÉTRICA.', N'01 - Imagens/02 - Depois/11486.jpeg', N'FOI DESENVOLVIDO PELA ENGENHARIA UM FORMS VALE DE CONTROLE DE RESERVA / PEDIDO PARA AGILIZAR LEVANTAMENTOS DE DADOS PARA CONSULTA PARA POSSÍVEL RASTREIO.', NULL, N'GANHOS TANGÍVEIS PARA CONTROLE DE RESERVAS  / PEDIDO ATRAVÉS DO DESENVOLVIMENTO DO FORMS PARA MATERIAIS.', N'ADQUIRIMOS HISTÓRICO DE REGISTROS DE CONTROLE DE RESERVAS / PEDIDOS COM EVIDÊNCIAS', 0, NULL, N'Redução do tempo gasto na investigação dos desvios; Maior disponibilidade de informações para análise; Aumento da produtividade das reuniões de OTIF; Melhoria da qualidade e padronização dos dados utilizados pela equipe.', '2026-07-29T00:00:00.000', '2026-07-30T14:45:33.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (11487, N'81032641', N'81032641', N'CONTROLE DE ABSENTEÍSMO', 2, N'Others/Outros', N'As informações eram compartilhadas apenas no corpo dos e-mails, o que dificultava a visualização rápida dos dados, o rastreamento dos motivos das ausências e o acompanhamento do histórico do colaborador. Além disso, o formato descentralizado comprometia a agilidade na tomada de decisão e exigia maior tempo para localizar informações específicas.', N'aprimorar a gestão das ausências de colaboradores e tornar o acompanhamento das informações mais eficiente, foi desenvolvida uma planilha padronizada para o controle de absenteísmo da unidade.', N'10017', N'01 - Imagens/01 - Antes/11487.jpeg', N'As informações eram compartilhadas no corpo dos e-mails, que dificultava a visualização rápida dos dados, o rastreamento dos motivos das ausências e o acompanhamento do histórico do colaborador.', N'01 - Imagens/02 - Depois/11487.jpeg', N'Planilha única e estruturada, reunindo informações relevantes em um único local. Ferramenta contempla dados como quantidade de dias, permitindo uma gestão visual organizada e de fácil atualização.', NULL, N'A implementação da planilha trouxe ganhos significativos para a rotina da unidade, dentre eles:
INSERT INTO #PVC VALUES (11488, N'81040231', N'81040231', N'Special waste re-routing', 1, N'No Replication/Sem replicação', N'Vale was incurring significant disposal and transportation costs by shipping certain waste streams through the Clean Harbors system to Quebec and other off-island facilities, while also experiencing operational constraints due to limited Clean Harbors bin availability. Opportunities exist to divert eligible waste streams to local disposal options such as Robin Hood Bay through Vardy''s, reducing transportation costs, freeing up bin inventory, and improving waste handling efficiency', N'Primary driver was avoiding costly transportation of waste to Quebec via Umiak and reducing reliance on limited Clean Harbors bin inventory', N'0', N'01 - Imagens/01 - Antes/11488.jpeg', N'Long Harbour was experiencing limited availability of Clean Harbors waste bins due to lengthy off-island disposal cycles, resulting in operational risk and high transportation costs.', N'01 - Imagens/02 - Depois/11488.jpeg', N'The team identified an opportunity to evaluate whether eligible waste streams could be diverted to local disposal facilities such as Robin Hood Bay through Vardy''s, reducing costs and improving bin availability. Savings of $137.5/ton on disposal and approximately $8000 per bin in transport costs depending on fsc. Assuming 1 bin per month of special waste annual savings would be about $120,000', NULL, N'Yes - Achieved by challenging the existing disposal process and finding a lower-cost local alternative for eligible waste streams.', N'Classify waste correctly and revisit/challenge classifications', 120000, 3, N'Agilidade ', '2026-01-01T00:00:00.000', '2026-07-30T15:29:31.000', N'81040231', NULL, NULL);
INSERT INTO #PVC VALUES (11489, N'81060533', N'81060533', N'SUPORTE ORGANIZADOR DE MATERIAIS', 3, N'Others/Outros', N'Os materiais permaneciam armazenados de forma inadequada, ocupando espaço, dificultando o acesso pelos colaboradores e comprometendo a organização do ambiente. Além disso, não havia um local padronizado para acondicionamento desses itens, o que gerava desperdícios de tempo durante a rotina e prejudicava a aplicação dos princípios do 5S.', N'fortalecer as práticas de Meio Ambiente e 5S, além de promover maior organização e padronização dos materiais de limpeza, foi desenvolvido um suporte organizador para armazenamento de papel-toalha e Perfex utilizando uma caixa plástica de hortifrúti reaproveitada.', N'10361', N'01 - Imagens/01 - Antes/11489.jpeg', N'Materiais eram armazenados de forma inadequada, ocupando espaço, dificultando o acesso pelos colaboradores e comprometendo a organização do ambiente. ', N'01 - Imagens/02 - Depois/11489.jpeg', N'Reaproveitamento de caixa hortifrúti para suporte organizador, com local adequado, identificado e de fácil acesso para o armazenamento do papel-toalha e Perfex. Reutilização de material que seria descartado, contribuindo para a redução de resíduos.', NULL, N'A implementação do suporte organizador trouxe diversos benefícios para a unidade, entre eles:
INSERT INTO #PVC VALUES (11490, N'81007314', N'81047010', N'Chapa de distanciamento do berço do DHR', 1, N'Others/Outros', N'Paradas em corretivas dos equipamentos da frota por folga na corrente de avanço, quebra de tirantes de tensionamento da corrente e mangueiras sacadas do tambor de mangueiras.
INSERT INTO #PVC VALUES (11491, N'369561', N'369561', N'Mudança de Metodologia do Plano A+3', 1, N'Open Pit/Poço aberto', N'Dificuldade e complexidade de alocação de escavadeiras manualmente nas frentes de lavra para um plano de 3 anos feito mês a mês (36 períodos).', N'Redução de tempo e flexibilidade na geração de cenários no plano de lavra A+3', N'10162', N'01 - Imagens/01 - Antes/11491.jpeg', N'Uso do Leveling para o sequenciamento de lavra. Para a elaboração do sequenciamento de lavra, era necessário fazer a alocação manualmente de todos os equipamentos de carga nos polígonos de lavra para um plano de 3 anos (36 meses). Essa atividade manual dificultava a geração de cenários diante das mudanças constantes de premissas dos equipamentos de cargas. Essa metodologia é ideal para horizontes de lavras operacionais, como planos de lavras semanais e mensais ', N'01 - Imagens/02 - Depois/11491.jpeg', N'Uso do Blend para o sequenciamento de lavra. Para a elaboração do sequenciamento de lavra com o blend, utilizamos as capacidades dos equipamentos de cargas como targets de movimentação por fases de lavra, sem uso manual de alocação de equipamentos. Essa metodologia facilita e flexibiliza a geração de cenários de lavra em tempo hábil para nossas entregas. Essa metodologia é ideal para horizontes de lavras de médio e longo prazo.', NULL, N'SIM. A nova metodologia foi testada e já utilizada nas atividades de rotina.', N'Eliminação de rotinas manuais', 0, NULL, N'Garantir um processo padronizado, rastreável e eficiente para o registro de resto ingestão, assegurando que 100% das informações e evidências fotográficas sejam armazenadas e compartilhadas de forma organizada por meio do Microsoft Forms e envio automático por e-mail.', '2026-05-01T00:00:00.000', '2026-07-30T17:17:10.000', N'369561', NULL, NULL);
INSERT INTO #PVC VALUES (11492, N'81057561', N'81057561', N'Cadastro de Fornecedores Alternativos', 1, N'Open Pit/Poço aberto', N'Antes da homologação, só tínhamos a opção de compra dos componentes com o fabricante do equipamentos, tais como, Sandvik, Komatsu e Epiroc. Elevado custo de compra, importação, logística dupla.
INSERT INTO #PVC VALUES (11493, N'978908', N'978908', N'Fórum de alinhamentos e validações prévias do plano trimestral rolante', 1, N'Others/Outros', N'Baixa integração entre os horizontes de planejamento, impactando diretamente a aderência do plano, a produtividade operacional e a utilização dos ativos.', N'Maior aderência ao planejamento, integração entre áreas operacionais, redução de desvios de execução, melhoria da previsibilidade da produção, governança estruturada do sequenciamento e maior alinhamento entre estratégia e operação.', N'10162', N'01 - Imagens/01 - Antes/11493.jpeg', N'Não aconteciam um fórum de alinhamentos e validações prévios para o plano trimestral rolante.', N'01 - Imagens/02 - Depois/11493.jpeg', N'Implementado fóruns mensais de alinhamentos e validações com as equipes operacionais para diligenciamento das atividades de infra, redes e linhas, perfuração e operação referentes ao plano trimestral rolante.', NULL, N'Sim. Atualmente reunimos mensalmente para alinhamentos das atividades para composição das premissas do plano trimestral rolante.', N'Engajamento das equipes.', 0, NULL, N'Implementar um sistema de acompanhamento visual e padronizado dos indicadores, proporcionando melhor gestão das informações, maior eficiência operacional e suporte às ações de melhoria contínua.', '2026-07-01T00:00:00.000', '2026-07-30T17:30:08.000', N'978908', NULL, NULL);
INSERT INTO #PVC VALUES (11494, N'978908', N'978908', N'Criação do Fluxo do Processo Master Plan D90', 1, N'Open Pit/Poço aberto', N'Falta de um fluxo padronizado para o processo recém criado do Master Plan de Polígonos de Desmonte.', N'Padronização ', N'10162', N'01 - Imagens/01 - Antes/11494.jpeg', N'Não existia um fluxo padrão para o processo recém criado do Master Plan de Polígonos de Desmonte.', N'01 - Imagens/02 - Depois/11494.jpeg', N'Criado e padronizado o fluxo do processo.', NULL, N'Sim', N'Ganho na assertividade / construção do plano trimestral.', 0, NULL, N'Otimização do processo.', '2026-07-27T00:00:00.000', '2026-07-30T17:50:15.000', N'978908', NULL, NULL);
INSERT INTO #PVC VALUES (11495, N'81022747', N'939199', N'ENGATE RAPIDO DE ABASTECIMENTO', NULL, N'Others/Outros', N'Para abastecer as caixas de água do pátio da perfuração era necessário remover a tampa para colocar a mangueira de abastecimento.', N'AGILIDADE', N'10144', N'01 - Imagens/01 - Antes/11495.jpeg', N'Para abastecer as caixas de água do pátio da perfuração era necessário remover a tampa para colocar a mangueira de abastecimento.', N'01 - Imagens/02 - Depois/11495.jpeg', N'foi instalado um engate rápido para facilitar o abastecimento.
INSERT INTO #PVC VALUES (11496, N'92000157', N'92000157', N'Relatório de acompanhamento dos desvios de preparação.', 1, N'Others/Outros', N'O acompanhamento dos desvios de materiais era realizado de forma manual e descentralizada, demandando elevado esforço para consolidação dos dados e dificultando a identificação dos principais ofensores e causas dos desvios.', N'Automatizar a consolidação e análise dos desvios de materiais', N'10269', N'01 - Imagens/01 - Antes/11496.jpeg', N'Dados dispersos em diferentes bases e controles, exigindo consolidação manual e limitando a agilidade das análises.', N'01 - Imagens/02 - Depois/11496.jpeg', N'Informações consolidadas em dashboard Power BI, com acompanhamento dos desvios por diferentes perspectivas e maior rapidez na identificação de oportunidades de atuação.', NULL, N'O relatório consolidou informações anteriormente dispersas, reduzindo o esforço de análise e aumentando a visibilidade dos desvios, atendendo ao objetivo de apoiar uma gestão mais eficiente e orientada por dados.', N'A estruturação e padronização dos dados são fundamentais para reduzir esforço operacional e aumentar a qualidade das análises e decisões.', 0, NULL, N'Este alarme antecipa e proporciona tempo hábil para acionar a operação e realizar a verificação em campo, mitigando o risco de desarme do bombeamento das torres de resfriamento, evitando cortes de alimentação da usina.
INSERT INTO #PVC VALUES (11497, N'81008286', N'81008286', N'New cage for nitrogen storage', 1, N'Others/Outros', N'old cage was rusted and signage was no longer legible', N'replace with new cage', N'0', N'01 - Imagens/01 - Antes/11497.jpeg', N'old cage was rusted, signage wasn''t legible, doors would not open properly.', N'01 - Imagens/02 - Depois/11497.jpeg', N'New cage to replace old one, proper signage installed.', NULL, N'yes.', N'n/a', 0, NULL, N'Melhor acompanhamento das aderências entre planos D90 e D30 para uma tomada de ação preditiva.', '2026-05-11T00:00:00.000', '2026-07-30T21:11:07.000', N'81008286', NULL, NULL);
INSERT INTO #PVC VALUES (11498, N'81008286', N'81008286', N'New valve for pressure bleed off', 2, N'Refining/Refino', N'There was no way to bleed off water pressure to this particular hose.', N'add valve for safe disconnect', N'0', N'01 - Imagens/01 - Antes/11498.jpeg', N'No shut off where hose connects, had to leave water in line when disconnecting the hose further up.', N'01 - Imagens/02 - Depois/11498.jpeg', N'Shut off valve added, allowing to stop flow of water and safely disconnect hose further down the line.', NULL, N'Yes, water can now be shut off and hose disconnected properly.', N'quick fix can save time and risks', 0, NULL, N'An alternative Muck Circuit was developed and validated using the Waste System', '2026-05-19T00:00:00.000', '2026-07-30T21:30:16.000', N'81008286', NULL, NULL);
INSERT INTO #PVC VALUES (11499, N'92000157', N'92000157', N'Reestruturação da base de acompanhamento da OTIF', 1, N'Others/Outros', N'A análise dos desvios identificados na OTIF dependia da consulta manual de informações em diferentes transações do SAP, demandando elevado esforço operacional e limitando a eficiência das investigações. Além disso, a estrutura das planilhas não favoreciam o desenvolvimento de relatórios em power BI para consolidação dos dados.', N'Automatizar a obtenção e consolidação de informações utilizadas na análise dos desvios de materiais, reduzindo o esforço manual e aumentando a disponibilidade de dados para tomada de decisão.', N'10269', N'01 - Imagens/01 - Antes/11499.jpeg', N'As informações utilizadas nas análises, como MRP, máximos, mínimos e características das ordens, precisavam ser consultadas individualmente no SAP, tornando o processo lento e suscetível a falhas.', N'01 - Imagens/02 - Depois/11499.jpeg', N'A planilha de acompanhamento foi reformulada e integrada a bases do SAP BO, permitindo o preenchimento automático de informações relevantes para análise dos desvios, como MRP, parâmetros de máximo e mínimo dos materiais e dados das ordens de manutenção. Com isso, os dados passaram a ser disponibilizados de forma estruturada, padronizada e adequada para análises e consolidação de indicadores.', NULL, N'A solução eliminou grande parte das consultas manuais necessárias para obtenção das informações de análise, disponibilizando os dados de forma consolidada e estruturada, em linha com o objetivo de tornar a avaliação dos desvios mais eficiente e produtiva.', N'A automação e o enriquecimento dos dados na origem reduzem significativamente o esforço analítico e ampliam o potencial de utilização das informações.', 0, NULL, N'mitigar o extravio de grampeadores  por falta de identificação', '2026-07-20T00:00:00.000', '2026-07-30T21:32:15.000', N'92000157', NULL, NULL);
INSERT INTO #PVC VALUES (11500, N'81047804', N'50004', N'Portão da bica de metal ', 2, N'Refining/Refino', N'Não pode fica  aberto risco de queda ', N'segurança ', N'10049', N'01 - Imagens/01 - Antes/11500.jpeg', N'Portão menor fora do padrão ', N'01 - Imagens/02 - Depois/11500.jpeg', N'Feita a melhoria e portão padronizador ', NULL, N'sim', N'Foco em segurança', 0, NULL, N'Aumento da confiabilidade dos dados utilizados nas análises de manutenção e confiabilidade, melhoria da qualidade dos apontamentos de parada, maior padronização dos critérios de classificação e identificação de oportunidades de capacitação das equipes.', '2026-07-25T00:00:00.000', '2026-07-30T21:53:58.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11501, N'81047804', N'487432', N'Portão do forno panela ', 2, N'Refining/Refino', N'Melhora o acesso e liberação do caminho seguro ', N'Melhora acesso ', N'10049', N'01 - Imagens/01 - Antes/11501.jpeg', N'atrapalhando o acesso ao caminho seguro ', N'01 - Imagens/02 - Depois/11501.jpeg', N'Fazer a liberação do caminho para melhora o acesso do caminho seguro', NULL, N'sim', N'Foco em segurança ', 0, NULL, N'Completed critical liner replacement without shutting down ore production.
INSERT INTO #PVC VALUES (11502, N'81047804', N'487432', N'Caixa de epi ', 2, N'Refining/Refino', N'Melhora o acesso aos amostrado e elimina o risco de batida contra ', N'Elimina riscos ', N'10049', N'01 - Imagens/01 - Antes/11502.jpeg', N'Dificildade para tira o amostrado podendo bate a mão contra caixa de epi ', N'01 - Imagens/02 - Depois/11502.jpeg', N'caixa de epi realocada eliminando o risco de batida contra ', NULL, N'Sim ', N'Segurança ', 0, NULL, N'aumento da produtividade e segurança', '2026-07-02T00:00:00.000', '2026-07-30T22:24:51.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11503, N'81047804', N'487432', N'Suporte do aluminizado ', 3, N'Refining/Refino', N'Falta de local adequado para colocação do epi ', N'5S', N'10049', N'01 - Imagens/01 - Antes/11503.jpeg', N'Falta de local adequado perto do local de trabalho para o armazenamento do  epi aluminizado ', N'01 - Imagens/02 - Depois/11503.jpeg', N'Suporte adequado para aluminizado próximo ao local de trabalho ', NULL, N'Sim ', N'5S e organização ', 0, NULL, N'Promoting a proper place to secure materials helps ensure crews are following the proper steps to return items as well ensuring safety by not dropping objects.', '2026-07-02T00:00:00.000', '2026-07-30T23:08:09.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11504, N'81045351', N'81045351', N'Implantação de Formulário Digital para Registro de Evidências e Monitoramento do Resto Ingestão nos Refeitórios', 1, N'Projects/Projetos', N'O acompanhamento do resto ingestão dos refeitórios era realizado por meio de mensagens em grupos de WhatsApp, dificultando a organização das informações, a rastreabilidade dos registros, a consulta ao histórico e a consolidação dos dados. A ausência de um processo padronizado comprometia a gestão das evidências e o monitoramento efetivo dos resultados.', N'Garantir 100% dos registros de resto ingestão com evidências fotográficas e informações padronizadas em plataforma digital, proporcionando rastreabilidade, histórico de dados e melhor acompanhamento dos indicadores dos refeitórios.', N'10017', N'01 - Imagens/01 - Antes/11504.jpeg', N'O registro das informações e evidências fotográficas do resto ingestão era realizado por meio de grupos de WhatsApp. Esse processo dificultava a padronização das informações, a rastreabilidade dos registros e a consulta ao histórico das evidências. Além disso, a busca por dados anteriores era demorada, havia risco de perda de informações em meio às mensagens e a consolidação dos dados para acompanhamento dos refeitórios era realizada de forma manual e pouco eficiente.', N'01 - Imagens/02 - Depois/11504.jpeg', N'Com a implantação do Microsoft Forms, os registros de resto ingestão passaram a ser realizados em um formulário padronizado, permitindo o preenchimento das informações e o envio das evidências fotográficas em um único ambiente. Após o preenchimento, as respostas são encaminhadas automaticamente por e-mail, garantindo que as informações fiquem registradas, organizadas e acessíveis para consulta e acompanhamento.
INSERT INTO #PVC VALUES (11505, N'81047804', N'487338', N'Rolete do escudo  ', 2, N'Refining/Refino', N'Dificuldade da remoção do plugue com o tubo ', N'Melhora a ergonomia ', N'10049', N'01 - Imagens/01 - Antes/11505.jpeg', N'Rolete avariado e travado dificultando a remoção da plugue da panela com a utilização de tubo', N'01 - Imagens/02 - Depois/11505.jpeg', N'Substituição por roletes com rolamentos evitando travamentos ', NULL, N'Sim ', N'Segurança e ergonomia ', 0, NULL, N'Easier and safer to preform isolation.  ', '2026-07-13T00:00:00.000', '2026-07-30T23:42:23.000', N'81047804', NULL, NULL);
INSERT INTO #PVC VALUES (11506, N'81045351', N'81045351', N'Criação de planilha gerencial com acompanhamento gráfico dos indicadores de Parada de Fila e Corpo Estranho', 1, N'Others/Outros', N'Os registros e acompanhamentos dos indicadores de Parada de Fila e Corpo Estranho eram realizados e armazenados por meio de trocas de e-mails, dificultando a consolidação das informações, a consulta ao histórico e a visualização da evolução dos resultados ao longo dos meses. A ausência de uma ferramenta centralizada gerava maior tempo para análise dos dados e limitava a identificação rápida de tendências e oportunidades de melhoria.', N'Desenvolver uma planilha de controle com atualização mensal e visualização gráfica dos principais indicadores de Parada de Fila e Corpo Estranho, proporcionando maior agilidade na análise dos resultados, acompanhamento da evolução mensal e suporte à tomada de decisão.', N'10017', N'01 - Imagens/01 - Antes/11506.jpeg', N'O acompanhamento dos indicadores de Parada de Fila e Corpo Estranho era realizado por meio de registros enviados e armazenados em e-mails. As informações ficavam descentralizadas, dificultando a consulta ao histórico, a consolidação dos dados e a visualização da evolução dos resultados ao longo dos meses. O processo demandava mais tempo para análise e acompanhamento dos indicadores.', N'01 - Imagens/02 - Depois/11506.jpeg', N'Foi desenvolvida uma planilha gerencial com gráficos de acompanhamento mensal, reunindo em um único local todas as informações dos indicadores de Parada de Fila e Corpo Estranho. A nova ferramenta permite visualizar rapidamente a evolução dos resultados, facilita a consulta ao histórico, agiliza as análises e apoia a tomada de decisão, tornando o monitoramento mais eficiente e padronizado.', NULL, N'A melhoria implementada atendeu integralmente à meta proposta, proporcionando melhor gestão visual dos indicadores, redução do tempo de consulta das informações e maior agilidade na análise dos resultados.', N'A transformação de um processo baseado em trocas de e-mails para uma ferramenta estruturada de controle e acompanhamento permitiu maior visibilidade dos resultados, otimização do tempo de análise e melhoria na gestão dos indicadores de qualidade.', 0, NULL, N'Economia Mensal:  R$ 366.919,08 
INSERT INTO #PVC VALUES (11507, N'521673', N'471863', N'Identificação de inicio da coleta de perolas', 1, N'No Replication/Sem replicação', N'Anteriormente, não existia uma identificação para indicar o início da primeira amostra da leitura.', N'Otimizar o processo', N'10366', N'01 - Imagens/01 - Antes/11507.jpeg', N'Anteriormente, não havia uma identificação que indicasse o início da primeira amostra da leitura, o que levava o técnico a gastar tempo verificando em qual lado deveria iniciar a leitura.', N'01 - Imagens/02 - Depois/11507.jpeg', N'A identificação do início da primeira amostra proporcionou maior segurança na execução da leitura, reduzindo a ocorrência de erros operacionais, especialmente em situações em que a identificação do balão se encontra comprometida ou com falhas.', NULL, N'Sim. A implementação da identificação do início da primeira amostra reduziu o tempo gasto pelos técnicos na localização do ponto inicial da leitura, tornando o processo mais ágil, padronizado e eficiente, além de minimizar possíveis erros de interpretação.', N'Rapidez e qualidade na coleta', 0, NULL, N'Making fueling of equipment safer and easier for all employees', '2026-07-27T00:00:00.000', '2026-07-31T00:47:39.000', N'521673', NULL, NULL);
INSERT INTO #PVC VALUES (11508, N'33019', N'33019', N'Padronização e Modernização da apresentação orçamentaria de 2026 3Y 3Y', 1, N'Others/Outros', N'Excesso de informações visuais.
INSERT INTO #PVC VALUES (11509, N'81037761', N'81037761', N'Alarme Crítico Prevenção de Desarme das Bombas por Nível Baixo nas Torres de Resfriamento dos Prensas.', 1, N'No Replication/Sem replicação', N'Quando ocorre a redução do nível de água nas torres de resfriamento dos prensas do Salobo 3, há uma redução na corrente da bomba. Essa condição pode não ser percebida em tempo hábil pelo técnico da sala de controle para acionar a operação e realizar a verificação em campo, podendo resultar no desarme da bomba e em cortes de alimentação da usina. 
INSERT INTO #PVC VALUES (11510, N'81047331', N'81047331', N'Curvas de Aderência Interplanos', 1, N'Others/Outros', N'Não rastreabilidade da aderência entre o plano D90 e o plano D30. ', N'Maior assertividade no sequenciamento ', N'#N/A', N'01 - Imagens/01 - Antes/11510.jpeg', N'Não havia esses indicadores', N'01 - Imagens/02 - Depois/11510.jpeg', N'Melhoria de visualização e controle da aderência entre planos.', NULL, N'Melhor visualização da aderência entre planos para uma melhor tomada de ação preditiva.', N'Importância da rastreabilidade dos processos', 0, NULL, N'Neon Green lanyard also makes wrenches location easy to spot.', '2026-07-28T00:00:00.000', '2026-07-31T08:57:26.000', N'81047331', NULL, NULL);
INSERT INTO #PVC VALUES (11511, N'477830', N'300740', N'Alternative Muck Circuit', 1, N'Underground/Subterrâneo', N'The current muck circuit relies on the 3800 Coarse Ore Bin (COB), underground Crusher, and Conveyor #2. Any major maintenance or extended repairs on these assets require production interruptions.', N'Develop and validate an alternative ore handling process that allows ore production to continue while the 3800 COB, Crusher, and Conveyor #2 are out of service for planned or unplanned maintenance activities.', N'10288', N'01 - Imagens/01 - Antes/11511.jpeg', N'Ore production relied entirely on the primary muck circuit through the 3800 Coarse Ore Bin (COB), underground Crusher, and Conveyor #2. Any major maintenance or extended repairs on these assets required production interruptions. The mine had no proven alternative route to maintain ore production while these assets were out of service.', N'01 - Imagens/02 - Depois/11511.jpeg', N'An Alternative Muck Circuit was developed and validated using the Waste System to bypass the 3800 COB, Crusher, and Conveyor #2. Ore can now be hoisted through the waste stream and routed to surface for crushing, allowing production to continue during planned or unplanned outages of the primary muck circuit.', NULL, N'The process was successfully risk assessed and demonstrated during a two-day Conveyor #2 belt repair, providing a reliable contingency option and increased flexibility for future maintenance activities.', N'Alternative ore circuit proved', 0, NULL, NULL, '2026-06-03T00:00:00.000', '2026-07-31T08:58:49.000', N'477830', NULL, NULL);
INSERT INTO #PVC VALUES (11512, N'81058052', N'81058052', N'tagueamento de grampeadores', 3, N'Others/Outros', N'grampeadores sem identificação eram extraviados ao serem emprestados para outras áreas 
INSERT INTO #PVC VALUES (11513, N'81059325', N'81059325', N'INDICADOR - QUALIDADE DAS CLASSIFICAÇÕES DE PARADA', 1, N'Others/Outros', N'Não havia um mecanismo para avaliar a assertividade das classificações de paradas registradas no sistema. Essa ausência gerava risco de distorções nas análises de confiabilidade e manutenção, uma vez que classificações inadequadas poderiam impactar a identificação das principais causas de perda dos ativos. Dessa forma, surgiu a necessidade de criar um indicador para medir e acompanhar a qualidade das classificações realizadas.', N'Verificar a aderência entre a classificação registrada para a parada e a intervenção efetivamente executada, garantindo maior confiabilidade das informações utilizadas nas análises de manutenção e confiabilidade.', N'10015', N'01 - Imagens/01 - Antes/11513.jpeg', N'Não havia um mecanismo para avaliar a assertividade das classificações de paradas registradas no sistema. Essa ausência gerava risco de distorções nas análises de confiabilidade e manutenção, uma vez que classificações inadequadas poderiam impactar a identificação das principais causas de perda dos ativos. Dessa forma, surgiu a necessidade de criar um indicador para medir e acompanhar a qualidade das classificações realizadas.', N'01 - Imagens/02 - Depois/11513.jpeg', N'Foi implantado um processo de auditoria das classificações de paradas, com avaliação amostral trimestral dos registros realizados pelas equipes.
INSERT INTO #PVC VALUES (11514, N'477830', N'477830', N'Surface Ore Bin Alternative Routing', 1, N'Underground/Subterrâneo', N'The current ore handling process relies on the Surface Ore Bin to load surface trucks and transport ore to the Ore Tent. Any major maintenance or repair work on the Surface Ore Bin requires shutting down the ore system, resulting in production losses.', N'Replace worn liners in the Surface Ore Bin while maintaining ore production and minimizing the impact on operations.', N'10288', N'01 - Imagens/01 - Antes/11514.jpeg', N'Ore was routed exclusively through the Surface Ore Bin before being loaded into trucks and transported to the Ore Tent. Because no alternate route existed, extended maintenance on the bin would have required shutting down ore handling activities, directly affecting production.', N'01 - Imagens/02 - Depois/11514.jpeg', N'An alternative ore routing process was assessed, reviewed, risk-evaluated, and successfully implemented. During daytime shifts, maintenance crews can work in the ore bin. During night shifts, the tilt chute redirected to the Waste Bin, bypassing the Surface Ore Bin.
INSERT INTO #PVC VALUES (11515, N'81058052', N'81058052', N'etiquetagem de caixas de bloqueio de leves', 3, N'Others/Outros', N'a falta de identificação nas caixas de bloqueio dificultava a liberação dos equipamentos sempre que era necessário fazer o desbloqueio dos equipamentos junto aos operadores. ', N'indentificar as caixas de bloqueio por meio de etiquetas impressas ', N'10346', N'01 - Imagens/01 - Antes/11515.jpeg', N'caixas de bloqueio sem identificação para determinar quais equipamentos estavam bloqueados . ', N'01 - Imagens/02 - Depois/11515.jpeg', N'aplicadas etiquetas para fácil descrição dos equipamentos bloqueados na oficina.', NULL, N'sim ,o problema foi resolvido com a identificação das caixas de bloqueio possibilitando a rastreabilidade das chaves debloqueio dos equipamentos de imediato.', N'pequenas ações garantem o aumento de produtividade ', 0, NULL, N'Eliminar o risco de tropeço, melhorar a ergonomia durante a execução das atividades, proporcionar maior segurança e conforto ao colaborador, facilitar o acesso ao componente e aumentar a eficiência e a padronização dos serviços de manutenção.', '2026-07-06T00:00:00.000', '2026-07-31T09:40:40.000', N'81058052', NULL, NULL);
INSERT INTO #PVC VALUES (11516, N'81055952', N'81055952', N'Banding Station 221 SMA Shop', 3, N'Others/Outros', N'Material to be sent back to warehouse continuously being strapped down by ratchet straps', N'Save on Material', N'0', N'01 - Imagens/01 - Antes/11516.jpeg', N'Material to be sent back to warehouse continuously being strapped down by ratchet straps', N'01 - Imagens/02 - Depois/11516.jpeg', N'Set up proper banding station to secure materials going back to warehouse.', NULL, N'Worked out Great', N'Save on straps', 1000, 3, N'Essa adequação permitiu a operação com segurança do ativo de R$ 250.000,00, recuperando a capacidade produtiva de 360 amostras por dia (10.800/mês).', '2026-07-30T00:00:00.000', '2026-07-31T10:00:37.000', N'81055952', NULL, NULL);
INSERT INTO #PVC VALUES (11517, N'81003675', N'81003675', N'Treinamento pratico inversores.', 2, N'Others/Outros', N'Não tinhamos além do dojo uma forma adequada e segura para que os colaboradores tivessem  acesso aos inversores para um primeiro contato de instalação e parametrização', N'Capacitar colaboradores para implementação básica de conexão e parametrização de inversores de frequência.', N'10038', N'01 - Imagens/01 - Antes/11517.jpeg', N'Somente era possível ministrar treinamento na área do dojo de elétrica pois dependia-se da bancada para simular os exercícios.
INSERT INTO #PVC VALUES (11518, N'1015316', N'1015316', N'Mill extension isolations', 2, N'Concentration/Concentração', N'Isolating interments at the mill extension requires opening the PLC cabinet or pulling wires off the TB to perform a task. This is a bigger risk to the assets and the persons involved. ', N'To make it easier and safer to isolate valves and other instruments at the mill extension', N'10359', N'01 - Imagens/01 - Antes/11518.jpeg', N'We previously had to open the PLC cabinets, which are located in the field, to isolate valves and other instruments.', N'01 - Imagens/02 - Depois/11518.jpeg', N'We installed isolation terminal blocks (shown above the red line), while the wiring below the red line represents the original configuration. These terminal blocks allow instruments to be isolated safely and efficiently without opening the PLC cabinets.
INSERT INTO #PVC VALUES (11519, N'496972', N'496972', N'Mercado interno - Redução nos custos de transporte', 1, N'Others/Outros', N'Altos custos com TRANSPORTE DE FERRO NIQUEL PARA CLIENTES DO MERCADO INTERNO, 
INSERT INTO #PVC VALUES (11520, N'81031571', N'81031571', N'Sure Can Fuel ', 2, N'Underground/Subterrâneo', N'To reduce spillage of fuel and splash back on employees while fueling equipment with fuel can', N'Prevent Fuel spills on Employees', N'0', N'01 - Imagens/01 - Antes/11520.jpeg', N'This style of can causes issues with splash back on employees.', N'01 - Imagens/02 - Depois/11520.jpeg', N'This style of fuel can with a nozzel and valve help prevent splash back and make fueling easier to control.', NULL, N'Initial goal was to make fueling equipment easier and safer for employees and has been a success to using the basic style can', N'New Style can is more efficient and easier to use', 0, NULL, N'Ganho na produtividade da equipe de Automação principalmente, que conseguem se planejar melhor e atender mais de uma demanda.', '2026-07-30T00:00:00.000', '2026-07-31T11:17:37.000', N'81031571', NULL, NULL);
INSERT INTO #PVC VALUES (11521, N'81064844', N'1010414', N'Deisel Fuel Storgae Tank - Inspection Interval Extension', 1, N'Refining/Refino', N'The current inspection interval for the LH Deisel Fuel storage tank (580-TNK-009) was no practical from a scheduling standpoint. It was believed that a detailed risk assessment could all for the inspection interval to be extended. The current inspections interval was 3years for both internal and external inspections', N'Extend Inspection Interval of 580-TNK-009', N'10006', N'01 - Imagens/01 - Antes/11521.jpeg', N'Previous Inspection interval 3 year internal/ External', N'01 - Imagens/02 - Depois/11521.jpeg', N'Updated Inspection Interval is 5 year Ext / 10 Year Int', NULL, N'By reviewing inspection reports and, estimating corrosion rates calculating minimum wall thickness of tank nozzle, it was determined that the internal inspection interval could be extended from 3 years to 10 year.', N'Look for oppertunities to extended intervals when there is low risk', 0, NULL, N'Redução de 100% do risco de cortes nas bordas do suporte de copos, garantindo um ambiente de trabalho mais seguro.', '2026-07-28T00:00:00.000', '2026-07-31T12:11:35.000', N'81064844', NULL, NULL);
INSERT INTO #PVC VALUES (11522, N'81020808', N'81020808', N'Planilha Unificada de Horímetros para Inspeção de Pneus', 1, N'Others/Outros', N'Era necessário acessar o SAP e consultar os equipamentos individualmente para coletar os horímetros. Esse processo demandava elevado tempo de execução, além de aumentar o risco de erros na transcrição das informações.', N'Redução de tempo na coleta de dados e confiabilidade.', N'10023', N'01 - Imagens/01 - Antes/11522.jpeg', N'Antes da implementação da planilha unificada, era necessário acessar o SAP e consultar os equipamentos individualmente para coletar os horímetros. Esse processo demandava elevado tempo de execução, além de aumentar o risco de erros na transcrição das informações.', N'01 - Imagens/02 - Depois/11522.jpeg', N'Foi desenvolvida uma planilha unificada de horímetros para inspeção de pneus, contemplando todas as frotas em operação. A ferramenta está integrada às planilhas de controle atualizadas pelos programadores de manutenção de cada frota, realizando a importação automática dos horímetros dos equipamentos.', NULL, N'Maior eficiência no processo de inspeção, melhoria da qualidade dos dados e aumento da assertividade no planejamento das ações de manutenção relacionadas aos pneus da frota.', N'Com essa automatização, as inspeções de pneus passam a utilizar dados atualizados em tempo real, eliminando lançamentos manuais, reduzindo riscos de erros de digitação e aumentando a confiabilidade das informações utilizadas no monitoramento da vida útil dos pneus.', 0, NULL, N'Garantir monitoramento automático e em tempo real das separações, permitindo identificar desvios rapidamente e aumentar a aderência das OTIFs da Mina e da Usina.', '2026-07-30T00:00:00.000', '2026-07-31T13:25:50.000', N'81020808', NULL, NULL);
INSERT INTO #PVC VALUES (11523, N'81053928', N'81053928', N'Use Of Lanyards', 2, N'Refining/Refino', N'Valve wrench for turning valves just left on ledge of I beam , which could fall and hit someone.', N'stop object from falling ', N'10283', N'01 - Imagens/01 - Antes/11523.jpeg', N'Valve wrench just left on ledge with possibility of falling.', N'01 - Imagens/02 - Depois/11523.jpeg', N'I attached the valve wrench to a fixed position next to the valves with a lanyard . Making it easier to spot and impossible to fall possibly hitting someone.', NULL, N'yes the problem was solved because now by adding a lanyard to the valve wrench should stop it from falling to the ground.', N'Dropped objects', 0, NULL, NULL, '2026-07-30T00:00:00.000', '2026-07-31T14:04:19.000', N'81053928', NULL, NULL);
INSERT INTO #PVC VALUES (11524, N'81050431', N'81058947', N'BANCADA DE CORTE', 3, N'Others/Outros', N'Bancada de corte em alto estado de desgaste.', N'custo evitado', N'10139', N'01 - Imagens/01 - Antes/11524.jpeg', N'Bancada de corte em alto estado de desgaste.', N'01 - Imagens/02 - Depois/11524.jpeg', N'Bancada de corte  foi feito uma  recuperação com revitalização e com material novo.', NULL, N'Bancada de corte  foi feito uma  recuperação com revitalização e com material novo', N'economia', 1, 1, N'GANHOS EXCELENTES PARA ELIMINAR PENDÊNCIAS PELA FALTA DE MATERIAIS NO KANBAN ELÉTRICA.', '2026-07-03T00:00:00.000', '2026-07-31T14:26:38.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (11525, N'141002', N'141002', N'Implantação de Informativo Diário de Estoque de Minério ', 1, N'Others/Outros', N'Falta de uma ferramenta de comunicação diária e padronizada para divulgação dos estoques de minério, impactando a eficiência da gestão operacional, o planejamento das atividades e o acompanhamento dos níveis de estoque.', N'esenvolver e implementar um Informativo Diário de Estoque de Minério, consolidando as principais informações de forma clara, visual e acessível para as equipes operacionais e de gestão.', N'10180', N'01 - Imagens/01 - Antes/11525.jpeg', N'As informações de estoque de minério encontravam-se dispersas em diferentes controles e consultas, dificultando a rápida visualização da situação operacional. A ausência de um informativo padronizado exige análises manuais para obtenção dos dados, aumentando o tempo de tomada de decisão e o risco de divergências nas informações.', N'01 - Imagens/02 - Depois/11525.jpeg', N'Implementação de um informativo diário de estoque de minério, consolidando dados de estoque, movimentações e indicadores operacionais em um único relatório padronizado. A iniciativa visa aumentar a visibilidade das informações, agilizar a tomada de decisão e melhorar a gestão dos estoques, reduzindo o tempo gasto na obtenção e análise dos dados.', NULL, N'A ausência de um informativo diário dificulta o acompanhamento dos níveis de estoque, da ocupação dos pátios e das movimentações realizadas, limitando a velocidade na tomada de decisões operacionais e no planejamento das atividades. Além disso, a falta de gestão visual reduz a percepção antecipada de possíveis desvios, como níveis críticos de estoque ou restrições operacionais, podendo impactar a eficiência da cadeia produtiva.', N'Gestão visual dos indicadores permitindo identificar desvios e riscos com antecedência', 0, NULL, N'O SERVIÇO DE SOLDA LEVA E MEDIA DUAS HORAS, SENDO QUE COM A TRAVA A ATIVIDADE É REALIZADA EM 20 MINUTO', '2026-07-30T00:00:00.000', '2026-07-31T14:30:16.000', N'141002', NULL, NULL);
INSERT INTO #PVC VALUES (11526, N'81043438', N'81037700', N'Modificação do sistema propulsão da bomba', 1, N'Projects/Projetos', N'Foi identificado baixo desempenho da bomba BP_2057_22, ocasionado pela alteração do fator de espuma do produto bombeado, resultando no aumento da recirculação interna da bomba durante o bombeamento para o DI_2057_06.', N'Melhorar o desempenho da bomba de polpa flotação', N'10178', N'01 - Imagens/01 - Antes/11526.jpeg', N'A bomba BP_2057_22, responsável pelo bombeamento de polpa para o DI_2057_06, apresentou redução de desempenho em função da elevação do fator de espuma do produto bombeado. Durante a análise, foi identificada a operação da bomba em uma posição inadequada para as condições de elevado fator de espuma. Adicionalmente, constatou-se a existência de uma redução no recalque da tubulação, bem como incrustações em seu interior, fatores que contribuíram para a restrição do fluxo e para a perda de eficiência do sistema de bombeamento.', N'01 - Imagens/02 - Depois/11526.jpeg', N'Foi realizado um estudo de engenharia pela equipe de Engenharia de Confiabilidade, em conjunto com as equipes de PCM e Execução, no qual foi identificado que, para restabelecer e otimizar o desempenho do sistema de bombeamento, seria necessária a alteração da posição de operação da bomba, a substituição do rotor por um modelo mais adequado às condições operacionais e o redimensionamento da tubulação de recalque, visando reduzir as perdas de carga e aumentar a eficiência do sistema', NULL, N'Sim, foi instalado um novo modelo de rotor mais indicado para fator alto de espuma, foi modificado a posição de operação da bomba e aumentador o diâmetro da tubulação de recalque. ', N'A troca do rotor permitiu a recuperação da eficiência operacional da bomba BP_2057_22, confirmando a relevância do acompanhamento sistemático de desempenho como ferramenta para prevenção de perdas de capacidade e confiabilidade do equipamento.', 0, NULL, N'Controle de sobrecarga e falha instantâneo.', '2026-07-21T00:00:00.000', '2026-07-31T14:32:58.000', N'81043438', NULL, NULL);
INSERT INTO #PVC VALUES (11527, N'486546', N'486546', N'Eliminação de Risco Crítico por Segregação do Tráfego de Pessoas e Combustíveis', 2, N'Others/Outros', N'O embarque e desembarque de colaboradores é realizado em um acesso compartilhado entre ônibus de transporte de pessoas e carretas de diesel, em área com espaço reduzido e sem condições adequadas para manobras seguras. A ocorrência de fluxo simultâneo, especialmente nos horários administrativos, aumenta significativamente o risco de colisões e exige manobras críticas, como marcha à ré em rampa com carretas carregadas, elevando a exposição a riscos operacionais no transporte de pessoas.
INSERT INTO #PVC VALUES (11528, N'81006946', N'81006946', N'TRAVA DO BRAÇO DE DIREÇÃO DO CARRO DE BAIXAR PEITO DE TRATOR', 2, N'Others/Outros', N'BRAÇO DE DIREÇÃO FICAVA NO CHÃO', N'POSICINAR O BRAÇO EM POSIÇÃO DE MELHOR ACESSO', N'10139', N'01 - Imagens/01 - Antes/11528.jpeg', N'Condição identificada: O braço permanecia na altura do solo, criando uma condição insegura por representar risco de tropeço e queda para as pessoas que circulam na área. Além disso, a posição exigia que o colaborador realizasse movimentos de flexão excessiva durante a operação, gerando desconforto ergonômico e aumentando o risco de lesões musculoesqueléticas.', N'01 - Imagens/02 - Depois/11528.jpeg', N'Com a aplicação da trava do braço, o componente passou a permanecer em uma posição elevada e estável, proporcionando melhor acesso para a execução das atividades. A melhoria eliminou o risco de tropeço, reduziu o esforço ergonômico do colaborador e aumentou a segurança durante a realização dos serviços.', NULL, N'SIM! SE MANTERMOS AS ORIENTAÇÕES E PROCEDIMENTOS', N'A identificação e correção de condições inseguras antes da execução das atividades são fundamentais para prevenir acidentes.', 0, NULL, NULL, '2026-07-30T00:00:00.000', '2026-07-31T14:51:34.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (11529, N'52548', N'471876', N'Otimização de Ativo Crítico: Redução de Ruído no Exaustor BOR004 e Retorno Operacional', 2, N'Others/Outros', N'A operação do exaustor BOR004 na Sala de Absorção Atômica gerava um ruído contínuo de 79,6 dB(A), tornando o ambiente em uma zona de incerteza técnica perante as diretrizes das normas NR-09, NR-15 e NHO 01. Sob o ponto de vista da saúde ocupacional, esse cenário expunha diretamente a equipe técnica e operacional a patologias, tais como fadiga psíquica, irritabilidade e perda auditiva induzida por ruído. Em decorrência do severo impacto ergonômico e visando resguardar a integridade física dos colaboradores, eles deixavam de utilizar o equipamento. Resultando na ociosidade completa de um ativo crítico de alto valor tecnológico, avaliado em R$ 250.000,00, tornando-se em um custo improdutivo para a empresa. Sob a ótica operacional, a paralisação do maquinário fez a unidade deixar de processar cerca de 360 amostras por dia, o que culminou em um déficit acumulado de 10.800 análises mensais não realizadas.', N'Garantir a Segurança Ocupacional: Eliminar o risco à saúde dos operadores de laboratório, reduzindo a exposição ao ruído contínuo e cumprindo os requisitos normativos de Higiene Ocupacional. Recuperar Capacidade Produtiva.', N'10155', N'01 - Imagens/01 - Antes/11529.jpeg', N'Foi medido com um sonômetro o nível de Ruido 79,6 dB(A) no exaustor BOR004 da Sala de Absorção atômica, caracterizando ruido no nível de incerteza em relação ao Nível de Ação do limite de exposição. ', N'01 - Imagens/02 - Depois/11529.jpeg', N'Após Substituição do exaustor BOR004, o novo nível de ruído medido foi de 65,1 dB(A), constatando redução de 14,5 dB(A), na geração de ruido do equipamento.', NULL, N'Sim, o Kaizen resolveu o problema ao substituir o exaustor BOR004, reduzindo o ruído em 14,5 dB(A) e eliminando os riscos à saúde, e adequando o conforto acústico dos colaboradores. ', N'Impactos de pequenas intervenções, A importância da escuta ativa, e Importância do Monitoramento Preventivo.', 0, NULL, N'melhoria na condição ergonômica e de organização da area', '2026-07-06T00:00:00.000', '2026-07-31T15:05:58.000', N'52548', NULL, NULL);
INSERT INTO #PVC VALUES (11530, N'535031', N'535031', N'Cronograma D90', 1, N'Others/Outros', N'O master plan não tinha um acompanhamento que apontasse as não realização do plano no tempo correto e com avanço planejado, além de não possuir visibilidade das atividades criticas para o bom andamento da mina. ', N'Acompanhar a aderência das atividades programada no D90', N'10161', N'01 - Imagens/01 - Antes/11530.jpeg', N'A inexistência de um controle estruturado das atividades limitava a visibilidade do time sobre a aderência ao plano de 90 dias. Com isso, os replanejamentos mensais ocorriam sem rastreabilidade histórica das atividades reprogramadas e dos desvios acumulados.', N'01 - Imagens/02 - Depois/11530.jpeg', N'Atualmente, é possível mensurar as reprogramações, controlar a aderência entre os planos e acompanhar o histórico das atividades. A implementação do cronograma trouxe uma visão sequenciada das atividades alinhada à lógica operacional das equipes executoras, proporcionando visibilidade por polígono das etapas realizadas e das próximas ações necessárias. Como benefício adicional, o cronograma antecipa a visão do sequenciamento operacional, contribuindo para a otimização do processo de elaboração do plano D30 e para uma tomada de decisão mais assertiva.', N'https://globalvale.sharepoint.com/:f:/s/PlanejamentoSLB-MdioPrazo/IgBE5Uky9RU4SqkDXLUdn80OAQLeIh_Ho6KncOvneUFwWsU?email=c0726735%40vale.com&e=vfO7ts', N'Melhor do que o esperado, trouxe outros resultados positivos. ', N'Implantar um cronograma integrado aumenta a visibilidade e a rastreabilidade das atividades. O controle das reprogramações permite identificar desvios recorrentes e atuar preventivamente. O sequenciamento por polígono melhora a integração entre Infraestrutura, Perfuração e Lavra. A visão antecipada das atividades reduz retrabalhos e aumenta a aderência entre os planos M12, D90 e D30. A gestão baseada em predecessoras proporciona maior previsibilidade e assertividade na tomada de decisão operacional.', 0, NULL, N'Foi confeccionado suporte com material sobressalente e instalado no compressor, de modo a manter a mangueira do mesmo enrolada e armazenada de maneira organizada e segura.', '2026-07-17T00:00:00.000', '2026-07-31T15:12:52.000', N'535031', NULL, NULL);
INSERT INTO #PVC VALUES (11531, N'81030963', N'81047196', N'Lista de Funcionários em situação de Emergência ', 1, N'Others/Outros', N'Foi implantado um sistema de controle de presença para emergências, garantindo identificação rápida das pessoas na área, maior rastreabilidade e mais segurança aos colaboradores.', N'Eliminar risco de pessoas ficarem sem acionamento em caso de Emergência ', N'10079', N'01 - Imagens/01 - Antes/11531.jpeg', N'Não havia um controle eficiente para identificar quem estava na área durante os acionamentos de emergência, gerando uma lacuna no processo de segurança e dificultando a rastreabilidade.', N'01 - Imagens/02 - Depois/11531.jpeg', N'Foi implementado um sistema de controle de presença que possibilita a identificação rápida e precisa das pessoas na área durante emergências, aumentando a rastreabilidade, a agilidade na resposta e a segurança dos colaboradores.', NULL, N'Ausência de um método confiável para controlar a presença de pessoas na área durante emergências.
INSERT INTO #PVC VALUES (11532, N'81030963', N'514428', N'MELHORIA NO PROCESSO DE DESCARTE DE INSERVÍVEIS – MID SAP', 1, N'Others/Outros', N'MID “Outros Inservíveis” sem os campos de responsável, gerência, diretoria e aprovador da área usuária; 
INSERT INTO #PVC VALUES (11533, N'81064091', N'81064091', N'Planejar melhor para Executar melhor', 1, N'Others/Outros', N'Tínhamos uma demanda da Automação, que era saber exatamente em qual horário eles teriam o equipamento liberado (desbloqueado), para executarem as preventivas e corretivas.
INSERT INTO #PVC VALUES (11534, N'81044397', N'81044397', N'Proteção das Bordas Metálicas do Suporte de Copos', 1, N'Others/Outros', N'Foi identificado risco de corte devido às bordas metálicas do suporte de copos, comprometendo a segurança dos colaboradores.', N'Eliminar 100% do risco de cortes nas bordas do suporte de copos com a aplicação de proteção de silicone em todos os suportes.', N'10213', N'01 - Imagens/01 - Antes/11534.jpeg', N'O suporte de copos apresenta bordas metálicas expostas, gerando risco de corte aos colaboradores. Como ação preventiva, foi proposta a instalação de bordas de silicone para eliminar esse risco e melhorar a segurança no local de trabalho.', N'01 - Imagens/02 - Depois/11534.jpeg', N'A melhoria consiste na aplicação de bordas de silicone nas partes metálicas expostas do suporte de copos. Essa solução foi proposta para eliminar o risco de cortes e proporcionar maior segurança durante o uso.', NULL, N'A ação proposta está alinhada à meta inicial de eliminar o risco de cortes.', N'A prevenção é a melhor forma de garantir um ambiente de trabalho seguro.', 0, NULL, N'Foi elaborado e confecionado com material sobressalente um suoporte para acondicionar e armazenar as talhas na vertical, de modo a mantê-las organizadas, livres de enrosco e em condição que não interfere em sua vida útil', '2026-07-29T00:00:00.000', '2026-07-31T15:32:14.000', N'81044397', NULL, NULL);
INSERT INTO #PVC VALUES (11535, N'81030963', N'81055853', N'Robo Otiff - Aderbot', 1, N'Others/Outros', N'O processo de acompanhamento da aderência das separações de materiais era realizado de forma manual, com baixa visibilidade dos resultados e identificação tardia de desvios. As análises demandavam consolidação de dados e atuação reativa, aumentando o risco de retrabalho e impactando o atendimento das OTIFs da Mina e da Usina.', N'Eliminar processo manual e dar celeridade no processo ', N'10079', N'01 - Imagens/01 - Antes/11535.jpeg', N'O controle da aderência das separações era manual, com baixa visibilidade dos resultados, identificação tardia de desvios e maior risco de retrabalho no atendimento das OTIFs.', N'01 - Imagens/02 - Depois/11535.jpeg', N'Com o ADERBOT, o monitoramento tornou-se automático e em tempo real, permitindo identificar desvios rapidamente, agir preventivamente e aumentar a aderência operacional.', NULL, N'Meta:
INSERT INTO #PVC VALUES (11536, N'81050431', N'81058947', N'RECUPERAÇÃO DA TRAVA ', 3, N'Others/Outros', N'TRAVA EM ALTA SITUAÇÃO DE DESGASTE', N'ECONOMIA', N'10139', N'01 - Imagens/01 - Antes/11536.jpeg', N'TRAVA EM ALTA SITUAÇÃO DE DESGASTE, RISCO DE QUEBRA OU ACIDENTE.', N'01 - Imagens/02 - Depois/11536.jpeg', N'RECUPERADO TRAVA PROLONGANDO VIDA ULTIL, EVITANDO CUSTO.', NULL, N'RECUPERADO TRAVA PROLONGANDO VIDA ULTIL, EVITANDO CUSTO.', N'ECONOMIA', 10000, 1, N'Sim. 
INSERT INTO #PVC VALUES (11537, N'522369', N'522369', N'TABELA DE PLANO DE AÇÃO KANBAN ELÉTRICA', 1, N'No Replication/Sem replicação', N'DIFICULDADE DE TER UM CONTROLE DE ROTINA PARA BUSCAR MATERIAIS SEMANALMENTE.', N'MELHORAR PERFORMANCE NA BUSCA DE MATERIAL ATRAVÉS DE UM TABELA SEMANAL.', N'10197', N'01 - Imagens/01 - Antes/11537.jpeg', N'TINHAMOS UMA LISTA DE PENDÊNCIAS SEMANAIS FORA DE CONTROLE NA BUSCA DE MATERIAIS PARA O KANBAN ELÉTRICA.', N'01 - Imagens/02 - Depois/11537.jpeg', N'FOI DESENVOLVIDO UMA TABELA DE PENDÊNCIAS PARA AGILIZAR A ROTINA NA BUSCA DE MATERIAIS DA SEMANAL CORRESPONDENTE.', NULL, N'HOUVE PLANEJAMENTO NA ROTINA DE ABASTECIMENTO NO KANBAN ELÉTRICA.', N'GESTÃO VISUAL DA ROTINAS DE BUSCA DE MATERIAIS SEMANALMENTE.', 0, NULL, N'Ganhos Qualitativos
INSERT INTO #PVC VALUES (11538, N'81050431', N'81058947', N'TRAVA DA BALANÇA', 1, N'Others/Outros', N'ANTES A BALANÇA ERA FIXADA COM SOLDA.', N'SEGURANÇA', N'10139', N'01 - Imagens/01 - Antes/11538.jpeg', N'ANTES A BALANÇA ERA FIXADA POR SOLDA, COM RISCO DE PROJEÇÃO.', N'01 - Imagens/02 - Depois/11538.jpeg', N'FABRICADO UMA TRAVA PARA MELHORA A FIXAÇÃO, ELIMINANDO O RISCO DE PROJEÇÃO.', NULL, N'O SERVIÇO DE SOLDA LEVA E MEDIA DUAS HORAS, SENDO QUE COM A TRAVA A ATIVIDADE É REALIZADA EM 20 MINUTO', N'MELHORIAS ', 0, NULL, N'Redução do tempo de consulta.
INSERT INTO #PVC VALUES (11539, N'81004893', N'81004893', N'Controle de Falhas de Balança e Sobrecarga dos Equipamentos', 1, N'Others/Outros', N'Ocorrência recorrente de falhas no sistema de balança e eventos de sobrecarga nos equipamentos de mina, comprometendo a confiabilidade das informações de carga, aumentando o risco de danos estruturais, reduzindo a vida útil dos componentes e impactando a segurança operacional.', N'aumentando a confiabilidade dos dados operacionais e garantindo aderência aos limites de carga estabelecidos para os equipamentos.', N'#N/A', N'01 - Imagens/01 - Antes/11539.jpeg', N'Falhas recorrentes nos sensores e sistemas de pesagem.
INSERT INTO #PVC VALUES (11540, N'81004893', N'81004893', N'Histórico de Tratamento de Eventos S-1 ', 1, N'Others/Outros', N'Ausência de registro histórico consolidado das tratativas realizadas nos eventos de telemetria S-1, dificultando a rastreabilidade das ações executadas, análise de reincidências e avaliação da efetividade das intervenções.', N'Garantir 100% de rastreabilidade das tratativas dos eventos S-1, disponibilizando histórico padronizado para consulta, acompanhamento e tomada de decisão.', N'10015', N'01 - Imagens/01 - Antes/11540.jpeg', N'Condição Antes:
INSERT INTO #PVC VALUES (11541, N'81040303', N'81040303', N'Reestruturação da governança de dados Segurança', 1, N'Others/Outros', N'Anteriormente, os dashboards da área de Segurança eram atualizados a partir de relatórios extraídos manualmente do SAP BW. Diariamente, um analista precisava dedicar aproximadamente 30 minutos para realizar a extração dos dados no período da manhã. Após essa etapa, os arquivos Excel eram atualizados manualmente para que os painéis em Power BI pudessem ser posteriormente atualizados.', N'Disponibilização de +30min diários ( 10h mensais )', N'10293', N'01 - Imagens/01 - Antes/11541.jpeg', N'Os dashboards de Segurança dependiam de extrações manuais diárias do SAP BW, consumindo cerca de 30 minutos por dia para atualização dos dados e dos painéis em Power BI. ', N'01 - Imagens/02 - Depois/11541.jpeg', N'O TechSalobo automatizou a atualização dos dashboards de Segurança, eliminando extrações manuais do SAP BW, reduzindo esforço operacional e aumentando a confiabilidade dos dados.', NULL, N'Disponibilização de +30min diários ( 10h mensais )
INSERT INTO #PVC VALUES (11542, N'478853', N'478853', N'Suporte Calços rodas pesados', 3, N'Others/Outros', N'Ausencia de local e suporte adequado para armazenamento dos calços de rodas de equipamentos de grande porte, acarretando em acumulo de materiais sobre o solo, desorganizados e com risco outros incidentes', N'Organização e 5s', N'10234', N'01 - Imagens/01 - Antes/11542.jpeg', N'Ausencia de local e suporte adequado para armazenamento dos calços de rodas de equipamentos de grande porte, acarretando em acumulo de materiais sobre o solo, desorganizados e com risco outros incidentes', N'01 - Imagens/02 - Depois/11542.jpeg', N'Foi confeccionado com materiais sobressalentes um suporte de armazenagem de calços de rodas de equipamentos pesados, com melhoria na condição ergonômica e de organização da area', NULL, N'Ausencia de local e suporte adequado para armazenamento dos calços de rodas de equipamentos de grande porte, acarretando em acumulo de materiais sobre o solo, desorganizados e com risco outros incidentes', N'Organizaçao', 0, NULL, N'PROPORCIONAR AGILIDADE E QUALIDADE NO TEMPO DE COLETA DE AMOSTRAGEM, GARANTINDO MAIOR EFICIÊNCIA E COMPROMETIMENTO COM O PROCESSO.', '2026-07-07T00:00:00.000', '2026-07-31T19:32:33.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11543, N'478853', N'478853', N'Suporte Mangueira Compressor', 3, N'Others/Outros', N'Ausencia de suporte para organziar e armazenar a mangueira do compressor, onde a mesma permanecia sobre o solo ou compressor, com risco de avairas na mesma, tropeços de pessoas ao operar o equipamento ou transitar próximo, alem de impactar no transporte do compressor com uso da empilhadeira', N'Organização e 5s', N'10234', N'01 - Imagens/01 - Antes/11543.jpeg', N'Ausencia de suporte para organziar e armazenar a mangueira do compressor, onde a mesma permanecia sobre o solo ou compressor, com risco de avairas na mesma, tropeços de pessoas ao operar o equipamento ou transitar próximo, alem de impactar no transporte do compressor com uso da empilhadeira', N'01 - Imagens/02 - Depois/11543.jpeg', N'Foi confeccionado suporte com material sobressalente e instalado no compressor, de modo a manter a mangueira do mesmo enrolada e armazenada de maneira organizada e segura.', NULL, N'Ausencia de suporte para organizar e armazenar a mangueira do compressor, onde a mesma permanecia sobre o solo ou compressor, com risco de avairas na mesma, tropeços de pessoas ao operar o equipamento ou transitar próximo, alem de impactar no transporte do compressor com uso da empilhadeira', N'Organização e 5s', 0, NULL, N'segurança / 5S / Organização do Ambiente', '2026-07-10T00:00:00.000', '2026-07-31T19:40:35.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11544, N'478853', N'478853', N'Central de Montagem de Embarcados', 2, N'Projects/Projetos', N'Ausência de local adequado e ergonômico para montagem dos paineis e sistema de embarcados dos ativos, onde era realizado ao ar livre, submetidos a intempéries e particulas, sem ambiente controlado para componentes eletroeletrônicos', N'Organização, 5s e produtividade', N'10234', N'01 - Imagens/01 - Antes/11544.jpeg', N'Ausência de local adequado e ergonômico para montagem dos paineis e sistema de embarcados dos ativos, onde era realizado ao ar livre, submetidos a intempéries e particulas, sem ambiente controlado para componentes eletroeletrônicos', N'01 - Imagens/02 - Depois/11544.jpeg', N'Foi criado um local adequado para montagem dos sistemas de embarcados, com um ambiente controlado, livre de intempéries, com melhores condições ergonômicas, otimizando as montagem e promovendo maior produtividade para o processo', NULL, N'Ausência de local adequado e ergonômico para montagem dos paineis e sistema de embarcados dos ativos, onde era realizado ao ar livre, submetidos a intempéries e particulas, sem ambiente controlado para componentes eletroeletrônicos', N'Produtividade com ambiente adequado', 0, NULL, N'Safety Compliance. ', '2026-07-02T00:00:00.000', '2026-07-31T19:46:39.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11545, N'478853', N'478853', N'Dispositvo abridor de latas de eletrodos', 2, N'Others/Outros', N'Ausência de um dispositivo adequado para abertura de latas de eletrodos, gerando improvisos para abertura, com risco de incidentes e maior tempo para concluir a abertura', N'produtividade', N'10234', N'01 - Imagens/01 - Antes/11545.jpeg', N'Ausência de um dispositivo adequado para abertura de latas de eletrodos, gerando improvisos para abertura, com risco de incidentes e maior tempo para concluir a abertura', N'01 - Imagens/02 - Depois/11545.jpeg', N'Desenvolvido e confeccionado um dispositivo utilizado para abertura das latas de eletrodos, com geometria compativel com as latas, de modo a garantir uma rapida abertura das latas de maneira padronizada, sem improvisos', NULL, N'Ausência de um dispositivo adequado para abertura de latas de eletrodos, gerando improvisos para abertura, com risco de incidentes e maior tempo para concluir a abertura', N'produtividade', 0, NULL, N'FOI CONFECCIONADO CHAPAS PARA FECHAMENTO DAS ABERTURAS, ASSIM ELIMINANDO O RISCO DE QUEDA.', '2026-07-13T00:00:00.000', '2026-07-31T19:51:26.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11546, N'478853', N'478853', N'Bomba sucção fluidos usados', 2, N'Others/Outros', N'Ausencia de modo de sucção das bacias de contenção de fluidos para transbordo e descarte após drenagem dos equipamentos, com risco a saude e meio ambiente, pois o processo era realizado de forma manual ou com uso de funil e com apoio de empilhadeira para drenagem por gravidade', N'produtividade e meio ambiente', N'10234', N'01 - Imagens/01 - Antes/11546.jpeg', N'Ausencia de modo de sucção das bacias de contenção de fluidos para transbordo e descarte após drenagem dos equipamentos, com risco a saude e meio ambiente, pois o processo era realizado de forma manual ou com uso de funil e com apoio de empilhadeira para drenagem por gravidade', N'01 - Imagens/02 - Depois/11546.jpeg', N'Foi dimensionada uma bomba para realizar a sucção das bacias e transbordo diretamente para os recipientes de descarte, eliminando a necessidade de uso da empilhadeira, processos manuais e com funil.', NULL, N'Ausencia de modo de sucção das bacias de contenção de fluidos para transbordo e descarte após drenagem dos equipamentos, com risco a saude e meio ambiente, pois o processo era realizado de forma manual ou com uso de funil e com apoio de empilhadeira para drenagem por gravidade', N'Produtividade e cuidado com meio ambiente', 0, NULL, NULL, '2026-07-08T00:00:00.000', '2026-07-31T19:58:23.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11547, N'478853', N'478853', N'Suporte talhas manuais', 3, N'Others/Outros', N'Talhas manuais eram armazendas de maneira desorganizadas, com riscos de danos e maior tempo para manuseio, devido estarem enroladas entre si', N'Organização, 5s e conservação da ferramenta', N'10234', N'01 - Imagens/01 - Antes/11547.jpeg', N'Talhas manuais eram armazendas de maneira desorganizadas, com riscos de danos e maior tempo para manuseio, devido estarem enroladas entre si', N'01 - Imagens/02 - Depois/11547.jpeg', N'Foi elaborado e confecionado com material sobressalente um suoporte para acondicionar e armazenar as talhas na vertical, de modo a mantê-las organizadas, livres de enrosco e em condição que não interfere em sua vida útil', NULL, N'Talhas manuais eram armazendas de maneira desorganizadas, com riscos de danos e maior tempo para manuseio, devido estarem enroladas entre si', N'Organização e melhoria da armazenagem', 0, NULL, NULL, '2026-07-02T00:00:00.000', '2026-07-31T20:06:37.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11548, N'478853', N'478853', N'Carrinho transporte cilindro trabalho a quente', 2, N'Others/Outros', N'Ausência de dispositvo para transporte individual de cilindros de trabalho a quente, sendo possivel somente com o uso de empilhadeira, inclusive em locais de espaço restrito, onde o equipamento não acessa', N'Praticidade e produtividade', N'10234', N'01 - Imagens/01 - Antes/11548.jpeg', N'Ausência de dispositvo para transporte individual de cilindros de trabalho a quente, sendo possivel somente com o uso de empilhadeira, inclusive em locais de espaço restrito, onde o equipamento não acessa', N'01 - Imagens/02 - Depois/11548.jpeg', N'Foi realizada a aquisição de carrinhos de transporte de cilindros individuais, de modo a garantir o transporte ate os locais onde a empilhadeira não acessa', NULL, N'Ausência de dispositvo para transporte individual de cilindros de trabalho a quente, sendo possivel somente com o uso de empilhadeira, inclusive em locais de espaço restrito, onde o equipamento não acessa', N'Produtividades e praticidade', 0, NULL, N'Com a implementação das etiquetas padronizada ganhamos clareza e melhor visualizações nas chaves e cadeados.', '2026-07-10T00:00:00.000', '2026-07-31T20:14:13.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (11549, N'521817', N'521817', N'RC sem Devoluções: Guia Prático para Elaboração Correta de Requisições de Compra', 1, N'Others/Outros', N'Temos observado um número elevado de RCs devolvidas pelo time de Suprimentos devido a inconsistências no preenchimento das requisições. Identificamos a necessidade de disponibilizar um procedimento passo a passo para criação de RCs, contemplando o correto preenchimento dos campos obrigatórios, a seleção adequada do tipo de requisição e a inclusão de toda a documentação e anexos obrigatórios, a fim de reduzir retrabalhos e agilizar o processo de aprovação.', N'Orientar todos os requisitantes sobre as melhores práticas para elaboração de uma Requisição de Compra (RC), garantindo o correto preenchimento de todos os campos obrigatórios, a seleção adequada do tipo de requisição, a inclusão dos anexos necessários e o fornecimento de informações completas ao comprador, de forma a minimizar devoluções, reduzir retrabalhos e aumentar a eficiência do processo de suprimentos.', N'10234', N'01 - Imagens/01 - Antes/11549.jpeg', N'Temos observado um número elevado de RCs devolvidas pelo time de Suprimentos devido a inconsistências no preenchimento das requisições. Identificamos a necessidade de disponibilizar um procedimento passo a passo para criação de RCs, contemplando o correto preenchimento dos campos obrigatórios, a seleção adequada do tipo de requisição e a inclusão de toda a documentação e anexos obrigatórios, a fim de reduzir retrabalhos e agilizar o processo de aprovação.', N'01 - Imagens/02 - Depois/11549.jpeg', N'Uma RC Spot deve ser elaborada de forma completa e consistente, garantindo o preenchimento de todos os campos obrigatórios, a correta classificação do tipo de requisição, a vinculação de todos os anexos e documentações pertinentes, bem como a inclusão de informações detalhadas no campo de texto descritivo e na nota ao comprador, destacando claramente todas as observações, justificativas e requisitos necessários para o correto processamento da demanda. ', NULL, N'Sim. 
INSERT INTO #PVC VALUES (11550, N'483318', N'483318', N'Desenvolvimento de Planilha Integrada de Indicadores para suporte às Reuniões de Performance da Diretoria de Operação', 1, N'Others/Outros', N'
INSERT INTO #PVC VALUES (11551, N'483318', N'483318', N'Melhoria da Planilha de Equipamentos Autônomos', 1, N'Others/Outros', N'A consulta de informações dos equipamentos autônomos exigia análise individual de TAGs.', N'Implementação de filtros e seleção automática de TAGs na planilha.', N'10323', N'01 - Imagens/01 - Antes/11551.jpeg', N'O ajuste de UF e Prod por tag de cada caminhão autonomo era feito de forma manual, demandando bastante tempo.', N'01 - Imagens/02 - Depois/11551.jpeg', N'Implementação de filtros e seleção automática de TAGs na planilha, lincando os indicadores referente a operação autônoma, apenas fazendo a marcação de um checkbox.', NULL, N'Processo mais intuitivo, com filtros automatizados.', N'Redução de erros de consolidação de metas. Maior velocidade na preparação dos dados.', 0, NULL, N'help with keeping technicians out of harms way and as well assist with ergonomics', '2026-07-01T00:00:00.000', '2026-07-31T21:54:02.000', N'483318', NULL, NULL);
INSERT INTO #PVC VALUES (11552, N'81008286', N'81008286', N'Heating Blanket intructions', 1, N'Refining/Refino', N'programming the temperature on heating blankets was confusing without instructions in field.', N'clarity on how to set up the heating blankets properly', N'0', N'01 - Imagens/01 - Antes/11552.jpeg', N'No instructions in field, blanket temps were often set up wrong or not set at all.', N'01 - Imagens/02 - Depois/11552.jpeg', N'easy to understand instructions added next to heating blankets in field.', NULL, N'Yes. temps have been properly set and should be from here on out.', N'simple easy to understand instructions save time', 0, NULL, N'zero acidentes e vidas mudadas por exposiçao desncessaria', '2026-07-31T00:00:00.000', '2026-08-01T01:59:45.000', N'81008286', NULL, NULL);
