INSERT INTO #PVC VALUES (11556, N'547290', N'547290', N'Instalação de suporte para bolsa e capacete na área operacional', 3, N'Others/Outros', N'Os colaboradores não possuem um local adequado e padronizado para acondicionar bolsas e capacetes durante as atividades, fazendo com que os itens sejam deixados em bancadas, mesas ou outros locais inadequados.', N'Eliminar a desorganização ', N'10054', N'01 - Imagens/01 - Antes/11556.jpeg', N'Os colaboradores não possuem um local adequado e padronizado para acondicionar bolsas e capacetes durante as atividades, fazendo com que os itens sejam deixados em bancadas, mesas ou outros locais inadequados.', N'01 - Imagens/02 - Depois/11556.jpeg', N'Fixação de suportes metálicos ou ganchos em local estratégico da área, permitindo que cada colaborador acomode sua bolsa e capacete de forma organizada e segura.', NULL, N'Melhoria da organização e limpeza da área.
INSERT INTO #PVC VALUES (11557, N'1010860', N'1010860', N'Tepid water skid PSV Replacement', 2, N'No Replication/Sem replicação', N'Tepid Water Vessel PSV Was due for recertification', N'Safety Compliance', N'10005', N'01 - Imagens/01 - Antes/11557.jpeg', N'Tepid Water Vessel PSV Was due for recertification. Maintenance did not have resources to complete so operations completed the work.', N'01 - Imagens/02 - Depois/11557.jpeg', N'Equipment was isolated and PSV replaced.', NULL, N'Yes PSV replaced and Equipment back in service', N'Compliance', 0, NULL, N'Não mensurado financeiramente. Benefício relacionado à redução de retrabalho, otimização de mão de obra e aumento da confiabilidade operacional.
INSERT INTO #PVC VALUES (11558, N'81030117', N'553136', N'PROTEÇÃO DE LATERAIS DA PASSARELA PF1601', 1, N'Others/Outros', N'ANTERIORMENTE HAVIA 2 ABERTURAS NAS LATERAIS DA PASSARELA DA PF1601 COM RISCO DE QUEDA.', N'ELIMINAR RISCOS DE QUEDA', N'10324', N'01 - Imagens/01 - Antes/11558.jpeg', N'ANTERIORMENTE HAVIA 2 ABERTURAS NAS LATERAIS DA PASSARELA DA PF1601 COM RISCO DE QUEDA', N'01 - Imagens/02 - Depois/11558.jpeg', N'FOI CONFECCIONADO CHAPAS PARA FECHAMENTO DAS ABERTURAS, ASSIM ELIMINANDO O RISCO DE QUEDA.', NULL, N'ANTERIORMENTE HAVIA 2 ABERTURAS NAS LATERAIS DA PASSARELA DA PF1601 COM RISCO DE QUEDA', N'MAIOR SEGURANÇA NAS ATIVIDADES', 0, NULL, N'It is now more time efficient to log and there is visual reminder of the acceptable range and when to perform the task', '2026-07-25T00:00:00.000', '2026-08-01T17:40:19.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (11559, N'81042683', N'81042683', N'Belt Filter 002 Bearing Journal Recovery Through In-House Belzona Repair', 1, N'Refining/Refino', N'A failed bearing journal was identified on Belt Filter 002, resulting in the belt being offline and risk to production continuity. The original replacement component valued at approximately $27,795 CAD, along with expedited freight of approximately $25,500 CAD. In addition to the direct cost, the replacement part carried a delivery delay that would have prolonged equipment downtime.', N'Restore Belt Filter 002 to service while avoiding the cost, lead time, and production impact associated with purchasing and expediting a replacement bearing assembly.', N'0', N'01 - Imagens/01 - Antes/11559.jpeg', N'Belt Filter 002 was offline due to a failed bearing journal.
INSERT INTO #PVC VALUES (11560, N'81042683', N'81042683', N'Development of an In-House Rebuild Program for DE and NDE Air Seals', 1, N'Refining/Refino', N'14 failed DE and NDE air seals were considered beyond repair by the WHSE. Replacement of these seals required the purchase of new units at a significant cost, resulting in high maintenance expenditures and the disposal of otherwise recoverable assets.
INSERT INTO #PVC VALUES (11561, N'486356', N'486356', N'Padronização e identificação visual dos cadeados ', 1, N'Others/Outros', N'Os cadeados de bloqueio não possuíam identificação fixa padrão, sendo identificados por papéis avulsos anotações manuais ou etiquetas improvisadas que se desgastavam facilmente ', N'Melhor identificação e padronização ', N'10209', N'01 - Imagens/01 - Antes/11561.jpeg', N'Os cadeados de bloqueios não possuíam identificação fixa padrão sendo identificados por papéis avulsos e anotações manuais feitas com canetas que se apagavam facilmente.', N'01 - Imagens/02 - Depois/11561.jpeg', N'Com a implementação e padronização de etiquetas adesivas impressas em material de Auta durabilidade é legível ganhamos tempo e rastreabilidade em nossas atividades de bloqueio.', NULL, N'Sim , tínhamos dificuldades em organizar os cadeados que não havia numerações legíveis ', N'Organização e padronização ', 0, NULL, N'Redução significativa do tempo da atividade.', '2026-07-28T00:00:00.000', '2026-08-01T22:48:21.000', N'486356', NULL, NULL);
INSERT INTO #PVC VALUES (11562, N'81023776', N'81023776', N'Slaker draining chute', 1, N'Others/Outros', N'Media in the past was messily drained from slaker resulting in time cleaning up', N'Create less workload', N'0', N'01 - Imagens/01 - Antes/11562.jpeg', N'Media in the past was messily drained from slaker resulting in time cleaning up', N'01 - Imagens/02 - Depois/11562.jpeg', N'Chute was created to funnel slaker media in hopper', NULL, N'Less workload for technicians to clean up', N'Less time wasted cleaning up media', 0, NULL, N'Eliminado derramamento de óleo ao solo e projeção ao colaborador', '2026-04-02T00:00:00.000', '2026-08-02T02:10:49.000', N'81023776', NULL, NULL);
INSERT INTO #PVC VALUES (11563, N'81023776', N'81023776', N'Magnet chute reject bin', 3, N'Others/Outros', N'Clean packs were utilized to contain magnet reject resulting in cost to continue replacing them', N'Have a bin available to keep reusing', N'0', N'01 - Imagens/01 - Antes/11563.jpeg', N'Clean packs were utilized to contain magnet reject resulting in cost to continue replacing them', N'01 - Imagens/02 - Depois/11563.jpeg', N'Reusable hopper was placed instead of clean packs to have ease of dumping and reuse instead of wasting cost replacing clean packs', NULL, N'Yes', N'Consumable items may have a reusable replacement', 1000, 3, N'Maior controle sobre os principais geradores de paradas, redução da atuação reativa da manutenção, aumento da previsibilidade operacional e sustentação das metas de MTBF por meio da identificação e tratamento antecipado dos modos de falha críticos.', '2026-07-01T00:00:00.000', '2026-08-02T02:17:15.000', N'81023776', NULL, NULL);
INSERT INTO #PVC VALUES (11564, N'81023776', N'81023776', N'Vice on lime laydown', 1, N'Others/Outros', N'technicians not able to clamp down work pieces ', N'Help technicians hold work pieces when using laydown table', N'0', N'01 - Imagens/01 - Antes/11564.jpeg', N'Technicians did not have an available vice to help with work on the lime laydown table', N'01 - Imagens/02 - Depois/11564.jpeg', N'A new vice was implemented and attached to the lime laydown table to assist technicians with clamping work pieces when needed helping with ergonomics and safety', NULL, N'Yes', N'Safety 1rst ', 0, NULL, N'Disponibilizar uma visão executiva e padronizada da saúde dos ativos, facilitando o entendimento dos riscos por todos os níveis da organização, acelerando o direcionamento das cadeias de ajuda e apoiando decisões mais assertivas sobre manutenção e confiabilidade.', '2026-07-01T00:00:00.000', '2026-08-02T02:22:01.000', N'81023776', NULL, NULL);
INSERT INTO #PVC VALUES (11565, N'81037517', N'87001735', N'dispositivo travamento da engrenagem do compressor', 1, N'Others/Outros', N'dispositivo  retirada do acomplamento de borracha do compressor (remoçao e instalaçao)', N'zero  acidente ', N'10324', N'01 - Imagens/01 - Antes/11565.jpeg', N'Durante a atividade de desacoplamento e acoplamento da engrenagem do compressor, foi identificada a ausência de um dispositivo de travamento padronizado capaz de impedir movimentos involuntários nos sentidos horário e anti-horário. Como alternativa para execução da tarefa, foram utilizados acessórios e ferramentas não padronizados, aumentando a exposição a desvios operacionais, dificuldades na execução da atividade e riscos de segurança para os envolvidos.', N'01 - Imagens/02 - Depois/11565.jpeg', N'foi feito dispositivo que trava de forma horaria e anti horario de forma segura o movimento da engrenagem evitando esmagamento e cortes dilaceraçoes e outros caidentes correlacionado ao movimento e travamento inadequado da engrenagem', NULL, N'sim, e retirado exposiçao por ferramentas inadequadas', N' necessario desenvolver dispositivo para nao usar recursos inadequados ', 0, NULL, N'Aumentar a visibilidade sobre o consumo de óleo hidráulico da frota, permitindo a identificação precoce de vazamentos, redução das perdas de óleo, diminuição de custos e maior agilidade na tomada de decisão.', '2026-05-20T00:00:00.000', '2026-08-02T03:13:41.000', N'81037517', NULL, NULL);
INSERT INTO #PVC VALUES (11566, N'81037517', N'81056020', N'corrimao de proteçao  para Reduçao de exposiçao a riscos e uso constante de andaime e plataforma no complento de oleo redutor ', 1, N'Projects/Projetos', N'Atualmente, as atividades de coleta e complemento de óleo do redutor de avanço exigem, de forma recorrente, a mobilização de plataforma elevatória e/ou montagem de andaime para acesso aos pontos de intervenção. Essa condição aumenta significativamente o tempo de manutenção devido à necessidade de montagem e desmontagem das estruturas de acesso, além de gerar custos adicionais com alocação de equipamentos. Também expõe os trabalhadores a riscos desnecessários associados ao trabalho em altura e à utilização de equipamentos motorizados para acesso suspenso, impactando a segurança, a produtividade e a disponibilidade do equipamento.', N' reduçao de custo e exposiçao  ', N'10324', N'01 - Imagens/01 - Antes/11566.jpeg', N'antes o colaborador subia e ficava exposto pela movimentação parte superior do equipamento    sem proteção  padrão com 03 pontos de acesso, e ou exposição a equipamentos de acessos ', N'01 - Imagens/02 - Depois/11566.jpeg', N'Foi desenvolvida e instalada uma plataforma fixa com escada e guarda-corpo para acesso seguro aos pontos de inspeção, coleta e reposição de óleo. A implementação dessa melhoria elimina a necessidade frequente de montagem e desmontagem de andaimes e da utilização de plataformas elevatórias, reduzindo custos operacionais e tempo de manutenção. Além disso, proporciona maior segurança aos colaboradores ao reduzir a exposição a riscos associados ao trabalho em altura e ao uso de equipamentos de acesso motorizados, contribuindo para a diminuição do tempo de parada dos ativos e aumento da produtividade das intervenções.', NULL, N'Comparação com a meta inicial / declaração do problema
INSERT INTO #PVC VALUES (11567, N'1008445', N'1008445', N'Cobalt Inventory Memo', 1, N'No Replication/Sem replicação', N'We are currently using NiEW Feed Tank #1 as surge capacity for Co solution. They weren''t a management plan for maintaining levels in the circuit', N'Standardize inventory management amongst all shifts', N'0', N'01 - Imagens/01 - Antes/11567.jpeg', N'We are using the NiEW Feed Tank #1 for Co solution surge. There was no direction on when to feed to the NiEW Feed Tank or when to bring solution back', N'01 - Imagens/02 - Depois/11567.jpeg', N'A tank level management plan memo was developed to standardize when to send to or receive solution from the NiEW Feed Tank', NULL, N'Yes', N'Memo Created', 0, NULL, N'Disponibilização de uma base de HH confiável e criação do primeiro estudo técnico de dimensionamento da equipe de Automação, trazendo maior visibilidade da carga de trabalho e suporte para decisões relacionadas à adequação do quadro de pessoal.', '2026-07-05T00:00:00.000', '2026-08-02T03:58:30.000', N'1008445', NULL, NULL);
INSERT INTO #PVC VALUES (11568, N'609694', N'609694', N'Dust collection box', 3, N'Underground/Subterrâneo', N'We installed an industrial vacuum at 3090. The unit is working really good. Now that we started the process-  we come to realize that when the debris box empties out - lots of dust gets air born  because of the ventilation in the area. we could not have known this until we actually got going with the project ', N'Stop dust from becoming air born', N'10260', N'01 - Imagens/01 - Antes/11568.jpeg', N'when debris box empties out the vent spreads the dust all over ', N'01 - Imagens/02 - Depois/11568.jpeg', N'We build a dust collection box around the bottom of the debris box that will stop vent and allow the dust to go in the hole ', NULL, N'yes ', N'All is possible ', 1, 3, N'Implementar uma priorização estruturada dos estudos de LDA e extensão de vida útil, direcionando os recursos para ativos com maior disponibilidade de dados e potencial de geração de resultados.', '2026-08-01T00:00:00.000', '2026-08-02T12:46:28.000', N'609694', NULL, NULL);
INSERT INTO #PVC VALUES (11569, N'81063699', N'81063699', N'Fixação definitiva do suporte de pincéis e apagador na parede', 3, N'Others/Outros', N'O suporte de pincéis e apagador encontrava-se fixado à parede por meio de fita adesiva/cola. Devido à textura da superfície e ao peso dos materiais armazenados, a fixação perdia aderência frequentemente, ocasionando a queda do suporte, danos ao dispositivo, desorganização da área e necessidade de retrabalho para reinstalação.', N'Eliminar a queda recorrente do suporte de pincéis e apagador através da fixação mecânica na parede, garantindo organização, conservação do material e segurança da área.', N'10346', N'01 - Imagens/01 - Antes/11569.jpeg', N'Suporte fixado com fita adesiva, desprendendo-se e caindo constantemente.', N'01 - Imagens/02 - Depois/11569.jpeg', N'Suporte fixado com parafusos e buchas, permanecendo estável e disponível para uso contínuo.', NULL, N'O problema foi resolvido. O suporte, que anteriormente era fixado por fita adesiva e sofria quedas frequentes devido à perda de aderência, passou a ser fixado por meio de parafusos e buchas. Após a implementação, não foram observadas novas quedas, garantindo maior segurança, organização e eliminando a necessidade de retrabalho com recolagens frequentes.', N'Fixações realizadas apenas com fita adesiva em superfícies texturizadas apresentam baixa confiabilidade. A utilização de fixação mecânica (parafusos e buchas) aumenta a durabilidade, segurança e estabilidade dos dispositivos de organização.', 0, NULL, N'maior segurança no armazenamento de material. ', '2026-08-01T00:00:00.000', '2026-08-02T14:26:19.000', N'81063699', NULL, NULL);
INSERT INTO #PVC VALUES (11570, N'81042078', N'81050572', N'Sistema Inteligente de Análise e Rastreabilidade das Células dos Bancos de Baterias por Meio de Relatório Automatizado', 1, N'Others/Outros', N'A ausência de um sistema de monitoramento e rastreabilidade das células dos bancos de baterias dificultava o controle histórico das medições e a identificação de desvios de tensão, resistência interna e temperatura. Como consequência, havia necessidade de novas inspeções para confirmação dos resultados, aumento do tempo de diagnóstico, retrabalho nas atividades de manutenção e menor assertividade na tomada de decisão para substituição de células, impactando a eficiência e a confiabilidade operacional do processo. 
INSERT INTO #PVC VALUES (11571, N'1010294', N'1010294', N'TSS Oven Temp Signage', 1, N'Refining/Refino', N'Logging of TSS oven temperatures are sometimes missed and finding the location of the file can be difficult.', N'Reminder and direction on when and how to track TSS Oven Temperatures', N'10352', N'01 - Imagens/01 - Antes/11571.jpeg', N'Signage and location of logging file was absent for when to complete TSS oven temperature check.', N'01 - Imagens/02 - Depois/11571.jpeg', N'When and where to log the TSS oven temperatures are now posted directly on the TSS Oven door to easy reference.', NULL, N'Yes, easy to reference and visual reminder.  More efficient use of time', N'Visual Aid to trigger data collection', 0, NULL, N'This will also ensure that our targets will be met and zero harm to employees', '2026-08-01T00:00:00.000', '2026-08-02T17:05:58.000', N'1010294', NULL, NULL);
INSERT INTO #PVC VALUES (11572, N'81045248', N'81052061', N'Wharf Conveyor Curtain size chart ', 1, N'Concentration/Concentração', N'not all curtains on the conveyor belts are the same size. When a curtain needs to be ordered we have to sometimes measure the curtain and order a new one using those measurements. If those measurements are not correct, we could order curtains that are not the right size. They are non refundable or returnable, so this could waste money', N'accurate ordering information ', N'0', N'01 - Imagens/01 - Antes/11572.jpeg', N'curtains can tear or become damaged. They are not all the same size, some need openings for pull cords or outlets, ect.  it can become dirty and the sizing information can be illegible. There have been times when a curtain was ordered and it did not fit. Curtains are not returnable or refundable, this could lead to unnecessary costs incurred. ', N'01 - Imagens/02 - Depois/11572.jpeg', N'Created a spreadsheet indicating correct sizes for each curtain along the conveyor. There''s 172 curtains on the wharf conveyor. This eliminates guessing or incorrect measuring. The ordering information for each curtain along the conveyor and its special specifications are included. ', NULL, N'over the course of a year we could order anywhere from 5-10 curtain replacements if not more. Now, we eliminate potentially ordering incorrect sizes', N'measure once', 5000, 3, N'MELHORIA PRODUTIVIDADE', '2026-08-02T00:00:00.000', '2026-08-03T00:21:01.000', N'81045248', NULL, NULL);
INSERT INTO #PVC VALUES (11573, N'81045248', N'81045248', N'handle cover', 2, N'Others/Outros', N'there are a few places where the handles of a blind are sticking out at angles that have the potential to come in contact with your body. Some are at chest level, some at eye level and some at knee or shin level. ', N'protect body from injury ', N'0', N'01 - Imagens/01 - Antes/11573.jpeg', N'sometimes there are handles that stick out that might be in the path that you are walking. This one in particular has been painted orange to raise awareness, but it is not at eye level and often gets missed. Hitting your shin or knee off of this can be really painful and has the potential to injure a person', N'01 - Imagens/02 - Depois/11573.jpeg', N'a foam roller or "Pool noodle" cut down to size and placed over the handle has helped to minimize the impact in the event that someone accidentally bumps into it. ', NULL, N'if you accidentally hit your shin or knee off of this handle, you will not hurt yourself nearly as much as you would if you hit it directly on the metal ', N'spacial awareness ', 0, NULL, NULL, '2026-08-02T00:00:00.000', '2026-08-03T01:06:07.000', N'81045248', NULL, NULL);
INSERT INTO #PVC VALUES (11574, N'539631', N'81048571', N'Engate para avanço e retração do cilindro de direção com nitrogênio', 2, N'Open Pit/Poço aberto', N'A instalação do cilindro de direção da frota 797F exige manipulação manual para extensão e retração do cilindro, expondo o colaborador a risco ergonômico e contaminação do componente.', N'Reduzir risco ergonômico e evitar contaminação do componente', N'10140', N'01 - Imagens/01 - Antes/11574.jpeg', N'Anteriormente, o avanço e retração do cilindro eram feitos manualmente, expondo o colaborador a risco ergonômico e o componente a risco de contaminação.', N'01 - Imagens/02 - Depois/11574.jpeg', N'Foi confeccionado um dispositivo para acoplar o reservatório de nitrogênio ao cilindro de direção, realizando o avanço e retração sem risco para o colaborador, e sem risco de contaminação.', NULL, N'O problema foi resolvido, o colaborador não fica mais exposto à risco ergonômico e o componente permanece isolado, entrando em contato apenas com o nitrogênio.', N'Nossas ferramentas do dia a dia podem nos ajudar em outras atividades além das que já utilizamos habitualmente', 0, NULL, N'Redução de tempo na identificação de demandas a tratar.', '2026-08-02T00:00:00.000', '2026-08-03T05:53:24.000', N'539631', NULL, NULL);
INSERT INTO #PVC VALUES (11575, N'539631', N'81048571', N'Mangueira de retorno de óleo para instalação do cilindro de direção.', 1, N'Open Pit/Poço aberto', N'Pela ausência de linha de drenagem, durante a extensão ou retração do cilindro pode ocorrer derramamento de óleo.', N'Evitar derramamento de óleo, direcionando corretamente para o coletor de óleo', N'10140', N'01 - Imagens/01 - Antes/11575.jpeg', N'Ao realizar extensão ou retração do cilindro havia derramamento de óleo e projeção', N'01 - Imagens/02 - Depois/11575.jpeg', N'Após confecção da melhoria, foi eliminado o derramamento de óleo e projeção ao colaborador. Além disso, foi reduzido o tempo gasto com limpeza do óleo derramado.', NULL, N'Problema foi sanado, eliminado derramamento de óleo e projeção.', N'Todo processo pode ser melhorado', 0, NULL, N'Reuse of approximately 420 tonnes (200 m³) of suitable excavated material between projects, eliminating unnecessary disposal and reducing material procurement, transportation costs, and landfill utilization.', '2026-08-02T00:00:00.000', '2026-08-03T06:08:06.000', N'539631', NULL, NULL);
INSERT INTO #PVC VALUES (11576, N'81059325', N'81047211', N'Gestão Semanal do Perfil de Perdas para Atingimento do MTBF - Escavação e Carregamento', 1, N'Others/Outros', N'O acompanhamento da confiabilidade das frotas era realizado principalmente por meio do MTBF, indicador que demonstra os resultados após a ocorrência das falhas. A ausência de uma ferramenta de monitoramento dos principais sistemas geradores de paradas dificultava a identificação antecipada de desvios e a priorização de ações de manutenção.
INSERT INTO #PVC VALUES (11577, N'81059325', N'81047211', N'Painel Integrado de Monitoramento Preditivo das Frotas de Escavação e Carregamento', 1, N'Others/Outros', N'O CMA realizava o monitoramento preditivo dos ativos, porém as informações estavam distribuídas em diferentes laudos e relatórios. A ausência de um painel gerencial consolidado dificultava a visualização da condição da frota, a comunicação dos riscos, o alinhamento das ações e a tomada de decisão nas reuniões S-1 e M-1.', N'Desenvolver e implantar um Painel Integrado de Monitoramento Preditivo das Frotas de Escavação e Carregamento, consolidando em uma única visão executiva as informações dos métodos preditivos, de forma simples e intuitiva, permitindo que todos os níveis hierárquicos identifiquem rapidamente a condição dos ativos, direcionem as cadeias de ajuda necessárias e apoiem a tomada de decisão nas reuniões S-1 e M-1.', N'10015', N'01 - Imagens/01 - Antes/11577.jpeg', N'O monitoramento dos ativos era realizado pelo Centro de Monitoramento de Ativos (CMA) por meio dos métodos preditivos disponíveis. Entretanto, não existia um painel gerencial consolidado para apresentação nas reuniões semanais (S-1) e mensais (M-1), permitindo visualizar de forma rápida a condição geral das frotas. As informações encontravam-se dispersas em diferentes laudos e relatórios técnicos, dificultando a comunicação dos riscos, o alinhamento entre as equipes e a tomada de decisão gerencial.', N'01 - Imagens/02 - Depois/11577.jpeg', N'Foi desenvolvido um Painel Integrado de Monitoramento Preditivo das Frotas de Escavação e Carregamento, consolidando em uma única visão os resultados de análise de óleo, vibração, termografia, ultrassom e telemetria. O painel passou a ser utilizado nas reuniões S-1 e M-1, permitindo identificar rapidamente os ativos classificados como Normal, Monitorar ou Crítico, facilitando a comunicação dos riscos, a priorização das ações e a tomada de decisão em todos os níveis da organização.', NULL, N'Sim. O objetivo foi atingido com a implantação de um painel gerencial consolidado para acompanhamento dos resultados preditivos. A ferramenta passou a fornecer uma visão clara e intuitiva da condição das frotas, permitindo que qualquer nível hierárquico compreenda rapidamente os principais riscos e as ações necessárias para mitigá-los, tornando as reuniões S-1 e M-1 mais objetivas e assertivas.', N'A consolidação de informações técnicas em uma ferramenta visual e padronizada facilita a comunicação entre os diferentes níveis da organização, melhora o alinhamento das ações e torna a tomada de decisão mais ágil e eficiente.', 0, NULL, N'Diminuição de paradas corretivas', '2026-07-31T00:00:00.000', '2026-08-03T09:10:27.000', N'81059325', NULL, NULL);
INSERT INTO #PVC VALUES (11578, N'81059325', N'81047211', N'Painel de Monitoramento do Consumo de Óleo Hidráulico das Escavadeiras PC5500-6D', 1, N'Others/Outros', N'Não existia uma ferramenta gerencial para acompanhamento sistemático do consumo de óleo hidráulico das escavadeiras durante as reuniões S-1 e M-1. A ausência de visibilidade consolidada dificultava a identificação precoce de desvios, atrasando o tratamento de vazamentos e aumentando o risco de elevação dos custos com reposição de óleo.', N'Desenvolver e implantar um painel de monitoramento do consumo de óleo hidráulico das escavadeiras PC5500-6D para acompanhamento nas reuniões S-1 e M-1, possibilitando a identificação precoce de desvios de consumo, direcionamento das ações corretivas e mitigação de vazamentos que possam gerar impactos operacionais e financeiros.', N'10015', N'01 - Imagens/01 - Antes/11578.jpeg', N'O acompanhamento do consumo de óleo hidráulico era realizado de forma pontual, sem uma visão consolidada das tendências de consumo por equipamento. Isso dificultava a identificação antecipada de desvios e o direcionamento das ações para eliminação de vazamentos.', N'01 - Imagens/02 - Depois/11578.jpeg', N'Foi desenvolvido um painel gerencial para acompanhamento semanal e mensal do consumo de óleo hidráulico das escavadeiras PC5500-6D. A ferramenta permite identificar rapidamente equipamentos com consumo acima do esperado, investigar as causas dos desvios, definir ações de mitigação e monitorar a evolução dos resultados durante as reuniões S-1 e M-1.', NULL, N'Sim. O painel foi implantado e incorporado às rotinas das reuniões S-1 e M-1, proporcionando visibilidade consolidada do consumo de óleo hidráulico da frota, identificação antecipada de desvios e suporte à tomada de decisão para mitigação de vazamentos e redução de perdas.', N'O monitoramento contínuo de indicadores de consumo permite identificar desvios antes que se tornem eventos de grande impacto, direcionando ações mais rápidas e reduzindo custos associados a vazamentos e perdas de fluido hidráulico.', 0, NULL, N'People are self-aware and drinking more water.', '2026-07-31T00:00:00.000', '2026-08-03T09:23:06.000', N'81059325', NULL, NULL);
INSERT INTO #PVC VALUES (11579, N'81050579', N'517587', N'Alarme de Locomoção ', 2, N'Projects/Projetos', N'Anteriormente, o alarme de locomoção estava instalado no cavalete do mastro do equipamento, o que dificultava a execução da manutenção. Para a substituição do componente, era necessária a utilização de Plataforma Elevatória.', N'eliminar risco de queda de altura, facilita na manutenção', N'10144', N'01 - Imagens/01 - Antes/11579.jpeg', N'Anteriormente, o alarme de locomoção estava instalado no cavalete do mastro do equipamento, o que dificultava a execução da manutenção. Para a substituição do componente, era necessária a utilização de Plataforma Elevatória.', N'01 - Imagens/02 - Depois/11579.jpeg', N'Efetivou-se a mudança de posicionamento do componente. A nova localização proporciona maior ergonomia e acessibilidade para as atividades de manutenção, dispensando o uso de Plataforma Elevatória e eliminando a exposição ao risco de queda em altura.', NULL, N'Sim', N'Sentimento de Dono ', 0, NULL, N'mais autonomia aos autorizados.', '2026-07-29T00:00:00.000', '2026-08-03T12:53:15.000', N'81050579', NULL, NULL);
INSERT INTO #PVC VALUES (11580, N'81053475', N'81053475', N'Saneamento de Dados e Quantificação da Demanda de Headcount da Equipe de Automação', 1, N'Others/Outros', N'A equipe de Automação não possuía uma base de HH confiável e estruturada, dificultando a quantificação da demanda de trabalho e a definição da necessidade adequada de mão de obra para as atividades de execução e inspeção.', N'Sanear e padronizar a base de HH da equipe de Automação, desenvolvendo um estudo estruturado para quantificar a demanda de HC necessária para execução e inspeção, aumentando a assertividade no planejamento de recursos.', N'10015', N'01 - Imagens/01 - Antes/11580.jpeg', N'A base de HH apresentava inconsistências e não existia um estudo estruturado que permitisse avaliar tecnicamente a demanda de mão de obra necessária para atender as atividades de execução e inspeção da equipe.', N'01 - Imagens/02 - Depois/11580.jpeg', N'Base de HH saneada e padronizada, com informações confiáveis para análise. Desenvolvimento do primeiro estudo estruturado de dimensionamento da equipe de Automação, permitindo quantificar a demanda necessária de HC para execução e inspeção.', NULL, N'Foi realizado o saneamento da base de HH, eliminando inconsistências e padronizando as informações registradas. Com os dados tratados, foi desenvolvido o primeiro estudo estruturado de dimensionamento da equipe de Automação, contemplando as atividades de execução e inspeção e permitindo quantificar tecnicamente a necessidade de HC para atendimento das demandas operacionais.', N'A qualidade dos dados é um fator crítico para o sucesso dos estudos de dimensionamento. O saneamento prévio das informações e a validação das premissas aumentam significativamente a confiabilidade dos resultados.', 0, NULL, N'Aumentar a segurança na movimentação de tambores, padronizar o processo de transporte, melhorar as condições ergonômicas da atividade e elevar a eficiência das intervenções de manutenção.', '2026-07-08T00:00:00.000', '2026-08-03T14:54:31.000', N'81053475', NULL, NULL);
INSERT INTO #PVC VALUES (11581, N'81054419', N'81054419', N'Estruturação da Priorização dos Estudos de LDA e Extensão de Vida Útil com Base em Similaridade de Ativos e Disponibilidade de Dados', 1, N'Underground/Subterrâneo', N'A carteira de ativos demandando estudos de LDA e avaliações de extensão de vida útil apresentava elevado volume e recursos limitados para execução. Além disso, não existia um critério padronizado para priorização, resultando em dificuldades na definição dos ativos com maior potencial de obtenção de resultados no curto prazo.', N'Classificar 100% dos ativos candidatos a estudos de LDA e extensão de vida útil em níveis de prioridade, permitindo a elaboração de um roadmap estruturado para execução dos estudos e otimização da utilização dos recursos de engenharia.', N'10015', N'01 - Imagens/01 - Antes/11581.jpeg', N'Estudos de LDA e extensão de vida útil eram priorizados sem critério padronizado, dificultando o direcionamento dos recursos de engenharia.', N'01 - Imagens/02 - Depois/11581.jpeg', N'Ativos classificados por similaridade e disponibilidade de dados, permitindo priorização estruturada, roadmap definido e foco nos estudos de maior potencial de resultado.', NULL, N'A ausência de critérios de priorização foi eliminada por meio da classificação dos ativos conforme similaridade e disponibilidade de dados. Com isso, foi possível estruturar um roadmap de execução, aumentar a assertividade na seleção dos estudos e otimizar a aplicação dos recursos de engenharia.', N'Ativos classificados por similaridade e disponibilidade de dados, permitindo priorização estruturada, roadmap definido e foco nos estudos de maior potencial de resultado.', 0, NULL, N'Helps to keep vehicles clean', '2026-07-31T00:00:00.000', '2026-08-03T15:16:37.000', N'81054419', NULL, NULL);
INSERT INTO #PVC VALUES (11582, N'81020787', N'81020787', N'Porta paletes', 2, N'Others/Outros', N'Porta paletes sem nivelamento e falta de travas de segurança.', N'Melhorar a segurança do CTM', N'10234', N'01 - Imagens/01 - Antes/11582.jpeg', N'Porta paletes desnivelado, com falta de batente e travas de segurança.', N'01 - Imagens/02 - Depois/11582.jpeg', N'Novo porta palete com todas as travas de segurança.', NULL, N'Sim, maior segurança no armazenamento de material. ', N'Segurança', 0, NULL, N'Segurança: Eliminar o risco de vazamento de combustível e incêndio devido a quebra de filtros por impacto.
INSERT INTO #PVC VALUES (11583, N'81020787', N'81020787', N'Isolamento de segurança', 2, N'Others/Outros', N'área estava sem opção de isolamento no local de operação de equipamento. ', N'Mitigar a trânsito de pessoas na área de operação.', N'10234', N'01 - Imagens/01 - Antes/11583.jpeg', N'Sem dispositivo de isolamento.', N'01 - Imagens/02 - Depois/11583.jpeg', N'Com dispositivo para isolar a área de operação.', NULL, N'Com esse dispositivo instalado, temos como isolar e mitigar o trânsito de pessoas durante a operação.', N'Segurança', 0, NULL, N'Safer CSE', '2026-07-31T00:00:00.000', '2026-08-03T16:34:13.000', N'81020787', NULL, NULL);
INSERT INTO #PVC VALUES (11584, N'400428', N'400428', N'Unsafe Condition reporting', 2, N'Underground/Subterrâneo', N'Completed unsafe condition cards were being misplaced and not entered, reducing our actual target numbers', N'To have a centralized spot to place completed unsafe condition cards', N'10058', N'01 - Imagens/01 - Antes/11584.jpeg', N'No standard spot for employees to place completed unsafe condition cards, thereby increasing the chances of misplacing and not entering them.', N'01 - Imagens/02 - Depois/11584.jpeg', N'Creating a standard spot for completed cards and informing employees ', NULL, N'Yes. Problem was solved and awareness of potential hazards will make it to employees ', N'Will reduce misplaced cards and potential of employees not hearing of hazards', 0, NULL, N'Reduzir o tempo de exportação dos PDFs e padronizar a formatação dos arquivos enviados à turma de manutenção, acabando com a instabilidade e o risco de omissão de dados.', '2026-08-02T00:00:00.000', '2026-08-04T00:03:33.000', N'400428', NULL, NULL);
INSERT INTO #PVC VALUES (11585, N'81024026', N'81024026', N'Proteção para swith de  acionamento controle remoto', 2, N'Projects/Projetos', N'TODA VEZ OPERADOR DESLIGAVA COM O BRAÇO ACIDENTALMENTE  SISTEMA  DE CONTROLE REMOTO CAUSANDO FALHA NO EQUIPAMENTO', N'Evitar que braço do operador acione acidentalmente o swith', N'10137', N'01 - Imagens/01 - Antes/11585.jpeg', N'ANTERIORMENTE NÃO TINHA A PROTEÇÃO E CONSTEMENTE ERAMOS ACIONADOS PARA VERIFICAR FALHA NO EQUIPAMENTO E MAQUINA ENTRANDO NO CODIGO', N'01 - Imagens/02 - Depois/11585.jpeg', N'COM A PROTEÇÃO MELHORAMOS A SEGURANÇA OPERACIONAL E A PRODUTIVIDADE EVITANDO EQUIPAMENTO ENTRAR NO CODIGO', NULL, N'MELHOROU A EFICIENCIA DO EQUIPAMENTO', N'MELHORA DA SEGURANÇA OPERACIONAL', 2, 1, N'Redução do tempo de limpeza e manutenção, maior agilidade na drenagem da caixa, menor esforço da equipe e aumento da disponibilidade do equipamento.', '2026-08-03T00:00:00.000', '2026-08-04T00:10:07.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11586, N'1014096', N'1014096', N'Aging Kit Storage Clean Up', 1, N'Others/Outros', N'Items are removed from warehouse inventory and placed into Kits for work order execution. A large backlog of items had accumulated from as far back as 2020.', N'Reduce the number of unclaimed equipment sitting in kit storage.', N'10210', N'01 - Imagens/01 - Antes/11586.jpeg', N'Approximately $5.7M dollars worth of equipment was sitting in kit storage from aging WOs (2024 & older) and was not readily available for use.', N'01 - Imagens/02 - Depois/11586.jpeg', N'Low value work was stood down and tied up material was returned to inventory or sent for value recovery. This meant high value work could be executed, and the components were put to productive use.', NULL, N'74% of the value of items from 2024 and older were cleaned up and the remaining items have plans to get them cleaned up. A solid plan exists to do the same for items from 2025.', N'Not every good idea is high enough value to pursue.', 5000000, 3, N'Com a implantação das placas de identificação dos Pousos 1 e 2, foi possível transformar um conhecimento informal em um padrão visual acessível a todos, aumentando a organização da área, a eficiência operacional e a confiabilidade do processo de gestão das tampas dos vagões de cobre.', '2026-08-03T00:00:00.000', '2026-08-04T08:10:29.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11587, N'92000100', N'92000100', N'Acompanhamento empenho YEM', 1, N'Others/Outros', N'Já existia controle dos empenhos por tipo de ordem e ano, porém não havia um painel específico para gestão das ordens YEM, que não devem permanecer empenhadas por longos períodos. Sem essa visão detalhada, os responsáveis priorizavam a tratativa dos empenhos por ano, reduzindo o foco no acompanhamento e na regularização das ordens YEM.', N'Melhorar visibilidade das ordens empenhadas em YEM', N'10234', N'01 - Imagens/01 - Antes/11587.jpeg', N'Ausência de painel específico e detalhado para a gestão das ordens YEM, que, por sua natureza, não devem permanecer empenhadas por longos períodos, por se tratarem de ordens de atendimento a corretiva emergencial. Dessa forma, a ausência dessa visão dedicada dificultava a identificação e o tratamento dessas ordens.', N'01 - Imagens/02 - Depois/11587.jpeg', N'A criação do painel detalhado das ordens YEM empenhadas permitiu identificar gaps na tratativa, além de evidenciar os valores por frota e responsável. Essa visibilidade possibilitou direcionar as ações de forma mais assertiva, focando nos responsáveis e nas ordens que demandam maior atenção e prioridade.', NULL, N'Com a criação desse painel, foi possível ver progresso na tratativa e consequentemente redução no valor empenhado.', N'A criação do painel evidenciou que uma visão específica para ordens YEM é essencial para identificar gaps, direcionar responsabilidades, priorizar ações e reduzir o tempo de permanência dos empenhos, tornando a gestão mais eficiente e assertiva.', 0, NULL, N'RESTABELECIMENTO DO ACESSO SEGURO AO INTERIOR DO CHUTE PARA LIMPEZA E MANUTENÇÕES ', '2026-07-30T00:00:00.000', '2026-08-04T10:49:11.000', N'92000100', NULL, NULL);
INSERT INTO #PVC VALUES (11588, N'607274', N'607274', N'Diverting Excavated Material from Landfill Through Beneficial Reuse', 1, N'Projects/Projetos', N'Approximately 420 tonnes (200 m³) of clean excavated roadbed material from the Creighton Dam & Ditch project was planned for disposal at the CTA Landfill, while the nearby Meatbird Recreation Area Rehabilitation project required imported backfill. This resulted in unnecessary material procurement, transportation costs and landfill utilization. The opportunity was identified through project team and contractor coordination during construction execution planning.', N'Reuse / less material to landfill', N'10225', N'01 - Imagens/01 - Antes/11588.jpeg', N'Prior to implementation of the Kaizen, approximately 420 tonnes (200 m³) of clean excavated roadbed material from the Creighton Dam & Ditch project was designated for transport and disposal at the CTA Landfill. At the same time, the nearby Meatbird Recreation Area Rehabilitation project was scheduled to purchase and import granular backfill material for pump station foundation construction. This approach resulted in avoidable transportation, disposal, and material procurement costs, increased landfill utilization, and additional construction activities. The opportunity to utilize the excavated material at the Meatbird project had not yet been identified.', N'01 - Imagens/02 - Depois/11588.jpeg', N'Although the material consists of clean Granular A and Granular B aggregates, it is not suitable for reuse within the Creighton Dam & Ditch project because excavation activities have blended the material layers, preventing compliance with project-specific material requirements. By redirecting suitable excavated material from the Creighton Dam & Ditch project to the nearby Meatbird Recreation Area Rehabilitation project, transportation and material procurement costs were reduced while minimizing landfill utilization and supporting more efficient project execution.', NULL, N'Yes. The identified inefficiency was eliminated by reusing suitable excavated material between the two projects, reducing disposal, transportation, and material procurement requirements while achieving cost and sustainability benefits', N'Early identification of material-sharing opportunities between projects can eliminate unnecessary disposal, procurement, and transportation costs while maximizing the value of existing resources.', 0, NULL, N'A solução demonstra ganhos relevantes em segurança operacional, ergonomia, produtividade, mobilidade operacional e custo-benefício, reduzindo significativamente a necessidade de estruturas auxiliares convencionais, como andaimes e linhas de vida fixas. Destaca-se ainda a rapidez de mobilização, facilidade de aplicação em diferentes terrenos e ambientes, aderência às normas NR10, NR12 e NR35, além da redução da exposição dos executantes a riscos operacionais.', '2026-07-15T00:00:00.000', '2026-08-04T10:56:21.000', N'607274', NULL, NULL);
INSERT INTO #PVC VALUES (11589, N'81050243', N'81050243', N'PZ35 - Implementação de bomba d''água de 4 pistões', 1, N'Others/Outros', N'A bomba d’água descontinuada apresentava recorrentes entradas de ar no sistema devido a falhas de lubrificação nos copos dosadores dos eixos dos pistões de bombeamento de água. Além disso, sua vida útil era inferior a 3.000 horas de operação, comprometendo a confiabilidade e a disponibilidade do equipamento.', N'Ganhos na UF,DF e confiabilidade do ativo ', N'0', N'01 - Imagens/01 - Antes/11589.jpeg', N'A bomba d’água descontinuada apresentava recorrentes entradas de ar no sistema devido a falhas de lubrificação nos copos dosadores dos eixos dos pistões de bombeamento de água. Além disso, sua vida útil era inferior a 3.000 horas de operação, comprometendo a confiabilidade e a disponibilidade do equipamento.', N'01 - Imagens/02 - Depois/11589.jpeg', N'A bomba instalada possui função semelhante à bomba CAT Pumps, porém o modelo Bean destaca-se pela elevada confiabilidade operacional. Seu projeto incorpora reservatório interno de óleo lubrificante e camisas dos cilindros em cerâmica polida, proporcionando maior resistência ao desgaste e redução do atrito entre os componentes móveis. A carcaça robusta contribui para a estabilidade do conjunto, enquanto a configuração de quatro cilindros promove maior uniformidade no bombeamento, reduzindo pulsações e vibrações. Adicionalmente, a montagem vertical assegura a lubrificação contínua das partes móveis, resultando em maior vida útil, podendo alcançar até 6.000 horas de operação, além de aumentar a disponibilidade e a confiabilidade do equipamento.
INSERT INTO #PVC VALUES (11590, N'81057561', N'81057561', N'Interflon Líquido Contra Particulados', 1, N'Open Pit/Poço aberto', N'O radiador não possui nenhum sistema de proteção ao acumulo de particulados, este quando acumula por sua vez impede a troca de calor de forma eficiente, sendo assim o equipamento alarma alta temperatura do compressor e precisa parar para manutenção corretiva, sendo este um modo de falhas recorrente que afeta o MTBF.
INSERT INTO #PVC VALUES (11591, N'81033186', N'81033186', N'Personal Hydration Levels', 2, N'Others/Outros', N'As the months get warmer it is important that personnel remain hydrated and know when they should drink more water.  ', N'To inform personnel on proper hydration during the summer months.', N'10352', N'01 - Imagens/01 - Antes/11591.jpeg', N'There was no visual aid to remind personnel to stay hydrated in the laboratory and how they should be checking if they had been drinking enough water.', N'01 - Imagens/02 - Depois/11591.jpeg', N'There are now visual aids from the internet placed in all bathroom stalls and urinals in the Lab. Personnel can now self-evaluate hydration level based on urine color. ', NULL, N'Yes, people are now able to self-evaluate if they are properly hydrated.', N'Proper Hydration during summer months.', 0, NULL, N'Controle de acesso passou a ser realizado pelo operador diretamente envolvido na operação do galpão.
INSERT INTO #PVC VALUES (11592, N'520942', N'520942', N'Portão de Acesso autorizados', 2, N'Others/Outros', N'Acesso principal do posto com uso de corrente e cadeado e varias copias de chaves.', N'Acessar entrada de forma eletrônica', N'10077', N'01 - Imagens/01 - Antes/11592.jpeg', N'Antes; o acesso era controlado por cadeado e cada empregado possuía uma cópia, e a cada seis meses era feito a troca do cadeado e a copia de todos, um total por ano de 80 copias só para o portão.', N'01 - Imagens/02 - Depois/11592.jpeg', N'Depois; instalado uma fechadura eletrônica e projetado uma proteção de chapa de ferro para proteger contra chuva e sol. com essa nova aquisição vai diminuir compra de cadeados e cópias de chaves e risco de prensamento de dedos, mais eficaz e seguro.', NULL, N'menos custo e mais beneficio.', N'mais autonomia e eficiência', 0, NULL, N'TEMPO DE ATUAÇÃO NA MÁQUINA REDUZIDO E MELHORAR A ERGONOMIA DO LOCAL.', '2026-07-31T00:00:00.000', '2026-08-04T15:26:55.000', N'520942', NULL, NULL);
INSERT INTO #PVC VALUES (11593, N'478572', N'478572', N'Desenvolvimento de carro para transporte seguro de tambores de correias transportadoras', 1, N'Others/Outros', N'Durante a substituição de tambores de correias transportadoras, a movimentação e o transporte eram realizados sem um dispositivo dedicado, aumentando os riscos operacionais, dificultando o posicionamento seguro do componente e reduzindo a padronização e a eficiência das atividades de manutenção.', N'Reduzir a exposição dos empregados aos riscos de movimentação de cargas pesadas durante as atividades de substituição de tambores de correias transportadoras.', N'10294', N'01 - Imagens/01 - Antes/11593.jpeg', N'Antes, os tambores eram movimentados e armazenados sem dispositivo específico, dificultando o transporte, o posicionamento seguro e a padronização das atividades de manutenção.', N'01 - Imagens/02 - Depois/11593.jpeg', N'Implementado carro de transporte específico para tambores, garantindo movimentação padronizada, maior segurança, melhor ergonomia e maior eficiência operacional.', NULL, N'SIM. O problema foi resolvido com a implantação de um carro dedicado para transporte de tambores. A solução padronizou a atividade, proporcionou maior estabilidade durante a movimentação e reduziu a exposição a riscos operacionais.', N'Dispositivos simples e dedicados podem eliminar riscos operacionais, padronizar atividades e aumentar a eficiência das intervenções de manutenção.', 0, NULL, N'busca contínua pela segurança operacional e eficiência no campo nos levou a desenvolver uma solução definitiva para os procedimentos de manutenção hidráulica e mecânica em nossas perfuratrizes', '2026-07-31T00:00:00.000', '2026-08-04T15:34:02.000', N'478572', NULL, NULL);
INSERT INTO #PVC VALUES (11594, N'1014308', N'1014308', N'Vehicle Wash cabinet', NULL, N'Others/Outros', N'Supplies for cleaning port vehicles', N'Save time cleaning vehicles', N'10002', N'01 - Imagens/01 - Antes/11594.jpeg', N'Hard finding everything to clean vehicles and everything was in the open', N'01 - Imagens/02 - Depois/11594.jpeg', N'Have everything that is needed to clean vehicles. ', NULL, N'Yes', N'N/A', 0, NULL, N'Padronizar o procedimento e garante conformidade com as normas de segurança para trabalhos com ar comprimido.
INSERT INTO #PVC VALUES (11595, N'81050299', N'81050299', N'BASE DOS FILTRO DE COMBUSTIVEL', 1, N'Others/Outros', N'Os filtros de combustível e sensores do equipamento 797F estão expostos na lateral do motor.
INSERT INTO #PVC VALUES (11596, N'1009878', N'1009878', N'Drone Inspection for Overhead Debris', 2, N'Concentration/Concentração', N'Work had been ongoing in Mobile Hopper #1 and it was believed that the hopper was fully clean.  Over a weekend when personnel where off shift debris fell that had not been observed.  This caused scaffold damage and fell down through the hopper to the ground below.', N'Find a better way to verify cleaning', N'0', N'01 - Imagens/01 - Antes/11596.jpeg', N'While many hours where spent on the hopper cleaning extensively; debris was tucked away that could not be seen and fell to the ground below.  All CSE work was shutdown until a path forward could be determined.  The hopper needed to be inspected thoroughly and in a safe manner not placing people in harms way.', N'01 - Imagens/02 - Depois/11596.jpeg', N'After discussions in meetings it was determined the best path forward would be to use the site drone to inspect the hopper without the requirement for CSE.  Once areas of concern were identified rope access could then be contacted to remove the debris by entering the area from above so that they could safely remove the concentrate.', NULL, N'Yes.  A means to better means to inspect the hopper in a safe manner.', N'Drone Inspection for Future Hopper Inspections', 0, NULL, N'alternative grinder options to reduce the risk', '2026-08-04T00:00:00.000', '2026-08-05T06:52:48.000', N'1009878', NULL, NULL);
INSERT INTO #PVC VALUES (11597, N'478572', N'478572', N'Automação na geração de PDFs da Programação Semanal de Manutenção', 1, N'Others/Outros', N'A geração dos PDFs da programação semanal era totalmente manual. O programador precisava ir aba por aba, ajustar a área de impressão e exportar os arquivos. Esse processo consumia em média 10 minutos, podendo chegar a 30 minutos devido a travamentos do Excel e da nuvem. Além do tempo excessivo, o método gerava inconsistências visuais e risco de esquecer de gerar o PDF de alguma especialidade', N'Reduzir o tempo de geração dos PDFs de compartilhamento da programação semanal de ~10 minutos (podendo chegar a 30 min em caso de travamentos) para menos de 30 segundos, padronizando a formatação e eliminando o risco de erro humano na hora de exportar as abas.', N'10294', N'01 - Imagens/01 - Antes/11597.jpeg', N'A geração manual de PDFs aba por aba consumia de 10 a 30 minutos por travamentos do sistema. O método gerava arquivos desformatados e risco de omissão de alguma especialidade.', N'01 - Imagens/02 - Depois/11597.jpeg', N'Automação via botão de 1 clique gera e padroniza todos os PDFs em 25s. Reduziu o tempo de 10-30 minutos, eliminou travamentos do sistema e acabou com o risco de omissão de alguma aba.', NULL, N'A meta era reduzir o tempo e acabar com os travamentos. O resultado superou a expectativa: passamos de um processo manual de 10 a 30 minutos (sujeito a falhas) para uma rotina automatizada de 25 segundos, 100% confiável e padronizada.', N'Pequenas automações no Excel eliminam grandes desperdícios de tempo. A padronização de processos manuais via macro não apenas ganha tempo, mas reduz erros humanos e o estresse de lidar com travamentos do sistema, libertando a equipe para focar no planejamento.', 0, NULL, N'Eliminar o trabalho em altura durante o abastecimento de água e diesel dos MMU''s, reduzindo o risco de Alto para Eliminado e aumentando a segurança operacional.', '2026-08-04T00:00:00.000', '2026-08-05T10:06:19.000', N'478572', NULL, NULL);
INSERT INTO #PVC VALUES (11598, N'81058966', N'81058364', N'Confecção e Instalação de Canhão de Água para Limpeza da Baia CX-2057-05/06', 1, N'Others/Outros', N'Durante as atividades de limpeza da baia CX-2057-05/06, foi identificado que o processo era realizado com baixo alcance do jato de água, exigindo maior esforço manual, mais tempo de execução e dificultando a limpeza de áreas de difícil acesso, impactando a produtividade e a segurança operacional.', N'Confeccionar e instalar um canhão de água para aumentar o alcance do jato, reduzir o tempo de limpeza, diminuir o consumo de água e melhorar a segurança e eficiência da operação.', N'10031', N'01 - Imagens/01 - Antes/11598.jpeg', N': Antes da melhoria, a limpeza era realizada com equipamento de baixo alcance, exigindo reposicionamento constante, maior esforço manual e mais tempo para conclusão da atividade.', N'01 - Imagens/02 - Depois/11598.jpeg', N'Foi montado e instalado um canhão de água utilizando tubulação, curva de 90°, válvula de bloqueio e bico de descarga, proporcionando maior alcance do jato, facilidade de operação e maior eficiência na limpeza.', NULL, N'A meta foi alcançada. Com a instalação da válvula de dreno, o tempo de limpeza foi reduzido de aproximadamente 8 horas para cerca de 2,5 horas, facilitando a drenagem do material acumulado, reduzindo o esforço operacional e aumentando a eficiência da manutenção.', N'Soluções simples e de baixo custo podem gerar ganhos significativos em segurança, produtividade e padronização das atividades, reduzindo esforço operacional e melhorando a eficiência do processo.', 0, NULL, N'Disponibilizar a visualização em tempo real das imagens do Vision Rock para os técnicos da sala de controle, aumentando a confiabilidade do monitoramento da granulometria, agilizando a identificação de desvios e proporcionando maior assertividade na tomada de decisão operacional.', '2025-07-31T00:00:00.000', '2026-08-05T10:26:00.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11599, N'81042207', N'81054975', N'Implementação de Gestão Visual para Identificação dos Pousos de Tampas de Vagões de Cobre', 1, N'Others/Outros', N'Durante inspeção realizada no galpão de descarga de vagões de cobre, foi identificado que os locais destinados ao repouso de tampas de vagões, conhecidos informalmente como Pouso 1 e Pouso 2, não possuíam qualquer tipo de identificação visual. Essa condição fazia com que somente os colaboradores habituados ao processo soubessem diferenciar os locais, gerando dependência de conhecimento tácito, dificuldades para novos operadores e possibilidade de erros na segregação e utilização das tampas durante as atividades de manutenção e substituição.
INSERT INTO #PVC VALUES (11600, N'81036958', N'81036958', N'JANELA VISITA TR2009-05', 1, N'Projects/Projetos', N'JANELAS DE VISITA ANTIGAS FORAM BLOQUEADAS POR VIGAS ESTRUTURAIS FAZENDO COM QUE AS MESMAS FICASSEM INACESSIVEIS , OUTRO PONTO A SER LEVADO EM CONSIDERAÇÃO É QUE AS JANELAS ANTIGAS ESTAVAM DETERIORADAS MECANICAMENTE', N'INSTALAR JANELAS PADRONIZADAS', N'10031', N'01 - Imagens/01 - Antes/11600.jpeg', N'JANELAS ANTIGAS OBSTRUIDAS POR VIGAS ESTRUTURAIS INSTALADAS PELA EQUIPE DE PROJETOS, JANELAS COM ALTO NIVEL DE DETERIORAÇÃO E INACESSIVEIS PARA LIMPEZA DE ROTINA E MANUTENÇÃO DO ATIVO DURANTE PARADAS DE MANUTENÇÃO ', N'01 - Imagens/02 - Depois/11600.jpeg', N'INSTALAÇÃO DE JANELA PADRONIZADA COM ACESSO LIMITADO POR GRADE QUE AUXILIA NA INSPEÇÃO DO CHUTE E RASPADOR PRIMARIO. JANELA ACESSIVEL DE FORMA ERGONOMICA SEGURA PARA LIMPEZA E MANUTENÇAO DURANTE PARADAS SEM EXPOR EXECUTANTES A RISCOS ERGONOMICOS OU FISICOS COMO CORTES POR CONTATO COM CHAPARIA DO CHUTE. ', NULL, N'O ACESSO AO INTERIOR DO CHUTE FOI RESTABELECIDO DE FORMA SEGURA TANTO PARA AS EQUIPES DE LIMPEZA QUANTO PARA AS MANUTENÇÕES DO EQUIPAMENTO. ', N'PADRONIZAÇÃO TRANSFORMA O AMBIENTE DE TRABALHO MAIS SEGURO ', 0, NULL, N'Results as planned. All stakeholders are able to utilize these prints.', '2026-06-24T00:00:00.000', '2026-08-05T11:34:41.000', N'81036958', NULL, NULL);
INSERT INTO #PVC VALUES (11601, N'81057561', N'81057561', N'Linha de Vida Móvel', 1, N'Open Pit/Poço aberto', N'Para determinados trabalhos em altura existe a necessidade de montagem de andaimes para ancoragem, o que leva muito tempo dependendo da demanda e da altura que necessitamos que seja montado o andaime no equipamento.
INSERT INTO #PVC VALUES (11602, N'81062687', N'81062687', N'RLS Basket Strainer Gasket Storage', 3, N'Others/Outros', N'Most gaskets are stored on the opposite corner of the plant. Having the basket strainer gaskets stored in the immediate vicinity of the RLS pumps allows for faster access and saves time not having to go look for the right size.', N'To provide quick and easy access to gaskets at point of work.', N'0', N'01 - Imagens/01 - Antes/11602.jpeg', N'Basket strainer gaskets, if on hand, could be found in the POL Laydown on the south side of the building. The RLS area is toward the Northeast corner of the building. ', N'01 - Imagens/02 - Depois/11602.jpeg', N'Now there is a designated storage area for basket strainer gaskets in the immediate vicinity of the RLS area, eliminating the need to traverse the building to look for them. Included in this 5S improvement are the stock code for re-ordering and minimum/maximum quantities to ensure that they are always available.', NULL, N'Gaskets are now stored on the wall in the area where they are used, with stock code and min/max quantities posted to ensure they are re-ordered and readily available.', N'5S improvement like having parts stored in their areas of use can improve efficiency by saving time not having to travel very far or search for what is needed.', 0, NULL, N'1 bearing costs ~$40,000 after installation.
INSERT INTO #PVC VALUES (11603, N'81057561', N'81057561', N'Mangueiras CAT', 3, N'Open Pit/Poço aberto', N'Baixa confiabilidade das mangueiras ALFAGOMMA, alto número de paradas para substituir mangueiras.', N'Aumentar a confiabilidade operacional dos equipamentos, trazendo mangueiras mais robustas e de melhor qualidade para serem utilizadas na frota, buscando uma diminuição no número de paradas corretivas, com isso aumento do MTBF.', N'10015', N'01 - Imagens/01 - Antes/11603.jpeg', N'Para manutenções corretivas utilizamos mangueiras ALFAGOMMA, a incidência de problemas com montagem de mangueiras, qualidade da mangueira propriamente dita, estava refletindo em muitas paradas corretivas por conta de vazamento hidráulico, onde a solução é quase sempre a troca da mangueira, impacto no MTBF e MTTR.', N'01 - Imagens/02 - Depois/11603.jpeg', N'Com a aquisição de material, temos a disponibilidade de utilizar a fábrica interna da Sotreq no site de Salobo para confecção de mangueiras a serem utilizadas na frota de perfuração.
INSERT INTO #PVC VALUES (11604, N'81042207', N'495412', N'Controle Seguro de Acesso ao Galpão de Descarga de Cobre', 1, N'Others/Outros', N'O processo de descarga de vagões de cobre dentro do galpão envolve a operação simultânea da ponte rolante (para destampar vagões) e da escavadeira hidráulica (para retirar o material e alimentar o sistema).​
INSERT INTO #PVC VALUES (11605, N'544566', N'544566', N'RELOCAÇÃO BOTOEIRA SELETORA UNIDADE HIDRÁULICA BR-2104SA-01', 1, N'Crusher/Britadeira', N'DEVIDO A INSTALAÇÃO DA BOTOEIRA SELETORA DO BRITADOR BR-2104SA-01 SER EM LOCAL DE DIFICIL ACESSO E ESCONDIDA HOUVE UMA PARADA DO BRITADOR POR CERCA DE 3 HORAS DEVIDO A MESMA ESTAR COM SUA SELEÇÃO EM CAMPO PARA MANUAL . AS EQUIPES DE MECÂNICA , OPERAÇÃO E ELÉTRICA TIVERAM EXTREMA DIFICULDADE EM ENCONTRAR O SISPOSITVO. ', N'ELIMINAR FALHAS DE ACIONAMENTO DA BOTOEIRA SELETORA', N'0', N'01 - Imagens/01 - Antes/11605.jpeg', N'BOTOEIRA DE SELEÇÃO MANUAL E AUTOMÁTICO DA UNIDADE DE LUBRIFICAÇÃO DO BRITADOR BR-2104SA-01 FICAVA EM LOCAL DE DÍFICIL ACESSO , LEVANDO SITUAÇÕES EXTREMAS EM SUA MANUTENÇÃO . ', N'01 - Imagens/02 - Depois/11605.jpeg', N'SELETORA FOI RELOCADA PARA A FORA DA UNIDADE HIDRÁULICA , GERANDO MELHORES CONDIÇÕES DE SEGURANÇA E MANUTENÇÃO . FEITO IDENTIFICAÇÃO DA SELETORA EM CAMPO PARA FACILITAR NA OPERAÇÃO .', NULL, N'HOJE DEVIDO A RELOCAÇÃO DO DISPOSITIVO ESTAMOS COM MAIS PRATICIDADE NA MANUTENÇÃO E IDENTIFICAÇÃO .', N'COMPONENTES PRECISAM ESTAR EM LOCAL MAIS ADEQUADO PARA MANUTENÇÃO.', 0, NULL, NULL, '2026-08-04T00:00:00.000', '2026-08-05T15:42:43.000', N'544566', NULL, NULL);
INSERT INTO #PVC VALUES (11606, N'81059721', N'545523', N'CRIAÇÃO DE DISPOSITIVO DE TRAVA DE HASTES PARA PERFURATRIZES', 2, N'No Replication/Sem replicação', N'O procedimento tradicional de retenção de hastes nas perfuratrizes dependia de cordas, cintas e tubos improvisados. Essa prática trazia alta instabilidade e expunha a equipe a riscos graves de acidentes pessoais e danos materiais aos equipamentos. Além da insegurança, demandava muito tempo para amarrações e ajustes, tornando a rotina lenta e ineficiente.', N'Evitar instabilidade e a equipe a riscos graves de acidentes pessoais e danos materiais aos equipamentos.', N'10144', N'01 - Imagens/01 - Antes/11606.jpeg', N'O procedimento tradicional de retenção de hastes nas perfuratrizes dependia de cordas, cintas e tubos improvisados. Essa prática trazia alta instabilidade e expunha a equipe a riscos graves de acidentes pessoais e danos materiais aos equipamentos. Além da insegurança, demandava muito tempo para amarrações e ajustes, tornando a rotina lenta e ineficiente.
INSERT INTO #PVC VALUES (11607, N'81059721', N'365593', N'INSTALAÇÃO DE REGISTRO DA EXTREMIDADE DA MANGUEIRA DO COMPRESSOR DE AR', 2, N'No Replication/Sem replicação', N'Mangueira do compressor de ar sem registro na extremidade, ocorrendo acionamentos involuntários quando usando em equipamento como bombas e ferramentas pneumáticas.', N'Elimina o efeito chicote e vazamentos durante a troca de ferramentas', N'10144', N'01 - Imagens/01 - Antes/11607.jpeg', N'A mangueira do compressor de ar não possuía registro na extremidade. Ocorrendo acionamentos involuntários, quando utilizado o equipamento, causando disparos acidentais ao operar bombas e ferramentas pneumáticas.
INSERT INTO #PVC VALUES (11608, N'189456', N'189456', N'Melhoria de informação no relatório despacho info resumo mina', 1, N'Open Pit/Poço aberto', N'Falta de uma visão unificada da frota, dificultando a identificação ágil dos caminhões disponíveis e daqueles em manutenção em um único relatório.', N'Informação rápida em um único relatório', N'0', N'01 - Imagens/01 - Antes/11608.jpeg', N'A ausência de um relatório único e consolidado para acompanhamento dos caminhões disponíveis e em manutenção dificulta a obtenção de informações rápidas e confiáveis sobre a situação da frota. Como consequência, as equipes precisam consultar diferentes fontes de dados, aumentando o tempo de análise e o risco de informações divergentes.', N'01 - Imagens/02 - Depois/11608.jpeg', N'A consolidação das informações de caminhões disponíveis e em manutenção em um único relatório proporciona maior agilidade e eficiência na gestão da frota. Com uma visão centralizada, as equipes conseguem identificar rapidamente a situação operacional de cada frota, reduzindo o tempo gasto na busca de informações em diferentes fontes garantindo assim maior eficiência operacional, melhor utilização dos ativos e mais velocidade na tomada de decisão, contribuindo para o alcance das metas de produção e disponibilidade da frota.', N'http://172.19.144.219/ReportServer/Pages/ReportViewer.aspx?/Planejamento/Relat%c3%b3rios+operacionais/Informativo+Resumo+Mina&rs:Command=Render', N'Ausência de meta anterior.', N'agilidade e eficiência na gestão da frota', 0, NULL, N'Todo material enviado via expresso deve possuir controle de rastreamento e registro de cada etapa da entrega.', '2026-08-05T00:00:00.000', '2026-08-06T11:09:20.000', N'189456', NULL, NULL);
INSERT INTO #PVC VALUES (11609, N'200795', N'607697', N'Alternate Grinder with Improved Safety Switch Configuration', 2, N'Underground/Subterrâneo', N'Worker was injured June 23, 2026 when they reached into their tool bag and a cordless grinder inadvertently started resulting in laceration to left index finger.', N'Source alternate grinders with other safety switch configurations', N'10202', N'01 - Imagens/01 - Antes/11609.jpeg', N'While reaching into the tool bag to grab a hammer, a worker accidentally triggered a battery-operated grinder. The safety switch moves in the same direction as the paddle. The grinder cut through the glove on the workers other hand requiring stitches
INSERT INTO #PVC VALUES (11610, N'81051447', N'81051447', N'Eliminação do Trabalho em Altura no Abastecimento de Água e Diesel dos MMU''s por Meio da Adequação do Sistema de Abastecimento', 2, N'Others/Outros', N'O processo de abastecimento de água e diesel dos MMU''s exigia que o operador realizasse acesso em altura para conectar e operar os pontos de abastecimento localizados na parte superior do equipamento. Essa condição expunha os trabalhadores ao risco de queda de altura, classificado como risco alto na matriz de riscos, além da exposição ao contato com diesel durante a operação. Apesar da existência de controles administrativos e requisitos de trabalho em altura, a atividade mantinha potencial para ocorrência de acidentes graves. Diante desse cenário, foi identificada a necessidade de uma solução de engenharia que eliminasse a exposição ao risco na fonte.', N'Eliminar a necessidade de acesso em altura durante as atividades de abastecimento de água e diesel dos MMU''s, reduzindo a exposição dos trabalhadores ao risco de queda de nível diferente e ao contato com diesel, elevando a segurança operacional e promovendo melhoria sustentável no processo.', N'10253', N'01 - Imagens/01 - Antes/11610.jpeg', N'-Necessidade de acesso à parte superior do MMU para abastecimento de água e diesel.
INSERT INTO #PVC VALUES (11611, N'488890', N'488890', N'Toque e veja.', 1, N'Projects/Projetos', N'Para o monitoramento da granulometria do minério transportado pelas correias 2051 TC 01, que alimenta a pilha pulmão, e 2301 TC 05, o sistema Vision Rock disponibilizava apenas os dados granulométricos. Embora o equipamento também possua recurso de visualização por imagem, essa funcionalidade não estava disponível para acompanhamento em tempo real pelos técnicos da sala de controle, limitando a análise operacional e a tomada de decisão.', N'Visualizar o material do Vision Rock da 2051 TC 01 e 2301 TC 05 em tempo real.', N'10054', N'01 - Imagens/01 - Antes/11611.jpeg', N'O sistema Vision Rock, responsável pelo monitoramento da granulometria do minério nas correias 2051 TC 01 (alimentação da pilha pulmão) e 2301 TC 05, disponibilizava apenas os dados granulométricos para a sala de controle. Apesar de o equipamento possuir recurso de visualização por imagem, essa funcionalidade não era acessível aos técnicos de operação, restringindo a validação visual das informações, reduzindo a confiabilidade das análises operacionais e dificultando a tomada de decisão em tempo real.', N'01 - Imagens/02 - Depois/11611.jpeg', N'Foi disponibilizada a visualização das imagens do sistema Vision Rock para os técnicos da sala de controle, permitindo o acompanhamento em tempo real da granulometria do minério nas correias 2051 TC 01 e 2301 TC 05. Com essa implementação, passou a ser possível validar visualmente as informações fornecidas pelo sistema, proporcionando maior confiabilidade no monitoramento do processo, maior agilidade na identificação de desvios granulométricos e melhor suporte à tomada de decisão operacional.', NULL, N'Antes da melhoria, os técnicos da sala de controle tinham acesso apenas aos dados granulométricos do Vision Rock, sem a visualização das imagens. Após a implantação, as imagens passaram a ser disponibilizadas em tempo real, aumentando a confiabilidade do monitoramento e proporcionando maior assertividade na tomada de decisão operacional.', N'O aproveitamento de recursos existentes aumentou a confiabilidade operacional e a agilidade na tomada de decisão.', 0, NULL, N'The objective was achieved by creating a clear and accessible tracking system that provides visibility of all active safety notices and associated timelines. The process reduces the risk of using outdated information and improves overall communication and compliance.', '2026-08-03T00:00:00.000', '2026-08-06T12:27:25.000', N'488890', NULL, NULL);
INSERT INTO #PVC VALUES (11612, N'81041701', N'81041701', N'Ferramenta de Gestão do Processo de Manutenção do Sistema Remoto', 1, N'Others/Outros', N'Demandas do time de monitoramento com dificuldade de gerir, devido as ordens sistemáticas, necessidades do sistema e solicitações do processo de preditiva. 
INSERT INTO #PVC VALUES (11613, N'1010585', N'300563', N'Ventilation Prints', 1, N'Underground/Subterrâneo', N'Ventilation requirements were being communicated through comments on a mid-range block plan. While these comments identified high-level requirements, they lacked the detailed information to support planning and implementation.', N'Develop detailed ventilation prints that clearly define all ventilation requirements, installation details, and supporting information required for successful execution.', N'10357', N'01 - Imagens/01 - Antes/11613.jpeg', N'Ventilation requirements were provided as notes and comments on block plans by the Ventilation Specialist. ', N'01 - Imagens/02 - Depois/11613.jpeg', N'Detailed ventilation prints are issued, including ducting layouts, accessories, fan specification and installation requirements providing a complete plan for execution.', NULL, N'The issue has been successfully resolved, as Operations now receives a complete understanding of requirements before installation begins. All stakeholders have greater visibility into project needs, including planners who can accurately design drift dimensions and other critical elements. This improved level of detail enhances communication, alignment, and decision-making across the entire process, resulting in more effective planning and execution.', N'Detailed Prints', 0, NULL, N'Padronização das análises dos históricos de falhas.', '2026-08-04T00:00:00.000', '2026-08-06T12:45:49.000', N'1010585', NULL, NULL);
INSERT INTO #PVC VALUES (11614, N'81041701', N'81041701', N'Ampliação da faixa de frequência monitorada nas células de flotação.', NULL, N'Crusher/Britadeira', N'O monitoramento de telemetria é essencial para acompanhar continuamente as variações do equipamento. Porém para as CFs da usina III que são redutores robustos e os sensores são colados longes do rolamento, além da rotação ser baixa no eixo de saída (88 RPM), precisávamos de uma coleta de vibração com maior sensibilidade. 
INSERT INTO #PVC VALUES (11615, N'81040957', N'81040957', N'Ultrasonic Greasing of Generator Bearings', 1, N'Smelting/Fundição', N'After a premature fixed bearing failure, greasing practices were focused on to prevent future bearing failures. The frequency of bearing greasing was to be determined, as well as methodology/equipment required to ensure optimal quantity of grease is injected into the bearings each time. ', N'Ensure accurate greasing frequency and quantity of generator bearings.', N'10111', N'01 - Imagens/01 - Antes/11615.jpeg', N'Greasing PM''s were set to bi-weekly, with inadequate quantity of grease injected into the bearings, contributing to premature failures. No equipment installed to monitor bearing conditions or assist with greasing. 
INSERT INTO #PVC VALUES (11616, N'81013114', N'81013114', N'Increase Hi SP', 1, N'Others/Outros', N'A sump LI was cycling, causing alarm to ring in sometimes 50-60 times a day.', N'To decrease DCS alarms', N'0', N'01 - Imagens/01 - Antes/11616.jpeg', N'A LI on a sump in our building was cycling, causing a Hi sump level alarm to ring in on DCS.', N'01 - Imagens/02 - Depois/11616.jpeg', N'A request was made to DCS support to increase the Hi setpoint alarm on the sump, causing the alarm to not ring in on DCS as frequently. But the sump still kicking in and pumping the solution', NULL, N'Yes so far the problem has been solved, the sump is doing its job while not having the alarm ring  in on DCS panel', N'An easy solution to get of unnessesary alarms', 0, NULL, N'A implementação da melhoria eliminou aproximadamente 2.350 tratativas manuais por mês relacionadas a horímetros repetidos, reduzindo cerca de 26,5 horas mensais de atividades operacionais e evitando mais de 1.500 interrupções no processamento. Com isso, o robô passou a executar o processo de forma contínua e confiável, alcançando 100% de sucesso no tratamento dessas ocorrências e aumentando a eficiência da automação.', '2026-08-05T00:00:00.000', '2026-08-06T14:14:30.000', N'81013114', NULL, NULL);
INSERT INTO #PVC VALUES (11617, N'202638', N'202638', N'Shipping cost savings', 1, N'Refining/Refino', N'Shipping copper cathodes to have copper removed had a quoted price of $1700 per load', N'Cost savings', N'0', N'01 - Imagens/01 - Antes/11617.jpeg', N'Shipping cost per load regardless of weight was $1700 per load quoted for contractor', N'01 - Imagens/02 - Depois/11617.jpeg', N'Sent out for quote and through Vale shipping portal we were able to get a quote for $950 per load. 8 loads total for a savings of $6000', NULL, N'yes, savings realized', N'Get quotes for all requests to find the cheapest price', 6000, 3, N'AHORA HÁ UMA MELHOR OTIMIZAÇÃO DO TEMPO DA EQUIPE.', '2026-08-05T00:00:00.000', '2026-08-06T15:02:21.000', N'202638', NULL, NULL);
INSERT INTO #PVC VALUES (11618, N'202638', N'1008697', N'Reduce WLN loading', NULL, N'Refining/Refino', N'Excess water being sent to WLN', N'Reduce water load to WLN', N'0', N'01 - Imagens/01 - Antes/11618.jpeg', N'The nickel dip tanks are always overflowing to prevent quality issues', N'01 - Imagens/02 - Depois/11618.jpeg', N'Water consumption was evaluated and reduced by.5m3 for a total of 24m3 per day (.5m3 per dip tank, two dip tanks) ', NULL, N'Yes reduced water sent to spillage', N'always look for waste and ways to reduce', 10000, 3, N'Se realiza trabajo de manera más rapida y con menos errores humanos.', '2026-08-05T00:00:00.000', '2026-08-06T15:13:43.000', N'202638', NULL, NULL);
INSERT INTO #PVC VALUES (11619, N'81011654', N'81011654', N'PADRONIZAÇÃO E OTIMIZAÇÃO DAS LISTAS DE TAREFAS SAP COM USO DO MICROSOFT COPILOT', 1, N'Others/Outros', N'ATUALMENTE AS LISTAS DE TAREFA APRESENTAM FALTA DE PADRONIZAÇÃO NA ESTRUTURA, CONTEÚDO E NÍVEL DE DETALHAMENTO, GERANDO DIVERGÊNCIAS NO PLANEJAMENTO E NA EXECUÇÃO DAS ATIVIDADES. ESSA VARIAÇÃO RESULTA EM RETRABALHOS, MAIOR TEMPO DE PREPARAÇÃO DAS ORDENS, DIFICULDADES NA ESTIMATIVA DE RECURSOS E REDUÇÃO DA EFICIÊNCIA DO PROCESSO DE MANUTENÇÃO. A AUSÊNCIA DE UM PADRÃO TÉCNICO TAMBÉM IMPACTA A QUALIDADE DOS REGISTROS E A REPLICABILIDADE DAS MELHORES PRÁTICAS.', N'PADRONIZAR E OTIMIZAR AS LISTAS DE TAREFA DE MANUTENÇÃO, GARANTINDO MAIOR QUALIDADE NO PLANEJAMENTO, REDUÇÃO DE RETRABALHOS, PADRONIZAÇÃO DAS ORDENS SAP, MELHORIA DA PRODUTIVIDADE E AUMENTO DA CONFIABILIDADE DAS INFORMAÇÕES UTILIZADAS PELAS EQUIPES DE EXECUÇÃO.', N'10279', N'01 - Imagens/01 - Antes/11619.jpeg', N'As listas de tarefas SAP possuíam informações repetidas, excesso de texto e falta de padronização, dificultando o planejamento das atividades de manutenção. Além disso, havia baixa aderência aos requisitos definidos no PRO-046572 Diretriz de Segurança Para Planejar Ordem de Manutenção - Sossego, resultando em maior tempo para elaboração das tarefas, variações na qualidade das informações cadastradas e risco de interpretações divergentes durante a execução das atividades.', N'01 - Imagens/02 - Depois/11619.jpeg', N'As listas de tarefas SAP foram revisadas, simplificadas e padronizadas em conformidade com o PRO-046572 Diretriz de Segurança Para Planejar Ordem de Manutenção - Sossego, eliminando redundâncias e incorporando os requisitos mínimos de SSMA. Também foram criadas chaves modelo para cada etapa da manutenção, garantindo uma estrutura padronizada para elaboração das atividades. Adicionalmente, foi desenvolvido um prompt padronizado no Microsoft Copilot para geração automática das descrições de Ordens SAP.
INSERT INTO #PVC VALUES (11620, N'81034352', N'81055552', N'Implementação de preenchimento automático no cadastro de pesagens', 1, N'Others/Outros', N'O sistema não permitia pesquisar os registros digitando o nome. Para localizar informações como empresa, material e outros campos, era necessário percorrer manualmente a barra de rolagem até encontrar a opção desejada. Esse processo aumentava o tempo de cadastro das pesagens, tornava a operação menos ágil e favorecia a seleção incorreta de itens. ', N'Reduzir tempo de cadastro das pesagens, eliminando o atraso procurando material por meio do preenchimento automático dos campos. ', N'10233', N'01 - Imagens/01 - Antes/11620.jpeg', N'Sistema não permitia pesquisar os registros digitando o nome. Para localizar informações como empresa, material e outros campos, era necessário percorrer manualmente a barra de rolagem até encontrar a opção desejada. Esse processo aumentava o tempo de cadastro das pesagens, tornava a operação menos ágil e favorecia a seleção incorreta de itens. ', N'01 - Imagens/02 - Depois/11620.jpeg', N'Com a implementação da pesquisa por digitação, basta inserir as primeiras letras para que o sistema localize e complete automaticamente o registro, reduzindo o tempo de busca e aumentando a eficiência operacional.', NULL, N'A melhoria atendeu ao objetivo proposto, eliminando a necessidade de percorrer a barra de rolagem para localizar informações. O preenchimento por pesquisa tornou o cadastro mais rápido, eficiente e com menor risco de erros na seleção dos dados.', N'Melhorias no sistema podem gerar grande impacto significativo na rotina.', 0, NULL, N'Se espera incentivar a los trabajadores a realizar actividad fisica en proyecto', '2026-08-03T00:00:00.000', '2026-08-06T17:54:16.000', N'81034352', NULL, NULL);
INSERT INTO #PVC VALUES (11621, N'550315', N'550315', N'CADERNO DE ENTREGA:  EXPRESSO PERFURAÇÂO', 1, N'Others/Outros', N'Durante a execução das atividades do projeto Expresso Perfuração, foi identificada a falta de materiais enviados via transporte expresso', N'Este caderno tem como finalidade formalizar a entrega dos serviços executados no projeto Expresso Perfuração', N'10234', N'01 - Imagens/01 - Antes/11621.jpeg', N'Não existe um Caderno de Entrega do Expresso Perfuração formalizado e consolidado contendo todas as informações, evidências, registros técnicos, documentos de inspeção, testes realizados e aprovações necessárias para a entrega oficial do projeto.', N'01 - Imagens/02 - Depois/11621.jpeg', N'Foi identificado atraso e interrupções nas atividades de perfuração devido a falhas operacionais nos equipamentos e condições adversas encontradas em campo, comprometendo a execução conforme o planejamento inicial.', NULL, N'A ocorrência evidenciou a necessidade de aprimorar os controles logísticos e a rastreabilidade dos materiais enviados via expresso', N'Fortalecer a rastreabilidade dos materiais  Todo material enviado via expresso deve possuir controle de rastreamento e registro de cada etapa da entrega.', 0, NULL, N'Proteger a los trabajadores de las ráfagas de viento que se pueden presentar en la región en estas fechas.', '2026-08-06T00:00:00.000', '2026-08-07T04:16:07.000', N'550315', NULL, NULL);
INSERT INTO #PVC VALUES (11622, N'92000587', N'81002955', N'RECUPERAÇÃO E ADEUQAÇÃO DAS BASES DE FIXAÇÃO ', 1, N'Others/Outros', N'APRESENTAVA DEFORMÇÕES, DESGASTE E FUROS DE FIXAÇÃO DANIFICADOS, NECESSITANTODA RECUPERAÇÃO PARA RESTABELECER SUAS CONDIÇÕES ADEQUADAS DE UTILIZAÇÃO ', N'RESTABELECER AS CONDIÇÕES ADEQUADAS DE USO E AFIXAÇÃO DO CONJUNTO ', N'10144', N'01 - Imagens/01 - Antes/11622.jpeg', N'Componente apresentava deformações, desgaste e danos nos pontos de fixação, incluindo furos comprometidos, necessitando de recuperação para garantir as condições adequadas de utilização.', N'01 - Imagens/02 - Depois/11622.jpeg', N'Foi realizada a recuperação dos componentes, contemplando o desempeno das peças, substituição da base do deslizante, recuperação de alguns furos, execução de novos furos nas bases de fixação no truque e aplicação de nova pintura.', NULL, N'Sim. O conjunto foi recuperado, com correção das deformações, recuperação e execução dos furos de fixação, substituição da base do deslizante e nova pintura, restabelecendo suas condições adequadas de utilização.', N'A identificação precoce de desgastes e danos permite uma recuperação preventiva e evita o agravamento dos problemas.', 0, NULL, N'Melhoria da produtividade e desempenho operacional através da disponibilização de um suporte adequado para o Tote Bin de sabão.', '2026-08-06T00:00:00.000', '2026-08-07T05:15:53.000', N'92000587', NULL, NULL);
INSERT INTO #PVC VALUES (11623, N'974865', N'81002390', N'Base de Apoio para Martelete Elétrico', 3, N'Others/Outros', N'Não havia local especifico para guardar as ferramentas elétricas as mesma eram acondicionadas no chão.
INSERT INTO #PVC VALUES (11624, N'1010585', N'300608', N'Safety Notice Tracking Sheet', NULL, N'Others/Outros', N'Improve visibility and management of active safety notices to ensure all team members are aware of current notices, upcoming action dates and expiration timelines.', N'To improve visibility and management of safety notices', N'10357', N'01 - Imagens/01 - Antes/11624.jpeg', N'Safety notices were tracked through the safety notice site and email notifications to the individual who originally created the notice. As staff changed roles or new employees joined the team, they weren''t apprised of the expiry as they weren''t on the email list. This created lack of visibility regarding safety notices that are active, upcoming expiry dates and we don''t want this overlooked during the planning and design stage.', N'01 - Imagens/02 - Depois/11624.jpeg', N'A centralized safety notice tracking sheet was developed and is maintained by the Divisional supervisor. The tracking sheet provides visibility of all the active safety notices and their associated timelines. Team members can now proactively monitor upcoming expiry dates, understand ownership and required actions, and ensure current safety notices are considered during planning activities. The process reduces the risk of using outdated information and improves overall communication and compliance.', NULL, N'Yes, the implementation of the safety notice tracking sheet successfully addressed the visibility gap. The team now has a single source of truth for the active safety notices, making it easy to identify current notices, track expiration dates, and take timely action. This has improved awareness and accountability, and confidence that layout plans are being developed using current and valid safety notices.', N'Visibility Gap Solved', 0, NULL, N'5S (Senso de Organização e Identificação)
INSERT INTO #PVC VALUES (11625, N'471876', N'471876', N'RUIDO EXCESSIVO NA SALA DE ABOSRÇÃO ATÔMICA', 1, N'Others/Outros', N'Rotor da sala de absorção com ruido excessivo.', N'Reduzir ruido ', N'10032', N'01 - Imagens/01 - Antes/11625.jpeg', N'Tivemos um ocorrido, onde um dos exaustores da sala de absorção atômica ficou com ruido excessivo ficando impraticável trabalhar naquela condição 79,6 decibéis, com isso, ficou parado um equipamento de 38.000 reais, que consegue produzir em condições normais , 1 amostra a cada 3 minutos, colocando em 24 horas e contemplando os horários de parada do Técnico, faria, 410 amostras, ou seja, deixamos de fazer, 87.320 amostras em 6 meses.', N'01 - Imagens/02 - Depois/11625.jpeg', N'Pesquisamos no mercado, colocamos um Exaustor mais silencioso e com a mesma performance do projeto original, solucionado e reestabelecida a analise, com o Técnico trabalhando conforme rege a Higiene ocupacional, 65,1 Decibéis.', NULL, N'resolvido', N'que com a pesquisa e recomendações conseguimos', 0, NULL, N'ESPERA-SE MANTER O CARREGADOR DE BATERIAS, EM LOCAL FIXO, IDENTIFICADO E ORGANIZADO.', '2026-08-03T00:00:00.000', '2026-08-07T11:16:39.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (11626, N'487516', N'487516', N'Controle de notas YE', 1, N'Others/Outros', N'Inexistência de relatório padrão que permita busca rápida das falhas ocorridas por componente, relacionando ao histórico de reformas anteriores e ordens de correção.', N'Criação de controle que permita a busca rápida das falhas ocorrida com os componentes, histórico da reforma e nota da tratativa.', N'10008', N'01 - Imagens/01 - Antes/11626.jpeg', N'Inexistência de controle de notas YE para as falhas. Necessidade de busca no SAP conforme necessidade das informações.', N'01 - Imagens/02 - Depois/11626.jpeg', N'Controle de notas YE relacionadas a falhas de componentes que permitam a criação de relatórios de busca por código Vale, número do equipamento, frota, fornecedor, garantia etc.', NULL, N'Sim.
INSERT INTO #PVC VALUES (11627, N'516619', N'516619', N'Adequação da Altura do Peneirador ', 1, N'No Replication/Sem replicação', N' Equipamento apresenta instabilidade operacional e altura inadequada em relação ao piso, dificultando o acesso seguro para operação,', N'Melhorar estabilidade estrutural, alinhamento adequado e elevação compatível com as necessidades operacionais e Ergonômicas', N'10032', N'01 - Imagens/01 - Antes/11627.jpeg', N'Antes da adequação, o peneirador suspenso apresentava instabilidade operacional e altura inadequada em relação ao piso, dificultando o acesso seguro para operação, limpeza e manutenção. A ausência de pés de apoio comprometia a ergonomia dos trabalhadores, exigindo posturas inadequadas, maior esforço físico e aumentando os riscos de desconforto muscular e acidentes durante as atividades.', N'01 - Imagens/02 - Depois/11627.jpeg', N'Após a instalação dos pés de sustentação, o equipamento passou a apresentar melhor estabilidade estrutural, alinhamento adequado e elevação compatível com as necessidades operacionais. A adequação ergonômica proporcionou melhores condições de trabalho, favorecendo postura mais correta dos operadores, redução do esforço físico, maior segurança durante o uso e facilidade no acesso para inspeção e higienização. Além disso, a melhoria contribui para maior eficiência operacional e conformidade com princípios ergonômicos e de segurança no ambiente de trabalho.', NULL, N'Sim, com a instalação dos pés de sustentação corrigiu as deficiências identificadas no equipamento, proporcionando maior estabilidade estrutural, alinhamento adequado e altura compatível com a operação.', N'Pequenas adequações estruturais podem proporcionar grandes benefícios em ergonomia, segurança e desempenho operacional.', 0, NULL, NULL, '2026-08-06T00:00:00.000', '2026-08-07T13:15:58.000', N'516619', NULL, NULL);
INSERT INTO #PVC VALUES (11628, N'487516', N'487516', N'Formulário padrão tratamento notas YE', 1, N'Others/Outros', N'Abertura e tratamento de notas YE de análise de falha sem um padrão definido.', N'Criar um formulário padrão para levantamento de informações para tratamento de falhas.', N'10008', N'01 - Imagens/01 - Antes/11628.jpeg', N'A inexistência de um padrão formal para análise de falhas gerava deficiências significativas no processo investigativo, comprometendo a qualidade e a confiabilidade dos resultados. Sem uma metodologia padronizada, as informações coletadas tendem a variar de acordo com o analista responsável, podendo resultar em registros incompletos sobre o equipamento, condições operacionais, histórico de manutenção e evidências da falha. Essa falta de uniformidade dificultava a comparação entre ocorrências semelhantes, reduzindo a rastreabilidade das informações e aumenta o risco de conclusões baseadas em dados insuficientes.', N'01 - Imagens/02 - Depois/11628.jpeg', N'A análise de falhas é um processo sistemático que tem como objetivo identificar a causa raiz de uma ocorrência, utilizando informações do equipamento, histórico de manutenção e condições operacionais. Inicialmente são levantados dados como conjunto, equipamento, fornecedor, máquina de aplicação, horímetro e descrição do ocorrido, além dos efeitos observados durante a falha. Essas informações permitem caracterizar o evento e estabelecer a base para a investigação técnica.
INSERT INTO #PVC VALUES (11629, N'510839', N'510839', N'Robô IK11: Eliminação da Intervenção Manual em Horímetros Repetidos', 1, N'Others/Outros', N'Após a implantação do robô de lançamento de horímetros na transação IK11 do SAP, foi identificado um desvio operacional quando o sistema encontrava leituras iguais às registradas anteriormente, situação comum em equipamentos parados. Nesses casos, o SAP retornava a mensagem "A posição do contador é a mesma do documento anterior", impedindo a continuidade automática do processo e exigindo intervenção manual para tratamento da ocorrência. Essa condição comprometia a automação completa da atividade e gerava retrabalho para os usuários.', N'Aprimorar o robô de lançamento de horímetros para tratar automaticamente ocorrências de horímetros repetidos', N'10234', N'01 - Imagens/01 - Antes/11629.jpeg', N'Quando o robô identificava uma leitura de horímetro com o mesmo valor do último registro existente no SAP — situação comum em equipamentos parados — o sistema emitia a mensagem "A posição do contador é a mesma do documento anterior" e interrompia o processamento automático.
INSERT INTO #PVC VALUES (11630, N'81063720', N'81063720', N'GESTÃO DE ANÁLISES', 1, N'Open Pit/Poço aberto', N'NÃO HÁ UMA GESTÃO DE ANÁLISE DE OMS, O QUE PODE ACABAR ACARRETANDO EM CONFUSÃO DURANTE AS ANÁLISES PODENDO ANÁLISAR A MESMA OM DUAS VEZES.', N'OTIMIZAÇÃO DE TEMPO', N'10024', N'01 - Imagens/01 - Antes/11630.jpeg', N'UMA PLANILHA DE OMS É GERADA POR SEMANA PELO PROGRAMADOR PARA A EQUIPE DE PREDITIVA REALIZAR, PORÉM NÃO HÁ UMA GESTÃO DE DE OMS TRATADAS, ONDE OS TÉCNICOS PODEM SE CONFUNDIR E ACABAR ANALISANDO A MESMA OM.', N'01 - Imagens/02 - Depois/11630.jpeg', N'A SOLUÇÃO PARA SANAR O PROBLEMA FOI ADICIONAR UMA COLUNA PARA CADA TÉCNICO SINALIZAR QUE A OM JÁ FOI TRATADA POR ELE, ASSIM OTIMIZANDO O TEMPO DE TRABALHO E EVITANDO O RETRABALHO DA EQUIPE.', NULL, N'SIM! HOJE A PLANILHA É COMPARTILHADA COM OS MEMBROS DA EQUIPE ONDE TODOS FICAM CIENTES DAS OMS QUE JÁ FORAM TRATADAS, ASSIM OTIMIZANDO O TEMPO DE TRABALHO.', N'TER GESTÃO DAS OM É IMPORTANTE', 0, NULL, NULL, '2026-08-06T00:00:00.000', '2026-08-07T16:43:45.000', N'81063720', NULL, NULL);
INSERT INTO #PVC VALUES (11631, N'87000071', N'87000089', N'Digitalización de toma de información geologica ', 1, N'Projects/Projetos', N'Se realiza la toma de datos geológicos de las muestras de sondaje en formularios de papel que posteriormente se pasan a una planilla digital, haciendo doble trabajo por parte de los asistentes ', N'Reducir el tiempo de trabajo en toma de datos geologicos ', N'#N/A', N'01 - Imagens/01 - Antes/11631.jpeg', N'Antes el proceso de almacenamiento de datos geológicos de las muestras era poco eficiente, propenso a errores humanos y lento, donde se generaban planillas en papel para luego ser digitalizadas. ', N'01 - Imagens/02 - Depois/11631.jpeg', N'Se genera aplicación digital para trabajar en tablets, donde los datos son almacenados solo una vez y pueden ser consultados en tiempo real, se evita duplicar trabajo y se ahorra tiempo. 
INSERT INTO #PVC VALUES (11632, N'87000071', N'87000088', N'Síntesis y orden de cambio de turno de asistentes ', 1, N'Projects/Projetos', N'Se realizan informes de cambios de turnos muy extensos y sin lineamientos. ', N'Orden y eficiencia en cambios de turnos', N'#N/A', N'01 - Imagens/01 - Antes/11632.jpeg', N'Informe de cambio de turno de los supervisores detallado, día a día, lo que genera un exceso de información y donde se pierden las cosas de importancia. ', N'01 - Imagens/02 - Depois/11632.jpeg', N'Nueva planilla donde se sintetiza lo más relevante de los trabajos, sobre esta misma se basa la comunicación durante el cambio de turno y almacenamiento de la información en Teams.', NULL, N'Si, se logra estandarizar el uso de un solo formato para el cambio de turno donde será más fácil acceder a la información y se reportarán los hechos relevantes del turno.', N'Estandarización de reportes', 0, NULL, NULL, '2026-07-21T00:00:00.000', '2026-08-07T18:36:36.000', N'87000071', NULL, NULL);
INSERT INTO #PVC VALUES (11633, N'87000071', N'87000089', N'Iniciativas deportivas', 2, N'Projects/Projetos', N'Se identifica que no existen iniciativas para realizar actividad fisica en proyecto después del horario laboral. ', N'Promover actividad fisica en proyecto', N'#N/A', N'01 - Imagens/01 - Antes/11633.jpeg', N'No se cuenta con equipamiento deportivos ni se organizan instancias deportivas que motive a salir del sedentarismo y mejorar la salud fisica de los trabajadores.', N'01 - Imagens/02 - Depois/11633.jpeg', N'Se gestiona la compra de elementos deportivos simples para realizar ejercicios posterior al horario laboral y se organiza un pequeño torneo de Ping-Pong, ya que se cuenta con mesa, pelotas y paletas. ', NULL, N'Si, los trabajadores muestran entusiasmo por la compra de los elementos para realizar ejercicio y el campeonato de ping pong que  fomenta la competencia sana, el vínculo y confianza entre trabajadores 
INSERT INTO #PVC VALUES (11634, N'87000071', N'87000089', N'Mejora en muestrera Proyecto Bloque El Loa', 1, N'Projects/Projetos', N'Solo se tiene malla protectora del sol pero se identifica vientos recurrentes en la zona', N'Protección del viento', N'#N/A', N'01 - Imagens/01 - Antes/11634.jpeg', N'Se tiene la muestrera tapada con malla en el techo para protección de la radiación UV, pero se identifica que la región presenta ráfagas de viento considerables en estas fechas. ', N'01 - Imagens/02 - Depois/11634.jpeg', N'Se habilitó una malla que protege del viento y especialmente de las partículas en suspensión, que generan incomodidad, irritación ocular, entre otras. ', NULL, N'Se confeccionó la muestrera, sin tomar en cuenta la posible condición de viento de la región. Ahora el personal se resguarda correctamente y puede desarrollar su trabajo con normalidad y seguros', N'Evaluar climatológicamente las áreas de trabajo ', 0, NULL, N'A better understanding of our targets by the business ', '2026-07-01T00:00:00.000', '2026-08-08T12:14:56.000', N'87000071', NULL, NULL);
INSERT INTO #PVC VALUES (11635, N'81035621', N'81035621', N'CAVALETE PARA TOTE BIN DE SABÃO', 3, N'Others/Outros', N'Atualmente o Tote Bin de sabão é utilizado sem um suporte adequado, dificultando o acesso ao ponto de drenagem e às operações de manuseio.', N'Desenvolver e instalar um cavalete para suporte do Tote Bin de sabão, garantindo maior estabilidade, ergonomia e segurança durante o manuseio, abastecimento e utilização do produto.', N'10324', N'01 - Imagens/01 - Antes/11635.jpeg', N'Atualmente o Tote Bin de sabão é utilizado sem um suporte adequado, dificultando o acesso ao ponto de drenagem e às operações de manuseio.', N'01 - Imagens/02 - Depois/11635.jpeg', N'Foi confeccionado e instalado um cavalete metálico para suporte do Tote Bin de sabão, elevando o recipiente a uma altura adequada para operação e drenagem do produto.', NULL, N'SIM, o problema foi resolvido. A instalação do cavalete proporcionou apoio adequado ao Tote Bin de sabão, eliminando a condição insegura identificada anteriormente.', N'Soluções simples e de baixo custo podem gerar ganhos significativos em segurança, ergonomia e organização.', 0, NULL, N'Otimização de HH estimada em 4h/mês.', '2026-08-01T00:00:00.000', '2026-08-09T04:40:50.000', N'81035621', NULL, NULL);
INSERT INTO #PVC VALUES (11636, N'81035621', N'81046347', N'SUPORTE PARA ENROLAR CABOS', 3, N'Others/Outros', N'Atualmente os cabos são armazenados diretamente no piso, ficando expostos a danos mecânicos, sujeira e emaranhamento.', N'Desenvolver e instalar um suporte para armazenamento e enrolamento de cabos, garantindo melhor organização da área, conservação dos cabos e eliminação de riscos de tropeços e quedas.', N'10324', N'01 - Imagens/01 - Antes/11636.jpeg', N'Os cabos eram armazenados diretamente sobre o piso, ficando desorganizados e sujeitos a emaranhamento, desgaste prematuro e contaminação por sujeira.', N'01 - Imagens/02 - Depois/11636.jpeg', N'Foi desenvolvido e instalado um suporte para enrolamento e armazenamento de cabos.', NULL, N'A instalação do suporte permitiu o armazenamento adequado dos cabos, eliminando a necessidade de mantê-los no piso. A melhoria proporcionou mais segurança, organização e praticidade no manuseio, atendendo aos objetivos estabelecidos pelo projeto.', N'A organização adequada de materiais e ferramentas contribui diretamente para a segurança, produtividade e conservação dos equipamentos.', 0, NULL, N'Using locally sourced seals, saved money on the initial replacement cost as well as money associated with replacing failed electrical components and ultimately the reliability of the crane and its downtime due to related failures.', '2026-08-02T00:00:00.000', '2026-08-09T04:51:15.000', N'81035621', NULL, NULL);
INSERT INTO #PVC VALUES (11637, N'81042207', N'81054975', N'Garantir a identificação clara e padronizada dos locais de repouso das tampas de vagões  (Pouso 1 e Pouso 2), eliminando ambiguidades e facilitando a gestão operacional da área  de descarga de vagões de cobre.', 3, N'Others/Outros', N'Durante inspeção realizada no galpão de descarga de vagões 
INSERT INTO #PVC VALUES (11638, N'81006946', N'81006946', N'SUPORTE DE CARREGADOR DE BATERIAS', 3, N'Others/Outros', N'NÃO TINHAMOS UM LOCAL ADEQUADO PARA POR O CARREGADOR DE BATERIAS', N'CRIAR UM LOCAL FIXO PARA O CARREGADOR', N'10346', N'01 - Imagens/01 - Antes/11638.jpeg', N'A ausência de um local fixo e definido para armazenar o carregador de baterias, lixadeiras e furadeira gera desorganização no ambiente de trabalho, dificultando a localização e o acesso aos equipamentos e ferramentas. Essa condição também pode aumentar o risco de extravios', N'01 - Imagens/02 - Depois/11638.jpeg', N'Foi desenvolvido e instalado um suporte específico para o carregador de baterias, estabelecendo um local fixo, identificado e organizado para sua armazenagem.', NULL, N'SIM! SE MANTERMOS O LOCAL ORGANIZADO', N'A PADRONIZAÇÃO E O MELHOR CAMINHO PARA UM LOCAL DE TRABOLHO SEGURO E ORGANIZADO', 0, NULL, N'Cost avoided would be associated with replacing the camera and components as they are currently no longer working and would need to be replaced on each crane if operations wanted to start using this system again. As well the potential for dropped objects has now been removed.', '2026-08-08T00:00:00.000', '2026-08-09T20:45:06.000', N'81006946', NULL, NULL);
INSERT INTO #PVC VALUES (11639, N'81024026', N'81024026', N'confecção degrau de segurança Pz 14', NULL, N'Projects/Projetos', N'Em alguns poligonos com patolamento equipamento o acesso equipamento fica arriscado podendo causar incidente', N'Melhor segurança ao subir equipamento', N'10137', N'01 - Imagens/01 - Antes/11639.jpeg', N'fizemos a melhoria na escada de acesso para adcionar mais um degrau', N'01 - Imagens/02 - Depois/11639.jpeg', N'Depois da melhoria tivemos melhor acesso ao equipamento tendo mais segurança nas atividades', NULL, N'com a resolução do problema melhoramos a atividade da operação e manutenção tendo mais segurança no acesso', N'segurança nas atividades', 0, NULL, N'This change resulted in an instant relief of these common and nuisance alarms that would knock the crane down for various lengths of time. Depending on where the crane was located, a ladder, AWP or scaffold would sometimes be required for a simple alignement repair.', '2026-08-04T00:00:00.000', '2026-08-09T22:45:18.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11640, N'81024026', N'81024026', N'Reforma de cerquites', NULL, N'Projects/Projetos', N'estavamos com muitos cerquites danificados gerando custo e desgaste', N'melhorar custo e sgurança', N'10137', N'01 - Imagens/01 - Antes/11640.jpeg', N'Muitos cerquites danificados causando excesso sucata e custo excessivo', N'01 - Imagens/02 - Depois/11640.jpeg', N'Cerquites recuperados melhorando ambiente de trabalho e redução de custo', NULL, N'Com esse reparo conseguimos reduzi despesa e melhorar eficiencia', N'podemos melhorar e evoluir diminuindo custo', 4, 1, N'Padronização de registro de dados e centralização do histórico para rastreabilidade.', '2026-08-02T00:00:00.000', '2026-08-09T22:55:35.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11641, N'81024026', N'81024026', N'Confeccionado suporte para extintor de incendio oxicorte', NULL, N'Projects/Projetos', N'Foi verificado que oxicorte não tinha extintor de incendio', N'Dar mais segurança atividade com oxicorte', N'10137', N'01 - Imagens/01 - Antes/11641.jpeg', N'Foi verificado que carinho oxicorte não tinha extintor incendio', N'01 - Imagens/02 - Depois/11641.jpeg', N'foi feito suporte para extintor e providenciado extintor trazendo mais segurança as atividades', NULL, N'Foi verificado que o carinho de oxicorte tem como ser mais seguros', N'temos ter sempre visão de segurança', 0, NULL, N'Sistema de lubrificação com graxa limpa, para que não haja nenhuma impureza que possa danificar componentes do equipamento.', '2026-08-03T00:00:00.000', '2026-08-09T23:13:24.000', N'81024026', NULL, NULL);
INSERT INTO #PVC VALUES (11642, N'1014096', N'1014096', N'Failed SX Flow Meter', 1, N'No Replication/Sem replicação', N'Process upsets increased HCL concentration in IMP SX. This was causing premature failure of 326-FIT-21242.', N'Prevent premature flow meter failure', N'10006', N'01 - Imagens/01 - Antes/11642.jpeg', N'HCL upsets were destroying the graphite gasket inside the flow meter. 2 failures in short succession occurred. Once the gasket failed, the process fluid destroyed the flow meter.', N'01 - Imagens/02 - Depois/11642.jpeg', N'Worked with vendor to find a much more suitable gasket for the regular service and for upsets. Updated the material master list and procured replacements.', NULL, N'YES - More compatible flow meter + gasket was installed.', N'Material Compatibility for SX Imp upsets.', 0, NULL, N'Ganhos Obtidos:
INSERT INTO #PVC VALUES (11643, N'1014096', N'1014096', N'Failed Acid Wash Pump', 1, N'No Replication/Sem replicação', N'Acid wash pump and motor 226-352-PNE-001 were upgraded under a previous MOC and it''s BOM wasn''t updated. Pump failed and maintenance had no spare parts.', N'Ensure Proper Sparing for Acid Wash Pump', N'10006', N'01 - Imagens/01 - Antes/11643.jpeg', N'Unable to locate spare pump after MOC completed (docs & SAP not updated), maintenance was about to order a new pump and motor.', N'01 - Imagens/02 - Depois/11643.jpeg', N'Found the MOC, located the correct pump information, found a surplus pump in inventory. Avoided purchase new $24k pump. Repair was planned, no wait for parts, no downtime.', NULL, N'BOM was updated to account for the MOC, existing surplus spare was utilized, no incremental cost to the business and no downtime.', N'Check inventory before buying new!', 24000, 3, N'Que o equipamento diminua os alarmes de falha por pressão do sistema/tanque hidráulico.', '2026-06-30T00:00:00.000', '2026-08-10T07:21:15.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11644, N'1014096', N'1014096', N'Repurposing Forgotten Lights', NULL, N'No Replication/Sem replicação', N'While cleaning up warehouse inventory, 3 Milwaukee work lights from 2014 were found. Unopened, unused and forgotten about. Find a use for them.', N'Find use for brand new, unused, forgotten about lights ', N'10006', N'01 - Imagens/01 - Antes/11644.jpeg', N'While cleaning up warehouse inventory, 3 Milwaukee work lights from 2014 were found. Unopened, unused and forgotten about. Find a use for them.', N'01 - Imagens/02 - Depois/11644.jpeg', N'Tristan H needed new lights for his maintenance team. Lights were re-purposed, taken and used. Avoided the need to purchase a set of new lights and avoided sending these lights for CMD.', NULL, N'Were able to utilize the lights rather than sending them to CMD. Avoided buying new lights. Used what was already on hand.', N'While cleaning up forgotten messes, you can find something valuable.', 1000, 3, N'Melhorou a segurança pois agora a empilhadeira tem o seu  próprio lugar para encaixar e executar a atividade de locomoção do gerador. ', '2026-06-17T00:00:00.000', '2026-08-10T07:35:48.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11645, N'1014096', N'1014096', N'Spare Gearbox Fitup Concerns', NULL, N'No Replication/Sem replicação', N'Spare gearbox for agitator 346-AGP-050 looked different from the existing in the field. The stoked couplings were also incorrect for the agitator.', N'Spare gearbox looked different from existing, could it be used?', N'10006', N'01 - Imagens/01 - Antes/11645.jpeg', N'Job stopped, mismatch between new and existing gearbox and spare couplings wrong.', N'01 - Imagens/02 - Depois/11645.jpeg', N'Clarified the spare was correct and design upgrade removed adaptor plate. Correct couplings sourced. BOM updated. Work rescheduled.', NULL, N'Avoided tossing out the spare gearbox and purchasing a new. Only had to purchase cheap new couplings (500$). Couplings updated on the BOM.', N'Parts that look slightly different can still be equivalent.', 10000, 3, N'alcançado com a eliminação do risco.', '2026-08-05T00:00:00.000', '2026-08-10T07:54:23.000', N'1014096', NULL, NULL);
INSERT INTO #PVC VALUES (11646, N'81043246', N'81046443', N'Controle de Rádios Operacionais', 1, N'No Replication/Sem replicação', N'O controle de rádios era realizado de forma inadequada, gerando dificuldades na gestão dos equipamentos, falta de informações sobre sua disponibilidade e falhas na comunicação entre as equipes. Como consequência, ocorriam atrasos nas atividades operacionais e impactos na produtividade.', N'Realizar o controle de rádios em campo ', N'10054', N'01 - Imagens/01 - Antes/11646.jpeg', N'O controle de rádios era realizado sem padronização, dificultando a gestão e a localização dos equipamentos. A falta de acompanhamento das entregas e devoluções favorecia o desvio de rádios, gerava falhas na comunicação entre as equipes e resultava em atrasos nas atividades operacionais, impactando diretamente a produtividade e a eficiência da operação.', N'01 - Imagens/02 - Depois/11646.jpeg', N'Com a implantação de um controle padronizado dos rádios, passou a ser possível acompanhar a disponibilidade dos equipamentos em tempo real, garantindo maior rastreabilidade e organização. Como resultado, houve redução das falhas de comunicação, mais agilidade na execução das atividades e aumento da eficiência operacional.', NULL, N'A meta foi alcançada com a implementação de um controle eficiente dos rádios, proporcionando maior rastreabilidade, redução de desvios, melhor comunicação entre as equipes e diminuição dos atrasos operacionais, aumentando a produtividade e a eficiência da operação.', N'A implementação do controle de rádios demonstrou a importância de manter um processo padronizado para a gestão dos equipamentos de comunicação.', 0, NULL, N'Este Kaizen tem como objetivo melhorar o processo de abastecimento do líquido de arrefecimento (ELC) da ilha de lubrificação, garantindo a integridade do fluido e eliminando riscos de contaminação durante a operação.hidráulicas.', '2026-08-03T00:00:00.000', '2026-08-10T10:21:30.000', N'81043246', NULL, NULL);
INSERT INTO #PVC VALUES (11647, N'1008789', N'1008789', N'Stock Availability Targets ', 1, N'Others/Outros', N'There was no visible targets on the Power BI page for Stock Availability, therefor there was no indicator of "what good looks like"', N'Visual display for availability targets ', N'0', N'01 - Imagens/01 - Antes/11647.jpeg', N'There was no visible targets on the Power BI page for Stock Availability, therefor there was no indicator of "what good looks like"', N'01 - Imagens/02 - Depois/11647.jpeg', N'Visual indicator added so everyone can be aware of what the targets are and if we are meeting them. ', NULL, N'Yes, a visual indicator added so everyone can be aware of what the targets are and if we are meeting them. ', N'Repeatable ', 0, NULL, N'Sem risco de queda', '2026-08-09T00:00:00.000', '2026-08-10T11:21:23.000', N'1008789', NULL, NULL);
INSERT INTO #PVC VALUES (11648, N'81063756', N'396366', N'Automatização da atualização do BI de RAF e Ações Stratws', 1, N'Others/Outros', N'O BI precisava ser diariamente atualizado manualmente consumindo cerca de 4h/mês de HH para essa tarefa.', N'Eliminar o processo manual de atualização diária do BI de RAF e Ações Stratws', N'10015', N'01 - Imagens/01 - Antes/11648.jpeg', N'Para a atualização diária da base de dados do BI de Controle de RAF e Ações Stratws, os dados de RAF, MCS e Ações do Stratws precisavam ser manualmente baixados do sistema DIARIAMENTE, gerando arquivos Excel que precisam ser carregados também em pastas do SharePoint.
INSERT INTO #PVC VALUES (11649, N'81043460', N'81043460', N'Harvesting Crane Enclosures', 1, N'Refining/Refino', N'Harvesting crane panel door seals have failed letting contaminants enter the panels causing extensive corrosion issues and premature failure of electrical components.', N'Seal the panels for better air quality, less corrosion', N'0', N'01 - Imagens/01 - Antes/11649.jpeg', N'Door seals on 16 harvesting crane panels have failed. Bought previously from Kuenz directly, and where quite costly with a long lead time, leading to additional corrosion and more electrical components to prematurely fail.', N'01 - Imagens/02 - Depois/11649.jpeg', N'Sourced replacements locally at a fraction of the cost and picked them up and installed within 24 hours. Saving time, money and component failures.', NULL, N'Yes', N'Source materials locally', 5000, 3, N'Engates protegidos contra sujeira e contaminação.
INSERT INTO #PVC VALUES (11650, N'81063756', N'81063756', N'Disparo de emails com relatório D-1 das frotas da mina Salobo', 1, N'Others/Outros', N'As informações encontravam-se em diferentes dashboards, tornando o processo de análise mais lento.', N'Consolidar em um relatório D-1 dados de performance, manutenção e gatilhos de RAF e MCS para promover uma análise mais rápida e centralizada dos responsáveis', N'10015', N'01 - Imagens/01 - Antes/11650.jpeg', N'A visão D-1 geralmente é realizada de forma dinâmica no BI de Performance de Frotas alternando entre as frotas e datas; e paralelizando com o BI de RAF e MCS para gerenciamento dos gatilhos.', N'01 - Imagens/02 - Depois/11650.jpeg', N'Este relatório já consolida em um único documento PDF o cenário D-1 e acumulado mensal dos indicadores de performance das frotas, gatilhos de RAF e MCS e Resumo de Paradas de Manutenção.', NULL, N'Hoje o time de engenharia de confiabilidade recebe diariamente um PDF consolidando dados de performance, paradas de manutenção e gatilhos de RAF e MCS em visão D-1 e acumulado mensal.', N'Criação de fluxo integrado com Power BI para disparo de e-mail com corpo escrito em HTML e CSS.', 0, NULL, NULL, '2026-07-31T00:00:00.000', '2026-08-10T12:54:06.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (11651, N'81043460', N'81043460', N'Remove Thermal Camera Components (RTMS)', 2, N'Refining/Refino', N'RTMS components are no longer required on the harvesting cranes, There are PMS to replace components we will no longer need to replace, as well the camera and associated parts pose a safety risk as a potential dropped object.', N'Remove RTMS components', N'0', N'01 - Imagens/01 - Antes/11651.jpeg', N'RTMS components are no longer required by the operations team and both mechanical and electrical components need to be removed from the bridge. ', N'01 - Imagens/02 - Depois/11651.jpeg', N'All components removed, no more risk of potential dropped objects!', NULL, N'yes', N'Easier solutions, sometime more economical and safe.', 20000, 3, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVÉIS.', '2026-08-04T00:00:00.000', '2026-08-10T13:49:54.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (11652, N'81043460', N'81043460', N'Increase Reflector Pad Size', 1, N'Refining/Refino', N'Harvesting crane rails, banging, knocking and misalignment issues cause the lasers to come off their reflective pad faulting out the cranes. Depending on the cranes location this could result in 20 min to +6 hours downtime and production loss.', N'Increase reliabaility of crane, reduce downtime for nuissance issues.', N'0', N'01 - Imagens/01 - Antes/11652.jpeg', N'Surface area of reflective pad and reflector isn''t suitable anymore for cranes operation and causes alarms and faults while harvesting in bay 3 and bay 4.', N'01 - Imagens/02 - Depois/11652.jpeg', N'Increase reflector pad by 2X to compensate for the crane rail issues further down the tank house. This has eliminated the nuisance faults, alarm and downtime associated with Crane 3 lasers.', NULL, N'Yes', N'A simple fix is sufficient enough for us to minimize downtime, all completed with materials on hand.', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVÁVEIS.', '2026-08-10T00:00:00.000', '2026-08-10T13:59:45.000', N'81043460', NULL, NULL);
INSERT INTO #PVC VALUES (11653, N'81063756', N'81063756', N'Formulário para cadastro de ganhos efetivos com alteração em estratégia de manutenção', 1, N'No Replication/Sem replicação', N'Ausência de repositório centralizado de dados referentes à ganhos reais com alterações em estratégias de manutenção, dificultando o registro e rastreabilidade dos ganhos obtidos.', N'Padronizar registro e centralizar histórico em BI dos ganhos efetivos obtidos com alteração em estratégia de manutenção', N'10015', N'01 - Imagens/01 - Antes/11653.jpeg', N'Ausência de repositório centralizado de dados referentes à ganhos reais com alterações em estratégias de manutenção, dificultando o registro e rastreabilidade dos ganhos obtidos.', N'01 - Imagens/02 - Depois/11653.jpeg', N'O cadastramento foi padronizado com a criação do formulário em MS Forms que grava as respostas e evidência anexada em lista do SharePoint.
INSERT INTO #PVC VALUES (11654, N'81057561', N'81057561', N'Filtro de Linha de Graxa', 1, N'Open Pit/Poço aberto', N'Komatsu alegou que havia contaminantes na graxa do equipamento, em virtude da falta de proteção para o abastecimento por parte da lubrificação, sendo assim colocamos um filtro na linha para proteção no abastecimento.', N'Realizar uma melhoria com a instalação de um filtro na linha de abastecimento de graxa.', N'10015', N'01 - Imagens/01 - Antes/11654.jpeg', N'Havia um filtro padrão na linha de abastecimento, mas muito ineficiente, o que fez com que fosse permitido a entrada de impurezas durante o abastecimento da graxa, contaminando o sistema.', N'01 - Imagens/02 - Depois/11654.jpeg', N'Foi instalado um filtro mais robusto, como iniciativa de melhoria, para resguardar melhor o sistema de lubrificação quanto a contaminantes oriundos do ato do abastecimento de graxa.', NULL, N'SIM, agora com a melhoria há um filtro mais robusto, era solução que era ação do plano diretor, onde precisamos buscar uma solução eficaz.', N'Importância da boa lubrificação.', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVÉIS.', '2026-08-09T00:00:00.000', '2026-08-10T14:34:18.000', N'81057561', NULL, NULL);
INSERT INTO #PVC VALUES (11655, N'492669', N'492669', N'CONTROLE ENVIO DE CILINDROS, AMPOLAS E TANQUE PARA RECARGA', 1, N'Others/Outros', N'Inexistência de base contendo todas as solicitações para emissão NF .', N'BASE DE CONTROLE CONSOLIDADA', N'10234', N'01 - Imagens/01 - Antes/11655.jpeg', N'Não existia uma base de controle consolidada para o envio de cilindros, ampolas e tanques para recarga. As solicitações eram realizadas por meio da emissão de Nota Fiscal e as informações ficavam disponíveis apenas no SAP, dificultando consultas futuras e rastreabilidade. Para localizar uma NF específica era necessário realizar pesquisas por diferentes critérios no sistema, consumindo em média 30 minutos por consulta. Além disso, não era possível obter rapidamente informações gerenciais, como quantidade de envios realizados no mês, responsáveis pelas solicitações, aprovações e ativos atendidos.', N'01 - Imagens/02 - Depois/11655.jpeg', N'Foi criada uma base única para controle das solicitações de saída de tanques, cilindros e ampolas para recarga, consolidando informações como Nota Fiscal, Ordem de Manutenção, ativo atendido, data da emissão, aprovadores e fornecedor responsável. Com a centralização dos dados, o tempo de localização de uma NF foi reduzido de aproximadamente 30 minutos para 5 minutos, representando uma redução de 83% no tempo gasto para consulta das informações. A solução também possibilitou maior rastreabilidade, padronização dos registros e geração rápida de informações gerenciais sobre o processo.', NULL, N'Tivemos muitos ganhos com o processo, o principal foi a centralização das demandas com todas as solicitações em banco de dados.', N'Agilidade nas informações', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVÉIS.', '2026-08-03T00:00:00.000', '2026-08-10T14:36:13.000', N'492669', NULL, NULL);
INSERT INTO #PVC VALUES (11656, N'81057561', N'81057561', N'Melhoria Regulador de Pressão Tanque Hidráulico', 1, N'Open Pit/Poço aberto', N'Havia uma repetição de falhas, onde era decorrente de alarmes de pressão do tanque hidráulico do equipamento, gerando impacto no MTBF principalmente.', N'Melhorar a regulagem de pressão  das linhas de alimentação do sistema  hidráulico', N'10015', N'01 - Imagens/01 - Antes/11656.jpeg', N'O regulador de pressão padrão apresentada alarmes, onde deveria haver falha de pressão no sistema hidráulico, porém, onde quando o equipamento parava não era identificada falha, entendemos então que o regulador não era confiavel.', N'01 - Imagens/02 - Depois/11656.jpeg', N'Foi instalado um modelo novo de regulador de pressão no equipamento, para melhorar a confiabilidade do sistema hidráulico como um todo.', NULL, N'SIM, agora com este modelo entendemos que o MTBF não será mais impactado pelo modo de falhas.', N'Importância de monitoramento da condição do equipamento.', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVÁVEIS.', '2026-08-09T00:00:00.000', '2026-08-10T15:09:37.000', N'81057561', NULL, NULL);
INSERT INTO #PVC VALUES (11657, N'92000525', N'485334', N'Suporte do gerador a Diesel', NULL, N'Others/Outros', N'Anteriormente o gerador era apoiado diretamente sobre o palete de madeira. Quando não havia palete, o equipamento era apoiado no chão, o que causava amassamento da base e danos estruturais.', N'Suporte para fazer o içamento com empilhadeira', N'10324', N'01 - Imagens/01 - Antes/11657.jpeg', N'O gerador era movimentado sobre palete, que frequentemente amassava ou quebrava pelo excesso de peso. Sem palete, o equipamento era arrastado direto no chão, sem apoio, causando dano estrutural e dificuldade na locomoção.', N'01 - Imagens/02 - Depois/11657.jpeg', N'Foi fabricado um suporte para o gerador. Agora é possível movimentá-lo com a empilhadeira de forma segura, eliminando o risco de dano e agilidade durante a movimentação.', NULL, N'Sim, pois agora temos local adequado para fazer o içamento que não vai gerar danos ao equipamento e será feito de forma segura.', N'Otimização e risco e melhoria no processo', 0, NULL, N'Melhorar a visibilidade das informações críticas do processo, eliminando alarmes obsoletos e reduzindo a poluição visual no supervisório, para proporcionar monitoramento mais eficiente e maior agilidade na tomada de decisão operacional.', '2026-08-07T00:00:00.000', '2026-08-10T15:18:02.000', N'92000525', NULL, NULL);
INSERT INTO #PVC VALUES (11658, N'471876', N'471876', N'DRENO DE LIMPEZA', 1, N'Others/Outros', N'Na sala Open space não havia dreno para agua de limpeza', N'ELIMINAR RISCO ', N'10032', N'01 - Imagens/01 - Antes/11658.jpeg', N'Na sala Open space, não havia dreno para limpeza, então a agua era jogada pela porta de emergência(ponto de atenção) com a nova reforma, a fiação elétrica em calhas passa abaixo do piso da porta de emergência, vindo a cair agua na fiação, além de abrir toda hora de limpeza a porta, nisso o risco de ficar escorregadio devido o sabão.', N'01 - Imagens/02 - Depois/11658.jpeg', N'Foi feito um dreno na sala, onde a agua de limpeza segue outro caminho, assim evitando esse trajeto com esses dois riscos, com também facilitou para nossos colaboradores da limpeza .', NULL, N'risco eliminado', N'que observando a gente resolve situações', 0, NULL, N'.', '2026-08-06T00:00:00.000', '2026-08-10T15:28:19.000', N'471876', NULL, NULL);
INSERT INTO #PVC VALUES (11659, N'81056513', N'552777', N'Melhoria no Sistema de Abastecimento do Líquido de Arrefecimento da Ilha de Lubrificação', 1, N'Others/Outros', N'Antes da implementação da melhoria, o abastecimento era realizado por apenas uma bomba pneumática da Graco, utilizada tanto para o líquido de arrefecimento (ELC) quanto para os óleos GEAR 150 e GEAR 220.
INSERT INTO #PVC VALUES (11660, N'81022747', N'81006480', N'SUPORTE  DO LAVA OLHOS', 3, N'Others/Outros', N'Antes não havia um suporte de apoio', N'Segurança', N'10144', N'01 - Imagens/01 - Antes/11660.jpeg', N'Não havia nenhum suporte de sustentação como base de apoio', N'01 - Imagens/02 - Depois/11660.jpeg', N'Foi confeccionado um suporte para melhor sustentação do material', NULL, N'Melhorando a segurança de quem vai ultilizar.', N'Organização', 0, NULL, N'ELIMINAÇÃO DO RISCO', '2026-08-09T00:00:00.000', '2026-08-10T17:03:55.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11661, N'81020607', N'723908', N' MELHORIA NO SISTEMA DE TRANSFERÊNCIA DE ÓLEO HIDRÁULICO', 1, N'Others/Outros', N'O processo de transferência dos óleos era mais demorado e exigia maior esforço operacional, aumentando o tempo gasto para realizar o abastecimento.', N'Melhoria continua', N'10139', N'01 - Imagens/01 - Antes/11661.jpeg', N'As bombas utilizadas para transferência dos óleos hidráulicos não possuíam a conexão adequada para facilitar a transferência dos óleos dos tambores para os Totibins.
INSERT INTO #PVC VALUES (11662, N'81020607', N'81016957', N'Implantação de tampas protetoras e identificação dos engates rápidos de abastecimento de graxa.', 1, N'Others/Outros', N'Os engates rápidos estavam expostos à poeira, la ma e outros contaminantes.
INSERT INTO #PVC VALUES (11663, N'503436', N'503436', N'MONITORAMENTO DO MUNHÃO DO CILINDRO DE DIREÇÃO', 1, N'Others/Outros', N'Os munhões dos caminhões fora-de-estrada CAT 797F referente ponto de articulação e suporte entre o cilindro de elevação que funciona como um eixo de articulação para os cilindros. No entanto Durante inspeções preditivas e preventivas, é comum encontrar: Falha de lubrificação, Aumento de temperatura por atrito.', N'ACOMPANHAR  POSSIVEIS DESGASTES ANTECIPADOS ', N'10024', N'01 - Imagens/01 - Antes/11663.jpeg', N'Ao longo do ciclo operacional do equipamento, a deficiência na lubrificação do munhão, associada à baixa frequência de inspeções sensitivas e preventivas, pode acelerar o processo de degradação do componente. Como consequência, é comum identificar condições como:
INSERT INTO #PVC VALUES (11664, N'81034776', N'81034776', N'Identificação Motores uh SLB III', 1, N'Others/Outros', N'Falta de identificação adequada podendo gerar lentidão para resolução de falhas.', N'Tornar atuação mas rápida e segura', N'10290', N'01 - Imagens/01 - Antes/11664.jpeg', N'Falta de identificação adequada no MO-2305SA-01-ST001-M1 podendo gerar lentidão para resolução de falhas.', N'01 - Imagens/02 - Depois/11664.jpeg', N'Com melhoria realizada no MO-2305SA-01-ST001-M1 passamos a ter uma condição de trabalho mas adequada, tornando as atuações mas rápidas e seguras, criando um ambiente mas confortável para a execução de atividades.', NULL, N'SIM. Com melhoria realizada no MO-2305SA-01-ST001-M1 passamos a ter uma condição de trabalho mas adequada, tornando as atuações mas rápidas e seguras, criando um ambiente mas confortável para a execução de atividades.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ UMA GRANDE DIFERENÇA NA SEGURANÇA E PRODUTIVIDADE.', 0, NULL, NULL, '2026-08-10T00:00:00.000', '2026-08-11T04:03:34.000', N'81034776', NULL, NULL);
INSERT INTO #PVC VALUES (11665, N'81034776', N'81034776', N'IDENTIFICAÇÃO MOTORES UH SLB III.', 1, N'Others/Outros', N'FALTA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'10290', N'01 - Imagens/01 - Antes/11665.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST001-M2 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/11665.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M2 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORÁVEL PARA A EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM. COM MELHORIA REALIZADA NO MO-2305SA-01-ST001-M2 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA, TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS, CRIANDO UM AMBIENTE MAS CONFORTÁVEL PARA EXECUÇÃO DE ATIVIDADES.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, N'cleaning / inspection not forgotten ', '2026-08-10T00:00:00.000', '2026-08-11T04:30:37.000', N'81034776', NULL, NULL);
