INSERT INTO #PVC VALUES (11802, N'608046', N'608046', N'Paint/Oil Storage Room Organization', 3, N'Others/Outros', N'Paint and Oil supply storage room area was out of order, materials and supply''s placed throughout the room and not stored properly.', N'Housekeeping', N'10193', N'01 - Imagens/01 - Antes/11802.jpeg', N'Pails of oil not placed in proper locations-on floor, paint supplies and debris left behind cans not sorted as per colour/identification, room covered in cobwebs-outdated materials require discard to environmental depot.', N'01 - Imagens/02 - Depois/11802.jpeg', N'All materials were removed; room was cleaned of spiders/webs, products were sorted accordingly, labelled for ease of identification, organized for inventory control-disposed of spent hazardous materials tagged to environmental depot. ', NULL, N'Yes-all flammable items are stored in paint/storage areas as required, maintain-organization of products, materials for ease of availability.', N'Housekeeping-Organization-Inventory', 0, NULL, N'✅ Redução da sobrecarga física dos operadores.
INSERT INTO #PVC VALUES (11803, N'81061536', N'81058947', N'SUPORTE PARA ALOJAR CIINDRO DO RIPPER TRATOR D10', 1, N'Projects/Projetos', N'NÃO EXISTIA SUPORTE PARA ALOJAR O CILINDRO DO RIPPER', N'ALOJAR CIINDRO DO RIPPER TRATOR D10', N'10139', N'01 - Imagens/01 - Antes/11803.jpeg', N'NÃO EXISTIA SUPORTE PARA ALOJAR O CILINDRO DO RIPPER', N'01 - Imagens/02 - Depois/11803.jpeg', N'FOI FABRICADO SUPORTE PARA ALOJAR O CILINDRO DO RIPPER DO TRATOR D10', NULL, N'SIM, FOI RESOLVIDO. ', N'SEGURANÇA - OS CILINDROS PODERIAM CAIR E MACUCAR ALGUM COLABORADOR. ', 14, 1, N'é possível redução entre 30 min e 01 hora deparada por evitar a logística até o armazém', '2026-08-18T00:00:00.000', '2026-08-19T16:41:21.000', N'81061536', NULL, NULL);
INSERT INTO #PVC VALUES (11804, N'81034922', N'81048568', N'Melhoria no posicionamento da buzina', 1, N'Others/Outros', N'Para substituir a buzina do caminhão KOMATSU 785HD era necessário remover a grade frontal do radiador expondo o empregado a risco de prensamento.', N'Eliminar o risco de troca da buzina ', N'0', N'01 - Imagens/01 - Antes/11804.jpeg', N'Para substituir a buzina do caminhão KOMATSU 785HD era necessário remover a grade frontal do radiador expondo o empregado a risco de prensamento de membros.', N'01 - Imagens/02 - Depois/11804.jpeg', N'Foi modificado a posição de instalação da buzina, cabeamento para eliminar o risco de prensamento de menbros ao remover a grade frontal do radiador.', NULL, N'Foi resolvido porque com a nova posição da buzina foi eliminado o risco de prensamento de membros.', N'É sempre importante buscar a eliminação de situações de risco nas atividades de manutenção.', 0, NULL, N'redução significativa do tempo de parrada do ativo por falta de lubrificante', '2026-08-18T00:00:00.000', '2026-08-19T16:54:31.000', N'81034922', NULL, NULL);
INSERT INTO #PVC VALUES (11805, N'81061536', N'81058947', N'SUPORTE PARA ALOJAR CILINDRO DE DIREÇÃO 24M', 1, N'Projects/Projetos', N'OS CILINDROS ERAM ARMAZENADOS EM CIMA DE UM PALET, SEM SEGURANÇA ', N'ALOJAR CILINDRO DE DIREÇÃO 24M', N'10139', N'01 - Imagens/01 - Antes/11805.jpeg', N'OS CILINDROS ERAM ARMAZENADOS EM CIMA DE UM PALET, SEM SEGURANÇA ', N'01 - Imagens/02 - Depois/11805.jpeg', N'REALIZADO A CONFECÇÃO DO DISPOSITIVO PARA ARMAZENAR OS CILINDROS DE DIREÇÃO DO 24M', NULL, N'SIM, FOI RESOLVIDO. ', N'SEGURANÇA - COM A CONFECÇÃO DO DISPOSITIVO TEMOS MAIOR SEGURANÇA AO TRANSITAR NA ÁREA.', 8, 1, N'Conclusão
INSERT INTO #PVC VALUES (11806, N'81061536', N'81058947', N'CONFECCIONADO SUPORTE PARA ALOJAR BULLDOZER DO TU', 1, N'Projects/Projetos', N'OS BULLDOZER FICAVAM NO CHÃO SEM LUGAR PARA ARMAZENAR', N' SUPORTE PARA ALOJAR BULLDOZER DO TU', N'10139', N'01 - Imagens/01 - Antes/11806.jpeg', N'NÃO EXISTIA ANTES', N'01 - Imagens/02 - Depois/11806.jpeg', N'CONFECCIONADO SUPORTE PARA ALOJAR BULLDOZER DO TU QUE FICAVA EXPOSTO ', NULL, N'SIM, FOI RESOLVIDO', N'SEGURANÇA E REDUÇÃO DE CUSTO PARA A ÁREA POIS AGORA OS BULLDOZER ESTÃO BEM ARMAZENADOS', 6, 1, N'Redução de tempo de análise de dados de indicadores em 98,3%.', '2026-08-18T00:00:00.000', '2026-08-19T17:17:24.000', N'81061536', NULL, NULL);
INSERT INTO #PVC VALUES (11807, N'81058052', N'81058052', N'Adaptação de válvula monobloco e conversão de acionamento em equipamento de comboio diesel CV-61', 1, N'Others/Outros', N'Devido à avaria no bloco de comando monobloco com acionamento pneumático do CV 61), o sistema apresentou aumento abrupto da temperatura do óleo hidráulico. Isso resultou em cavitação severa e avaria na bombas da tomada de força (PTO).', N'Eliminar o superaquecimento do óleo hidráulico (limite de 130°C), sanando a cavitação e prevenindo a quebra das bombas da tomada de força (PTO), garantindo a confiabilidade operacional do sistema.', N'10346', N'01 - Imagens/01 - Antes/11807.jpeg', N'O equipamento CV-61apresentou um severo superaquecimento do óleo hidráulico, alcançando temperaturas superiores a 130°C.
INSERT INTO #PVC VALUES (11808, N'1008695', N'1008695', N'Coach office KPI Monitoring ', 1, N'Others/Outros', N'No continuous monitoring of POL KPI''s ', N'Consistency ', N'0', N'01 - Imagens/01 - Antes/11808.jpeg', N'No screen to continuously Monitor POL KPI''s at a glance.  ', N'01 - Imagens/02 - Depois/11808.jpeg', N'TV monitor and computer added to coach office to display POL KPI''s and production information 24/7 at a glance. ', NULL, N'yes ', N'Constant visuals are better', 0, NULL, N'Maior eficiência na gestão das requisições SAP e melhor alinhamento entre os envolvidos no processo.', '2026-08-19T00:00:00.000', '2026-08-20T00:28:03.000', N'1008695', NULL, NULL);
INSERT INTO #PVC VALUES (11809, N'92000587', N'365544', N'TAMPA DE INSPEÇÃO DOS MOTORES DE LOCOMOÇÃO E MANGUEIRAS DOS TRUCKS', 2, N'Others/Outros', N'A tampa, único acesso aos motores de locomoção e mangueiras hidráulicas, pesava aproximadamente 80 kg e exigia duas pessoas para sua remoção, com tempo estimado de 30 a 40 minutos. O processo demandava esforço físico, auxílio de equipamentos e expunha os mantenedores à linha de fogo, aumentando o tempo e os riscos da manutenção.', N'Eliminação dos colaboradores na linha de fogo mediante o peso da estrutura, e por não ter condições de equipamentos auxiliar para na remoção da mesma', N'10144', N'01 - Imagens/01 - Antes/11809.jpeg', N'A tampa é o único acesso aos motores de locomoção e mangueiras hidráulicas,pesando aproximadamente 80 kg e exigia duas pessoas para sua remoção,com tempo estimado de 30 a 40 minutos.O processo demandava esforço físico,alem da exposição dos colaboradores na linha de fogo,aumentando o tempo e os riscos da manutenção.', N'01 - Imagens/02 - Depois/11809.jpeg', N'Foi instalada uma tampa articulada com dobradiças e maçaneta de segurança,eliminando a necessidade de remoção completa.
INSERT INTO #PVC VALUES (11810, N'81058741', N'81058741', N'Criação de um modelo de controle de ações e um painel em BI para gestão das ações entre Vale e Delers', 1, N'Others/Outros', N'Não existia uma visão estratégica consolidada das ações definidas nas reuniões de diretoria entre os Dealers e a Vale. ', N'Visualizar de forma mais ágil de integrada das ações das reuniões entre a diretoria Vale e Dealers', N'10015', N'01 - Imagens/01 - Antes/11810.jpeg', N'Não existia uma visão estratégica consolidada das ações definidas nas reuniões de diretoria entre os Dealers e a Vale. Os planos de ação ficavam registrados apenas nas apresentações utilizadas durante os encontros, sem uma base centralizada para controle, acompanhamento de prazos, responsáveis e status das entregas. Essa condição dificultava a gestão, o monitoramento e a cobrança das ações acordadas.', N'01 - Imagens/02 - Depois/11810.jpeg', N'Foi desenvolvida uma base de dados estruturada em Excel para centralizar todas as ações provenientes das reuniões com os Dealers, incorporando fórmulas, automações e padronização das informações. Complementarmente, foi implementado um dashboard em Power BI, proporcionando uma visão gerencial consolidada do status das ações, prazos, responsáveis e indicadores de desempenho. A solução aumentou a confiabilidade do controle, melhorou a governança dos planos de ação e tornou mais eficiente o processo de acompanhamento e cobrança junto aos responsáveis, contribuindo para maior agilidade na tomada de decisão.', NULL, N'Sim, a solução implementada resolveu esses problemas com sucesso, criando um banco de dados centralizado em Excel com controles automatizados e um painel do Power BI para monitorar o status das ações, prazos e responsáveis', N'A centralização das informações em uma única base de dados aumenta a confiabilidade e reduz o risco de perda de ações', 0, NULL, N'Estabelecida uma solucao simples, sustentável e de baixo custo. ', '2026-08-19T00:00:00.000', '2026-08-20T09:02:11.000', N'81058741', NULL, NULL);
INSERT INTO #PVC VALUES (11811, N'81020737', N'81020737', N'Remoção do Exercício Prático de Evacuação e Atualização do Passaporte de PAEBM', 2, N'No Replication/Sem replicação', N'Antes realizado 3 vezes por semana com cerca de 100 pessoas por turma, o exercício expunha participantes a riscos operacionais e burocratizava o acesso à ZAS por ser obrigatório.', N'Desburocratizar e trazer celeridade no acesso à Zona de Autossalvamento, bem como reduzir cenários de risco associados a realização do treinamento prático.', N'10141', N'01 - Imagens/01 - Antes/11811.jpeg', N'Superlotação em área operacional de risco;
INSERT INTO #PVC VALUES (11812, N'81058741', N'81058741', N'Criação de um dashboard automatizado para visualização dos processos de garantias', 1, N'Others/Outros', N'Visualização das informações via gráficos atualizados diretamente no power point, demandando mais tempo para atualizar as apresentações.', N'Visualizar e gerenciar melhor as FNC abertas', N'10015', N'01 - Imagens/01 - Antes/11812.jpeg', N'As informações de garantias eram apresentadas por meio de gráficos atualizados manualmente em apresentações PowerPoint. Esse processo demandava tempo significativo para consolidação e atualização dos dados, além de aumentar o risco de inconsistências e retrabalho na preparação dos materiais gerenciais.', N'01 - Imagens/02 - Depois/11812.jpeg', N'Foi desenvolvido um dashboard em Power BI para automatizar a atualização dos indicadores e gráficos de garantias. A solução proporcionou maior agilidade na preparação das apresentações, reduziu o esforço manual, aumentou a confiabilidade das informações e melhorou a qualidade visual das análises, tornando a tomada de decisão mais rápida e eficiente.', NULL, N'A solução atingiu o objetivo proposto ao eliminar atividades manuais repetitivas, reduzir o tempo de preparação das apresentações', N'A automação de indicadores reduz significativamente o tempo gasto com atividades manuais e repetitivas.', 0, NULL, N'As melhorias em uma bancada de teste geram maior confiabilidade, redução do tempo de ciclo e eliminação de falhas humanas. Os principais resultados esperados envolvem precisão de dados, segurança operacional e integração completa de processos.', '2026-06-30T00:00:00.000', '2026-08-20T09:25:01.000', N'81058741', NULL, NULL);
INSERT INTO #PVC VALUES (11813, N'520044', N'81030465', N'Caixa de vedação do coletor do filtro manga', 2, N'No Replication/Sem replicação', N' Ocorria vazamento de material particulado para o ambiente, gerando acúmulo de poeira na área, necessidade frequente de limpeza, devido a falhas de vedação na região de descarga para o recipiente coletor do filtro manga.', N'Reduzir o vazamento de partículas no ambiente.', N'10032', N'01 - Imagens/01 - Antes/11813.jpeg', N'Antes o coletor apresentava falhas de vedação na região de descarga para o recipiente coletor do filtro manga. Devido à existência de folgas entre o tubo de descarte e a tampa do recipiente, ocorria vazamento de material particulado para o ambiente, gerando acúmulo de poeira na área, necessidade frequente de limpeza. Além disso, havia perda de produto durante a operação.', N'01 - Imagens/02 - Depois/11813.jpeg', N'Foi implantada uma caixa de vedação na interface entre o tubo de descarga e o recipiente coletor, eliminando as folgas existentes. Com a melhoria, o descarte do material passou a ocorrer de forma confinada, reduzindo significativamente a emissão de particulados para o ambiente, evitando perdas de material e mantendo a área mais limpa e segura. ', NULL, N'Sim, foi implantado uma vedação na interface entre o tubo de descarga e o recipiente coletor, reduzindo o risco de vazamento das partículas.
INSERT INTO #PVC VALUES (11814, N'471876', N'471876', N'DRENO DE LIMPEZA', 1, N'Others/Outros', N'Na sala do Open não tinha dreno para escoar agua de limpeza, retirando a mesma de forma inadequada e improvisada.', N'Eliminar risco fisico e elétrico , preservando a integridade fisica dos colaboradores.', N'10032', N'01 - Imagens/01 - Antes/11814.jpeg', N'Na sala Open space, não havia dreno para limpeza, então a
INSERT INTO #PVC VALUES (11815, N'81054422', N'81054422', N'Escada Plataforma para Utilização Segura e Ergonômica do Britador Combo', 1, N'Others/Outros', N'Identificada dificuldade na utilização do equipamento britador combo ao inserir o material a ser cominuído, pois o ponto de alimentação encontrava-se em uma altura incompatível com a estatura média dos usuários, exigindo uma postura inadequada.', N'Garantir a utilização segura e ergonômica do britador combo', N'10081', N'01 - Imagens/01 - Antes/11815.jpeg', N'O ponto de alimentação do britador cônico do laboratório encontrava-se em uma altura incompatível com a estatura média dos usuários, exigindo posturas inadequadas, esforço excessivo e dificuldades durante o abastecimento do equipamento.
INSERT INTO #PVC VALUES (11816, N'81019185', N'81019185', N'Correia acionamento britador no Kanban', 1, N'Crusher/Britadeira', N'quando o britator para por rompimento da correia de acionamento, há um indisponibilidade grande por conta tempo desprendido em criar a reserva, localizar um veículo disponível, se deslocar até o armazém retirar as correias e voltar ao ativo para  manutenção', N'redução tempo parado ativo em corretiva', N'10178', N'01 - Imagens/01 - Antes/11816.jpeg', N'No ato da para do equipamento por quebra/rompimento da correia de acionamento, gerava perda significante no tempo, devido a necessidade de deslocamento até o armazém para retirar as correias de acionamento.
INSERT INTO #PVC VALUES (11817, N'81019185', N'81019185', N'Kanban Lubrificação Usinas', 1, N'Others/Outros', N'Tínhamos dificuldades com a programação de OMs com lubrificantes, pois em algumas situações não era possível gerar demanda antecipada, a inspeção identificava a necessidade, na semana da execução, isso gerava,  transportar com planejar OM< aprovar, liberar, logística do material, assim corríamos sério riscos de comprometer a saúde do ativo.', N'disponibilidade imediata de lubrificantes para aplicação nas usinas de Salobo', N'10178', N'01 - Imagens/01 - Antes/11817.jpeg', N'Antes da implementação do Kanban, era necessário aguardar que a inspeção avaliasse a necessidade de lubrificação do ativo, em muitos casos, isso era identificado faltando poucos dias para a manutenção programada, impactando diretamente vários processos, como a própria progamação, execução e saúde do ativo, além riscos de corretiva e no pior dos casos, em uma manutenção corretiva, a necessidade de deslocamento até o armazém', N'01 - Imagens/02 - Depois/11817.jpeg', N'Após a implementação do Kanban, o material fica disponível para aplicação imediata, contudo há necessidade de monitoramento diário dos níveis para bipagem do QR Code', NULL, N'o problema foi resolvido com a implementação do Kanban', N'a disponibilidade imediata de peças, materiais e sobressalentes, é fundamental para a saúde do ativo', 0, NULL, N'No more wondering drivers on roadways ', '2026-08-03T00:00:00.000', '2026-08-20T13:57:09.000', N'81019185', NULL, NULL);
INSERT INTO #PVC VALUES (11818, N'81039085', N'81039085', N'Sistema de lubrificação Filtro Andritz FI-2020-31', 1, N'Others/Outros', N'O sistema de translado do carro móvel do filtro Andritz FI-2020-31 não possuía sistema de lubrificação automática nos trilhos. A lubrificação era realizada manualmente e sem uma frequência definida, ocasionando deficiência na lubrificação dos trilhos. Como consequência, ocorriam travamentos durante o deslocamento do carro móvel, impedindo seu posicionamento correto nas etapas de abertura e fechamento do filtro. Essa condição gerava paradas corretivas do equipamento e impactava a disponibilidade operacional.', N'Redução de Falha, Aumento do MTBF e DF', N'10181', N'01 - Imagens/01 - Antes/11818.jpeg', N'KAIZEN: Instalação de Lubrificador Automático no Carro Móvel do Filtro Andritz FI-2020-31
INSERT INTO #PVC VALUES (11819, N'532446', N'532446', N'Tendência de Confiabilidade de KPIs – Usina Salobo', 1, N'Others/Outros', N'Reduzir em ≥ 98% o tempo de análise de tendência e eliminar a intervenção humana no cálculo, disponibilizando a leitura de 10 subprocessos para 4 gerências / 10 usuários, sustentando as metas de DF(%) 2026: Britagem Primária Complexo 87,8% · Britagem Secundária Complexo 88,1% · Usina Complexo 92,2%.', N'Redução de 98% no tempo de análise de tendência de kpis DF(%), MTBF(%) e MTTR(%)', N'10293', N'01 - Imagens/01 - Antes/11819.jpeg', N'•	Análise de tendência de KPIs feita de forma manual e não padronizada, via tabelas e planilhas nas rotinas D-1, S-1, M-1, RP e na análise quinzenal.
INSERT INTO #PVC VALUES (11820, N'81030117', N'81002274', N'Suporte de fixação do condensador do HDS ', 1, N'Others/Outros', N'Antes. 
INSERT INTO #PVC VALUES (11821, N'81058741', N'81058741', N'Melhoria na gestão de requisições criadas pela gerência', 1, N'Others/Outros', N'Gestão sem visão integrada e estratégica do acompanhamento das requisições abertas dentro da gerência', N'Melhorar a visão das requisiçõs criadas pela gerência', N'10015', N'01 - Imagens/01 - Antes/11821.jpeg', N'O controle das requisições SAP era realizado de forma não estruturada, sem atender plenamente às necessidades da gerência e sem proporcionar uma visão estratégica do acompanhamento das requisições em aberto. Isso dificultava o monitoramento, a priorização e a tomada de decisão.', N'01 - Imagens/02 - Depois/11821.jpeg', N'O controle foi aprimorado por meio da implementação de novas fórmulas, colunas de análise e indicadores relevantes. Além disso, foi desenvolvido um dashboard gerencial que fornece uma visão estratégica, permitindo que todos os solicitantes acompanhem o status das requisições de forma clara, ágil e padronizada, aumentando a visibilidade e a eficiência na gestão do processo.', NULL, N'A solução implementada atendeu ao objetivo inicial de transformar um controle descentralizado e pouco estruturado em uma ferramenta de gestão mais eficiente e estratégica', N'A automação de cálculos e análises reduz o trabalho manual, minimiza erros e aumenta a produtividade da equipe.', 0, NULL, N'Eliminar o risco de queda na área do hidrociclone, proporcionando acesso seguro para inspeções e manutenções, aumentando a segurança e a eficiência das atividades.', '2026-08-04T00:00:00.000', '2026-08-20T15:50:13.000', N'81058741', NULL, NULL);
INSERT INTO #PVC VALUES (11822, N'81030117', N'81002274', N'Suporte do evaporador do HDS', 1, N'Others/Outros', N'Sem suporte do evaporador do HDS', N'Garantir maior eficiencia no equipamento', N'10324', N'01 - Imagens/01 - Antes/11822.jpeg', N'Sem suporte do evaporador do HDS', N'01 - Imagens/02 - Depois/11822.jpeg', N'Projetado e Confeccionado suporte para o evaporador do HDS na cabine do operador.', NULL, N'Sem suporte do evaporador do HDS', N'Ganho de produtividade', 0, NULL, N'A vibração foi diminuída drasticamente do conjunto motor e bomba, aumentando a sua vida útil. ', '2026-08-11T00:00:00.000', '2026-08-20T15:59:56.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (11823, N'763789', N'763789', N'Ausência de direcionamento de água da drenagem do ar condicionado na Cabine da Ponte Rolante', 1, N'Others/Outros', N'Foi identificada a ausência de direcionamento adequado da água proveniente do dreno do ar-condicionado da cabine da Ponte Rolante, ocasionando o acúmulo de água na parte interna da estrutura, aumento da umidade e recorrência de intervenções de manutenção corretiva.', N'Eliminar a umidade proveniente do acúmulo da água condensada do ar-condicionado, garantindo o direcionamento seguro da drenagem para um ponto adequado de escoamento evitando recorrências.', N'10294', N'01 - Imagens/01 - Antes/11823.jpeg', N'No Posto da Ponte Rolante da Descarga de Cobre foi identificado que a água proveniente do dreno do ar-condicionado caia atrás da cabine em uma região interna da estrutura sem direcionamento adequado. Como consequência, a água causava muita umidade no local e necessidade de manutenção corretiva.', N'01 - Imagens/02 - Depois/11823.jpeg', N'Foi realizado um furo na estrutura e efetuado o transpasse da mangueira de drenagem para o lado externo. Com a adequação, a água passou a ser direcionada diretamente para a canaleta existente do lado de fora, eliminando o acúmulo da água e proporcionando um caminho controlado para o escoamento.', NULL, N'A mangueira de drenagem foi direcionada para a parte externa da cabine e conectada ao fluxo da canaleta existente, eliminando o acúmulo de água no interior da estrutura e proporcionando um escoamento controlado.', N'A melhoria demonstrou que a identificação e o direcionamento adequado de pequenos fluxos de água podem prevenir problemas recorrentes de umidade e manutenção. A solução simples utilizando a infraestrutura de drenagem  mostrou a importância de atuar na causa do problema e não apenas nos seus efeitos.', 0, NULL, N'Disponibilizar dashboard automatizado para acompanhamento dos custos evitados por frota, planejador e período, proporcionando maior visibilidade dos resultados para coordenação e gerência.', '2026-08-17T00:00:00.000', '2026-08-20T16:08:53.000', N'763789', NULL, NULL);
INSERT INTO #PVC VALUES (11824, N'81030117', N'81002274', N'Providenciado e instalado uma barreira 24v', 1, N'Others/Outros', N' Sistema eletrônico com baixa eficiência de tensão pelo acúmulo de dispositivos eletrônicos no equipamento.', N'Garantir maior segurança e eficiência', N'10324', N'01 - Imagens/01 - Antes/11824.jpeg', N' Sistema eletrônico com baixa eficiência de tensão pelo acúmulo de dispositivos eletrônicos no equipamento.', N'01 - Imagens/02 - Depois/11824.jpeg', N'Providenciado e instalado uma barreira 24v para o dimensionamento e balanceamento da tensão do equipamento, dividido a carga dos componentes e HDS.', NULL, N' Sistema eletrônico com baixa eficiência de tensão pelo acúmulo de dispositivos eletrônicos no equipamento.', N'Maior segurança', 0, NULL, N'Cada amostra deverá possuir uma identificação clara, permitindo sua rápida localização sempre que necessário. ', '2026-08-09T00:00:00.000', '2026-08-20T16:12:27.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (11825, N'81006670', N'81053737', N'MELHORIA NA BANCADA DE TESTE DE ALTERNADORES CAT', 1, N'Projects/Projetos', N'Bancada de testes possuía apenas um sistema de acionamento liga/desliga (ON/OFF), sem possibilidade de controle da rotação do motor responsável pelo acionamento do alternador.', N'Ajuste e controle de velocidade por meio de inversor de frequência.', N'10144', N'01 - Imagens/01 - Antes/11825.jpeg', N'A bancada de testes possuía apenas um sistema de acionamento liga/desliga (ON/OFF), sem possibilidade de controle da rotação do motor responsável pelo acionamento do alternador.
INSERT INTO #PVC VALUES (11826, N'81006670', N'81053737', N' Relé de Falta de Fase e Assimetria | CA07', NULL, N'Others/Outros', N'Ausência de monitoramento das três fases poderia permitir a alimentação das cargas em condições elétricas inadequadas.', N'Proteção contra falta de fase e assimetria no painel elétrico do CA07.', N'10144', N'01 - Imagens/01 - Antes/11826.jpeg', N'Alimentação do painel 380/220 V realizada por gerador síncrono acoplado a motor hidráulico.
INSERT INTO #PVC VALUES (11827, N'81038952', N'81021112', N'Tendência da Corrente na Bomba de Graxa (Prensagem)', 1, N'Others/Outros', N'Ausência do acompanhamento e leitura da curva de tendência da corrente elétrica no Faceplate do HP 2010-04 M11.
INSERT INTO #PVC VALUES (11828, N'1013590', N'1013590', N'Lime Slurry Pump Discharge Interlock Update', 1, N'Refining/Refino', N'The discharge valves for the lime slurry pumps could not be opened to drain back the lime slurry line without a bypass', N'Update interlocks', N'0', N'01 - Imagens/01 - Antes/11828.jpeg', N'The discharge valves for the lime slurry pumps could not be opened to drain back the lime slurry line without a bypass', N'01 - Imagens/02 - Depois/11828.jpeg', N'Changed "Pump Interlocked" Interlock Condition to only be active if pump is running. 
INSERT INTO #PVC VALUES (11829, N'81042534', N'81042534', N'Controle de vida útil dos revestimento do vertimil - Horimetro', 1, N'Concentration/Concentração', N'método de controle de desgaste de revestimento atual com assertividade baixa.', N'Controlar o desgaste dos revestimento dos moinhos verticais', N'10178', N'01 - Imagens/01 - Antes/11829.jpeg', N'O controle da vida útil dos revestimentos do moinho Vertimill era realizado com base apenas em dias corridos, sem considerar as horas efetivas de operação do equipamento. Esse método gerava informações imprecisas sobre o desgaste dos revestimentos, comprometendo a assertividade do planejamento de manutenção, das previsões de troca e da gestão de custos.', N'01 - Imagens/02 - Depois/11829.jpeg', N'O controle da vida útil dos revestimentos passou a ser realizado com base nas horas efetivamente trabalhadas pelo Vertimill, alinhando o acompanhamento do desgaste às condições reais de operação do equipamento.', NULL, N'A nova metodologia proporcionou maior precisão na gestão da vida útil dos revestimentos, aumentando a confiabilidade das previsões de troca, melhorando o planejamento das intervenções e contribuindo para a otimização dos custos de manutenção e da disponibilidade operacional.', N'ndicadores de desempenho devem refletir as condições reais de uso dos ativos.', 0, NULL, N'Disponibilização imediata de recurso para resgate em caso de queda na água.
INSERT INTO #PVC VALUES (11830, N'81009995', N'81009995', N'Added Walkway for Truck Drivers', 3, N'Others/Outros', N'When Drivers enter the plant and park, there is no fixed walk way for them to enter the security shack, causing them to wonder along our roadways ', N'give drivers clear direction on where to go', N'10255', N'01 - Imagens/01 - Antes/11830.jpeg', N'No painted walkway for the drivers to follow', N'01 - Imagens/02 - Depois/11830.jpeg', N'Painted walk way the directs drivers directly to the security shack', NULL, N'Drivers now have direction to get to the security shack', N'Drivers need direction', 0, NULL, N'Outcome achieved and makes cleaning easier ', '2026-08-20T00:00:00.000', '2026-08-21T11:21:59.000', N'81009995', NULL, NULL);
INSERT INTO #PVC VALUES (11831, N'81040856', N'81040856', N'LEIRA FIXA ENTRE OS BRITADORES FASE I E II', 1, N'Crusher/Britadeira', N'Tempo elevado para a confecção das leiras de bloqueio efetivo e para a liberação de acesso das equipes de manutenção, impactando o início das atividades e o cumprimento do cronograma das paradas preventivas.
INSERT INTO #PVC VALUES (11832, N'81046597', N'81046597', N'Painel de Gestão de PROs e DTs', 1, N'Open Pit/Poço aberto', N'Identificou-se a necessidade de correlacionar os PROs com seus respectivos DTs e controlar suas revisões, garantindo aderência entre os documentos e maior eficiência na gestão das Diretrizes Básicas.', N'Reduzir o tempo de análise e eliminar retrabalhos decorrentes da manipulação manual de planilhas, além de gerar insights para apoiar a elaboração e atualização dos DTs.', N'10293', N'01 - Imagens/01 - Antes/11832.jpeg', N'O controle era realizado por meio de planilhas atualizadas manualmente, gerando risco de erros, retrabalho e dificuldade para identificar PROs sem DTs associados ou documentos desatualizados. A análise da base completa demandava cerca de 5 horas.', N'01 - Imagens/02 - Depois/11832.jpeg', N'Foi desenvolvido um painel integrado às bases do SISPAV e GDB, correlacionando automaticamente PROs e DTs, controlando revisões e disponibilizando indicadores por meio de gráficos e tabelas. Com isso, o tempo de análise foi reduzido para aproximadamente 30 minutos.', N'https://app.powerbi.com/groups/me/apps/26f3e8ea-2b35-43eb-b4e0-5b07e8ff22ae/reports/faf9c3ce-2b4c-4e33-8c49-de9d7aca9eb5/be1a6fff60ddd9a37668?experience=power-bi', N'O problema foi resolvido. A ferramenta foi útil e passou a proporcionar uma análise rápida e eficaz.', N'A manipulação manual de planilhas aumenta a probabilidade de erros e retrabalhos. A integração automática de bases de dados aumenta a confiabilidade das informações.', 0, NULL, N'Criação da primeira projeção quinquenal de estoque para a Mina Salobo, proporcionando maior previsibilidade do Working Capital e suporte ao planejamento estratégico', '2026-08-20T00:00:00.000', '2026-08-21T12:13:51.000', N'81046597', NULL, NULL);
INSERT INTO #PVC VALUES (11833, N'81058052', N'81058052', N'Instalação de kit inclinômetro na prancha  do CV-60', 1, N'Others/Outros', N'A prancha CV-60 opera em terrenos acidentados sem monitoramento de inclinação, apresentando alto risco de tombamento e ineficiência operacional.', N'Zerar acidentes por tombamento da prancha e reduzir o tempo de carga/descarga em 10%.', N'10346', N'01 - Imagens/01 - Antes/11833.jpeg', N'Anteriormente, o acionamento de patolas e rampas era feito manualmente por alavancas no bloco. Isso impedia a visão ampla dos implementos, gerando risco de acidentes na mina. Além disso, a ausência de sistemas de inibição em desníveis deixava a operação vulnerável ao tombamento."', N'01 - Imagens/02 - Depois/11833.jpeg', N'Instalação de controle remoto com inclinômetro, permitindo visão panorâmica da manobra. Sistema antitombamento bloqueia comandos acima de 5° de desnível. Função anti-comando abrupto protege cilindros de içamento. Fim da operação manual, garantindo ergonomia e segurança contra tombamentos na mina', N'https://tecnnic.com.br/videos/ajuste-de-velocidade-do-instalador-no-controle-remoto-g4/', N'SIM. A automação via inclinômetro e controle remoto resolveu o problema ao bloquear operações em desníveis acima de 5°, zerando os riscos de tombamento. A visibilidade ampla da manobra e a proteção anti-comando abrupto dos cilindros garantiram total segurança operacional na mina, atingindo a meta estabelecida.', N'A automação de comandos manuais críticos na mina comprovou-se indispensável para a segurança. O monitoramento de desníveis e a proteção contra trancos hidráulicos eliminam riscos de tombamento e danos aos cilindros. Dar mobilidade e visão panorâmica ao operador eleva a eficiência operacional.', 14546, 1, N'A urna é utilizada para o recebimento contínuo de sugestões relacionadas à segurança, saúde e meio ambiente, possibilitando a criação de pautas relevantes para DDS, treinamentos e campanhas internas, além de apoiar na implementação de melhorias nos processos operacionais e nas condições de trabalho.', '2026-08-08T00:00:00.000', '2026-08-21T12:29:59.000', N'81058052', NULL, NULL);
INSERT INTO #PVC VALUES (11834, N'81061558', N'521769', N'"Eliminação de Risco de Queda em Hidrociclone por Meio da Instalação de Chapa de Piso Metálico"', 2, N'Concentration/Concentração', N'Durante as atividades de manutenção no hidrociclone, foi identificada a existência de uma área aberta ao redor do equipamento sem piso de apoio adequado. Essa condição expunha os colaboradores ao risco de queda durante a execução das atividades, exigindo o uso de linha de vida e aumentando o tempo e a complexidade da intervenção. Além disso, a falta de uma superfície segura dificultava o acesso aos pontos de manutenção, impactando a segurança e a eficiência operacional.', N'Melhorar a segurança e as condições de acesso para manutenção no hidrociclone, eliminando o risco de queda e proporcionando uma área de trabalho mais segura, reduzindo a necessidade de utilização de sistema de proteção contra quedas para atividades rotineiras.', N'#N/A', N'01 - Imagens/01 - Antes/11834.jpeg', N'Foi identificada uma condição insegura no acesso ao hidrociclone devido à inexistência de piso metálico em uma área utilizada para manutenção. A presença do vão aberto gerava risco potencial de queda de pessoas e ferramentas, exigindo controles adicionais de segurança, como o uso de linha de vida. Essa situação dificultava a execução das atividades de manutenção, aumentava o tempo de intervenção e expunha os colaboradores a riscos desnecessários.', N'01 - Imagens/02 - Depois/11834.jpeg', N'Solução/Melhoria 
INSERT INTO #PVC VALUES (11835, N'81063720', N'81063720', N'Reforço da Base da Bomba do Lavador', 1, N'Others/Outros', N'A bomba do lavador estava com uma vibração elevada em todo o conjunto motor e bomba, com isso a vida útil do equipamento é menor devido os danos causados com a vibração.', N'Reduzir vibração', N'10024', N'01 - Imagens/01 - Antes/11835.jpeg', N'A bomba do lavador estava com uma vibração elevada em todo o conjunto motor e bomba devido a base não ser muito rigida, com isso a vida útil do equipamento é menor devido os danos causados pela vibração.', N'01 - Imagens/02 - Depois/11835.jpeg', N'Foi realizado o reforço estrutural da base da bomba do lavador por meio da concretagem da fundação, eliminando folgas existentes no conjunto motor-bomba. A intervenção aumentou a rigidez do sistema, reduzindo significativamente os níveis de vibração do equipamento. Como resultado, houve melhoria na estabilidade operacional, aumento da confiabilidade do conjunto e redução do risco de falhas mecânicas associadas a desalinhamentos e afrouxamentos estruturais.', NULL, N'A vibração foi diminuída drasticamente do conjunto motor e bomba, aumentando a sua vida útil. ', N'Evitar vibração excessiva', 0, NULL, N'ausência de dispositivo com segurança para manuseio do feixe de mola.', '2026-08-20T00:00:00.000', '2026-08-21T14:38:45.000', N'81063720', NULL, NULL);
INSERT INTO #PVC VALUES (11836, N'510839', N'510839', N'Implantação de Dashboard Executivo para Gestão de Custos Evitados da Manutenção', 1, N'Others/Outros', N'Os custos evitados eram registrados, porém não existia uma ferramenta para consolidar e visualizar os resultados de forma gerencial. A falta de indicadores dificultava a análise dos ganhos financeiros e a tomada de decisão. A necessidade foi identificada durante a necessidade de fazer os resumos executivos mensais e semanais.', N'Implantar dashboard em Power BI para monitoramento automático dos custos evitados, proporcionando visibilidade gerencial dos resultados por frota, planejador e período.', N'10234', N'01 - Imagens/01 - Antes/11836.jpeg', N'O controle dos custos evitados era realizado diretamente em planilhas Excel individuais, exigindo atualização manual dos registros, consolidação dos resultados e cálculo dos valores acumulados. A ausência de indicadores visuais dificultava a análise dos resultados por frota, período e responsável, além de demandar tempo para preparação das informações gerenciais.', N'01 - Imagens/02 - Depois/11836.jpeg', N'Foi desenvolvido um dashboard corporativo em Power BI integrado à base de dados de custos evitados, permitindo atualização automática, consolidação dos resultados, visualização por frota e planejador, acompanhamento histórico e disponibilização dos indicadores em tempo real para coordenação e gerência.', N'https://app.powerbi.com/groups/me/apps/35b7c9ac-ffa0-4477-aab7-413c30d8c790/reports/477d7499-d8ba-4041-a40b-7048ae8df7c2/77b17664cf55f1f46bf8?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&experience=power-bi', N'Sim. O problema foi resolvido através da implantação de dashboard em Power BI, permitindo consolidação automática dos dados, visualização dos custos evitados por frota e planejador e acesso rápido às informações para suporte à tomada de decisão.', N'Ferramentas de automação e visualização de dados permitem transformar informações operacionais em indicadores gerenciais confiáveis, reduzindo atividades manuais e aumentando a velocidade na tomada de decisão.', 0, NULL, N'Os principais resultados alcançados com a implementação do Kaizen foram:
INSERT INTO #PVC VALUES (11837, N'81037508', N'81037508', N'ETIQUETA DE IDENTIFICAÇÃO ANALISES E LOCALIZAÇÃO', 3, N'Projects/Projetos', N'Durante a procura de amostras de minério, foi identificada a necessidade de manter um arquivo de amostras organizado, padronizado e corretamente identificado. A ausência de uma organização adequada pode gerar perda de tempo na localização das amostras, analises ainda não finalizadas, dificuldade de rastreamento e risco de armazenamento incorreto.', N'OTIMIZAR TEMPO ALIADO A ORGANIZAÇÃO', N'10032', N'01 - Imagens/01 - Antes/11837.jpeg', N'As caixas de amostras eram recebidas e pesadas para a realização das análises solicitadas. Porém, não havia um local padronizado para identificar e acompanhar as análises pendentes com isso, era necessário investir um tempo considerável na localização das amostras e na verificação de quais análises ainda estavam pendentes ou se já poderiam ser descartadas.
INSERT INTO #PVC VALUES (11838, N'146134', N'146134', N'Desenvolvimento do extensor metálico da tremonha do MP1000', 1, N'Crusher/Britadeira', N'A vedação entre o chute de alimentação e o bojo do britador MP1000 era realizada por meio de um borrachão adaptado, que apresentava desgaste frequente e baixa eficiência de vedação, ocasionando fuga de material, emissão de poeira para o ambiente, aumento das demandas de manutenção e comprometimento das condições operacionais da área.', N'Desenvolver e implantar um extensor metálico para a tremonha do britador MP1000', N'10146', N'01 - Imagens/01 - Antes/11838.jpeg', N'Antes da implantação do extensor da tremonha, a vedação entre o chute de alimentação e o bojo do britador MP1000 era realizada por meio de um borrachão adaptado. Essa solução apresentava baixa resistência às condições operacionais, sofrendo desgaste acelerado em função da abrasão do minério e das vibrações do equipamento.
INSERT INTO #PVC VALUES (11839, N'81009995', N'81009995', N'Added Sign for Pre Scanning Shipments', 3, N'No Replication/Sem replicação', N'A CCS came in and the wrong lot numbers were inputted to the wrong shipment due to shippers pre scanning bags. ', N'to get the shippers to not pre scan loads', N'10255', N'01 - Imagens/01 - Antes/11839.jpeg', N'No sign at the shipping bays ', N'01 - Imagens/02 - Depois/11839.jpeg', N'A sign has been added to the shipping bays to ensure that loads are not pre scanned.', NULL, N'Added sign to the shipping bay area to ensure no pre scanning ', N'Accountability for shippers to scan after the load', 0, NULL, N'Less wasted time, less trash to cleanup', '2026-08-20T00:00:00.000', '2026-08-21T16:35:25.000', N'81009995', NULL, NULL);
INSERT INTO #PVC VALUES (11840, N'1010227', N'1010227', N'Coriolis Flowmeter 231-474-FIT-10250 PM Revision', 1, N'Others/Outros', N'Two separate calibration PMs existed for the same flowmeter. The flowmeter measures flow, temperature, and density, but the calibration procedure covers all outputs. There is no need for having separate work orders to repeat the same calibration.', N'Review PMs to ensure they are applicable for the instrument model.', N'0', N'01 - Imagens/01 - Antes/11840.jpeg', N'Two PMs existed for a calibration of the same Coriolis Meter, one on a one-year cycle and another on a two-year cycle.  ', N'01 - Imagens/02 - Depois/11840.jpeg', N'Deactivated the duplicate PM and reduced the tasks to just one operation. The calibration procedure is now clearly defined on one plan.', NULL, N'Yes, the problem was solved. Going forward there will be much clearer calibration history of this instrument.', N'Maintenance activities should be routinely scrutinized to ensure they are adding value to the operation of the plant.', 0, NULL, N'Ergonomic improvement.', '2026-08-14T00:00:00.000', '2026-08-21T16:39:29.000', N'1010227', NULL, NULL);
INSERT INTO #PVC VALUES (11841, N'81055646', N'81054838', N'Adequação da altura do canhão de água', 1, N'Others/Outros', N'O canhão de água encontrava-se com altura insuficiente para atingir adequadamente a área de aplicação. Devido à sua posição baixa, o equipamento estava praticamente inutilizado, comprometendo a eficiência da aspersão e do controle operacional.', N' Recuperação da funcionalidade do canhão de água. Aumento da área de cobertura da aspersão.', N'10097', N'01 - Imagens/01 - Antes/11841.jpeg', N'Canhão instalado em altura inadequada, com baixo alcance e sem atender à necessidade operacional da área.', N'01 - Imagens/02 - Depois/11841.jpeg', N'Canhão elevado através da instalação de extensão de tubulação, proporcionando alcance adequado e retorno da operação eficiente do equipamento.', NULL, N'Foi acoplado um trecho adicional de tubulação na base do canhão, elevando sua altura de instalação. A modificação permitiu aumentar o alcance operacional e direcionar o jato para a área necessária.', N'Com uma simples adequação da tubulação, foi possível transformar um equipamento sem utilização efetiva em uma solução operacional novamente funcional, aumentando a eficiência do sistema sem investimentos significativos', 0, NULL, N'N/A', '2026-08-14T00:00:00.000', '2026-08-22T09:47:59.000', N'81055646', NULL, NULL);
INSERT INTO #PVC VALUES (11842, N'81055646', N'81054838', N'Disponibilização de Boia de Resgate em Área de Sump', 2, N'Others/Outros', N'A área do sump possuía risco potencial de queda de pessoas na água e não contava com um dispositivo de resgate disponível nas proximidades para atuação imediata em caso de emergência.', N'Disponibilização imediata de recurso para resgate em caso de queda na água.', N'10097', N'01 - Imagens/01 - Antes/11842.jpeg', N'Área do sump sem boia de resgate disponível, dificultando uma resposta rápida em caso de emergência envolvendo queda na água.', N'01 - Imagens/02 - Depois/11842.jpeg', N'Boia de resgate instalada em local visível e de fácil acesso, com cabo e sinalização, proporcionando maior segurança e agilidade em situações de resgate.', NULL, N'Foi instalada uma boia de resgate com cabo em ponto estratégico próximo ao sump, acompanhada de sinalização orientando sua preservação e utilização em situações de emergência.', N'Uma ação simples e de baixo custo que fortalece a prontidão para emergências, contribuindo para a preservação da vida e para um ambiente de trabalho mais seguro.', 0, NULL, N'N/A', '2026-08-14T00:00:00.000', '2026-08-22T10:08:52.000', N'81055646', NULL, NULL);
INSERT INTO #PVC VALUES (11843, N'1008360', N'81039898', N'Light for Ball Mill Discharge Tank ', 3, N'Others/Outros', N'Due to low light above the tank it makes it hard for cleaning out the tank and getting samples ', N'Install light to help see ', N'0', N'01 - Imagens/01 - Antes/11843.jpeg', N'Light missing, making the cleaning of the tank harder and grabbing samples more troublesome ', N'01 - Imagens/02 - Depois/11843.jpeg', N'Light installed to make cleaning and obtaining samples easier ', NULL, N'Yes', N'Lighting makes things easier ', 0, NULL, N'Reduzir o esforço físico e os riscos ergonômicos e operacionais, facilitar o acionamento e a manutenção da válvula, evitar travamentos e quebras do pino e aumentar a confiabilidade do sistema.', '2026-08-21T00:00:00.000', '2026-08-22T11:10:32.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11844, N'81033365', N'1005614', N'Suporte da antena', 1, N'Others/Outros', N'ausência de suporte adequado', N'processo de melhoria', N'10346', N'01 - Imagens/01 - Antes/11844.jpeg', N'FOI IDENTIFICADO QUE A ANTENA ERA FIXADA COM BRAÇADEIRAS PLASTICAS, NO ENTANTO, EM POUCO TEMPO DANIFICAVA A ANTENA DEVIDO A FIXAÇÃO INADEQUADA.', N'01 - Imagens/02 - Depois/11844.jpeg', N'FOI FRABRICADO UM SUPORTE ADEQUADO PARA REALIZAR A FIXAÇÃO DA ANTENA ELIMINANDO AS FALHAS DE FIXAÇÃO.', NULL, N'fabricado suporte adequado.', N'Melhoria continua', 0, NULL, N'Resolvido ', '2026-08-21T00:00:00.000', '2026-08-22T15:34:55.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11845, N'81054395', N'81054395', N'Projeção de Capital de Giro Aplicada à Gestão Estratégica de Materiais para os Próximos Cinco Anos', 1, N'Open Pit/Poço aberto', N'O time de Suprimentos não possuía visibilidade sobre o planejamento futuro de materiais da operação, dificultando a projeção das variações de estoque e a construção das metas de Working Capital.', N'Desenvolver uma metodologia para projetar os impactos futuros no estoque e apoiar o planejamento do Capital de Giro (Working Capital) da operação para os próximos cinco anos.', N'10015', N'01 - Imagens/01 - Antes/11845.jpeg', N'O time de Suprimentos não possuía visibilidade dos impactos futuros das movimentações de estoque da operação, limitando a previsibilidade do Working Capital e o planejamento de longo prazo', N'01 - Imagens/02 - Depois/11845.jpeg', N'Projeção das entradas e saídas de materiais em estoque para os próximos cinco anos, apoiando o planejamento do Working Capital, aumentando a previsibilidade financeira e a assertividade na tomada de decisão estratégica.', NULL, N'O problema foi resolvido por meio da consolidação das projeções de estoque para os próximos cinco anos, proporcionando maior previsibilidade do Working Capital e suporte ao planejamento estratégico da operação.', N'ntegração de dados - Visão de longo prazo - Previsibilidade financeira - Planejamento estratégico - Tomada de decisão assertiva - Gestão de estoque - Working Capital', 0, NULL, N'EVITAR QUEBRA CONSTANTE E PARADAS EM CORRETIVAS . MELHORANDO NOSSOS INDICADORES', '2026-08-21T00:00:00.000', '2026-08-22T15:40:01.000', N'81054395', NULL, NULL);
INSERT INTO #PVC VALUES (11846, N'81045351', N'81045351', N'Urna de Sugestões de Temas e Melhorias da Segurança do Trabalho', 2, N'Others/Outros', N'Foi identificada a necessidade de ampliar a participação dos colaboradores na identificação e comunicação de oportunidades de melhoria relacionadas à Segurança, Saúde e Meio Ambiente, uma vez que nem todas as sugestões, percepções de riscos e necessidades observadas no dia a dia são formalmente registradas e direcionadas para tratamento.', N'Estimular o envolvimento direto das equipes na identificação de oportunidades de melhoria, reforçar a cultura de prevenção e valorizar a escuta ativa dos trabalhadores no ambiente laboral.', N'10017', N'01 - Imagens/01 - Antes/11846.jpeg', N'Antes da iniciativa, não havia um canal contínuo para registro de sugestões, dificultando a participação dos colaboradores e o aproveitamento de ideias para melhorias em SSMA.', N'01 - Imagens/02 - Depois/11846.jpeg', N'Após a iniciativa, a urna passou a facilitar o registro de sugestões, ampliando a participação das equipes e contribuindo para melhorias em SSMA, DDS, treinamentos e campanhas.', NULL, N'A iniciativa atendeu à necessidade identificada ao criar um canal contínuo para recebimento de sugestões, ampliando a participação dos colaboradores e contribuindo para a identificação e implementação de melhorias em SSMA.', N'A iniciativa mostrou que a participação dos colaboradores fortalece a cultura de prevenção, facilita a identificação de oportunidades de melhoria e contribui para ações mais assertivas em Segurança, Saúde e Meio Ambiente.', 0, NULL, N'Aumentar a assertividade na separação dos materiais pelo Armazém.
INSERT INTO #PVC VALUES (11847, N'81022747', N'81011443', N'Suporte para  transportar caixas de ferramentas', 1, N'Others/Outros', N'Antes caixas de ferramentas eram transportadas dessa formas', N'Mas segurança e organização', N'10144', N'01 - Imagens/01 - Antes/11847.jpeg', N'Antes caixas de ferramentas eram transportadas dessa formas', N'01 - Imagens/02 - Depois/11847.jpeg', N'Foi confeccionado e aplicado na SM-04 Suporte para  transportar caixas de ferramentas de formas seguras e organizado', NULL, N'Antes não tinha segurança ao transportar as caixas, as mesmas ficavam soltas na carroceria podendo causar acidentes.', N'Segurança no processo', 0, NULL, N'segurança durante o processo de pressurização hidráulica do sistema.', '2026-08-21T00:00:00.000', '2026-08-22T15:55:18.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (11848, N'81033365', N'81048572', N'Dispositivo de içamento do feixe de mola', 1, N'Others/Outros', N'ausência de dispositivo de içamento', N'processo de melhoria', N'10346', N'01 - Imagens/01 - Antes/11848.jpeg', N'Antes, a colocação manual do feixe de mola por duas pessoas exigia esforço excessivo e gerava sério risco de graves acidentes por queda ou pensamento.', N'01 - Imagens/02 - Depois/11848.jpeg', N'Com a fabricação de um suporte para a utilização da talha, o manuseio tornou-se mecânico, eliminando a força bruta e garantindo total segurança no processo.', NULL, N'ausência de dispositivo com segurança para manuseio do feixe de mola.', N'melhoria continua', 0, NULL, NULL, '2026-08-21T00:00:00.000', '2026-08-22T15:56:10.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11849, N'81045351', N'81045351', N'Nosso Maior Motivo para Trabalhar com Segurança', 2, N'Others/Outros', N'Falta de um vínculo visual e emocional que conecte as práticas diárias de segurança ao retorno diário para a família, limitando a conscientização e o sentimento de pertencimento dos colaboradores.', N'fortalecer o engajamento, o reconhecimento e a conscientização sobre segurança no trabalho, para relembrar os colaboradores as famílias que estão aguardando o retorno para casa com saúde e segurança.', N'10017', N'01 - Imagens/01 - Antes/11849.jpeg', N'Não há um mural físico que destaque os colaboradores e suas famílias, o que limita a conexão emocional com o propósito maior da segurança: voltar para casa bem todos os dias. ', N'01 - Imagens/02 - Depois/11849.jpeg', N'Forma poderosa de nos lembrar da importância de trabalhar com segurança, para que possamos sempre voltar para casa, para os braços das pessoas mais importantes da nossa vida: nossa família.', NULL, N'A meta foi plenamente atingida ao transformar uma regra operacional abstrata ("trabalhar com segurança") em um lembrete diário e tangível ("voltar para quem nos espera"), cobrindo a lacuna emocional identificada no problema inicial.', N'A principal lição aprendida com esta iniciativa é que conectar os procedimentos técnicos de segurança do trabalho a gatilhos emocionais e visuais — como a imagem da família de cada colaborador — transforma a prevenção em um valor pessoal, humanizando as regras operacionais, fortalecendo o sentimento de pertencimento e gerando um engajamento coletivo muito mais profundo do que o obtido por treinamentos e avisos tradicionais.', 0, NULL, N'ausência de recurso para realizar lavagem.', '2026-08-17T00:00:00.000', '2026-08-22T16:17:25.000', N'81045351', NULL, NULL);
INSERT INTO #PVC VALUES (11850, N'87000071', N'87000089', N'Mejora en soporte de manguera de agua', 3, N'Projects/Projetos', N'Se evidencia que no se contaba con un soporte estandarizado para la manguera de agua industrial para la perforación', N'Estandarizar el soporte de manguera', N'10028', N'01 - Imagens/01 - Antes/11850.jpeg', N'Se utiliza una escalera plegable para dar la altura y soporte a la manguera de agua industrial ', N'01 - Imagens/02 - Depois/11850.jpeg', N'Se confeccionan soportes adecuados para las mangueras de agua industrial', NULL, N'El problema fue solucionado con un soporte apropiado para el requerimiento, dando mejor soporte a las mangueras de agua que es un elemento crítico en el desarrollo de la perforación de sondajes ', N'Evaluar si los elementos utilizados en las campañas de perforación son apropiados', 0, NULL, N'RETIRAMOS O RISCO DE ACIDENTE', '2026-08-17T00:00:00.000', '2026-08-22T17:28:20.000', N'87000071', NULL, NULL);
INSERT INTO #PVC VALUES (11851, N'81023633', N'125450', N'Otimização de Bloqueio Operacional: Britagens 1, 2 e 3', 1, N'Others/Outros', N'O tempo de bloqueio nas Britagens era muito alto (40 a 60 minutos) devido à grande distância física entre o CCB e a subestação. Esse deslocamento demorado aumentava a exposição das equipes ao risco de campo e elevava a chance de perda ou extravio de chaves e cartões de bloqueio.', N'Otimizar o processo de bloqueio e desbloqueio operacional nas Britagens Secundárias (Salobo 1, 2 e 3), aumentando a segurança das equipes e a disponibilidade física dos ativos durante as PGUs e paradas longas.', N'10064', N'01 - Imagens/01 - Antes/11851.jpeg', N'O processo de bloqueio apresentava um tempo de execução entre 40 e 60 minutos, devido à distância entre o CCB e a subestação. Essa condição aumentava o tempo de deslocamento e, consequentemente, a exposição das equipes aos riscos, além de elevar a possibilidade de perda ou extravio de chaves e cartões de bloqueio durante os deslocamentos, impactando a segurança e a eficiência do processo.', N'01 - Imagens/02 - Depois/11851.jpeg', N'Instalação de um anexo do CCB, integrado ao planejamento estratégico do PAEBM para redução de riscos. A ação otimizou o processo e reduziu o tempo de bloqueio de 40–60 minutos para apenas 5–15 minutos, garantindo muito mais agilidade nas PGUs e paradas longas. Por utilizar uma estrutura em container de fácil deslocamento, a unidade pode ser movimentada e operar alternadamente conforme a necessidade entre a Britagem Secundária Salobo 1 e 2 e a Britagem Secundária Salobo 3, gerando economia ao evitar a compra de um novo equipamento.', NULL, N'Sim. O problema foi totalmente resolvido. A distância foi eliminada, o tempo de bloqueio caiu drasticamente de 40–60 minutos para 5–15 minutos, e os riscos de segurança e extravio de chaves foram mitigados com sucesso.', N'Tempo otimizado, Layout estratégico, Custo evitado ', 0, NULL, N'- Eliminação/redução de riscos elétricos;
INSERT INTO #PVC VALUES (11852, N'1010304', N'1010304', N'Reject cleanout bucket upgrade', 3, N'Crusher/Britadeira', N'A smaller bucket was being used to catch the garbage from the newly installed ball mill reject collection box. This resulted in some of the trash being dropped to the floor instead of going into the bucket for disposal.', N'Better and easier cleanup of Ball mill reject', N'10002', N'01 - Imagens/01 - Antes/11852.jpeg', N'Small bucket being used to collect waste was not big enough to catch entire contents, therefore some trash was landing on the floor requiring extra effort to clean up.', N'01 - Imagens/02 - Depois/11852.jpeg', N'Larger collection barrel was made, with handles, for easy catch-all and dumping of ball mill reject waste.', NULL, N'Yes, problem was solved. All the trash is collected in one motion now, and remains easy to dump into appropriate bin.', N'Easier waste cleanup and disposal. ', 0, NULL, N'Garantir acompanhamento contínuo dos treinamentos obrigatórios da equipe, permitindo atuação preventiva sobre vencimentos, maior conformidade dos requisitos de capacitação e melhor suporte à gestão da equipe.', '2026-08-22T00:00:00.000', '2026-08-23T01:40:31.000', N'1010304', NULL, NULL);
INSERT INTO #PVC VALUES (11853, N'1010304', N'1010304', N'Easy move ball mill media chute', 2, N'Crusher/Britadeira', N'Ball Mill media chute is difficult to move into position for use and/or storage', N'Ergonomics and ease of use', N'10002', N'01 - Imagens/01 - Antes/11853.jpeg', N'Flat wooden bottom does not move on grating easily. Unit is awkward and somewhat heavy to move, especially alone.', N'01 - Imagens/02 - Depois/11853.jpeg', N'Castors added to one side, creating a tip and roll type unit, which is easy to move around, and eliminates the need to lift the unit fully off the floor.', NULL, N'Yes, the problem was solved. Unit is easier to move, creating less potential for injury.', N'Much better and safer ergonomics for the task.', 0, NULL, N'Rastreabilidade.', '2026-08-22T00:00:00.000', '2026-08-23T01:47:09.000', N'1010304', NULL, NULL);
INSERT INTO #PVC VALUES (11854, N'1008792', N'1008792', N'SUV Booster Cables ', 3, N'No Replication/Sem replicação', N'No Booster cables in SUV, ', N'Safety', N'10002', N'01 - Imagens/01 - Antes/11854.jpeg', N'No booster cables in SUV when battery would die', N'01 - Imagens/02 - Depois/11854.jpeg', N'Booster cables added to SUV, if vehicle battery dies we can easily boost it ', NULL, N'YES', N'N/A', 0, NULL, N'Com a eliminação das paradas por sobrecarga do transportador TR-0320-04, foi eliminada a necessidade de intervenção direta dos operadores para a remoção do excesso de material sobre a correia por meio de ferramentas manuais, aumentando a segurança operacional e reduzindo a exposição a riscos.', '2026-08-22T00:00:00.000', '2026-08-23T02:20:27.000', N'1008792', NULL, NULL);
INSERT INTO #PVC VALUES (11855, N'1008792', N'1008792', N'Ball Mill Gear Spray Area', 3, N'No Replication/Sem replicação', N'Gear Spray area was leaking/Heating blankets would sometimes not work', N'Safety, Clean', N'10002', N'01 - Imagens/01 - Antes/11855.jpeg', N'Area needed to be cleaned up', N'01 - Imagens/02 - Depois/11855.jpeg', N'New Heating blankets ordered and installed, lines wrapped for the gear spray, area overall tidied up. New pumps installed for gear spray barrel as well', NULL, N'YES', N'N/A', 0, NULL, N'Significant improvements to time saving and accuracy.', '2026-08-22T00:00:00.000', '2026-08-23T02:34:51.000', N'1008792', NULL, NULL);
INSERT INTO #PVC VALUES (11856, N'81052181', N'506197', N'Melhoria no sistema de fixação do volante da Válvula de Fluxo. ', 1, N'Others/Outros', N'O pino de fixação do volante da válvula de fluxo apresentava oxidação e travamento, dificultando sua remoção e exigindo maior esforço físico. Essa condição poderia causar quebra de componentes, riscos ergonômicos e de segurança, além de dificultar o acionamento da válvula, comprometendo o controle do fluxo, a manutenção e a continuidade operacional.', N'Implementar o pino de saque rápido em 100% dos volantes de válvula de fluxo que apresentem a mesma condição, eliminando o travamento do sistema de fixação e reduzindo a zero as ocorrências relacionadas à oxidação, dificuldade de remoção e quebra do pino após a implantação da melhoria.', N'10245', N'01 - Imagens/01 - Antes/11856.jpeg', N'Pino convencional sujeito á oxidação e travamento, dificultando a remoção do volante e exigindo esforço excessivo. ', N'01 - Imagens/02 - Depois/11856.jpeg', N'Pino de saque rápido, facilitando a remoção do volante, reduzindo esforço e riscos operacionais e de manutenção. ', NULL, N'A melhoria atendeu à meta proposta, eliminando as dificuldades de remoção do pino e reduzindo os riscos associados ao travamento.', N'A substituição de componentes sujeitos à oxidação por soluções de saque rápido reduz esforços, facilita a manutenção e aumenta a segurança operacional.', 0, NULL, N'ELIMANANDO RISCO DE EXPOSIÇÃO DOS COLABORADORES, REDUÇÃO TEMPO ATIVIDADE DE 8H PARA 1 HORA, PROPORCIONANDO AMBIENTE MAIS LIMPO E SEGURO NAS ATIVIDADES.', '2026-08-21T00:00:00.000', '2026-08-23T03:26:35.000', N'81052181', NULL, NULL);
INSERT INTO #PVC VALUES (11857, N'81035680', N'524796', N'APLICAÇÃO DE MELHORIA NO CABO DE ALIMENTAÇÃO DA EC18', 2, N'Projects/Projetos', N'Cabo de alimentação estava amarrado com cordas e exposto a quinas vivas na saída do kambao que auxilia o equipamento no arraste do cabo.', N'Evitar perdas, evitar ocorrências de segurança relacionadas ao cabo de alimentação', N'10324', N'01 - Imagens/01 - Antes/11857.jpeg', N'Cabo de alimentação estava amarrado com cordas e exposto a quinas vivas na saída do kambao que auxilia o equipamento no arraste do cabo.', N'01 - Imagens/02 - Depois/11857.jpeg', N'Fabricado suporte, providenciado  abraçadeira e aplicado melhoria evitando que em algum momento na locomoção do equipamento viesse acontecer algum dano ao cabo ou ao equipamento.', NULL, N'Sim, resultando em uma melhoria para evitar danos ao cabo e ao equipamento ', N'Evitar ocorrências de segurança relacionadas ao cabo de alimentação', 0, NULL, N'Maior rastreabilidade da carteira, possibilidade de não alocar recursos em tarefas já executadas.', '2026-08-22T00:00:00.000', '2026-08-23T04:36:28.000', N'81035680', NULL, NULL);
INSERT INTO #PVC VALUES (11858, N'496444', N'496410', N'MELHORIA NO ESTRIBO DE EMERGENCIA', 1, N'Others/Outros', N'PRIMEIRO DEGRAU DANIFICAVA CONSTANTEMENTE DURANTE A OPERAÇAO. ', N'ELIMINAR REPARO CONSTANTE ', N'10131', N'01 - Imagens/01 - Antes/11858.jpeg', N'ESTRIBO DE EMERGENCIA DANIFICAVA CONSTANTEMENTE DURANTE A OPERAÇAO. GERAVA CUSTOS DE MATERIAL TEMPO E MAO DE OBRA PARA REPARO .', N'01 - Imagens/02 - Depois/11858.jpeg', N'FOI ELIMINADO O PRIMEIRO DEGRAU E DEIXADO APANAS DOIS DEGRAUS METALICOS. ASSIM A BORRACHA FICAVA MAIS MALEAVEL E REDUZINDO A RIDIZ DO COMPENENTE EVITANDO A QUEBRA CONSTANTE DO ESTRIBO', NULL, N'SIM FOI RESOLVIDO . O EQUIPAMENTO RODOU E VERIFICAMOS QUE O EQUIPAMENTE PERFOMOU SEM DANIFICAR NOVAMENTE A ESCADA APOS A MELHORIA', N'MELHORAR O PROCESSO SEMPRE', 0, NULL, N'redução de risco no transporte dos mantos primário, melhor ambiente 5S na área, ', '2026-08-22T00:00:00.000', '2026-08-23T05:37:26.000', N'496444', NULL, NULL);
INSERT INTO #PVC VALUES (11859, N'81030153', N'81030153', N'Envio dos Protocolos de Separação ao Armazém para Maior Assertividade nas Entregas de Materiais', 1, N'Others/Outros', N'O Armazém recebia apenas a capa contendo as ordens, solicitações e reservas de materiais para realizar a separação. Como não possuía acesso aos protocolos completos utilizados pela equipe de Preparação de Materiais, nem sempre tinha visibilidade de todos os itens previstos para cada frota. Essa limitação gerava desvios na separação, necessidade de retrabalho, atrasos na identificação de inconsistências e aumento do tempo gasto para correção dos processos, impactando a eficiência e a confiabilidade das entregas planejadas.', N'Aumentar a assertividade na separação de materiais por meio do envio dos protocolos de conferência ao Armazém, reduzindo desvios, retrabalho e tempo gasto na resolução de inconsistências nas entregas.', N'10279', N'01 - Imagens/01 - Antes/11859.jpeg', N'Antes da implementação da melhoria, a equipe do Armazém recebia apenas a capa contendo as ordens, solicitações e reservas de materiais para realizar a separação. Os protocolos de conferência elaborados pela equipe de Preparação de Materiais permaneciam apenas com os preparadores, não sendo compartilhados com o Armazém.', N'01 - Imagens/02 - Depois/11859.jpeg', N'A equipe de Preparação de Materiais passou a enviar ao Armazém, por e-mail, os protocolos de conferência de todas as frotas juntamente com a capa das ordens e reservas. Com acesso a essas informações, o Armazém realiza uma separação mais assertiva, reduzindo desvios, retrabalho e o tempo gasto com correções.', NULL, N'Sim, o problema foi resolvido. Com o envio dos protocolos de conferência ao Armazém, além da capa com ordens, solicitações e reservas, a equipe passou a ter acesso a todas as informações necessárias para realizar a separação dos materiais de forma mais assertiva. A melhoria reduziu a ocorrência de desvios, diminuiu o retrabalho e agilizou a identificação de possíveis inconsistências, atendendo ao objetivo de aumentar a confiabilidade e a eficiência do processo de entrega de materiais.', N'O compartilhamento de informações entre as equipes contribui para uma separação mais assertiva dos materiais.', 0, NULL, N'Redução de  tempo de segregação, exposição empregados, melhoria no 5 S da área.', '2026-08-20T00:00:00.000', '2026-08-23T07:43:26.000', N'81030153', NULL, NULL);
INSERT INTO #PVC VALUES (11860, N'81034908', N'81034908', N'Dispositivo de anti-chicoteamento unidade hidraúlica moinhos', 2, N'Projects/Projetos', N'Ao realizar inspeção nas unidades hidráulicas dos moinhos, foi observado o risco de rompimento de mangueiras de alta pressão devido a fadiga nos terminais, podendo projetar em colaboradores que estiverem proximo do local', N'mitigar o impacto do desprendimento de mangueiras hidráulicas.', N'10031', N'01 - Imagens/01 - Antes/11860.jpeg', N'Ao realizar inspeção nas unidades hidráulicas dos moinhos, foi observado o risco de rompimento de mangueiras de alta pressão devido a fadiga nos terminais, podendo projetar em colaboradores que estiverem proximo do local', N'01 - Imagens/02 - Depois/11860.jpeg', N'Foi realizado a instalação de cabo de aço dimensionado corretamente para absorção caso tenhamos qualquer rompimento da mangueira hidráulica, mitigando a projeção da mangueira no colaborador que estiver proximo do local.', NULL, N'sim, aplicando esse dispositivo conseguimos dar mais segurança aos nossos colaboradores no circuito pressurizado do sistema hidráulico.', N'todo equipamento tem possibilidade de melhoria', 0, NULL, N'Equipe de execução tem ferramenta para acompanhamento dos custos, consumo e requisições.', '2026-08-07T00:00:00.000', '2026-08-23T08:04:44.000', N'81034908', NULL, NULL);
INSERT INTO #PVC VALUES (11861, N'1008368', N'1008368', N'Replacing of steam trap ST-0269', NULL, N'No Replication/Sem replicação', N'Waiting for Maintenance to replace steam trap is lost time and lost steam literally up the vent stack. Also the cost of maintenance doing the task can be saved if operations does the task', N'Trap without involving maintenance', N'0', N'01 - Imagens/01 - Antes/11861.jpeg', N'Steam Trap 0269 is passing high pressure steam which is not making condensate which could be reused in boiler room. Steam entering the condensate vessel is lost as it escapes to atmosphere through vent on vessel.', N'01 - Imagens/02 - Depois/11861.jpeg', N'New Trap installed allowing steam to convert to condensate for reuse rather than losing it through the Vent stack.', NULL, N'Yes, new steam trap installed without involving maintenance', N'Having operations complete task removes the cost of having maintenance do the task.', 3000, 3, NULL, '2026-08-22T00:00:00.000', '2026-08-23T12:40:46.000', N'1008368', NULL, NULL);
INSERT INTO #PVC VALUES (11862, N'81033365', N'81033365', N'Mangueira de água retrátil', 1, N'Others/Outros', N'ausência de mangueira de água.', N'processo de melhoria', N'10346', N'01 - Imagens/01 - Antes/11862.jpeg', N'Lavagem dos condensadores de A/C era demorada e difícil por falta de um ponto de água próximo para realizar.', N'01 - Imagens/02 - Depois/11862.jpeg', N'Foi instalado um ponto de água local e mangueira retrátil para facilitar a dos condensadores de A/C dos caminhões. ', NULL, N'ausência de recurso para realizar lavagem.', N'melhoria continua', 0, NULL, N'Otimização de parada em PM.', '2026-08-22T00:00:00.000', '2026-08-23T15:12:04.000', N'81033365', NULL, NULL);
INSERT INTO #PVC VALUES (11863, N'543555', N'543555', N'ELIMNAÇÃO DO VAZAMENTO SALA DE PURIFICAÇÃO DE ÁGUA', 2, N'Others/Outros', N'O SISTEMA DE DRENO DAS PIAS NÃO ERA EFICAZ, FAZENDO COM QUE A ÁGUA TRANSBORDASSE PARA DENTRO DA SALA, AUMENTANDO O RISCO DE ESCORREGÃO E QUEDA DO EMPREGADO.', N'ELIMINAÇÃO', N'10198', N'01 - Imagens/01 - Antes/11863.jpeg', N'O sistema de drenagem das pias não apresentava eficácia, permitindo o transbordamento de água para o interior da sala e expondo os empregados ao risco de escorregão e queda.', N'01 - Imagens/02 - Depois/11863.jpeg', N'Foi realizado o alongamento da tubulação, com a devida inserção da mesma no ralo, evitando o transbordamento de água para o interior da sala', NULL, N'SIM, ELIMINAMOS A POSSIBILIDADE DE VAZAMENTO DA ÁGUA PROVENIENTE DAS PIAS', N'REFORÇANDO O CUIDADO ATIVO GENUINO', 0, NULL, N'Aumentar a produtividade na fabricação das buchas do SAG, reduzindo o tempo de usinagem e o desperdício de material, sem comprometer a qualidade e a segurança, elevando a produção de 1 para 12 peças por turno.', '2026-08-22T00:00:00.000', '2026-08-23T22:55:22.000', N'543555', NULL, NULL);
INSERT INTO #PVC VALUES (11864, N'81030486', N'81047116', N'Eliminação de riscos elétricos e melhoria da organização, proteção e confiabilidade das conexões elétricas.', 1, N'Others/Outros', N'Durante inspeção em campo, foi identificada uma condição inadequada na instalação elétrica, principalmente no encaminhamento e nas conexões dos cabos de potência.
INSERT INTO #PVC VALUES (11865, N'92000576', N'92000576', N'Automatização da Gestão de Treinamentos VES por Meio de Dashboard', 1, N'Others/Outros', N'O processo de acompanhamento dos treinamentos obrigatórios da equipe era realizado por meio de uma planilha Excel atualizada manualmente pela pessoa focal da coordenação. Para manter as informações atualizadas, cada colaborador precisava informar a conclusão dos treinamentos, permitindo o preenchimento manual das datas e respectivos vencimentos. Esse método demandava tempo significativo para manutenção, além de estar sujeito a erros de preenchimento, cálculos incorretos de vencimento e inconsistências nas informações.', N'Desenvolver uma ferramenta que automatize o acompanhamento dos treinamentos da equipe, permitindo melhor gestão dos vencimentos, maior confiabilidade das informações e visibilidade gerencial sobre a situação dos treinamentos obrigatórios dos colaboradores.', N'10024', N'01 - Imagens/01 - Antes/11865.jpeg', N'Antes da melhoria, o controle dos treinamentos era realizado por meio de planilhas Excel mantidas manualmente. A atualização dependia da conferência das informações, lançamento manual das datas de conclusão e cálculo dos vencimentos dos treinamentos. Esse processo consumia tempo administrativo, dificultava o acompanhamento das pendências e aumentava o risco de erros humanos na gestão das capacitações da equipe.', N'01 - Imagens/02 - Depois/11865.jpeg', N'Foi desenvolvido um dashboard em Power BI para gestão dos treinamentos da equipe. A solução automatiza o cálculo dos vencimentos, organiza as informações dos colaboradores em uma única interface e disponibiliza indicadores visuais sobre treinamentos vencidos, próximos ao vencimento e situação individual de cada colaborador. O dashboard também apresenta cronogramas de vencimento, visão consolidada da equipe e detalhamento dos treinamentos obrigatórios, permitindo acompanhamento mais eficiente e apoio à tomada de decisão da coordenação.', N'https://app.powerbi.com/groups/me/apps/b4139931-2fbb-4202-b590-6beb2c32cfdc/reports/949be163-1ec7-4c46-8b22-c7607e81c20b/cc2dc89fd3b6e5c3ac84?ctid=7893571b-6c2c-4cef-b4da-7d4b266a0626&language=pt-BR&experience=power-bi', N'A implementação do dashboard substituiu um processo predominantemente manual por uma solução visual, padronizada e confiável, proporcionando melhor controle dos treinamentos, acompanhamento dos vencimentos e aumento da eficiência na gestão das capacitações da equipe.', N'A utilização de indicadores visuais e cálculos automatizados simplifica significativamente a gestão dos treinamentos, melhora a qualidade das informações e reduz atividades administrativas que não agregam valor ao processo.', 0, NULL, N'Aumentar a eficiência do acompanhamento das paradas por meio de informações claras, padronizadas e de fácil consulta.', '2026-08-21T00:00:00.000', '2026-08-24T09:29:30.000', N'92000576', NULL, NULL);
INSERT INTO #PVC VALUES (11866, N'478997', N'478997', N'Fator de HH previsto adicionado às projeções de custo M+1, M+2, M+3', 1, N'Others/Outros', N'A projeção dos custos de material de aplicação da frota de Infra é realizada mensalmente, só contemplava o valor total das ordens a faturar. Como se trata de um fluxo cíclico (mensal), foi inserido o valor de HH previsto para execução das ordens e dos planos de preventiva, não podendo exceder 60% da capacidade total da equipe de execução.
INSERT INTO #PVC VALUES (11867, N'81063758', N'81063758', N'Redução Frequência de Partidas - Correia Longa distância TR-0320-04', 1, N'Others/Outros', N'Dificuldade de retomada do transportador após interrupções do processo. | Aumento da indisponibilidade do equipamento. | Em setembro de 2025 ocorreu um acidente de potencial moderado (N4). | Redução da cadência produtiva das plantas.', N'Redução / eliminação eventos de sobrecarga na correia de longa distância TR-0320-04', N'10297', N'01 - Imagens/01 - Antes/11867.jpeg', N'No último mês, as plantas de Secagem 01 e 02 registraram 26 e 27 horas de indisponibilidade, respectivamente, ocasionado pela TR-0320-04 afetando a cadência de produção e gerando perdas estimadas em 10.000 toneladas de minério secado.
INSERT INTO #PVC VALUES (11868, N'1015842', N'1015842', N'VNL EBITDA Model Recreation', 1, N'Others/Outros', N'Prior NA model for EBITDA forecast and Budget calculations was extremely complex and relied on numerous unlink data that could not be analyzed and was difficult to update and trouble shoot. It consisted of 25-30 separately linked files that open looped back and fourth into each other
INSERT INTO #PVC VALUES (11869, N'515949', N'515949', N'SEGREGAÇÃO MANTO PRIMÁRIO', 1, N'No Replication/Sem replicação', N'OS REVESTIMENTOS DOS CÔNCAVOS BRITADOR PRIMÁRIO ERA SEGREGADO POR CAMINHÃO GUINDALTO MUNCK, ONDE EMPREGADO FICAVA EXPOSTO MOVIMENTAÇÃO CRÍTICA DE IÇAMENTO, PRENSAMENTO, COLISÃO, RISCO QUEDA MATERIAL, CUJO ATIVIDADE ACONTECIA COM 8 h DE DURAÇÃO PARA DESCARTE NO  CMD.', N'DIMINUIR EXPOSIÇÃO COLABORADORES', N'10178', N'01 - Imagens/01 - Antes/11869.jpeg', N'OS REVESTIMENTOS DOS CÔNCAVOS BRITADOR PRIMÁRIO ERA SEGREGADO POR CAMINHÃO GUINDALTO MUNCK, ONDE EMPREGADO FICAVA EXPOSTO MOVIMENTAÇÃO CRÍTICA DE IÇAMENTO, PRENSAMENTO, COLISÃO, RISCO QUEDA MATERIAL, CUJO ATIVIDADE ACONTECIA COM 8 h DE DURAÇÃO PARA DESCARTE NO  CMD.', N'01 - Imagens/02 - Depois/11869.jpeg', N'FOI IMPLANTADO COM PARCERIA TIME CMD/ITAUCON APOIO COM CAMINHÃO GARRA E CARRETA NO PROCESSO DE COLETA EM ÁREA PARA SEGREGAÇÃO DOS REVESTIMENTOS DOS CÔNCAVOS, ELIMANANDO RISCO DE EXPOSIÇÃO DOS COLABORADORES, REDUÇÃO TEMPO ATIVIDADE DE 8H PARA 1 HORA, PROPORCIONANDO AMBIENTE MAIS LIMPO E SEGURO NAS ATIVIDADES.', NULL, N'SIM', N'MOVIMENTAÇÃO SEGURA', 0, NULL, N'Com a implementação do dispositivo hidráulico para montagem de rolamentos do VT, espera-se obter os seguintes resultados:
INSERT INTO #PVC VALUES (11870, N'478997', N'478997', N'Estratégia de controle via campo revisão das ordens Infra - indicador ordem vencida', 1, N'Others/Outros', N'Baixa rastreabilidade e visibilidade das ações macro referente às ordens vencidas em sistema SAP.', N'Reduzir % ordens vencidas, meta diretoria - 5%', N'10023', N'01 - Imagens/01 - Antes/11870.jpeg', N'Baixa rastreabilidade da efetividade de planejamento.', N'01 - Imagens/02 - Depois/11870.jpeg', N'Ordens classificadas via campo revisão mensalmente, referente a aderência de custos e entrada no horizonte de planejamento.', NULL, N'Não. Em andamento.', N'Planejamento, rastreabilidade', 0, NULL, NULL, '2026-06-30T00:00:00.000', '2026-08-24T12:41:12.000', N'478997', NULL, NULL);
INSERT INTO #PVC VALUES (11871, N'515949', N'515949', N'SEGREGAÇÃO MANTO PRIMÁRIO SEGURO', 1, N'No Replication/Sem replicação', N'Os revestimento Britadores Primários era acumulado em área devido falta de espaço físico no CMD ocasionando acúmulo e limitação para colaboradores trabalhar com segurança em área.', N'Redução de Resíduos em área', N'10178', N'01 - Imagens/01 - Antes/11871.jpeg', N'Os revestimento Britadores Primários era acumulado em área devido falta de espaço físico no CMD ocasionando acúmulo e limitação para colaboradores trabalhar com segurança em área.risco de colisão, inexistência de 5S no local.', N'01 - Imagens/02 - Depois/11871.jpeg', N'Foi implantado com apoio time cmd/itaucon a coleta dos revestimentos dos Mantos Britadores Primários em área, garantindo uma movimentação segura, eliminando a exposição de   3 colaboradores  para 01 garantindo 5 S na área.', NULL, N'sim', N'Segregação segura', 0, NULL, N'Segurança no funcionamento do sistema de combate a incêndio de toda a área de salobo 3', '2026-08-14T00:00:00.000', '2026-08-24T12:45:39.000', N'515949', NULL, NULL);
INSERT INTO #PVC VALUES (11872, N'515949', N'515949', N'Segregação segura manto Britador secundário', NULL, N'No Replication/Sem replicação', N'O manto Britador secundário, realizava o cortante para redução do revestimento para segregação em área, o serviço colocava em exposição colaboradores com serviço caldeiraria de corte, tempo estimado de 4 h de serviço, exposição e prensamento de membros.', N'Segurança e transporte', N'10178', N'01 - Imagens/01 - Antes/11872.jpeg', N'O manto Britador secundário, realizava o cortante para redução do revestimento para segregação em área, o serviço colocava em exposição colaboradores com serviço caldeiraria de corte, tempo estimado de 4 h de serviço, exposição e prensamento de membros.', N'01 - Imagens/02 - Depois/11872.jpeg', N'Foi implantado em parceria com time cmd a coleta do revestimento completo sem aplicação serviço de corte, reduzindo tempo de segregação, exposição empregados, melhoria no 5 S da área.', NULL, N'sim', N'Redução exposição empregados', 0, NULL, N'Eliminar a necessidade de andaime e trabalho em altura para manutenção na valvula .', '2026-08-12T00:00:00.000', '2026-08-24T12:55:51.000', N'515949', NULL, NULL);
INSERT INTO #PVC VALUES (11873, N'478997', N'478997', N'Modelo de projeção de custo variável (FPS) da frota de Infra baseado no D90 (DF/UF)', 1, N'Others/Outros', N'Gestores e analistas da execução não tinham previsibilidade dos custos variáveis a ser executados na frota Infra. ', N'Previsibilidade consumo FPS Infra.', N'10023', N'01 - Imagens/01 - Antes/11873.jpeg', N'Projeção de consumo varíavel (FPS) baseado em média.', N'01 - Imagens/02 - Depois/11873.jpeg', N'Previsibilidade dos custos variáveis da frota de maneira mais assertiva, baseado em dados de histórico recente X performance operacional das frotas, considerando entrada e saida de equipamentos e manutenções relevantes.', NULL, N'Sim. Previsibilidade do consumo.', N'Planejamento', 0, NULL, NULL, '2026-07-31T00:00:00.000', '2026-08-24T13:18:35.000', N'478997', NULL, NULL);
INSERT INTO #PVC VALUES (11874, N'478997', N'478997', N'Análise de tempo ocioso frota D10, sugestão de hibernação baseada em dados de telemetria', 1, N'Others/Outros', N'Frota D10 apresenta baixa utilização e alto grau de ociosidade, realizado trabalho de engenharia e apresentado para manutenção/operação possibilidade de redução de 2 tratores, absorvendo as atividades para outros tratores, D11. Redução 2,5M.', N'Redução de custos', N'10023', N'01 - Imagens/01 - Antes/11874.jpeg', N'Frota D10 apresenta baixa utilização e alto grau de ociosidade, correspondendo a boa parcela do orçamento até Dez/26 na frota de Infra.', N'01 - Imagens/02 - Depois/11874.jpeg', N'Possibilidade de absorção da carga de trabalho dos D10, utilizando dos tratores D11 novos, que também apresentam nível alto de ociosidade.', NULL, N'Não. Em andamento, análise pela equipe de planejamento de mina.', N'Visão macro do processo operação/manutenção.', 2000000, 1, N'Outcome achieved ', '2026-07-31T00:00:00.000', '2026-08-24T13:34:21.000', N'478997', NULL, NULL);
INSERT INTO #PVC VALUES (11875, N'478997', N'478997', N'Ajuste dos planos de ultrassom da frota transporte, realização em paralelo da PM', 1, N'Others/Outros', N'Planos de ultrassom de fixações e articulações específicas da frota transporte sendo realizada fora da PM, gerando paradas em duplicidade.', N'Otimização de paradas', N'10023', N'01 - Imagens/01 - Antes/11875.jpeg', N'Planos realizados fora da PM.', N'01 - Imagens/02 - Depois/11875.jpeg', N'Planos realizados em conjunto da PM, a cada 1500 horas.', NULL, N'Não. Em andamento.', N'Otimização', 0, NULL, N'Tempo reduzido na manutenção da correa e redução de risco de acidentes. ', '2026-08-24T00:00:00.000', '2026-08-24T14:03:43.000', N'478997', NULL, NULL);
INSERT INTO #PVC VALUES (11876, N'81029873', N'81006344', N'Suporte de fabricação de peças', 1, N'Others/Outros', N'Desperdício de tempo e material na usinagem das buchas do SAG.', N'Meta é melhorar o processo de produção e otimizar tempo.', N'10245', N'01 - Imagens/01 - Antes/11876.jpeg', N'Inicialmente, a ausência de um gabarito adequado fazia com que a usinagem de uma única bucha do SAG na fresa consumisse todo o turno, além de gerar desperdício de material e um acabamento abaixo do esperado. Posteriormente, foi desenvolvido um gabarito para utilização na serra-fita, proporcionando ganhos no processo. Com essa melhoria, a produção passou de uma para duas buchas por turno, aumentando a produtividade e reduzindo perdas.', N'01 - Imagens/02 - Depois/11876.jpeg', N'Com a melhoria do segundo gabarito melhoramos o tempo de fabricação, redução do desperdício de material, aumento na qualidade de acabamento e quantidade de peças fabricadas por dia no torno mecânico. Saímos de apenas uma peça turno para doze peças por tuno.
INSERT INTO #PVC VALUES (11877, N'524616', N'524616', N'Monitoramento online do PTO da PZ02.', 2, N'Others/Outros', N'Evitar a exposição de pessoas aos riscos durante a realização presencial das coletas de vibração no componente.', N'Retirar pessoas da exposição do risco ao realizar a coleta no  equipamento', N'10024', N'01 - Imagens/01 - Antes/11877.jpeg', N'A coleta de vibração era realizada manualmente por meio de um sensor portátil, aplicado diretamente nos pontos de medição dos componentes. Para executar a atividade, o técnico precisava acessar fisicamente o equipamento em operação, posicionar o sensor em cada ponto de coleta e aguardar a aquisição individual dos dados. Esse processo exigia exposição à área operacional, aumentava o tempo de inspeção e demandava deslocamentos frequentes entre os pontos monitorados, elevando a exposição aos riscos e reduzindo a eficiência da atividade.', N'01 - Imagens/02 - Depois/11877.jpeg', N'Foi implantado um sistema de monitoramento online por meio de sensores fixos, permitindo o acompanhamento contínuo e em tempo real das condições dos componentes. Essa solução reduziu significativamente a necessidade de coletas manuais em campo, minimizando a exposição dos profissionais aos riscos operacionais, aumentando a confiabilidade das informações e proporcionando maior agilidade na identificação de anomalias e na tomada de decisões para manutenção.', NULL, N'Sim, conseguimos eliminar a necessidade de exposição dos profissionais à linha de fogo durante as atividades de monitoramento, reduzindo os riscos operacionais e aumentando a eficiência na detecção de falhas dos equipamentos.', N'Através do monitoramento online, conseguimos aumentar a segurança das atividades, reduzindo a necessidade de intervenções em campo e a exposição dos profissionais aos riscos operacionais, além de proporcionar maior eficiência no processo de coleta e análise dos dados.', 0, NULL, N'Garantir a rápida identificação dos brigadistas, promovendo maior agilidade, organização e segurança no atendimento às emergências.', '2026-08-21T00:00:00.000', '2026-08-24T14:48:44.000', N'524616', NULL, NULL);
INSERT INTO #PVC VALUES (11878, N'81012522', N'81013737', N'Report Cronograma Parada Manutenção Equipamentos de Mina', 1, N'Others/Outros', N'Informações do cronograma de paradas pouco claras, dificultando o acompanhamento das atividades.', N'Apresentar de forma clara e objetiva o andamento das atividades do cronograma de paradas programadas dos equipamentos de mina', N'10119', N'01 - Imagens/01 - Antes/11878.jpeg', N'Informações do cronograma de paradas pouco claras, dificultando o acompanhamento das atividades. Vários slides', N'01 - Imagens/02 - Depois/11878.jpeg', N'Informações do cronograma apresentadas de forma clara e objetiva, facilitando o acompanhamento das atividades.', NULL, N'O problema de falta de clareza nas informações foi eliminado por meio da padronização e organização do cronograma, facilitando o acompanhamento das paradas programadas.', N'A apresentação clara e padronizada das informações do cronograma melhorou o acompanhamento das paradas, a comunicação entre as áreas e a tomada de decisão.', 0, NULL, N'Personnel can now reference the sheet to get a picture of the water flow and whether or not certain sumps are being locked out because of full sumps upstream.', '2026-08-21T00:00:00.000', '2026-08-24T15:03:03.000', N'81012522', NULL, NULL);
INSERT INTO #PVC VALUES (11879, N'81012522', N'81013737', N'Implementação de BI para Gestão da Carteira de Laudos', NULL, N'Others/Outros', N'As informações da carteira de laudos eram consultadas de forma manual no sistema levando muito tempo para consulta', N'Disponibilizar informações da carteira de laudos em um painel BI de forma clara, centralizada e atualizada, facilitando o acompanhamento e a tomada de decisão.', N'10119', N'01 - Imagens/01 - Antes/11879.jpeg', N'Ausência de padronização das informações da carteira de laudos entre as frotas.', N'01 - Imagens/02 - Depois/11879.jpeg', N'Informações consolidadas em BI, com visualização clara dos status, prazos e indicadores da carteira de laudos.', NULL, N'As informações passaram a ser padronizadas entre as frotas, proporcionando maior confiabilidade e facilidade na análise da carteira de laudos.', N'A centralização e padronização das informações em BI melhora a gestão da carteira, agiliza as análises e apoia a tomada de decisão.', 0, NULL, N'Redução do tempo de recebimento e movimentação de materiais, diminuição das manobras realizadas pela empilhadeira, melhor aproveitamento da área de descarga e armazenamento, aumento da produtividade operacional e otimização do fluxo logístico da área.', '2026-08-21T00:00:00.000', '2026-08-24T16:15:01.000', N'81012522', NULL, NULL);
INSERT INTO #PVC VALUES (11880, N'81016620', N'81038833', N'Coriolis', 1, N'Others/Outros', N'Ocorrências de falhas recorrentes devido  projeção 
INSERT INTO #PVC VALUES (11881, N'81012522', N'81013737', N'Divulgação do cronograma em modelo A0 para acompanhamento troca de turno', 1, N'Others/Outros', N'As informações do cronograma não estavam disponíveis de forma visual e padronizada para consulta durante as trocas de turno, dificultando o alinhamento das equipes.', N'Disponibilizar o cronograma de paradas em formato A0, de forma clara e visual, para melhorar a comunicação e o acompanhamento das atividades durante as trocas de turno.', N'10119', N'01 - Imagens/01 - Antes/11881.jpeg', N'Cronograma divulgado de forma limitada, dificultando o acompanhamento das atividades durante a troca de turno.', N'01 - Imagens/02 - Depois/11881.jpeg', N'Cronograma disponibilizado em modelo A0, proporcionando maior visibilidade e alinhamento entre as equipes.', NULL, N'A divulgação do cronograma em modelo A0 proporcionou maior visibilidade das informações, melhor alinhamento entre as equipes e acompanhamento mais eficiente das paradas programadas.', N'A disponibilização de informações em formato visual e de fácil acesso contribui para uma comunicação mais eficaz, maior engajamento das equipes e melhor controle das atividades.', 0, NULL, N'Maior segurança e confiança dos usuários ao utilizar a escada.
INSERT INTO #PVC VALUES (11882, N'81061558', N'81061558', N'montagem de rolamento do VT', 2, N'Concentration/Concentração', N'Atualmente, durante a substituição dos rolamentos do VT, a montagem é realizada por meio de impactos com marreta diretamente sobre o rolamento. Esse método pode causar danos aos elementos rolantes, pistas e vedações, reduzindo a vida útil do componente e aumentando o risco de falhas prematuras. Além disso, a atividade exige maior esforço físico dos executantes, aumenta o tempo de manutenção e apresenta riscos relacionados à segurança e à qualidade da montagem.', N'Implementar um método adequado para montagem de rolamentos no VT, eliminando a necessidade de impactos com marreta e garantindo uma instalação segura, padronizada e tecnicamente correta', N'10301', N'01 - Imagens/01 - Antes/11882.jpeg', N'Antes da implementação da melhoria, a montagem dos rolamentos do VT era realizada por meio de impactos diretos com marreta. Esse método apresentava diversos problemas operacionais e de manutenção, tais como:
INSERT INTO #PVC VALUES (11883, N'485595', N'485595', N'Redução de custo com filtro tela do conversor de torque', 1, N'Others/Outros', N'Elevado custo com substituição dos filtros telas dos conversores de torque e respiro do tanque da direção', N'Reduzir pela metade o custo com filtro tela e respiro da direção', N'10081', N'01 - Imagens/01 - Antes/11883.jpeg', N'Elevado custo com filtros telas dos conversores de torque e respiro da direção que eram substituídos a cada 500h.', N'01 - Imagens/02 - Depois/11883.jpeg', N'Com a nova estratégia, o filtro tela do conversor e o respiro do tanque da direção, serão substituídos a cada 1000 horas', NULL, N'A redução de custa é imediata. Os itens foram alterados de 500h para 1000 h. Estimando uma redução de R$ 179.964,05 no ano.', N'Sempre há oportunidade de redução de custo', 179964, 1, N'Redução de deslocamentos para coleta manual.
INSERT INTO #PVC VALUES (11884, N'81058068', N'81058068', N'Desenvolvimento ponto de abastecimento de água bruta com pipa nos TQ5102SA-01/02', 2, N'Others/Outros', N'Os níveis do tanque de água bruta da ETEBR estavam baixo, em nível critico, com isso não estava conseguindo manter os níveis de água nos tanques do sistema de combate a incêndio em Salobo 3, desta forma, foi soldado uma conexão no dreno do tanque, permitindo transferência de agua para o tanque com o pipa.', N'Garantir o nível de água dos tanques em 100% garatindo o funcionamento do sistema de combate a incêndio em caso de sinistro na área', N'10033', N'01 - Imagens/01 - Antes/11884.jpeg', N'Tanques do sistema de combate a incêndio de Salobo 3, em níveis críticos, comprometendo a segurança das operações em caso de sinistro na área operacional, havendo necessidade de uso do sistema.', N'01 - Imagens/02 - Depois/11884.jpeg', N'Desenvolvido um ponto de conexão no dreno do tanque, permitindo que o tanque seja abastecido por pipa, garantindo a funcionalidade do sistema e a segurança nas operações.', NULL, N'sim', N'Elevação da segurança no sistema de SPCI em Salobo 3', 0, NULL, N'Redução de deslocamentos para coleta manual.
INSERT INTO #PVC VALUES (11885, N'81049566', N'81017006', N'Bancada válvula de adição de agua bolas 02', 2, N'Concentration/Concentração', N'Durante manobra de válvulas e manutenção era necessário a montagem de andaime  para manutenção na valvula de adição de agua do moinho de bolas MO02.', N'eliminar a necessidade de andaime e trablho em altura', N'#N/A', N'01 - Imagens/01 - Antes/11885.jpeg', N'Necessário montagem de andaime e trabalho em altura para manutenção e abertura da válvula de adição de agua do moinho 2251MO02', N'01 - Imagens/02 - Depois/11885.jpeg', N'Fabricado bancada para manutenção e ajuste na válvula sem a necessidade de andaime e trabalho em altura.', NULL, N'Atividade pode ser realizada da plataforma, sem a necessidade de montagem de andaime. ', N'Eliminado a necessidade de andaime.', 0, NULL, N'Redução de deslocamentos para coleta manual.
INSERT INTO #PVC VALUES (11886, N'81057178', N'81057178', N'Redução de Indisponibilidade do Gateway do piso zero (BPs_2014) por Meio da Proteção do Painel Elétrico e Readequação do Cabeamento ', 1, N'Others/Outros', N'A gateway de monitoramento remoto das BP_2014 apresentava frequentes perdas de comunicação, permanecendo em estado offline devido à exposição do painel de alimentação à água e ao acúmulo de resíduos gerados pelas atividades de limpeza dos pisos superiores, além da vulnerabilidade do cabeamento, que se encontrava exposto e sujeito a rompimentos durante a operação de equipamentos de limpeza. Esse problema impactava diretamente a confiabilidade do sistema de monitoramento remoto, comprometendo a coleta e transmissão de dados dos ativos monitorados, além de gerar intervenções corretivas recorrentes e aumento dos custos de manutenção. A situação foi identificada por meio do monitoramento da disponibilidade do gateway e de inspeções em campo, que constataram a presença de água e sujeira interna e externa do painel, bem como danos frequentes à fiação decorrentes da falta de proteção adequada.', N'Garantir a disponibilidade e a confiabilidade do gateway de monitoramento remoto das bp_2014 por meio da proteção do painel de alimentação contra exposição à água e resíduos, bem como da adequação e proteção mecânica do cabeamento, eliminando falhas recorrentes de comunicação, reduzindo intervenções corretivas e assegurando a continuidade da transmissão de dados para o sistema de monitoramento remoto.', N'10261', N'01 - Imagens/01 - Antes/11886.jpeg', N'O painel de alimentação do gateway de monitoramento remoto das BPs_2014, localizado no piso zero, apresentava acúmulo frequente de água e resíduos sólidos sobre sua estrutura interna e externa devido às atividades de limpeza realizadas nos pisos superiores. Além disso, o cabeamento de alimentação e comunicação encontrava-se exposto, sofrendo constantes danos durante a operação de equipamentos de limpeza, como o Bobcat.
INSERT INTO #PVC VALUES (11887, N'1008360', N'81039898', N'Plate Under Ball Mill Feed Belt Head Chute ', 3, N'Others/Outros', N'Under the BM feed belt head chute its open grating so when spillage occurs it falls to the lower level. Making it a bigger mess to clean. ', N'Stop spillage from reaching lower levels ', N'0', N'01 - Imagens/01 - Antes/11887.jpeg', N'Under the BM feed belt head chute its open grating so when spillage occurs it falls to the lower level. Making it a bigger mess to clean. ', N'01 - Imagens/02 - Depois/11887.jpeg', N'Now with a plate installed it makes the spillage stay on one level making it easier and quicker to shovel/clean up ', NULL, N'Yes', N'Cleaning one area is easier than two ', 0, NULL, N'os dados chegam automaticamente à plataforma por meio dos Gateways, permitindo monitoramento contínuo, mais segurança para as equipes e decisões mais rápidas e assertivas para a manutenção.', '2026-08-23T00:00:00.000', '2026-08-24T19:23:23.000', N'1008360', NULL, NULL);
INSERT INTO #PVC VALUES (11888, N'521673', N'521673', N'Proteção móvel', 2, N'No Replication/Sem replicação', N'A proteção da correia da estufa era fixada por solda, exigindo o corte da solda para acesso aos componentes durante a manutenção e a realização de nova soldagem após a conclusão do serviço, aumentando o tempo de intervenção.', N'Evitar trabalho excessivo e acidentes', N'10032', N'01 - Imagens/01 - Antes/11888.jpeg', N'Anteriormente, a proteção da correia da estufa era fixada por solda, sendo necessário realizar o corte da solda para sua remoção, executar a manutenção e posteriormente efetuar uma nova soldagem para reinstalação. Esse processo aumentava o tempo de intervenção e expunha os colaboradores a riscos adicionais, como projeção de partículas, queimaduras, cortes, exposição a fumos de solda e acidentes durante a execução dos trabalhos a quente.', N'01 - Imagens/02 - Depois/11888.jpeg', N'Foi implementada uma melhoria na proteção da correia da estufa, que deixou de ser fixada por solda e passou a ser fixada por parafusos e porcas. Com essa alteração, a proteção pode ser removida e reinstalada de forma rápida e segura, eliminando a necessidade de corte e nova soldagem durante as intervenções de manutenção. A melhoria reduziu o tempo de execução da atividade, aumentou a disponibilidade do equipamento e minimizou os riscos ocupacionais associados aos trabalhos a quente, como queimaduras, projeção de partículas, cortes e exposição a fumos de solda, proporcionando maior segurança aos colaboradores.', NULL, N'Sim, o problema foi resolvido. Proteção fixada por parafusos e porcas, permitindo remoção rápida e segura, reduzindo o tempo de manutenção e aumentando a segurança da atividade.', N'Segurança e gestão de tempo andam juntas', 0, NULL, N'Redução de deslocamentos para coleta manual.
INSERT INTO #PVC VALUES (11889, N'81046574', N'81046574', N'Visão Simplificada do D+90', 1, N'Others/Outros', N'Durante o período do by-pass haverá uma mudança de cenário sobre as paradas da usina, na qual há tanto paradas de GP26 e paradas de singelo com intuito garantir o máximo de confiabilidade na planta. Com isso, para facilitar a visão dos gestores e do time de planejamento foi elaborado uma visão simplificada do mapa que foi impresso e entregue a cada time.', N'Trazer visão gerencial sobre o mapa de paradas de 2026', N'10081', N'01 - Imagens/01 - Antes/11889.jpeg', N'Visão Anterior do Mapa em Excel que gerava dificuldade de visualização.', N'01 - Imagens/02 - Depois/11889.jpeg', N'Visão simplificada trazendo uma visão simples e de rápido visualização.', NULL, N'Sim', N'Simplificação de dados', 0, NULL, N'Redução de deslocamentos para coleta manual.
INSERT INTO #PVC VALUES (11890, N'81060533', N'504475', N'BRIGADA IDENTIFICADA, SEGURANÇA REFORÇADA', 2, N'Others/Outros', N'Dificuldade na identificação imediata dos brigadistas durante as atividades e situações de emergência, podendo comprometer a agilidade na resposta.', N'Garantir a rápida identificação dos brigadistas, aumentando a agilidade e segurança durante situações de emergência.', N'10361', N'01 - Imagens/01 - Antes/11890.jpeg', N'Os brigadistas não possuíam identificação visual padronizada, dificultando seu reconhecimento rápido pelos colaboradores durante as atividades e situações de emergência.', N'01 - Imagens/02 - Depois/11890.jpeg', N'Brigadistas passaram a utilizar abraçadeiras de identificação, facilitando o reconhecimento imediato e proporcionando mais agilidade, organização e segurança nas situações de emergência.', NULL, N'A meta foi atingida, pois a identificação visual dos brigadistas foi implementada, facilitando seu reconhecimento e aumentando a agilidade e segurança nas situações de emergência.', N'A identificação visual facilita a localização dos brigadistas. Pequenas melhorias podem aumentar a segurança e agilidade nas emergências. A atuação da brigada depende do reconhecimento e apoio de toda a equipe.', 0, NULL, N'os dados chegam automaticamente à plataforma por meio dos Gateways, permitindo monitoramento contínuo, mais segurança para as equipes e decisões mais rápidas e assertivas para a manutenção.', '2026-08-17T00:00:00.000', '2026-08-25T09:33:19.000', N'81060533', NULL, NULL);
INSERT INTO #PVC VALUES (11891, N'81025074', N'81025074', N'Underground Pumping Flow Chart', 1, N'Underground/Subterrâneo', N'An easy to read, physical graphic was needed for operations personnel to show how the underground sumps link together and how certain sumps affect others when they are full.
INSERT INTO #PVC VALUES (11892, N'81061558', N'81061558', N'Remoção de proteção frontal para facilitar recebimento e movimentação de materiais com empilhadeira', 1, N'Concentration/Concentração', N'Durante o recebimento de materiais, as proteções instaladas na frente da área de armazenamento dificultavam o acesso e posicionamento da empilhadeira, exigindo manobras adicionais e aumentando o tempo de descarga. Com a remoção dessas proteções, foi criado um acesso mais direto para deposição dos materiais, tornando o processo mais ágil e seguro para a operação logística.', N'Melhorar a logística de recebimento de materiais, reduzindo o tempo de movimentação e facilitando o acesso da empilhadeira à área de descarga, aumentando a eficiência operacional e reduzindo manobras.', N'10301', N'01 - Imagens/01 - Antes/11892.jpeg', N'área de recebimento de materiais possuía proteções/guarda-corpos frontais que dificultavam o acesso da empilhadeira para descarga e posicionamento das cargas. Essa condição exigia manobras adicionais, aumentava o tempo de movimentação dos materiais e dificultava o aproveitamento do espaço disponível para armazenamento temporário. Como consequência, o processo de recebimento apresentava menor eficiência operacional e maior esforço para os operadores.
INSERT INTO #PVC VALUES (11893, N'81061558', N'521769', N'Substituição de válvula por modelo mais robusto e resistente à contaminação', 1, N'Others/Outros', N'A válvula instalada apresentava falhas frequentes devido ao acúmulo de sujeira e partículas presentes no processo. Essa condição causava travamentos, comprometia o desempenho do sistema e gerava paradas para manutenção corretiva.', N'Aumentar a confiabilidade do equipamento, reduzindo falhas causadas pelo acúmulo de sujeira e minimizando intervenções de manutenção.', N'10301', N'01 - Imagens/01 - Antes/11893.jpeg', N'A válvula instalada era sensível à presença de sujeira no processo, ocasionando falhas operacionais, travamentos e necessidade de intervenções frequentes para limpeza e manutenção. Essa condição impactava a confiabilidade do equipamento e aumentava o tempo de indisponibilidade.', N'01 - Imagens/02 - Depois/11893.jpeg', N'Foi realizada a substituição da válvula existente por um modelo mais robusto e adequado às condições do processo, com maior resistência à presença de sujeira e partículas. A melhoria aumentou a confiabilidade operacional, reduziu a necessidade de manutenção corretiva e minimizou o risco de falhas e interrupções do sistema.', NULL, N'SIM. O problema foi resolvido com a substituição da válvula por um modelo mais adequado às condições do processo e menos suscetível ao acúmulo de sujeira. Após a implementação, houve aumento da confiabilidade operacional, redução das falhas recorrentes e diminuição das intervenções de manutenção corretiva, atendendo ao objetivo proposto.', N'A seleção adequada dos componentes de acordo com as condições do processo é fundamental para garantir a confiabilidade operacional. A substituição da válvula por um modelo mais resistente à presença de sujeira reduziu falhas, aumentou a disponibilidade do equipamento e diminuiu a necessidade de intervenções de manutenção.', 0, NULL, N'Redução de deslocamentos para coleta manual.
INSERT INTO #PVC VALUES (11894, N'520046', N'520046', N'Escada de acesso ao banheiro químico do lavador', 2, N'Others/Outros', N'A escada de acesso ao banheiro químico do lavador não possuía corrimão nem proteção nos vãos entre os degraus, criando uma condição insegura e aumentando o risco de escorregões, quedas e lesões. A necessidade de melhoria foi identificada após um incidente envolvendo uma colaboradora da empresa Hidralpress, que escorregou ao utilizar a escada, evidenciando a necessidade de adequação do acesso.', N'Meta: Adequar a escada às condições seguras de uso.  Objetivo: Reduzir o risco de quedas e acidentes, proporcionando mais segurança e estabilidade aos empregados por meio da instalação de corrimão e tela de proteção.', N'10139', N'01 - Imagens/01 - Antes/11894.jpeg', N'A escada de acesso ao banheiro químico não possuía corrimão nem proteção entre os degraus, aumentando o risco de escorregões e quedas. A condição foi evidenciada após um incidente com uma colaboradora.', N'01 - Imagens/02 - Depois/11894.jpeg', N'Foram instalados corrimão e proteção nos vãos da escada, padronizando o acesso conforme requisitos de segurança. A melhoria reduziu o risco de quedas e aumentou a segurança dos usuários.', NULL, N' O problema foi resolvido porque foram instalados corrimão e proteção nos vãos entre os degraus, eliminando as principais condições inseguras identificadas. Com a melhoria, os usuários passaram a contar com apoio durante a subida e descida, além da proteção contra possíveis escorregões e quedas, tornando o acesso ao banheiro químico mais seguro e adequado aos padrões de segurança da área.', N'Identificar e corrigir condições inseguras antes da ocorrência de acidentes. Realizar inspeções periódicas nos acessos e estruturas utilizadas pelos trabalhadores. Priorizar a instalação de dispositivos de proteção, como corrimãos e guarda-corpos. Valorizar o relato e a investigação de incidentes como oportunidade de melhoria. Reforçar a cultura de prevenção, garantindo ambientes de trabalho mais seguros para todos.', 0, NULL, N'Coleta automática e contínua dos dados.
INSERT INTO #PVC VALUES (11895, N'81061558', N'521769', N'Confecção de base para transporte seguro de bomba reserva', 3, N'Others/Outros', N'As bombas eram armazenadas e movimentadas sem uma base adequada, dificultando o transporte e o manuseio durante as atividades de manutenção. Essa condição aumentava o risco de quedas, danos ao equipamento e maior esforço operacional durante a movimentação.', N'Facilitar o transporte, armazenamento e manuseio da bomba, garantindo maior segurança, estabilidade e preservação do equipamento.', N'10301', N'01 - Imagens/01 - Antes/11895.jpeg', N'A bomba era armazenada e transportada sem uma base adequada de apoio, permanecendo apoiada diretamente sobre pallets ou superfícies improvisadas. Essa condição dificultava a movimentação do equipamento, aumentava o risco de tombamento, danos mecânicos e exigia maior esforço da equipe durante o manuseio e transporte.', N'01 - Imagens/02 - Depois/11895.jpeg', N'Foi confeccionada uma base metálica específica para transporte e armazenamento da bomba, proporcionando maior estabilidade e segurança durante a movimentação. A melhoria facilitou o manuseio do equipamento, reduziu riscos de danos, padronizou o armazenamento e aumentou a segurança das atividades de manutenção.', NULL, N'SIM. O problema foi resolvido com a fabricação de uma base exclusiva para a bomba, proporcionando maior estabilidade durante o transporte e armazenamento, reduzindo os riscos de danos ao equipamento e facilitando o manuseio pela equipe.', N'O desenvolvimento de dispositivos simples e adequados para movimentação e armazenamento contribui para a preservação dos equipamentos, redução de riscos operacionais e aumento da eficiência das atividades de manutenção.', 0, NULL, N'Coleta automática e contínua dos dados.
