INSERT INTO #PVC VALUES (11931, N'81020607', N'516988', N'Suporte para o motor do trator de esteira', 2, N'Others/Outros', N'Ausência de dispositivo adequado para acondicionamento e apoio seguro do motor durante a manutenção;
INSERT INTO #PVC VALUES (11932, N'502383', N'81015670', N'SUPORTE PARA GAS', 1, N'Open Pit/Poço aberto', N'Transporte irregular do gás, RISCO DE DANOS MATERIAS.', N'ELIMINAR CONDIÇÃO INSEGURA NO TRANSPORTE DE GÁS ', N'0', N'01 - Imagens/01 - Antes/11932.jpeg', N'Transporte irregular de gás, risco de perda material, risco de incidentes pessoal.', N'01 - Imagens/02 - Depois/11932.jpeg', N'Transporte correto do gás por suporte com trava de segurança para translado correto, redução do risco de perda material. ', NULL, N'Foi minimizado os riscos de perda material e incidentes pessoais', N'Redução riscos de perda material', 0, NULL, N'com essa melhoria agilizamos o processo de lubrificação', '2026-08-15T00:00:00.000', '2026-08-26T08:10:08.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (11933, N'502383', N'502383', N'PROTEÇÃO PINHÃO DE GIRO', 2, N'Open Pit/Poço aberto', N'Pinhão de giro exposto com peças rotativas ', N'ELIMINAR RISCO DE ACIDENTE', N'0', N'01 - Imagens/01 - Antes/11933.jpeg', N'Pinhão de giro exposto com risco de pensamento de dedos, esmagamento, lesões graves.', N'01 - Imagens/02 - Depois/11933.jpeg', N'Foi fabricado e montado proteção no pinhão e eliminado risco de acidentes pessoais, padrozação de proteção de equipamentos. ', NULL, N'Pinhão exposto com risco de acidentes pessoais, após fabricação e montagem da proteção esse risco foi eliminado ', N'Eliminado risco de acidentes', 0, NULL, NULL, '2026-08-13T00:00:00.000', '2026-08-26T08:30:10.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (11934, N'81051007', N'81051007', N'Melhoria Ergonômica no Abastecimento do Britador', 1, N'Others/Outros', N'A atividade de alimentação do britador era realizada diretamente do nível do piso, exigindo que o operador elevasse as bandejas acima da altura dos ombros para despejar o material no equipamento. Essa condição gerava esforço físico excessivo, postura inadequada e exposição a riscos ergonômicos, aumentando o potencial de fadiga e desconforto durante a execução da tarefa.', N'Reduzir o risco ergonômico na atividade de alimentação do britador, proporcionando uma condição de trabalho mais segura, confortável e eficiente para os operadores.', N'10129', N'01 - Imagens/01 - Antes/11934.jpeg', N'Alimentação do britador realizada diretamente do piso.
INSERT INTO #PVC VALUES (11935, N'502383', N'81046924', N'SUPORTE PARA TUBULAÇÃO ', 1, N'Open Pit/Poço aberto', N'Tubulação sem escora com risco de rompimento ', N'Minimizar risco de perda material', N'0', N'01 - Imagens/01 - Antes/11935.jpeg', N'Tubulação sem escora com risco de rompimento consequentemente perda material ', N'01 - Imagens/02 - Depois/11935.jpeg', N'Foi fabricado e instalado escora na tubulação minimizando riscos de perda material por rompimento da tubulação. ', NULL, N'Minimizado risco de rompimento da tubulação ', N'Eliminação risco de perda material ', 0, NULL, N'less time for person to figure out printer configuration for this application.', '2026-08-22T00:00:00.000', '2026-08-26T08:44:06.000', N'502383', NULL, NULL);
INSERT INTO #PVC VALUES (11936, N'81009270', N'81009270', N'Mine Dewatering sample point', 1, N'Concentration/Concentração', N'Tailings and Water Leads monitor the water chemistry of the Ovoid pit water. This required the TWL to go down to the shore of the Ovoid and collect a sample. This was time consuming and required working at the waters edge. The sample collected is also not representative of the water being removed form the Ovoid. ', N'Add a sample point to the Mine Dewatering pipeline in the mill to allow sample collection', N'10311', N'01 - Imagens/01 - Antes/11936.jpeg', N'The Tailings and water lead would go down to the shore of the ovoid and collet a sample. This was time consuming and required working right at the water''s edge. The sample collected was not representative of the water pumped back to the mill', N'01 - Imagens/02 - Depois/11936.jpeg', N'An old tee off the mine dewatering pipeline that was removed from service was repurposed and new piping was installed to add a sample point inside the Mill. ', NULL, N'The sample point is now in service and sample collection is happening in the mill. A representative sample of what is being pumped from the Ovoid is now possible. TWLs no longer have to collect samples from the water''s edge.', N'Decommissioned piping was used to save money on replacing large sections of pipe', 0, NULL, NULL, '2026-07-31T00:00:00.000', '2026-08-26T10:35:02.000', N'81009270', NULL, NULL);
INSERT INTO #PVC VALUES (11937, N'81002116', N'81002116', N'Implantação de Governança para Aprovação de Ordens de Manutenção com Impacto Orçamentário', 1, N'Others/Outros', N'Ausência de um processo estruturado para avaliação e priorização das Ordens de Manutenção com impacto orçamentário, resultando em alocação ineficiente dos recursos disponíveis e baixo nível de governança sobre as decisões de aprovação.', N'Implantar um fluxo padronizado de análise e aprovação das Ordens de Manutenção com impacto orçamentário, garantindo critérios claros de decisão, rastreabilidade do processo, alinhamento entre áreas e utilização mais eficiente do orçamento de manutenção.', N'10184', N'01 - Imagens/01 - Antes/11937.jpeg', N'Antes da implantação do fluxo de aprovação, as Ordens de Manutenção eram analisadas individualmente, sem um fórum estruturado para discutir necessidade, momento adequado de execução e aderência ao orçamento disponível.
INSERT INTO #PVC VALUES (11938, N'81007243', N'81047727', N'Confeccionado suporte para o motor da freezer da entrada da oficina', 3, N'Others/Outros', N'O motor encontrava-se exposto, com risco de danos, e a qualidade da imagem registrada demonstrava um ambiente desorganizado ', N'Proteção do motor', N'10139', N'01 - Imagens/01 - Antes/11938.jpeg', N'O motor encontrava-se exposto, com risco de danos, e a qualidade da imagem registrada demonstrava um ambiente desorganizado ', N'01 - Imagens/02 - Depois/11938.jpeg', N'Confeccionado suporte para o motor da freezer da entrada da oficina', NULL, N'Qualidade em nosso ambiente de trabalho ', N'Qualidade em nosso ambiente de trabalho ', 0, NULL, NULL, '2026-08-20T00:00:00.000', '2026-08-26T12:04:15.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11939, N'81010520', N'81010520', N'Malvern motor replacement', 1, N'Refining/Refino', N'Lab technician noticed the motor looked black and the mixer wasn''t working. They had a spare motor ordered and asked if we could try fixing it.', N'equipment back in service/cost savings', N'0', N'01 - Imagens/01 - Antes/11939.jpeg', N'The Malvern sample dispersion unit was not operational due to a failed motor. This was causing operational slow down at the lab. ', N'01 - Imagens/02 - Depois/11939.jpeg', N'We removed the old motor and replaced it with a new motor from the factory.', NULL, N'The motor was replaced and the unit is back in operation.', N'Instead of ordering a new malvern mixer at a cost of $30,000 we can stock replacement parts and make repairs on-site.', 25500, 3, N'Não há ganhos financeiros diretos, porém há ganho de produtividade uma vez que houve redução de 763HH/ano nos planos de inspeção da automação,  liberando o técnico de automação para executar outras atividades, redução de custo com combustível (Não mensurável), menor exposição ao risco deslocamento (RAC02)', '2026-08-16T00:00:00.000', '2026-08-26T12:16:39.000', N'81010520', NULL, NULL);
INSERT INTO #PVC VALUES (11940, N'81007243', N'81047727', N'Instalado botoeira de emergencia', 2, N'Others/Outros', N'Maquina estava interditada pela segurança devido não ter acionamento de emergência. ', N'Segurança ', N'10139', N'01 - Imagens/01 - Antes/11940.jpeg', N'A máquina encontrava-se interditada pela área de Segurança, em razão da ausência de acionamento de emergência.', N'01 - Imagens/02 - Depois/11940.jpeg', N'Instalado botoeira de emergência ', NULL, N'Qualidade e segurança das atividades', N'Qualidade e segurança das atividades', 0, NULL, N'Disponibilizar a informação certa, no momento certo e no local onde a atividade acontece, contribuindo para operações mais ágeis, produtivas e eficientes', '2026-08-24T00:00:00.000', '2026-08-26T12:18:30.000', N'81007243', NULL, NULL);
INSERT INTO #PVC VALUES (11941, N'498554', N'498554', N'Identificação física de componente', 1, N'Others/Outros', N'Dificuldade de rastrear o componentes reformado', N'Criar controle', N'#N/A', N'01 - Imagens/01 - Antes/11941.jpeg', N'Os componentes não possuíam placas de identificação com numeração de rastreio.', N'01 - Imagens/02 - Depois/11941.jpeg', N'Desenvolvido em parceria com o fornecedor, o sistema de identificação foi projetado para garantir maior durabilidade e confiabilidade, mantendo a rastreabilidade dos componentes', NULL, N'Foi resolvido o problema', N'Pensar fora da caixa', 0, NULL, N'SEGURANÇA E CONFIABILIDADE NO TRANSPORTE DE IMPLEMENTOS SOBRE CARROCERIA .', '2026-08-24T00:00:00.000', '2026-08-26T12:49:28.000', N'498554', NULL, NULL);
INSERT INTO #PVC VALUES (11942, N'81057418', N'81057499', N'Implantação de mangueira para direcionamento da água no lavador de peneiras', 3, N'Open Pit/Poço aberto', N'Durante a lavagem das peneiras, a água utilizada se espalhava pela área do lavador, dificultando seu escoamento até o ralo. Isso gerava acúmulo de água aumentando a necessidade de limpeza', N'Melhor direcionamento da água para o ralo.', N'10129', N'01 - Imagens/01 - Antes/11942.jpeg', N'Durante a lavagem das peneiras, a água utilizada se espalhava pela área do lavador, dificultando seu escoamento até o ralo. Isso gerava acúmulo de água aumentando a necessidade de limpeza', N'01 - Imagens/02 - Depois/11942.jpeg', N'Foi instalada uma mangueira no sistema de drenagem do lavador de peneiras para direcionar a água de descarte diretamente ao ralo. Dessa forma, o escoamento ocorre de maneira eficiente e controlada.', NULL, N'A água que antes se acumulava na área de lavagem passou a ser direcionada diretamente ao ralo por meio da mangueira instalada, proporcionando melhor drenagem, maior segurança e melhores condições de trabalho.', N'Pequenas melhorias de baixo custo podem gerar impactos significativos na organização, segurança e eficiência das atividades rotineiras.', 0, NULL, N'Facilidade nas limpeza 
INSERT INTO #PVC VALUES (11943, N'81057418', N'81057418', N'Placa de controle para acompanhamento de amostras em ataque ', 1, N'Open Pit/Poço aberto', N'As informações das amostras de cloro em  chapa não ficavam centralizadas em um local de fácil visualização, dificultando o acompanhamento das etapas do processo ', N'Redução de erros e falhas de comunicação ', N'10129', N'01 - Imagens/01 - Antes/11943.jpeg', N'Falta de um local para registrar em qual etapa as amostras de  cloro está, dificultando o acompanhamento do processo, horários e das observações necessárias. Aumentando o risco de dúvidas, falhas de comunicação e perda de informações durante a rotina de trabalho.', N'01 - Imagens/02 - Depois/11943.jpeg', N'Instalada uma placa de controle para registro e acompanhamento das amostras em ataque. A placa permite registrar a identificação das amostras, a etapa em que se encontram, os horários de início e término do ataque e observações relevantes sobre o processo.', NULL, N'A placa implantada passou a concentrar as informações do processo, permitindo acompanhamento em tempo real das amostras, trazendo organização e confiabilidade na execução das atividades.', N'A gestão visual é uma ferramenta simples e eficaz para melhorar o controle dos processos.', 0, NULL, N'Visão rápida e direta do andamento da execução de custos da Ger. de PCM e Confiabilidade para os responsáveis pelo orçamento da Gerência.', '2026-08-25T00:00:00.000', '2026-08-26T13:56:08.000', N'81057418', NULL, NULL);
INSERT INTO #PVC VALUES (11944, N'81026275', N'81026275', N'Cost Avoidance - Lime Transfer Tank (176-AGP-001)', 1, N'Open Pit/Poço aberto', N'High vibration indicating lubrication/bearing fault on the motor for lime transfer tank agitator motor 176-AGP-001. 
INSERT INTO #PVC VALUES (11945, N'81050431', N'81050431', N'proteção para graxeiro', 1, N'Others/Outros', N'durante operação os pino graxeiros vinham a danificar  devido projeção de blocos', N'redução de retrabalo ', N'10139', N'01 - Imagens/01 - Antes/11945.jpeg', N'durante operação os pino graxeiros vinham á danificar  devido projeção de blocos, dificultando assim a lubrificação', N'01 - Imagens/02 - Depois/11945.jpeg', N'foi fabricado uma proteção para garantir a vida útil da graxeiro protegendo de projeção, contaminação e outros.', NULL, N'com essa melhoria agilizamos o processo de lubrificação', N'melhorias', 0, NULL, N'Garantir 100% de travamento da porta, reduzir o tempo de fechamento manual  e eliminar 100% das aberturas acidentais causadas pelo vento ou por batidas.', '2026-08-25T00:00:00.000', '2026-08-26T17:43:54.000', N'81050431', NULL, NULL);
INSERT INTO #PVC VALUES (11946, N'81052333', N'81040197', N'Redução da montagem das vigas no silo 2.', 1, N'Crusher/Britadeira', N'Durante a troca do excêntrico do britador primário, a montagem das vigas do carro Troller era necessária para acesso à área de manutenção, consumindo cerca de 8 horas e exigindo elevado esforço físico da equipe. Devido ao desgaste do revestimento e do concreto, também era necessária a montagem de andaimes, aumentando o tempo de execução, a complexidade da atividade.', N'Redução de montagem de Vigas no silo 2', N'10362', N'01 - Imagens/01 - Antes/11946.jpeg', N'Durante a troca do excêntrico do britador primário, era necessária a montagem das vigas do carro Troller para possibilitar o acesso à área de manutenção. Essa atividade exigia intenso esforço físico da equipe exposição dos empregados a riscos durante a movimentação e instalação dos componentes.', N'01 - Imagens/02 - Depois/11946.jpeg', N' Foi projetado e implementado um novo modelo de viga fixa, revestida com chapas de desgaste, permanecendo instalada no local de forma permanente. Dessa forma, eliminou-se a necessidade de montagem e desmontagem das vigas e do uso de andaimes a cada intervenção de troca do excêntrico.', NULL, N'sim,Com base em estudos e planejamento da atividade, foi desenvolvida uma solução definitiva para a instalação das vigas. Foi projetado e implementado um novo modelo de viga fixa, revestida com chapas de desgaste, permanecendo instalada no local de forma permanente. ', N'redução de esforços físicos e cenário de risco.', 80000, 1, N'The new scanners help to improve our inventory system.', '2026-08-20T00:00:00.000', '2026-08-26T19:21:20.000', N'81052333', NULL, NULL);
INSERT INTO #PVC VALUES (11947, N'1009274', N'1009274', N'Retaining ring set screw', 1, N'Refining/Refino', N'The retaining ring for the hammer puck would become loose during operation and damage the puck holder. in 2025 we consumed over 50 units due to this failure. ', N'prevent the retaining ring from coming loose', N'0', N'01 - Imagens/01 - Antes/11947.jpeg', N'during normal operation, the retaining ring would come loose and damage the puck holder. This would require the replacement of the full puck holder.', N'01 - Imagens/02 - Depois/11947.jpeg', N'addition of a set screw in the lock ring ensured the retaining ring stayed tight during operation.', NULL, N'problem solved!', N'replicated on stripping booth #2', 70000, 3, N'Support beam repaired.', '2026-05-28T00:00:00.000', '2026-08-26T19:54:39.000', N'1009274', NULL, NULL);
INSERT INTO #PVC VALUES (11948, N'1009274', N'1009274', N'Shipping Printer Setup', NULL, N'Others/Outros', N'No procedure for setting up the shipping printer', N'easy to follow procedure', N'0', N'01 - Imagens/01 - Antes/11948.jpeg', N'no setup procedure for the nickel shipping printer was increasing the time to replace the unit when it failed.', N'01 - Imagens/02 - Depois/11948.jpeg', N'Developed an easy-to-follow setup procedure for replacing a failed unit.', NULL, N'solved! ', N'works well', 0, NULL, N'OS RESULTADO FORAM ALCANÇADOS COM A PADRONIZAÇÃO', '2026-07-24T00:00:00.000', '2026-08-26T19:59:55.000', N'1009274', NULL, NULL);
INSERT INTO #PVC VALUES (11949, N'1009274', N'1009274', N'Spyder Lift', 1, N'Others/Outros', N'Many of our areas in LH are tight access and traditional AWP machines are not capable of fitting into the areas required. This leaves only scaffolding which is labour intensive and costly.', N'reduce costs', N'0', N'01 - Imagens/01 - Antes/11949.jpeg', N'to reach many areas, scaffolding was required. Traditional AWP''s would not fit down the isle way with the reach required for the work location elevation.', N'01 - Imagens/02 - Depois/11949.jpeg', N'the Spyder lift only requires a 36" opening but can reach 27M in height. This eliminates the need for large scaffold builds to reach a desired location.', NULL, N'problem solved!', N'works very well', 100000, 3, N'O sistema de saia de PU resolveu o derramamento de carga, gerando ganho operacional e aumentando a segurança no entorno do equipamento.', '2026-08-05T00:00:00.000', '2026-08-26T20:32:21.000', N'1009274', NULL, NULL);
INSERT INTO #PVC VALUES (11950, N'1009274', N'1009274', N'Recycling outdated wear pads', 3, N'No Replication/Sem replicação', N'previous revision wear pads did not fit the new design.', N'modify old inventory to fit new design', N'0', N'01 - Imagens/01 - Antes/11950.jpeg', N'Old wear pads were large and costly. A new design was introduced, but the old inventory sat in the warehouse unable to be used. ', N'01 - Imagens/02 - Depois/11950.jpeg', N'use the old inventory and correct the sizing to fit the new design, reducing waste.', NULL, N'solved!', N'worked as intended', 15680, 3, N'A melhoria eliminou a causa raiz do desgaste estrutural e aumentou a confiabilidade operacional do transportador.', '2026-08-25T00:00:00.000', '2026-08-26T20:47:19.000', N'1009274', NULL, NULL);
INSERT INTO #PVC VALUES (11951, N'81046149', N'81046149', N'Dispositivo de retirada de corpo moedores presos moinho sag.', 2, N'Projects/Projetos', N'Durante a execução da atividade de expurgar corpos moedores da parte interna do moinho SAG que estavam alocados entre os revestimentos de canto, considerada uma atividade crítica da Grande Parada (GP), foi identificada a permanência de corpos moedores presos no interior do equipamento. A ausência de uma ferramenta ou dispositivo específico para sua remoção gerava exposição dos trabalhadores ao risco de queda de materiais, exigia esforço físico excessivo e elevava o potencial de ocorrência de incidentes durante a execução da tarefa, impactando diretamente as condições de segurança e eficiência operacional.', N'Eliminar ou reduzir a exposição dos colaboradores aos riscos durante a retirada de corpos moedores presos nos revestimentos de canto do moinho, utilizando um dispositivo acoplado ao manipulador para realizar a atividade de forma remota, segura e controlada', N'10362', N'01 - Imagens/01 - Antes/11951.jpeg', N'Durante a execução da atividade de expurgar corpos moedores da parte interna do moinho SAG que estavam alocados entre os revestimentos de canto, considerada uma atividade crítica da Grande Parada (GP), foi identificada a permanência de corpos moedores presos no interior do equipamento. A ausência de uma ferramenta ou dispositivo específico para sua remoção gerava exposição dos trabalhadores ao risco de queda de materiais, exigia esforço físico excessivo e elevava o potencial de ocorrência de incidentes durante a execução da tarefa, impactando diretamente as condições de segurança e eficiência operacional.', N'01 - Imagens/02 - Depois/11951.jpeg', N'Foi desenvolvido e instalado um dispositivo específico acoplado ao manipulador para a remoção controlada dos corpos moedores presos no interior do moinho SAG. A solução permite executar a atividade com maior segurança, mantendo os trabalhadores fora da zona de risco, reduzindo o esforço físico e proporcionando maior controle durante a movimentação e retirada dos materiais.', NULL, N'Identificar riscos antecipadamente permite desenvolver soluções mais seguras.
INSERT INTO #PVC VALUES (11952, N'81058081', N'81058081', N'Redução do desperdício com deslocalmentos desnecessários durante inspeções de ativos da automação', 1, N'Others/Outros', N'Deslocamentos redundantes à mesma sala elétrica, estrutura fragmentada (103 planos e 169 listas de atividades), desperdício de HH, combustível e exposição desnecessária ao risco de RAC02', N'Redução de 600 horas por ano gastas com inspeção preditiva', N'10293', N'01 - Imagens/01 - Antes/11952.jpeg', N'▪  103 planos de manutenção
INSERT INTO #PVC VALUES (11953, N'81063768', N'81063768', N'ScanMat', 1, N'Others/Outros', N'Antes da implementação do QR Code, a consulta à disponibilidade e especificação dos materiais dependia do deslocamento físico dos colaboradores até o setor responsável ou do contato direto com a equipe de apoio para obtenção das informações. Esse processo gerava tempo improdutivo, atrasos na execução das atividades de campo e dependência de recursos administrativos para consultas simples.
INSERT INTO #PVC VALUES (11954, N'81058052', N'81058052', N'confecção de guarda corpo gd-52', 3, N'Others/Outros', N'parte traseira do caminhão não dispunha de um guarda corpo eficaz ,o anterior por ter sido feito de forma aleatória veio a ser extraviado.', N'mitigar eventuais incidentes e acidentes envolvendo trabalho em altura e queda de materiais  com o objetivo de aumentar a segurança no transporte de cargas com o munck', N'10346', N'01 - Imagens/01 - Antes/11954.jpeg', N'equipamento sem guarda corpo traseiro podendo propiciar queda de nível diferente dos colaboradores ao subirem na carroceria para atividades de rotina e queda de materiais da carroceria do caminhão.', N'01 - Imagens/02 - Depois/11954.jpeg', N'Foi confeccionado um guarda corpo com barra tubular de 7/16'''' com reforço no centro e cantos arredondados sem cantos vivos ,trava com parafuso na base inferior para evitar o desprendimento .', NULL, N'O PROBLEMA FOI RESOLVIDO NÃO HAVENDO MAIS RELATOS DE QUEDA DO GUARDA CORPO DO EQUIPAMENTO EM QUESTÃO.', N'a melhoria impacta positivamente atividades não inerentes a manutenção mecânica ,porem o cuidado ativo genuíno se faz presente ao atentarmos para a segurança  dos colaboradores de operações distintas ás nossas.', 0, NULL, N'Increased production ', '2026-08-01T00:00:00.000', '2026-08-27T09:26:40.000', N'81058052', NULL, NULL);
INSERT INTO #PVC VALUES (11955, N'81058966', N'81038855', N'Implantação de suporte para enrolar e armazenar mangueiras', 1, N'Others/Outros', N'Foi identificado que as mangueiras proximos a CF-2057-32 utilizadas na área permaneciam espalhadas pelo piso, sem um local definido para armazenamento.', N'Aumento da vida útil da mangueiras  Ambiente mais limpo,  seguro e organizado ', N'10031', N'01 - Imagens/01 - Antes/11955.jpeg', N'A falta de um sistema de armazenamento fazia com que as mangueiras fossem deixadas diretamente sobre o piso, aumentando a possibilidade de acidentes e danos ao equipamento.', N'01 - Imagens/02 - Depois/11955.jpeg', N'Foi  instalado um suporte metálico específico para enrolar e armazenar as mangueiras, proporcionando um local definido para guarda após a utilização.
INSERT INTO #PVC VALUES (11956, N'81034722', N'81034722', N'Card Semanal de Custos', 1, N'Others/Outros', N'Dificuldade de ter a informação de forma rápida do andamento do custo, BI''s de controle são restritos e de visual dificultoso.', N'Visão rápida e direta do andamento da execução de custos da Ger. de PCM e Confiabilidade', N'10081', N'01 - Imagens/01 - Antes/11956.jpeg', N'Dificuldade de ter a informação de forma rápida do andamento do custo, BI''s de controle são restritos e de visual dificultoso.', N'01 - Imagens/02 - Depois/11956.jpeg', N'Criada Visão rápida e direta do andamento da execução de custos da Ger. de PCM e Confiabilidade, com atualização e divulgação semanal.', NULL, N'Sim, com a criação do card, a informação ficou mais clara e rápida para os responsáveis pelo orçamento, com a informação sendo atualizada semanalmente.', N'Com a criação do card, a informação ficou mais clara e rápida para os responsáveis pelo orçamento.', 0, NULL, N'Padronização dos estudos de LCC, eliminação da dependência de planilhas individuais, armazenamento seguro em nuvem, aumento da rastreabilidade e auditabilidade, melhoria da experiência do usuário e fortalecimento da governança dos dados.', '2026-08-07T00:00:00.000', '2026-08-27T09:28:17.000', N'81034722', NULL, NULL);
INSERT INTO #PVC VALUES (11957, N'81058966', N'81038934', N'Implantação de Sistema Hídrico para Higienização Industrial da Baia — Proximidade do Equipamento BP-2057-34', 1, N'Others/Outros', N'A baia apresentava limitação no sistema de limpeza industrial, principalmente quanto ao alcance do jato hídrico e à cobertura de determinadas regiões da área operacional.', N'Implantar um sistema hídrico exclusivo para higienização industrial da baia, com ponto de suprimento estrategicamente posicionado próximo ao BP-2057-34, proporcionando maior alcance e cobertura do jato, redução do tempo de limpeza, racionalização do consumo hídrico e redução da exposição dos colaboradores a riscos operacionais.', N'10031', N'01 - Imagens/01 - Antes/11957.jpeg', N'Antes da implantação, a baia não dispunha de um ponto hídrico estrategicamente localizado para atender de forma eficiente toda a área destinada à higienização industrial.', N'01 - Imagens/02 - Depois/11957.jpeg', N'Foi confeccionado, montado e instalado um sistema hídrico exclusivo para limpeza e higienização,o sistema foi composto por tubulação de 1½ polegada, mangueira de 1½ polegada e bico direcionador de jato. ', NULL, N'SIM.
INSERT INTO #PVC VALUES (11958, N'81060882', N'81060882', N'Instalação de trinco mecânico na porta de acesso.', 1, N'Others/Outros', N'A porta permanecia sem sistema de retenção rápida, gerando abertura acidental.', N' Eliminar a abertura indesejada do ambiente e otimizar o controle de acesso diário.', N'10362', N'01 - Imagens/01 - Antes/11958.jpeg', N'A porta permanecia sem sistema de retenção rápida, gerando abertura acidental por correntes de ar ou falta de travamento prático temporário.
INSERT INTO #PVC VALUES (11959, N'124132', N'124132', N'Scanning LH Plate bags', 1, N'Refining/Refino', N'Our old scanning system did not support scanning the LH Plate bar codes and some operators were double scanning them that affect the inventory of the LH Plate bags.', N'New scanners programmed to scan the LH Plate bags', N'10255', N'01 - Imagens/01 - Antes/11959.jpeg', N'Our old scanning system did not support scanning the LH Plate bar codes and some operators were double scanning them that affect the inventory of the LH Plate bags. We used to collect the tags from each bag and them put them into SAP.', N'01 - Imagens/02 - Depois/11959.jpeg', N'The new scanners are programmed to scan the LH Plate bags when operations dump them. The bags cannot be double scanned with the new system. ', NULL, N'No double scanning that would affect the inventory.', N'New scanners work perfectly', 0, NULL, NULL, '2026-08-26T00:00:00.000', '2026-08-27T10:40:15.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11960, N'124132', N'124132', N'Support beam in #4 building ', NULL, N'Refining/Refino', N'We had a support beam in #4 building that was ', N'Repair the support beam ', N'10255', N'01 - Imagens/01 - Antes/11960.jpeg', N'The beam in #4 building was damaged and caught in an OSHE inspection.', N'01 - Imagens/02 - Depois/11960.jpeg', N'The support beam was repaired with a large steam plate.', NULL, N'The support beam was repaired.', N'Inspections are very important', 0, NULL, N'This went as expected. We will now take care of the area that was freed up by the West personnel door of the Cobalt Maintenance Shop. Prop ear plug dispensers, painted wall, good to go!', '2026-08-20T00:00:00.000', '2026-08-27T10:54:30.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11961, N'521797', N'521797', N'PADRONIZAÇÃO DAS TUBULAÇÕES AR DE SECAGEM', 2, N'Others/Outros', N'Durante Realização de atividades na área da Filtragem, foi identificado que as tubulações de ar de secagem do Filtro 2 não possuíam a mesma padronização de instrumentação existente no Filtro 1. Essa divergência dificultava o monitoramento operacional, reduzia a confiabilidade das informações de processo, expondo equipes a riscos durante intervenções.', N'Aumentar a segurança dos empregados durante inspeções e manutenções, melhorar a confiabilidade do sistema de ar de secagem e garantir a padronização dos equipamentos e instrumentos entre os filtros, reduzindo riscos operacionais e facilitando a tomada de decisão baseada em dados precisos de processo.', N'0', N'01 - Imagens/01 - Antes/11961.jpeg', N'As tubulações de ar de secagem do Filtro 2 não possuíam os mesmos instrumentos instalados no Filtro 1, resultando em falta de padronização entre os equipamentos. Essa condição limitava o monitoramento adequado do sistema, aumentava a dificuldade na identificação de desvios operacionais e elevava os riscos durante atividades de operação e manutenção.', N'01 - Imagens/02 - Depois/11961.jpeg', N'Foram instalados e padronizados os instrumentos nas tubulações de ar de secagem do Filtro 2, adotando a mesma configuração existente no Filtro 1. Com a adequação, o sistema passou a possuir maior confiabilidade no monitoramento dos parâmetros operacionais, melhor suporte às atividades de manutenção e maior segurança para as equipes envolvidas.', NULL, N'SIM. A meta foi alcançada. A diferença de instrumentação existente entre os filtros foi eliminada por meio da padronização das tubulações de ar de secagem do Filtro 2, resultando em maior segurança, confiabilidade operacional e alinhamento com o padrão adotado no Filtro 1.', N'A padronização dos instrumentos entre equipamentos semelhantes aumenta a segurança operacional, melhora a confiabilidade do monitoramento do processo e facilita as atividades de operação e manutenção. Inspeções periódicas contribuem para identificar oportunidades de melhoria e eliminar desvios de padronização.', 0, NULL, N'Menor tempo de setup e manutenção corretiva.
INSERT INTO #PVC VALUES (11962, N'81060882', N'81060882', N'Implementação de Saia de Vedação em PU', 1, N'Projects/Projetos', N'O transportador operava sem guias laterais de contenção eficientes ou com saias de vedação desgastadas, isso causava vazamento constante de material pelas laterais da correia, desalinhamento do fluxo e acúmulo de sujeira na estrutura e nos roletes inferiores.', N'Eliminar o vazamento de material nas zonas de carga e transferência', N'10362', N'01 - Imagens/01 - Antes/11962.jpeg', N'O transportador operava sem guias laterais de contenção eficientes ou com saias de vedação desgastadas, isso causava vazamento constante de material pelas laterais da correia, desalinhamento do fluxo e acúmulo de sujeira na estrutura e nos roletes inferiores.
INSERT INTO #PVC VALUES (11963, N'81060882', N'81060882', N'Instalação de Rolos Guias Limitadores para Proteção Estrutural no Carro Tensor', 1, N'Projects/Projetos', N'O carro tensor sofria com desalinhamentos dinâmicos frequentes da correia ou oscilações estruturais durante a partida e parada do transportador', N'Eliminar o contato direto metal-metal ou correia-estrutura no conjunto do carro tensor', N'10362', N'01 - Imagens/01 - Antes/11963.jpeg', N'O carro tensor sofria com desalinhamentos dinâmicos frequentes da correia ou oscilações estruturais durante a partida e parada do transportador, sem um limitador físico giratório, as bordas da correia ou os componentes móveis do próprio carro tensor colidiam diretamente contra a estrutura fixa do equipamento, desgaste prematuro e rasgos nas bordas da correia, deformação estrutural do trilho/chassi do carro tensor, alto índice de paradas corretivas e risco de travamento do sistema de esticamento.
INSERT INTO #PVC VALUES (11964, N'81060882', N'81060882', N'Implementação de Sistema de Eixo Tipo Gaveta', 1, N'Projects/Projetos', N'O raspador terciário utilizava um sistema de eixo convencional inteiriço e extremamente pesado, posicionado em uma área de espaço físico severamente limitado e de difícil acesso.', N'Reduzir o peso manuseado pelos mecânicos durante a manutenção do raspador.', N'10362', N'01 - Imagens/01 - Antes/11964.jpeg', N'O raspador terciário utilizava um sistema de eixo convencional inteiriço e extremamente pesado, posicionado em uma área de espaço físico severamente limitado e de difícil acesso.
INSERT INTO #PVC VALUES (11965, N'81037771', N'81034200', N'suporte para celular', 3, N'Projects/Projetos', N'Ao utilizar o banheiro, os celulares ficavam sobre a pia, e constantemente entrando em contato com água. ', N'Evitar que os aparelhos celulares entrem em contato com água', N'10122', N'01 - Imagens/01 - Antes/11965.jpeg', N'Durante o uso do banheiro, o celular permanece sobre a pia, podendo entrar em contato com água e ficar sujeito a danos.', N'01 - Imagens/02 - Depois/11965.jpeg', N'Como medida preventiva, foi criado um suporte para posicionamento do celular, evitando sua exposição à água durante a utilização do banheiro.', NULL, N'SIM. O problema foi resolvido. Com a criação de um suporte para acomodação do celular, o equipamento deixou de ficar exposto sobre a pia durante o uso do banheiro, eliminando o risco de contato com água e reduzindo a possibilidade de danos. A solução implementada atendeu à meta proposta e contribuiu para a preservação do equipamento.', N'A implementação de um suporte para acomodação do celular eliminou a exposição direta à água durante o uso do banheiro, aumentando a proteção do equipamento e reduzindo o risco de danos. A solução simples e de baixo custo demonstrou a importância de identificar riscos cotidianos e adotar medidas preventivas para garantir a conservação dos recursos.', 0, NULL, N'Aquisição de armário dedicado para ferramentas utilizados na limpeza da área.', '2026-08-21T00:00:00.000', '2026-08-27T12:40:05.000', N'81037771', NULL, NULL);
INSERT INTO #PVC VALUES (11966, N'81062557', N'81062557', N'Implantação de Redundância no Sistema de Monitoramento de Velocidade da Correia 2301-TC-02', 1, N'Crusher/Britadeira', N'A correia transportadora 2301-TC-02 possuía apenas um sensor indutivo para monitoramento de velocidade. Essa configuração apresentava um ponto único de falha, tornando a disponibilidade do equipamento dependente da integridade de um único dispositivo. Falhas causadas por danos mecânicos, infiltração de água, rompimento de cabos, mau contato ou defeitos internos do sensor resultavam na parada imediata da correia para intervenção corretiva, gerando aproximadamente 2 horas de indisponibilidade por ocorrência. Para eliminar essa vulnerabilidade, a melhoria consistiu na instalação de um segundo sensor indutivo e no desenvolvimento de uma lógica de controle redundante, permitindo a continuidade operacional do equipamento em caso de falha de um dos sensores.', N'Eliminar paradas não programadas causadas por falhas no sensor de velocidade da 2301-TC-02, aumentando a confiabilidade e a disponibilidade operacional do equipamento por meio da implantação de redundância no sistema de monitoramento.', N'10125', N'01 - Imagens/01 - Antes/11966.jpeg', N'O monitoramento de velocidade da correia 2301-TC-02 era realizado por apenas um sensor indutivo. Em caso de falha do sensor ou de seus componentes associados, ocorria a parada imediata da correia para diagnóstico e manutenção. Por se tratar de um sistema sem redundância, qualquer falha isolada impactava diretamente a disponibilidade do equipamento, gerando indisponibilidade operacional e risco de perda de produção.', N'01 - Imagens/02 - Depois/11966.jpeg', N'Como solução, foi instalado um segundo sensor indutivo no sistema de monitoramento de velocidade da correia 2301-TC-02 e desenvolvida uma lógica de controle redundante (arquitetura 2oo1). Com a nova configuração, a falha de um dos sensores passa a gerar apenas um alarme para a equipe de manutenção, mantendo a correia em plena operação através do sensor redundante. A parada do equipamento ocorre somente em caso de falha simultânea dos dois sensores, permitindo que as intervenções sejam realizadas de forma programada, em parada oportuna.
INSERT INTO #PVC VALUES (11967, N'124132', N'124132', N'Installing new removable cross bars on the 10 kg line', NULL, N'Refining/Refino', N'When we package P-Pellet some of the bags made do not form well which causes issues when the bags fall into the box. This causes issues when the boxes get taped at the end of the line which results in production loss.', N'Cross bars to be installed which help flaten the bags going into the boxes.', N'10255', N'01 - Imagens/01 - Antes/11967.jpeg', N'When we package P-Pellet some of the bags made do not form well which causes issues when the bags fall into the box. This causes issues when the boxes get taped at the end of the line which results in production loss.', N'01 - Imagens/02 - Depois/11967.jpeg', N'Now with the new removable cross bars the P-Pellet bags are made and flattened on the line. This allows the bags to fall perfectly into the box.', NULL, N'The new cross bars help to flatten the bags.', N'New cross bars will help with increased production', 0, NULL, N'Espera-se alcançar resultados de redução do tempo de espera na entrada ao site, aumento da qualidade de transporte dos colaboradores e confiabilidade nos dados de bloqueio de acesso na portaria de N1.', '2026-08-26T00:00:00.000', '2026-08-27T13:18:21.000', N'124132', NULL, NULL);
INSERT INTO #PVC VALUES (11968, N'99655', N'99655', N'Utilização de dispositivo para homogeneização de amostras', 2, N'Open Pit/Poço aberto', N'Na análise de U temos que homogeneizar os tubos de ensaio contendo amostra uma de cada vez, levando mais tempo para realizar a atividade.
INSERT INTO #PVC VALUES (11969, N'517013', N'517013', N'Aplicativo Corporativo de LCC para Padronização e Rastreabilidade dos Estudos', 1, N'Open Pit/Poço aberto', N'Os estudos de Life Cycle Cost (LCC) eram realizados de forma descentralizada e sem padronização, dificultando a rastreabilidade, auditoria e compartilhamento das informações entre os usuários.', N'Padronizar a execução dos estudos de LCC, garantindo rastreabilidade, segurança das informações, governança dos dados e acesso controlado aos estudos realizados.', N'10015', N'01 - Imagens/01 - Antes/11969.jpeg', N'Não existia uma metodologia padronizada para elaboração de estudos de LCC. Os estudos eram desenvolvidos em planilhas Excel individuais e normalmente ficavam armazenados apenas no computador da pessoa responsável pela análise. Essa prática dificultava o compartilhamento das informações, comprometia a rastreabilidade e gerava riscos para auditorias e consultas futuras, especialmente quando o responsável pelo estudo já não estava disponível. Além disso, não havia controle centralizado das informações, histórico de alterações ou governança adequada dos estudos realizados.', N'01 - Imagens/02 - Depois/11969.jpeg', N'Foi desenvolvido um aplicativo corporativo de LCC em Power Apps, com controle de acesso por usuário, metodologia estruturada para análise de Life Cycle Cost, armazenamento das informações em ambiente corporativo na nuvem e acesso por pessoas autorizadas. A solução conta com rastreabilidade completa, histórico dos estudos, geração automática de PDF, fluxo de notificações por e-mail, interface moderna com foco em UX/UI e mecanismos de feedback ao usuário por meio de alertas, mensagens de erro e confirmações. O aplicativo transformou o processo em uma solução padronizada, segura, auditável e escalável para toda a empresa.', NULL, N'Foi desenvolvido um aplicativo corporativo em Power Apps integrado à Power Platform, utilizando banco de dados em nuvem, controle de acesso, geração automática de PDF, fluxos de e-mail, interface moderna e metodologia estruturada de análise de LCC, garantindo gestão centralizada e auditável dos estudos.', N'A digitalização e centralização de processos críticos em plataformas corporativas aumentam significativamente a rastreabilidade, a governança dos dados e a sustentabilidade do conhecimento organizacional.', 0, NULL, N'5S', '2026-08-26T00:00:00.000', '2026-08-27T14:59:15.000', N'517013', NULL, NULL);
INSERT INTO #PVC VALUES (11970, N'81026275', N'81026275', N'Implementation of Online Condition Monitoring', 1, N'Others/Outros', N'Maintenance strategy in LH has been focused on preventative maintenance (PMs). 
INSERT INTO #PVC VALUES (11971, N'81060882', N'81060882', N'Janela de visita para acesso a calha', 1, N'Others/Outros', N'Local sem acesso seguro ao sensor de transbordo e à janela de visita da calha da 2301TR01 P/ TC06.', N'Garantir a segurança da equipe, facilitar a inspeção visual e permitir a manutenção corretiva/preventiva do sensor.', N'10362', N'01 - Imagens/01 - Antes/11971.jpeg', N'Calha da correia 2301TR01 P/ 2301TC06.
INSERT INTO #PVC VALUES (11972, N'1007278', N'1007278', N'Portable Diesel Air Compressors Tie Ins', 1, N'No Replication/Sem replicação', N'New air compressors are being installed, but the temp air compressors connections have to be moved to another location. Job planned for POrt Down day and air system shutdown and temp air compressors connected in different location to allow maintenance to work on new air compressors install.', N'No production losses', N'0', N'01 - Imagens/01 - Antes/11972.jpeg', N'Temporary diesel air compressors were tied into connections that were needed for the new air compressors. This was slowing down the new install.', N'01 - Imagens/02 - Depois/11972.jpeg', N'Temp diesel air compressors tied into system and maintenance can work on new air tie ins without any production impact.', NULL, N'Yes, compressors were tied into main air system without any production loss.', N'Work with other departments on solution ', 1000, 3, N'To have pipe clamps available in variety of sizes when needed.', '2026-08-26T00:00:00.000', '2026-08-27T15:55:12.000', N'1007278', NULL, NULL);
INSERT INTO #PVC VALUES (11973, N'81031229', N'81031229', N'Flammable Storage Improvement', 3, N'Others/Outros', N'The storage of flammable materials has been a recent focal point. It had come to my attention that our department was not storing aerosols correctly. Though the cabinet in which the aerosols were stored had been in use for many years, I decided to not only act on it''s correction, but to keep all paint related containers, aerosol and can, in a dedicated space which we use for paint application anyhow.', N'5S of Flammable Materials', N'10193', N'01 - Imagens/01 - Antes/11973.jpeg', N'Aerosol Paints were stored in the pictured grey cabinet. It had been accepted practice. ', N'01 - Imagens/02 - Depois/11973.jpeg', N'We upsized the flammable cabinet and placed it in our FRP shop. We had the cabinets grounded. We use this space to apply paint because there is adequate ventilation in there as well as a filtered spray booth. All paint is now in one location.', NULL, N'This went well. Paints go into a proper cabinet, and the cabinets stay together.', N'Everything has a place, and it should be found in that place', 0, NULL, N'pugmill''s are now filling 20m3 faster', '2026-08-25T00:00:00.000', '2026-08-27T15:55:38.000', N'81031229', NULL, NULL);
INSERT INTO #PVC VALUES (11974, N'923201', N'979633', N'Dispositivo guia para alinhamento do queimador', 1, N'Others/Outros', N'O alinhamento do queimador dependia da experiência do analista, devido à ausência de uma referência física de posicionamento, aumentando o risco de desalinhamento e afetando a estabilidade da chama e o desempenho da análise.
INSERT INTO #PVC VALUES (11975, N'81046755', N'81041899', N'KAIZEN – APP CHECKLIST FÁCIL', 2, N'Others/Outros', N'A rota Kamishibai era realizada integralmente por meio de apresentações em PowerPoint.
INSERT INTO #PVC VALUES (11976, N'81046755', N'81041899', N'KAIZEN – APP CHECKLIST FÁCIL ', 2, N'Others/Outros', N'A rota Kamishibai era realizada integralmente por meio de apresentações em PowerPoint.
INSERT INTO #PVC VALUES (11977, N'81014137', N'81007941', N'Aumento da segurança no Monitoramento de Pneus MEMS.', 2, N'Others/Outros', N'Monitoramento de Pressão e Temperatura de Pneus limitado somente através da rede de comunicação com a aplicação MEMS4.
INSERT INTO #PVC VALUES (11978, N'81006689', N'81006689', N'Armário de Materiais', 3, N'Others/Outros', N'Ferramentas de limpeza em local mal acondicionados  e fora de local adequado.', N'Organização e 5s', N'10233', N'01 - Imagens/01 - Antes/11978.jpeg', N'Ferramentas de limpeza em local mal acondicionados  e fora de local adequado.', N'01 - Imagens/02 - Depois/11978.jpeg', N'Aquisição de armário dedicado para ferramentas utilizados na limpeza da área.', NULL, N'Aquisição de armário dedicado para ferramentas utilizados na limpeza da área.', N'Sempre manter a organização ', 0, NULL, N'Eliminação do esforço físico manual para acionamento da válvula;
INSERT INTO #PVC VALUES (11979, N'81006689', N'81006689', N'Carrinho de Amostras', NULL, N'Others/Outros', N'Carrinho de entrega de amostras pequeno para quantidade de acordo com aumento de corridas .', N'Substituição de carrinho ', N'10233', N'01 - Imagens/01 - Antes/11979.jpeg', N'Carrinho de entrega de amostras pequeno para quantidade de acordo com aumento de corridas .', N'01 - Imagens/02 - Depois/11979.jpeg', N'Substituição de carrinho de entrega de amostras, por um maior que comporta todas as amostras necessárias sem prejudicar ergonomia.', NULL, N'Substituição de carrinho de entrega de amostras, por um maior que comporta todas as amostras necessárias sem prejudicar ergonomia.', N'Cuidados no transporte de cargas manuais', 0, NULL, N'além de evitar riscos ergonômicos aos trabalhadores', '2026-08-26T00:00:00.000', '2026-08-27T19:29:39.000', N'81006689', NULL, NULL);
INSERT INTO #PVC VALUES (11980, N'81020737', N'81020737', N'Automatização do Processo de Fiscalização de PAEBM na Portaria de N1', 2, N'Others/Outros', N'Atualmente, o processo de fiscalização do treinamento de PAEBM na portaria acontece de forma visual, pela checagem do passaporte. Isso leva tempo e ocasiona atrasos e filas na portaria, além de interromper o descanso dos trabalhadores durante o trajeto.', N'Reduzir o tempo de espera dos colaboradores no processo de fiscalização, bem como diminuir o tempo de parada na portaria de N1. Além disso, implementar maior confiabilidade dos dados de fiscalização por meio da automatização.', N'10141', N'01 - Imagens/01 - Antes/11980.jpeg', N'Atualmente, a checagem acontece por meio da visualização do passaporte de PAEBM de forma individual e lenta, onde o vigilante precisa olhar com atenção para verificar os dados do passaporte.', N'01 - Imagens/02 - Depois/11980.jpeg', N'Com a automatização, o processo será mais rápido e confiável, sem necessidade de checagem detalhada dos dados.', NULL, N'O problema ainda não foi resolvido. Ele foi cadastrado para constar na lista de Kaizens e entrar no processo de visibilidade e viabilização.', N'Serão aprendidas lições nos âmbitos de diminuição do tempo de espera, qualidade de transporte do colaborador, diminuição de filas de entrada na portaria de N1 e confiabilidade de dados.', 0, NULL, NULL, '2026-08-26T00:00:00.000', '2026-08-27T21:06:22.000', N'81020737', NULL, NULL);
INSERT INTO #PVC VALUES (11981, N'81029931', N'81033526', N'Demarcação da Área Útil da Chapa', NULL, N'Others/Outros', N'A chapa de aquecimento não tinha sinalização sobre o limite da área útil. Isso fazia com que os beckeres fossem posicionados em locais frios ou de baixa transferência térmica, comprometendo a preparação adequada das amostras.', N'Garantir que os beckeres sejam posicionados nos locais onde há aquecimento da chapa', N'10032', N'01 - Imagens/01 - Antes/11981.jpeg', N'A chapa de aquecimento não tinha sinalização sobre o limite da área útil. O problema era mais crítico na parte dos fundos da chapa, onde a visibilidade já se torna comprometida Isso fazia com que os beckeres fossem posicionados em locais frios ou de baixa transferência térmica, comprometendo a preparação adequada das amostras.', N'01 - Imagens/02 - Depois/11981.jpeg', N'As bordas da área de aquecimento foram pintadas com tinta resistente ao calor. A demarcação delimita a região quente da chapa, permitindo o posicionamento correto dos beckeres e garantindo a aquecimento correto das amostras .', NULL, N'Sim, a marcação pintada na chapa orienta o posicionamento correto dos beckeres dentro da área de aquecimento, garantindo a transferência de calor adequada para o preparo das amostras.', N'Soluções simples e mais visuais melhoram a rotina de trabalho.', 0, NULL, N'Aumento da da confiabilidade e segurança operacional para os ativos. 
INSERT INTO #PVC VALUES (11982, N'1015393', N'1015393', N'Auxiliary Air Hose Storage', 3, N'No Replication/Sem replicação', N'No extra air hoses for utility purposes on hand. In the occurrence a utility hose is damaged or an extra is needed, there are no spares.', N'Have air hoses stored and ready for use in area without having to search and or order. Makes replacing a damaged air hose in field faster and more efficient.', N'0', N'01 - Imagens/01 - Antes/11982.jpeg', N'No spare hoses readily available in field area.', N'01 - Imagens/02 - Depois/11982.jpeg', N'Extra hoses ordered and storage hooks installed in compressor room area. Allowing for spares to be stored in area with no wait time.', NULL, N'Yes', N'Organization/Spares', 0, NULL, NULL, '2026-08-26T00:00:00.000', '2026-08-27T22:47:30.000', N'1015393', NULL, NULL);
INSERT INTO #PVC VALUES (11983, N'492584', N'81009651', N'IDENTIFICAÇÃO', 1, N'Others/Outros', N'Válvulas e mangueira sem identificação, dificultando identificação em momentos de intervenção/manutenção e manobras de controle do processo.', N'Rápida identificação e segurança', N'10054', N'01 - Imagens/01 - Antes/11983.jpeg', N'Válvulas e mangueira sem identificação, dificultando identificação em momentos de intervenção/manutenção e manobras de controle do processo.', N'01 - Imagens/02 - Depois/11983.jpeg', N'Com identificação temos mais celeridade na identificação, contribuindo para intervenção mais seguras e rápidas tomadas de ações e controle no processo.', NULL, N'SIM!
INSERT INTO #PVC VALUES (11984, N'1008382', N'1008382', N'Flash cooler pressure indicator flush ', 2, N'Others/Outros', N'Flash cooler pressure indicator on cone requires flushing to give proper level indication. These pressure indicators are difficult to access without scaffold. ', N'Make flushing level indicators easier and safer so that they can be done more often and reduce downtime due to level indicator issues.  ', N'0', N'01 - Imagens/01 - Antes/11984.jpeg', N'Flush point for pressure indicator difficult to access ', N'01 - Imagens/02 - Depois/11984.jpeg', N'Addition of hose with valve allows flush point on flash cooler to remain open and operator to easily flush pressure/level indicator safely and with much better ergonomics. This was done on both flash coolers. ', NULL, N'Yes, flushing can be done more easily and safely. ', N'If the point of work creates a hazard, relocate if possible. ', 0, NULL, NULL, '2026-07-05T00:00:00.000', '2026-08-28T03:26:06.000', N'1008382', NULL, NULL);
INSERT INTO #PVC VALUES (11985, N'1015684', N'1015684', N'Pipe Clamp Storage Area', 3, N'Refining/Refino', N'There was no supply of pipe clamps at Port. If a line started to leak there was no way to quickly and safely seal up the actively leaking line.', N'To have a supply of a variety of sizes of pipe clamps at Port to safely and quickly be able to stop leaks.', N'0', N'01 - Imagens/01 - Antes/11985.jpeg', N'There was no supply of pipe clamps at Port. If a line started to leak there was no way to quickly and safely seal up the actively leaking line.', N'01 - Imagens/02 - Depois/11985.jpeg', N'Ordered a variety of different size pipe clamps and created a proper storage area for them. Clamps are now available in all sizes when needed.', NULL, N'Yes, Pipe clamps are now available when needed and stored using proper 5S techniques.', N'Having proper supply of clamps available will cut down on time spent looking across site and having an active leak.', 0, NULL, N'Com a adequação realizada no PIT do Moinho 02, espera-se garantir acesso seguro, rápido e desobstruído às válvulas manifold dos transmissores de pressão diferencial, facilitando as atividades de operação, inspeção, calibração e manutenção.', '2026-08-27T00:00:00.000', '2026-08-28T03:41:24.000', N'1015684', NULL, NULL);
INSERT INTO #PVC VALUES (11986, N'81013118', N'81013118', N'pugmill anolyte fill SP change', 1, N'Refining/Refino', N'pugmill wasn''t filling up quickly enough', N'increase fill setpoint', N'0', N'01 - Imagens/01 - Antes/11986.jpeg', N'pugmill fill setpoint was at a hi hi of 80 M3 ', N'01 - Imagens/02 - Depois/11986.jpeg', N'got DCS support to increase it to 100 M3', NULL, N'yes', N'faster processing of WLN solution ', 0, NULL, N'- Redução de subjetividade na
INSERT INTO #PVC VALUES (11987, N'1015684', N'1015684', N'Grip tape storage', 2, N'Refining/Refino', N'Grip tape is necessary for use on ladder rungs at Port. There was no supply for reapplying the tape as needed. What grip tape there was had no designated storage area.', N'To have grip tape on hand for when it is needed to reapply to ladder rungs, and also stored in a proper location.', N'0', N'01 - Imagens/01 - Antes/11987.jpeg', N'Grip tape is necessary for use on ladder rungs at Port. There was no supply for reapplying the tape as needed. What grip tape there was had no designated storage area.', N'01 - Imagens/02 - Depois/11987.jpeg', N'Ordered a supply and designated a proper storage location for grip tape. It is now at the ready when needed to be reapplied to ladder rungs at Port.', NULL, N'Yes, grip tape now has a designated home and is ready when needed.', N'Having proper storage location for items makes it easier for everyone to use them.', 0, NULL, N'Melhorar o tempo de resposta das amostras, realizar as coletas dentro prazo planejado evitando desvios e garantido a integridade  da amostra.', '2026-08-27T00:00:00.000', '2026-08-28T03:46:38.000', N'1015684', NULL, NULL);
INSERT INTO #PVC VALUES (11988, N'1008427', N'1008427', N'New Value Handles for Flash Cooler System', 1, N'Refining/Refino', N'Operating Valve handles around the Flash Cooler has been a pain point for some while due to the make of the previous stock ones consistently breaking. This led to countless isolation delays and overall safety issues due to not always having a usable handle available to swing a valve if need', N'Enable more efficient operation of valves by fabricating multiple handles to replace broken ones', N'10003', N'01 - Imagens/01 - Antes/11988.jpeg', N'Stock Handles were of very poor quality. With the majority of them cracked and unusable. This would lead to major delays to isolations due to tracking down a functional handle or if both coolers needed to come down at once, simply not having enough to complete the job efficiently', N'01 - Imagens/02 - Depois/11988.jpeg', N'Fabricated multiple handles that would replace the previous ones and have an inventory in the event that more break in the future. Suggested that if the 3D Printed version of the handles doesn''t hold up, to have them fabricated with a suitable metal', NULL, N'3D Printed Handled will do the job of the previous stock handles while saving money by not having to go through the vendor for more', N'We should have inventory for all valve handles', 1000, 3, NULL, '2026-08-27T00:00:00.000', '2026-08-28T03:49:47.000', N'1008427', NULL, NULL);
INSERT INTO #PVC VALUES (11989, N'81039896', N'81039896', N'Low Level Notice (Floc Dilution)', 1, N'Others/Outros', N'Floc Dilution is not on a main screen we use on the control panel, and it did not have a Lo Limit. When it hit its Lolo, it immediately shut down our pumps. ', N'Stop our pumps from randomly shutting down', N'0', N'01 - Imagens/01 - Antes/11989.jpeg', N'When the Floc Dilution tank got to its LoLo Limit, it automatically tripped. There was no notice before to catch it. Right now, we are using a "helper hose" to maintain tank levels, which requires a technician to be in field to adjust the hose. If we had a Lo Limit that gave us a warning, we could have a tech adjust flows before it tripped the pumps. ', N'01 - Imagens/02 - Depois/11989.jpeg', N'After adding a Lo Limit notice for the tank level, we are now able to get a technician in field to adjust the flow going into the tank before the pumps trip. ', NULL, N'Yes, we are now able to adjust the flow before our pumps trip. ', N'Giving notice to low limits avoid us losing pumps', 0, NULL, N'Atividades de movimentação de equipamentos em condições seguras.', '2026-06-23T00:00:00.000', '2026-08-28T07:16:45.000', N'81039896', NULL, NULL);
INSERT INTO #PVC VALUES (11990, N'81058966', N'81030439', N'Substituição de válvula com proteção. CI-2017-2 letra A', 1, N'Others/Outros', N'A válvula antiga não tinha proteção na guilhotina que estava exposta podendo vir a ocasionar um acidente. CI-2017-2 letra A
INSERT INTO #PVC VALUES (11991, N'81058966', N'81010548', N'Foi substituído por uma válvula superior que possui proteção diminuindo o risco drasticamente.', 1, N'Others/Outros', N'Durante uma manutenção a válvula de aperto manual travou e ela dependia de muita força física pra abri-la. BQ-2022-01
INSERT INTO #PVC VALUES (11992, N'81058966', N'473401', N'Fabricação de Suporte para kit de mitigação', 1, N'Others/Outros', N'Foi identificada a necessidade de um suporte adequado para acondicionamento e organização dos materiais utilizados durante as atividades.', N'Fabricar um suporte adequado para melhorar a organização dos materiais, facilitar o acesso e proporcionar melhores condições de segurança e ergonomia durante as atividades.', N'10031', N'01 - Imagens/01 - Antes/11992.jpeg', N'Não havia um suporte adequado para acondicionamento dos materiais, dificultando a organização e o acesso durante a execução das atividades.', N'01 - Imagens/02 - Depois/11992.jpeg', N' fabricação e instalação de um suporte específico, proporcionando melhor organização e acondicionamento dos materiais, melhorando as condições ergonômicas e de segurança no local.', NULL, N'sim, melhorou a organização do local.', N'A identificação de oportunidades de melhoria no local de trabalho permite desenvolver soluções simples e eficientes, contribuindo para a organização, ergonomia e segurança das atividades.', 0, NULL, NULL, '2026-08-07T00:00:00.000', '2026-08-28T10:00:51.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (11993, N'81015749', N'81015749', N'Revisão de Estratégia - Alteração de Manutenção Sistemática para Manutenção Condicional ', 1, N'No Replication/Sem replicação', N'Cubos de roda dos caminhões rodoviários eram substituídos de forma sistemática a cada 4.000h, com muitos desses itens ainda em boas condições representando um custo desnecessário realizado. ', N'Diminuir o custo de manutenção sistemática através da revisão da ', N'10015', N'01 - Imagens/01 - Antes/11993.jpeg', N'Substituição sistemática para os equipamentos (CV39,CV45,CV46,CV48,CV58,CV64,CV65) dos cubos de roda dianteiro e traseiro a cada 4.000h. Para caminhões do modelo G440, o custo de manutenção com materiais é estimado em R$ 104.644,96 , já para o modelo G450 é de R$ 108.945,04. 
INSERT INTO #PVC VALUES (11994, N'81015749', N'81015749', N' Implementação de Inspeções Estruturais Periódicas nos Tanques dos Comboios de Abastecimento ', 1, N'Open Pit/Poço aberto', N'Conforme previsto no artigo 11 do Regulamento para o Transporte Rodoviário de Produtos Perigosos – RTPP (Resolução ANTT nº 5.848/2019), é necessário que o implemento dos caminhões comboios sejam inspecionados, periodicamente, por profissional qualificado atestando a integridade estrutural do tanque. Os caminhões comboio de Salobo só eram avaliados por profissionais não certificados de forma visual para avaliar a condição estrutural do tanque. ', N'Aumentar a segurança operacional de atividades envolvendo comboios de Abastecimento ', N'10015', N'01 - Imagens/01 - Antes/11994.jpeg', N'Inexistência de processo estruturado para monitoramento da integridade estrutural dos comboios de abastecimento mediante ensaios não destrutivos, limitando a identificação preventiva de desgaste e potenciais eventos indesejados. 
INSERT INTO #PVC VALUES (11995, N'81054419', N'81054419', N'Extensão de Vida Útil do Motor Diesel da Perfuratriz PZ44', 1, N'Underground/Subterrâneo', N'A substituição de componentes com base apenas na vida recomendada pelo fabricante gerava trocas prematuras e perda de valor dos ativos. Havia a necessidade de validar, por meio de técnicas preditivas, o potencial de extensão de vida útil de componentes críticos, reduzindo custos sem comprometer a confiabilidade operacional.', N'Aumento de 10% a 20% de vida útil', N'10015', N'01 - Imagens/01 - Antes/11995.jpeg', N'A gestão de componentes baseada na vida nominal resultando em substituições preventivas de itens com boas condições de operação. Esse cenário limita a vida útil remanescente e aumenta os custos', N'01 - Imagens/02 - Depois/11995.jpeg', N'Motor Diesel DR416i (PZ44): Extensão de vida útil de 19% com suporte de análise de óleo e monitoramento de contaminação, postergando a substituição para 15.436 h sem registros de alertas críticos, com ganho estimado de R$ 813 mil.', NULL, N'A meta de validar a extensão segura da vida útil de componentes críticos foi alcançada, resultando em ganhos de 19% vida útil e aproximadamente R$813 mil em captura de valor, reduzindo substituições prematuras sem impactos na confiabilidade operacional.', N'A gestão baseada na condição dos ativos, suportada por técnicas preditivas e atuação integrada das equipes, demonstrou potencial para ampliar a vida útil de componentes de forma segura, confiável e economicamente vantajosa.', 813000, 1, N'Conseguimos tira as pessoas da linha de 
INSERT INTO #PVC VALUES (11996, N'81011133', N'81044230', N'Controle de solicitações obsolescência/descarte de saldo', 1, N'Others/Outros', N'Falta de consolidação de todas as solicitações', N'Controle de solicitações obsolescência/descarte de saldo', N'10079', N'01 - Imagens/01 - Antes/11996.jpeg', N'Todo controle era realizado por emails que geravam apenas volume e várias etapas de processo.', N'01 - Imagens/02 - Depois/11996.jpeg', N'Toda solicitação de obsolescência é avaliada pelo gestor de estoque, coletado o de acordo gerencial e registrado no apps dentro de um padrão para Ana seguir com o fluxo de obsolescência junto as evidências. Quando registrado no apps ele realiza uma cópia dos arquivos e das evidencias, para futuras auditorias/necessidade de consulta.', NULL, N'Problema resolvido, agora temos um controle consolidado', N'consolidação das informações e rastreabilidade', 0, NULL, N'Conseguimos tira as pessoas da linha de 
INSERT INTO #PVC VALUES (11997, N'81054419', N'81054419', N'Extensão de Vida Útil do Diferencial do Caminhão CA310', 1, N'Underground/Subterrâneo', N'A substituição de componentes com base apenas na vida recomendada pelo fabricante gerava trocas prematuras e perda de valor dos ativos. Havia a necessidade de validar, por meio de técnicas preditivas, o potencial de extensão de vida útil de componentes críticos, reduzindo custos sem comprometer a confiabilidade operacional.', N'Aumento de vida útil de 20% a 25%', N'10015', N'01 - Imagens/01 - Antes/11997.jpeg', N'Trocas realizadas por vida nominal, sem suporte estruturado da condição real do componente, ocasionando substituições prematuras, aumento de custos e perda de potencial de extensão de vida útil.', N'01 - Imagens/02 - Depois/11997.jpeg', N'Extensão de vida útil de 21% baseada em análise de óleo e acompanhamento das condições permitindo operação até 32.682 h sem níveis excessivos de contaminação, gerando ganho estimado de R$ 163 mil.', NULL, N'A meta de validar a extensão segura da vida útil de componentes críticos foi alcançada, resultando em ganhos de 21% de vida útil e aproximadamente R$ 163 mil em captura de valor, reduzindo substituições prematuras sem impactos na confiabilidade operacional.', N'A gestão baseada na condição dos ativos, suportada por técnicas preditivas e atuação integrada das equipes, demonstrou potencial para ampliar a vida útil de componentes de forma segura, confiável e economicamente vantajosa.', 163000, 1, N'Maior controle da vida das esteira utilizadas e mais insumo para tomadas de decisões estratégicas.', '2026-08-27T00:00:00.000', '2026-08-28T11:22:43.000', N'81054419', NULL, NULL);
INSERT INTO #PVC VALUES (11998, N'81057208', N'81057208', N'INSTALAÇÃO DE MANIFOLD NOS PIT`s do MOINHO 02. ', 1, N'Others/Outros', N'O acesso às válvulas manifold dos transmissores de pressão diferencial do PIT do Moinho 02 era inadequado devido ao posicionamento do conjunto de instrumentação em uma região com interferências estruturais. Essa condição dificultava a operação das válvulas, a execução de calibrações, inspeções e manutenções preventivas e corretivas, exigindo maior esforço dos profissionais e aumentando o tempo de intervenção. Além disso, a limitação de espaço comprometia a ergonomia e a segurança das atividades, elevando o risco de danos aos componentes e de dificuldades durante manobras operacionais. Após a adequação realizada, o conjunto passou a apresentar melhor acessibilidade, proporcionando condições mais seguras e eficientes para as atividades de manutenção e operação', N'Eliminar interferências estruturais que dificultavam o acesso às válvulas manifold.', N'10178', N'01 - Imagens/01 - Antes/11998.jpeg', N'A válvula manifold dos transmissores apresenta acesso restrito em função da sua instalação em área confinada entre a estrutura metálica de sustentação e a grade de proteção. O reduzido espaço operacional dificulta a atuação dos técnicos durante intervenções de manutenção e calibração.', N'01 - Imagens/02 - Depois/11998.jpeg', N'O reposicionamento do conjunto de transmissores e válvulas manifold no PIT do Moinho 02 Salobo 03 proporcionou acesso facilitado para operação e manutenção. As válvulas encontram-se totalmente visíveis e com espaço adequado para atuação manual, permitindo a execução das atividades de bloqueio, equalização, inspeção e calibração de forma mais segura e eficiente.', NULL, N'O problema foi resolvido com sucesso por meio do reposicionamento do conjunto de instrumentação, proporcionando acesso livre e adequado às válvulas manifold do PIT do Moinho 02.', N'Condições ergonômicas adequadas contribuem para a redução do esforço físico dos mantenedores e minimizam riscos de acidentes.', 0, NULL, N'Foi reduzido o risco de contato acidental com componentes elétricos, prevenindo possíveis choques elétricos, curtos-circuitos e outros acidentes.', '2026-08-24T00:00:00.000', '2026-08-28T11:37:05.000', N'81057208', NULL, NULL);
INSERT INTO #PVC VALUES (11999, N'81046238', N'81046238', N'Redução de 83,3% do tempo de análise da qualidade das emissões de Melhorias ', 1, N'Others/Outros', N'Itens qualitativos
INSERT INTO #PVC VALUES (12000, N'81043724', N'81043724', N'RAC 02 EXPRESS ', 1, N'Open Pit/Poço aberto', N'Falta de HEADCOUNT para distribuição de atividades. Com isso provoca atraso na coleta dos filtros e na demanda que está sendo executada. Tendo em vista os frequentes atrasos e as paradas durante a produção. Exemplo saída para coletas na filtragem. Devido a quantidade de pessoas mapeadas em RAC 02 que no momento atual é de uma pessoa.  ', N'Melhorar o tempo de resposta das amostras, evitar insatisfação dos clientes, parada de caminhões na logística, evitar impacto no navio , fazendo a coleta no tempo planejado e evita desvios na amostra. ', N'10032', N'01 - Imagens/01 - Antes/12000.jpeg', N'Falta de HEADCOUNT para distribuição de atividades logística. Com isso provoca atraso na coleta dos filtros e na demanda que está sendo executada. Tendo em vista as frequentes paradas e a necessidade de otimização de tempo. Exemplo saída para coletas na filtragem. Devido a quantidade de pessoas mapeadas em RAC 02 que no momento atual é de uma pessoa. ', N'01 - Imagens/02 - Depois/12000.jpeg', N'Treinar um numero maior de pessoas em RAC 02,hoje temos a opção da equipe ( TOP GEO).', NULL, N'Garantir qualidade nas entregas ao nossos clientes, otimizando nosso tempo  e seguindo nossas demanda conforme PRO.', N'Otimização do tempo, aproveitando nossas ferramentas disponíveis e mão de obra que são as pessoas da áreas.', 0, NULL, N'Forma mais interativa e lúdica de repassar informação dos PROs.', '2026-08-27T00:00:00.000', '2026-08-28T12:32:17.000', N'81043724', NULL, NULL);
INSERT INTO #PVC VALUES (12001, N'81057254', N'81057254', N'Otimização de Lubrificante com redução de custo de R$ 928 Mil/Ano', 1, N'Others/Outros', N'Os sistemas de lubrificação dos moinhos de bolas do Salobo III utilizavam óleo sintético CLP ISO VG 460 à base de PAO, com custo unitário de R$ 55,03/L, embora as condições operacionais do equipamento não exigissem esta especificação.
INSERT INTO #PVC VALUES (12002, N'81045885', N'81045885', N'SUPORTE PARA IÇAMENTO E TRANSPORTE   ', 2, N'Others/Outros', N'As movimentações dos equipamentos eram realizadas de forma insegura, devido à inexistência de um dispositivo adequado para o transporte  comprometendo a segurança e a eficiência das atividades de movimentação.', N'Possibilitar o transporte do eixo e do rotor das células de flotação do Salobo 3, garantindo condições adequadas de movimentação, acondicionamento e envio dos equipamentos com segurança e integridade.', N'10293', N'01 - Imagens/01 - Antes/12002.jpeg', N'As movimentações dos equipamentos eram realizadas de forma insegura, devido à inexistência de um dispositivo adequado para o transporte  comprometendo a segurança e a eficiência das atividades de movimentação.', N'01 - Imagens/02 - Depois/12002.jpeg', N'Operação de içamento e transporte, garantindo condições adequadas de movimentação, acondicionamento e envio dos equipamentos com segurança e integridade.', NULL, N'Diminuição do tempo na atividade de movimentação do equipamento', N'Dar maior atenção às operações de transporte de equipamentos, garantindo que sejam realizadas de forma segura, padronizada e eficiente, reduzindo a exposição dos colaboradores a riscos e assegurando a integridade dos componentes durante toda a movimentação', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVEIS.', '2026-08-19T00:00:00.000', '2026-08-28T14:50:17.000', N'81045885', NULL, NULL);
INSERT INTO #PVC VALUES (12003, N'92000519', N'92000519', N'Fluxo projetos estruturais dos embarcados de Mina ', 1, N'Projects/Projetos', N'Atualmente, as solicitações de projetos estruturais para embarcados dos equipamentos de mina são realizadas sem um fluxo padronizado, resultando em retrabalhos, falta de informações técnicas, dificuldades na priorização das demandas, atrasos nas aprovações e baixa rastreabilidade do processo. Essa condição impacta diretamente os prazos de execução, a disponibilidade dos equipamentos e a eficiência das equipes envolvidas.', N'Padronizar e otimizar o processo de solicitação, análise, priorização e desenvolvimento de projetos estruturais para sistemas embarcados dos equipamentos de mina, garantindo maior agilidade, rastreabilidade, qualidade técnica e redução do tempo de atendimento das demandas', N'10015', N'01 - Imagens/01 - Antes/12003.jpeg', N'As solicitações de projetos estruturais para embarcados de equipamentos de mina eram realizadas sem um fluxo padronizado, gerando falta de informações técnicas, dificuldades de rastreabilidade, atrasos e retrabalhos. A ausência de critérios definidos para abertura das demandas resultava em projetos elaborados com especificações incompletas, sem definição adequada de cargas, condições operacionais, requisitos de resistência estrutural e fatores de segurança. Como consequência, ocorria aumento do tempo de atendimento, revisões frequentes de projeto e riscos à confiabilidade das soluções implementadas.', N'01 - Imagens/02 - Depois/12003.jpeg', N'Foi desenvolvido e implementado um fluxo padronizado para solicitação de projetos estruturais dos embarcados de equipamentos de mina, definindo etapas, responsáveis e requisitos mínimos de entrada. O processo passou a exigir informações técnicas padronizadas, incluindo condições operacionais, cargas atuantes, critérios de resistência estrutural, fatores de segurança e demais premissas de engenharia. A melhoria proporcionou maior rastreabilidade das demandas, redução de retrabalhos, melhor priorização dos projetos, aumento da qualidade técnica das soluções desenvolvidas e maior confiabilidade das estruturas implementadas. ', NULL, N'SIM. O problema foi mitigado com a implementação de um fluxo padronizado que garante o envio das informações técnicas necessárias, critérios de resistência estrutural e rastreabilidade das demandas, reduzindo retrabalhos e aumentando a qualidade dos projetos.', N'A definição de requisitos técnicos e a padronização do fluxo aumentam a qualidade dos projetos, reduzem retrabalhos e melhoram a rastreabilidade das demandas.', 0, NULL, N'TEMOS TAMBEM MELHORA NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVEL.', '2026-08-14T00:00:00.000', '2026-08-28T14:54:45.000', N'92000519', NULL, NULL);
INSERT INTO #PVC VALUES (12004, N'81004462', N'81004462', N'Otimização de Estratégia de Manutenção', 1, N'Smelting/Fundição', N'Frota de escavadeiras Hidráulicas Komatsu PC5500 estavam com Planos Preventivos com custo elevados e tempos de parada impactando disponibilidade física devido ao elevado número de horas de manutenção preventiva.', N'Redução de custo e aumento de DF', N'10015', N'01 - Imagens/01 - Antes/12004.jpeg', N'Tempo elevado de preventiva em todos os ciclos, impactando a DF da frota. Além disso, 46% das atividades dos planos eram sistemáticas, ampliando o tempo de parada e elevando os custos de manutenção preventiva, que estavam previstos em R$ 741,8 mil para os ciclos de Setembro a Dezembro de 2026.
INSERT INTO #PVC VALUES (12005, N'81057254', N'81057254', N'Redução de 63% do custo de abastecimento do óleo lubrificante do Moinho de Bolas 2 SLB III ', 1, N'Others/Outros', N'Especificação incorreta do lubrificante para aplicação no sistema de lubrificação dos moinhos de bola do SLB3, causando alto custo de manutenção e degradação da vedação por incompatibilidade', N'Reduzir em 50% o custo de abastecimento do óleo do moinho', N'10293', N'01 - Imagens/01 - Antes/12005.jpeg', N'Especificação incorreta do lubrificante para aplicação no sistema de lubrificação dos moinhos de bola do SLB3, causando alto custo de manutenção e degradação da vedação por incompatibilidade.
INSERT INTO #PVC VALUES (12006, N'81061965', N'81061965', N'Otimização dos Planos Preventivos e Listas Técnicas da Frota 830E', 1, N'Others/Outros', N'Os planos preventivos da frota 830E continham materiais e operações que não eram executados durante as manutenções programadas. O filtro secador SAP 15286420 estava previsto para troca nos ciclos de 1.000h, 5.000h e 10.000h, embora sua substituição ocorra apenas em revisões do sistema de ar condicionado ou troca do compressor. Adicionalmente, o material SAP 15394440 (Adaptador PB5557 Komatsu) permanecia vinculado às listas de tarefas mesmo sem utilização nas preventivas. Essa condição gerava desperdícios, reservas desnecessárias de materiais e baixa aderência entre planejamento e execução.', N'Eliminar/modificar materiais e atividades sem aplicação prática dos planos preventivos da frota 830E, reduzindo desperdícios, aumentando a aderência dos planos à manutenção executada e otimizando a gestão de materiais no SAP.', N'#N/A', N'01 - Imagens/01 - Antes/12006.jpeg', N'O filtro secador SAP 15286420 estava previsto para substituição nos planos preventivos da frota 830E (1.000h, 5.000h e 10.000h), porém sua troca não era realizada nessas intervenções, ocorrendo apenas em revisões do sistema ou substituição do compressor. Isso gerava previsão de materiais e atividades que não eram executadas.
INSERT INTO #PVC VALUES (12007, N'81056513', N'81047889', N'SUPORTE CINTO DE SEGURANÇA', 3, N'Others/Outros', N'Cintos de segurança ficavam no chão', N'ORGANIZAÇÃO 5S', N'10324', N'01 - Imagens/01 - Antes/12007.jpeg', N'Cintos de segurança ficavam no chão', N'01 - Imagens/02 - Depois/12007.jpeg', N'Foi criado e aplicado suporte para armazenar e manter cintos organizados seguindo padrão 5s', NULL, N'Agora container esta organizado', N'5s e padronização', 0, NULL, N'TEMOS TAMBEM NO ASPECTO DE SEGURANÇA EM QUE FALHAS PO IDENTIFICAÇÃO INCORRETA SE TORNA MUINTO MENOS IMPROVAVEIS.', '2026-08-27T00:00:00.000', '2026-08-28T15:32:57.000', N'81056513', NULL, NULL);
INSERT INTO #PVC VALUES (12008, N'524616', N'524616', N'Monitoramento online do sistema hidráulico da PZ02.', 2, N'Others/Outros', N'Eliminar a necessidade de exposição dos técnicos aos riscos operacionais durante a coleta de vibração, por meio da substituição das medições presenciais no componente por tecnologias de monitoramento mais seguras.', N'Retirar as pessoas da exposição ao risco ao realizar atividade de coleta de vibração na máquina.', N'10024', N'01 - Imagens/01 - Antes/12008.jpeg', N'A coleta de vibração era realizada manualmente, utilizando sensor portátil aplicado diretamente nos pontos de medição da cabeça rotativa. Para execução da atividade, o técnico necessitava acessar fisicamente o equipamento em operação, posicionar o sensor em cada ponto de coleta e aguardar individualmente a aquisição dos dados. Esse processo demandava maior tempo de inspeção, deslocamentos frequentes em área operacional e exposição dos profissionais aos riscos inerentes à atividade.', N'01 - Imagens/02 - Depois/12008.jpeg', N'Foi implantado o sistema de monitoramento online por meio de sensores fixos, possibilitando o acompanhamento contínuo da condição dos componentes em tempo real. A solução reduziu a necessidade de coletas manuais em campo, minimizou a exposição dos profissionais aos riscos operacionais e proporcionou maior rapidez na identificação de anomalias e na tomada de decisões de manutenção.', NULL, N'Sim, conseguimos tira as pessoas da 
INSERT INTO #PVC VALUES (12009, N'524616', N'524616', N'Monitoramento online do compressor da PZ02.', 2, N'Others/Outros', N'Reduzir a exposição de pessoas a riscos operacionais, eliminando a necessidade de acesso físico ao componente para realização das coletas de vibração.', N'Retirar as pessoas de exposição do risco ao realizar a coleta de vibração no equipamento.', N'10024', N'01 - Imagens/01 - Antes/12009.jpeg', N'O monitoramento de vibração era executado por meio de coletas manuais com sensor portátil, exigindo acesso direto aos pontos de medição do componente durante sua operação. A atividade requeria a presença do técnico em campo para posicionamento do sensor e aquisição individual dos dados, resultando em maior tempo de execução, aumento da exposição a riscos operacionais e limitação da frequência de monitoramento do ativo.', N'01 - Imagens/02 - Depois/12009.jpeg', N'Foi implantado o sistema de monitoramento online por meio de sensores fixos, possibilitando o acompanhamento contínuo da condição dos componentes em tempo real. A solução reduziu a necessidade de coletas manuais em campo, minimizou a exposição dos profissionais aos riscos operacionais e proporcionou maior rapidez na identificação de anomalias e na tomada de decisões de manutenção.', NULL, N'Sim, conseguimos tira as pessoas da 
INSERT INTO #PVC VALUES (12010, N'81015244', N'81015244', N'Reporte de Controle de Vida de Esteiras', 1, N'Open Pit/Poço aberto', N'Atualmente estávamos sem um reporte da vida/previsibilidade das esteiras dos tratores de esteira; assim as esteiras estávamos perdendo a confiabilidade no planejamento preventivo de substituições.', N'Aumento de confiabilidade, controle de vida, previsibilidade de troca.', N'10154', N'01 - Imagens/01 - Antes/12010.jpeg', N'Não havia um reporte com o controle de vida.', N'01 - Imagens/02 - Depois/12010.jpeg', N'Com o controle de vida, tem-se uma maior confiabilidade para planejar a substituição das esteiras do tratores de esteira, o controle de inspeções e definição de ações sobre o equipamento está apresentando uma maior taxa de desgaste.', NULL, N'Sim, agora temos um maior controle da vida das esteira utilizadas e mais insumo para tomadas de decisões estratégicas.', N'Controle aumenta a confiabilidade da tomada de ações', 0, NULL, NULL, '2026-08-25T00:00:00.000', '2026-08-28T17:21:12.000', N'81015244', NULL, NULL);
INSERT INTO #PVC VALUES (12011, N'521673', N'521673', N'Porta cadeado para a porta do pulverizador', 1, N'No Replication/Sem replicação', N'A porta do pulverizador que fica os comandos eletricos permanecia aberta, com toda a fiação exposta, deixando o empregado em situação de risco durante a operação do equipamento.', N'Manter a porta fechada e garantir a segurança durante a atividade', N'10032', N'01 - Imagens/01 - Antes/12011.jpeg', N'Foi constatado que a porta do pulverizador onde fica os comados do equipamento, permanecia aberta durante a operação do equipamento, deixando toda a fiação elétrica interna exposta. Essa condição comprometia a integridade dos dispositivos de proteção e aumentava significativamente o risco de acidentes, uma vez que o empregado ficava suscetível ao contato acidental com componentes elétricos energizados. Além do risco de choque elétrico, a situação poderia ocasionar curtos-circuitos, danos ao equipamento e interrupções operacionais. A exposição da fiação também favorecia o acúmulo de poeira, umidade e outros agentes externos, agravando as condições de segurança.', N'01 - Imagens/02 - Depois/12011.jpeg', N'Como medida corretiva, foi instalado um porta-cadeado no sistema de fechamento da porta do pulverizador, permitindo que ela permanecesse devidamente fechada e travada durante a operação do equipamento. A implementação dessa proteção eliminou a exposição da fiação elétrica interna, restabelecendo as condições seguras de utilização do equipamento.', NULL, N'A integridade física dos operadores e demais empregados que atuam nas proximidades do equipamento passou a ser adequadamente protegida, garantindo maior segurança durante as atividades operacionais.', N'Segurança em primeiro lugar', 0, NULL, NULL, '2026-08-25T00:00:00.000', '2026-08-28T17:34:31.000', N'521673', NULL, NULL);
INSERT INTO #PVC VALUES (12012, N'538696', N'538696', N'Concentra ', 1, N'Concentration/Concentração', N'Com a implementação do novo cenário operacional da usina, com by-pass na moagem durante a etapa de clinquerização, observou-se redução do volume mássico na alimentação e nos circuitos subsequentes. Após testes e análises, verificou-se baixa eficiência operacional das colunas de flotação, sem geração de produção no circuito.', N'Aumentar produção', N'10054', N'01 - Imagens/01 - Antes/12012.jpeg', N'Com a implementação do novo cenário operacional da usina, com by-pass na moagem durante a etapa de clinquerização, observou-se redução do volume mássico na alimentação e nos circuitos subsequentes. Após testes e análises, verificou-se baixa eficiência operacional das colunas de flotação, sem geração de produção no circuito.', N'01 - Imagens/02 - Depois/12012.jpeg', N'Implementou-se nova lógica operacional no circuito Cleaner, restringindo a alimentação a uma única coluna de flotação, devido à baixa geração de sólidos no circuito, insuficiente para a operação com mais de uma coluna. Após a implementação, verificou-se melhoria na cinética de flotação e incremento na produção.', NULL, N'Zero produção com 3 ou 2 colunas.
INSERT INTO #PVC VALUES (12013, N'81015244', N'365759', N'Novo Padrão de Treinamento em PROs', 1, N'Open Pit/Poço aberto', N'As pessoas eram treinadas nos PROs e muitas vezes faltava imersão, onde tinha muita escrita para ser explicado ao executante.', N'Criar um padrão imersivo para documentos de treinamento em PRO ', N'10154', N'01 - Imagens/01 - Antes/12013.jpeg', N'Antes os executantes eram treinados diretamente no documento do PRO onde há de muitas páginas escritas, exigindo maior interação do palestrante por não chamar tanto a atenção.', N'01 - Imagens/02 - Depois/12013.jpeg', N'Com o novo padrão, o treinamento é mais imersivo, em formato mais atual dos treinamentos técnicos, onde o palestrante consegue de forma mais lúdica repassar a informação/conhecimento aos colaboradores.', NULL, N'Melhora no modelo de treinamento em PRO.', N'Forma mais andragógica de repassar conhecimento', 0, NULL, NULL, '2026-08-27T00:00:00.000', '2026-08-28T21:53:29.000', N'81015244', NULL, NULL);
INSERT INTO #PVC VALUES (12014, N'1015684', N'1015684', N'Tripper Conveyor Battery Lights', 2, N'Refining/Refino', N'The top of the tripper conveyor is very dark, and workers have issues seeing what they are doing during cleaning operations at various locations.', N'To have additional mobile lighting available around the tripper conveyor area.', N'0', N'01 - Imagens/01 - Antes/12014.jpeg', N'The top of the tripper conveyor is very dark, and workers have issues seeing what they are doing during cleaning operations at various locations.', N'01 - Imagens/02 - Depois/12014.jpeg', N'Procured battery powered lights and stored them in a cabinet at the Tripper conveyor level. Workers now have the ability to move lighting to wherever they need it when working in the area.', NULL, N'Yes, additional mobile lighting is now available at the top of 211.', N'Having mobile lighting makes working in the area safer.', 0, NULL, N'Feito melhoria para melhor adequação.', '2026-08-28T00:00:00.000', '2026-08-29T02:01:41.000', N'1015684', NULL, NULL);
INSERT INTO #PVC VALUES (12015, N'81034776', N'81034776', N'IDENTIFICAÇÃO MOTORES SLB III', 1, N'Others/Outros', N'FALTA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'10329', N'01 - Imagens/01 - Antes/12015.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST003-M1 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/12015.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST003-M1 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA,TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS,CRIANDO UM AMBIENTE MAS CONFORTAVEL PARA A EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM.COM MELHORIA REALIZADA NO MO-2305SA-01-ST003-M1 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA,TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS,CRIANDO UM AMBIENTE MAS CONFORTAVEL PARA A EXECUÇÃO DE ATIVIDADES.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, N'Os colegas que executavam essa atividade manualmente podem usar desse HH disponível para dedicarem-se a outras atividades.', '2026-08-27T00:00:00.000', '2026-08-29T04:24:06.000', N'81034776', NULL, NULL);
INSERT INTO #PVC VALUES (12016, N'81034776', N'81034776', N'IDENTIFICAÇÃO DE MOTORES SLB III', 1, N'Others/Outros', N'FALHA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'10329', N'01 - Imagens/01 - Antes/12016.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST003-M2 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/12016.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST003-M2 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA,TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS,CRIANDO UM AMBIENTE MAS CONFORTAVEL PARA A EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM.COM MELHORIA REALIZADA NO MO-2305SA-01-ST003-MO2 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA,TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURA,CRIANDO UM AMBIENTE MAS CONFORTAVEL PARA A EXECUÇÃO DE ATIVIDADE.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, N'Otimização na realização de atividades operacionais e condição ergonômica dos executantes na realização da manobras ', '2026-08-21T00:00:00.000', '2026-08-29T04:39:01.000', N'81034776', NULL, NULL);
