INSERT INTO #PVC VALUES (12020, N'81034776', N'81034776', N'IDENTIFICAÇÃO MOTORES UH SLB III', 1, N'Others/Outros', N'FALTA DE IDENTIFICAÇÃO ADEQUADA PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'TORNAR ATUAÇÃO MAS RÁPIDA E SEGURA.', N'0', N'01 - Imagens/01 - Antes/12020.jpeg', N'FALTA DE IDENTIFICAÇÃO ADEQUADA NO MO-2305SA-01-ST003-M8 PODENDO GERAR LENTIDÃO PARA RESOLUÇÃO DE FALHAS.', N'01 - Imagens/02 - Depois/12020.jpeg', N'COM MELHORIA REALIZADA NO MO-2305SA-01-ST003-M8 PASSAMOS A TER UMA CONDIÇÃO DE TRABALHO MAS ADEQUADA,TORNANDO AS ATUAÇÕES MAS RÁPIDAS E SEGURAS,CRIANDO UM AMBIENTE MAS CONFORTAVEL PARA EXECUÇÃO DE ATIVIDADES.', NULL, N'SIM.COM MELHORIA REALIZADA NO MO-2305SA-01-ST003-M8 PASSAMOS A TER CONDIÇÃO DE TRABALHO MAS ADEQUADA,TORNANDO AS ATUAÇÕES MAS RÁPIDA E SEGURAS,CRIANDO UM AMBIENTE MAS CONFORTAVEL PARA A EXECUÇÃO DE ATIVIDADES.', N'UMA BOA IDENTIFICAÇÃO APESAR DE PARECER SIMPLES FAZ TODA DIFERENÇA PARA UMA ATIVIDADE RÁPIDA E SEGURA.', 0, NULL, N'Agora esse HH poupado pode ser redirecionado para outras atividades de relevância para o negócio.', '2026-08-11T00:00:00.000', '2026-08-29T05:27:25.000', N'81034776', NULL, NULL);
INSERT INTO #PVC VALUES (12021, N'1008379', N'1008379', N'Coag Dilution upgrade', 1, N'Others/Outros', N'We were using Cu/Fe for coag dilution in the IR1 circuit. This dilution was constantly plugging and not maintaining proper flows, also Cu/Fe is from the IR2 circuit. Even though the dilution flow is low this solution is not meant to be in the IR1 circuit', N'To have proper coag dilution and consistentc dilution flow', N'10276', N'01 - Imagens/01 - Antes/12021.jpeg', N'We were using Cu/Fe for coag dilution in the IR1 circuit. This dilution was constantly plugging and not maintaining proper flows, also Cu/Fe is from the IR2 circuit. Even though the dilution flow is low, this solution is not meant to be in the IR1 circuit. 
INSERT INTO #PVC VALUES (12022, N'763789', N'763789', N'Implantação de Método Padronizado de Limpeza Setorizada das Sapatas do Armazém de Carvão.', 1, N'Others/Outros', N'A limpeza das sapatas era realizada sem uma sequência padronizada, com deslocamentos desnecessários dos empregados e dificuldade para identificar o status de limpeza de cada posição.', N'Implementar um novo método padronizado de limpeza das sapatas, baseado em setorização e gestão visual e criação de instrução de trabalho, visando aumentar a eficiência operacional, melhorar a organização da atividade e eliminar desperdícios durante a execução da limpeza.', N'10294', N'01 - Imagens/01 - Antes/12022.jpeg', N'A limpeza das sapatas era realizada de forma não padronizada, sem definição de sequência entre os pontos. Os empregados deslocavam-se entre diferentes sapatas conforme a necessidade percebida, gerando movimentações desnecessárias, dificuldade de acompanhamento da atividade e variação na forma de execução entre equipes.', N'01 - Imagens/02 - Depois/12022.jpeg', N'Foi implantado um padrão de limpeza com setorização e fluxo contínuo, além da implantação de instrução de trabalho. O processo inclui sequência definida, critérios de limpeza e inspeção visual.', NULL, N'A meta estabelecida foi atingida através da criação e implantação de um novo padrão operacional para limpeza das sapatas. O processo passou a contar com identificação estruturada, setorização, sequência padronizada de execução, critérios de aceitação e Instrução de Trabalho formalizada, garantindo maior organização, rastreabilidade e sustentabilidade da atividade.', N'Pequenas mudanças no método podem gerar grandes ganhos operacionais. A participação dos executantes é fundamental para construção do novo padrão. A gestão visual facilitou o acompanhamento e a sustentação dos resultados. A padronização reduziu variações entre equipes. ', 0, NULL, N'✅ BOA PRÁTICA / 5S 
INSERT INTO #PVC VALUES (12023, N'81013558', N'81016922', N'suporte para lixadeira ', 2, N'Open Pit/Poço aberto', N'no processo de fabricação durante as atividades de corte com lixadeira não havia suporte para o equipamento a mesma teria que ser depositada no chão oferecendo risco de tropeço para quem estivesse no local.', N'condição normal e anormal da área ', N'10318', N'01 - Imagens/01 - Antes/12023.jpeg', N'no processo de fabricação durante as atividades de corte com lixadeira não havia suporte para o equipamento a mesma teria que ser depositada no chão oferecendo risco de tropeço para quem estivesse no local.', N'01 - Imagens/02 - Depois/12023.jpeg', N'foi confeccionado um suporte para o equipamento nesta condição durante as atividades permite-se que o equipamento fique em um local de fácil identificação e eliminando o risco de tropeço para os executantes da área.', NULL, N'foi confeccionado um suporte para o equipamento nesta condição durante as atividades permite-se que o equipamento fique em um local de fácil identificação e eliminando o risco de tropeço para os executantes da área.', N'melhoria continua ', 2000, 1, N'To have enough space for all workers towels to be hung in the clean shower area.', '2026-08-26T00:00:00.000', '2026-08-29T13:37:36.000', N'81013558', NULL, NULL);
INSERT INTO #PVC VALUES (12024, N'81013558', N'81016922', N'SUPORTE PARA AS RODAS E SAPATAS DAS ESCADAS ', NULL, N'Open Pit/Poço aberto', N'durante o processo de transporte das escadas moveis de uso externos da oficina as roldanas e sapatas estabilizadoras entram em contato com o garfo da empilhadeira ocasionando danos a as mesmas. ', N'TEMPO ESPAÇO SEGURANRAÇA ', N'10318', N'01 - Imagens/01 - Antes/12024.jpeg', N'durante o processo de transporte das escadas moveis de uso externos da oficina as roldanas e sapatas estabilizadoras entram em contato com o garfo da empilhadeira ocasionando danos a as mesmas. ', N'01 - Imagens/02 - Depois/12024.jpeg', N'foi confeccionado uma proteção para as sapatas e roldanas das escadas impossibilitando que o garfo da empilhadeira entre em contato com os componentes das escadas preservando a integridade e trazendo segurança para o time.', NULL, N'foi confeccionado uma proteção para as sapatas e roldanas das escadas impossibilitando que o garfo da empilhadeira entre em contato com os componentes das escadas preservando a integridade e trazendo segurança para o time.', N'melhoria continua ', 15000, 1, N'Instalada corrente de proteção entre corrimão e carenagem da máquina para fechamento de vão com risco de queda.
INSERT INTO #PVC VALUES (12025, N'81013558', N'508773', N'SUPORTE PARA CHAVES ', NULL, N'Open Pit/Poço aberto', N'não havia local adequado para armazenamento de forma organizadas as chaves manuais no conteiner 320 sem padrão de condição normal e anormal.', N'CONDIÇÃO NORMAL E ANORMAL ', N'10320', N'01 - Imagens/01 - Antes/12025.jpeg', N'não havia local adequado para armazenamento de forma organizadas as chaves manuais no conteiner 320 sem padrão de condição normal e anormal.', N'01 - Imagens/02 - Depois/12025.jpeg', N'foi confeccionado painel Suporte para chaves manuais proporcionando condição normal e anormal trazendo condições seguras para time de execução.', NULL, N'foi confeccionado painel Suporte para chaves manuais proporcionando condição normal e anormal trazendo condições seguras para time de execução.', N'melhoria continua ', 2000, 1, N'A nova sinalização proporcionou maior visibilidade e rápida identificação das balizas, reduzindo os riscos operacionais, melhorando a referência visual durante a movimentação do Tripper e aumentando a segurança, a ergonomia e a eficiência da atividade.
INSERT INTO #PVC VALUES (12026, N'81013558', N'81016922', N'PAINEL PARA CHAVES MANUAIS ', NULL, N'Open Pit/Poço aberto', N'não havia local adequado para armazenamento de forma organizadas as chaves manuais no conteiner 320 sem padrão de condição normal e anormal.', N'CRIAR CONDIÇÃO NORMAL E ANORMAL ', N'10320', N'01 - Imagens/01 - Antes/12026.jpeg', N'não havia local adequado para armazenamento de forma organizadas as chaves manuais no conteiner 320 sem padrão de condição normal e anormal.', N'01 - Imagens/02 - Depois/12026.jpeg', N'foi confeccionado painel Suporte para chaves manuais proporcionando condição normal e anormal trazendo condições seguras para time de execução.', NULL, N'foi confeccionado painel Suporte para chaves manuais proporcionando condição normal e anormal trazendo condições seguras para time de execução.', N'MELHORIA CONTINUA ', 5000, 1, N'Reduzir em mais de 90% o tempo de elaboração das estimativas preliminares, aumentar a produtividade da engenharia, padronizar os cálculos, eliminar retrabalhos e garantir maior confiabilidade e rapidez na disponibilização das informações.', '2026-08-27T00:00:00.000', '2026-08-29T14:55:03.000', N'81013558', NULL, NULL);
INSERT INTO #PVC VALUES (12027, N'81022747', N'26518', N'SUPORTE PARA TECLADO DA TELA DE MONITORAMENTO CIAN', 1, N'Others/Outros', N'Descrição...teclado do monitor da tela de monitoramento do CIAN não conforme  ergonomicamente. ', N'ERGONOMIA', N'10144', N'01 - Imagens/01 - Antes/12027.jpeg', N'Teclado do monitor da tela de monitoramento do SIAN..não conforme  ergonomicamente.', N'01 - Imagens/02 - Depois/12027.jpeg', N'Feito melhoria para melhor adequação.', NULL, N'teclado do monitor da tela de monitoramento do SIAN não conforme  ergonomicamente. ', N'ORGANIZAÇÃO', 0, NULL, N'This will reduce downtime and increase productivity. ', '2026-08-28T00:00:00.000', '2026-08-29T16:33:36.000', N'81022747', NULL, NULL);
INSERT INTO #PVC VALUES (12028, N'81063756', N'81058516', N'Otimização de HH com Agente de IA para notificação de riscos de prazos de notas YE', 1, N'Others/Outros', N'Trabalho diário e manual de acompanhamento dos prazos de notas YE e notificação dos responsáveis dos centros de trabalho para ciência dos status das notas.', N'Eliminar aproximadamente 8 h/mês de trabalho manual', N'10015', N'01 - Imagens/01 - Antes/12028.jpeg', N'Tínhamos pessoa responsável por editar diariamente um painel com status das ações para divulgar no grupo com os responsáveis pelos centros, e outra que notificava-os de notas em risco, consumindo HH cerca de 8 h/mês.', N'01 - Imagens/02 - Depois/12028.jpeg', N'Fluxo automatizado conectado a agente de IA que envia diariamente um resumo dos status das notas YE, consumindo os dados do BI de Notas YE.
INSERT INTO #PVC VALUES (12029, N'541142', N'498011', N'Linha de distribuição de ar individualizada  ', 1, N'Others/Outros', N'Ausência de linha de distribuição de ar individualizada  para realização de abertura e fechamento da alimentação e by pass da remoagem CS 01', N'Reduzir impactos e perdas no processo produtivo', N'10054', N'01 - Imagens/01 - Antes/12029.jpeg', N'Ausência de linha de distribuição de ar individualizada  para realização de abertura e fechamento da alimentação e by pass da remoagem CS 01', N'01 - Imagens/02 - Depois/12029.jpeg', N'Realizada instalação de linha de ar individualizada  para realização de abertura e fechamento da alimentação e by pass da remoagem CS 01', NULL, N'Otimização na realização de atividades operacionais e condição ergonômica dos executantes na realização da manobras ', N'Perdas / Impacto produtivo / 5S', 0, NULL, N'Less time wasted and we removed having to physically lift the pump out of the well.', '2026-08-27T00:00:00.000', '2026-08-29T18:23:14.000', N'541142', NULL, NULL);
INSERT INTO #PVC VALUES (12030, N'81013885', N'81046945', N' Tubulação de adição', 1, N'Others/Outros', N'Anteriormente estávamos tendo muitas obstruções na caixa devido o material do by-pass está vindo muito denso acumulava na caixa e obstruía. Consequentemente obstruindo a bacia de Under.', N' evitando que a mesma chegue a obstruir.', N'10362', N'01 - Imagens/01 - Antes/12030.jpeg', N'Anteriormente estávamos tendo muitas obstruções na caixa devido o material do by-pass está vindo muito denso acumulava na caixa e obstruía. Consequentemente obstruindo a bacia de Under.
INSERT INTO #PVC VALUES (12031, N'541142', N'498011', N'Linha de distribuição de ar individualizada  ', 1, N'Others/Outros', N'Ausência de linha de distribuição de ar individualizada  
INSERT INTO #PVC VALUES (12032, N'486869', N'487651', N'"TAG CERTO"', 3, N'Others/Outros', N'DURANTE A INSPEÇÃO DO PROJETO IN PIT - FASE 1, FOI IDENTIFICADO QUE AS TUBULAÇÕES DAS BOMBAS NÃO ESTAVAM DEVIDAMENTE IDENTIFICADAS COM AS TAGS CORRESPONDENTES AOS SEUS EQUIPAMENTOS, O QUE DIFICULTAVA A RASTREABILIDADE E A IDENTIFICAÇÃO DAS TUBULAÇÕES EM CAMPO.', N'IDENTIFICAR AS TUBULAÇÕES DAS BOMBAS DO PROJETO  IN PIT', N'10062', N'01 - Imagens/01 - Antes/12032.jpeg', N'OS COLABORADORES APRESENTAVAM DIFICULDADES PARA IDENTIFICAR CORRETAMENTE AS TUBULAÇÕES CORRESPONDENTES A CADA BOMBA, TORNANDO O PROCESSO DE OPERAÇÃO E MANUTENÇÃO MAIS DEMORADO DO QUE O NECESSÁRIO. ESSA DIFICULDADE OCORRIA PORQUE TODAS AS TUBULAÇÕES POSSUÍAM AS MESMAS DIMENSÕES E CORES E NÃO HAVIA TAGS NELAS, O QUE DIFICULTAVA SUA DIFERENCIAÇÃO VISUAL.', N'01 - Imagens/02 - Depois/12032.jpeg', N'FOI EXECUTADA A IDENTIFICAÇÃO DAS TUBULAÇÕES COM SUAS RESPECTIVAS TAGS, ASSOCIADAS A CADA BOMBA, MELHORANDO A RASTREABILIDADE DOS EQUIPAMENTOS E GARANTINDO UMA IDENTIFICAÇÃO MAIS RÁPIDA, SEGURA E EFICIENTE EM CAMPO.
INSERT INTO #PVC VALUES (12033, N'81063756', N'81059325', N'Otimização de HH com Painel de RAF e Ações por engenheiros em Power BI', 1, N'No Replication/Sem replicação', N'Um painel com resumo do status de gatilhos e ações de RAF por engenheiro era preciso ser atualizado semanalmente para o FMDS, gerando um custo de HH de 4 h/mês.', N'Reduzir consumo de HH de 4h/mês com atualização semanal e manual de painel usado em FMDS', N'10015', N'01 - Imagens/01 - Antes/12033.jpeg', N'Eram feitas inúmeras consultas para registrar os status de gatilhos e ações de RAF de cada engenheiro de confiabilidade, além de cálculos manuais.', N'01 - Imagens/02 - Depois/12033.jpeg', N'Agora temos um painel em Power BI equivalente ao painel construído manualmente, mas que atualiza diariamente e automaticamente. Dessa forma, basta copiar ou printar o painel para apresentar no FMDS.', NULL, N'Não há mais a necessidade de gastar cerca de 4 h/mês de HH para atualizar a tabela semanalmente. ', N'Eliminação de tarefa manual via Power BI.', 0, NULL, NULL, '2026-08-17T00:00:00.000', '2026-08-29T18:56:02.000', N'81063756', NULL, NULL);
INSERT INTO #PVC VALUES (12034, N'81018270', N'81018270', N'Deslocamento da Leira LADO A – BR_2001_01', 1, N'Crusher/Britadeira', N'O LADO A do silo 1 do britador BR_2001_01, tinha  limitação de tamanho dos caminhões para basculamento, com caminhões com capacidade de carga de 400ton tem dificuldades em realizar manobra para se posicionar e bascular no silo 1 do britador. Com isso gerava um desbalanceamento de massa processada entre os lados britador e gerando desgaste irregular dos côncavos. 
INSERT INTO #PVC VALUES (12035, N'81047450', N'81048611', N'SUPORTE PARA BALDES', 3, N'Others/Outros', N'Balde de  óleo deixado em cima da grade da carrinho de contenção, fora do local. Risco de queda em pessoa e de obstruir a drenagem. Precisa retirar e levar pro local correto.', N'ORGANIZAÇÃO DA OFICINA', N'0', N'01 - Imagens/01 - Antes/12035.jpeg', N'Balde de  óleo deixado em cima da grade da carrinho de contenção, fora do local. Risco de queda em pessoa e de obstruir a drenagem. Precisa retirar e levar pro local correto.', N'01 - Imagens/02 - Depois/12035.jpeg', N'✅ BOA PRÁTICA / 5S 
INSERT INTO #PVC VALUES (12036, N'1015684', N'1015684', N'Shower room towel hooks', 2, N'Refining/Refino', N'There was not enough room for workers to hang towels to dry in the clean shower area in 212 annex. Workers are forced to hang their towels up in the main change room area potentially exposing them to contaminates.', N'To have adequate hooks for all workers to hang and dry their towels in the clean shower area.', N'0', N'01 - Imagens/01 - Antes/12036.jpeg', N'There was not enough room for workers to hang towels to dry in the clean shower area in 212 annex. Workers are forced to hang their towels up in the main change room area potentially exposing them to contaminates.', N'01 - Imagens/02 - Depois/12036.jpeg', N'Installed additional hooks throughout the clean shower stall area of 212 annex. There is now adequate space, and workers will no longer have to leave their towels in a dirty area to dry.', NULL, N'Yes, there is now adequate space, and workers will no longer have to leave their towels in a dirty area to dry.', N'Setting up the area for adequate amount of towels and worker use.', 0, NULL, N'No contaminated waste left around the belt deck.', '2026-08-29T00:00:00.000', '2026-08-30T02:03:48.000', N'1015684', NULL, NULL);
INSERT INTO #PVC VALUES (12037, N'81047450', N'81048611', N'CORRENTE PROTEÇÃO CONTRA QUEDA ', 2, N'Others/Outros', N'🚨 COND INSEGURA ESCAVADEIRA EC20
INSERT INTO #PVC VALUES (12038, N'81039464', N'81017935', N'Instalação de placas de sinalização', 1, N'Others/Outros', N'Durante a movimentação do Tripper nos armazéns de Salobo e Sossego, as balizas de sinalização instaladas nas colunas apresentavam baixa visibilidade e difícil identificação pelos operadores. Essa condição comprometia a referência visual necessária para o posicionamento seguro e preciso do equipamento, aumentando o risco de erros operacionais e reduzindo a eficiência das movimentações.
INSERT INTO #PVC VALUES (12039, N'81038786', N'81038786', N'Ferramenta de Cálculo de Lucros Cessantes', 1, N'Others/Outros', N'O cálculo de lucros cessantes era realizado manualmente, exigindo coleta de dados, preenchimento de planilhas e validações individuais. O processo demandava tempo elevado, era suscetível a erros, retrabalhos e dependia do conhecimento técnico dos responsáveis.', N'esenvolver uma ferramenta automatizada para padronizar e agilizar o cálculo de lucros cessantes, reduzindo atividades manuais, aumentando a confiabilidade das estimativas, melhorando a produtividade da equipe e apoiando uma tomada de decisão mais rápida e assertiva.', N'10293', N'01 - Imagens/01 - Antes/12039.jpeg', N'O cálculo de lucros cessantes era realizado manualmente, exigindo coleta de dados, preenchimento de planilhas e validações individuais. O processo demandava tempo elevado, era suscetível a erros, retrabalhos e dependia do conhecimento técnico dos responsáveis.', N'01 - Imagens/02 - Depois/12039.jpeg', N'Foi desenvolvida uma ferramenta automatizada que padroniza os cálculos de lucros cessantes. Com a inserção do tempo de ganho ou perda, os resultados são gerados instantaneamente, reduzindo esforços manuais, erros, retrabalhos e aumentando a autonomia dos usuários.', NULL, N'Atendeu a expectativa de redução de tempo de execução.', N'A automatização de rotinas repetitivas proporciona ganhos expressivos de produtividade, qualidade e confiabilidade. A padronização reduz erros, elimina dependências individuais e permite direcionar esforços para análises mais estratégicas.', 0, NULL, N'Resultado foi o esperado', '2026-08-28T00:00:00.000', '2026-08-30T13:11:07.000', N'81038786', NULL, NULL);
INSERT INTO #PVC VALUES (12040, N'81010520', N'81010520', N'Autoclave deck 600-volt outlets.', 1, N'Refining/Refino', N'During planned shutdowns we would always have to run cords to the welding plugs on the ground level to supply 600-volt power. Now we have 4 additional 60Amp 600-volt outlets installed to allow us to provide the required power for the upcoming shutdown.', N'To have permanent 600-volt power supplys for planned outages', N'0', N'01 - Imagens/01 - Antes/12040.jpeg', N'The Autoclave deck had no 600-Volt power available.', N'01 - Imagens/02 - Depois/12040.jpeg', N'We now have 4 additional 60 Amp outlets installed that will allow us to provide the required power during the shutdown.', NULL, N'We now have a permanent solution that will provide vendors the additional power required during shutdown work.', N'Always look for ways to improve productivity.', 0, NULL, N'Everyone will now see this line label.', '2026-08-29T00:00:00.000', '2026-08-30T13:30:45.000', N'81010520', NULL, NULL);
INSERT INTO #PVC VALUES (12041, N'544306', N'544306', N'Bloco de Lego  ', 2, N'No Replication/Sem replicação', N'A área ficava contaminada devido acumulo de concentrado.', N'Adequação da área.', N'10237', N'01 - Imagens/01 - Antes/12041.jpeg', N'A área ficava contaminada devido acumulo de concentrado. Deixando a área inadequada e insegura. Mobilizando pessoas e maquinas para limpar o local.', N'01 - Imagens/02 - Depois/12041.jpeg', N'Depois que realizou toda a limpeza no local, foi  colocado barreira pra evitar contaminação de concentrado com material de manutenção e concentrado. Assim adequando e deixando área mas segura. ', NULL, N'A meta foi alcançada e com excelência para isolar e sinalizada conforme normas de segurança NR-18 e NR-35.', N'Segurança e Comprometimento.', 0, NULL, N'line is now easily identified', '2026-08-22T00:00:00.000', '2026-08-30T15:07:20.000', N'544306', NULL, NULL);
INSERT INTO #PVC VALUES (12042, N'81053928', N'81053928', N'Monitoring well on and off labelling.', 1, N'Others/Outros', N'Monitoring well panel had no labeling for on and off switch. You have to pull the pump out of the well to check if it''s actually running which takes a while because its 30 ft or more down the well.', N'read a label and knowing if it''s turned on without having to drag the pump all the way out of the well.', N'10158', N'01 - Imagens/01 - Antes/12042.jpeg', N'Panel not labeled for on and off switch. You have to pull pump out of well to see if it''s actually running.', N'01 - Imagens/02 - Depois/12042.jpeg', N'I added an off and an on sticker which lets you know the pump is on without wasting time pulling it out of the well.', NULL, N'Yes, the problem was solved as now we don''t have to pull the pump out of well to check if it''s on as we now only have to look at the labels on the panel.', N'Work smarter not harder', 0, NULL, N'line was identified so workers will not make the mistake of not knowing what the line was', '2026-08-29T00:00:00.000', '2026-08-30T15:08:43.000', N'81053928', NULL, NULL);
INSERT INTO #PVC VALUES (12043, N'533543', N'81037486', N'REAGENTE ', NULL, N'Others/Outros', N'Bomba principal de reagente da área  de espumante, parava com falha e não tinha nenhum alarme para identificar de imediato.', N'Ver e agir de forma ágil ', N'0', N'01 - Imagens/01 - Antes/12043.jpeg', N'Bomba principal de reagente da área  de espumante, parava com falha e não tinha nenhum alarme para identificar de imediato.', N'01 - Imagens/02 - Depois/12043.jpeg', N'Solicitado alarme na tela de supervisório (Flotação GR1/GR2 e SCV do cleaner. Onde e identificado de imediato o alarme de bomba parada.', NULL, N'Bomba principal de reagente da área  de espumante, parava com falha e não tinha nenhum alarme para identificar de imediato.', N'Ver e Agir com rapidez ', 0, NULL, N'workers will easily identify the line', '2026-08-15T00:00:00.000', '2026-08-30T16:18:27.000', N'533543', NULL, NULL);
INSERT INTO #PVC VALUES (12044, N'1010294', N'1010294', N'Labeling storage areas - Garbage bins', 3, N'Others/Outros', N'Garbages had no set location, one had to look to find them.  Now there is a place designated on the floor indicating where the garbage should be placed.', N'Organization and effective 5S', N'10352', N'01 - Imagens/01 - Antes/12044.jpeg', N'Garbages where place in the hallway with no set space.  Sometimes you would have to look for it, or it would go unchecked as there was no set place for it.', N'01 - Imagens/02 - Depois/12044.jpeg', N'Clearly marked area for where garbage bin belongs.  Easy to find and clearly noted if missing.', NULL, N'Yes.  Clearly marked locations for easy reference.', N'Easy to find and noticable when missing', 0, NULL, N'Eliminar a necessidade de abertura manual dos Big Bags com ferramenta cortante.
INSERT INTO #PVC VALUES (12045, N'81027090', N'81027090', N'Suporte dos embarcados CAT416', 1, N'Others/Outros', N'O equipamento não possuía suporte adequado para a instalação e acomodação do painel do sistema embarcado de automação.', N'Segurança e produtividade', N'10015', N'01 - Imagens/01 - Antes/12045.jpeg', N'Foi constatado que o equipamento CAT 416 não dispunha de estrutura de suporte para a fixação e acomodação do painel do sistema de automação embarcado.', N'01 - Imagens/02 - Depois/12045.jpeg', N'Foi desenvolvido o projeto do suporte, seguido de sua fabricação e instalação no equipamento CAT 416, com o objetivo de proporcionar a acomodação adequada do painel do sistema de automação embarcado.', NULL, N'O problema foi resolvido por meio da elaboração do projeto de um suporte dedicado, seguido de sua fabricação e instalação no equipamento. A adequação realizada proporcionou a estrutura necessária para a correta fixação e acomodação do painel do sistema de automação embarcado, atendendo aos requisitos operacionais e de segurança da instalação.', N'A análise antecipada das condições físicas do equipamento permite identificar a necessidade de suportes e acessórios de montagem, reduzindo atrasos e custos com modificações em campo.', 0, NULL, N'The stir bars to get back on the magnet after use.', '2026-08-18T00:00:00.000', '2026-08-30T20:28:28.000', N'81027090', NULL, NULL);
INSERT INTO #PVC VALUES (12046, N'1008799', N'1008799', N'Flocculant inspection pictures', 3, N'Others/Outros', N'Flocculant can be often be made incorrectly . new or inexperienced technicians may not have seen bad flocculant batches. Laminated pictures place at flocullant skid area allows for quick reference for new technicians. This will prevent bad batches from entering the storage tanks and causing production upsets. ', N'To prevent poorly made flocculant being added to system', N'10003', N'01 - Imagens/01 - Antes/12046.jpeg', N'No pictures for reference for bad flocculant batches', N'01 - Imagens/02 - Depois/12046.jpeg', N'Laminated picture directly attached to flocculant preparation tank for easy reference. This will prevent the addition to the circuit of bad flocculant batches', NULL, N'Problem was solved . less chance of bad batches entering circuit.', N'Visual cues right at source prevents production issues', 10000, 3, N'The sticker will catch the attention of people, and the holder will be fully stocked at all times.', '2026-08-29T00:00:00.000', '2026-08-30T21:22:23.000', N'1008799', NULL, NULL);
INSERT INTO #PVC VALUES (12047, N'81054033', N'81054033', N'Weighing Station Reminder', 1, N'Others/Outros', N'Due to fans and ventilation in our lab, if the door is not closed it may cause the weight to fluctuate due to the precision of the scale.', N'Precise Results', N'10003', N'01 - Imagens/01 - Antes/12047.jpeg', N'This is our weighing station in our lab; we use it to weigh various reagents for testing.', N'01 - Imagens/02 - Depois/12047.jpeg', N'I now have a sticker in front of the scale just to remind everyone to close the due when weighing. ', NULL, N'Hopefully this is a reminder that will help in the future.', N'Consistency is key ', 0, NULL, N'Eliminar 100% a necessidade de o operador subir na grelha para retirar os blocos.
INSERT INTO #PVC VALUES (12048, N'81054033', N'81054033', N'Level Indicator Cleaning Supplies', 3, N'Projects/Projetos', N'Sometimes we need to clean the level indicators in a timely manner, therefore having everything close by is a huge help. The things needed to clean these indicators may vary, but for the most part its fairly common. At the station I have some extra gloves, a wand to reach inside the indicator, some paper towels and some squirt bottles with water. ', N'Save Time and Further Problems ', N'10003', N'01 - Imagens/01 - Antes/12048.jpeg', N'Empty station near the level indicators.', N'01 - Imagens/02 - Depois/12048.jpeg', N'I have the station now labelled as Level Indicator Cleaning, and as you can see, I have cups, squirt bottles, gloves, paper towel and a wand to reach inside.', NULL, N'Having everything nearby can help save time and issues.', N'Organization Can Save Time.', 0, NULL, N'Melhor acesso nas inspeções ', '2026-08-30T00:00:00.000', '2026-08-30T23:58:18.000', N'81054033', NULL, NULL);
INSERT INTO #PVC VALUES (12049, N'81054033', N'81054033', N'Clean Pak Storage Area', 3, N'Projects/Projetos', N'When there is a Belt DFR or repairs often times clean paks are needed for contaminated waste such as solids, cloth and flaps off the belt. ', N'Promote cleanup and save some time.', N'#N/A', N'01 - Imagens/01 - Antes/12049.jpeg', N'This is the area before I cleaned it up and set up the Kaizen', N'01 - Imagens/02 - Depois/12049.jpeg', N'There is now a pallet in the area with the clean paks on it. Having them on the pallet will keep them from getting damaged. It is also labelled with Cleak-Pak Storage and another sticker that says do not remove', NULL, N'Hopefully now with the clean paks in the area it will make it much easier for people to execute the proper clean up.', N'Proper Planning Can Help Save Time.', 0, NULL, N'Em 2026, a revisão da estratégia de manutenção permitiu eliminar preventivas exclusivas de 250h sem necessidade técnica comprovada, reduzindo paradas planejadas e aumentando a disponibilidade operacional. Para 2027, projeta-se evitar a geração de 8 preventivas exclusivas de 250h por equipamento, correspondendo à redução de 32 horas anuais de manutenção planejada e ganho estimado de 0,68 p.p. na Disponibilidade Física (DF), sem impacto na confiabilidade da frota.', '2026-08-30T00:00:00.000', '2026-08-31T01:03:31.000', N'81054033', NULL, NULL);
INSERT INTO #PVC VALUES (12050, N'1008382', N'1008382', N'IR1 Antiscalant Rerouting', 1, N'Refining/Refino', N'Antiscalant used in IR 1 polish filter feed injected into the discharge of 1 pump. This scale inhibitor only working to prevent scale on discharge of this pump discharge line and PPLS tank, Pumps and lines.  ', N'To relocate the antiscalant injection to have effect on the poliswh filter feed tank, other 3 pumps and flocculant dilution system.  ', N'#N/A', N'01 - Imagens/01 - Antes/12050.jpeg', N'Antiscalant used in IR 1 polish filter feed injected into the discharge of 1 of the 4 pumps. This scale inhibitor only working to prevent scale on discharge of this pump discharge line and PPLS tank, Pumps and lines.  ', N'01 - Imagens/02 - Depois/12050.jpeg', N'By using the old body feed line to the top of the polish filter feed tank which is no longer in use we were able to reroute the injection of antiscalant from the discharge of polish filter feed pump #3 to the top of the polish filter feed tank. 
INSERT INTO #PVC VALUES (12051, N'81043245', N'81043245', N'SUPORTE DE BOLSAS E CAPACETES', 1, N'Others/Outros', N'Foi identificada a ausência de um local adequado para armazenamento de bolsas e capacetes.', N'LOCAL ADEQUADO PARA ARMAZENAMNTO', N'10054', N'01 - Imagens/01 - Antes/12051.jpeg', N'As bolsas e os capacetes eram deixados de forma inadequada sobre o frigobar ou mesas, gerando desorganização e ocupando espaços destinados a outras finalidades.', N'01 - Imagens/02 - Depois/12051.jpeg', N'Foi instalado um suporte específico para bolsas e capacetes, proporcionando um local adequado para armazenamento, melhorando a organização e contribuindo para a prática de 5S na área.', NULL, N'SIM. A definição de locais específicos para cada item facilita a organização e evita o uso inadequado de outros espaços.', N'A organização adequada dos pertences contribui para um ambiente mais limpo.', 0, NULL, N'Simplificação e redução de tempo para apuração do fechamento.', '2026-08-21T00:00:00.000', '2026-08-31T02:04:29.000', N'81043245', NULL, NULL);
INSERT INTO #PVC VALUES (12052, N'92000584', N'92000584', N'Melhoria no sistema de acionamento da chave geral da PC-02', 1, N'Others/Outros', N'Ao investigar ocorrências de baterias descarregadas, identificamos que o acionamento da chave geral exigia esforço físico elevado, criando uma barreira operacional para parte das operadoras.', N'Facilitar o acionamento da chave geral, tornando a operação mais acessível e ergonômica para diferentes perfis de operadores.', N'10035', N'01 - Imagens/01 - Antes/12052.jpeg', N'O acionamento da chave geral possuía uma caixa de proteção ao redor do acionamento, o que dificultava o acesso e exigia maior esforço físico.', N'01 - Imagens/02 - Depois/12052.jpeg', N'Instalamos um dispositivo que facilitou o acionamento da chave geral, eliminando a barreira operacional identificada.', NULL, N'A meta foi atingida com a retirada da caixa que dificultava o acesso.', N'Inclusão acontece nos detalhes. Quando consideramos diferentes perfis de usuários no desenho das soluções, criamos um ambiente mais acessível, seguro e eficiente para todos.', 0, NULL, N'Centralização das informações, redução do retrabalho, confiabilidade e visibilidade em tempo real das férias.', '2026-08-29T00:00:00.000', '2026-08-31T02:39:19.000', N'92000584', NULL, NULL);
INSERT INTO #PVC VALUES (12053, N'81062449', N'81062449', N'Belt Filter Feed Labelling ', NULL, N'Projects/Projetos', N'You could mistake this line for another line, and it could also be very helpful for our new hires trying to catch on.', N'Make belt filter feed line easier to identify ', N'10003', N'01 - Imagens/01 - Antes/12053.jpeg', N'The line here has no label', N'01 - Imagens/02 - Depois/12053.jpeg', N'line now is easy to identify', NULL, N'Yes, this line now has a label that can be clearly seen.', N'Labels Can Help Avoid Confusion', 0, NULL, N' Ganho de disponibilidade de equipamento.
INSERT INTO #PVC VALUES (12054, N'81062449', N'81062449', N'Seal water to Belt #4', 1, N'Projects/Projetos', N'someone could mistake the line as something else', N'to avoid mistaking the line for something else', N'#N/A', N'01 - Imagens/01 - Antes/12054.jpeg', N'line was not labled', N'01 - Imagens/02 - Depois/12054.jpeg', N'line is now easily identifiable', NULL, N'yes', N'avoid mistaking a line', 0, NULL, N'Produtividade, facilidade na manutenção no componentes. ', '2026-08-30T00:00:00.000', '2026-08-31T04:00:19.000', N'81062449', NULL, NULL);
INSERT INTO #PVC VALUES (12055, N'81062449', N'81062449', N'Barren solution', NULL, N'Projects/Projetos', N'line was not labled', N'to identify line', N'10003', N'01 - Imagens/01 - Antes/12055.jpeg', N'line was not identified', N'01 - Imagens/02 - Depois/12055.jpeg', N'identified the line', NULL, N'yes', N'identify the line to avoid mistakes', 0, NULL, N'Mais segurança, aumento de produtividade, e menos exposição de pessoa.', '2026-08-30T00:00:00.000', '2026-08-31T04:11:50.000', N'81062449', NULL, NULL);
INSERT INTO #PVC VALUES (12056, N'81062449', N'81062449', N'Recycle water', NULL, N'Projects/Projetos', N'line was not labled', N'to identify the line', N'10003', N'01 - Imagens/01 - Antes/12056.jpeg', N'line was not identified', N'01 - Imagens/02 - Depois/12056.jpeg', N'line now is identified', NULL, N'yes', N'to avoid any mistakes of not knowing what the line was', 0, NULL, N'The redesigned feed gate guides are expected to reduce maintenance time and equipment downtime by improving accessibility and simplifying component replacement. The new bolted guide design will reduce ergonomic risk to mechanics, eliminate dependence on expensive OEM replacement parts.', '2026-08-30T00:00:00.000', '2026-08-31T04:17:32.000', N'81062449', NULL, NULL);
INSERT INTO #PVC VALUES (12057, N'549066', N'549066', N'Implemento para rasgo de Bag. ', 2, N'Others/Outros', N'Na atividade de blend de material estocado em Bags, era necessário realizar a abertura dos Bags para descarregamento do material. Essa operação era executada utilizando uma ferramenta cortante manual, exigindo que o colaborador se posicionasse próximo à carga suspensa/elevada pela empilhadeira para realizar o rasgo do Bag cheio.
INSERT INTO #PVC VALUES (12058, N'81054033', N'81054033', N'Stir Bar Storage', 3, N'Projects/Projetos', N'Stir bars left on the counter, ending up on the floor or getting lost. Sometimes hard to find one when needed.', N'Have all the stir bars connected to the magnet and stored', N'10003', N'01 - Imagens/01 - Antes/12058.jpeg', N'The cabinet without a sticker.', N'01 - Imagens/02 - Depois/12058.jpeg', N'As you can see the Stir Bar Storage sticker is there with the magnets just below it, hopefully this bright sticker will catch the attention of people and will result in the stir bars getting put back.', NULL, N'Yes', N'Simple Stickers ', 0, NULL, N'Após a implantação da melhoria, foi criada uma bancada próxima aos verticais da remoagem para apoio da prancheta e emissão das PTs. A adequação proporcionou melhores condições ergonômicas aos operadores, tornando o processo mais organizado, confortável e eficiente durante a liberação das permissões de trabalho.', '2026-08-30T00:00:00.000', '2026-08-31T04:42:25.000', N'81054033', NULL, NULL);
INSERT INTO #PVC VALUES (12059, N'81054033', N'81054033', N'Glove Holder', NULL, N'Projects/Projetos', N'No gloves in the holder', N'Gloves Always Fully Stocked', N'10003', N'01 - Imagens/01 - Antes/12059.jpeg', N'Glove holder without a label', N'01 - Imagens/02 - Depois/12059.jpeg', N'This is a picture of the glove holder with a label', NULL, N'Yes', N'Simple Stickers', 0, NULL, N'Além do aumento da assertividade da carteira orçamentária, o projeto proporcionou a padronização dos critérios de avaliação e priorização de componentes reformáveis, reduzindo a subjetividade no processo decisório. Houve também maior integração entre as áreas envolvidas, melhoria na rastreabilidade das justificativas para inclusão de itens no orçamento, criação de uma base estruturada para futuras revisões orçamentárias e fortalecimento da gestão de risco associada à indisponibilidade de ativos críticos.', '2026-08-30T00:00:00.000', '2026-08-31T04:46:35.000', N'81054033', NULL, NULL);
INSERT INTO #PVC VALUES (12060, N'123307', N'513430', N'DISPOSITIVO DE REMOÇÃO DE BLOCOS', 2, N'Projects/Projetos', N'Durante a alimentação do by-pass,  blocos de minério ficavam retidos nas grelhas, ocasionando obstruções e comprometendo o fluxo de alimentação. Para realizar a desobstrução, o operador precisava subir na grelha para retirar manualmente os blocos, sendo necessário realizar o bloqueio do AL 05. Essa condição aumentava o tempo para liberação do equipamento e expunha o colaborador a riscos durante a atividade.
INSERT INTO #PVC VALUES (12061, N'81009130', N'81009130', N'Escada de Acesso ao Canteiro de Contratadas Manutenção.', 1, N'Others/Outros', N'Acesso sem condição adequada de circulação com a presença irregular do caminho, vegetação excessiva, dificuldades de acesso nos canteiros das contratada da manutenção e melhor resposta de trabalho junto a contratada. ', N'Melhor facilidade de acesso aos canteiros. ', N'10184', N'01 - Imagens/01 - Antes/12061.jpeg', N'Acesso sem condição adequada de circulação com a presença irregular do caminho, vegetação excessiva, dificuldades de acesso nos canteiros das contratada da manutenção e melhor resposta de trabalho junto a contratada e perda de tempo durante as inspeção de 5S.', N'01 - Imagens/02 - Depois/12061.jpeg', N'Foi identificado que o acesso bem definido e padronizado, com adequação do piso, controle de engenharia o acesso traz maior rapidez de trabalho no forno I redução a equipe se desloca sem precisar de veículo, proporcionando maior agilidade na execução das atividades.', NULL, N'Sim, melhor movimento de acesso ao canteiros das contratada devido não precisar de veículo', N'Relações interpessoais ', 0, NULL, N'Após a implantação da melhoria, foi criada uma bancada próxima aos moinhos da moagem para apoio da prancheta e emissão das PTs. A adequação proporcionou melhores condições ergonômicas aos operadores, tornando o processo mais organizado, confortável e eficiente durante a liberação das permissões de trabalho', '2026-08-28T00:00:00.000', '2026-08-31T08:15:59.000', N'81009130', NULL, NULL);
INSERT INTO #PVC VALUES (12062, N'81061965', N'81061965', N'Otimização da Estratégia de Manutenção do CA 401 com Eliminação de Preventivas Exclusivas de 250h', NULL, N'Others/Outros', N'A estratégia de manutenção da frota contemplava preventivas de 250h geradas de forma exclusiva, exigindo a retirada do caminhão de operação apenas para atendimento desse pacote. A análise do histórico de manutenção e da necessidade técnica das atividades executadas identificou que essas intervenções não agregavam valor suficiente para justificar paradas dedicadas, podendo ser absorvidas em preventivas de maior ciclo ou tratadas conforme condição.', N'Reduzir paradas planejadas de manutenção por meio da eliminação de preventivas exclusivas de 250h sem impacto na confiabilidade dos caminhões, aumentando a disponibilidade física da frota.', N'10015', N'01 - Imagens/01 - Antes/12062.jpeg', N'A estratégia de manutenção da frota contemplava a execução de preventivas de 250 h com duração planejada de 4 horas. Parte dessas intervenções era gerada de forma exclusiva, exigindo a retirada do caminhão de operação apenas para atendimento desse pacote, gerando paradas com baixo valor agregado, impactando a disponibilidade física dos equipamentos e aumentando o consumo de recursos de manutenção.
INSERT INTO #PVC VALUES (12063, N'81061965', N'81061965', N'Revisão de atividades sistemáticas e materiais dos planos preventivos da frota 830E', 1, N'Others/Outros', N'Os planos preventivos da frota 830E continham atividades e materiais sem necessidade técnica comprovada. O filtro secador SAP 15286420 permanecia previsto para substituição nos ciclos preventivos, embora sua troca não fosse realizada nessas intervenções. Adicionalmente, as listas técnicas continham o adaptador P85557 (Komatsu), componente que não era consumido durante as manutenções. Essa condição gerava reservas indevidas de materiais, retrabalho administrativo, aumento de custos e baixa aderência entre o planejamento e a execução da manutenção.', N'Eliminar atividades e materiais sem necessidade técnica dos planos preventivos da frota 830E, reduzindo custos de manutenção e aumentando a aderência entre planejamento e execução.', N'10015', N'01 - Imagens/01 - Antes/12063.jpeg', N'Os planos preventivos da frota 830E previam a substituição do filtro secador SAP 15286420 e mantinham cadastrado o adaptador P85557 (Komatsu) nas listas técnicas, apesar de ambos não serem utilizados nas intervenções preventivas. Como consequência, eram geradas reservas desnecessárias de materiais, inconsistências no planejamento e custos recorrentes sem retorno operacional.', N'01 - Imagens/02 - Depois/12063.jpeg', N'Foi realizada a revisão técnica dos planos preventivos e das listas de materiais da frota 830E. O filtro secador SAP 15286420 foi removido dos planos preventivos e passou a ser tratado como item de troca condicional, enquanto o adaptador P85557 (Komatsu) foi excluído das listas técnicas por não possuir aplicação nas manutenções. A iniciativa aumentou a aderência entre planejamento e execução, eliminou desperdícios e reduziu custos recorrentes.', NULL, N'O problema foi resolvido por meio da revisão técnica dos planos preventivos da frota 830E. Foram removidos o filtro secador SAP 15286420, que não era substituído nas preventivas previstas, e o adaptador P85557 (Komatsu), que permanecia cadastrado nas listas técnicas sem consumo nas intervenções. A atualização eliminou materiais sem necessidade operacional, aumentou a aderência entre planejamento e execução da manutenção e proporcionou redução anual estimada de R$ 130.112,94 em custos recorrentes.', N'A revisão periódica dos planos preventivos e listas técnicas é fundamental para identificar atividades e materiais sem necessidade técnica comprovada. A eliminação desses itens aumenta a aderência entre planejamento e execução, reduz desperdícios e melhora a eficiência da manutenção sem impactar a confiabilidade dos ativos.', 130000, 1, N'A AÇÃO EVITA O ACESSO DO COLABORADOR ACESSAR A PARTE INTERNA DO TRANSPORTADOR, EVINTANDO A EXPOSIÇÃO DO FUNIONÁRIO A PARTES MOVEIS/ROTATIVAS DO TRANSPORTADOR.', '2026-08-21T00:00:00.000', '2026-08-31T09:34:28.000', N'81061965', NULL, NULL);
INSERT INTO #PVC VALUES (12064, N'532872', N'532872', N'Painel de Fechamento Mensal - Indicadores de Confiabilidade e Gestão do trabalho de Manutenção', 1, N'Others/Outros', N'os dados de fechamento de indicadores de processo eram reportados separadamente.', N'Consolidar dado de Performance e processo ', N'10081', N'01 - Imagens/01 - Antes/12064.jpeg', N'os indicadores e Processo e Performance eram apurados separadamente.', N'01 - Imagens/02 - Depois/12064.jpeg', N'Desenvolvido painel no Power BI usando HTML e CSS consolidando o fechamento dos indicadores Performance e Processo com uso de camada semântica do Power BI. ', N'https://app.powerbi.com/groups/me/apps/2f1cf443-5ea8-45a4-9860-b084ee3f2a39/reports/49c2fd06-e2cf-4712-bc38-8669f2adbbdb/259980e693099ec81cbd?experience=power-bi', N'Sim, indicadores consolidados de forma dinâmica.', N'a inovação é o caminho para modernização', 0, NULL, N'Ganho qualitativo, relacionado à redução de perdas operacionais, aumento da 
INSERT INTO #PVC VALUES (12065, N'499365', N'81001594', N'Dashboard de Férias: Visibilidade, Planejamento e Governança para Gestão de Pessoas', 1, N'Others/Outros', N'Processo de gestão de férias manual e descentralizado, gerando retrabalho, baixa visibilidade e riscos no planejamento das equipes', N'Automatizar e padronizar a gestão de férias das equipes por meio de um dashboard integrado, garantindo 100% de visibilidade do planejamento anual, maior previsibilidade operacional e redução significativa do tempo gasto com controles manuais', N'10367', N'01 - Imagens/01 - Antes/12065.jpeg', N'Controle de férias descentralizado em planilhas, gerando baixa confiabilidade das informações e esforço manual elevado.
INSERT INTO #PVC VALUES (12066, N'81058966', N'508825', N' Instalação de Válvula de Bloqueio para Otimização de Tempo e Segurança na Manutenção', 1, N'Others/Outros', N' Em uma necessidade de realizar bloqueio para manutenção de equipamento/linha, não existia válvula dedicada de bloqueio no trecho, sendo necessário realizar o bloqueio geral da linha ou despressurizar todo o sistema.', N'Otimizar o tempo de bloqueio e liberação para manutenção, reduzindo o tempo de parada em 75% (de 120 min para 30 min) através da instalação de válvula de bloqueio setorial.', N'10031', N'01 - Imagens/01 - Antes/12066.jpeg', N'Linha sem bloqueio setorial. Era necessário bloquear a válvula principal a 3 m e drenar toda a linha, gerando alto tempo de espera e impossibilitando o bloqueio localizado.', N'01 - Imagens/02 - Depois/12066.jpeg', N'Instalada válvula de bloqueio em ponto estratégico, permitindo isolamento do trecho em menos de 5 minutos, com LOTO dedicado, reduzindo significativamente o tempo de despressurização e drenagem.', NULL, N'Sim, tempo de bloqueio reduzido de 120 min para 25 min (-79%)', N'Investir em pontos de bloqueio setoriais planejados para manutenibilidade gera retorno rápido em segurança e produção. Pequena modificação de projeto elimina grande desperdício de tempo.', 0, NULL, N'Monitoramento contínuo das temperaturas, identificação antecipada de desvios e redução do risco de falhas e paradas não programadas.', '2026-08-24T00:00:00.000', '2026-08-31T10:15:17.000', N'81058966', NULL, NULL);
INSERT INTO #PVC VALUES (12067, N'81027090', N'81027090', N'Suporte para embarcados CV basculante', 1, N'Projects/Projetos', N'Falta de suporte para acomodar os embarcados dos novos equipamentos dos leves - Basculante ', N'Produtividade/segurança', N'10015', N'01 - Imagens/01 - Antes/12067.jpeg', N'Foi identificado que o equipamento basculante não possuía suporte adequado para a montagem do painel embarcado de automação.', N'01 - Imagens/02 - Depois/12067.jpeg', N'Foi projetado e instalado um suporte metálico dedicado para a fixação do painel embarcado de automação, garantindo resistência estrutural, segurança operacional e acesso facilitado para manutenção.', NULL, N'Sim! garantindo resistência estrutural, segurança operacional e acesso facilitado para manutenção.', N'Acesso facilitado para manutenção e segurança.', 0, NULL, N'Adequação de componentes de segurança.', '2026-08-20T00:00:00.000', '2026-08-31T10:39:51.000', N'81027090', NULL, NULL);
INSERT INTO #PVC VALUES (12068, N'520942', N'542508', N'Recebimento TOP LEADING E BOTTOM LOADING', 2, N'Projects/Projetos', N'Eliminar trabalho em Altura na descarrega de combustível e ergonomia de repetição de processo.', N'Eliminar trabalho em Altura na descarrega de combustivel', N'10077', N'01 - Imagens/01 - Antes/12068.jpeg', N'Realizar a descarga em trabalho em altura, preenchendo a PTS, conferindo os equipamentos e coletando a documentação do motorista.
INSERT INTO #PVC VALUES (12069, N'200500', N'120569', N'Roaster Feed Gate Guides', 1, N'Others/Outros', N'The existing OEM-designed Roaster Feed Gate guides were difficult and costly to maintain, resulting in excessive maintenance downtime, increased repair costs, and ergonomic challenges for maintenance personnel.', N'The Roaster Feed Gate guide system experiences maintenance costs, lengthy repair durations, and elevated ergonomic risk due to an OEM design that is difficult to maintain and dependent on expensive, long-lead replacement parts. These conditions reduce equipment availability and increase maintenance burden. A redesign is required to improve maintainability, reduce downtime, lower repair costs, and increase spare part accessibility while maintaining or improving equipment reliability.', N'10183', N'01 - Imagens/01 - Antes/12069.jpeg', N'The Roaster Feed Gates are purchased from Dezurik. The original design was very difficult and costly to maintain, requiring significant downtime and presenting MSD hazards to the mechanics. Additionally, OEM replacement parts were very expensive and long lead time. 
INSERT INTO #PVC VALUES (12070, N'542336', N'542336', N'CONTROLE DE MATERIAIS DESTINADOS A REFORMA DE COMPONENTES NA ', 1, N'Others/Outros', N'AUSÊNCIA DE UM CONTROLE CENTRALIZADO DOS MATERIAIS DESTINADOS À REFORMA DE COMPONENTES NA OFICINA CENRAL, DIFICULTANDO A IDENTIFICAÇÃO, APLICAÇÃO E QUANTIDADES NECESSÁRIA AO ATENDIMENTO, PROPORCIONANDO ATRASOS NAS REFORMAS E AQUISIÇÕES DESNECESSÁRIAS.', N'CONTROLE', N'10081', N'01 - Imagens/01 - Antes/12070.jpeg', N'O CONTROLE DOS MATERIAIS DESTINADOS À REFORMA DE COMPONENTES ERA REALIZADO DE FORMA DESCENTRALIZADA, SEM UMA VISÃO CONSOLIDADA POR ÁREA, ATIVO, COMPONENTE E TIPO DE MATERIAL. ISSO DIFICULTAVA A CONSULTA AOS CÓDIGOS, QUANTIDADES NECESSÁRIAS E SALDOS DISPONÍVEIS, AUMENTANDO O RISCO DE FALTA DE MATERIAIS, COMPRAS EMERGENCIAIS, DUPLICIDADES E ATRASOS NA EXECUÇÃO DAS REFORMAS PELA OFICINA CENTRAL.', N'01 - Imagens/02 - Depois/12070.jpeg', N'FOI IMPLEMENTADO UM CONTROLE CENTRALIZADO DOS MATERIAIS DESTINADOS À REFORMA DE COMPONENTES NA OFICINA CENTRAL, COM INFORMAÇÕES CONSOLIDADAS POR ÁREA, ATIVO, COMPONENTE, GRUPO E TIPO DE MATERIAL. A FERRAMENTA PERMITE CONSULTAR CÓDIGOS, QUANTIDADES NECESSÁRIAS E SALDOS DISPONÍVEIS, PROPORCIONANDO MAIOR RASTREABILIDADE, AGILIDADE E PREVISIBILIDADE. COMO RESULTADO, REDUZ O RISCO DE FALTA DE MATERIAIS, COMPRAS EMERGENCIAIS, CONTROLES DUPLICADOS E ATRASOS NAS REFORMAS.', NULL, N'SIM. O PROBLEMA FOI RESOLVIDO COM A IMPLANTAÇÃO DE UM CONTROLE CENTRALIZADO, PERMITINDO VISUALIZAR CÓDIGOS, QUANTIDADES NECESSÁRIAS E SALDOS DISPONÍVEIS POR COMPONENTE, REDUZINDO CONSULTAS MANUAIS, DUPLICIDADES E RISCOS DE ATRASO.', N'A CENTRALIZAÇÃO E A PADRONIZAÇÃO DAS INFORMAÇÕES MELHORAM A RASTREABILIDADE DOS MATERIAIS, ANTECIPAM POSSÍVEIS FALTAS E TORNAM O PLANEJAMENTO DAS REFORMAS MAIS CONFIÁVEL.', 0, NULL, N'Com a identificação dos equipamentos, foi feito um planejamento onde foi determinado uma prazo para visitar todos os equipamentos, após a visita é feito um relatório onde podemos verificar e gerar ações para que os equipamentos fiquem adequados para a  operação conforme as normas.', '2026-08-10T00:00:00.000', '2026-08-31T10:52:32.000', N'542336', NULL, NULL);
INSERT INTO #PVC VALUES (12071, N'81022554', N'964502', N'Bancada de emissão de pts Remoagem ', 1, N'Others/Outros', N'Durante a liberação das PTs (Permissões de Trabalho), os operadores não possuíam um local fixo próximo aos verticais da remoagem para realizar o preenchimento e a emissão dos documentos. Como consequência, as PTs eram abertas em locais inadequados, prejudicando a postura ergonômica dos colaboradores. Além disso, a prancheta com os anexos precisava ser apoiada em superfícies improvisadas, dificultando a atividade.
INSERT INTO #PVC VALUES (12072, N'81063762', N'81063762', N'Desenvolvimento de Metodologia para Classificação de Criticidade e Priorização de Componentes', 1, N'Others/Outros', N'Ausência de critério padronizado para priorização e classificação de sobressalentes durante a elaboração do orçamento anual e para tomadas de decisões na rotina. ', N'Desenvolver e implantar uma metodologia estruturada para classificação dos componentes em categorias Z, Y, X e W e subcategorias P0, P1, P2 e P3, utilizando critérios técnicos e econômicos padronizados.', N'10081', N'01 - Imagens/01 - Antes/12072.jpeg', N'Situação atual:
INSERT INTO #PVC VALUES (12073, N'532872', N'532872', N'Dashboard de Performance geral de Gestão do trabalho', NULL, N'Others/Outros', N'Painel de monitoramento da performance geral de gestão do Trabalho de CTO não desdobrado nos níveis desejados e gerência e supervisão e Centro de trabalho.', N'Monitoramento integrado da performance geral de gestão do Trabalho', N'10081', N'01 - Imagens/01 - Antes/12073.jpeg', N'Painel de monitoramento da performance geral de gestão do Trabalho de CTO não desdobrado nos níveis adequados para possibilitar melhoria ( gerência e supervisão e Centro de trabalho).', N'01 - Imagens/02 - Depois/12073.jpeg', N'Foi desenvolvido um novo dashboard de Gestão do Trabalho com desdobramento completo dos indicadores em todos os níveis da estrutura organizacional, permitindo análises hierarquizadas por gerência, supervisão e centro de trabalho. A solução proporciona maior visibilidade das áreas impactando, principais ofensores, direcionamento assertivo dos planos de ação e acompanhamento mais efetivo da performance operacional, fortalecendo a governança e a tomada de decisão.', N'https://app.powerbi.com/groups/me/apps/2f1cf443-5ea8-45a4-9860-b084ee3f2a39/reports/49c2fd06-e2cf-4712-bc38-8669f2adbbdb/38a81f7e2dd0073ea8b1?experience=power-bi', N'Sim, painel desenvolvido', N'desdobrar o problema no menor nível possível', 0, NULL, N'Priorização correta das notas de projetos, com foco em atacar primeiro riscos de segurança, depois riscos de processo. ', '2026-08-15T00:00:00.000', '2026-08-31T11:30:32.000', N'532872', NULL, NULL);
INSERT INTO #PVC VALUES (12074, N'81022554', N'964502', N' Bancada de emissão de pts Moagem', 1, N'Others/Outros', N'Durante a liberação das PTs (Permissões de Trabalho), os operadores não possuíam um local fixo próximo aos moinhos da moagem para realizar o preenchimento e a emissão dos documentos. Como consequência, as PTs eram abertas em locais inadequados, prejudicando a postura ergonômica dos colaboradores. Além disso, a prancheta com os anexos precisava ser apoiada em superfícies improvisadas, dificultando a atividade', N'A adequação proporcionou melhores condições ergonômicas aos operadores', N'10033', N'01 - Imagens/01 - Antes/12074.jpeg', N'Durante a liberação das PTs (Permissões de Trabalho), os operadores não possuíam um local fixo próximo aos moinhos da moagem para realizar o preenchimento e a emissão dos documentos. Como consequência, as PTs eram abertas em locais inadequados, prejudicando a postura ergonômica dos colaboradores. Além disso, a prancheta com os anexos precisava ser apoiada em superfícies improvisadas, dificultando a atividade.
INSERT INTO #PVC VALUES (12075, N'81026607', N'81026607', N'SUPORTE PARA COMANDO FINAL CAMINHÃO FORA DE ESTRADA ​', 2, N'No Replication/Sem replicação', N'A entrega de componentes no MRO de Sossego é de rotina com movimentações realizadas entre áreas e oficinas , na ocasião para o componente comando final de caminhão fora de estrada o suporte para o transporte não apresenta reforço nas extremidades com risco de movimentação.​', N'Garantir o transporte seguro do comando final de caminhão fora de estrada por meio da adequação do suporte', N'10330', N'01 - Imagens/01 - Antes/12075.jpeg', N'suporte utilizado para transporte não apresenta reforço nas extremidades, havendo risco de movimentação do componente durante o deslocamento.', N'01 - Imagens/02 - Depois/12075.jpeg', N'Após reuniões internas e visita em campo, foi criado projeto via engenharia para melhor adequação do componente e eliminando qualquer movimentação do componente em seu trajeto de entrega entre áreas , praças de maquinas e MRO.', NULL, N'O suporte utilizado para o transporte do componente comando final de caminhão fora de estrada não possuía reforço nas extremidades, gerando risco de movimentação da carga durante o deslocamento entre áreas e oficinas do MRO de Sossego.', N'A implementação de reforços nas extremidades do suporte eliminou o risco de deslocamento do comando final durante o transporte, aumentando a segurança, a confiabilidade do processo e a preservação dos ativos.', 0, NULL, NULL, '2026-08-25T00:00:00.000', '2026-08-31T12:03:55.000', N'81026607', NULL, NULL);
INSERT INTO #PVC VALUES (12076, N'538357', N'538357', N'RETIRAR BOTOEIRA DE RESETE DE DENTRO DO TRANSPORTADOR', 1, N'Others/Outros', N'NA NECESSIDADE DE RESETE DA CHAVE DETECTORA DE RASGO, FAZIA-SE NECESSÁRIO A ABERTURA DA PORTA PARA ACESSAR O BOTÃO DE RESETE NO TRANSPORTADOR.  ', N'ELIMINAR RISCOS EMINENTES AO ABRIR A PORTA DO PAINEL PARA REALIZAR O RESETE', N'10294', N'01 - Imagens/01 - Antes/12076.jpeg', N'O BOTÃO FICAVA NA PARTE INTERNA DO TRANSPORTADOR, SENDO NECESSÁRIO O ACESSO ABRINDO A PORTA.', N'01 - Imagens/02 - Depois/12076.jpeg', N'REALIZADO A MUDANÇA DE POSIÇÃO DA CAIXA DO BOTÃO DE RESETE PARA A LATERAL DO TRANSPORTADOR. ', NULL, N'SIM. NÃO É MAIS NECESSÁRIO A ABERTURA DA PORTA PARA ACESSAR A PARTE INTERNA DO TRANSPORTADOR.', N'SEMPTE EXISTEM POSSIBILIDADES DE MELHORIAS NO PROCESSO', 0, NULL, N'Eliminação do risco de queda de altura, aumento da segurança operacional, adequação às normas de segurança e maior proteção dos colaboradores.', '2026-08-26T00:00:00.000', '2026-08-31T12:38:25.000', N'538357', NULL, NULL);
INSERT INTO #PVC VALUES (12077, N'81042078', N'81055019', N'Implantação de Área de Segurança para Parada do Tripper Antes dos Fins de Curso', 1, N'Others/Outros', N'Durante a movimentação do tripper para o início ou para o fim do 
INSERT INTO #PVC VALUES (12078, N'81042078', N'81042078', N'Estruturação e Padronização do Estoque de Materiais do Laboratório', 1, N'Others/Outros', N'Anteriormente, o laboratório não possuía um estoque estruturado para armazenamento e controle dos materiais de consumo. Os itens eram armazenados em locais distintos, dificultando a localização, o acompanhamento dos níveis de estoque e a identificação das necessidades de reposição. Essa condição gerava desperdício de tempo na busca por materiais, riscos de falta de itens críticos e menor confiabilidade no controle dos recursos.
INSERT INTO #PVC VALUES (12079, N'488890', N'488890', N'Oculto não', 1, N'Projects/Projetos', N'Atualmente, não há disponibilidade de uma visualização em tempo real dos diferenciais de temperatura entre as engrenagens dos moinhos de bolas. Essa limitação dificulta o acompanhamento contínuo das condições operacionais do conjunto de acionamento, podendo atrasar a identificação de desvios de temperatura e, consequentemente, aumentar o risco de falhas, paradas não programadas e danos aos componentes mecânicos.', N'Ter visão em tempo real dos diferenciais de temperaturas engrenagem do moinhos de bolas. ', N'10054', N'01 - Imagens/01 - Antes/12079.jpeg', N'Antes da melhoria, não havia visualização em tempo real do diferencial de temperatura entre as engrenagens dos moinhos de bolas na sala de controle. Essa limitação dificultava o monitoramento contínuo pela operação e a identificação antecipada de desvios, aumentando o risco de falhas, danos aos componentes e paradas não programadas.', N'01 - Imagens/02 - Depois/12079.jpeg', N'Após a implantação da melhoria, a sala de controle passou a contar com a visualização em tempo real do diferencial de temperatura entre as engrenagens dos moinhos de bolas. A solução permite o monitoramento contínuo pela operação, facilitando a identificação antecipada de desvios e possibilitando ações preventivas para evitar falhas e paradas não programadas.', NULL, N'Meta atingida, com disponibilização do monitoramento em tempo real do diferencial de temperatura na sala de controle.
INSERT INTO #PVC VALUES (12080, N'520942', N'542508', N'VALVULA ESFERICA  ', 2, N'No Replication/Sem replicação', N'válvula esférica com posicionamento voltada para o eixo da bomba.
INSERT INTO #PVC VALUES (12081, N'81030963', N'81041935', N'Mitigação: Pessoas x Máquina', 1, N'Others/Outros', N'próximo dos equipamento e pessoas expostas 
INSERT INTO #PVC VALUES (12082, N'81026607', N'81026607', N'Padronização do Agendamento de Salas de Reunião', 1, N'No Replication/Sem replicação', N'O agendamento e identificação da sala de reunião era realizado sem uma padronização definida e sem a identificação das reuniões fixas. Essa condição dificultava a visualização da disponibilidade das salas, gerava conflitos de agendamento, dúvidas sobre a ocupação dos espaços e maior tempo para consulta e organização das reservas.
INSERT INTO #PVC VALUES (12083, N'542798', N'594051', N'Dashboards NR12', 1, N'Others/Outros', N'Equipamentos com ações pendentes na NR12 devido, a necessidade de uma apreciação de risco para adequação nas normas regulamentadoras.', N'Atender todos os ativos ', N'10081', N'01 - Imagens/01 - Antes/12083.jpeg', N'Necessidade de um acompanhamento da apreciação de risco relacionada a NR12.', N'01 - Imagens/02 - Depois/12083.jpeg', N'Criado Dashboards para acompanhamento de equipamentos adequados as normas regulamentadoras e o andamentos dos planos de ações para adequação dos equipamentos que estão com pendencias, com esse acompanhamento conseguimos identificar todos os equipamentos mapeados.', NULL, N'Sim, conseguimos identificar todos os equipamentos que precisavam realizar a apreciação de risco. ', N'Deixar todos os ativos adequados a NR12.', 0, NULL, N'Date meaning now clear.', '2026-08-21T00:00:00.000', '2026-08-31T14:51:15.000', N'542798', NULL, NULL);
INSERT INTO #PVC VALUES (12084, N'522369', N'522369', N'PISO COM DEMARCAÇÃO KANBAN ELÉTRICA USINA', 3, N'No Replication/Sem replicação', N'DIFICULDADE DEMARCAÇÃO INCOMPLETA FEITAS COM FITAS COLORIDA AMARELA QUE ESTAVA SOLTAS COM O TEMPO DE USO. DEIXANDO O LAYOUT DE PADRONIZAÇÃO INCOMPLETA.', N'PADRONIZAÇÃO NO 5S ', N'10178', N'01 - Imagens/01 - Antes/12084.jpeg', N'PISO SEM DEMARCAÇÃO DE SEGURANÇA PARA SINALIZAR AS PRATELEIRAS NO PADRÃO DE LAYOUT DE 5S NO KANBAN ELÉTRICA USINA I,II.', N'01 - Imagens/02 - Depois/12084.jpeg', N'FOI FEITO UM PINTURA CINZA E AMARELA NO PADRÃO DE 5S NO PISO DO KANBAN ELÉTRICA COM MARCAÇÃO AMARELA PARA SINALIZAR O CAMINHO SEGURO NO LOCAL.', NULL, N'BAIXA QUALIDADE DO PISO SEM DEMARCAÇÃO ADEQUADA NO OBTENDO UM CAMINHO SEGURO. APOIO A IMPLANTAÇÃO MELHOROU A ALTO ESTIMA DA EQUIPE.', N'MELHOROU O LOCAL PARA FACILITAR UMA AVALIAÇÃO DE ELEVAR A MATURIDADE 4 NO KANBAN ELÉTRICA EM 2026', 0, NULL, N'Garantia da segurança das pessoas envolvidas no procedimento. ', '2026-08-24T00:00:00.000', '2026-08-31T14:59:39.000', N'522369', NULL, NULL);
INSERT INTO #PVC VALUES (12085, N'486546', N'486546', N'Acesso Inteligente de Comboios à Mina', 2, N'Open Pit/Poço aberto', N'Os comboios de combustível utilizavam acesso compartilhado com veículos, equipamentos e carretas de grande porte em uma via estreita, gerando filas, atrasos operacionais e aumento do risco de trânsito. O acesso alternativo exigia abertura manual de corrente e cadeado, demandando desembarque do operador e maior exposição às condições climáticas.', N'Reduzir o tempo de acesso dos comboios à mina, eliminando exposições desnecessárias ao trânsito operacional e aumentando a segurança e o controle dos acessos.', N'10079', N'01 - Imagens/01 - Antes/12085.jpeg', N'Os comboios de combustível compartilhavam uma via estreita com outros veículos, gerando filas, atrasos e maior risco de trânsito. O acesso alternativo exigia desembarque para abertura manual de corrente/ cadeado.', N'01 - Imagens/02 - Depois/12085.jpeg', N'Implantada cancela automatizada com leitura de crachá, eliminando o desembarque do operador, reduzindo a exposição ao trânsito, aumentando a agilidade operacional e o controle de acessos. ', NULL, N'A implantação da cancela automatizada eliminou a abertura manual por corrente e cadeado, reduziu a exposição dos operadores aos riscos do trânsito operacional, eliminou filas e tempos de espera no acesso à mina e permitiu acesso controlado exclusivamente por colaboradores autorizados. A solução trouxe ganhos significativos em segurança, produtividade e eficiência operacional.', N'Pequenas melhorias em atividades rotineiras podem eliminar exposições críticas a riscos, reduzir desperdícios de tempo e aumentar a eficiência operacional de forma simples e sustentável.', 0, NULL, N'New instrument has less components to fail and less spare parts.', '2026-08-28T00:00:00.000', '2026-08-31T15:21:52.000', N'486546', NULL, NULL);
INSERT INTO #PVC VALUES (12086, N'526788', N'526788', N'Priorização inteligente de Notas de Projeto', 1, N'Projects/Projetos', N'A priorização das notas de projeto extraídas do SAP era realizada de forma predominantemente manual, exigindo consolidação da base, eliminação de duplicidades, conferência de status, leitura das descrições e avaliação individual de riscos e prazos. Esse processo consumia tempo da equipe, dependia do julgamento de cada engenheiro/projetista e gerava risco de inconsistência na classificação, retrabalho e atraso na identificação de demandas críticas de Segurança, Saúde e continuidade do processo produtivo. Além disso, o ranking da carteira, os indicadores e a visão macro dos prazos precisavam ser preparados separadamente.', N'Automatizar a análise de 100% das notas de projeto elegíveis contidas na base SAP selecionada, padronizando sua classificação em prioridades P1 a P4 de acordo com a hierarquia Segurança/Saúde, risco de processo, PGU, prazo e idade da nota. Gerar, em uma única execução, o ranking da carteira, as justificativas de priorização, os indicadores, o relatório executivo e a visão macro do cronograma por meio da Curva S, mantendo rastreabilidade para eventuais ajustes manuais.', N'10184', N'01 - Imagens/01 - Antes/12086.jpeg', N'Após a extração da base do SAP, era necessário tratar e analisar manualmente as informações. O responsável precisava identificar as notas de projeto, verificar quais permaneciam abertas, consolidar registros repetidos, consultar status, ler descrições curtas e textos longos, avaliar criticidade, conferir prazos e então organizar uma sequência de execução.
INSERT INTO #PVC VALUES (12087, N'81037142', N'81035997', N'Dispositivo para medição de pressão', 1, N'Projects/Projetos', N'BA 2305SA-02, equipamento sem nenhum dispositivo para medição de pressão, dificultando o acompanhamento do desempenho da mesma.', N'Instalar o manômetro ou transmissor de pressâo', N'10031', N'01 - Imagens/01 - Antes/12087.jpeg', N'BA 2305SA-02, equipamento sem nenhum dispositivo para medição de pressão, dificultando o acompanhamento do desempenho da mesma.', N'01 - Imagens/02 - Depois/12087.jpeg', N'Depois BA 2305SA-02, instalado manômetro na tubulação de recalque para a identificação precisa da pressão de saída do equipamento, evitando baixo desempenho e cavitação', NULL, N'Sim, com a instalação do manômetro foi possível fazer identificação precisa da pressão.', N'Sim', 0, NULL, N'Well labelled areas.', '2026-08-28T00:00:00.000', '2026-08-31T15:45:53.000', N'81037142', NULL, NULL);
INSERT INTO #PVC VALUES (12088, N'607251', N'607251', N'Proper troubleshooting equipment', 1, N'Underground/Subterrâneo', N'Mobile department not having the proper electronic testing equipment to troubleshoot and repair issues on Kubota and Caterpillar equipment', N'Reduce contracting out. Give Vale tech''s the proper equipment to perform troubleshooting and repairs', N'10066', N'01 - Imagens/01 - Antes/12088.jpeg', N'The mobile department relied on OEM''s (contractors) to come to site and troubleshoot using their electronic testing equipment.', N'01 - Imagens/02 - Depois/12088.jpeg', N'Totten mobile department purchased the proper licensing and programs to install on our laptop. Now Vale technicians have the proper equipment to troubleshoot and repair our machines without calling in contractors.  ', NULL, N'Yes, the problem was solved. ', N'Always look for solutions to problems', 5000, 3, N'Segurança operacional', '2026-08-28T00:00:00.000', '2026-08-31T16:01:14.000', N'607251', NULL, NULL);
INSERT INTO #PVC VALUES (12089, N'547290', N'547290', N'Guarda vida', 2, N'No Replication/Sem replicação', N'Antes da melhoria, a área encontrava-se sem sistema de proteção coletiva (guarda-corpo), gerando risco de queda de pessoas de uma altura superior a 4 metros e comprometendo a segurança operacional.', N'eliminar io risco ', N'10054', N'01 - Imagens/01 - Antes/12089.jpeg', N'Foi identificada a ausência de guarda-corpo na área, criando uma condição insegura com potencial de queda de altura superior a 4 metros.', N'01 - Imagens/02 - Depois/12089.jpeg', N'Realizada a instalação de guarda-corpo conforme os requisitos de segurança, criando uma barreira de proteção coletiva que elimina a exposição dos trabalhadores ao risco de queda de altura superior a 4 metros.', NULL, N'Eliminação do risco de queda de altura, aumento da segurança operacional, adequação às normas de segurança e maior proteção dos colaboradores.', N'Não aprender a conviver com os risco ', 0, NULL, N'Ganho predominantemente qualitativo, relacionado à melhoria da 
INSERT INTO #PVC VALUES (12090, N'526788', N'526788', N'Gestão Inteligente da Razão entre Manutenção Corretiva e Preventiva', 1, N'Others/Outros', N'A análise da relação entre manutenções corretivas e preventivas dependia de planilhas e de um notebook analítico que exigia conhecimento técnico, alteração de código e reprocessamentos para cada novo recorte. A investigação por área, sistema, ativo, centro de trabalho, modo de falha, quantidade de ordens, homem-hora e custo não estava disponível em uma ferramenta única de uso diário.
INSERT INTO #PVC VALUES (12091, N'81033139', N'81033139', N'Análise Técnica Econômica de Recapabilidade  ', 1, N'Others/Outros', N'A estratégia de recapagem era aplicada sem uma avaliação integrada dos custos de reforma, vida útil alcançada e impacto das paradas de equipamento, gerando risco de investimentos em reformas sem retorno econômico para o negócio.
INSERT INTO #PVC VALUES (12092, N'81016620', N'81016620', N'Painel do ciclonagem PS- 2308SA-31', 1, N'Others/Outros', N'Foi identificado que o sistema não possui recursos para bloqueio e isolamento individual das válvulas solenoide.', N'Realizado adequação do painel de comando pneumático', N'10197', N'01 - Imagens/01 - Antes/12092.jpeg', N'O painel- 2308SA-31 era composto por conjunto de válvulas direcionais pneumáticas alimentadas por uma única linha de ar comprimido, sem a disponibilidade de válvulas de bloqueio individual ou dispositivos que permitam isolar um único atuador durante atividades de manutenção, testes ou substituição de componentes.', N'01 - Imagens/02 - Depois/12092.jpeg', N'Foi realizada adequação do painel-2308SA-31 de comando pneumático com a instalação de válvulas de bloqueio individualizadas em cada circuito de acionamento. Cada válvula solenoide passou a contar com um dispositivo de isolamento dedicado, permitindo o bloqueio independente do fornecimento de ar comprimido para cada atuador controlado.​', NULL, N'Após a substituição do painel aumentou a segurança das intervenções, reduzindo o tempo de manutenção e melhorando a confiabilidade operacional do sistema pneumático.', N'Maior confiabilidades da painel do comandos das válvulas solenoides.', 0, NULL, N'A melhoria da sinalização visual de equipamentos, mesmo de pequeno porte, contribui para aumentar sua visibilidade e percepção no ambiente operacional, fortalecendo a prevenção de incidentes e tornando a operação mais segura.', '2026-08-12T00:00:00.000', '2026-08-31T16:22:18.000', N'81016620', NULL, NULL);
INSERT INTO #PVC VALUES (12093, N'389635', N'389635', N'Controle de Qualidade Despacho Sossego', 1, N'Others/Outros', N'Dificuldade no acompanhamento de taxa horária na britagem, dificultado a tomada de decisão na designação de equipamentos de transporte para os ciclos de alimentação e frentes de lavra.', N'Melhorar o controle de Taxa horária na Britagem', N'#N/A', N'01 - Imagens/01 - Antes/12093.jpeg', N'Inexistência de uma ferramenta web integrada que permita monitorar, em tempo real, a alimentação da britagem primária, relacionando o número de viagens e a massa depositada às respectivas frentes de lavra e ao teor homogeneizado.', N'01 - Imagens/02 - Depois/12093.jpeg', N'Foi desenvolvida e disponibilizada uma solução web baseada em SQL Server para consulta em tempo real da composição homogeinizada das frentes de lavra. A ferramenta apresenta indicadores estratégicos, como teor, massa e quantidade de viagens por hora, proporcionando maior visibilidade operacional e suporte à tomada de decisão. A iniciativa contribuiu para aumentar a assertividade do Despacho no direcionamento da frota, garantindo melhor aderência às taxas de alimentação estabelecidas para o britador e maior controle sobre a qualidade do material alimentado', N'https://siam.valenet.valeglobal.net/Reports/report/SIAM/011_Sossego/R11_014_Controle_Qualidade', N'Sim, as equipes relatam maior clareza nas informações.', N'A disponibilidade de dados analíticos confiáveis contribui para decisões mais assertivas e bem fundamentadas.', 0, NULL, N'ADQUIRIDO BALIZADOR DE LED PARA SINALIZAR COM SEGURANÇA AO OPERADOR DE EQUIPAMENTOS PARA MANOBRAS OU MOVIMENTAÇOES', '2026-08-30T00:00:00.000', '2026-08-31T16:26:36.000', N'389635', NULL, NULL);
INSERT INTO #PVC VALUES (12094, N'607148', N'81036983', N'CHP Operating Sheets', 3, N'Refining/Refino', N'No formal designated area to store completed CHP Operating sheets.', N'5s', N'10275', N'01 - Imagens/01 - Antes/12094.jpeg', N'No 5S labelling with specific home for operating sheets', N'01 - Imagens/02 - Depois/12094.jpeg', N'Formal designated home created', NULL, N'New 5s location created.', N'Importance of 5s', 0, NULL, N'DEFINIDO E POSICIONADO EXTINTOR DE INCENDIO MANUAL EM SUPORTE, NO LOCAL DE LIVRE ACESSO, SEM INTERCORRÊNCIAS E BLOQUEIOS DAS ATIVIDADES DE CALDEIRARIA', '2026-08-03T00:00:00.000', '2026-08-31T16:42:53.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (12095, N'607148', N'81023580', N'CHP Spare Cloth Management', 3, N'Refining/Refino', N'Difficult to find cloths when needed.', N'5s', N'10275', N'01 - Imagens/01 - Antes/12095.jpeg', N'Cloths not organized making it hard to find cloths and do inventory.', N'01 - Imagens/02 - Depois/12095.jpeg', N'Each cloth type has specific location labelled with part #''s', NULL, N'Less time wasted on finding cloths and doing inventory.', N'5s importance', 0, NULL, N'FOI ELABORADA, CONFECCIONADA EM CALDEIRARIA LOCAL E INSTALADA UMA CAIXA DE BLOQUEIO DE CHAVE GERAL DO CAMINHAO PIPA, PERMITINDO O BLOQUEIO DE ENERGIA PARA ATIVIDADES DE MANUTENÇÃO', '2026-08-04T00:00:00.000', '2026-08-31T16:48:57.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (12096, N'607148', N'81032308', N'Breathing Air Bottle Tagging', 3, N'Refining/Refino', N'During the Breathing Air Bottle expiry PM, it was identified that inconsistent labeling was being applied to the incoming bottles. Some appeared to be labeled with their delivery date, and some appeared to be labeled with their expiry date (1 year after receipt). This caused confusion during the PM, as some still usable bottles may have been discarded as the ambiguous date on the tag had multiple interpretations.', N'5s', N'10275', N'01 - Imagens/01 - Antes/12096.jpeg', N'Breathing Air Bottle tagged with an ambiguous date.', N'01 - Imagens/02 - Depois/12096.jpeg', N'The Operator responsible for adding status tags to the incoming bottles was asked to add detail to eliminate the uncertainty around the date (ie. EXP Mar/27).', NULL, N'Date meaning now clear.', N'Importance of clarity and detail.', 0, NULL, N'FORAM INSTALADOS ADESIVOS RELFETIVOS NAS COLUNAS DA TENDA DE CALDEIRARIA, CRIANDO UMA SINALIZAÇÃO VISUAL PARA OS OPERADORES, VISANDO MAIOR SEGURANÇA NAS MOVIMENTAÇÕES E OPERAÇÃO DE EQUIPAMENTOS MOVEIS', '2026-08-05T00:00:00.000', '2026-08-31T16:57:29.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (12097, N'544624', N'544624', N'Guilhotina Baixo Giro', 1, N'Others/Outros', N'Dificuldade para realizar a abertura da guilhotina do baixo giro do 2251 MO 03', N'Realizar abertura da guilhotina com esforço mínimo. ', N'10054', N'01 - Imagens/01 - Antes/12097.jpeg', N'Antes da implementação da melhoria, a abertura da guilhotina de baixo giro do 2251 MO 03 era realizada manualmente, exigindo grande esforço físico dos operadores, o que gerava desconforto e risco ergonômico, além de apresentar risco de prensamento de mãos e dedos durante a execução da atividade, comprometendo a segurança no processo.', N'01 - Imagens/02 - Depois/12097.jpeg', N'Realizado a instalação de uma catraca manual com trava para facilitar a elevação da guilhotina da engrenagem da bomba hidráulica do baixo giro. Essa melhoria reduziu significativamente o tempo de atuação dos operadores e eliminou riscos ergonômicos, prensamento de mãos e dedos. ', NULL, N'Alcançado a satisfação de modo geral dos operadores', N'Otimizar riscos e procedimentos', 0, NULL, N'FOI REALIZADA A AQUISIÇÃO DE PISO PORTAFLOOR, COMPOSTO DE POLIMEROS, VISANDO ADEQUAR A AREA ADMINISTRATIVA DO PATIO DE MONTAGEM, COM GANHOS EM SAUDE E SEGURANÇA', '2026-08-30T00:00:00.000', '2026-08-31T16:59:31.000', N'544624', NULL, NULL);
INSERT INTO #PVC VALUES (12098, N'607148', N'300582', N'Upgrade UV-Vis Spectrophotometer', 1, N'Refining/Refino', N'OLD instrument had a sipper to pull sample into a cell with more parts that could fail than newer technology for UV-Vis Spectrophotometers made today.', N'Productivity/Reliability', N'10275', N'01 - Imagens/01 - Antes/12098.jpeg', N'OLD instrument had a sipper to pull sample into a cell with more parts that could fail than newer technology for UV-Vis Spectrophotometers made today.', N'01 - Imagens/02 - Depois/12098.jpeg', N'New UV-Vis Spectrophotometer has no sipper to fail mechanically and operates using fibre optics. Less parts to fail and no sample reservoir for spent samples to manage.', NULL, N'New instrument has less components to fail and less spare parts.', N'New technology efficiencies', 0, NULL, N'ELABORADO SOB MEDIDA E ADQUIRIDA UMA PRATELEIRA PARA CHAPARIA METALICA, VISANDO ORGANIZAR CHAPAS E CANTONEIRAS', '2026-08-06T00:00:00.000', '2026-08-31T17:04:22.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (12099, N'607148', N'81024727', N'Upgrading Chem Cleaning Garden Spray Bottles', 2, N'Refining/Refino', N'Ops reported that there is difficulty in relieving built-up pressure in the spray bottle once solution is prepared with potential for sprayback if improperly removing lid before pressure is evacuated via the wand. Ops requested if possible, spray bottle with pressure relief valve', N'Safety', N'10275', N'01 - Imagens/01 - Antes/12099.jpeg', N'Ops reported that there is difficulty in relieving built-up pressure in the spray bottle once solution is prepared with potential for sprayback if improperly removing lid before pressure is evacuated via the wand. Ops requested if possible, spray bottle with pressure relief valve', N'01 - Imagens/02 - Depois/12099.jpeg', N'Sourced new bottle from different manufacturer that came with built-in pressure relieve valve. After testing with various operators and obtaining positive feedback for ease-of-use, new spray bottles were deployed to be used for application of chem cleaning.', NULL, N'New sprayers have controlled relief valve.', N'Importance of ZES', 0, NULL, N'ELABORADO E CONFECCIONADOS SUPORTES PARA ARMAZENAMENTO DAS FERRAMENTAS DE TRABALHO A QUENTE, PROMOVENDO MAIOR SEGURANÇA OPERACIONAL E ORGANIZAÇÃO DO AMBIENTES, OTIMIZANDO OS ESPAÇOS DOS ARMARIOS', '2026-08-07T00:00:00.000', '2026-08-31T17:09:57.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (12100, N'607148', N'81036983', N'ECR Vibrafinisher Fines Drain/Chute labelling 5S', 3, N'Refining/Refino', N'The ECR Vibrafinisher North fines cleanout chutes were a continual area being missed by Ops on pull days for getting cleaned out. With a few instances of blocking being reported over the last few months to the floor sump below. When quizzed operators would forget it apart of routines or not know the process for cleaning out. Labelling in the area as well as coaching will help with knowing the areas to be cleaned out and help put equipment back when job is completed.', N'5s', N'10275', N'01 - Imagens/01 - Antes/12100.jpeg', N'Blank area with no labelling and tools not put back in proper home.', N'01 - Imagens/02 - Depois/12100.jpeg', N'Labelling to show where the Vibrafinisher needs to be cleaned out, the areas the cleanouts go to and clear markings on where tools need to be returned to upon completion of the job.', NULL, N'Well labelled areas.', N'5s importance', 0, NULL, N'FOI DESENVOLVIDO SUPORTE PARA ARMAZENAR E TRANSPORTAR DE MANEIRA ESTÁVEL E SEGURA O MACACO HIDRAULICO COM APOIO DA EMPILHADEIRA', '2026-08-10T00:00:00.000', '2026-08-31T17:14:33.000', N'607148', NULL, NULL);
INSERT INTO #PVC VALUES (12101, N'544624', N'81009655', N'Refletor de inspeção na alimentação dos moinhos', 1, N'No Replication/Sem replicação', N'Falta de iluminação na alimentação dos moinhos', N'Garantir a qualidade da inspeção', N'10054', N'01 - Imagens/01 - Antes/12101.jpeg', N'Durante o procedimento de alimentação dos moinhos de bolas, o operador encontrava dificuldade para realizar a inspeção da caixa de alimentação do moinho. ', N'01 - Imagens/02 - Depois/12101.jpeg', N'Realizado a instalação de um refletor direcionado para dentro da caixa, gerando visibilidade facilitada do material na alimentação.', NULL, N'Redução do tempo de inspeção, facilidade na visualização.', N'Garantia de confiabilidade', 0, NULL, N'FOI DESENVOLVIDO UM SUPORTE PARA TRAVAR A LATA DE ELETRODOS E PROPORCIONAR SUA ABERTURA DE MANEIRA A MINIMIZAR OS RISCOS DE PRENSAMENTOS E CORTES, ALEM DE AGILIZAR DE MANEIRA SEGURA', '2026-08-26T00:00:00.000', '2026-08-31T18:19:29.000', N'544624', NULL, NULL);
INSERT INTO #PVC VALUES (12102, N'81055041', N'81055041', N'Implantação do Sistema de Identificação Visual e Controle de Retenção e Descarte de Amostras Arquivadas', 1, N'Others/Outros', N'Anteriormente, as amostras arquivadas no laboratório não possuíam identificação visual padronizada contendo informações como embarque, navio, cliente, data de embarque, data prevista para descarte e localização física nas estantes. Essa condição dificultava a localização das amostras, aumentava o tempo gasto em consultas e verificações, comprometia a rastreabilidade do processo e gerava riscos de descarte incorreto ou retenção além do prazo estabelecido. Além disso, para confirmar informações relacionadas às amostras arquivadas era necessária a consulta a registros e controles paralelos, tornando o processo menos eficiente e aumentando o tempo necessário para execução das atividades de arquivamento, retenção e descarte.', N'Padronizar a identificação das amostras arquivadas por meio da implementação de etiquetas contendo informações do embarque, cliente, localização física e data de descarte, assegurando a rastreabilidade, o controle dos prazos de retenção, a agilidade na localização das amostras e a conformidade com os procedimentos e acordos estabelecidos com os clientes.', N'10294', N'01 - Imagens/01 - Antes/12102.jpeg', N'O processo anterior consistia em:
INSERT INTO #PVC VALUES (12103, N'81046574', N'81046574', N'Controle de Materiais Estocáveis', 1, N'Others/Outros', N'Durante o primeiro semestre de 2026 houve diversas falhas envolvendo o processo de materiais esticáveis que culminaram no aumento de custo com fretes emergências e em horas de manutenção corretiva. Com isso, esse controle visa automatizar essa visão de forma precisa e clara.', N'Criar visão sistêmica da acuracidade dos itens estocáveis', N'10081', N'01 - Imagens/01 - Antes/12103.jpeg', N'Não havia', N'01 - Imagens/02 - Depois/12103.jpeg', N'Criado controle com visão sistêmica da situação do estoque da fase mina e usina. Além disso, é possível cruzar com as áreas e fases do sistema operacional.', NULL, N'sim, em virtude que foi possível trazer uma visão clara do processo.', N'Ferramenta evitou a necessidade atualização manual e dependências humanas para o processo,', 0, NULL, N'MELHOR PRODUTIVIDADE E ACERTIVIDADE NA INSPEÇÃO DOS ATIVOS.', '2026-08-28T00:00:00.000', '2026-08-31T21:32:59.000', N'81046574', NULL, NULL);
INSERT INTO #PVC VALUES (12104, N'493280', N'81033881', N'Desenvolvimento de Sistema de Tamponamento dos Alimentadores 2202-AL-01, 2202-AL-02 e 2202-AL-03', 1, N'Crusher/Britadeira', N'A presença da pilha de minério sobre os alimentadores 2202-AL-01, 02 e 03 impedia o bloqueio efetivo do fluxo de material, inviabilizando intervenções seguras na correia transportadora localizada a jusante do sistema.', N'Permitir o isolamento seguro da pilha de minério, viabilizando a manutenção da correia transportadora e a operacionalização do sistema de contingência.', N'10081', N'01 - Imagens/01 - Antes/12104.jpeg', N'Não existia um método para isolar a carga de minério armazenada sobre os alimentadores, impossibilitando a execução de manutenção na correia transportadora e restringindo alternativas operacionais durante a parada da planta.', N'01 - Imagens/02 - Depois/12104.jpeg', N'Foi desenvolvido e instalado um sistema de tamponamento dos alimentadores 2202-AL-01, 2202-AL-02 e 2202-AL-03, permitindo o bloqueio temporário do fluxo de minério e o isolamento seguro da área de intervenção.', NULL, N'Sim. O tamponamento permitiu isolar a pilha de minério dos alimentadores, viabilizando a manutenção da correia transportadora e a operacionalização do sistema de contingência de forma segura e eficiente.', N'O desenvolvimento de soluções de isolamento temporário pode ampliar a flexibilidade operacional e reduzir restrições de manutenção em sistemas críticos.', 0, NULL, N'Allow more efficient passenger movement for outbound travellers.', '2026-07-30T00:00:00.000', '2026-08-31T22:40:44.000', N'493280', NULL, NULL);
INSERT INTO #PVC VALUES (12105, N'92000587', N'641183', N'MONTAGEM GIROFLEX ', 1, N'Others/Outros', N'EQUIPAMENTO COM POUCA VISIBILIDADE JÁ QUE É PEQUENO ', N'MELHOR VISIBILIDADE', N'10144', N'01 - Imagens/01 - Antes/12105.jpeg', N'O equipamento apresentava baixa visibilidade à distância,principalmente durante operações no período noturno, devido à ausência de sinalização luminosa ,dificultando sua identificação no ambiente operacional.', N'01 - Imagens/02 - Depois/12105.jpeg', N'Montado um giroflex,para terem melhor visibilidade a distância,já que o equipamento é de pequeno porte,facilitará com que os demais operadores tenha uma melhor facilidade em identificar o equipamento', NULL, N'Baixa visibilidade do equipamento à distância, principalmente no período noturno, devido à ausência de giroflex.', N'MELHOR PERCEPÇÃO NO AMBIENTE OPERACIONAL ', 0, NULL, N'foi eliminado o uso de pta e consequentimente o trabalho em altura nessa atividade. ', '2026-04-11T00:00:00.000', '2026-08-31T23:03:18.000', N'92000587', NULL, NULL);
INSERT INTO #PVC VALUES (12106, N'478853', N'478853', N'BALIZADOR DE LED', 2, N'Others/Outros', N'AUSENCIA DE INDICADOR SINALIZADOR PARA BALIZAR A MOVIMENTAÇÃO E MANOBRA DE EQUIPAMENTOS DE GRANDE PORTE', N'SEGURANÇA', N'10234', N'01 - Imagens/01 - Antes/12106.jpeg', N'AUSENCIA DE INDICADOR SINALIZADOR PARA BALIZAR A MOVIMENTAÇÃO E MANOBRA DE EQUIPAMENTOS DE GRANDE PORTE', N'01 - Imagens/02 - Depois/12106.jpeg', N'ADQUIRIDO BALIZADOR DE LED PARA SINALIZAR COM SEGURANÇA AO OPERADOR DE EQUIPAMENTOS PARA MANOBRAS OU MOVIMENTAÇOES', NULL, N'AUSENCIA DE INDICADOR SINALIZADOR PARA BALIZAR A MOVIMENTAÇÃO E MANOBRA DE EQUIPAMENTOS DE GRANDE PORTE', N'SEGURANÇA', 0, NULL, N'Maior rastreabilidade, organização do processo, controle de estoque e conscientização sobre o uso dos recursos.', '2026-08-10T00:00:00.000', '2026-08-31T23:08:16.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12107, N'478853', N'478853', N'SUPORTE EXTINTOR CALDEIRARIA', 2, N'Others/Outros', N'AUSENCIA DE LOCAL ADEQUADO E ERGONOMICO PARA EXTINTOR DE INCENDIO NA AREA DE CALDEIRARIA', N'5S E SEGURANÇA', N'10234', N'01 - Imagens/01 - Antes/12107.jpeg', N'AUSENCIA DE LOCAL ADEQUADO E ERGONOMICO PARA EXTINTOR DE INCENDIO NA AREA DE CALDEIRARIA', N'01 - Imagens/02 - Depois/12107.jpeg', N'DEFINIDO E POSICIONADO EXTINTOR DE INCENDIO MANUAL EM SUPORTE, NO LOCAL DE LIVRE ACESSO, SEM INTERCORRÊNCIAS E BLOQUEIOS DAS ATIVIDADES DE CALDEIRARIA', NULL, N'AUSENCIA DE LOCAL ADEQUADO E ERGONOMICO PARA EXTINTOR DE INCENDIO NA AREA DE CALDEIRARIA', N'5s E SEGURANÇA', 0, NULL, N'A melhoria contribuiu para a organização do ambiente, melhor utilização do espaço disponível e fortalecimento das práticas de 5S.', '2026-08-19T00:00:00.000', '2026-08-31T23:13:17.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12108, N'478853', N'478853', N'CAIXA DE BLOQUEIO CAMINHAO PIPA', 2, N'Others/Outros', N'AUSENCIA DE CAIXA DE BLOQUEIO PARA CHAVE GERAL DE CAMINHÃO PIPA', N'SEGURANÇA', N'10234', N'01 - Imagens/01 - Antes/12108.jpeg', N'AUSENCIA DE CAIXA DE BLOQUEIO PARA CHAVE GERAL DE CAMINHÃO PIPA', N'01 - Imagens/02 - Depois/12108.jpeg', N'FOI ELABORADA, CONFECCIONADA EM CALDEIRARIA LOCAL E INSTALADA UMA CAIXA DE BLOQUEIO DE CHAVE GERAL DO CAMINHAO PIPA, PERMITINDO O BLOQUEIO DE ENERGIA PARA ATIVIDADES DE MANUTENÇÃO', NULL, N'AUSENCIA DE CAIXA DE BLOQUEIO PARA CHAVE GERAL DE CAMINHÃO PIPA', N'ADEQUAÇAO SEGURANÇA', 0, NULL, N'Alem de eliminar o esforço fisico e ergonomico ganhamos em eliminação de colaborador e  linha de fogo de arco eletrico e explosoes. ', '2026-08-20T00:00:00.000', '2026-08-31T23:16:43.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12109, N'478853', N'478853', N'FAIXA REFLETIVA COLUNA TENDA CALDEIRARIA', 2, N'Others/Outros', N'AUSENCIA DE SINALIZADOR DE COLUNA NA TENDA DE CALDEIRARIA ONDE OCORRE INTEREAÇÃO COM MAQUINAS E EQUIPAMENTOS MOVEIS', N'ADEQUAÇÃO SEGURANÇA', N'10234', N'01 - Imagens/01 - Antes/12109.jpeg', N'AUSENCIA DE SINALIZADOR DE COLUNA NA TENDA DE CALDEIRARIA ONDE OCORRE INTEREAÇÃO COM MAQUINAS E EQUIPAMENTOS MOVEIS', N'01 - Imagens/02 - Depois/12109.jpeg', N'FORAM INSTALADOS ADESIVOS RELFETIVOS NAS COLUNAS DA TENDA DE CALDEIRARIA, CRIANDO UMA SINALIZAÇÃO VISUAL PARA OS OPERADORES, VISANDO MAIOR SEGURANÇA NAS MOVIMENTAÇÕES E OPERAÇÃO DE MAQUINAS E EQUIPAMENTOS MOVEIS', NULL, N'AUSENCIA DE SINALIZADOR DE COLUNA NA TENDA DE CALDEIRARIA ONDE OCORRE INTEREAÇÃO COM MAQUINAS E EQUIPAMENTOS MOVEIS', N'ADEQUAÇAO SEGURANÇA', 0, NULL, NULL, '2026-08-19T00:00:00.000', '2026-08-31T23:21:54.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12110, N'478853', N'478853', N'PISO PORTAFLOOR AREA ADM PATIO MONTAGEM', 3, N'Projects/Projetos', N'AUSENCIA DE PISO NIVELADO E ADEQUADO NA AREA ADMINISTRATIVA DO PÁTIO DE MONTAGEM, COM MUITA PROJEÇÃO DE PARTICULAS', N'5S E SEGURANÇA', N'10234', N'01 - Imagens/01 - Antes/12110.jpeg', N'AUSENCIA DE PISO NIVELADO E ADEQUADO NA AREA ADMINISTRATIVA DO PÁTIO DE MONTAGEM, COM MUITA PROJEÇÃO DE PARTICULAS', N'01 - Imagens/02 - Depois/12110.jpeg', N'FOI REALIZADA A AQUISIÇÃO DE PISO PORTAFLOOR, COMPOSTO DE POLIMEROS, VISANDO ADEQUAR A AREA ADMINISTRATIVA DO PATIO DE MONTAGEM, COM GANHOS EM SAUDE E SEGURANÇA', NULL, N'AUSENCIA DE PISO NIVELADO E ADEQUADO NA AREA ADMINISTRATIVA DO PÁTIO DE MONTAGEM, COM MUITA PROJEÇÃO DE PARTICULAS', N'5S E SEGURANÇA', 0, NULL, N'A ação demonstrou que melhorias preventivas são mais eficazes e econômicas do que intervenções corretivas posteriores.', '2026-08-12T00:00:00.000', '2026-08-31T23:25:29.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12111, N'478853', N'478853', N'PRATELEIRA CHAPARIA METALICA', 3, N'Others/Outros', N'CHAPAS E CANTONEIRAS METALICAS ARMAZENADAS DE MANEIRA  INADEQUADA, SOBRE O SOLO OU PALLETS', N'ORGANIZAÇÃO E 5S', N'10234', N'01 - Imagens/01 - Antes/12111.jpeg', N'CHAPAS E CANTONEIRAS METALICAS ARMAZENADAS DE MANEIRA  INADEQUADA, SOBRE O SOLO OU PALLETS', N'01 - Imagens/02 - Depois/12111.jpeg', N'ELABORADO SOB MEDIDA E ADQUIRIDA UMA PRATELEIRA PARA CHAPARIA METALICA, VISANDO ORGANIZAR CHAPAS E CANTONEIRAS', NULL, N'CHAPAS E CANTONEIRAS METALICAS ARMAZENADAS DE MANEIRA  INADEQUADA, SOBRE O SOLO OU PALLETS', N'ORGANIZAÇAO E 5S', 0, NULL, N'Instalado câmera melhorando efetivamente a visão lado oposto cabine', '2026-08-05T00:00:00.000', '2026-08-31T23:29:10.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12112, N'478853', N'478853', N'SUPORTE FERRAMENTAS A QUENTE', 3, N'Others/Outros', N'FERRAMENTAS ARMAZRENADAS DE MANEIRA INADEQUADA, DENTRO DE ARMARIOS E COM DIFICULDADE DE ACESSO E MANUSEIO, COM RISCO DE AQUECIMENTO AO SER ENCLAUSURADA', N'ORGANIZAÇÃO E 5S', N'10234', N'01 - Imagens/01 - Antes/12112.jpeg', N'FERRAMENTAS ARMAZRENADAS DE MANEIRA INADEQUADA, DENTRO DE ARMARIOS E COM DIFICULDADE DE ACESSO E MANUSEIO, COM RISCO DE AQUECIMENTO AO SER ENCLAUSURADA', N'01 - Imagens/02 - Depois/12112.jpeg', N'ELABORADO E CONFECCIONADOS SUPORTES PARA ARMAZENAMENTO DAS FERRAMENTAS DE TRABALHO A QUENTE, PROMOVENDO MAIOR SEGURANÇA OPERACIONAL E ORGANIZAÇÃO DO AMBIENTES, OTIMIZANDO OS ESPAÇOS DOS ARMARIOS', NULL, N'FERRAMENTAS ARMAZRENADAS DE MANEIRA INADEQUADA, DENTRO DE ARMARIOS E COM DIFICULDADE DE ACESSO E MANUSEIO, COM RISCO DE AQUECIMENTO AO SER ENCLAUSURADA', N'5S E ORGANIZAÇÃO', 0, NULL, N'Com essa ação, a máquina passou de uma condição anterior, com cabos expostos e risco de falhas elétricas, para uma instalação padronizada e segura, garantindo maior confiabilidade operacional e facilitando futuras manutenções.', '2026-08-07T00:00:00.000', '2026-08-31T23:33:56.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12113, N'478853', N'478853', N'SUPORTE TRANSPORTE MACACO HIDRAULICO', 2, N'Others/Outros', N'AUSENCIA DE PONTO DE TRANSPORTE ADEQUADO PARA TRANSPORTAR MACACO HIDRAULICO PARA AS FRENTES DE ATIVIDADES COM APOIO DA EMPILHADEIRA, DEVIDO PISO NAO SER COMPATIVEL PARA TRANSPORTE MANUAL', N'5S E SEGURANÇA', N'10234', N'01 - Imagens/01 - Antes/12113.jpeg', N'AUSENCIA DE PONTO DE TRANSPORTE ADEQUADO PARA TRANSPORTAR MACACO HIDRAULICO PARA AS FRENTES DE ATIVIDADES COM APOIO DA EMPILHADEIRA, DEVIDO PISO NAO SER COMPATIVEL PARA TRANSPORTE MANUAL', N'01 - Imagens/02 - Depois/12113.jpeg', N'FOI DESENVOLVIDO SUPORTE PARA ARMAZENAR E TRANSPORTAR DE MANEIRA ESTÁVEL E SEGURA O MACACO HIDRAULICO COM APOIO DA EMPILHADEIRA', NULL, N'AUSENCIA DE PONTO DE TRANSPORTE ADEQUADO PARA TRANSPORTAR MACACO HIDRAULICO PARA AS FRENTES DE ATIVIDADES COM APOIO DA EMPILHADEIRA, DEVIDO PISO NAO SER COMPATIVEL PARA TRANSPORTE MANUAL', N'5S E SEGURANÇA', 0, NULL, N'Segurança, com redução do risco de acidentes relacionados á baixa visibilidade e melhoria das condições de trabalho no local.', '2026-08-26T00:00:00.000', '2026-08-31T23:37:52.000', N'478853', NULL, NULL);
INSERT INTO #PVC VALUES (12114, N'478853', N'478853', N'KIT FERRAMENT ABERTURA LATA ELETRODO SOLDA', 2, N'Others/Outros', N'AUSENCIA DE DISPOSITIVO ADEQUADA PARA ABERTURA DE LATAS DE ELETRODOS DE SOLDA, COM RISCO DE CORTE E PRENSAMENTO DE MEMBROS ', N'SEGURANÇA', N'10234', N'01 - Imagens/01 - Antes/12114.jpeg', N'AUSENCIA DE DISPOSITIVO ADEQUADA PARA ABERTURA DE LATAS DE ELETRODOS DE SOLDA, COM RISCO DE CORTE E PRENSAMENTO DE MEMBROS ', N'01 - Imagens/02 - Depois/12114.jpeg', N'FOI DESENVOLVIDO UM SUPORTE PARA TRAVAR A LATA DE ELETRODOS E PROPORCIONAR SUA ABERTURA DE MANEIRA A MINIMIZAR OS RISCOS DE PRENSAMENTOS E CORTES, ALEM DE AGILIZAR DE MANEIRA SEGURA', NULL, N'AUSENCIA DE DISPOSITIVO ADEQUADA PARA ABERTURA DE LATAS DE ELETRODOS DE SOLDA, COM RISCO DE CORTE E PRENSAMENTO DE MEMBROS ', N'SEGURANÇA', 0, NULL, N'Ganho alcançado: Maior segurança 
INSERT INTO #PVC VALUES (12115, N'81042217', N'81038723', N'Implantação de escada de acesso ao TR-07.', 1, N'Others/Outros', N'c0715499@vale.com', N'Garantir acesso seguro ao TR-07 para execução das atividades operacionais. Reduzir o risco de quedas durante o deslocamento dos colaboradores. Melhorar a ergonomia e a acessibilidade ao equipamento. Reduzir o esforço físico necessário para acessar a área. Padronizar o acesso ao local de acordo com boas práticas de segurança.', N'10294', N'01 - Imagens/01 - Antes/12115.jpeg', N'Escada construída em solo natural e madeira. Degraus irregulares e desgastados. 
INSERT INTO #PVC VALUES (12116, N'151878', N'151878', N'PROCEDIMENTO PARA INSPEÇÃO CAIXA DE POLPA', 1, N'Projects/Projetos', N'REALIZAÇÃO DE INSPEÇÃO SEM PROCEDIMENTO E INCOMPLETA DEVIDO FALTA DE ORIENTAÇÕES, CONHECIMENTO E PADRONIZAÇÃO.', N'PADRONIZAR INSPEÇÃO', N'10105', N'01 - Imagens/01 - Antes/12116.jpeg', N'RELATORIOS DE INSPEÇÃO E DEVOLUTIVA SEM PADRONIZAÇÃO E AUSENCIA DE ELEMENTOS CRITICOS.', N'01 - Imagens/02 - Depois/12116.jpeg', N'INSPEÇÕES PADRONIZADAS E COM MAIOR QUALIDADE E ACERTIVIDADE. ', NULL, N'RESOLVIDO O PROBLEMA DE FALTA DE PADRONIZAÇÃO E INSPEÇÃO. ', N'EVOLUÇÃO DE PROCEDIMENTOS', 0, NULL, N'Ganho alcançado: Maior segurança 
INSERT INTO #PVC VALUES (12117, N'460285', N'81013825', N'Intercom Expansion', 1, N'Others/Outros', N'With renovations and reduction to a single bus pickup location, hearing announcements from security regarding travel departures were not easy to hear in the cafeteria.', N'Improve communications to assist with loading outbound passengers in an effective manner', N'10204', N'01 - Imagens/01 - Antes/12117.jpeg', N'The expanded are of the cafeteria was difficult to hear the intercom announcements from security.', N'01 - Imagens/02 - Depois/12117.jpeg', N'New intercom sourced and installed into the expansion of the cafeteria to allow personnel to hear announcements from security.', NULL, N'Yes', N'Improved Communication', 0, NULL, N'Ganho alcançado: Maior segurança 
INSERT INTO #PVC VALUES (12118, N'81037989', N'81047715', N'Otimização de manutenção no display da balança da ponte rolante. ', 1, N'Others/Outros', N'Dificuldade de acesso para manutenção disply balança de ponte rolante, sendo necessário uso de PTA e execução de trabalho em altura.  
INSERT INTO #PVC VALUES (12119, N'81063699', N'81063699', N'Controle e Redução do Consumo de Copos Descartáveis por Meio de Registro de Distribuição', 1, N'No Replication/Sem replicação', N'Atualmente não existe um controle formal da distribuição de copos descartáveis, dificultando a identificação dos setores com maior consumo e gerando desperdícios. A ausência de rastreabilidade impede análises precisas sobre o uso dos materiais e oportunidades de redução de custos.', N'Implementar um sistema de controle para distribuição de copos descartáveis, registrando a retirada por colaborador e área, visando reduzir o consumo em 20% nos próximos 6 meses, evitar desperdícios e aumentar a conscientização sobre o uso responsável dos recursos.', N'10346', N'01 - Imagens/01 - Antes/12119.jpeg', N'O controle da distribuição de copos descartáveis era realizado sem registro formal, impossibilitando a rastreabilidade das retiradas por colaborador, empresa ou área. A ausência de informações sobre quantidade, data e responsável pela retirada dificultava a identificação de desperdícios, o monitoramento do consumo e a tomada de decisões para redução de custos. Como consequência, havia consumo excessivo de copos descartáveis, aumento de despesas com reposição de materiais e dificuldade em promover a conscientização sobre o uso responsável dos recursos.', N'01 - Imagens/02 - Depois/12119.jpeg', N'Implantada planilha para controle da distribuição de copos descartáveis, com registro das retiradas. A ação aumentou a rastreabilidade, reduziu desperdícios e melhorou a gestão do estoque.', NULL, N'EM ANDAMENTO. A planilha de controle foi implantada para registrar as retiradas de copos descartáveis e aumentar a rastreabilidade do consumo. Os resultados serão monitorados ao longo dos próximos meses para avaliar a redução de desperdícios, o controle de estoque e o alcance das metas estabelecidas.', N'O registro das retiradas permite maior controle do consumo, reduz desperdícios e facilita o acompanhamento dos estoques.', 1, 1, N'hole was noticed and remedied', '2026-08-31T00:00:00.000', '2026-09-01T10:56:01.000', N'81063699', NULL, NULL);
INSERT INTO #PVC VALUES (12120, N'92000679', N'81005006', N'CANTINHO DO CAFÉ', 3, N'Others/Outros', N'Antes da melhoria, os copos descartáveis eram armazenados sem local definido, ocupando espaço na bancada e gerando desorganização visual no Cantinho do Café.', N'ORGANIZAÇÃO', N'10234', N'01 - Imagens/01 - Antes/12120.jpeg', N'A ausência de um suporte apropriado dificultava o acesso aos copos e comprometia os padrões de organização do ambiente.', N'01 - Imagens/02 - Depois/12120.jpeg', N'Instalação de dispenser vertical para armazenamento dos copos descartáveis próximo à área do café, garantindo fácil acesso, melhor aproveitamento do espaço e padronização do local.', NULL, N'SIM. O problema foi resolvido. A instalação do dispenser permitiu armazenar os copos de forma organizada e padronizada, eliminando a necessidade de armazenamento improvisado sobre a bancada.', N'Pequenas melhorias de baixo custo podem gerar ganhos significativos na organização, padronização e experiência dos usuários, fortalecendo a cultura 5S no ambiente de trabalho.', 0, NULL, N'A ação atingiu integralmente a meta proposta, transformando uma condição de risco e desorganização em uma solução segura, sustentável, padronizada e de fácil manutenção, gerando ganhos para a segurança, o 5S e o meio ambiente.', '2026-08-26T00:00:00.000', '2026-09-01T11:03:53.000', N'92000679', NULL, NULL);
INSERT INTO #PVC VALUES (12121, N'81037989', N'81057215', N'UPGRADE DE PROTEÇÃO DE DISJUNTOR DE ENTRADA DAS SUBESTAÇÕES. ', 2, N'Others/Outros', N'risco operacional, comprometendo diretamente a execução das manobras de inserção e extração do disjuntor.', N'Reduzir exposição a risco critico na manutençao eletrica ssg', N'10245', N'01 - Imagens/01 - Antes/12121.jpeg', N' O dispositivo instalado no painel elétrico de entrada da subestação encontra-se obsoleto frente aos requisitos atuais de proteção e segurança elétrica, operando com limitações críticas e sem mecanismos eficazes de mitigação de riscos. 
INSERT INTO #PVC VALUES (12122, N'81025146', N'81025146', N'Shotcrete Accelerator Mixer', 1, N'No Replication/Sem replicação', N'Bringing 1000-liter totes of liquid accelerator to site proved in effective. The shelf life of the product was short, making the logistics of balancing life of product over demand challenging. ', N'make Shotcrete Accelerator on site', N'10169', N'01 - Imagens/01 - Antes/12122.jpeg', N'Bringing 1000-liter totes of liquid accelerator to site proved in effective. The shelf life of the product was short, making the logistics of balancing life of product with demand challenging. 
INSERT INTO #PVC VALUES (12123, N'81037142', N'81035997', N'Instalação purgador automático.', 1, N'Others/Outros', N'VA 2316SA-03, equipamento sem dispositivo automático de drenagem de água acumulada no fundo do vaso de pressão, necessitando que o colaborador viesse de tempos em tempos abrir a válvula manualmente para drenar.', N'Automatizar o processo de drenagem para eliminar a atividade manual', N'10031', N'01 - Imagens/01 - Antes/12123.jpeg', N'VA 2316SA-03, equipamento sem dispositivo automático de drenagem de água acumulada no fundo do vaso de pressão, necessitando que o colaborador viesse de tempos em tempos abrir a válvula manualmente para drenar.', N'01 - Imagens/02 - Depois/12123.jpeg', N'VA 2316SA-03 depois, instalado purgador automático na linha de dreno do equipamento tirando a necessidade do colaborador abrir manualmente e evitando o acúmulo de água na forma líquida no fundo do vaso de pressão prevenindo a corrosão e oxidação interna.', NULL, N'A instalação do purgador automático na linha de dreno do VA 2316SA-03 evidenciou a importância da automatização de processos para eliminar falhas humanas, prevenir o acúmulo de condensado, reduzir riscos de corrosão interna e aumentar a confiabilidade.', N'A instalação do purgador automático eliminou a necessidade de drenagem manual pelo colaborador, reduzindo a possibilidade de falhas por esquecimento', 0, NULL, N'Tornar o acionamento de emergência mais acessível, ágil e padronizado, disponibilizando o acionamento como canal complementar ao rádio e telefone. A melhoria busca facilitar a comunicação da ocorrência, reduzir dificuldades relacionadas ao acesso aos meios convencionais e garantir o envio das informações necessárias para uma mobilização mais assertiva da equipe de emergência.', '2026-08-31T00:00:00.000', '2026-09-01T14:35:39.000', N'81037142', NULL, NULL);
INSERT INTO #PVC VALUES (12124, N'81030117', N'81005184', N'MELHORIA PZ22', 1, N'Others/Outros', N'Antes: Ponto cego lado oposto cabine, operador tinha visão limitada com retrovisor.', N'melhorar a visão do lado oposto cabine', N'10324', N'01 - Imagens/01 - Antes/12124.jpeg', N'Ponto cego lado oposto cabine, operador tinha visão limitada com retrovisor.', N'01 - Imagens/02 - Depois/12124.jpeg', N'Instalado câmera melhorando efetivamente a visão lado oposto cabine', NULL, N'Ponto cego lado oposto cabine, operador tinha visão limitada com retrovisor.', N'Garantido maior segurança', 0, NULL, N'Ficou dentro do esperado e com replicação, iremos indicar para outros Laboratórios.', '2026-08-01T00:00:00.000', '2026-09-01T16:40:23.000', N'81030117', NULL, NULL);
INSERT INTO #PVC VALUES (12125, N'81030117', N'81057321', N'MELHORIA NA PZ37', 1, N'Others/Outros', N'Foi realizada na perfuratriz PZ37 , uma melhoria no sistema de cabos dos motores de partida.
INSERT INTO #PVC VALUES (12126, N'123307', N'81049793', N'Flotação iluminada', 2, N'Others/Outros', N'Área da flotação cleanner sem iluminação, tendo risco de acidentes, quedas , tropeços e batidas.', N'Melhorar a  iluminada e reduzir o risco de acidentes na área', N'10054', N'01 - Imagens/01 - Antes/12126.jpeg', N'Área da flotação Cleaners encontra-se sem iluminação adequada, comprometendo a visibilidade durante a circulação e execução das atividades no local. A baixa visibilidade aumenta o potencial de ocorrência de quedas no mesmo nível, tropeços, escorregões, batidas contra estruturas/equipamentos e outros acidentes, principalmente durante atividades noturnas ou em condições de baixa luminosidade.', N'01 - Imagens/02 - Depois/12126.jpeg', N'Foram instalados refletores na área, proporcionando melhor iluminação e visibilidade local.', NULL, N'Sim', N'Pequenas melhorias no ambiente podem eliminar riscos de quedas, tropeços e batidas.', 0, NULL, N'melhoria de segurança', '2026-08-30T00:00:00.000', '2026-09-01T21:00:40.000', N'123307', NULL, NULL);
